// Hyperrealistic Field-Guide Plate: A Dozen House Keys as Taxonomic Species
// Rendered with p5.js v2 + p5.brush in WEBGL

const PAPER_BG = "#b3bfb1";
const KEY_ANGLE = 32; // Unified taxonomic orientation (degrees)
const SHADOW_DX = 11; // Global lower-right shadow offset X
const SHADOW_DY = 15; // Global lower-right shadow offset Y

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(8812);

  // Register custom gouache and fine coloured-pencil brushes before scaling
  brush.add("gouache", {
    type: "marker",
    weight: 1.6,
    scatter: 0.04,
    opacity: 215,
    spacing: 0.25,
    pressure: [0.95, 1.0, 0.95],
    rotate: "natural",
    markerTip: false,
    noise: 0.12
  });

  brush.add("glaze", {
    type: "marker",
    weight: 2.4,
    scatter: 0.1,
    opacity: 75,
    spacing: 0.3,
    pressure: [0.7, 1.0, 0.7],
    rotate: "natural",
    markerTip: false,
    noise: 0.2
  });

  brush.add("micro_pencil", {
    type: "default",
    weight: 0.24,
    scatter: 0.06,
    sharpness: 0.88,
    grain: 14,
    opacity: 210,
    spacing: 0.45,
    pressure: [0.6, 1.15, 0.5],
    rotate: "natural",
    noise: 0.25
  });

  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Muted Grey-Green Tinted Specimen Paper & Archival Framing
  drawTintedPaper();
  drawPlateBordersAndHeader();

  // 2. Define the 12 Key Species in 4 Tidy Staggered Rows
  const keys = getSpeciesData();

  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    // Faint taxonomic numeral beside each key
    drawFaintNumeral(k.id, k.cx - 128, k.cy - 44);

    push();
    translate(k.cx, k.cy);
    rotate(KEY_ANGLE);
    if (k.kind === "pin") {
      renderPinTumblerKey(k);
    } else {
      renderSkeletonOrLeverKey(k);
    }
    pop();
  }

  noLoop();
}

// ============================================================================
// PAPER & ARCHIVAL FIELD-GUIDE FRAMING
// ============================================================================

function drawTintedPaper() {
  background(PAPER_BG);

  // Subtle watercolor mottling across the grey-green archival paper
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);

  const tones = [
    { c: "#a7b5a5", a: 28 },
    { c: "#c0cbbd", a: 26 },
    { c: "#9ca99a", a: 20 }
  ];
  for (let t of tones) {
    brush.fill(t.c, t.a);
    for (let i = 0; i < 4; i++) {
      let rx = random(140, 1060);
      let ry = random(140, 1060);
      let rw = random(320, 620);
      let rh = random(280, 540);
      brush.rect(rx, ry, rw, rh, "center");
    }
  }
  brush.noFill();

  // Fine woven paper fibers & subtle archival grain
  brush.noField();
  for (let i = 0; i < 650; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let len = random(6, 26);
    let ang = random(360);
    let col = i % 3 === 0 ? "#cbd4c8" : (i % 3 === 1 ? "#98a696" : "#8b9989");
    brush.set("2H", col, random(0.1, 0.2));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Subtle stipple Foxing / mineral flecks in the paper
  brush.set("spray", "#8e9c8c", 0.35);
  for (let i = 0; i < 18; i++) {
    let x = random(60, 1140);
    let y = random(60, 1140);
    brush.line(x, y, x + random(-35, 35), y + random(-35, 35));
  }
}

function drawPlateBordersAndHeader() {
  // Outer and inner ruled taxonomic border
  brush.set("rotring", "#6e7d6f", 0.28);
  drawRectOutline(46, 46, 1108, 1108);
  brush.set("rotring", "#819082", 0.16);
  drawRectOutline(54, 54, 1092, 1092);

  // Corner ticks
  const corners = [[46, 46], [1154, 46], [46, 1154], [1154, 1154]];
  brush.set("2H", "#637264", 0.22);
  for (let [cx, cy] of corners) {
    brush.line(cx - 8, cy, cx + 8, cy);
    brush.line(cx, cy - 8, cx, cy + 8);
  }

  // Faint Plate Title at Top: "TAB. XII — CLAVES DOMESTICAE"
  drawMicroText("TAB. XII", 568, 69, 1.35, "#5e6d60", 0.22);

  // Faint Scale Bar at Bottom Right (50 mm)
  let sx = 980, sy = 1130;
  brush.set("2H", "#637264", 0.22);
  brush.line(sx, sy, sx + 120, sy);
  for (let i = 0; i <= 5; i++) {
    let tx = sx + i * 24;
    let th = (i === 0 || i === 5) ? 6 : 3.5;
    brush.line(tx, sy - th, tx, sy + 1);
  }
  drawMicroText("50 MM", sx + 44, sy - 11, 1.05, "#637264", 0.18);
}

function drawRectOutline(x, y, w, h) {
  brush.line(x, y, x + w, y);
  brush.line(x + w, y, x + w, y + h);
  brush.line(x + w, y + h, x, y + h);
  brush.line(x, y + h, x, y);
}

