function drawFaintNumeral(num, x, y) {
  let label = num + ".";
  // Delicate graphite numeral with subtle double-pass hand feel
  drawMicroText(label, x, y, 1.55, "#617062", 0.24);
  drawMicroText(label, x + 0.4, y + 0.4, 1.55, "#7b8a7c", 0.15);
}

function drawMicroText(str, x, y, scale, col, weight) {
  brush.set("2H", col, weight);
  let cursorX = x;
  let cw = 6.2 * scale;
  let ch = 9.5 * scale;
  for (let i = 0; i < str.length; i++) {
    let c = str[i].toUpperCase();
    if (c === " ") {
      cursorX += cw * 0.7;
      continue;
    }
    let strokes = GLYPHS[c];
    if (strokes) {
      for (let s of strokes) {
        for (let j = 0; j < s.length - 1; j++) {
          let x1 = cursorX + s[j][0] * cw;
          let y1 = y + s[j][1] * ch;
          let x2 = cursorX + s[j + 1][0] * cw;
          let y2 = y + s[j + 1][1] * ch;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    cursorX += (c === "." ? cw * 0.55 : cw * 0.92);
  }
}

// Stamped lettering on metal (dark indented shadow + bright bottom-right rim glint)
function drawStampedText(str, x, y, scale, shadowCol, highlightCol) {
  drawMicroText(str, x + 0.6, y + 0.7, scale, highlightCol, 0.22);
  drawMicroText(str, x, y, scale, shadowCol, 0.26);
}

