// ============================================================================
// GEOMETRY & SHADOW HELPERS
// ============================================================================

function getLocalShadowOffset() {
  // Convert global (SHADOW_DX, SHADOW_DY) into rotated local coordinates
  return {
    x: SHADOW_DX * cos(KEY_ANGLE) + SHADOW_DY * sin(KEY_ANGLE),
    y: -SHADOW_DX * sin(KEY_ANGLE) + SHADOW_DY * cos(KEY_ANGLE)
  };
}

function drawPolygonWash(pts, col, alpha) {
  brush.noStroke();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawSoftDropShadow(polyList, holeList) {
  const s = getLocalShadowOffset();

  // Multi-pass soft shadow to lower-right
  const layers = [
    { scale: 1.15, col: "#7f8f7e", a: 55 },
    { scale: 0.92, col: "#667565", a: 85 },
    { scale: 0.65, col: "#4c594b", a: 115 }
  ];

  for (let l of layers) {
    let ox = s.x * l.scale;
    let oy = s.y * l.scale;
    for (let pts of polyList) {
      let shifted = pts.map(p => [p[0] + ox, p[1] + oy]);
      drawPolygonWash(shifted, l.col, l.a);
    }
  }

  // Restore sunlit paper inside shifted hole cutouts so keyholes cast true ring shadows
  if (holeList && holeList.length > 0) {
    for (let hPts of holeList) {
      let shiftedHole = hPts.map(p => [p[0] + s.x * 0.9, p[1] + s.y * 0.9]);
      drawPolygonWash(shiftedHole, PAPER_BG, 235);
    }
  }
}

function getBowVertices(shape, cx, cy, rx, ry) {
  let pts = [];
  if (shape === "hex") {
    pts = [
      [cx - rx, cy - ry * 0.42],
      [cx - rx * 0.52, cy - ry],
      [cx + rx * 0.45, cy - ry],
      [cx + rx * 0.72, cy - ry * 0.58],
      [cx + rx, cy - ry * 0.48],
      [cx + rx, cy + ry * 0.48],
      [cx + rx * 0.72, cy + ry * 0.58],
      [cx + rx * 0.45, cy + ry],
      [cx - rx * 0.52, cy + ry],
      [cx - rx, cy + ry * 0.42]
    ];
  } else if (shape === "plastic_teal") {
    pts = [
      [cx - rx, cy - ry * 0.62],
      [cx - rx * 0.78, cy - ry * 0.92],
      [cx + rx * 0.62, cy - ry],
      [cx + rx, cy - ry * 0.68],
      [cx + rx, cy + ry * 0.68],
      [cx + rx * 0.62, cy + ry],
      [cx - rx * 0.78, cy + ry * 0.92],
      [cx - rx, cy + ry * 0.62]
    ];
  } else if (shape === "kwik") {
    pts = [
      [cx - rx, cy - ry * 0.38],
      [cx - rx * 0.65, cy - ry * 0.88],
      [cx - rx * 0.05, cy - ry],
      [cx + rx * 0.55, cy - ry * 0.82],
      [cx + rx * 0.78, cy - ry * 0.42],
      [cx + rx, cy - ry * 0.42],
      [cx + rx, cy + ry * 0.42],
      [cx + rx * 0.78, cy + ry * 0.42],
      [cx + rx * 0.55, cy + ry * 0.82],
      [cx - rx * 0.05, cy + ry],
      [cx - rx * 0.65, cy + ry * 0.88],
      [cx - rx, cy + ry * 0.38]
    ];
  } else if (shape === "square_dimple") {
    pts = [
      [cx - rx, cy - ry * 0.78],
      [cx - rx * 0.78, cy - ry],
      [cx + rx * 0.75, cy - ry],
      [cx + rx, cy - ry * 0.72],
      [cx + rx, cy + ry * 0.72],
      [cx + rx * 0.75, cy + ry],
      [cx - rx * 0.78, cy + ry],
      [cx - rx, cy + ry * 0.78]
    ];
  } else if (shape === "winged_brass") {
    pts = [
      [cx - rx, cy - ry * 0.3],
      [cx - rx * 0.65, cy - ry * 0.95],
      [cx + rx * 0.25, cy - ry],
      [cx + rx * 0.65, cy - ry * 0.55],
      [cx + rx, cy - ry * 0.45],
      [cx + rx, cy + ry * 0.45],
      [cx + rx * 0.65, cy + ry * 0.55],
      [cx + rx * 0.25, cy + ry],
      [cx - rx * 0.65, cy + ry * 0.95],
      [cx - rx, cy + ry * 0.3]
    ];
  } else if (shape === "oct_compact") {
    pts = [
      [cx - rx, cy - ry * 0.45],
      [cx - rx * 0.48, cy - ry],
      [cx + rx * 0.48, cy - ry],
      [cx + rx, cy - ry * 0.45],
      [cx + rx, cy + ry * 0.45],
      [cx + rx * 0.48, cy + ry],
      [cx - rx * 0.48, cy + ry],
      [cx - rx, cy + ry * 0.45]
    ];
  } else {
    // round_embossed or red_capped
    let steps = 24;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
    }
  }
  return pts;
}

function getHoleVertices(shape, hx, hy, r) {
  let pts = [];
  if (shape === "slot") {
    let w = r * 0.62, h = r * 1.65;
    pts = [
      [hx - w, hy - h * 0.65],
      [hx - w * 0.35, hy - h],
      [hx + w * 0.35, hy - h],
      [hx + w, hy - h * 0.65],
      [hx + w, hy + h * 0.65],
      [hx + w * 0.35, hy + h],
      [hx - w * 0.35, hy + h],
      [hx - w, hy + h * 0.65]
    ];
  } else if (shape === "arch") {
    pts = [
      [hx - r * 0.75, hy - r * 0.5],
      [hx, hy - r * 1.25],
      [hx + r * 0.85, hy - r * 0.85],
      [hx + r * 0.85, hy + r * 0.85],
      [hx, hy + r * 1.25],
      [hx - r * 0.75, hy + r * 0.5]
    ];
  } else {
    for (let i = 0; i < 18; i++) {
      let a = (i / 18) * 360;
      pts.push([hx + cos(a) * r, hy + sin(a) * r]);
    }
  }
  return pts;
}

function buildBladeData(xStart, bladeLen, yTop, yBot, bitting) {
  const xEnd = xStart + bladeLen;
  const topSegs = [];

  // Shoulder stop projection at top and bottom
  const shoulderX = xStart + 11;
  topSegs.push([xStart, yTop]);
  topSegs.push([xStart + 3, yTop - 6.5]);
  topSegs.push([shoulderX - 2, yTop - 6.5]);
  topSegs.push([shoulderX, yTop]);

  // Bitting cuts (flat pin root plateaus + 48-degree ramps)
  const cutZoneStart = shoulderX + 6;
  const cutZoneEnd = xEnd - 22;
  const n = bitting.length;
  const stepX = (cutZoneEnd - cutZoneStart) / n;

  let prevX = shoulderX;
  let prevY = yTop;

  for (let i = 0; i < n; i++) {
    let cx = cutZoneStart + (i + 0.5) * stepX;
    let depth = bitting[i]; // 1..6
    let cy = yTop + depth * 2.35;
    let flatHalf = 3.2;

    let rampStartX = cx - flatHalf - abs(cy - prevY) * 0.85;
    if (rampStartX > prevX + 1.5) {
      // Peak plateau between distant cuts
      topSegs.push([rampStartX, prevY]);
    }
    topSegs.push([cx - flatHalf, cy]);
    topSegs.push([cx + flatHalf, cy]);
    prevX = cx + flatHalf;
    prevY = cy;
  }

  // Exit from last cut to tip nose
  let tipShoulderX = xEnd - 15;
  topSegs.push([tipShoulderX, yTop + 1.5]);
  let tipApexX = xEnd;
  let tipApexY = (yTop + yBot) * 0.12;
  topSegs.push([tipApexX, tipApexY]);

  // Full polygon including bottom chamfer, bottom shoulder stop, and back edge
  let fullPoly = [...topSegs];
  fullPoly.push([xEnd - 13, yBot]);
  fullPoly.push([shoulderX, yBot]);
  fullPoly.push([shoulderX - 1.5, yBot + 4.5]);
  fullPoly.push([xStart + 3, yBot + 4.5]);
  fullPoly.push([xStart, yBot]);

  // Helper to query upper bitting height at any x
  function getTopYAt(x) {
    for (let i = 0; i < topSegs.length - 1; i++) {
      let [x1, y1] = topSegs[i];
      let [x2, y2] = topSegs[i + 1];
      if (x >= x1 && x <= x2) {
        if (abs(x2 - x1) < 0.001) return max(y1, y2);
        let t = (x - x1) / (x2 - x1);
        return lerp(y1, y2, t);
      }
    }
    return yTop;
  }

  return { fullPoly, topSegs, xStart, xEnd, shoulderX, yTop, yBot, tipApexY, getTopYAt };
}

// ============================================================================
// RENDERER 1: PIN-TUMBLER KEYS (GOUACHE + COLOURED PENCIL)
// ============================================================================

function renderPinTumblerKey(k) {
  const bowCx = -74;
  const bowCy = 0;
  const bladeStartX = bowCx + k.bowRx - 5;

  const bowPts = getBowVertices(k.bowShape, bowCx, bowCy, k.bowRx, k.bowRy);
  const holePts = getHoleVertices(k.holeShape, k.holeX, 0, k.holeR);
  const blade = buildBladeData(bladeStartX, k.bladeLen, k.bladeTop, k.bladeBot, k.bitting);

  // 1. Cast small soft shadow to lower right
  drawSoftDropShadow([bowPts, blade.fullPoly], [holePts]);

  // 2. Render Blade (underneath if plastic-headed, or seamlessly joined)
  renderPinBlade(k, blade);

  // 3. Render Bow (Metal, Faded Teal Plastic, or Rubber-Capped)
  if (k.bowShape === "plastic_teal") {
    renderTealPlasticBow(k, bowPts, holePts, bowCx, bowCy);
  } else {
    renderMetallicBow(k, bowPts, holePts, bowCx, bowCy);
    if (k.bowShape === "red_capped") {
      renderVermilionCap(k, bowPts, bowCx, bowCy);
    }
  }

  // 4. Cut out the Keyring Hole with 3D inner-rim thickness & cast shadow on paper
  renderKeyholeCutout(holePts, k.bowShape === "plastic_teal" ? k.headPal : k.pal);
}

function renderPinBlade(k, blade) {
  const pal = k.pal;
  const { fullPoly, topSegs, xStart, xEnd, shoulderX, yTop, yBot, getTopYAt } = blade;

  // 3D Bottom Thickness Rim (dark lower edge extruded 3.6px down)
  let rimPoly = fullPoly.map(p => [p[0] + 0.8, p[1] + 3.4]);
  drawPolygonWash(rimPoly, pal.deep, 240);

  // Main Opaque Gouache Blade Fill
  drawPolygonWash(fullPoly, pal.base, 250);

  // Longitudinal Gouache Shading Bands across the Blade
  brush.set("gouache", pal.mid, 1.4);
  for (let y = yTop + 2; y <= yBot - 2; y += 2.2) {
    let col = y < 0 ? pal.mid : (y > 6 ? pal.bounce : pal.base);
    brush.set("gouache", col, 1.15);
    let xs = shoulderX + 2;
    let xe = xEnd - 10;
    // Clip line segments against top bitting profile
    drawClippedHorizontalLine(xs, xe, y, getTopYAt, 1.5);
  }

  // Brassing wear on plated blade (Key 11)
  if (k.brassing) {
    brush.set("gouache", "#d99316", 1.5);
    drawClippedHorizontalLine(shoulderX + 6, xEnd - 22, 1.2, getTopYAt, 2.5);
    brush.set("micro_pencil", "#f7bd36", 0.9);
    drawClippedHorizontalLine(shoulderX + 10, xEnd - 26, 0.2, getTopYAt, 2.5);
  }

  // Machined 3D Bitting Bevel Facets along every tooth slope
  const bevelDepth = 3.6;
  for (let i = 0; i < topSegs.length - 1; i++) {
    let [x1, y1] = topSegs[i];
    let [x2, y2] = topSegs[i + 1];
    let dy = y2 - y1;
    let facet = [
      [x1, y1],
      [x2, y2],
      [x2, y2 + bevelDepth],
      [x1, y1 + bevelDepth]
    ];

    if (k.anodized) {
      // Raw silver aluminum exposed on milled bitting teeth!
      let silverCol = dy < -0.5 ? "#ffffff" : (dy > 0.5 ? "#69829c" : "#b8d0e8");
      drawPolygonWash(facet, silverCol, 245);
    } else {
      let fCol = dy < -0.5 ? pal.hi : (dy > 0.5 ? pal.dark : pal.rim);
      drawPolygonWash(facet, fCol, 235);
    }

    // Crisp coloured-pencil ridge along base of the bitting bevel
    brush.set("micro_pencil", dy < 0 ? pal.hi : pal.deep, 0.85);
    brush.line(x1, y1 + bevelDepth, x2, y2 + bevelDepth);

    // Patina/verdigris settled in the deep valley corners of bitting cuts
    if (abs(dy) < 0.2 && y1 > yTop + 4) {
      brush.set("micro_pencil", pal.patina, 1.1);
      brush.line(x1 + 0.5, y1 + 0.8, x2 - 0.5, y2 + 0.8);
    }
  }

  // Milled Keyway Grooves (Fluting) with recessed shadow, verdigris patina & bright bottom lip
  for (let g of k.grooves) {
    let gy = g.y;
    let gw = g.w;
    let gxEnd = xEnd - (gy > 0 ? 5 : 12);

    // Dark recessed groove core
    brush.set("gouache", pal.deep, gw * 0.55);
    drawClippedHorizontalLine(xStart + 4, gxEnd, gy, getTopYAt, 1.8);

    // Upper shadow edge of milling
    brush.set("rotring", pal.deep, 0.35);
    drawClippedHorizontalLine(xStart + 2, gxEnd + 1, gy - gw * 0.45, getTopYAt, 1.5);

    // Patina / Verdigris in the groove
    if (g.patina) {
      brush.set("micro_pencil", pal.patina, 1.15);
      drawClippedHorizontalLine(xStart + 6, gxEnd - 8, gy + 0.2, getTopYAt, 2.0);
      // Bright malachite flecks inside the groove
      brush.set("micro_pencil", pal.patinaHi, 0.75);
      for (let fx = xStart + 12; fx < gxEnd - 15; fx += random(9, 18)) {
        if (gy > getTopYAt(fx) + 2) {
          brush.line(fx, gy - 0.2, fx + random(3, 6), gy + 0.3);
        }
      }
    }

    // Razor-sharp specular highlight on the bottom lip of the groove
    brush.set("micro_pencil", pal.hi, 0.95);
    drawClippedHorizontalLine(xStart + 4, gxEnd, gy + gw * 0.48, getTopYAt, 1.8);
  }

  // Precision Drilled Dimples for High-Security Key 7
  if (k.dimples) {
    for (let i = 0; i < k.dimples.length; i++) {
      let dx = k.dimples[i];
      let dy = (i % 2 === 0) ? -0.5 : 2.2;
      let dr = (i % 3 === 0) ? 3.2 : 2.4;
      // Conical drilled crater: upper-left dark shadow, lower-right bright crescent
      brush.noStroke();
      brush.wash(pal.deep, 235);
      brush.circle(dx, dy, dr);
      brush.wash(pal.hi, 220);
      brush.circle(dx + dr * 0.28, dy + dr * 0.28, dr * 0.55);
      brush.noWash();
      brush.set("rotring", pal.deep, 0.25);
      brush.circle(dx, dy, dr);
    }
  }

  // Bottom blade bevel & crisp outline
  brush.set("gouache", pal.dark, 0.9);
  brush.line(shoulderX, yBot, xEnd - 13, yBot);
  brush.line(xEnd - 13, yBot, xEnd, blade.tipApexY);

  // Specular glint on the tip nose & shoulder stop
  brush.set("micro_pencil", pal.hi, 1.1);
  brush.line(xStart + 3, yTop - 6.2, shoulderX - 2, yTop - 6.2);
  brush.line(xEnd - 14, yTop + 1.8, xEnd - 1, blade.tipApexY);

  // Pocket scratches across the blade
  drawPocketScratches(shoulderX + 6, xEnd - 20, -2, yBot - 2, 12, pal.scratch, pal.dark);
}

function drawClippedHorizontalLine(x1, x2, y, getTopYAt, margin) {
  let step = 3;
  let inSeg = false;
  let segStart = x1;
  for (let x = x1; x <= x2; x += step) {
    let limitY = getTopYAt(x) + margin;
    if (y >= limitY) {
      if (!inSeg) {
        segStart = x;
        inSeg = true;
      }
    } else {
      if (inSeg) {
        if (x - segStart > 2) brush.line(segStart, y, x - step, y);
        inSeg = false;
      }
    }
  }
  if (inSeg && x2 - segStart > 2) {
    brush.line(segStart, y, x2, y);
  }
}

function renderMetallicBow(k, bowPts, holePts, cx, cy) {
  const pal = k.pal;

  // 1. 3D Bottom-Right Thickness Rim of Bow
  let rimPts = bowPts.map(p => [p[0] + 1.0, p[1] + 3.6]);
  drawPolygonWash(rimPts, pal.deep, 245);

  // 2. Main Opaque Gouache Bow Body
  drawPolygonWash(bowPts, pal.base, 252);

  // 3. Recessed Inner Coined Medallion / Frame on the Bow
  let innerPts = bowPts.map(p => [
    lerp(cx, p[0], 0.76),
    lerp(cy, p[1], 0.76)
  ]);
  drawPolygonWash(innerPts, pal.dark, 95);

  // Directional Metallic Sheen across the Bow Face
  brush.hatchStyle("gouache", pal.mid, 1.1);
  brush.hatch(3.5, -25, { rand: 0.04 });
  brush.noStroke();
  brush.beginShape(0);
  for (let p of innerPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noHatch();

  // Warm Brassing Patch on Worn Plated Key (Key 11)
  if (k.brassing) {
    brush.noStroke();
    brush.wash("#d99414", 210);
    brush.circle(cx + 8, cy - 2, 21, 0.15);
    brush.wash("#f5b82e", 170);
    brush.circle(cx + 6, cy - 4, 13, 0.15);
    brush.noWash();
  }

  // Vivid Red Enamel Security Token Inset (Key 7)
  if (k.redToken) {
    let tx = cx - 12, ty = cy - 21, tr = 6.2;
    brush.noStroke();
    brush.wash("#4a0606", 245);
    brush.circle(tx, ty, tr + 1.0);
    brush.wash("#e32227", 250);
    brush.circle(tx, ty, tr);
    brush.wash("#ff857a", 220);
    brush.circle(tx - 1.8, ty - 1.8, tr * 0.42);
    brush.noWash();
    brush.set("rotring", "#2b0202", 0.28);
    brush.circle(tx, ty, tr + 0.6);
  }

  // 4. Coined Inner Rim Bevel (dark top-left shadow, bright bottom-right catchlight)
  for (let i = 0; i < innerPts.length; i++) {
    let p1 = innerPts[i];
    let p2 = innerPts[(i + 1) % innerPts.length];
    let nx = -(p2[1] - p1[1]);
    let ny = (p2[0] - p1[0]);
    let lightDot = nx * (-0.7) + ny * (-0.7);

    // Patina tucked into the coined recess crease
    brush.set("micro_pencil", pal.patina, 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Specular or shadow rim
    let edgeCol = lightDot > 0 ? pal.deep : pal.hi;
    brush.set("micro_pencil", edgeCol, 0.9);
    brush.line(p1[0] + 0.7, p1[1] + 0.7, p2[0] + 0.7, p2[1] + 0.7);
  }

  // 5. Outer Chamfered Rim Highlights & Shadows
  for (let i = 0; i < bowPts.length; i++) {
    let p1 = bowPts[i];
    let p2 = bowPts[(i + 1) % bowPts.length];
    let dy = p2[1] - p1[1];
    let dx = p2[0] - p1[0];
    // Top-left edges catch vivid specular highlight
    let isLit = (p1[1] + p2[1]) * 0.5 < 2 && dx > -5;
    if (k.anodized && isLit) {
      // Scratched raw silver edge wear on cobalt anodized bow
      brush.set("gouache", "#e6f2ff", 0.85);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else {
      brush.set("gouache", isLit ? pal.hi : pal.dark, 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
    brush.set("rotring", pal.deep, 0.25);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 6. Stamped Maker's Lettering & Serial Numbers
  if (k.stamp) {
    drawStampedText(k.stamp, cx + 2, cy - 11, 1.05, pal.deep, pal.hi);
  }
  if (k.serial) {
    drawStampedText(k.serial, cx + 5, cy + 4, 0.85, pal.deep, pal.rim);
  }

  // 7. Pocket Scratches & Surface Micro-Texture on Bow
  drawPocketScratches(cx - k.bowRx * 0.55, cx + k.bowRx * 0.55, -k.bowRy * 0.55, k.bowRy * 0.55, 16, pal.scratch, pal.dark);
}

function renderTealPlasticBow(k, bowPts, holePts, cx, cy) {
  const hp = k.headPal;

  // 1. Thick Molded Vinyl 3D Rim Shadow
  let rimPts = bowPts.map(p => [p[0] + 1.4, p[1] + 4.4]);
  drawPolygonWash(rimPts, hp.deep, 250);

  // 2. Vivid Faded Teal Gouache Base
  drawPolygonWash(bowPts, hp.base, 255);

  // 3. Recessed Thumb Well in Center of Plastic Head
  let wellPts = [
    [cx - 14, cy - 24],
    [cx + 24, cy - 26],
    [cx + 28, cy - 16],
    [cx + 28, cy + 16],
    [cx + 24, cy + 26],
    [cx - 14, cy + 24]
  ];
  drawPolygonWash(wellPts, hp.dark, 185);

  // 4. Molded Raised Grip Ridge & Sun-Faded Chalky Teal Highlights
  brush.set("gouache", hp.mid, 1.8);
  brush.line(cx - 32, cy - 25, cx + 28, cy - 30);
  brush.line(cx + 33, cy - 24, cx + 33, cy + 24);

  // Raised tactile grip bar near neck
  brush.set("gouache", hp.deep, 1.4);
  brush.line(cx + 22, cy - 17, cx + 22, cy + 17);
  brush.set("gouache", hp.hi, 1.2);
  brush.line(cx + 20.5, cy - 17, cx + 20.5, cy + 17);

  // Chalky worn seafoam edge highlights along top-left perimeter
  for (let i = 0; i < 4; i++) {
    let p1 = bowPts[i];
    let p2 = bowPts[i + 1];
    brush.set("gouache", hp.hi, 1.15);
    brush.line(p1[0], p1[1] + 1, p2[0], p2[1] + 1);
    brush.set("micro_pencil", hp.worn, 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Molded debossed text inside the plastic thumb well
  drawStampedText("YALE", cx - 4, cy - 4, 0.95, hp.deep, hp.rim);

  // Fine scuff marks on the matte vinyl surface
  drawPocketScratches(cx - 20, cx + 25, -22, 22, 14, hp.worn, hp.deep);
}

function renderVermilionCap(k, bowPts, cx, cy) {
  const cp = k.capPal;
  // Stretch-on rubber cap covering the left/upper 65% of the round bow
  let capPts = [];
  for (let p of bowPts) {
    if (p[0] < cx + 16) {
      capPts.push([p[0] * 1.03, p[1] * 1.05]);
    }
  }
  capPts.push([cx + 15, -k.bowRy * 0.88]);
  capPts.push([cx + 10, 0]);
  capPts.push([cx + 15, k.bowRy * 0.88]);

  // Cast shadow of the rubber cap lip onto the nickel bow
  let capShadow = capPts.map(p => [p[0] + 2.2, p[1] + 2.5]);
  drawPolygonWash(capShadow, "#16222e", 180);

  // Vivid Vermilion Gouache Cap Body
  drawPolygonWash(capPts, cp.base, 255);

  // Molded raised rim along the rubber cap opening
  brush.set("gouache", cp.mid, 1.8);
  brush.line(cx + 13, -k.bowRy * 0.82, cx + 8, 0);
  brush.line(cx + 8, 0, cx + 13, k.bowRy * 0.82);

  brush.set("gouache", cp.hi, 1.1);
  brush.arc(cx, cy, k.bowRx * 0.92, 165, 295);

  brush.set("micro_pencil", "#ffc2b8", 0.9);
  brush.arc(cx, cy, k.bowRx * 0.95, 185, 275);
}

function renderKeyholeCutout(holePts, pal) {
  const s = getLocalShadowOffset();

  // 1. Dark inner wall thickness of the hole (visible along upper-left interior)
  drawPolygonWash(holePts, pal.deep, 250);

  // 2. Sunlit paper visible inside the hole, shifted by wall thickness
  let innerPaper = holePts.map(p => [p[0] + 1.8, p[1] + 2.2]);
  drawPolygonWash(innerPaper, PAPER_BG, 255);

  // 3. Soft shadow cast by the keyhole rim onto the paper inside the hole
  let shadowBand = holePts.map(p => [p[0] + s.x * 0.45, p[1] + s.y * 0.45]);
  brush.set("gouache", "#6b7a6a", 1.6);
  for (let i = 0; i < holePts.length; i++) {
    let p1 = holePts[i];
    let p2 = holePts[(i + 1) % holePts.length];
    if (p1[0] + p1[1] < -85) {
      brush.line(p1[0] + 2.2, p1[1] + 2.8, p2[0] + 2.2, p2[1] + 2.8);
    }
  }

  // 4. Crisp bottom-right inner bevel glint where light hits the hole edge
  for (let i = 0; i < holePts.length; i++) {
    let p1 = holePts[i];
    let p2 = holePts[(i + 1) % holePts.length];
    let isBottomRight = (p1[1] > -2);
    brush.set("micro_pencil", isBottomRight ? pal.hi : pal.deep, 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// RENDERER 2: SKELETON & LEVER KEYS (IRON, BRONZE, RUST & VERDIGRIS)
// ============================================================================

function renderSkeletonOrLeverKey(k) {
  const pal = k.pal;
  const bowCx = -82;
  const bowCy = 0;
  const shankStartX = -42;
  const shankEndX = shankStartX + k.shankLen;
  const r = k.shankR;

  // Build Bow Outer & Cutout Polygons
  const { bowOuter, bowHoles } = getSkeletonBowGeometry(k, bowCx, bowCy);

  // Build Shank Polygon
  const shankPoly = [
    [shankStartX, -r],
    [shankEndX - 4, -r * 0.92],
    [shankEndX, 0],
    [shankEndX - 4, r * 0.92],
    [shankStartX, r]
  ];

  // Build Bit (Warded Flag) Polygon
  const bitPolys = getBitPolygons(k, r);

  // 1. Cast unified soft shadow to lower right
  drawSoftDropShadow([bowOuter, shankPoly, ...bitPolys], bowHoles);

  // 2. Render Warded Bit(s) at the Tip
  renderSkeletonBit(k, bitPolys, r);

  // 3. Render Cylindrical Barrel Shank (or Flat Steel Shank for Lever Key)
  renderSkeletonShank(k, shankStartX, shankEndX, r);

  // 4. Render Turned Decorative Collar / Boss Rings
  renderTurnedCollar(k, shankStartX + 4, r);

  // 5. Render Pierced Skeleton Bow
  renderSkeletonBow(k, bowOuter, bowHoles, bowCx, bowCy);
}

function getSkeletonBowGeometry(k, cx, cy) {
  let bowOuter = [];
  let bowHoles = [];

  if (k.kind === "lever") {
    // Flat paddle bow with capsule slot
    bowOuter = getBowVertices("hex", cx, cy, 40, 36);
    bowHoles.push(getHoleVertices("slot", cx - 10, cy, 11));
  } else if (k.bowType === "trefoil") {
    // Ornate clover/trefoil skeleton bow
    for (let i = 0; i < 32; i++) {
      let a = (i / 32) * 360;
      let lobe = 1 + 0.18 * cos(3 * a);
      bowOuter.push([cx + cos(a) * 39 * lobe, cy + sin(a) * 39 * lobe]);
    }
    // Three pierced trefoil lobes
    bowHoles.push(getHoleVertices("round", cx - 12, cy, 9.5));
    bowHoles.push(getHoleVertices("round", cx + 5, cy - 13, 8.5));
    bowHoles.push(getHoleVertices("round", cx + 5, cy + 13, 8.5));
  } else if (k.bowType === "oval_pinched") {
    for (let i = 0; i < 28; i++) {
      let a = (i / 28) * 360;
      let pinch = 1 - 0.22 * pow(sin(a), 2);
      bowOuter.push([cx + cos(a) * 41, cy + sin(a) * 38 * pinch]);
    }
    bowHoles.push(getHoleVertices("round", cx - 14, cy, 10));
    bowHoles.push(getHoleVertices("round", cx + 12, cy, 10));
  } else {
    // shield_gothic (Key 12)
    bowOuter = [
      [cx - 42, cy - 22],
      [cx - 32, cy - 39],
      [cx + 6, cy - 41],
      [cx + 38, cy - 14],
      [cx + 42, cy],
      [cx + 38, cy + 14],
      [cx + 6, cy + 41],
      [cx - 32, cy + 39],
      [cx - 42, cy + 22]
    ];
    bowHoles.push(getHoleVertices("arch", cx - 16, cy, 11));
    bowHoles.push(getHoleVertices("round", cx + 10, cy - 13, 7.5));
    bowHoles.push(getHoleVertices("round", cx + 10, cy + 13, 7.5));
  }

  return { bowOuter, bowHoles };
}

function getBitPolygons(k, r) {
  let polys = [];
  let bx = k.bitX;
  let bw = k.bitW;
  let bh = k.bitH;

  // Lower warded bit
  polys.push([
    [bx, r - 1],
    [bx + bw, r - 1],
    [bx + bw, r + bh],
    [bx, r + bh]
  ]);

  // Symmetrical upper bit for double-bitted mortise key (Key 5)
  if (k.doubleBit) {
    polys.push([
      [bx + 3, -r + 1],
      [bx + bw - 3, -r + 1],
      [bx + bw - 3, -r - bh * 0.88],
      [bx + 3, -r - bh * 0.88]
    ]);
  }
  return polys;
}

function renderSkeletonBit(k, bitPolys, r) {
  const pal = k.pal;
  let bx = k.bitX, bw = k.bitW, bh = k.bitH;

  for (let poly of bitPolys) {
    // 3D thickness rim
    let rim = poly.map(p => [p[0] + 1.2, p[1] + 2.8]);
    drawPolygonWash(rim, pal.deep, 245);
    drawPolygonWash(poly, pal.base, 252);
  }

  // Stepped bevels & shading on the lower bit
  brush.set("gouache", pal.mid, 1.3);
  brush.line(bx + 2, r + 3, bx + bw - 2, r + 3);
  brush.line(bx + 2, r + bh - 4, bx + bw - 2, r + bh - 4);

  // Golden Brazed Brass Repair on Victorian Iron Key (Key 12)
  if (k.brazedRepair) {
    let repairPoly = [
      [bx + 2, r + 6],
      [bx + bw - 1, r + 3],
      [bx + bw - 1, r + 15],
      [bx + 4, r + 18]
    ];
    drawPolygonWash(repairPoly, "#d9900f", 240);
    brush.set("gouache", "#ffcf54", 1.1);
    brush.line(bx + 3, r + 8, bx + bw - 2, r + 6);
    brush.set("micro_pencil", "#7a4900", 0.85);
    brush.line(bx + 2, r + 16, bx + bw - 2, r + 14);
  }

  // Cut Intricate Ward Slots into the Bit (revealing paper + rim glint)
  const wardSlots = [
    [bx + bw * 0.44, r + bh * 0.35, 4.2, bh * 0.68], // Center vertical ward slot
    [bx + bw * 0.22, r + bh * 0.55, bw * 0.55, 3.8], // Horizontal T-bridge slot
    [bx - 0.5, r + bh * 0.42, 5.5, 4.2],             // Left edge ward notch
    [bx + bw - 5, r + bh * 0.68, 5.5, 4.2]           // Right edge ward notch
  ];

  for (let [wx, wy, ww, wh] of wardSlots) {
    let slotPoly = [
      [wx, wy], [wx + ww, wy], [wx + ww, wy + wh], [wx, wy + wh]
    ];
    drawPolygonWash(slotPoly, PAPER_BG, 250);
    // Dark inner thickness of the slot
    brush.set("rotring", pal.deep, 0.38);
    brush.line(wx, wy, wx + ww, wy);
    brush.line(wx, wy, wx, wy + wh);
    // Specular glint on opposite edge of the ward cut
    brush.set("micro_pencil", pal.hi, 0.9);
    brush.line(wx, wy + wh, wx + ww, wy + wh);
  }

  if (k.doubleBit) {
    let uSlot = [
      [bx + bw * 0.45, -r - bh * 0.88],
      [bx + bw * 0.45 + 4, -r - bh * 0.88],
      [bx + bw * 0.45 + 4, -r - 6],
      [bx + bw * 0.45, -r - 6]
    ];
    drawPolygonWash(uSlot, PAPER_BG, 250);
  }

  // Highlight along the leading left edge of the bit
  brush.set("micro_pencil", pal.hi, 1.05);
  brush.line(bx, r + 1, bx, r + bh);
}

function renderSkeletonShank(k, x1, x2, r) {
  const pal = k.pal;

  // Cylindrical Barrel Shading (from top -r to bottom +r)
  const bands = [
    { y: -r,       col: pal.dark, w: 1.0 },
    { y: -r * 0.6, col: pal.mid,  w: 1.3 },
    { y: -r * 0.25,col: pal.hi,   w: 1.1 }, // Specular cylindrical highlight ridge
    { y: r * 0.15, col: pal.base, w: 1.4 },
    { y: r * 0.55, col: pal.deep, w: 1.5 }, // Core shadow
    { y: r * 0.9,  col: pal.rim,  w: 0.9 }  // Reflected bounce light on bottom edge
  ];

  for (let b of bands) {
    brush.set("gouache", b.col, b.w);
    brush.line(x1, b.y, x2 - 3, b.y);
  }

  // Turned button finial at the tip of the barrel
  brush.noStroke();
  brush.wash(pal.deep, 245);
  brush.circle(x2 - 1, 0.8, r * 0.95);
  brush.wash(pal.mid, 245);
  brush.circle(x2 - 2, -0.5, r * 0.85);
  brush.wash(pal.hi, 230);
  brush.circle(x2 - 2.5, -1.8, r * 0.42);
  brush.noWash();

  // Rust flecks or oil-stain patina along the shank and bit
  if (k.rustLevel) {
    drawRustAndPatinaFlecks(x1 - 30, x2, -r, r + 18, k.rustLevel, pal);
  }
}

function renderTurnedCollar(k, cx, r) {
  const pal = k.pal;
  const rings = [-6, -1.5, 3, 7.5];
  for (let i = 0; i < rings.length; i++) {
    let rx = cx + rings[i];
    let cr = (i === 1 || i === 2) ? r * 1.68 : r * 1.35;

    // Patina/rust crust in the crevices between turned rings
    brush.set("gouache", pal.patina, 1.3);
    brush.line(rx - 1.6, -cr * 0.9, rx - 1.6, cr * 0.9);

    // Turned ring body
    brush.set("gouache", pal.deep, 1.4);
    brush.line(rx + 0.8, -cr, rx + 0.8, cr + 1.5);
    brush.set("gouache", pal.base, 1.3);
    brush.line(rx, -cr, rx, cr);

    // Bright specular bead highlight at top-center of each turned ring
    brush.set("gouache", pal.hi, 1.1);
    brush.line(rx - 0.4, -cr * 0.75, rx - 0.4, -cr * 0.15);
  }
}

function renderSkeletonBow(k, bowOuter, bowHoles, cx, cy) {
  const pal = k.pal;

  // 1. 3D Thickness Rim
  let rim = bowOuter.map(p => [p[0] + 1.2, p[1] + 3.6]);
  drawPolygonWash(rim, pal.deep, 245);

  // 2. Main Bow Fill
  drawPolygonWash(bowOuter, pal.base, 252);

  // 3. Highlight & Shadow Modeling around the Forged Bow
  for (let i = 0; i < bowOuter.length; i++) {
    let p1 = bowOuter[i];
    let p2 = bowOuter[(i + 1) % bowOuter.length];
    let isUpperLeft = (p1[1] + p2[1]) * 0.5 < 4;
    brush.set("gouache", isUpperLeft ? pal.mid : pal.dark, 1.15);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (isUpperLeft) {
      brush.set("micro_pencil", pal.hi, 0.95);
      brush.line(p1[0] + 0.8, p1[1] + 1.2, p2[0] + 0.8, p2[1] + 1.2);
    }
  }

  // Stamped number on flat lever key bow (Key 8)
  if (k.stamp) {
    drawStampedText(k.stamp, cx + 6, cy - 5, 0.95, pal.deep, pal.hi);
  }

  // Rust blooms & pitting on the bow
  if (k.rustLevel) {
    drawRustAndPatinaFlecks(cx - 35, cx + 30, -30, 30, k.rustLevel * 0.85, pal);
  }

  // 4. Cut out all pierced openings with 3D rim & paper interior
  for (let hPts of bowHoles) {
    renderKeyholeCutout(hPts, pal);
  }
}

// ============================================================================
// SURFACE HYPERREALISM: RUST FLECKS, VERDIGRIS & POCKET SCRATCHES
// ============================================================================

function drawRustAndPatinaFlecks(xMin, xMax, yMin, yMax, intensity, pal) {
  let count = floor(32 * intensity);
  for (let i = 0; i < count; i++) {
    let rx = random(xMin, xMax);
    let ry = random(yMin, yMax);
    // Keep flecks on the key structure
    if (rx > -36 && abs(ry) > 6.5 && (rx < 65 || ry < 0)) continue;

    let col = i % 3 === 0 ? pal.rust2 : (i % 3 === 1 ? pal.rust1 : pal.rustDark);
    brush.set("micro_pencil", col, random(0.65, 1.25));
    let len = random(1.5, 4.5);
    let ang = random(360);
    brush.line(rx, ry, rx + cos(ang) * len, ry + sin(ang) * len);
  }
}

function drawPocketScratches(xMin, xMax, yMin, yMax, count, hiCol, darkCol) {
  for (let i = 0; i < count; i++) {
    let sx = random(xMin, xMax);
    let sy = random(yMin, yMax);
    let len = random(4, 15);
    let ang = random(-65, 75);
    let ex = sx + cos(ang) * len;
    let ey = sy + sin(ang) * len;

    // Fine dark oxidized scratch groove + adjacent bright metallic burr
    brush.set("2H", darkCol, 0.16);
    brush.line(sx, sy, ex, ey);
    brush.set("micro_pencil", hiCol, 0.42);
    brush.line(sx + 0.35, sy + 0.35, ex + 0.35, ey + 0.35);
  }
}

