let juiceDrops = [];

// Spatial hash grid for strict grout-preserving non-overlapping tessera placement
const GRID_CELL = 10;
const GRID_DIM = 120;
let spatialGrid = [];

function initSpatialGrid() {
  spatialGrid = new Array(GRID_DIM * GRID_DIM);
  for (let i = 0; i < spatialGrid.length; i++) {
    spatialGrid[i] = [];
  }
}

function canPlaceTile(x, y, r, minBorder) {
  let margin = minBorder || 12;
  if (x < margin || x > 1200 - margin || y < margin || y > 1200 - margin) return false;
  let cx = Math.floor(x / GRID_CELL);
  let cy = Math.floor(y / GRID_CELL);
  let searchRad = Math.ceil((r + 14) / GRID_CELL);
  for (let dy = -searchRad; dy <= searchRad; dy++) {
    let ny = cy + dy;
    if (ny < 0 || ny >= GRID_DIM) continue;
    for (let dx = -searchRad; dx <= searchRad; dx++) {
      let nx = cx + dx;
      if (nx < 0 || nx >= GRID_DIM) continue;
      let cell = spatialGrid[ny * GRID_DIM + nx];
      for (let i = 0; i < cell.length; i++) {
        let other = cell[i];
        let ddx = x - other.x;
        let ddy = y - other.y;
        let minD = r + other.r;
        if (ddx * ddx + ddy * ddy < minD * minD) return false;
      }
    }
  }
  return true;
}

function registerTile(tile, r) {
  tiles.push(tile);
  let cx = Math.floor(tile.x / GRID_CELL);
  let cy = Math.floor(tile.y / GRID_CELL);
  if (cx >= 0 && cx < GRID_DIM && cy >= 0 && cy < GRID_DIM) {
    spatialGrid[cy * GRID_DIM + cx].push({ x: tile.x, y: tile.y, r: r });
  }
}

// Coordinate helper for rotated ellipse local space
function toLocal(x, y, cx, cy, angleDeg) {
  let rad = (angleDeg * Math.PI) / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  let dx = x - cx;
  let dy = y - cy;
  return {
    u: dx * c + dy * s,
    v: -dx * s + dy * c
  };
}

function toWorld(u, v, cx, cy, angleDeg) {
  let rad = (angleDeg * Math.PI) / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  return {
    x: cx + u * c - v * s,
    y: cy + u * s + v * c
  };
}

// Smooth angular distance
function angleDiff(a, b) {
  let d = ((a - b) % 360 + 540) % 360 - 180;
  return d;
}

