  ];

  // Generate pitted oil-gland coordinates across each lemon's 3D rind zone
  for (let li = 0; li < lemons.length; li++) {
    let L = lemons[li];
    for (let k = 0; k < 55; k++) {
      let ang = random(-180, 180);
      let t = random(0.12, 0.88);
      let pt = sampleRindPoint(L, t, ang);
      if (pt) {
        let tooClose = false;
        for (let m = 0; m < L.pits.length; m++) {
          let dx = pt.x - L.pits[m].x;
          let dy = pt.y - L.pits[m].y;
          if (dx * dx + dy * dy < 18 * 18) {
            tooClose = true;
            break;
          }
        }
        if (!tooClose) {
          L.pits.push({ x: pt.x, y: pt.y, r: random(6.5, 9.5) });
        }
      }
    }
  }

  // Solitary Bay Leaf in Deep Green Glass Tiles (Lower Foreground)
  bayLeaf = {
    cx: 482,
    cy: 922,
    angle: -14,
    halfLen: 122,
    halfWid: 47,
    stemLen: 34,
    shadowCx: 498,
    shadowCy: 942,
    shadowRx: 142,
    shadowRy: 58
  };

  // Glistening stray citrus juice droplets resting on the gold floor
  juiceDrops = [
    { x: 618, y: 812, rx: 14, ry: 11, angle: 12 },
    { x: 652, y: 834, rx: 9, ry: 8, angle: -8 },
    { x: 295, y: 828, rx: 11, ry: 9, angle: -18 }
  ];
}

// Compute outer 3D rind silhouette radius at local angle `angDeg` for a lemon
function getRindOuterPoint(L, angDeg) {
  let rad = (angDeg * Math.PI) / 180;
  let cu = Math.cos(rad);
  let sv = Math.sin(rad);
  // Nipple protrusion around rindDirAngle
  let dAng = angleDiff(angDeg, L.rindDirAngle);
  let nipple = L.nippleAmp * Math.exp(-(dAng * dAng) / (L.nippleWidth * L.nippleWidth));
  let u = L.rindShiftU + (L.rindRx + nipple * 0.45) * cu;
  let v = L.rindShiftV + (L.rindRy + nipple) * sv;
  return { u, v };
}

// Sample a point on the 3D rind crescent/dome between cut-face rim (t=0) and outer rind silhouette (t=1)
function sampleRindPoint(L, t, angDeg) {
  let rad = (angDeg * Math.PI) / 180;
  let innerU = L.rx * Math.cos(rad);
  let innerV = L.ry * Math.sin(rad);
  let outer = getRindOuterPoint(L, angDeg);
  // Check thickness along this ray
  let du = outer.u - innerU;
  let dv = outer.v - innerV;
  let dist = Math.sqrt(du * du + dv * dv);
  // Only valid where outer silhouette actually protrudes beyond cut face
  let outerNorm = (outer.u * outer.u) / (L.rx * L.rx) + (outer.v * outer.v) / (L.ry * L.ry);
  if (outerNorm <= 1.04 || dist < 6) return null;
  let u = innerU + du * t;
  let v = innerV + dv * t;
  let wPt = toWorld(u, v, L.cx, L.cy, L.angle);
  return { u, v, x: wPt.x, y: wPt.y, thick: dist };
}

// Signed distance / containment check for a lemon (including both cut face and 3D rind)
function getLemonDistance(x, y, L) {
  let loc = toLocal(x, y, L.cx, L.cy, L.angle);
  let u = loc.u;
  let v = loc.v;
  // Cut face ellipse distance approximation
  let cutNorm = Math.sqrt((u * u) / (L.rx * L.rx) + (v * v) / (L.ry * L.ry));
  let avgCutR = 0.5 * (L.rx + L.ry);
  let dCut = (cutNorm - 1.0) * avgCutR;

  // Rind silhouette distance approximation
  let ang = (Math.atan2(v - L.rindShiftV, u - L.rindShiftU) * 180) / Math.PI;
  let dAng = angleDiff(ang, L.rindDirAngle);
  let nipple = L.nippleAmp * Math.exp(-(dAng * dAng) / (L.nippleWidth * L.nippleWidth));
  let rRx = L.rindRx + nipple * 0.45;
  let rRy = L.rindRy + nipple;
  let du = u - L.rindShiftU;
  let dv = v - L.rindShiftV;
  let rindNorm = Math.sqrt((du * du) / (rRx * rRx) + (dv * dv) / (rRy * rRy));
  let avgRindR = 0.5 * (rRx + rRy);
  let dRind = (rindNorm - 1.0) * avgRindR;

  return Math.min(dCut, dRind);
}

// Bay leaf half-width profile along local u in [-halfLen, +halfLen]
function getBayLeafHalfWidth(u) {
  let normU = u / bayLeaf.halfLen;
  if (normU < -1 || normU > 1) return 0;
  // Pointed lanceolate profile with gentle wavy laurel margin
  let baseProfile = Math.pow(1 - normU * normU, 0.68);
  let wave = 1.0 + 0.055 * Math.sin(normU * Math.PI * 5.0);
  return bayLeaf.halfWid * baseProfile * wave;
}

function getBayLeafDistance(x, y) {
  let loc = toLocal(x, y, bayLeaf.cx, bayLeaf.cy, bayLeaf.angle);
  let u = loc.u;
  let v = loc.v;
  if (u > bayLeaf.halfLen && u <= bayLeaf.halfLen + bayLeaf.stemLen) {
    // Woody stem / petiole
    let stemHalfW = 3.5;
    return Math.abs(v - (u - bayLeaf.halfLen) * 0.12) - stemHalfW;
  }
  if (u < -bayLeaf.halfLen || u > bayLeaf.halfLen) {
    let dx = Math.abs(u) - bayLeaf.halfLen;
    return Math.sqrt(dx * dx + v * v);
  }
  let hw = getBayLeafHalfWidth(u);
  return Math.abs(v) - hw;
}

function getMinSubjectDistance(x, y) {
  let minD = 9999;
  for (let i = 0; i < lemons.length; i++) {
    let d = getLemonDistance(x, y, lemons[i]);
    if (d < minD) minD = d;
  }
  let dLeaf = getBayLeafDistance(x, y);
  if (dLeaf < minD) minD = dLeaf;
  return minD;
}

// Compute inner scalloped pith radius (with triangular gusset cusps at each septum!)
function getScallopedPithInner(L, rNorm, angDeg) {
  let minAngDist = 180;
  for (let i = 0; i < L.septaAngles.length; i++) {
    let sa = L.septaAngles[i] + L.septaCurve[i] * Math.sin(rNorm * Math.PI);
    let d = Math.abs(angleDiff(angDeg, sa));
    if (d < minAngDist) minAngDist = d;
  }
  // Inward triangular cusp where each septum joins the outer pith ring
  let cusp = 0.095 * Math.exp(-(minAngDist * minAngDist) / 38.0);
  let organicWobble = 0.015 * Math.sin((angDeg * Math.PI) / 180 * 7 + L.id * 2.1);
  return L.pithInner - cusp + organicWobble;
}

// ============================================================================
// TESSERA GENERATION BY ANATOMICAL PRIORITY
// ============================================================================

function generateAllTesserae() {
  initSpatialGrid();
  tiles = [];

  // 1. Pips (Seeds) inside the cut lemons
  for (let i = 0; i < lemons.length; i++) {
    generatePipTesserae(lemons[i]);
  }

  // 2. Central Pith Cores (Columella)
  for (let i = 0; i < lemons.length; i++) {
    generateCoreTesserae(lemons[i]);
  }

  // 3. Translucent Segment Walls (Septa)
  for (let i = 0; i < lemons.length; i++) {
    generateSeptaTesserae(lemons[i]);
  }

  // 4. Pulp Vesicles & Hyperreal Juice Beads inside each lemon segment
  for (let i = 0; i < lemons.length; i++) {
    generatePulpAndBeadTesserae(lemons[i]);
  }

  // 5. Inner White Pith Rings (Albedo)
  for (let i = 0; i < lemons.length; i++) {
    generatePithRingTesserae(lemons[i]);
  }

  // 6. Outer 3D Pitted Rind Crescents & Domes (Flavedo)
  for (let i = 0; i < lemons.length; i++) {
    generateRindTesserae(lemons[i]);
  }

  // 7. Solitary Bay Leaf in Deep Green Glass Tiles
  generateBayLeafTesserae();

  // 8. Stray Glistening Juice Droplets on the Gold Floor
  generateJuiceDropTesserae();

  // 9. Concentric Gold Halo Courses (Opus Circumdatum) around Fruit & Leaf
  generateHaloGoldTesserae();

  // 10. Undulating Gold Field & Cast Shadow Tesserae (Opus Tessellatum)
  generateBackgroundGoldTesserae();
}

function generatePipTesserae(L) {
  for (let p = 0; p < L.pips.length; p++) {
    let pip = L.pips[p];
    let pipWorld = toWorld(pip.u, pip.v, L.cx, L.cy, L.angle);
    let pipAngle = L.angle + pip.rot;

    // Center spine of pip (bright ivory highlight + warm flax)
    let steps = 4;
    for (let i = 0; i < steps; i++) {
      let t = (i / (steps - 1)) * 2 - 1; // -1 to 1
      let uOff = t * (pip.len * 0.36);
      let pt = toWorld(uOff, 0, pipWorld.x, pipWorld.y, pipAngle);
      let w = 6.2;
      let h = 5.4;
      let exR = 2.6;
      if (canPlaceTile(pt.x, pt.y, exR)) {
        registerTile({
          x: pt.x,
          y: pt.y,
          w: w,
          h: h,
          angle: pipAngle + random(-4, 4),
          baseColor: i === 1 || i === 2 ? "#fcf6e3" : "#ebd9b0",
          gleamColor: i === 1 ? "#ffffff" : "#fcf6e3",
          gleamType: i === 1 ? 3 : 1
        }, exR);
      }
    }

    // Outer ring of the teardrop pip (ivory upper-left, warm olive-ochre lower-right)
    let ringCount = 12;
    for (let i = 0; i < ringCount; i++) {
      let a = (i / ringCount) * 360;
      let rad = (a * Math.PI) / 180;
      // Teardrop taper toward -u (pointed toward lemon core)
      let taper = 1.0 + 0.25 * Math.cos(rad);
      let lu = Math.cos(rad) * (pip.len * 0.44);
      let lv = Math.sin(rad) * (pip.wid * 0.42) * taper;
      let pt = toWorld(lu, lv, pipWorld.x, pipWorld.y, pipAngle);
      let tang = pipAngle + a + 90 + random(-5, 5);
      let isLit = Math.sin(rad - 0.6) < 0;
      let w = 5.8;
      let h = 4.6;
      let exR = 2.5;
      if (canPlaceTile(pt.x, pt.y, exR)) {
        registerTile({
          x: pt.x,
          y: pt.y,
          w: w,
          h: h,
          angle: tang,
          baseColor: isLit ? "#f2e6c2" : "#9e8138",
          gleamColor: isLit ? "#fcf6e3" : "#cfba82",
          gleamType: isLit ? 1 : 0
        }, exR);
      }
    }

    // Dark wet cavity shadow ring immediately hugging the pip
    let cavCount = 15;
    for (let i = 0; i < cavCount; i++) {
      let a = (i / cavCount) * 360;
      let rad = (a * Math.PI) / 180;
      let lu = Math.cos(rad) * (pip.len * 0.66);
      let lv = Math.sin(rad) * (pip.wid * 0.68);
      let pt = toWorld(lu, lv, pipWorld.x, pipWorld.y, pipAngle);
      let tang = pipAngle + a + 90 + random(-6, 6);
      let w = 6.2;
      let h = 5.0;
      let exR = 2.8;
      if (canPlaceTile(pt.x, pt.y, exR)) {
        registerTile({
          x: pt.x,
          y: pt.y,
          w: w,
          h: h,
          angle: tang,
          baseColor: "#662902",
          gleamColor: "#823802",
          gleamType: 0
        }, exR);
      }
    }
  }
}

function generateCoreTesserae(L) {
  let coreWorld = toWorld(L.coreU, L.coreV, L.cx, L.cy, L.angle);
  // Center dimple tile
  if (canPlaceTile(coreWorld.x, coreWorld.y, 3.0)) {
    registerTile({
      x: coreWorld.x,
      y: coreWorld.y,
      w: 6.4,
      h: 6.4,
      angle: random(360),
      baseColor: "#b59b5b",
      gleamColor: "#cfba82",
      gleamType: 0
    }, 3.0);
  }

  // Two tight rings of creamy star-pith tesserae
  let rings = [0.065, 0.125];
  for (let ri = 0; ri < rings.length; ri++) {
    let rNorm = rings[ri];
    let avgR = 0.5 * (L.rx + L.ry) * rNorm;
    let circumference = 2 * Math.PI * avgR;
    let count = Math.max(7, Math.floor(circumference / 8.2));
    for (let i = 0; i < count; i++) {
      let a = (i / count) * 360 + ri * 17;
      let rad = (a * Math.PI) / 180;
      let u = L.coreU + L.rx * rNorm * Math.cos(rad);
      let v = L.coreV + L.ry * rNorm * Math.sin(rad);
      let pt = toWorld(u, v, L.cx, L.cy, L.angle);
      let tang = L.angle + a + 90 + random(-6, 6);
      let exR = 3.1;
      if (canPlaceTile(pt.x, pt.y, exR)) {
        registerTile({
          x: pt.x,
          y: pt.y,
          w: 6.8,
          h: 5.8,
          angle: tang,
          baseColor: ri === 0 ? "#e3cfa0" : "#f2e6c2",
          gleamColor: "#fcf6e3",
          gleamType: 1
        }, exR);
      }
    }
  }
}

function generateSeptaTesserae(L) {
  // Radial translucent segment membranes connecting core to outer pith ring
  for (let s = 0; s < L.septaAngles.length; s++) {
    let baseAng = L.septaAngles[s];
    let curveAmp = L.septaCurve[s];
    let startR = L.coreRad + 0.03;
    let endR = L.pithInner - 0.03;
    let avgSpan = 0.5 * (L.rx + L.ry) * (endR - startR);
    let steps = Math.max(8, Math.floor(avgSpan / 9.2));

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let rNorm = startR + t * (endR - startR);
      let ang = baseAng + curveAmp * Math.sin(t * Math.PI);
      let rad = (ang * Math.PI) / 180;
      let u = L.coreU * (1 - rNorm) + L.rx * rNorm * Math.cos(rad);
      let v = L.coreV * (1 - rNorm) + L.ry * rNorm * Math.sin(rad);
      let pt = toWorld(u, v, L.cx, L.cy, L.angle);
      let rayAng = L.angle + ang + curveAmp * Math.cos(t * Math.PI) * 2.5 + random(-3.5, 3.5);
      let exR = 2.9;

      if (canPlaceTile(pt.x, pt.y, exR)) {
        let isOuter = t > 0.65;
        registerTile({
          x: pt.x,
          y: pt.y,
          w: 7.8,
          h: 4.5,
          angle: rayAng,
          baseColor: isOuter ? "#ebd9b0" : "#e3cfa0",
          gleamColor: "#fcf6e3",
          gleamType: 1
        }, exR);
      }
    }
  }
}

function generatePulpAndBeadTesserae(L) {
  // Concentric curved vesicle courses inside each segment
  let startR = L.coreRad + 0.055;
  let endR = L.pithInner - 0.015;
  let avgRadius = 0.5 * (L.rx + L.ry);
  let numCourses = Math.floor(((endR - startR) * avgRadius) / 8.8);

  for (let ci = 0; ci <= numCourses; ci++) {
    let tR = ci / Math.max(1, numCourses);
    let rNorm = startR + tR * (endR - startR);
    let courseRadius = avgRadius * rNorm;
    let tileW = map(tR, 0, 1, 6.4, 8.6);
    let tileH = map(tR, 0, 1, 5.4, 6.8);
    let stepArc = tileW + 2.5;
    let count = Math.max(14, Math.floor((2 * Math.PI * courseRadius) / stepArc));

    for (let i = 0; i < count; i++) {
      let ang = (i / count) * 360 + (ci % 2) * (180 / count);
      let maxR = getScallopedPithInner(L, rNorm, ang) - 0.02;
      if (rNorm > maxR) continue;

      let rad = (ang * Math.PI) / 180;
      let u = L.coreU * (1 - rNorm) + L.rx * rNorm * Math.cos(rad);
      let v = L.coreV * (1 - rNorm) + L.ry * rNorm * Math.sin(rad);
      let pt = toWorld(u, v, L.cx, L.cy, L.angle);

      // Check distance to nearest septum for vesicle curvature & shading
      let minSeptumDeg = 180;
      for (let s = 0; s < L.septaAngles.length; s++) {
        let sa = L.septaAngles[s] + L.septaCurve[s] * Math.sin(tR * Math.PI);
        let d = Math.abs(angleDiff(ang, sa));
        if (d < minSeptumDeg) minSeptumDeg = d;
      }

      // Check proximity to hyperreal juice beads
      let beadHit = null;
      let beadDist = 999;
      for (let b = 0; b < L.beads.length; b++) {
        let bd = L.beads[b];
        let bRad = (bd.a * Math.PI) / 180;
        let bu = L.coreU * (1 - bd.r) + L.rx * bd.r * Math.cos(bRad);
        let bv = L.coreV * (1 - bd.r) + L.ry * bd.r * Math.sin(bRad);
        let bWorld = toWorld(bu, bv, L.cx, L.cy, L.angle);
        let d = dist(pt.x, pt.y, bWorld.x, bWorld.y);
        if (d < bd.rad && d < beadDist) {
          beadDist = d;
          beadHit = { bd, bWorld, dx: pt.x - bWorld.x, dy: pt.y - bWorld.y };
        }
      }

      // Orientation of pulp tesserae: follow arched vesicle courses with slight hand tilt
      let tileAngle = L.angle + ang + 90 + random(-6, 6);
      let exR = 0.39 * Math.max(tileW, tileH) + 0.95;

      if (!canPlaceTile(pt.x, pt.y, exR)) continue;

      let baseCol, gleamCol, gType = 0;

      if (beadHit) {
        // Hyperreal wet juice bead optics:
        // Upper-left core blazes white-gold, mid-belly glows electric citron, outer rim refracts deep honey-amber
        let lightProj = (beadHit.dx * -0.707 + beadHit.dy * -0.707) / beadHit.bd.rad;
        if (beadDist < beadHit.bd.rad * 0.42 || lightProj > 0.15) {
          baseCol = "#fff7bf";
          gleamCol = "#ffffff";
          gType = 3;
        } else if (beadDist < beadHit.bd.rad * 0.72) {
          baseCol = "#ffe652";
          gleamCol = "#fffdf0";
          gType = 3;
        } else {
          // Dark honey-amber liquid surface-tension rim
          baseCol = "#823802";
          gleamCol = "#b36004";
          gType = 0;
        }
      } else {
        // Translucent citrus pulp gradient:
        // Deep amber-saffron in the central hollow of each segment, glowing citron near septa & light side
        let lightBias = Math.cos(((L.angle + ang + 135) * Math.PI) / 180);
        let nVal = noise(pt.x * 0.025, pt.y * 0.025);
        let radialHollow = Math.sin(tR * Math.PI); // deeper in mid-segment belly
        let septumGlow = Math.exp(-(minSeptumDeg * minSeptumDeg) / 45.0);
        let lum = 0.48 + 0.22 * lightBias - 0.28 * radialHollow + 0.25 * septumGlow + (nVal - 0.5) * 0.32;

        if (lum > 0.76) {
          baseCol = "#ffe652";
          gleamCol = "#fff7bf";
          gType = 2;
        } else if (lum > 0.60) {
          baseCol = "#ffd82b";
          gleamCol = "#ffe652";
          gType = 2;
        } else if (lum > 0.46) {
          baseCol = "#f7c316";
          gleamCol = "#ffd82b";
          gType = 1;
        } else if (lum > 0.34) {
          baseCol = "#eba90c";
          gleamCol = "#f7c316";
          gType = 1;
        } else if (lum > 0.22) {
          baseCol = "#db8f08";
          gleamCol = "#eba90c";
          gType = 0;
        } else if (lum > 0.10) {
          baseCol = "#c77706";
          gleamCol = "#db8f08";
          gType = 0;
        } else {
          baseCol = "#9c4b03";
          gleamCol = "#b36004";
          gType = 0;
        }
      }

      registerTile({
        x: pt.x + random(-0.4, 0.4),
        y: pt.y + random(-0.4, 0.4),
        w: tileW * random(0.94, 1.06),
        h: tileH * random(0.94, 1.06),
        angle: tileAngle,
        baseColor: baseCol,
        gleamColor: gleamCol,
        gleamType: gType
      }, exR);
    }
  }
}

function generatePithRingTesserae(L) {
  // Creamy white albedo ring with scalloped inner gussets where septa attach
  let avgRadius = 0.5 * (L.rx + L.ry);
  let courses = 4;
  for (let ci = 0; ci < courses; ci++) {
    let t = ci / (courses - 1);
    let tileW = 8.4;
    let tileH = 6.6;
    let approxR = avgRadius * (L.pithInner + 0.06);
    let count = Math.floor((2 * Math.PI * approxR) / (tileW + 2.4));

    for (let i = 0; i < count; i++) {
      let ang = (i / count) * 360 + (ci % 2) * (180 / count);
      let innerR = getScallopedPithInner(L, 0.82, ang);
      let outerR = L.pithOuter + 0.012 * Math.sin((ang * Math.PI) / 180 * 5);
      let rNorm = innerR + t * (outerR - innerR);

      let rad = (ang * Math.PI) / 180;
      let u = L.rx * rNorm * Math.cos(rad);
      let v = L.ry * rNorm * Math.sin(rad);
      let pt = toWorld(u, v, L.cx, L.cy, L.angle);
      let tang = L.angle + ang + 90 + random(-5, 5);
      let exR = 0.39 * Math.max(tileW, tileH) + 0.95;

      if (!canPlaceTile(pt.x, pt.y, exR)) continue;

      let lightBias = Math.cos(((L.angle + ang + 135) * Math.PI) / 180);
      let nVal = noise(pt.x * 0.02, pt.y * 0.02);
      let tone = lightBias * 0.35 + (nVal - 0.5) * 0.3 + (1 - t) * 0.15;

      let baseCol, gleamCol, gType = 0;
      if (tone > 0.22) {
        baseCol = "#fcf6e3";
        gleamCol = "#ffffff";
        gType = 1;
      } else if (tone > 0.0) {
        baseCol = "#f2e6c2";
        gleamCol = "#fcf6e3";
        gType = 1;
      } else if (tone > -0.22) {
        baseCol = "#e3cfa0";
        gleamCol = "#f2e6c2";
        gType = 0;
      } else {
        baseCol = "#cfba82";
        gleamCol = "#e3cfa0";
        gType = 0;
      }

      registerTile({
        x: pt.x + random(-0.4, 0.4),
        y: pt.y + random(-0.4, 0.4),
        w: tileW * random(0.93, 1.06),
        h: tileH * random(0.93, 1.06),
        angle: tang,
        baseColor: baseCol,
        gleamColor: gleamCol,
        gleamType: gType
      }, exR);
    }
  }
}

function generateRindTesserae(L) {
  // 1. Thin cut-edge flavedo rim (from pithOuter to 1.0) all around the cut face
  let avgRadius = 0.5 * (L.rx + L.ry);
  let rimCount = Math.floor((2 * Math.PI * avgRadius * 0.97) / 10.6);
  for (let i = 0; i < rimCount; i++) {
    let ang = (i / rimCount) * 360;
    let rNorm = 0.968;
    let rad = (ang * Math.PI) / 180;
    let u = L.rx * rNorm * Math.cos(rad);
    let v = L.ry * rNorm * Math.sin(rad);
    let pt = toWorld(u, v, L.cx, L.cy, L.angle);
    let tang = L.angle + ang + 90 + random(-5, 5);
    let tileW = 8.4;
    let tileH = 6.2;
    let exR = 3.9;
    if (canPlaceTile(pt.x, pt.y, exR)) {
      let lightBias = Math.cos(((L.angle + ang + 135) * Math.PI) / 180);
      let baseCol = lightBias > 0 ? "#ffd82b" : "#db8f08";
      let gleamCol = lightBias > 0 ? "#ffe652" : "#f7c316";
      registerTile({
        x: pt.x,
        y: pt.y,
        w: tileW,
        h: tileH,
        angle: tang,
        baseColor: baseCol,
        gleamColor: gleamCol,
        gleamType: lightBias > 0.2 ? 1 : 0
      }, exR);
    }
  }

  // 2. Curved 3D Pitted Rind Crescent / Dome courses outside the cut face
  let maxCourses = 18;
  for (let ci = 1; ci <= maxCourses; ci++) {
    let t = ci / maxCourses; // 0 (cut rim) to 1 (outer rind silhouette)
    let angleSteps = 140;
    let prevPt = null;

    for (let ai = 0; ai < angleSteps; ai++) {
      let ang = -180 + (ai / angleSteps) * 360;
      let samp = sampleRindPoint(L, t, ang);
      if (!samp) {
        prevPt = null;
        continue;
      }
      // Ensure local radial spacing matches the thickness at this angle
      let neededCourses = Math.max(1, Math.floor(samp.thick / 8.8));
      let courseIdxFloat = t * neededCourses;
      if (Math.abs(courseIdxFloat - Math.round(courseIdxFloat)) > 0.34 && neededCourses < maxCourses * 0.7) {
        continue;
      }

      let nextSamp = sampleRindPoint(L, t, ang + 2.5);
      let tang = L.angle + ang + 90;
      if (nextSamp) {
        tang = (Math.atan2(nextSamp.y - samp.y, nextSamp.x - samp.x) * 180) / Math.PI;
      }

      let tileW = 8.8;
      let tileH = 7.4;
      let exR = 0.40 * Math.max(tileW, tileH) + 1.05;

      if (!canPlaceTile(samp.x, samp.y, exR)) continue;

      // Check if this tile falls on a concave pitted oil gland!
      let isPit = false;
      for (let p = 0; p < L.pits.length; p++) {
        let d = dist(samp.x, samp.y, L.pits[p].x, L.pits[p].y);
        if (d < L.pits[p].r) {
          isPit = true;
          break;
        }
      }

      // 3D Spherical-Conical Rind Lighting + Warm Reflected Gold Bounce on underside
      let worldAng = L.angle + ang;
      let lightDot = Math.cos(((worldAng + 135) * Math.PI) / 180);
      let domeCurve = Math.sin(t * Math.PI); // 3D roundness across the rind dome
      let reflectedGold = t > 0.72 && lightDot < -0.2 ? 0.26 : 0.0;
      let nVal = noise(samp.x * 0.025, samp.y * 0.025);
      let lum = 0.46 + 0.34 * lightDot + 0.14 * domeCurve + reflectedGold + (nVal - 0.5) * 0.22;

      let baseCol, gleamCol, gType = 0;
      if (isPit) {
        // Concave oil gland pit: dark amber-ochre pit with bright lower-right rim glint!
        baseCol = lum > 0.45 ? "#9c4b03" : "#662902";
        gleamCol = lum > 0.45 ? "#ffe652" : "#db8f08";
        gType = 4;
      } else if (lum > 0.78) {
        baseCol = "#ffe652";
        gleamCol = "#fff7bf";
        gType = 2;
      } else if (lum > 0.62) {
        baseCol = "#ffd82b";
        gleamCol = "#ffe652";
        gType = 1;
      } else if (lum > 0.48) {
        baseCol = "#f7c316";
        gleamCol = "#ffd82b";
        gType = 1;
      } else if (lum > 0.34) {
        baseCol = "#eba90c";
        gleamCol = "#f7c316";
        gType = 0;
      } else if (lum > 0.22) {
        baseCol = "#db8f08";
        gleamCol = "#eba90c";
        gType = 0;
      } else {
        baseCol = "#b36004";
        gleamCol = "#c77706";
        gType = 0;
      }

      registerTile({
        x: samp.x + random(-0.4, 0.4),
        y: samp.y + random(-0.4, 0.4),
        w: tileW * random(0.93, 1.07),
        h: tileH * random(0.93, 1.07),
        angle: tang + random(-5, 5),
        baseColor: baseCol,
        gleamColor: gleamCol,
        gleamType: gType
      }, exR);
    }
  }
}

function generateBayLeafTesserae() {
  // 1. Midrib vein (costa) and woody petiole stem
  let midribSteps = 28;
  for (let i = 0; i <= midribSteps; i++) {
    let t = i / midribSteps;
    let u = -bayLeaf.halfLen + 6 + t * (bayLeaf.halfLen * 2 + bayLeaf.stemLen - 8);
    let v = u > bayLeaf.halfLen ? (u - bayLeaf.halfLen) * 0.12 : 2.5 * Math.sin((u / bayLeaf.halfLen) * Math.PI);
    let pt = toWorld(u, v, bayLeaf.cx, bayLeaf.cy, bayLeaf.angle);
    let isStem = u > bayLeaf.halfLen;
    let w = isStem ? 7.2 : 7.8;
    let h = isStem ? 5.2 : 4.4;
    let exR = 2.8;
    if (canPlaceTile(pt.x, pt.y, exR)) {
      registerTile({
        x: pt.x,
        y: pt.y,
        w: w,
        h: h,
        angle: bayLeaf.angle + random(-3, 3),
        baseColor: isStem ? "#663306" : "#8eab3c",
        gleamColor: isStem ? "#8c4c07" : "#d4e388",
        gleamType: 1
      }, exR);
    }
  }

  // 2. Arching lateral secondary veins in celadon/chartreuse glass
  let veinOrigins = [-78, -42, -6, 30, 64];
  for (let vi = 0; vi < veinOrigins.length; vi++) {
    let u0 = veinOrigins[vi];
    for (let side = -1; side <= 1; side += 2) {
      let maxW = getBayLeafHalfWidth(u0) * 0.85;
      let steps = Math.max(3, Math.floor(maxW / 8.5));
      for (let s = 1; s <= steps; s++) {
        let frac = s / steps;
        let u = u0 - frac * 22; // arches toward leaf apex
        let v = side * frac * getBayLeafHalfWidth(u) * 0.84;
        let pt = toWorld(u, v, bayLeaf.cx, bayLeaf.cy, bayLeaf.angle);
        let veinAng = bayLeaf.angle + side * (135 - frac * 25);
        let exR = 2.9;
        if (canPlaceTile(pt.x, pt.y, exR)) {
          registerTile({
            x: pt.x,
            y: pt.y,
            w: 7.4,
            h: 4.5,
            angle: veinAng + random(-4, 4),
            baseColor: side < 0 ? "#8eab3c" : "#6f8f28",
            gleamColor: side < 0 ? "#d4e388" : "#b2c95b",
            gleamType: 1
          }, exR);
        }
      }
    }
  }

  // 3. Deep green glass smalti courses curving along the leaf blade
  let uSteps = 26;
  for (let ui = 0; ui <= uSteps; ui++) {
    let u = -bayLeaf.halfLen + 8 + (ui / uSteps) * (bayLeaf.halfLen * 2 - 16);
    let hw = getBayLeafHalfWidth(u) - 3.5;
    if (hw < 4) continue;
    let vCount = Math.max(2, Math.floor((hw * 2) / 8.2));
    for (let vi = 0; vi <= vCount; vi++) {
      let v = -hw + (vi / vCount) * (hw * 2);
      let pt = toWorld(u, v, bayLeaf.cx, bayLeaf.cy, bayLeaf.angle);
      let edgeFrac = Math.abs(v) / hw;
      let contourSlope = (-u / (bayLeaf.halfLen * bayLeaf.halfLen)) * bayLeaf.halfWid * (v >= 0 ? 1 : -1);
      let slopeDeg = (Math.atan2(contourSlope, 1) * 180) / Math.PI;
      let tileAng = bayLeaf.angle + slopeDeg * edgeFrac + random(-6, 6);

      let tileW = 7.8;
      let tileH = 6.8;
      let exR = 3.6;
      if (!canPlaceTile(pt.x, pt.y, exR)) continue;

      // Vitreous green glass lighting: upper half (v < 0) catches warm light & specular glass glints
      let nVal = noise(pt.x * 0.03, pt.y * 0.03);
      let waveGlint = Math.sin((u / bayLeaf.halfLen) * Math.PI * 3.5);
      let lum = (v < 0 ? 0.62 : 0.28) + 0.18 * waveGlint + (nVal - 0.5) * 0.32;

      let baseCol, gleamCol, gType = 0;
      if (lum > 0.72) {
        baseCol = "#6f8f28";
        gleamCol = "#b2c95b";
        gType = 2;
      } else if (lum > 0.54) {
        baseCol = "#4f731c";
        gleamCol = "#8eab3c";
        gType = 1;
      } else if (lum > 0.38) {
        baseCol = "#365916";
        gleamCol = "#4f731c";
        gType = 1;
      } else if (lum > 0.24) {
        baseCol = "#224212";
        gleamCol = "#365916";
        gType = 0;
      } else {
        baseCol = "#142e0c";
        gleamCol = "#224212";
        gType = 0;
      }

      registerTile({
        x: pt.x + random(-0.4, 0.4),
        y: pt.y + random(-0.4, 0.4),
        w: tileW * random(0.92, 1.08),
        h: tileH * random(0.92, 1.08),
        angle: tileAng,
        baseColor: baseCol,
        gleamColor: gleamCol,
        gleamType: gType
      }, exR);
    }
  }
}

function generateJuiceDropTesserae() {
  for (let i = 0; i < juiceDrops.length; i++) {
    let d = juiceDrops[i];
    let exR = 4.2;
    // Upper-left bright specular juice tile
    let pt1 = toWorld(-d.rx * 0.25, -d.ry * 0.2, d.x, d.y, d.angle);
    if (canPlaceTile(pt1.x, pt1.y, exR)) {
      registerTile({
        x: pt1.x,
