        h: 7.2,
        angle: d.angle + random(-5, 5),
        baseColor: "#ffe652",
        gleamColor: "#ffffff",
        gleamType: 3
      }, exR);
    }
    // Lower-right honey-amber refraction tile
    let pt2 = toWorld(d.rx * 0.35, d.ry * 0.25, d.x, d.y, d.angle);
    if (canPlaceTile(pt2.x, pt2.y, exR)) {
      registerTile({
