}

// Compute shadow intensity at (x, y) on the gold floor cast by the 3 lemons and bay leaf
function getGoldShadowFactor(x, y) {
  let maxS = 0;
  for (let i = 0; i < lemons.length; i++) {
    let L = lemons[i];
    let loc = toLocal(x, y, L.shadowCx, L.shadowCy, L.shadowAngle);
    let normD = Math.sqrt((loc.u * loc.u) / (L.shadowRx * L.shadowRx) + (loc.v * loc.v) / (L.shadowRy * L.shadowRy));
    if (normD < 1.0) {
      let s = Math.pow(1.0 - normD, 1.35) * 0.88;
      if (s > maxS) maxS = s;
    }
  }
  let locLeaf = toLocal(x, y, bayLeaf.shadowCx, bayLeaf.shadowCy, bayLeaf.angle);
  let normLeaf = Math.sqrt(
    (locLeaf.u * locLeaf.u) / (bayLeaf.shadowRx * bayLeaf.shadowRx) +
    (locLeaf.v * locLeaf.v) / (bayLeaf.shadowRy * bayLeaf.shadowRy)
  );
  if (normLeaf < 1.0) {
    let s = Math.pow(1.0 - normLeaf, 1.3) * 0.78;
    if (s > maxS) maxS = s;
  }
  return maxS;
}

// Select gold tessera colors for a given position, halo proximity, and shadow intensity
function pickGoldColors(x, y, haloBoost, shadowFactor) {
  let nLarge = noise(x * 0.0038, y * 0.0038);
  let nMed = noise(x * 0.014 + 50, y * 0.014 + 50);
  let tileTilt = random(-0.28, 0.30);

  // Subtle devotional radial glow centered on the triad of lemons
  let dCenter = dist(x, y, 585, 565);
  let aura = constrain(map(dCenter, 80, 620, 0.18, -0.16), -0.18, 0.18);

  let lum = 0.50 + (nLarge - 0.5) * 0.55 + (nMed - 0.5) * 0.32 + tileTilt + haloBoost * 0.22 + aura - shadowFactor * 0.58;

  if (lum > 0.84) {
    return { baseColor: "#ffef9e", gleamColor: "#fff8cf", gleamType: 3 };
  } else if (lum > 0.72) {
    return { baseColor: "#fae075", gleamColor: "#ffef9e", gleamType: 2 };
  } else if (lum > 0.62) {
    return { baseColor: "#f2cc52", gleamColor: "#fae075", gleamType: 2 };
  } else if (lum > 0.52) {
    return { baseColor: "#e6b835", gleamColor: "#f2cc52", gleamType: 1 };
  } else if (lum > 0.43) {
    return { baseColor: "#d9a324", gleamColor: "#e6b835", gleamType: 1 };
  } else if (lum > 0.34) {
    return { baseColor: "#cc8f18", gleamColor: "#d9a324", gleamType: 1 };
  } else if (lum > 0.25) {
    return { baseColor: "#bf7e12", gleamColor: "#cc8f18", gleamType: 0 };
  } else if (lum > 0.16) {
    return { baseColor: "#b06d0e", gleamColor: "#bf7e12", gleamType: 0 };
  } else if (lum > 0.08) {
    return { baseColor: "#9e5c0a", gleamColor: "#b06d0e", gleamType: 0 };
  } else if (lum > -0.02) {
    return { baseColor: "#8c4c07", gleamColor: "#9e5c0a", gleamType: 0 };
  } else if (lum > -0.12) {
    return { baseColor: "#7a3e05", gleamColor: "#8c4c07", gleamType: 0 };
  } else if (lum > -0.22) {
    return { baseColor: "#663306", gleamColor: "#7a3e05", gleamType: 0 };
  } else {
    return { baseColor: "#522705", gleamColor: "#663306", gleamType: 0 };
  }
}

function generateHaloGoldTesserae() {
  // 3 concentric contour-hugging courses around the lemons and bay leaf (Byzantine Opus Circumdatum)
  let haloCourses = [10.5, 24.5, 39.0];
  let tileSize = 11.4;
  let exR = tileSize * 0.42 + 1.25;

  // Halo rings around each lemon
  for (let c = 0; c < haloCourses.length; c++) {
    let targetDist = haloCourses[c];
    let haloBoost = (3 - c) * 0.35;

    for (let li = 0; li < lemons.length; li++) {
      let L = lemons[li];
      let steps = 115;
      for (let i = 0; i < steps; i++) {
        let ang = (i / steps) * 360;
        let outer = getRindOuterPoint(L, ang);
        let rad = (ang * Math.PI) / 180;
        let cutU = L.rx * Math.cos(rad);
        let cutV = L.ry * Math.sin(rad);
        let baseU = (outer.u * outer.u) / (L.rx * L.rx) + (outer.v * outer.v) / (L.ry * L.ry) > 1.0 ? outer.u : cutU;
        let baseV = (outer.u * outer.u) / (L.rx * L.rx) + (outer.v * outer.v) / (L.ry * L.ry) > 1.0 ? outer.v : cutV;

        let len = Math.sqrt(baseU * baseU + baseV * baseV);
        let u = baseU + (baseU / len) * targetDist;
        let v = baseV + (baseV / len) * targetDist;
        let pt = toWorld(u, v, L.cx, L.cy, L.angle);

        if (getMinSubjectDistance(pt.x, pt.y) < 6.0) continue;
        if (!canPlaceTile(pt.x, pt.y, exR, 14)) continue;

        let tang = L.angle + ang + 90 + random(-6, 6);
        let sh = getGoldShadowFactor(pt.x, pt.y);
        let cols = pickGoldColors(pt.x, pt.y, haloBoost, sh);

        registerTile({
          x: pt.x + random(-0.6, 0.6),
          y: pt.y + random(-0.6, 0.6),
          w: tileSize * random(0.92, 1.08),
          h: tileSize * random(0.90, 1.08),
          angle: tang,
          baseColor: cols.baseColor,
          gleamColor: cols.gleamColor,
          gleamType: cols.gleamType
        }, exR);
      }
    }

    // Halo courses around the solitary bay leaf
    let leafSteps = 72;
    for (let i = 0; i < leafSteps; i++) {
      let ang = (i / leafSteps) * 360;
      let rad = (ang * Math.PI) / 180;
      let u = (bayLeaf.halfLen + targetDist) * Math.cos(rad);
      let hw = getBayLeafHalfWidth(constrain(u, -bayLeaf.halfLen, bayLeaf.halfLen));
      let v = (hw + targetDist) * Math.sin(rad);
      let pt = toWorld(u, v, bayLeaf.cx, bayLeaf.cy, bayLeaf.angle);

      if (getMinSubjectDistance(pt.x, pt.y) < 5.5) continue;
      if (!canPlaceTile(pt.x, pt.y, exR, 14)) continue;

      let tang = bayLeaf.angle + ang + 90 + random(-6, 6);
      let sh = getGoldShadowFactor(pt.x, pt.y);
      let cols = pickGoldColors(pt.x, pt.y, haloBoost * 0.7, sh);

      registerTile({
        x: pt.x + random(-0.5, 0.5),
        y: pt.y + random(-0.5, 0.5),
        w: tileSize * random(0.92, 1.08),
        h: tileSize * random(0.90, 1.08),
        angle: tang,
        baseColor: cols.baseColor,
        gleamColor: cols.gleamColor,
        gleamType: cols.gleamType
      }, exR);
    }
  }
}

function generateBackgroundGoldTesserae() {
  // Undulating Byzantine gold courses across the entire 1200x1200 field
  let tileW = 13.4;
  let tileH = 13.0;
  let grout = 3.2;
  let stepY = tileH + grout;
  let stepX = tileW + grout;
  let exR = 0.41 * Math.max(tileW, tileH) + 1.25;

  for (let row = 0; row * stepY < 1185; row++) {
    let baseY = 18 + row * stepY;
    let rowShift = (row % 2) * (stepX * 0.45);

    for (let col = 0; col * stepX < 1185; col++) {
      let x = 18 + col * stepX + rowShift + random(-0.9, 0.9);
      // Subtle artisanal wave in the horizontal mortar courses
      let waveY = 7.5 * Math.sin(x * 0.008 + row * 0.12) + 4.0 * (noise(x * 0.005, baseY * 0.005) - 0.5);
      let y = baseY + waveY + random(-0.9, 0.9);

      if (getMinSubjectDistance(x, y) < 6.5) continue;
      if (!canPlaceTile(x, y, exR, 14)) continue;

      let waveSlope = 7.5 * 0.008 * Math.cos(x * 0.008 + row * 0.12);
      let baseAng = (Math.atan2(waveSlope, 1) * 180) / Math.PI;
      // Each gold tessera is slightly tilted for uneven glimmer
      let tiltAng = baseAng + (noise(col * 0.3, row * 0.3) - 0.5) * 14 + random(-5.5, 5.5);

      let sh = getGoldShadowFactor(x, y);
      let cols = pickGoldColors(x, y, 0.0, sh);

      registerTile({
        x: x,
        y: y,
        w: tileW * random(0.91, 1.08),
        h: tileH * random(0.91, 1.08),
        angle: tiltAng,
        baseColor: cols.baseColor,
        gleamColor: cols.gleamColor,
        gleamType: cols.gleamType
      }, exR);
    }
  }
}

// ============================================================================
// RENDERING ENGINE (p5.brush exclusively)
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep roasted umber-charcoal mortar bed
  background("#160e08");
  drawMortarUnderpainting();

  // 2. Render all square marker tesserae in color-batched passes for peak speed & depth
  renderTesseraePasses();

  // 3. Fine hyperreal finishing accents: mortar relief shadows & wet citrus highlights
  drawHyperrealFinishingAccents();

  noLoop();
}

function drawMortarUnderpainting() {
  brush.noStroke();

  // Warm dark bituminous mortar variations across the ground
  brush.wash("#1f140b", 130);
  brush.rect(600, 600, 1180, 1180, "center");

  // Deep espresso mortar bed in the cast shadow zones
  brush.wash("#0d0704", 165);
  for (let i = 0; i < lemons.length; i++) {
    let L = lemons[i];
    brush.circle(L.shadowCx, L.shadowCy, 0.5 * (L.shadowRx + L.shadowRy), 0.15);
  }
  brush.circle(bayLeaf.shadowCx, bayLeaf.shadowCy, 75, 0.2);

  // Warm devotional golden-saffron underglow inside the three cut lemons
  // so the mortar channels between pulp tesserae glow like stained glass
  brush.wash("#452605", 150);
  for (let i = 0; i < lemons.length; i++) {
    let L = lemons[i];
    brush.circle(L.cx, L.cy, 0.48 * (L.rx + L.ry), 0.1);
  }

  // Deep forest-umber mortar bed under the bay leaf
  brush.wash("#0b1a0c", 160);
  brush.circle(bayLeaf.cx, bayLeaf.cy, 65, 0.2);
  brush.noWash();

  // Subtle dry charcoal grain in the mortar crevices
  brush.set("charcoal", "#0e0804", 0.5);
  for (let i = 0; i < 45; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let ang = random(360);
    let len = random(60, 180);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }
}

function renderTesseraePasses() {
  // Group strokes into color buckets for Pass 1 (Lower/Base Half of Tile),
  // Pass 2 (Upper/Lit Half of Tile), and Pass 3 (Facet Glint / Specular Juice Bead / Rind Pit)
  let pass1Buckets = {};
  let pass2Buckets = {};
  let pass3Buckets = {};

  for (let i = 0; i < tiles.length; i++) {
    let t = tiles[i];
    let rad = (t.angle * Math.PI) / 180;
    let ux = Math.cos(rad);
    let uy = Math.sin(rad);
    let vx = -uy;
    let vy = ux;

    // Two slightly overlapping parallel chisel-marker strokes form a crisp square/rectangular dab
    let sw = Math.min(t.h * 0.56, t.w * 0.78);
    let halfL = Math.max(0.45, (t.w - sw * 0.94) * 0.5);
    let dy = t.h * 0.21;

    // Lower half-tile stroke (base color)
    let x1L = t.x + vx * dy - ux * halfL;
    let y1L = t.y + vy * dy - uy * halfL;
    let x2L = t.x + vx * dy + ux * halfL;
    let y2L = t.y + vy * dy + uy * halfL;

    if (!pass1Buckets[t.baseColor]) pass1Buckets[t.baseColor] = [];
    pass1Buckets[t.baseColor].push({ x1: x1L, y1: y1L, x2: x2L, y2: y2L, sw: sw });

    // Upper half-tile stroke (gleam/variation color)
    let topColor = t.gleamType === 4 ? t.baseColor : t.gleamColor;
    let x1U = t.x - vx * dy - ux * halfL;
    let y1U = t.y - vy * dy - uy * halfL;
    let x2U = t.x - vx * dy + ux * halfL;
    let y2U = t.y - vy * dy + uy * halfL;

    if (!pass2Buckets[topColor]) pass2Buckets[topColor] = [];
    pass2Buckets[topColor].push({ x1: x1U, y1: y1U, x2: x2U, y2: y2U, sw: sw });

    // Optional Pass 3: Inner bevel gleam, specular juice bead core, or concave rind pit
    if (t.gleamType > 0) {
      let accColor = t.gleamColor;
      let accSw = sw * 0.58;
      let accHalfL = halfL * 0.68;
      let offV = 0;

      if (t.gleamType === 1) {
        // Upper bevel glint
        offV = -t.h * 0.18;
      } else if (t.gleamType === 2) {
        // Luminous inner core
        offV = -t.h * 0.05;
        accSw = sw * 0.65;
      } else if (t.gleamType === 3) {
        // Dazzling specular juice bead or pale-gold flash
        offV = -t.h * 0.10;
        accSw = sw * 0.72;
        accHalfL = halfL * 0.75;
      } else if (t.gleamType === 4) {
        // Concave rind oil-gland pit: bright highlight catches the lower-right lip (+offV)
        offV = +t.h * 0.22;
        accSw = sw * 0.52;
        accHalfL = halfL * 0.65;
      }

      let ax1 = t.x + vx * offV - ux * accHalfL;
      let ay1 = t.y + vy * offV - uy * accHalfL;
      let ax2 = t.x + vx * offV + ux * accHalfL;
      let ay2 = t.y + vy * offV + uy * accHalfL;

      if (!pass3Buckets[accColor]) pass3Buckets[accColor] = [];
      pass3Buckets[accColor].push({ x1: ax1, y1: ay1, x2: ax2, y2: ay2, sw: accSw });
    }
  }

  // Execute Pass 1
  let p1Colors = Object.keys(pass1Buckets);
  for (let c = 0; c < p1Colors.length; c++) {
    let col = p1Colors[c];
    let list = pass1Buckets[col];
    brush.set("smalti", col, 1);
    for (let i = 0; i < list.length; i++) {
      let seg = list[i];
      brush.strokeWeight(seg.sw);
      brush.line(seg.x1, seg.y1, seg.x2, seg.y2);
    }
  }

  // Execute Pass 2
  let p2Colors = Object.keys(pass2Buckets);
  for (let c = 0; c < p2Colors.length; c++) {
    let col = p2Colors[c];
    let list = pass2Buckets[col];
    brush.set("smalti", col, 1);
    for (let i = 0; i < list.length; i++) {
      let seg = list[i];
      brush.strokeWeight(seg.sw);
      brush.line(seg.x1, seg.y1, seg.x2, seg.y2);
    }
  }

  // Execute Pass 3 (High-opacity smalti gleam & specular highlights)
  let p3Colors = Object.keys(pass3Buckets);
  for (let c = 0; c < p3Colors.length; c++) {
    let col = p3Colors[c];
    let list = pass3Buckets[col];
    brush.set("smalti_gleam", col, 1);
    for (let i = 0; i < list.length; i++) {
      let seg = list[i];
      brush.strokeWeight(seg.sw);
      brush.line(seg.x1, seg.y1, seg.x2, seg.y2);
    }
  }
}

function drawHyperrealFinishingAccents() {
  // 1. Crisp mortar relief shadow lines along the lower-right edge of selected tesserae
  // to emphasize physical tile depth and dark grout definition
  brush.set("rotring", "#120a04", 0.28);
  for (let i = 0; i < tiles.length; i += 2) {
    let t = tiles[i];
    let rad = (t.angle * Math.PI) / 180;
    let ux = Math.cos(rad);
    let uy = Math.sin(rad);
    let vx = -uy;
    let vy = ux;
    let hw = t.w * 0.46;
    let hh = t.h * 0.48;
    // Lower edge mortar crease
    let x1 = t.x + vx * hh - ux * hw;
    let y1 = t.y + vy * hh - uy * hw;
    let x2 = t.x + vx * hh + ux * hw;
    let y2 = t.y + vy * hh + uy * hw;
    brush.line(x1, y1, x2, y2);
  }

  // 2. Pinpoint liquid specular glints on the juice beads, pips, and shiny gold tesserae
  brush.set("rotring", "#fffef5", 0.36);
  for (let i = 0; i < tiles.length; i++) {
    let t = tiles[i];
    if (t.gleamType === 3) {
      let rad = (t.angle * Math.PI) / 180;
      let ux = Math.cos(rad);
      let uy = Math.sin(rad);
      let hw = t.w * 0.26;
      brush.line(t.x - ux * hw, t.y - uy * hw, t.x + ux * hw, t.y + uy * hw);
    }
  }

  // 3. Delicate warm graphite/colored-pencil surface veining along the translucent septa
  brush.set("cpencil", "#fcf6e3", 0.25);
  for (let li = 0; li < lemons.length; li++) {
    let L = lemons[li];
    for (let s = 0; s < L.septaAngles.length; s++) {
      let baseAng = L.septaAngles[s];
      let curveAmp = L.septaCurve[s];
      let r1 = L.coreRad + 0.05;
      let r2 = L.pithInner - 0.05;
      let a1 = ((baseAng + curveAmp * 0.3) * Math.PI) / 180;
      let a2 = ((baseAng + curveAmp * 0.7) * Math.PI) / 180;
      let p1 = toWorld(L.rx * r1 * Math.cos(a1), L.ry * r1 * Math.sin(a1), L.cx, L.cy, L.angle);
      let p2 = toWorld(L.rx * r2 * Math.cos(a2), L.ry * r2 * Math.sin(a2), L.cx, L.cy, L.angle);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }
}

const SEED = 4289;

// Rotation of the tray grid:
// Local +v runs diagonally from top-left to bottom-right (+35 deg on screen),
// so macarons nestled along +v have their domes facing top-left (toward the light)
// and their ruffled feet, bulging filling, and low soft shadows facing bottom-right.
// Local +u runs perpendicularly across the stripes (-55 deg on screen).
const ROT_DEG = -55;
const COS_R = Math.cos((ROT_DEG * Math.PI) / 180);
const SIN_R = Math.sin((ROT_DEG * Math.PI) / 180);

