function toScreen(u, v) {
  return [
    600 + u * COS_R - v * SIN_R,
    600 + u * SIN_R + v * COS_R
  ];
}

function isOnCanvas(u, v, margin = 85) {
  const [x, y] = toScreen(u, v);
  return x >= -margin && x <= 1200 + margin && y >= -margin && y <= 1200 + margin;
}

function macPt(mac, lu, lv) {
  const u = mac.u + lu * mac.cosA - lv * mac.sinA;
  const v = mac.v + lu * mac.sinA + lv * mac.cosA;
  return [
    600 + u * COS_R - v * SIN_R,
    600 + u * SIN_R + v * COS_R
  ];
}

function drawClosedShape(pts, curvature = 0.35) {
  if (pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f3ead8");
  brush.noField();

  // -------------------------------------------------------------------------
  // 1. DEFINE DIAGONAL PATISSERIE TRAY ROWS & EMPTY TRAY TRACKS
  // -------------------------------------------------------------------------
  const rowDefs = [
    { id: 0,  u: -790, flav: "violet",    pleatLeft: true },
    { id: 1,  u: -676, flav: "lemon",     pleatLeft: true },
    { id: 2,  u: -562, flav: "raspberry", pleatLeft: true },
    { id: 3,  u: -458, flav: "raspberry", pleatLeft: false }, // Twin band
    { id: 4,  u: -344, flav: "pistachio", pleatLeft: true },
    { id: 5,  u: -240, flav: "pistachio", pleatLeft: false }, // Twin band
    { id: 6,  u: -126, flav: "rose",      pleatLeft: true },
    // Notice longitudinal empty track at u = -12 (Row 7 mostly harvested!)
    { id: 7,  u: -12,  flav: "coffee",    pleatLeft: true, mostlyEmpty: true },
    { id: 8,  u: 102,  flav: "coffee",    pleatLeft: true },
    { id: 9,  u: 216,  flav: "lemon",     pleatLeft: true },
    { id: 10, u: 330,  flav: "violet",    pleatLeft: true },
    { id: 11, u: 434,  flav: "violet",    pleatLeft: false }, // Twin band
    { id: 12, u: 548,  flav: "rose",      pleatLeft: true },
    { id: 13, u: 662,  flav: "pistachio", pleatLeft: true },
    { id: 14, u: 776,  flav: "raspberry", pleatLeft: true }
  ];

  // Two perpendicular cross-tracks of empty tray slicing across all diagonal bands
  // like canals/tracks across Dutch bulb fields:
  // Cross-Track A: v in [-252, -162]
  // Cross-Track B: v in [ 178,  268]
  const vBlocks = [
    { name: "top",    vStart: -840, vEnd: -280 },
    { name: "middle", vStart: -130, vEnd:  146 },
    { name: "bottom", vStart:  298, vEnd:  850 }
  ];
  const stepV = 56;

  // Determine whether a specific slot in a block is empty (harvested/sold track)
  function isSlotEmpty(rowId, blockName, slotIdx, totalSlots) {
    // Row 7 is a longitudinal empty track across the top and middle blocks
    if (rowId === 7) {
      if (blockName === "top" || blockName === "middle") return true;
      if (blockName === "bottom" && slotIdx < 3) return true;
    }
    // Partial empty tracks in other stripes for authentic patisserie tray feel
    if (rowId === 2 && blockName === "middle" && slotIdx < 3) return true;
    if (rowId === 5 && blockName === "top" && slotIdx >= totalSlots - 3) return true;
    if (rowId === 9 && blockName === "middle" && slotIdx >= totalSlots - 2) return true;
    if (rowId === 11 && blockName === "bottom" && slotIdx >= 1 && slotIdx <= 3) return true;
    return false;
  }

  const macarons = [];
  const emptySlots = [];
  const bandSegments = [];

  for (let r = 0; r < rowDefs.length; r++) {
    const row = rowDefs[r];
    const flav = FLAVOURS[row.flav];

    for (let b = 0; b < vBlocks.length; b++) {
      const blk = vBlocks[b];
      const totalSlots = Math.floor((blk.vEnd - blk.vStart) / stepV) + 1;
      let segStartV = null;
      let prevV = null;

      for (let s = 0; s < totalSlots; s++) {
        const vBase = blk.vStart + s * stepV;
        const empty = isSlotEmpty(row.id, blk.name, s, totalSlots);

        if (!isOnCanvas(row.u, vBase, 95)) {
          if (segStartV !== null && prevV !== null) {
            bandSegments.push({ u: row.u, v1: segStartV, v2: prevV, flav });
            segStartV = null;
          }
          continue;
        }

        if (empty) {
          emptySlots.push({
            u: row.u + random(-2, 2),
            v: vBase + random(-2, 2),
            flav,
            rowId: row.id
          });
          if (segStartV !== null && prevV !== null) {
            bandSegments.push({ u: row.u, v1: segStartV, v2: prevV, flav });
            segStartV = null;
          }
        } else {
          if (segStartV === null) segStartV = vBase;
          prevV = vBase;

          // Slight natural variation per macaron
          const nextEmpty = (s === totalSlots - 1) || isSlotEmpty(row.id, blk.name, s + 1, totalSlots);
          const ang = random(-2.4, 2.4) + (nextEmpty ? random(-2.5, 2.5) : 0);
          const rad = (ang * Math.PI) / 180;

          macarons.push({
            rowId: row.id,
            blockIdx: b,
            slotIdx: s,
            flavName: row.flav,
            flav,
            u: row.u + random(-1.6, 1.6),
            v: vBase + random(-1.3, 1.3),
            rx: 45.5 + random(-1.4, 1.4),
            ry: (nextEmpty ? 29.5 : 27.5) + random(-1.0, 1.0),
            ang,
            cosA: Math.cos(rad),
            sinA: Math.sin(rad),
            seed: random(1000),
            hasBigCrack: random() < 0.42,
            crackSide: random() < 0.5 ? -1 : 1
          });
        }
      }
      if (segStartV !== null && prevV !== null) {
        bandSegments.push({ u: row.u, v1: segStartV, v2: prevV, flav });
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. PARCHMENT LINER, PLEATED CHANNELS & EMPTY TRAY TRACKS
  // -------------------------------------------------------------------------
  brush.noStroke();
  // Warm parchment paper variation washes
  const parchmentTones = ["#eadbc3", "#e2cfb2", "#f7f0e2"];
  for (let i = 0; i < 3; i++) {
    brush.fill(parchmentTones[i], 42);
    brush.fillBleed(0.25, "out");
    brush.fillTexture(0.55, 0.2);
    for (let k = 0; k < 4; k++) {
      const pu = random(-700, 700);
      const pv = random(-700, 700);
      const [px, py] = toScreen(pu, pv);
      if (px > -150 && px < 1350 && py > -150 && py < 1350) {
        brush.circle(px, py, random(180, 320), 0.3);
      }
    }
  }

  // Recessed trough shadow washes along every row channel
  brush.noStroke();
  brush.fill("#d4c0a1", 48);
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.45, 0.2);
  for (let r = 0; r < rowDefs.length; r++) {
    const ru = rowDefs[r].u;
    for (let b = 0; b < vBlocks.length; b++) {
      const blk = vBlocks[b];
      const p1 = toScreen(ru - 42, blk.vStart - 34);
      const p2 = toScreen(ru + 42, blk.vStart - 34);
      const p3 = toScreen(ru + 42, blk.vEnd + 32);
      const p4 = toScreen(ru - 42, blk.vEnd + 32);
      drawClosedShape([p1, p2, p3, p4], 0.05);
    }
  }

  // Faint butter/sugar rings in empty macaron slots (harvested tracks)
  brush.noStroke();
  brush.fill("#c9b08c", 52);
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.5, 0.35);
  for (let i = 0; i < emptySlots.length; i++) {
    const es = emptySlots[i];
    const pts = [];
    for (let a = 0; a < 12; a++) {
      const ang = (a / 12) * Math.PI * 2;
      pts.push(toScreen(es.u + Math.cos(ang) * 38, es.v + 8 + Math.sin(ang) * 19));
    }
    drawClosedShape(pts, 0.35);
  }

  // Tiny filling smudges in some empty slots where tongs lifted a macaron
  for (let i = 0; i < emptySlots.length; i++) {
    const es = emptySlots[i];
    if (random() < 0.65) {
      brush.noStroke();
      brush.fill(es.flav.fillBase, 65);
      brush.fillBleed(0.15, "out");
      const pts = [];
      for (let a = 0; a < 8; a++) {
        const ang = (a / 8) * Math.PI * 2;
        pts.push(toScreen(es.u + random(-8, 8) + Math.cos(ang) * 14, es.v + 12 + Math.sin(ang) * 6));
      }
      drawClosedShape(pts, 0.4);
    }
  }

  // Perpendicular "Tracks of Empty Tray" (Cross-Track A & Cross-Track B)
  // Rendered as exposed brushed-pewter patisserie tray dividers & folded parchment seams
  const crossTracks = [
    { v1: -254, v2: -158 },
    { v1:  176, v2:  272 }
  ];
  brush.noStroke();
  for (let ct of crossTracks) {
    const vMid1 = ct.v1 + 22;
    const vMid2 = ct.v2 - 22;
    // Exposed metallic tray channel between parchment sheets
    brush.fill("#c2beb6", 110);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.35, 0.25);
    drawClosedShape([
      toScreen(-920, vMid1),
      toScreen( 920, vMid1),
      toScreen( 920, vMid2),
      toScreen(-920, vMid2)
    ], 0.02);

    // Recessed shadow just under the parchment lip
    brush.fill("#8f8474", 75);
    drawClosedShape([
      toScreen(-920, vMid1),
      toScreen( 920, vMid1),
      toScreen( 920, vMid1 + 12),
      toScreen(-920, vMid1 + 12)
    ], 0.02);
  }
  brush.noFill();

  // Crisp parchment paper fold edges & metallic divider ridges in the cross-tracks
  for (let ct of crossTracks) {
    const vMid1 = ct.v1 + 22;
    const vMid2 = ct.v2 - 22;

    // Brushed metal grain lines along the empty tray track
    brush.set("2H", "#969188", 0.55);
    for (let k = -880; k <= 880; k += 45) {
      const pA = toScreen(k, vMid1 + 6);
      const pB = toScreen(k + 32, vMid1 + 6);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
      const pC = toScreen(k, vMid2 - 6);
      const pD = toScreen(k + 32, vMid2 - 6);
      brush.line(pC[0], pC[1], pD[0], pD[1]);
    }

    // Center tray divider seam + specular highlight
    const s1 = toScreen(-900, (ct.v1 + ct.v2) * 0.5);
    const s2 = toScreen( 900, (ct.v1 + ct.v2) * 0.5);
    brush.set("rotring", "#635d55", 0.7);
    brush.line(s1[0], s1[1], s2[0], s2[1]);

    const h1 = toScreen(-900, (ct.v1 + ct.v2) * 0.5 + 3);
    const h2 = toScreen( 900, (ct.v1 + ct.v2) * 0.5 + 3);
    brush.set("cpencil", "#f7f5f0", 1.1);
    brush.line(h1[0], h1[1], h2[0], h2[1]);

    // Folded parchment edges bordering the cross-tracks
    for (let vEdge of [vMid1, vMid2]) {
      const e1 = toScreen(-900, vEdge);
      const e2 = toScreen( 900, vEdge);
      brush.set("HB", "#8c7a62", 0.75);
      brush.line(e1[0], e1[1], e2[0], e2[1]);

      const eh1 = toScreen(-900, vEdge - 2.5);
      const eh2 = toScreen( 900, vEdge - 2.5);
      brush.set("cpencil", "#fffdf9", 1.2);
      brush.line(eh1[0], eh1[1], eh2[0], eh2[1]);
    }
  }

  // Longitudinal pleated parchment ridges between the diagonal rows
  for (let r = 0; r < rowDefs.length - 1; r++) {
    const uMid = (rowDefs[r].u + rowDefs[r + 1].u) * 0.5;
    const isTwin = !rowDefs[r + 1].pleatLeft;

    for (let b = 0; b < vBlocks.length; b++) {
      const blk = vBlocks[b];
      const v1 = blk.vStart - 34;
      const v2 = blk.vEnd + 34;

      // Shadow flank of parchment pleat
      const ps1 = toScreen(uMid + 3, v1);
      const ps2 = toScreen(uMid + 3, v2);
      brush.set("2B", "#c7b293", isTwin ? 0.65 : 1.0);
      brush.line(ps1[0], ps1[1], ps2[0], ps2[1]);

      // Sharp fold crease
      const pc1 = toScreen(uMid, v1);
      const pc2 = toScreen(uMid, v2);
      brush.set("HB", "#9e886b", isTwin ? 0.45 : 0.65);
      brush.line(pc1[0], pc1[1], pc2[0], pc2[1]);

      // Bright paper ridge highlight
      const ph1 = toScreen(uMid - 2.2, v1);
      const ph2 = toScreen(uMid - 2.2, v2);
      brush.set("cpencil", "#fffdf7", isTwin ? 0.8 : 1.25);
      brush.line(ph1[0], ph1[1], ph2[0], ph2[1]);

      // Subtle diagonal crinkles along the parchment fold
      if (!isTwin) {
        brush.set("2H", "#b59f80", 0.4);
        for (let vv = v1 + 25; vv < v2 - 25; vv += 48) {
          if (isOnCanvas(uMid, vv, 40)) {
            const c1 = toScreen(uMid, vv);
            const c2 = toScreen(uMid + random(-9, 9), vv + random(8, 16));
            brush.line(c1[0], c1[1], c2[0], c2[1]);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 3. CLEAN WATERCOLOUR FILLS FOR EACH BAND & LOW SOFT SHADOWS (BATCHED)
  // -------------------------------------------------------------------------
  brush.noStroke();

  // Pass 3A: Clean watercolour band fills along each contiguous stripe segment
  const flavKeys = Object.keys(FLAVOURS);
  for (let fk of flavKeys) {
    const flav = FLAVOURS[fk];
    brush.fill(flav.bandWash, 58);
    brush.fillBleed(0.12, "out");
    brush.fillTexture(0.45, 0.25);

    for (let seg of bandSegments) {
      if (seg.flav.name !== fk) continue;
      const u = seg.u;
      const v1 = seg.v1 - 32;
      const v2 = seg.v2 + 28;
      const pts = [
        toScreen(u - 44, v1 + 8),
        toScreen(u,      v1 - 4),
        toScreen(u + 44, v1 + 8),
        toScreen(u + 44, v2 - 6),
        toScreen(u,      v2 + 6),
        toScreen(u - 44, v2 - 6)
      ];
      drawClosedShape(pts, 0.25);
    }
  }

  // Pass 3B: Low soft cast shadow beneath every macaron (batched in one shadow colour)
  brush.fill("#2b1f1c", 82);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.42, 0.2);
  for (let i = 0; i < macarons.length; i++) {
    const mac = macarons[i];
    const pts = [];
    const n = 12;
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2;
      const lu = 4 + mac.rx * 1.03 * Math.cos(a);
      const lv = 22 + 17.5 * Math.sin(a);
      pts.push(macPt(mac, lu, lv));
    }
    drawClosedShape(pts, 0.38);
  }

  // Tighter ambient occlusion shadow directly under the lower shell
  brush.fill("#1c1210", 92);
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.35, 0.2);
  for (let i = 0; i < macarons.length; i++) {
    const mac = macarons[i];
    const pts = [];
    const n = 10;
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2;
      const lu = 2 + mac.rx * 0.86 * Math.cos(a);
      const lv = 23 + 9.5 * Math.sin(a);
      pts.push(macPt(mac, lu, lv));
    }
    drawClosedShape(pts, 0.35);
  }

  // Pass 3C: Batched watercolour fills for every macaron's bulging filling & shell dome
  for (let fk of flavKeys) {
    const flav = FLAVOURS[fk];
    const flavMacs = macarons.filter((m) => m.flavName === fk);

    // 1) Bulging filling watercolour base
    brush.fill(flav.fillBase, 190);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.4, 0.3);
    for (let mac of flavMacs) {
      const pts = [];
      const steps = 7;
      for (let s = 0; s <= steps; s++) {
        const t = -1 + (2 * s) / steps;
        const lu = t * mac.rx * 0.94;
        const lv = 5 + 9 * Math.cos(t * Math.PI * 0.5);
        pts.push(macPt(mac, lu, lv));
      }
      for (let s = steps; s >= 0; s--) {
        const t = -1 + (2 * s) / steps;
        const lu = t * mac.rx * 0.94;
        const lv = 11 + 14.5 * Math.cos(t * Math.PI * 0.5);
        pts.push(macPt(mac, lu, lv));
      }
      drawClosedShape(pts, 0.35);
    }

    // 2) Main upper shell dome watercolour fill
    brush.fill(flav.shellBase, 180);
    brush.fillBleed(0.05, "in");
    brush.fillTexture(0.48, 0.36);
    for (let mac of flavMacs) {
      const pts = [];
      const n = 14;
      for (let k = 0; k < n; k++) {
        const a = (k / n) * Math.PI * 2;
        const lu = mac.rx * Math.cos(a);
        const sinA = Math.sin(a);
        // Slightly fuller upper crown, slightly flatter front rim where foot attaches
        const lv = -7 + (sinA < 0 ? mac.ry : mac.ry * 0.62) * sinA;
        pts.push(macPt(mac, lu, lv));
      }
      drawClosedShape(pts, 0.38);
    }

    // 3) Lower-right dome shading watercolour glaze
    brush.fill(flav.shellShade, 115);
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.42, 0.25);
    for (let mac of flavMacs) {
      const pts = [];
      const steps = 7;
      // Outer lower-right rim
      for (let s = 0; s <= steps; s++) {
        const a = -0.25 + (s / steps) * (Math.PI + 0.1);
        const lu = mac.rx * Math.cos(a);
        const sinA = Math.sin(a);
        const lv = -7 + (sinA < 0 ? mac.ry : mac.ry * 0.62) * sinA;
        pts.push(macPt(mac, lu, lv));
      }
      // Inner crescent boundary
      for (let s = steps; s >= 0; s--) {
        const a = -0.1 + (s / steps) * (Math.PI - 0.2);
        const lu = mac.rx * 0.72 * Math.cos(a) + 5;
        const lv = -9 + mac.ry * 0.36 * Math.sin(a);
        pts.push(macPt(mac, lu, lv));
      }
      drawClosedShape(pts, 0.35);
    }

    // 4) Upper-left crown highlight watercolour wash
    brush.fill(flav.shellHighlight, 130);
    brush.fillBleed(0.1, "out");
    brush.fillTexture(0.3, 0.15);
    for (let mac of flavMacs) {
      const pts = [];
      const n = 10;
      for (let k = 0; k < n; k++) {
        const a = (k / n) * Math.PI * 2;
        const lu = -mac.rx * 0.22 + mac.rx * 0.50 * Math.cos(a);
        const lv = -15.5 + mac.ry * 0.40 * Math.sin(a);
        pts.push(macPt(mac, lu, lv));
      }
      drawClosedShape(pts, 0.38);
    }
  }
  brush.noFill();

  // -------------------------------------------------------------------------
  // 4. BACK-TO-FRONT HYPERREAL SHARPENING OF EVERY SHELL
  // -------------------------------------------------------------------------
  // Sort macarons from largest v (bottom-right) to smallest v (top-left) so each
  // macaron's lower edge & filling cleanly overlap the upper crown of the one behind it.
  const sortedMacs = macarons.slice().sort((a, b) => b.v - a.v);

  for (let i = 0; i < sortedMacs.length; i++) {
    const mac = sortedMacs[i];
    const flav = mac.flav;
    const rx = mac.rx;
    const ry = mac.ry;

    // --- 4.1 LOWER SHELL RIM & LOWER RUFFLED FOOT ---
    brush.noStroke();
    brush.wash(flav.shellShade, 210);
    const botShellPts = [];
    const bSteps = 7;
    for (let s = 0; s <= bSteps; s++) {
      const t = -1 + (2 * s) / bSteps;
      botShellPts.push(macPt(mac, t * rx * 0.88, 12 + 11 * Math.cos(t * Math.PI * 0.5)));
    }
    for (let s = bSteps; s >= 0; s--) {
      const t = -1 + (2 * s) / bSteps;
      botShellPts.push(macPt(mac, t * rx * 0.85, 15 + 14.5 * Math.cos(t * Math.PI * 0.5)));
    }
    drawClosedShape(botShellPts, 0.35);
    brush.noWash();

    // Lower foot frothy edge & dark base contour
    const botFootCurve = [];
    const botEdgeCurve = [];
    for (let s = 0; s <= 6; s++) {
      const t = -0.84 + (1.68 * s) / 6;
      botFootCurve.push(macPt(mac, t * rx, 13.5 + 12 * Math.cos(t * Math.PI * 0.5)));
      botEdgeCurve.push(macPt(mac, t * rx * 0.96, 15.5 + 14 * Math.cos(t * Math.PI * 0.5)));
    }
    brush.set("cpencil", flav.footBase, 1.3);
    brush.spline(botFootCurve, 0.4);
    brush.set("2B", flav.shellDeep, 0.85);
    brush.spline(botEdgeCurve, 0.4);

    // --- 4.2 THE BULGING FILLING (OPAQUE BODY, ROUNDED HIGHLIGHT & TEXTURES) ---
    brush.noStroke();
    brush.wash(flav.fillMid, 205);
    const fillBodyPts = [];
    for (let s = 0; s <= bSteps; s++) {
      const t = -1 + (2 * s) / bSteps;
      fillBodyPts.push(macPt(mac, t * rx * 0.92, 6 + 9.5 * Math.cos(t * Math.PI * 0.5)));
    }
    for (let s = bSteps; s >= 0; s--) {
      const t = -1 + (2 * s) / bSteps;
      fillBodyPts.push(macPt(mac, t * rx * 0.92, 10.5 + 14 * Math.cos(t * Math.PI * 0.5)));
    }
    drawClosedShape(fillBodyPts, 0.35);
    brush.noWash();

    // Plump lower shadow of the bulging filling
    const fillBotShadow = [];
    for (let s = 0; s <= 6; s++) {
      const t = -0.88 + (1.76 * s) / 6;
      fillBotShadow.push(macPt(mac, t * rx, 10.5 + 14 * Math.cos(t * Math.PI * 0.5)));
    }
    brush.set("2B", flav.fillShadow, 0.95);
    brush.spline(fillBotShadow, 0.4);

    // Cylindrical specular highlight band along the equator of the bulging filling
    const fillHighlightPts = [];
    for (let s = 0; s <= 6; s++) {
      const t = -0.76 + (1.52 * s) / 6;
      fillHighlightPts.push(macPt(mac, t * rx, 8.2 + 11.8 * Math.cos(t * Math.PI * 0.5)));
    }
    brush.set("marker", flav.fillHighlight, 1.35);
    brush.spline(fillHighlightPts, 0.4);

    // Crisp wet/creamy glint on the lit left-center bulge of the filling
    const glintPts = [];
    for (let s = 0; s <= 4; s++) {
      const t = -0.52 + (0.76 * s) / 4;
      glintPts.push(macPt(mac, t * rx, 8.0 + 11.5 * Math.cos(t * Math.PI * 0.5)));
    }
    brush.set("cpencil", flav.shellSpec, 1.15);
    brush.spline(glintPts, 0.4);

    // Flavour-specific hyperreal filling inclusions
    if (mac.flavName === "raspberry") {
      // Golden raspberry seeds & ruby jam glints
      for (let k = -2; k <= 2; k++) {
        const t = k * 0.28 + random(-0.06, 0.06);
        const lu = t * rx;
        const lv = 8.2 + 11.8 * Math.cos(t * Math.PI * 0.5) + random(-1.2, 1.2);
        const p1 = macPt(mac, lu - 1.4, lv - 0.5);
        const p2 = macPt(mac, lu + 1.4, lv + 0.5);
        brush.set("rotring", "#4a0112", 0.9);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
        brush.set("rotring", "#f5c756", 0.65);
        brush.line(p1[0] - 0.5, p1[1] - 0.5, p2[0] - 0.5, p2[1] - 0.5);
      }
    } else if (mac.flavName === "pistachio") {
      // Crushed roasted & green pistachio nibs on the filling
      for (let k = -2; k <= 2; k++) {
        const t = k * 0.3 + random(-0.07, 0.07);
        const lu = t * rx;
        const lv = 8.4 + 11.6 * Math.cos(t * Math.PI * 0.5) + random(-1.2, 1.2);
        const p1 = macPt(mac, lu - 1.6, lv);
        const p2 = macPt(mac, lu + 1.6, lv + 0.6);
        brush.set("rotring", k % 2 === 0 ? "#c8f77c" : "#214207", 0.75);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    } else if (mac.flavName === "lemon") {
      // Sharp lemon curd mirror-gloss & zest flecks
      brush.set("rotring", "#fffff2", 0.7);
      brush.spline(glintPts, 0.4);
      for (let k = -1; k <= 2; k++) {
        const t = k * 0.32 + random(-0.08, 0.08);
        const p1 = macPt(mac, t * rx, 8.5 + 11.5 * Math.cos(t * Math.PI * 0.5));
        const p2 = macPt(mac, t * rx + 2.0, 9.0 + 11.5 * Math.cos(t * Math.PI * 0.5));
        brush.set("rotring", "#cc5800", 0.6);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    } else if (mac.flavName === "violet") {
      // Candied violet crystal glints
      for (let k = -1; k <= 1; k++) {
        const t = k * 0.34 + random(-0.08, 0.08);
        const p1 = macPt(mac, t * rx - 1.0, 8.5 + 11.5 * Math.cos(t * Math.PI * 0.5));
        const p2 = macPt(mac, t * rx + 1.2, 8.5 + 11.5 * Math.cos(t * Math.PI * 0.5));
        brush.set("rotring", "#f6e8ff", 0.75);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    } else if (mac.flavName === "coffee") {
      // Glossy dark espresso mirror streak
      brush.set("rotring", "#fff0e3", 0.65);
      brush.spline(glintPts, 0.4);
    } else if (mac.flavName === "rose") {
      // Delicate rose buttercream ridges & dried rose-petal fleck
      const p1 = macPt(mac, -rx * 0.15, 19.5);
      const p2 = macPt(mac, -rx * 0.15 + 2.5, 20.2);
      brush.set("rotring", "#9e113d", 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // --- 4.3 THE UPPER RUFFLED FOOT (PIÉD / COLLERETTE) ---
    // Scalloped, frothy collar flaring slightly wider than the shell dome (rx * 1.03)
    const footPts = [];
    const lobeCount = 13;
    // Top boundary of the ruffled foot (tucked into the base of the smooth dome)
    for (let s = 0; s <= 8; s++) {
      const t = -1 + (2 * s) / 8;
      const lu = t * rx * 1.01;
      const lv = -4.5 + 12.5 * Math.cos(t * Math.PI * 0.5);
      footPts.push(macPt(mac, lu, lv));
    }
    // Scalloped lower boundary overhanging the bulging filling
    const footBottomPts = [];
    for (let s = lobeCount; s >= 0; s--) {
      const t = -1 + (2 * s) / lobeCount;
      const lu = t * rx * 1.035;
      const bump = 1.8 * Math.sin(s * 3.7 + mac.seed) + (s % 2 === 0 ? 1.4 : -0.8);
      const lv = -0.5 + 14.2 * Math.cos(t * Math.PI * 0.5) + bump;
      const pt = macPt(mac, lu, lv);
      footPts.push(pt);
      footBottomPts.push(pt);
    }

    brush.noStroke();
    brush.wash(flav.footBase, 230);
    drawClosedShape(footPts, 0.35);
    brush.noWash();

    // Deep occlusion shadow directly beneath the overhanging ruffled foot
    brush.set("2B", flav.fillShadow, 1.15);
    brush.spline(footBottomPts, 0.35);
    brush.set("rotring", flav.fillShadow, 0.55);
    brush.spline(footBottomPts, 0.35);

    // Frothy meringue foam cells, air-pocket pores & highlights inside the ruffled foot
    for (let s = 1; s < lobeCount; s++) {
      const t = -0.94 + (1.88 * s) / lobeCount;
      const lu = t * rx * 1.01;
      const lvMid = -2.2 + 13.0 * Math.cos(t * Math.PI * 0.5);

      // Frothy puff highlight on the upper-left side of each ruffle lobe
      const hp1 = macPt(mac, lu - 1.8, lvMid - 0.8);
      const hp2 = macPt(mac, lu + 1.2, lvMid + 0.5);
      brush.set("cpencil", s < lobeCount * 0.65 ? flav.shellHighlight : flav.footBase, 1.15);
      brush.line(hp1[0], hp1[1], hp2[0], hp2[1]);

      // Dark baked meringue pore / cavity dot inside the ruffled foot
      const dp1 = macPt(mac, lu + random(-1.2, 1.2), lvMid + 1.5 + random(-0.8, 0.8));
      const dp2 = macPt(mac, lu + random(-1.2, 1.2) + 1.3, lvMid + 2.1 + random(-0.8, 0.8));
      brush.set("rotring", flav.footDark, 0.65);
      brush.line(dp1[0], dp1[1], dp2[0], dp2[1]);

      // Secondary upper pore tick
      if (s % 2 === 0) {
        const up1 = macPt(mac, lu - 1.0, lvMid - 1.2);
        const up2 = macPt(mac, lu + 0.4, lvMid - 0.9);
        brush.set("rotring", flav.shellDeep, 0.48);
        brush.line(up1[0], up1[1], up2[0], up2[1]);
      }
    }

    // Indented "skirt seam" where the smooth upper shell dome meets the ruffled foot
    const seamPts = [];
    for (let s = 0; s <= 8; s++) {
      const t = -0.96 + (1.92 * s) / 8;
      seamPts.push(macPt(mac, t * rx, -4.5 + 12.8 * Math.cos(t * Math.PI * 0.5)));
    }
    brush.set("rotring", flav.shellShade, 0.48);
    brush.spline(seamPts, 0.4);

    // --- 4.4 SHARPENING THE UPPER SHELL DOME ---
    // Rich translucent wash over the upper dome so it cleanly occludes any shadow behind it
    brush.noStroke();
    brush.wash(flav.shellBase, 92);
    const domePts = [];
    const dCount = 14;
    for (let k = 0; k < dCount; k++) {
      const a = (k / dCount) * Math.PI * 2;
      const lu = rx * Math.cos(a);
      const sinA = Math.sin(a);
      const lv = -7 + (sinA < 0 ? ry : ry * 0.62) * sinA;
      domePts.push(macPt(mac, lu, lv));
    }
    drawClosedShape(domePts, 0.38);
    brush.noWash();

    // Form-following dry-media shading along the lower-right side of the shell dome
    for (let ring = 0; ring < 2; ring++) {
      const shadeArc = [];
      const scaleR = 0.88 - ring * 0.12;
      for (let s = 0; s <= 6; s++) {
        const a = -0.15 + (s / 6) * (Math.PI * 0.92);
        const lu = rx * scaleR * Math.cos(a) + 3;
        const lv = -7 + ry * 0.56 * scaleR * Math.sin(a);
        shadeArc.push(macPt(mac, lu, lv));
      }
      brush.set("cpencil", ring === 0 ? flav.shellShade : flav.shellBase, 1.15);
      brush.spline(shadeArc, 0.4);
    }

    // Satin sheen & specular crescent on the upper-left crown of the shell
    for (let ring = 0; ring < 2; ring++) {
      const crownArc = [];
      const rScale = 0.72 - ring * 0.18;
      for (let s = 0; s <= 5; s++) {
        const a = Math.PI * 1.08 + (s / 5) * (Math.PI * 0.62);
        const lu = -4 + rx * rScale * Math.cos(a);
        const lv = -8 + ry * 0.82 * rScale * Math.sin(a);
        crownArc.push(macPt(mac, lu, lv));
      }
      brush.set("cpencil", ring === 0 ? flav.shellHighlight : flav.shellSpec, ring === 0 ? 1.45 : 1.1);
      brush.spline(crownArc, 0.4);
    }

    // Delicate almond-flour micro-speckles on the baked meringue skin
    for (let sp = 0; sp < 8; sp++) {
      const rAng = random(0, Math.PI * 2);
      const rDist = random(0.18, 0.82);
      const lu = rx * rDist * Math.cos(rAng);
      const sinA = Math.sin(rAng);
      const lv = -7 + (sinA < 0 ? ry : ry * 0.55) * rDist * sinA;
      const p1 = macPt(mac, lu, lv);
      const p2 = macPt(mac, lu + 0.9, lv + 0.5);
      brush.set("rotring", sp % 3 === 0 ? flav.shellHighlight : flav.shellShade, 0.35);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Crisp upper-left rim contour + inner rim light catch
    const topRimPts = [];
    const topInnerHighlight = [];
    for (let s = 0; s <= 7; s++) {
      const a = Math.PI * 0.95 + (s / 7) * (Math.PI * 1.08);
      topRimPts.push(macPt(mac, rx * Math.cos(a), -7 + ry * Math.sin(a)));
      topInnerHighlight.push(macPt(mac, rx * 0.95 * Math.cos(a), -7 + ry * 0.94 * Math.sin(a)));
    }
    brush.set("cpencil", flav.shellHighlight, 0.85);
    brush.spline(topInnerHighlight, 0.4);
    brush.set("rotring", flav.shellShade, 0.45);
    brush.spline(topRimPts, 0.4);

    // --- 4.5 FAINT CRACKS ON THE SHELL ---
    // Every shell has a faint rim stress craze; ~42% have a branched hairline crack
    const cSide = mac.crackSide;
    const cStartU = cSide * rx * random(0.25, 0.58);
    const cStartV = -7 + ry * random(-0.55, -0.1);

    const crackPts = [[cStartU, cStartV]];
    const segs = mac.hasBigCrack ? 4 : 2;
    let curU = cStartU;
    let curV = cStartV;
    for (let cs = 0; cs < segs; cs++) {
      curU += -cSide * random(4.0, 7.5) + random(-2.0, 2.0);
      curV += random(2.2, 5.5);
      crackPts.push([curU, curV]);
    }

    // Draw dark hairline fissure + parallel bright broken-crust edge
    for (let cs = 0; cs < crackPts.length - 1; cs++) {
      const pA = macPt(mac, crackPts[cs][0], crackPts[cs][1]);
      const pB = macPt(mac, crackPts[cs + 1][0], crackPts[cs + 1][1]);
      const hA = macPt(mac, crackPts[cs][0] - 0.8, crackPts[cs][1] - 0.8);
      const hB = macPt(mac, crackPts[cs + 1][0] - 0.8, crackPts[cs + 1][1] - 0.8);

      brush.set("rotring", flav.shellSpec, 0.35);
      brush.line(hA[0], hA[1], hB[0], hB[1]);
      brush.set("rotring", flav.crackDark, mac.hasBigCrack ? 0.46 : 0.34);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    // Secondary fork branch on shells with a fuller crack
    if (mac.hasBigCrack && crackPts.length >= 3) {
      const mid = crackPts[1];
      const f1 = [mid[0] + cSide * random(2.5, 5.5), mid[1] + random(3.5, 6.5)];
      const f2 = [f1[0] + random(-3.5, 3.5), f1[1] + random(2.5, 4.5)];
      const p0 = macPt(mac, mid[0], mid[1]);
      const p1 = macPt(mac, f1[0], f1[1]);
      const p2 = macPt(mac, f2[0], f2[1]);
      const h0 = macPt(mac, mid[0] - 0.7, mid[1] - 0.7);
      const h1 = macPt(mac, f1[0] - 0.7, f1[1] - 0.7);

      brush.set("rotring", flav.shellSpec, 0.3);
      brush.line(h0[0], h0[1], h1[0], h1[1]);
      brush.set("rotring", flav.crackDark, 0.36);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // -------------------------------------------------------------------------
  // 5. CRUMBS ON THE PARCHMENT LINER & EMPTY TRAY TRACKS
  // -------------------------------------------------------------------------
  const crumbs = [];

  // Crumbs scattered in the pleated parchment gutters between rows
  for (let r = 0; r < rowDefs.length; r++) {
    const row = rowDefs[r];
    const flav = FLAVOURS[row.flav];
    for (let k = 0; k < 18; k++) {
      const side = random() < 0.5 ? -1 : 1;
      const cu = row.u + side * random(44, 58);
      const cv = random(-800, 800);
      if (isOnCanvas(cu, cv, 15)) {
        crumbs.push({
          u: cu,
          v: cv,
          size: random(1.2, 4.2),
          color: random(flav.crumbColors),
          shadow: flav.shellDeep
        });
      }
    }
  }

  // Denser clusters of crumbs & broken foot flakes inside the empty macaron slots
  for (let i = 0; i < emptySlots.length; i++) {
    const es = emptySlots[i];
    const count = Math.floor(random(8, 15));
    for (let k = 0; k < count; k++) {
      const cu = es.u + random(-36, 36);
      const cv = es.v + random(-20, 24);
      if (isOnCanvas(cu, cv, 15)) {
        crumbs.push({
          u: cu,
          v: cv,
          size: random(1.4, 5.2),
          color: random(es.flav.crumbColors),
          shadow: es.flav.shellDeep
        });
      }
    }
  }

  // Crumbs along the perpendicular empty tray cross-tracks
  for (let ct of crossTracks) {
    for (let k = 0; k < 40; k++) {
      const cu = random(-780, 780);
      const cv = random(ct.v1 + 6, ct.v2 - 6);
      if (isOnCanvas(cu, cv, 15)) {
        // Pick flavour of nearest row
        let nearestFlav = FLAVOURS.pistachio;
        let minDist = 9999;
        for (let rd of rowDefs) {
          const d = Math.abs(cu - rd.u);
          if (d < minDist) {
            minDist = d;
            nearestFlav = FLAVOURS[rd.flav];
          }
        }
        crumbs.push({
          u: cu,
          v: cv,
          size: random(1.2, 3.8),
          color: random(nearestFlav.crumbColors),
          shadow: "#3b2c24"
        });
      }
    }
  }

  // Render every crumb with a tiny cast shadow, pigmented body, and bright top glint
  for (let c of crumbs) {
    const [cx, cy] = toScreen(c.u, c.v);
    const sz = c.size;

    // Tiny cast shadow offset down-right
    brush.set("rotring", "#3d2d24", Math.max(0.45, sz * 0.28));
    brush.line(cx + 1.2, cy + 1.4, cx + 1.2 + sz * 0.75, cy + 1.4 + sz * 0.35);

    // Crumb body
    if (sz > 3.0) {
      brush.noStroke();
      brush.wash(c.color, 235);
      const cPts = [
        [cx - sz * 0.6, cy - sz * 0.2],
        [cx + sz * 0.2, cy - sz * 0.6],
        [cx + sz * 0.7, cy + sz * 0.1],
        [cx - sz * 0.1, cy + sz * 0.5]
      ];
      drawClosedShape(cPts, 0.2);
      brush.noWash();

      // Tiny highlight edge on larger meringue flakes
      brush.set("rotring", "#fffdf9", 0.38);
      brush.line(cx - sz * 0.4, cy - sz * 0.3, cx + sz * 0.2, cy - sz * 0.4);
    } else {
      brush.set("cpencil", c.color, Math.max(0.7, sz * 0.45));
      brush.line(cx, cy, cx + sz * 0.65, cy + sz * 0.25);
    }
  }

  noLoop();
}

// Hyperreal Burin Engraving of a Torn Sourdough Boule
// Pure line-work: tapering/swelling burin splines, globe-like contour lines,
// shifting-angle cross-hatching, and dot-and-lozenge stipple. Nothing is filled.

const PALETTE = {
  paper: "#f0ede4",
  laidLight: "#e5e0d5",
  laidDark: "#d8d3c6",
  plateTone: "#b7bcc2",
  inkWhisper: "#939ba4",
  inkLight: "#6d757f",
  inkMid: "#4b525b",
  inkDark: "#31363d",
  inkDeep: "#1f2328",
  inkBlack: "#121518",
  inkSepiaDark: "#272423",
  inkSepiaMid: "#3e3937"
};

// Scene geometry constants (off-centre placement on linen fold)
const BCX = 690;
const BCY = 538;
const BRX = 328;
const BRY = 242;

const SHARD_CX = 252;
const SHARD_CY = 746;
const SHARD_RX = 82;
const SHARD_RY = 45;

let crustBlisters = [];
let crumbCells = [];
let microPores = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(7319);
  noiseSeed(7319);

  // Custom copperplate burin gravers
  brush.add("burin_fine", {
    type: "default",
    weight: 0.22,
    scatter: 0.015,
    sharpness: 0.94,
    grain: 2,
    opacity: 230,
    spacing: 0.11,
    pressure: [0.12, 1.35, 0.12],
    noise: 0.12
  });

  brush.add("burin_swell", {
    type: "default",
    weight: 0.36,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 3,
    opacity: 245,
    spacing: 0.1,
    pressure: [0.08, 1.65, 0.08],
    noise: 0.1
  });

  brush.add("burin_lozenge", {
    type: "default",
    weight: 0.32,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 2,
    opacity: 245,
    spacing: 0.08,
    pressure: [0.15, 1.5, 0.15],
    noise: 0.05
  });

  initCrustBlisters();
  initCrumbArchitecture();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Strictly no fills, washes, or masses anywhere in the artwork
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  background(PALETTE.paper);

  // 1. Archival laid paper & copperplate plate-mark
  drawLaidPaperAndPlate();

  // 2. Bare linen folds engraved in long undulating parallel strokes
  drawEngravedLinen();

  // 3. Intact floured & blistered crust (globe contour lines & shifting cross-hatching)
  drawGlobeContouredCrust();
  drawCrustBlisters();

  // 4. The scorched ear & taut oven-spring belly
  drawScorchedEarAndBelly();

  // 5. The jagged torn crust rim & open gelatinised crumb with alveoli
  drawTornCrumbMatrix();
  drawBrokenCrustCliff();

  // 6. Foreground torn bread shard & scattered crumbs on the linen fold
  drawBreadShardAndCrumbs();

  // 7. Final archival burin accent pass (deepest crevices & crisp轮廓 reinforcements)
  drawFinalArchivalAccents();

  noLoop();
}

// ============================================================================
// GEOMETRY & DOMAIN MASK FUNCTIONS
// ============================================================================

function getLoafBoundaryPoint(angDeg) {
  let rad = (angDeg * PI) / 180;
  let ca = cos(rad);
  let sa = sin(rad);

  let rx = BRX;
  let ry = BRY;

  // Organic sourdough asymmetry
  let n1 = noise(ca * 1.6 + 4, sa * 1.6 + 4) - 0.5;
  let n2 = noise(ca * 4.2 + 10, sa * 4.2 + 10) - 0.5;

  rx += n1 * 28;
  ry += n1 * 20;

  // Scorched ear projects upward on the crown (-128 deg to -28 deg)
  if (angDeg > -132 && angDeg < -24) {
    let t = map(angDeg, -132, -24, 0, 180);
    let earBump = pow(sin(t), 1.4) * 24;
    let jag = (noise(angDeg * 0.35, 2.1) - 0.45) * 9 * sin(t);
    ry += earBump + jag;
    rx += (earBump + jag) * 0.35;
  }

  // Left torn profile (-180 to -125 and 115 to 180) is ragged & slightly indented
  let leftDist = abs(atan2(sa, -ca) * (180 / PI));
  if (leftDist < 68) {
    let w = pow(map(leftDist, 0, 68, 1, 0), 1.2);
    let tearIndent = -16 * w + (noise(angDeg * 0.22, 8.7) - 0.5) * 26 * w;
    let microTear = (noise(angDeg * 0.85, 3.3) - 0.5) * 10 * w;
    rx += tearIndent + microTear;
    ry += (tearIndent + microTear) * 0.4;
  }

  let x = BCX + ca * rx;
  let y = BCY + sa * ry;

  // Weight of boule flattens bottom softly against the linen fold
  if (sa > 0.12) {
    let flatFactor = pow((sa - 0.12) / 0.88, 1.55);
    y -= flatFactor * 34;
    // Slight outward bulge at lower cheek from dough settling
    x += ca * flatFactor * 14;
  }

  return { x, y };
}

function inMainLoaf(x, y) {
  let dx = x - BCX;
  let dy = y - BCY;
  if (abs(dx) > 380 || abs(dy) > 290) return false;

  // Reverse the bottom flattening slightly for angle estimation
  let ang = atan2(dy, dx) * (180 / PI);
  let bPt = getLoafBoundaryPoint(ang);
  let bDx = bPt.x - BCX;
  let bDy = bPt.y - BCY;
  let maxRSq = bDx * bDx + bDy * bDy;
  let curRSq = dx * dx + dy * dy;
  return curRSq <= maxRSq;
}

// The jagged cliff where the crust broke open to reveal the crumb
function getTearSplitX(y) {
  let t = constrain((y - 342) / (752 - 342), 0, 1);
  // Sweeps from beneath the left ear tip out across the front belly and down to the base
  let baseCurve =
    468 +
    sin(t * 165) * 168 +
    sin(t * 320 - 25) * 22 -
    pow(t, 2.4) * 58;
  let jag =
    (noise(y * 0.035, 14.2) - 0.5) * 22 +
    (noise(y * 0.14, 5.8) - 0.5) * 8;
  return baseCurve + jag;
}

// Lower boundary of the scorched ear overhang
function getEarSpineY(x) {
  let t = constrain((x - 455) / (895 - 455), 0, 1);
  let arch = 368 - sin(t * 155) * 76 + pow(t, 1.7) * 112;
  let serration = (noise(x * 0.06, 9.1) - 0.5) * 11;
  return arch + serration;
}

function getEarLipWidth(x) {
  let t = constrain((x - 455) / (895 - 455), 0, 1);
  return sin(t * 180) * 28 + 5;
}

function inEarBand(x, y) {
  if (x < 452 || x > 898) return false;
  if (!inMainLoaf(x, y)) return false;
  let spineY = getEarSpineY(x);
  let w = getEarLipWidth(x);
  return y >= spineY - w * 0.65 && y <= spineY + w * 0.55;
}

function inTearRegion(x, y) {
  if (!inMainLoaf(x, y)) return false;
  if (inEarBand(x, y)) return false;
  let spineY = getEarSpineY(x);
  if (y < spineY + 6 && x > 455) return false;
  if (y < 344 || y > 754) return false;
  return x < getTearSplitX(y);
}

function inSmallShard(x, y) {
  let dx = x - SHARD_CX;
  let dy = y - SHARD_CY;
  if (abs(dx) > 105 || abs(dy) > 65) return false;
  // Tilted rugged wedge
  let rot = -11;
  let rx = dx * cos(rot) - dy * sin(rot);
  let ry = dx * sin(rot) + dy * cos(rot);
  let ang = atan2(ry, rx) * (180 / PI);
  let n = (noise(cos(ang) * 1.8 + 2, sin(ang) * 1.8 + 2) - 0.5) * 0.24;
  let maxRx = SHARD_RX * (1 + n);
  let maxRy = SHARD_RY * (1 + n);
  if (ry > 0) maxRy *= 0.82; // flatter bottom on linen
  return (rx * rx) / (maxRx * maxRx) + (ry * ry) / (maxRy * maxRy) <= 1.0;
}

// ============================================================================
// 1. ARCHIVAL LAID PAPER & COPPERPLATE BORDER
// ============================================================================

function drawLaidPaperAndPlate() {
  brush.noField();

  // Horizontal wire lines of antique laid paper
  for (let y = 54; y <= 1146; y += 4.5) {
    let col = int(y / 4.5) % 2 === 0 ? PALETTE.laidLight : PALETTE.laidDark;
    brush.set("rotring", col, 0.14);
    let yOff = (noise(y * 0.05, 1.1) - 0.5) * 0.8;
    brush.line(54, y + yOff, 1146, y - yOff);
  }

  // Vertical chain lines every 86 px
  brush.set("rotring", PALETTE.laidDark, 0.2);
  for (let x = 92; x <= 1124; x += 86) {
    brush.line(x, 54, x, 1146);
  }

  // Copperplate outer emboss / bevel shadow
  brush.set("burin_fine", PALETTE.plateTone, 0.35);
  brush.line(52, 52, 1148, 52);
  brush.line(52, 52, 52, 1148);
  brush.set("burin_fine", PALETTE.inkWhisper, 0.45);
  brush.line(53, 1148, 1148, 1148);
  brush.line(1148, 53, 1148, 1148);

  // Double-ruled archival burin border
  brush.set("rotring", PALETTE.inkMid, 0.42);
  brush.line(68, 68, 1132, 68);
  brush.line(1132, 68, 1132, 1132);
  brush.line(1132, 1132, 68, 1132);
  brush.line(68, 1132, 68, 68);

  brush.set("rotring", PALETTE.inkLight, 0.24);
  brush.line(74, 74, 1126, 74);
  brush.line(1126, 74, 1126, 1126);
  brush.line(1126, 1126, 74, 1126);
  brush.line(74, 1126, 74, 74);

  // Diagonal corner plate-bevel ticks
  brush.set("burin_fine", PALETTE.inkLight, 0.28);
  brush.line(52, 52, 68, 68);
  brush.line(1148, 52, 1132, 68);
  brush.line(1148, 1148, 1132, 1132);
  brush.line(52, 1148, 68, 1132);
}

// ============================================================================
// 2. BARE LINEN FOLD IN LONG PARALLEL BURIN STROKES
// ============================================================================

function getLinenSurface(x, y) {
  // 1. Primary sweeping diagonal fold from left-mid to lower-right
  let d1 = (y - (665 + (x - 100) * 0.29)) / 64;
  let fold1 = exp(-d1 * d1) * 26;
  let slope1 = -2 * d1 * exp(-d1 * d1);

  // 2. Secondary lower foreground fold
  let d2 = (y - (835 + (x - 100) * 0.23)) / 52;
  let fold2 = exp(-d2 * d2) * 19;
  let slope2 = -2 * d2 * exp(-d2 * d2);

  // 3. Receding left fold behind the bread shard
  let d3 = (y - (575 + (x - 100) * 0.16)) / 48;
  let fold3 = exp(-d3 * d3) * 14 * constrain(map(x, 100, 620, 1, 0), 0, 1);
  let slope3 = -2 * d3 * exp(-d3 * d3) * constrain(map(x, 100, 620, 1, 0), 0, 1);

  // 4. Right lateral cloth crease pressed down by loaf weight
  let d4 = (y - (745 + (x - 780) * 0.18)) / 42;
  let w4 = constrain(map(x, 720, 1080, 0, 1), 0, 1);
  let fold4 = exp(-d4 * d4) * 16 * w4;
  let slope4 = -2 * d4 * exp(-d4 * d4) * w4;

  // Subtle linen weave undulation
  let micro = sin(x * 0.9 + y * 0.4) * 1.2;

  let relief = fold1 + fold2 + fold3 + fold4 + micro;
  let totalSlope = slope1 * 0.5 + slope2 * 0.4 + slope3 * 0.3 + slope4 * 0.35;

  // Lighting on linen folds (light from upper-left: negative slope = lit, positive = shaded)
  let foldShade = constrain(0.22 + totalSlope * 0.55, 0.02, 0.72);

  // Cast shadow of main boule (elliptical shadow stretching right and down-right)
  let sdx = (x - 742) / 348;
  let sdy = (y - 758) / 76;
  let loafShadowDist = sqrt(sdx * sdx + sdy * sdy);
  let loafCast = constrain(map(loafShadowDist, 0.55, 1.12, 0.78, 0), 0, 0.78);

  // Tight dark occlusion crease directly beneath the boule base
  let occDx = (x - 688) / 295;
  let occDy = (y - 748) / 32;
  let occDist = sqrt(occDx * occDx + occDy * occDy);
  let loafOcclusion = constrain(map(occDist, 0.7, 1.08, 0.95, 0), 0, 0.95);

  // Cast shadow & occlusion beneath the foreground bread shard
  let shDx = (x - 266) / 96;
  let shDy = (y - 762) / 28;
  let shardDist = sqrt(shDx * shDx + shDy * shDy);
  let shardCast = constrain(map(shardDist, 0.5, 1.15, 0.85, 0), 0, 0.85);

  let shade = constrain(
    max(foldShade, loafCast + foldShade * 0.35, loafOcclusion, shardCast),
    0,
    1
  );

  return { relief, shade, loafOcclusion, shardCast };
}

function drawEngravedLinen() {
  brush.noField();

  // Long parallel strokes sweeping across the bare linen fold
  let rowIndex = 0;
  for (let baseY = 515; baseY <= 1095; baseY += 3.3) {
    rowIndex++;
    // Fade in the cloth gracefully along its upper horizon
    let leftStart = 96;
    let rightEnd = 1104;

    let currentSegment = [];
    let avgShade = 0;
    let companionPoints = [];

    for (let x = leftStart; x <= rightEnd; x += 9) {
      // Gently sloped horizon behind loaf
      let horizonY = 540 + (x - 100) * 0.095;
      if (baseY < horizonY) continue;

      // Vignette outer edges of linen so it breathes inside the plate
      let edgeDist =
        pow((x - 600) / 510, 4) + pow((baseY - 820) / 290, 4);
      if (edgeDist > 1.05 + (noise(baseY * 0.05) - 0.5) * 0.18) {
        if (currentSegment.length > 2) {
          flushLinenSegment(currentSegment, avgShade / currentSegment.length, rowIndex);
        }
        currentSegment = [];
        avgShade = 0;
        continue;
      }

      let surf = getLinenSurface(x, baseY);
      let yPlot = baseY + (x - 600) * 0.055 - surf.relief;

      // Clip cleanly against the main boule and small shard
      if (inMainLoaf(x, yPlot) || inSmallShard(x, yPlot)) {
        if (currentSegment.length > 2) {
          flushLinenSegment(currentSegment, avgShade / currentSegment.length, rowIndex);
        }
        currentSegment = [];
        avgShade = 0;
        continue;
      }

      // In bright sunlit fold crowns, drop alternate lines for luminous paper highlights
      if (surf.shade < 0.14 && rowIndex % 2 === 0) {
        if (currentSegment.length > 2) {
          flushLinenSegment(currentSegment, avgShade / currentSegment.length, rowIndex);
        }
        currentSegment = [];
        avgShade = 0;
        continue;
      }

      let pressure = constrain(map(surf.shade, 0.05, 0.95, 0.22, 1.55), 0.2, 1.6);
      currentSegment.push([x, yPlot, pressure]);
      avgShade += surf.shade;

      // Record points for second swelling burin cut in deeper shadows
      if (surf.shade > 0.42) {
        companionPoints.push({ x, y: yPlot + 1.25, shade: surf.shade });
      }
    }

    if (currentSegment.length > 2) {
      flushLinenSegment(currentSegment, avgShade / currentSegment.length, rowIndex);
    }

    // Swelling companion burin cut (classic copperplate technique to darken parallel strokes)
    if (companionPoints.length > 2) {
      drawCompanionLinenCuts(companionPoints);
    }
  }

  // Secondary oblique cross-hatching strictly in the deep occlusion shadows beneath the loaf & shard
  for (let x = 155; x <= 1035; x += 3.8) {
    let seg = [];
    for (let s = 0; s <= 150; s += 7) {
      let px = x + s * 0.72;
      let py = 695 + s * 0.68 + (x - 600) * 0.04;
      if (px > 1095 || py > 1060) break;

      let surf = getLinenSurface(px, py);
      let yPlot = py - surf.relief * 0.7;
      if (inMainLoaf(px, yPlot) || inSmallShard(px, yPlot)) {
        if (seg.length > 2) {
          brush.set("burin_fine", PALETTE.inkDeep, 0.3);
          brush.spline(seg, 0.25);
        }
        seg = [];
        continue;
      }

      if (surf.shade > 0.52) {
        let p = map(surf.shade, 0.52, 0.95, 0.25, 1.35);
        seg.push([px, yPlot, p]);
      } else {
        if (seg.length > 2) {
          brush.set("burin_fine", PALETTE.inkDeep, 0.3);
          brush.spline(seg, 0.25);
        }
        seg = [];
      }
    }
    if (seg.length > 2) {
      brush.set("burin_fine", PALETTE.inkDeep, 0.3);
      brush.spline(seg, 0.25);
    }
  }
}

function flushLinenSegment(pts, meanShade, rowIdx) {
  let col = PALETTE.inkLight;
  let w = 0.24;
  let bName = "burin_fine";

  if (meanShade > 0.62) {
    col = PALETTE.inkDeep;
    w = 0.36;
    bName = "burin_swell";
  } else if (meanShade > 0.38) {
    col = PALETTE.inkDark;
    w = 0.3;
  } else if (meanShade > 0.22) {
    col = PALETTE.inkMid;
    w = 0.25;
  } else {
    col = rowIdx % 3 === 0 ? PALETTE.inkWhisper : PALETTE.inkLight;
    w = 0.2;
  }

  brush.set(bName, col, w);
  brush.spline(pts, 0.3);
}

function drawCompanionLinenCuts(compPts) {
  let seg = [];
  for (let i = 0; i < compPts.length; i++) {
    let pt = compPts[i];
    if (i > 0 && abs(pt.x - compPts[i - 1].x) > 12) {
      if (seg.length > 2) {
        brush.set("burin_fine", PALETTE.inkDark, 0.26);
        brush.spline(seg, 0.25);
      }
      seg = [];
    }
    seg.push([pt.x, pt.y, map(pt.shade, 0.42, 0.95, 0.2, 1.25)]);
  }
  if (seg.length > 2) {
    brush.set("burin_fine", PALETTE.inkDark, 0.26);
    brush.spline(seg, 0.25);
  }
}

// ============================================================================
// 3. FLOURED & BLISTERED CRUST (GLOBE CONTOUR LINES & BLISTERS)
// ============================================================================

function initCrustBlisters() {
  crustBlisters = [];
  let attempts = 0;
  while (crustBlisters.length < 62 && attempts < 1200) {
    attempts++;
    let x = random(500, 995);
    let y = random(310, 745);
    if (!inMainLoaf(x, y) || inTearRegion(x, y) || inEarBand(x, y)) continue;
    // Keep slightly clear of the immediate tear cliff
    if (abs(x - getTearSplitX(y)) < 16) continue;

    let r = random() < 0.25 ? random(8.5, 14.5) : random(3.5, 8.0);
    let overlap = false;
    for (let b of crustBlisters) {
      if (dist(x, y, b.x, b.y) < (r + b.r) * 1.25) {
        overlap = true;
        break;
      }
    }
    if (!overlap) {
      // Orientation follows local tangent of boule dome
      let ang = atan2(y - BCY, x - BCX) * (180 / PI) + 90;
      let distNorm = constrain(dist(x, y, BCX, BCY) / 310, 0, 1);
      let foreshorten = map(distNorm, 0, 1, 0.88, 0.48);
      crustBlisters.push({
        x,
        y,
        r,
        rx: r,
        ry: r * foreshorten,
        ang,
        toasted: random(0.4, 1.0)
      });
    }
  }
}

// Returns local crust shading, flour thickness, and blister deflection
function evaluateCrustSurface(x, y) {
  // 3D normal on the boule ellipsoid
  let nx = (x - (BCX + 15)) / 335;
  let ny = (y - (BCY - 10)) / 248;
  let r2 = constrain(nx * nx + ny * ny, 0, 0.99);
  let nz = sqrt(1 - r2);

  // Light source at upper-left-front: (-0.42, -0.52, 0.74)
  let dotL = nx * -0.42 + ny * -0.52 + nz * 0.74;
  let baseShade = constrain(map(dotL, 0.85, -0.45, 0.04, 0.96), 0.04, 0.96);

  // Extra roasting darkness near the scorched ear and lower-right base
  let spineY = getEarSpineY(x);
  let earProx = abs(y - spineY);
  if (earProx < 70 && x > 470 && x < 890) {
    let roast = pow(map(earProx, 0, 70, 1, 0), 1.6) * 0.35;
    baseShade = constrain(baseShade + roast, 0, 0.98);
  }

  // Rattan proofing basket (banneton) flour rings centered on the upper-right dome
  let fdx = (x - 795) / 1.15;
  let fdy = y - 485;
  let fDist = sqrt(fdx * fdx + fdy * fdy);
  // Concentric spiral ridges every ~27 px
  let ringWave = pow(0.5 + 0.5 * cos((fDist / 27) * 360 + noise(x * 0.02, y * 0.02) * 70), 1.8);
  let cheekMask = constrain(map(fDist, 25, 225, 1.0, 0.0), 0, 1);
  let flourPatch = cheekMask * (0.45 + 0.55 * ringWave) * noise(x * 0.018 + 3, y * 0.018 + 3) * 1.45;
  flourPatch = constrain(flourPatch, 0, 0.92);

  // Oven-spring stretched belly (just below the ear on the upper-left/mid): glossy & low-flour
  if (y > spineY && y < spineY + 68 && x > 475 && x < 845) {
    flourPatch *= 0.15;
  }

  // Blister deflection & highlight check
  let inBlisterLight = false;
  let deflectX = 0;
  let deflectY = 0;
  for (let b of crustBlisters) {
    let d = dist(x, y, b.x, b.y);
    if (d < b.r * 1.45) {
      let push = map(d, 0, b.r * 1.45, b.r * 0.42, 0);
      let ux = (x - b.x) / (d + 0.01);
      let uy = (y - b.y) / (d + 0.01);
      deflectX += ux * push;
      deflectY += uy * push;
      // Upper-left interior of blister is an untouched specular highlight
      if (d < b.r * 0.72 && x - b.x < b.r * 0.25 && y - b.y < b.r * 0.25) {
        inBlisterLight = true;
      }
    }
  }

  let effectiveShade = constrain(baseShade * (1 - flourPatch * 0.78), 0.02, 0.98);
  return {
    shade: effectiveShade,
    rawShade: baseShade,
    flour: flourPatch,
    inBlisterLight,
    deflectX,
    deflectY
  };
}

function drawGlobeContouredCrust() {
  brush.noField();

  // Pole 1 (near crown/ear apex) and Pole 2 (tucked under bottom-right base)
  let poleTop = { x: 648, y: 298 };
  let poleBot = { x: 718, y: 778 };

  // PASS 1: Meridional (Longitude) Globe Contour Lines
  // Arching from crown to base across the 3D ellipsoid of the boule
  for (let i = -38; i <= 78; i++) {
    let lonNorm = i / 62; // controls lateral bulge of the meridian
    let currentPts = [];
    let sumShade = 0;

    let steps = 90;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let latAng = t * 180; // 0 at top pole to 180 at bottom pole
      let sinLat = sin(latAng);
      let cosLat = cos(latAng);

      // 3D globe meridian projected onto the tilted boule dome
      let midX = lerp(poleTop.x, poleBot.x, t) + sinLat * lonNorm * 295;
      let midY = lerp(poleTop.y, poleBot.y, (1 - cosLat) * 0.5) - sinLat * abs(lonNorm) * 18;

      if (!inMainLoaf(midX, midY) || inTearRegion(midX, midY) || inEarBand(midX, midY)) {
        if (currentPts.length > 2) {
          flushCrustContour(currentPts, sumShade / currentPts.length, i);
        }
        currentPts = [];
        sumShade = 0;
        continue;
      }

      let surf = evaluateCrustSurface(midX, midY);
      let px = midX + surf.deflectX;
      let py = midY + surf.deflectY;

      // Leave untouched paper in blister specular domes and dense flour pockets
      if (
        surf.inBlisterLight ||
        (surf.flour > 0.68 && (i + s) % 3 !== 0) ||
        (surf.shade < 0.14 && i % 2 === 0)
      ) {
        if (currentPts.length > 2) {
          flushCrustContour(currentPts, sumShade / currentPts.length, i);
        }
        currentPts = [];
        sumShade = 0;
        continue;
      }

      let p = constrain(map(surf.shade, 0.05, 0.95, 0.18, 1.55), 0.15, 1.6);
      currentPts.push([px, py, p]);
      sumShade += surf.shade;
    }

    if (currentPts.length > 2) {
      flushCrustContour(currentPts, sumShade / currentPts.length, i);
    }
  }

  // PASS 2: Latitudinal (Parallel) Globe Contour Lines
  // Wrapping horizontally/circumferentially around the loaf belly and shoulder
  for (let j = 1; j <= 88; j++) {
    let vNorm = j / 89;
    let baseY = lerp(302, 768, vNorm);
    let currentPts = [];
    let sumShade = 0;

    for (let x = 455; x <= 1020; x += 6.5) {
      // Equator-like 3D curvature wrapping down across the front belly and rising toward the horizons
      let dxNorm = (x - 705) / 315;
      if (abs(dxNorm) > 1.05) continue;
      let domeArc = sqrt(max(0, 1 - dxNorm * dxNorm));
      let tiltOffset = (vNorm - 0.42) * domeArc * 78 + dxNorm * 22;
      let y = baseY + tiltOffset;

      if (!inMainLoaf(x, y) || inTearRegion(x, y) || inEarBand(x, y)) {
        if (currentPts.length > 2) {
          flushCrustContour(currentPts, sumShade / currentPts.length, j + 100);
        }
        currentPts = [];
        sumShade = 0;
        continue;
      }

      let surf = evaluateCrustSurface(x, y);
      let px = x + surf.deflectX;
      let py = y + surf.deflectY;

      // Latitudinal lines thin out in the floured highlight zone
      if (
        surf.inBlisterLight ||
        (surf.flour > 0.52 && j % 2 === 0) ||
        (surf.shade < 0.22 && (j + int(x / 7)) % 2 === 0)
      ) {
        if (currentPts.length > 2) {
          flushCrustContour(currentPts, sumShade / currentPts.length, j + 100);
        }
        currentPts = [];
        sumShade = 0;
        continue;
      }

      let p = constrain(map(surf.shade, 0.08, 0.95, 0.16, 1.45), 0.15, 1.5);
      currentPts.push([px, py, p]);
      sumShade += surf.shade;
    }

    if (currentPts.length > 2) {
      flushCrustContour(currentPts, sumShade / currentPts.length, j + 100);
    }
  }

  // PASS 3: Shifting-angle third cross-hatch & lozenge stipple in deep crust shadows and roasted zones
  for (let y = 320; y <= 760; y += 5.5) {
    for (let x = 490; x <= 1015; x += 5.5) {
      if (!inMainLoaf(x, y) || inTearRegion(x, y) || inEarBand(x, y)) continue;
      let surf = evaluateCrustSurface(x, y);

      // Third shifting cross-hatch pass in dark roasted/shadow regions
      if (surf.shade > 0.54 && !surf.inBlisterLight) {
        let tangentAng = atan2(y - BCY, x - BCX) * (180 / PI) + 36;
        let len = map(surf.shade, 0.54, 0.96, 4.5, 9.5);
        let col = surf.shade > 0.76 ? PALETTE.inkBlack : PALETTE.inkSepiaDark;
        brush.set("burin_fine", col, map(surf.shade, 0.54, 0.96, 0.22, 0.36));
        let dx = cos(tangentAng) * len * 0.5;
        let dy = sin(tangentAng) * len * 0.5;
        brush.line(x - dx, y - dy, x + dx, y + dy);
      }

      // Dot-and-lozenge stipple along the transition edge of floured banneton rings
      if (surf.flour > 0.25 && surf.flour < 0.65 && random() < 0.42) {
        drawBurinLozenge(
          x + random(-2, 2),
          y + random(-2, 2),
          atan2(y - BCY, x - BCX) * (180 / PI) + 45,
          random(1.2, 2.4),
          PALETTE.inkMid,
          0.24
        );
      }
    }
  }
}

function flushCrustContour(pts, meanShade, idx) {
  let col = PALETTE.inkMid;
  let w = 0.24;
  let bName = "burin_fine";

  if (meanShade > 0.72) {
    col = PALETTE.inkBlack;
    w = 0.38;
    bName = "burin_swell";
  } else if (meanShade > 0.52) {
    col = idx % 2 === 0 ? PALETTE.inkDeep : PALETTE.inkSepiaDark;
    w = 0.32;
    bName = "burin_swell";
  } else if (meanShade > 0.34) {
    col = PALETTE.inkDark;
    w = 0.26;
  } else if (meanShade > 0.2) {
    col = PALETTE.inkMid;
    w = 0.22;
  } else {
    col = PALETTE.inkLight;
    w = 0.18;
  }

  brush.set(bName, col, w);
  brush.spline(pts, 0.35);
}

function drawCrustBlisters() {
  for (let b of crustBlisters) {
    let ca = cos(b.ang);
    let sa = sin(b.ang);

    // 1. Concentric shadow crescent on the lower-right side of each blister
    for (let ring = 0; ring < 3; ring++) {
      let scaleR = 1.0 - ring * 0.16;
      let pts = [];
      for (let a = -25; a <= 155; a += 20) {
        let lx = cos(a) * b.rx * scaleR;
        let ly = sin(a) * b.ry * scaleR;
        let gx = b.x + lx * ca - ly * sa;
        let gy = b.y + lx * sa + ly * ca;
        let p = sin(map(a, -25, 155, 0, 180)) * 1.35;
        pts.push([gx, gy, p]);
      }
      brush.set(
        "burin_fine",
        ring === 0 ? PALETTE.inkBlack : PALETTE.inkSepiaDark,
        0.28 - ring * 0.04
      );
      brush.spline(pts, 0.4);
    }

    // 2. Delicate broken contour on the lit upper-left rim
    let litPts = [];
    for (let a = 175; a <= 315; a += 25) {
      let lx = cos(a) * b.rx;
      let ly = sin(a) * b.ry;
      let gx = b.x + lx * ca - ly * sa;
      let gy = b.y + lx * sa + ly * ca;
      litPts.push([gx, gy, 0.35]);
    }
    brush.set("burin_fine", PALETTE.inkMid, 0.2);
    brush.spline(litPts, 0.35);

    // 3. Micro-stipple dots around the blister highlight transition
    let numDots = int(b.r * 1.4);
    for (let d = 0; d < numDots; d++) {
      let a = random(-10, 140);
      let radScale = random(0.35, 0.82);
      let lx = cos(a) * b.rx * radScale;
      let ly = sin(a) * b.ry * radScale;
      let gx = b.x + lx * ca - ly * sa;
      let gy = b.y + lx * sa + ly * ca;
      drawBurinLozenge(gx, gy, b.ang + 30, random(1.0, 2.1), PALETTE.inkDeep, 0.25);
    }
  }
}

// ============================================================================
// 4. SCORCHED EAR & TAUT OVEN-SPRING BELLY
// ============================================================================

function drawScorchedEarAndBelly() {
  brush.noField();

  // A. Taut, glossy oven-spring striations immediately beneath the ear overhang
  for (let x = 468; x <= 882; x += 2.6) {
    let spineY = getEarSpineY(x);
    let w = getEarLipWidth(x);
    let startY = spineY + w * 0.35;
    let bellyLen = sin(map(x, 468, 882, 0, 180)) * 52 + 14;

    // Leave alternating bright ribbons of untouched paper for the stretched glossy skin
    let ribbonPhase = sin(x * 4.2 + noise(x * 0.05) * 90);
    if (ribbonPhase > 0.58) continue;

    let pts = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let px = x - u * 18 + sin(u * 180) * 4;
      let py = startY + u * bellyLen;
      if (!inMainLoaf(px, py) || inTearRegion(px, py)) break;
      // Heavy pressure directly under the ear overhang, tapering down into the crust
      let p = lerp(1.55, 0.2, pow(u, 0.75));
      pts.push([px, py, p]);
    }

    if (pts.length > 2) {
      let col = ribbonPhase < -0.2 ? PALETTE.inkBlack : PALETTE.inkSepiaDark;
      brush.set("burin_swell", col, ribbonPhase < -0.2 ? 0.34 : 0.24);
      brush.spline(pts, 0.3);
    }
  }

  // B. Deep cavern shadow directly under the overhanging lip of the ear
  for (let pass = 0; pass < 4; pass++) {
    let pts = [];
    for (let x = 462; x <= 888; x += 6) {
      let spineY = getEarSpineY(x);
      let w = getEarLipWidth(x);
      let py = spineY + w * 0.28 + pass * 1.4;
      if (!inMainLoaf(x, py)) continue;
      let t = map(x, 462, 888, 0, 180);
      let p = sin(t) * 1.6 + 0.2;
      pts.push([x, py, p]);
    }
    if (pts.length > 2) {
      brush.set("burin_swell", PALETTE.inkBlack, 0.42 - pass * 0.05);
      brush.spline(pts, 0.35);
    }
  }

  // C. The scorched, blistered, curled crest of the ear itself
  // Engraved with aggressive multi-angle cross-hatching & serrated charred edges
  for (let x = 456; x <= 894; x += 1.65) {
    let spineY = getEarSpineY(x);
    let w = getEarLipWidth(x);
    if (w < 3) continue;

    let topY = spineY - w * 0.65;
    let botY = spineY + w * 0.32;

    // Tiny charred blisters along the ear leave pinpoint white highlights
    let blisterCheck = noise(x * 0.14, spineY * 0.14);

    // Primary curving cross-stroke across the curled thickness of the ear
    let pts = [];
    for (let k = 0; k <= 5; k++) {
      let u = k / 5;
      let px = x + sin(u * 180) * 5.5 - u * 3;
      let py = lerp(topY, botY, u);
      if (blisterCheck > 0.72 && u > 0.25 && u < 0.65) continue;
      let p = 0.6 + sin(u * 180) * 1.1;
      pts.push([px, py, p]);
    }
    if (pts.length >= 2) {
      let isCharredCore = noise(x * 0.04, 2.2) > 0.32;
      brush.set(
        "burin_swell",
        isCharredCore ? PALETTE.inkBlack : PALETTE.inkSepiaDark,
        isCharredCore ? 0.38 : 0.28
      );
      brush.spline(pts, 0.35);
    }

    // Secondary opposing diagonal cross-hatch on the scorched crest
    if (int(x * 10) % 2 === 0) {
      let x2 = x + 6;
      let spineY2 = getEarSpineY(x2);
      brush.set("burin_fine", PALETTE.inkBlack, 0.32);
      brush.line(x - 3, botY, x2, spineY2 - w * 0.55);
    }

    // Jagged fibrous serrations projecting along the charred upper lip
    if (noise(x * 0.25, 7.7) > 0.44) {
      let flickLen = random(4, 11) * (w / 28);
      let flickAng = -68 + (noise(x * 0.1) - 0.5) * 45;
      brush.set("burin_fine", PALETTE.inkBlack, 0.3);
      brush.line(
        x,
        topY + 2,
        x + cos(flickAng) * flickLen,
        topY + 2 + sin(flickAng) * flickLen
      );
    }
  }

  // Longitudinal contour ribs along the scorched ear
  for (let r = -3; r <= 2; r++) {
    let pts = [];
    for (let x = 460; x <= 890; x += 7) {
      let spineY = getEarSpineY(x);
      let w = getEarLipWidth(x);
      let py = spineY + (r / 4) * w * 0.8;
      pts.push([x, py, 0.4 + sin(map(x, 460, 890, 0, 180)) * 1.1]);
    }
    brush.set("burin_fine", r >= 0 ? PALETTE.inkBlack : PALETTE.inkSepiaDark, 0.32);
    brush.spline(pts, 0.35);
  }
}

// ============================================================================
// 5. TORN OPEN CRUMB (ALVEOLI, GLOSSY GELATINISED WALLS, LOZENGE STIPPLE)
// ============================================================================

function initCrumbArchitecture() {
  crumbCells = [];
  microPores = [];

  // 1. Hero & Medium Alveoli packed organically across the tear region
  let targetRadii = [
    29, 26, 24, 23, 21, 20, 19, 18, 17, 17, 16, 15, 15, 14, 14,
    13, 12.5, 12, 11.5, 11, 11, 10.5, 10, 10, 9.5, 9.5, 9, 9, 8.5, 8.5,
    8, 8, 7.5, 7.5, 7, 7, 7, 6.5, 6.5, 6.5, 6, 6, 6, 5.5, 5.5, 5.5, 5, 5
  ];

  for (let rTarget of targetRadii) {
    let bestPt = null;
    let bestScore = -1;

    for (let attempt = 0; attempt < 180; attempt++) {
      let x = random(358, 638);
      let y = random(352, 745);
      if (!inTearRegion(x, y)) continue;

      // Distance from outer crust boundary and tear cliff
      let splitDist = getTearSplitX(y) - x;
      if (splitDist < rTarget * 1.1 + 6) continue;
      if (!inMainLoaf(x - rTarget - 5, y) || !inMainLoaf(x, y + rTarget + 5)) continue;

      let minClearance = 9999;
      for (let c of crumbCells) {
        // Wall thickness between alveoli is 4.5 to 9 px (the gelatinised dough membrane!)
        let d = dist(x, y, c.x, c.y) - (rTarget + c.r);
        if (d < minClearance) minClearance = d;
      }

      if (minClearance >= 4.2 && minClearance < 22) {
        let score = 22 - minClearance + random(0, 4);
        if (score > bestScore) {
          bestScore = score;
          bestPt = { x, y };
        }
      } else if (crumbCells.length === 0 && minClearance > 100) {
        bestPt = { x, y };
        break;
      }
    }

    if (bestPt) {
      // Oven-spring flow angle tilts upward toward the scorched ear (-32 to -58 deg)
      let flowAng = -44 + (bestPt.y - 540) * 0.08 + (bestPt.x - 500) * 0.06;
      crumbCells.push({
        x: bestPt.x,
        y: bestPt.y,
        r: rTarget,
        rx: rTarget * random(1.05, 1.24),
        ry: rTarget * random(0.78, 0.94),
        ang: flowAng + random(-14, 14),
        depth: constrain(map(rTarget, 5, 29, 0.52, 1.0) * random(0.88, 1.08), 0.45, 1.0),
        seed: random(100, 999),
        hasInnerWindow: rTarget > 16 && random() < 0.65
      });
    }
  }

  // 2. Small interstitial pores nestled inside the gelatinised dough walls between alveoli
  let poreAttempts = 0;
  while (microPores.length < 165 && poreAttempts < 2800) {
    poreAttempts++;
    let x = random(352, 642);
    let y = random(348, 748);
    if (!inTearRegion(x, y)) continue;
    if (getTearSplitX(y) - x < 8) continue;

    let pr = random(2.2, 4.8);
    let valid = true;
    for (let c of crumbCells) {
      if ( getWarpedCellDist(x, y, c) < 1.16 + pr / c.r ) {
        valid = false;
        break;
      }
    }
    if (!valid) continue;

    for (let mp of microPores) {
      if (dist(x, y, mp.x, mp.y) < pr + mp.r + 3.2) {
        valid = false;
        break;
      }
    }
    if (valid) {
      microPores.push({
        x,
        y,
        r: pr,
        ang: -40 + random(-25, 25)
      });
    }
  }
}

// Warped normalized radial distance from an alveolus center (<= 1.0 is inside the pocket)
function getWarpedCellDist(x, y, c) {
  let dx = x - c.x;
  let dy = y - c.y;
  let ca = cos(-c.ang);
  let sa = sin(-c.ang);
  let lx = dx * ca - dy * sa;
  let ly = dx * sa + dy * ca;
  let theta = atan2(ly, lx);
  let warp =
    1.0 +
    0.12 * sin(theta * 2 + c.seed) +
    0.08 * cos(theta * 3 - c.seed * 1.7) +
    0.05 * sin(theta * 5 + c.seed * 0.5);
  return sqrt((lx * lx) / (c.rx * c.rx) + (ly * ly) / (c.ry * c.ry)) / warp;
}

function getWarpedCellPoint(c, angleDeg, normRad) {
  let rad = (angleDeg * PI) / 180;
  let warp =
    1.0 +
    0.12 * sin(rad * 2 + c.seed) +
    0.08 * cos(rad * 3 - c.seed * 1.7) +
    0.05 * sin(rad * 5 + c.seed * 0.5);
  let lx = cos(angleDeg) * c.rx * normRad * warp;
  let ly = sin(angleDeg) * c.ry * normRad * warp;
  let ca = cos(c.ang);
  let sa = sin(c.ang);
  return {
    x: c.x + lx * ca - ly * sa,
    y: c.y + lx * sa + ly * ca
  };
}

function drawTornCrumbMatrix() {
  brush.noField();

  // STEP 1: The Glossy Gelatinised Crumb Matrix (Inter-Alveolar Walls & Torn Ridges)
  // Read through tighter, darker hatching immediately beside untouched paper highlights!
  drawGelatinisedCrumbWalls();

  // STEP 2: Deep Alveoli Cavities (Internal Bowl Contours, Shifting Cross-Hatching, Lozenge Stipple)
  for (let c of crumbCells) {
    drawSingleAlveolus(c);
  }

  // STEP 3: Small Interstitial Pores in the Gelatinised Walls
  for (let mp of microPores) {
    drawMicroPore(mp);
  }
}

function drawGelatinisedCrumbWalls() {
  // Flow-following contour hatching across the gelatinised dough walls between alveoli
  // Wherever a point is right on the ridge crest between two alveoli (dNorm ~ 1.22..1.45),
  // we leave UNTOUCHED PAPER for the glossy gelatinised highlight.
  // Immediately beside that highlight (dNorm ~ 1.02..1.22, the bevel turning into the alveolus),
  // we lay down TIGHTER, DARKER HATCHING!

  for (let band = 0; band < 155; band++) {
    let baseY = map(band, 0, 154, 344, 754);
    let seg = [];
    let segDarkness = 0;

    for (let x = 350; x <= 646; x += 3.5) {
      // Curving flow path of torn gluten strands (sweeping upward toward the ear)
      let flowOffset =
        sin((x - 350) * 0.45) * 18 -
        (x - 480) * 0.22 +
        (noise(x * 0.02, baseY * 0.02) - 0.5) * 16;
      let y = baseY + flowOffset;

      if (!inTearRegion(x, y)) {
        if (seg.length >= 2) {
          flushGelatinisedWallStroke(seg, segDarkness / seg.length);
        }
        seg = [];
        segDarkness = 0;
        continue;
      }

      // Evaluate distance to nearest and second-nearest alveolus
      let d1 = 999;
      let d2 = 999;
      let nearestCell = null;
      for (let c of crumbCells) {
        let wd = getWarpedCellDist(x, y, c);
        if (wd < d1) {
          d2 = d1;
          d1 = wd;
          nearestCell = c;
        } else if (wd < d2) {
          d2 = wd;
        }
      }

      // Skip inside the alveoli cavities (they have their own concave bowl engraving)
      if (d1 < 1.02) {
        if (seg.length >= 2) {
          flushGelatinisedWallStroke(seg, segDarkness / seg.length);
        }
        seg = [];
        segDarkness = 0;
        continue;
      }

      // Check micro-pores
      let inPore = false;
      for (let mp of microPores) {
        if (dist(x, y, mp.x, mp.y) < mp.r * 1.15) {
          inPore = true;
          break;
        }
      }
      if (inPore) {
        if (seg.length >= 2) {
          flushGelatinisedWallStroke(seg, segDarkness / seg.length);
        }
        seg = [];
        segDarkness = 0;
        continue;
      }

      // Specular highlight ribbon along the ridge crest between adjacent alveoli
      // (where d2 - d1 is small, or along the upper-left lit crest of a dough filament)
      let ridgeMetric = d2 - d1;
      let isLitCrest =
        nearestCell &&
        x < nearestCell.x + nearestCell.r * 0.3 &&
        y < nearestCell.y + nearestCell.r * 0.3 &&
        d1 > 1.16 &&
        d1 < 1.46;

      if (ridgeMetric < 0.24 || isLitCrest) {
        // Leave untouched cream paper for the glossy gelatinised highlight!
        if (seg.length >= 2) {
          flushGelatinisedWallStroke(seg, segDarkness / seg.length);
        }
        seg = [];
        segDarkness = 0;
        continue;
      }

      // Tight, dark hatching immediately bordering the untouched paper highlight!
      let wallBevelDarkness = constrain(map(d1, 1.02, 1.42, 0.95, 0.35), 0.25, 0.95);
      // Global form shadow on the lower-left and near the ear overhang
      let globalShade = constrain(map(y, 360, 740, 0.15, 0.42) + map(x, 355, 620, 0.25, 0), 0.1, 0.55);
      let combinedDark = constrain(max(wallBevelDarkness, globalShade), 0.2, 0.98);

      let p = map(combinedDark, 0.2, 0.98, 0.3, 1.55);
      seg.push([x, y, p]);
      segDarkness += combinedDark;
    }

    if (seg.length >= 2) {
      flushGelatinisedWallStroke(seg, segDarkness / seg.length);
    }
  }

  // Sharp, tight bevel ticks around the outer collar of every alveolus
  // (This directly frames the bright paper ridge with tight dark hatching)
  for (let c of crumbCells) {
    let stepDeg = map(c.r, 5, 29, 10, 4.2);
    for (let a = 0; a < 360; a += stepDeg) {
      // Leave upper-left highlight ridge open on one side while tightly hatching the bevel
      let pInner = getWarpedCellPoint(c, a, 1.01);
      let pOuter = getWarpedCellPoint(c, a, 1.19);
      if (!inTearRegion(pInner.x, pInner.y) || !inTearRegion(pOuter.x, pOuter.y)) continue;

      // Check if pOuter invades another alveolus
      let invades = false;
      for (let other of crumbCells) {
        if (other !== c && getWarpedCellDist(pOuter.x, pOuter.y, other) < 1.02) {
          invades = true;
          break;
        }
      }
      if (invades) continue;

      // Shadowed bevel (bottom-right external rim of cell wall, or steep collar)
      let bevelShade = 0.55 + 0.45 * cos((a - 45) * (PI / 180));
      if (bevelShade > 0.32) {
        let col = bevelShade > 0.7 ? PALETTE.inkBlack : PALETTE.inkDeep;
        brush.set("burin_fine", col, map(bevelShade, 0.32, 1.0, 0.22, 0.36));
        brush.line(pInner.x, pInner.y, pOuter.x, pOuter.y);
      }
    }
  }
}

function flushGelatinisedWallStroke(pts, meanDark) {
  let col = PALETTE.inkMid;
  let w = 0.24;
  let bName = "burin_fine";

  if (meanDark > 0.74) {
    col = PALETTE.inkBlack;
    w = 0.36;
    bName = "burin_swell";
  } else if (meanDark > 0.54) {
    col = PALETTE.inkDeep;
    w = 0.3;
    bName = "burin_swell";
  } else if (meanDark > 0.36) {
    col = PALETTE.inkDark;
    w = 0.25;
  }

  brush.set(bName, col, w);
  brush.spline(pts, 0.3);
}

function drawSingleAlveolus(c) {
  // Inside a concave alveolus pocket, light from the upper-left casts a deep
  // overhang shadow in the UPPER-LEFT interior (-175 deg to +25 deg) and
  // softly illuminates the concave lower-right floor (+45 deg to +135 deg).

  // 1. Crisp outer rim of the alveolus opening
  let rimPts = [];
  for (let a = 0; a <= 360; a += 12) {
    let pt = getWarpedCellPoint(c, a, 1.0);
    if (!inTearRegion(pt.x, pt.y)) continue;
    // Upper-left overhang rim is razor-dark; lower-right rim catches specular gloss
    let rimDark = 0.55 - 0.45 * cos((a - 50) * (PI / 180));
    let p = map(rimDark, 0.1, 1.0, 0.22, 1.55);
    rimPts.push([pt.x, pt.y, p]);
  }
  if (rimPts.length > 3) {
    brush.set("burin_swell", PALETTE.inkBlack, 0.34);
    brush.spline(rimPts, 0.4);
  }

  // 2. Concentric concave bowl contour lines stepping into the depth of the pocket
  let numRings = int(map(c.r, 5, 29, 4, 15));
  // Deepest pit offset toward upper-left (-135 deg)
  let pitOffX = -c.r * 0.22;
  let pitOffY = -c.r * 0.2;

  for (let rIdx = 1; rIdx <= numRings; rIdx++) {
    let u = rIdx / (numRings + 1); // 0 near rim -> 1 near deep pit
    let scaleR = 1.0 - u * 0.86;
    let offX = pitOffX * u;
    let offY = pitOffY * u;

    let ringPts = [];
    for (let a = 0; a <= 360; a += 14) {
      let basePt = getWarpedCellPoint(c, a, scaleR);
      let px = basePt.x + offX;
      let py = basePt.y + offY;
      if (!inTearRegion(px, py)) continue;

      // Internal illumination of the concave bowl
      let shadowWeight =
        (0.55 - 0.45 * cos((a - 45) * (PI / 180))) * 0.65 + u * 0.55 * c.depth;

      // Leave the illuminated lower-right floor open on inner rings for stippling
      if (shadowWeight < 0.34 && rIdx % 2 === 0) {
        if (ringPts.length > 2) {
          brush.set("burin_fine", PALETTE.inkDark, 0.24);
          brush.spline(ringPts, 0.35);
        }
        ringPts = [];
        continue;
      }

      let p = constrain(map(shadowWeight, 0.2, 1.1, 0.2, 1.6), 0.18, 1.65);
      ringPts.push([px, py, p]);
    }
    if (ringPts.length > 2) {
      let col = u > 0.45 ? PALETTE.inkBlack : PALETTE.inkDeep;
      brush.set(u > 0.45 ? "burin_swell" : "burin_fine", col, u > 0.45 ? 0.34 : 0.26);
      brush.spline(ringPts, 0.35);
    }
  }

  // 3. Cross-hatching laid at shifting angles across the concave interior
  let hatchAngles = [
    c.ang + 18,
    c.ang + 52, // +34 deg shift
    c.ang - 24  // -42 deg shift for deepest cavern pit
  ];

  for (let pass = 0; pass < 3; pass++) {
    let hAng = hatchAngles[pass];
    let spacing = pass === 0 ? 2.1 : pass === 1 ? 2.3 : 2.6;
    let minShadow = pass === 0 ? 0.32 : pass === 1 ? 0.52 : 0.72;

    let ca = cos(hAng);
    let sa = sin(hAng);
    let perpX = -sa;
    let perpY = ca;

    let maxSpan = c.r * 1.25;
    for (let d = -maxSpan; d <= maxSpan; d += spacing) {
      let ox = c.x + perpX * d;
      let oy = c.y + perpY * d;

      let hSeg = [];
      for (let s = -maxSpan; s <= maxSpan; s += 2.5) {
        // Curve the hatch line slightly so it hugs the concave bowl
        let curveBend = (1 - pow(s / maxSpan, 2)) * (d / maxSpan) * c.r * 0.18;
        let px = ox + ca * s + perpX * curveBend;
        let py = oy + sa * s + perpY * curveBend;

        if (!inTearRegion(px, py)) continue;
        let wd = getWarpedCellDist(px, py, c);
        if (wd > 0.96) {
          if (hSeg.length >= 2) {
            flushAlveolusHatch(hSeg, pass);
          }
          hSeg = [];
          continue;
        }

        // Compute concave shadow depth at (px, py)
        let relAng = atan2(py - c.y, px - c.x) * (180 / PI);
        let directionalShadow = 0.52 - 0.48 * cos((relAng - 45) * (PI / 180));
        let radialDepth = (1 - wd * 0.55) * c.depth;
        let localShadow = directionalShadow * 0.65 + radialDepth * 0.55;

        // Inner window (secondary deep hole at back of large alveoli)
        if (c.hasInnerWindow) {
          let wDist = dist(px, py, c.x + pitOffX * 0.9, c.y + pitOffY * 0.9);
          if (wDist < c.r * 0.36) localShadow += 0.35;
        }

        if (localShadow >= minShadow) {
          let p = constrain(map(localShadow, minShadow, 1.15, 0.25, 1.55), 0.2, 1.6);
          hSeg.push([px, py, p]);
        } else {
          if (hSeg.length >= 2) {
            flushAlveolusHatch(hSeg, pass);
          }
          hSeg = [];
        }
      }
      if (hSeg.length >= 2) {
        flushAlveolusHatch(hSeg, pass);
      }
    }
  }

  // 4. Dot-and-Lozenge Stipple in the deepest alveoli & light transition zone
  let stippleStep = 3.1;
  for (let sy = c.y - c.r * 1.1; sy <= c.y + c.r * 1.1; sy += stippleStep) {
    for (let sx = c.x - c.r * 1.1; sx <= c.x + c.r * 1.1; sx += stippleStep) {
      let jx = sx + random(-1.1, 1.1);
      let jy = sy + random(-1.1, 1.1);
      if (!inTearRegion(jx, jy)) continue;
      let wd = getWarpedCellDist(jx, jy, c);
      if (wd > 0.92) continue;

      let relAng = atan2(jy - c.y, jx - c.x) * (180 / PI);
      let directionalShadow = 0.52 - 0.48 * cos((relAng - 45) * (PI / 180));
      let localShadow = directionalShadow * 0.6 + (1 - wd * 0.5) * c.depth * 0.55;

      // In the deep cross-hatched diamond interstices (localShadow > 0.55): diamond lozenge marks
      // In the lit transition floor (0.20 < localShadow <= 0.55): tapering pinpoint dots & small lozenges
      if (localShadow > 0.55) {
        drawBurinLozenge(
          jx,
          jy,
          c.ang + 35,
          random(1.8, 3.1),
          PALETTE.inkBlack,
          0.34
        );
      } else if (localShadow > 0.22 && random() < map(localShadow, 0.22, 0.55, 0.28, 0.85)) {
        drawBurinLozenge(
          jx,
          jy,
          relAng + 90,
          map(localShadow, 0.22, 0.55, 0.9, 2.2),
          localShadow > 0.38 ? PALETTE.inkDeep : PALETTE.inkDark,
          map(localShadow, 0.22, 0.55, 0.2, 0.3)
        );
      }
    }
  }
}

function flushAlveolusHatch(pts, pass) {
  let col = pass === 2 ? PALETTE.inkBlack : pass === 1 ? PALETTE.inkBlack : PALETTE.inkDeep;
  let w = pass === 2 ? 0.35 : 0.28;
  brush.set(pass === 2 ? "burin_swell" : "burin_fine", col, w);
  brush.spline(pts, 0.25);
}

function drawMicroPore(mp) {
  // Tiny dark crescent & lozenge stipple inside each small dough pore
  let ca = cos(mp.ang);
  let sa = sin(mp.ang);
  let pts = [];
  for (let a = 115; a <= 345; a += 35) {
    let lx = cos(a) * mp.r;
    let ly = sin(a) * mp.r * 0.8;
    let gx = mp.x + lx * ca - ly * sa;
    let gy = mp.y + lx * sa + ly * ca;
    pts.push([gx, gy, sin(map(a, 115, 345, 0, 180)) * 1.3]);
  }
  brush.set("burin_fine", PALETTE.inkBlack, 0.28);
  brush.spline(pts, 0.35);

  // Interior lozenge dot
  drawBurinLozenge(
    mp.x - mp.r * 0.2,
    mp.y - mp.r * 0.2,
    mp.ang + 25,
    mp.r * 0.75,
    PALETTE.inkBlack,
    0.32
  );
}

// Helper for authentic copperplate burin dot-and-lozenge stipple marks
function drawBurinLozenge(x, y, angDeg, len, col, weight) {
  let dx = cos(angDeg) * len * 0.5;
  let dy = sin(angDeg) * len * 0.5;
  brush.set("burin_lozenge", col, weight);
  brush.spline(
    [
      [x - dx, y - dy, 0.12],
      [x, y, 1.55],
      [x + dx, y + dy, 0.12]
    ],
    0.1
  );
}

// ============================================================================
// BROKEN CRUST CLIFF (BORDER BETWEEN INTACT CRUST AND OPEN CRUMB)
// ============================================================================

function drawBrokenCrustCliff() {
  brush.noField();

  // The broken crust wall along getTearSplitX(y) has a physical thickness of ~11 px
  for (let y = 344; y <= 752; y += 1.9) {
    let splitX = getTearSplitX(y);
    if (!inMainLoaf(splitX, y) || inEarBand(splitX, y)) continue;

    // Local tangent of the tear cliff
    let splitNext = getTearSplitX(y + 4);
    let cliffAng = atan2(4, splitNext - splitX) * (180 / PI);
    let normAng = cliffAng + 180; // points left into the crumb

    let wallThick = 9 + noise(y * 0.08, 4.4) * 7;

    // Leave occasional ragged bright flakes of torn inner crust
    if (noise(y * 0.22, 1.9) > 0.74) continue;

    let xOuter = splitX + 2.5;
    let xInner = splitX - wallThick;

    let pts = [
      [xOuter, y, 1.45],
      [lerp(xOuter, xInner, 0.5), y + sin(normAng) * 2.5, 1.15],
      [xInner, y + sin(normAng) * 4.5, 0.25]
    ];

    let isDarkRim = int(y) % 2 === 0 || noise(y * 0.05) > 0.45;
    brush.set(
      "burin_swell",
      isDarkRim ? PALETTE.inkBlack : PALETTE.inkSepiaDark,
      isDarkRim ? 0.34 : 0.25
    );
    brush.spline(pts, 0.25);

    // Cross-hatched dark outer skin along the snapped crust edge
    if (int(y * 10) % 3 === 0) {
      brush.set("burin_fine", PALETTE.inkBlack, 0.3);
      brush.line(xOuter - 3, y - 3, xOuter + 1.5, y + 3.5);
    }
  }
}

// ============================================================================
// 6. FOREGROUND TORN BREAD SHARD & SCATTERED CRUMBS ON LINEN
// ============================================================================

function drawBreadShardAndCrumbs() {
  brush.noField();

  // 1. Small torn bread wedge resting on the bare linen fold at lower-left
  // Lower crescent is toasted crust; upper face is open gelatinised crumb
  for (let x = SHARD_CX - 92; x <= SHARD_CX + 92; x += 2.3) {
    for (let y = SHARD_CY - 52; y <= SHARD_CY + 52; y += 2.3) {
      if (!inSmallShard(x, y)) continue;

      let crustSplitY =
        SHARD_CY +
        6 +
        sin((x - SHARD_CX) * 2.2) * 7 +
        (x - SHARD_CX) * 0.12;

      if (y >= crustSplitY) {
        // Dark toasted bottom crust resting on the linen
        if (int(x) % 2 === 0) {
          let len = random(4, 7.5);
          let ang = 75 + (x - SHARD_CX) * 0.35;
          brush.set("burin_swell", PALETTE.inkBlack, 0.32);
          brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
        }
      }
    }
  }

  // Crumb alveoli & glossy ridges on the upper face of the shard
  let shardAlveoli = [
    { x: SHARD_CX - 34, y: SHARD_CY - 8, r: 12 },
    { x: SHARD_CX - 8, y: SHARD_CY - 12, r: 15 },
    { x: SHARD_CX + 22, y: SHARD_CY - 7, r: 13 },
    { x: SHARD_CX + 46, y: SHARD_CY - 2, r: 9.5 },
    { x: SHARD_CX - 54, y: SHARD_CY - 1, r: 8.5 },
    { x: SHARD_CX + 6, y: SHARD_CY + 3, r: 8 }
  ];

  // Flow lines on the shard's gelatinised crumb walls (leaving bright paper ridges)
  for (let sy = SHARD_CY - 42; sy <= SHARD_CY + 14; sy += 2.4) {
    let seg = [];
    for (let sx = SHARD_CX - 88; sx <= SHARD_CX + 88; sx += 3.5) {
      let py = sy + sin((sx - SHARD_CX) * 1.8) * 3.5 - (sx - SHARD_CX) * 0.1;
      if (!inSmallShard(sx, py)) {
        if (seg.length >= 2) {
          brush.set("burin_fine", PALETTE.inkDark, 0.25);
          brush.spline(seg, 0.3);
        }
        seg = [];
        continue;
      }

      let minD = 999;
      for (let sa of shardAlveoli) {
        let d = dist(sx, py, sa.x, sa.y) / sa.r;
        if (d < minD) minD = d;
      }

      // Skip inside alveoli and leave a bright paper highlight ring at minD ~ 1.15..1.38
      if (minD < 1.0 || (minD > 1.16 && minD < 1.38)) {
        if (seg.length >= 2) {
          brush.set("burin_fine", PALETTE.inkDark, 0.25);
          brush.spline(seg, 0.3);
        }
        seg = [];
        continue;
      }

      let p = minD < 1.16 ? 1.35 : 0.55;
      seg.push([sx, py, p]);
    }
    if (seg.length >= 2) {
      brush.set("burin_fine", PALETTE.inkDark, 0.25);
      brush.spline(seg, 0.3);
    }
  }

  // Engrave the shard's alveoli with shifting cross-hatching & lozenge stipple
  for (let sa of shardAlveoli) {
    for (let rScale = 1.0; rScale >= 0.3; rScale -= 0.22) {
      let pts = [];
      for (let a = 110; a <= 370; a += 22) {
        let px = sa.x + cos(a) * sa.r * rScale;
        let py = sa.y + sin(a) * sa.r * 0.72 * rScale;
        if (inSmallShard(px, py)) {
          pts.push([px, py, 1.25]);
        }
      }
      if (pts.length > 2) {
        brush.set("burin_fine", PALETTE.inkBlack, 0.3);
        brush.spline(pts, 0.35);
      }
    }
    for (let k = 0; k < 14; k++) {
      let a = random(0, 360);
      let d = random(0.15, 0.85);
      let px = sa.x + cos(a) * sa.r * d;
      let py = sa.y + sin(a) * sa.r * 0.7 * d;
      if (inSmallShard(px, py)) {
        drawBurinLozenge(px, py, 25, random(1.2, 2.3), PALETTE.inkBlack, 0.3);
      }
    }
  }

  // Crisp silhouette & base shadow of the small shard
  let shardBotPts = [];
  for (let a = -15; a <= 195; a += 8) {
    let rx = cos(a) * SHARD_RX;
    let ry = sin(a) * SHARD_RY * 0.82;
    let rot = -11;
    let gx = SHARD_CX + rx * cos(rot) - ry * sin(rot);
    let gy = SHARD_CY + rx * sin(rot) + ry * cos(rot);
    shardBotPts.push([gx, gy, sin(map(a, -15, 195, 0, 180)) * 1.5 + 0.2]);
  }
  brush.set("burin_swell", PALETTE.inkBlack, 0.38);
  brush.spline(shardBotPts, 0.35);

  // 2. Scattered toasted crumbs on the linen fold between shard and boule
  let crumbs = [
    { x: 358, y: 768, r: 5.2 },
    { x: 382, y: 782, r: 3.6 },
    { x: 404, y: 762, r: 6.4 },
    { x: 425, y: 794, r: 4.1 },
    { x: 446, y: 775, r: 3.2 },
    { x: 342, y: 792, r: 2.8 },
    { x: 472, y: 786, r: 4.8 },
    { x: 512, y: 798, r: 3.5 },
    { x: 192, y: 778, r: 3.8 },
    { x: 295, y: 796, r: 4.4 }
  ];

  for (let cr of crumbs) {
    // Shadow side of crumb + tiny cast shadow on the linen
    brush.set("burin_swell", PALETTE.inkBlack, 0.32);
    brush.arc(cr.x, cr.y, cr.r, 15, 205);
    brush.set("burin_fine", PALETTE.inkDeep, 0.24);
    brush.line(cr.x - cr.r * 0.4, cr.y + cr.r * 0.9, cr.x + cr.r * 1.5, cr.y + cr.r * 0.9);
    brush.line(cr.x, cr.y + cr.r * 1.15, cr.x + cr.r * 1.2, cr.y + cr.r * 1.15);
    drawBurinLozenge(cr.x + 1, cr.y + 1, 30, cr.r * 0.55, PALETTE.inkBlack, 0.28);
  }
}

// ============================================================================
// 7. FINAL ARCHIVAL ACCENTS & OUTER CONTOUR REINFORCEMENT
// ============================================================================

function drawFinalArchivalAccents() {
  brush.noField();

  // Reinforce the lower-right & bottom shadow contour where the boule presses into the linen
  let baseContour = [];
  for (let a = -12; a <= 168; a += 4) {
    let pt = getLoafBoundaryPoint(a);
    let p = sin(map(a, -12, 168, 0, 180)) * 1.55 + 0.15;
    baseContour.push([pt.x, pt.y, p]);
  }
  brush.set("burin_swell", PALETTE.inkBlack, 0.42);
  brush.spline(baseContour, 0.35);

  // Delicate broken contour along the ragged left tear silhouette
  for (let a = 152; a <= 232; a += 5) {
    let pt1 = getLoafBoundaryPoint(a);
    let pt2 = getLoafBoundaryPoint(a + 3.5);
    // Alternate dark alveolar rim cuts with bright paper highlights
    if (noise(a * 0.25) > 0.32) {
      brush.set("burin_fine", PALETTE.inkDeep, 0.28);
      brush.line(pt1.x, pt1.y, pt2.x, pt2.y);
    }
  }
}

// Hyperrealist Mixed-Media Drawing (Graphite, Colored Pencil, Charcoal & Wash)
// "Seconds After" — A half-eaten birthday cake on a cluttered kitchen table

const TILT = -7.2;
const COS_T = Math.cos((TILT * Math.PI) / 180);
const SIN_T = Math.sin((TILT * Math.PI) / 180);

// Rotate scene coordinates around canvas center for handheld tilted framing
function R(x, y) {
  let dx = x - 600;
  let dy = y - 600;
  return [
    600 + dx * COS_T - dy * SIN_T,
    600 + dx * SIN_T + dy * COS_T
  ];
}

// Helper for ellipse perimeter point in scene coordinates
function ellPt(cx, cy, rx, ry, deg, rotDeg = 0) {
  let rad = (deg * Math.PI) / 180;
  let px = Math.cos(rad) * rx;
  let py = Math.sin(rad) * ry;
  if (rotDeg !== 0) {
    let rr = (rotDeg * Math.PI) / 180;
    let nx = px * Math.cos(rr) - py * Math.sin(rr);
    let ny = px * Math.sin(rr) + py * Math.cos(rr);
    px = nx;
    py = ny;
  }
  return [cx + px, cy + py];
}

// Draw a tilted polygon using beginShape/vertex/endShape
function rShape(pts, curv = 0.15, closeShape = true) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    let [rx, ry] = R(pts[i][0], pts[i][1]);
    if (pts[i].length > 2) {
      brush.vertex(rx, ry, pts[i][2]);
    } else {
      brush.vertex(rx, ry);
    }
  }
  brush.endShape(closeShape);
}

// Draw a tilted spline
function rSpline(pts, curv = 0.5) {
  if (pts.length < 2) return;
  let tPts = pts.map((p) => {
    let [rx, ry] = R(p[0], p[1]);
    return p.length > 2 ? [rx, ry, p[2]] : [rx, ry];
  });
  brush.spline(tPts, curv);
}

// Draw a tilted line
function rLine(x1, y1, x2, y2) {
  let [rx1, ry1] = R(x1, y1);
  let [rx2, ry2] = R(x2, y2);
  brush.line(rx1, ry1, rx2, ry2);
}

// Draw a tilted ellipse as a smooth polygon
function rEllipse(cx, cy, rx, ry, steps = 36, curv = 0.35, wobble = 0, rotDeg = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let [px, py] = ellPt(cx, cy, rx, ry, a, rotDeg);
    if (wobble > 0) {
      px += random(-wobble, wobble);
      py += random(-wobble, wobble);
    }
    pts.push([px, py]);
  }
  rShape(pts, curv, true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  randomSeed(7841);
  noiseSeed(7841);
  angleMode(DEGREES);

  // Required brush scaling
  brush.scaleBrushes(3);

  // Custom brushes for hyperreal graphite micro-detail, charcoal smoke smears, and sponge crumb
  brush.add("smudge", {
    type: "default",
    weight: 10.5,
    scatter: 1.5,
    sharpness: 0.07,
    grain: 0.35,
    opacity: 19,
    spacing: 0.22,
    pressure: [0.25, 1.15, 0.15],
    noise: 0.65
  });

  brush.add("fine_graphite", {
    type: "default",
    weight: 0.35,
    scatter: 0.05,
    sharpness: 0.84,
    grain: 0.52,
    opacity: 155,
    spacing: 0.14,
    pressure: [0.6, 1.0, 0.5],
    noise: 0.35
  });

  brush.add("crumb_spray", {
    type: "spray",
    weight: 1.1,
    scatter: 2.1,
    opacity: 110,
    spacing: 0.45,
    pressure: [0.7, 1.1, 0.6],
    noise: 0.5
  });

  // Custom vector field for rising, curling candle smoke drifting right
  brush.addField("smoke_drift", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.09;
        let ny = row * 0.09;
        let n = noise(nx, ny, t * 0.1);
        field[col][row] = -68 + (n - 0.48) * 95 + TILT;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm unbleached cotton paper ground
  background("#e4dacb");

  // 1. Kitchen Backdrop, Cluttered Wood Table & Grey Window Daylight Leak
  drawTableAndLighting();

  // 2. Cluttered Kitchen Table Props (Cropped Glass, Crumpled Napkin, Burnt Match, Fallen Holder)
  drawTableClutter();

  // 3. Cropped Ceramic Plate & Crinkled Aluminum Foil Board
  drawPlateAndFoil();

  // 4. Smeared Buttercream & Child's Sticky Fingerprint on the Foil
  drawFoilSmearsAndFingerprint();

  // 5. Half-Eaten Birthday Cake (Shadows, Exterior Frosting, Cut Sponge & Jam Layers, Broken Bite)
  drawHalfEatenCake();

  // 6. Stainless-Steel Fork Stuck in the Sponge
  drawForkInSponge();

  // 7. Recently Blown-Out Candles, Wax Drips & Soft Charcoal Smoke Smears
  drawCandlesAndSmoke();

  // 8. Foreground Motion Blur Drag & Film-Like Pencil Grain
  drawForegroundMotionBlurAndGrain();

  noLoop();
}

