function drawPlateAndFoil() {
  // Plate center at (785, 595) with rx=545, ry=370 -> right side (785+545=1330) crops off canvas!
  let pcx = 785;
  let pcy = 595;

  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.45, 0.35);

  // Deep warm cast shadow under the plate Rim (shifted right by left window light)
  brush.fill("#241710", 165);
  rEllipse(pcx + 28, pcy + 26, 550, 374, 48, 0.3, 0, 2);

  // Outer ceramic plate body (warm ivory-cream glaze)
  brush.fill("#dfd6c3", 220);
  rEllipse(pcx, pcy, 542, 368, 52, 0.35, 0, 2);

  // Cool window-daylight sheen along the left rim of the plate
  brush.fill("#e6edf0", 140);
  let leftRim = [];
  for (let a = 115; a <= 255; a += 8) {
    leftRim.push(ellPt(pcx, pcy, 540, 366, a, 2));
  }
  for (let a = 255; a >= 115; a -= 8) {
    leftRim.push(ellPt(pcx, pcy, 435, 294, a, 2));
  }
  rShape(leftRim, 0.25, true);

  // Inner plate well shadow
  brush.fill("#bfb39c", 150);
  rEllipse(pcx + 8, pcy + 6, 432, 292, 48, 0.35, 0, 2);

  brush.noFill();

  // Ceramic plate rim outlines & terracotta-ochre double stripes
  brush.set("2B", "#524638", 0.55);
  rEllipse(pcx, pcy, 542, 368, 60, 0.35, 0.6, 2);

  brush.set("cpencil", "#9e4d32", 0.65);
  rEllipse(pcx, pcy, 512, 347, 60, 0.35, 0.8, 2);
  brush.set("cpencil", "#b8743e", 0.45);
  rEllipse(pcx, pcy, 498, 338, 60, 0.35, 0.8, 2);

  brush.set("HB", "#7d705f", 0.4);
  rEllipse(pcx, pcy, 432, 292, 56, 0.35, 0.6, 2);

  // --- Crinkled Aluminum Foil Cake Board (cx=750, cy=575, rx=405, ry=272) ---
  let fcx = 750;
  let fcy = 575;
  let foilOuter = [];
  let foilSteps = 64;
  for (let i = 0; i < foilSteps; i++) {
    let a = (i / foilSteps) * 360;
    // Crinkled polygonal edge variations
    let rMod = 1 + 0.028 * Math.sin(i * 5.3) + 0.018 * Math.cos(i * 11.7);
    let [px, py] = ellPt(fcx, fcy, 405 * rMod, 272 * rMod, a, 1);
    foilOuter.push([px, py]);
  }

  // Foil shadow on plate
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fill("#4a3e33", 145);
  rShape(foilOuter.map((p) => [p[0] + 9, p[1] + 8]), 0.1, true);

  // Base metallic grey-silver wash of the foil
  brush.wash("#9c9e9e", 215);
  rShape(foilOuter, 0.08, true);
  brush.noWash();

  // Faceted crinkled foil highlights & dark metallic reflections (especially on exposed left/front half)
  for (let i = 0; i < 42; i++) {
    let a1 = random(85, 275);
    let a2 = a1 + random(6, 18);
    let rIn = random(0.15, 0.65);
    let rOut = random(0.72, 0.99);
    let p1 = ellPt(fcx, fcy, 405 * rIn, 272 * rIn, a1, 1);
    let p2 = ellPt(fcx, fcy, 405 * rOut, 272 * rOut, a1, 1);
    let p3 = ellPt(fcx, fcy, 405 * rOut, 272 * rOut, a2, 1);
    let p4 = ellPt(fcx, fcy, 405 * rIn, 272 * rIn, a2, 1);

    let facetType = random();
    if (facetType < 0.38) {
      // Bright window daylight reflection facet
      brush.fill("#e3eaed", random(95, 165));
    } else if (facetType < 0.72) {
      // Dark tarnished pewter reflection facet
      brush.fill("#56595c", random(85, 140));
    } else {
      // Warm amber cake bounce-light reflection on foil
      brush.fill("#b89263", random(75, 125));
    }
    rShape([p1, p2, p3, p4], 0.02, true);
  }
  brush.noFill();

  // Sharp radial crinkle ridges along the foil perimeter and exposed surface
  for (let i = 0; i < 95; i++) {
    let a = random(75, 285);
    let r1 = random(0.28, 0.84);
    let r2 = random(0.88, 1.0);
    let [x1, y1] = ellPt(fcx, fcy, 405 * r1, 272 * r1, a, 1);
    let [x2, y2] = ellPt(fcx, fcy, 405 * r2, 272 * r2, a + random(-5, 5), 1);

    if (random() < 0.5) {
      brush.set("fine_graphite", "#2e3133", random(0.45, 0.85));
    } else {
      brush.set("cpencil", "#f0f5f7", random(0.35, 0.65));
    }
    rSpline([
      [x1, y1],
      [(x1 + x2) * 0.5 + random(-6, 6), (y1 + y2) * 0.5 + random(-6, 6)],
      [x2, y2]
    ], 0.25);
  }

  // Crisp crinkled foil border in graphite
  brush.set("2B", "#3a3c3e", 0.5);
  rShape(foilOuter, 0.05, true);

  // Knife score lines scratched into the exposed foil where cake slices were cut
  brush.set("fine_graphite", "#222426", 0.75);
  rLine(725, 565, 425, 505);
  rLine(730, 570, 495, 695);
  rLine(720, 562, 585, 765);
  brush.set("cpencil", "#f7fafc", 0.45);
  rLine(725, 567, 425, 507);
  rLine(730, 572, 495, 697);
}

