// ============================================================================
function drawFoilSmearsAndFingerprint() {
  brush.noStroke();
  brush.fillBleed(0.12, "out");

  // Greasy buttercream smears dragged across the exposed foil & plate lip
  brush.fill("#e8dac0", 175);
  rShape([[485, 545], [645, 535], [670, 625], [535, 650], [465, 595]], 0.35, true);
  rShape([[545, 655], [665, 640], [645, 745], [520, 730]], 0.35, true);
  rShape([[335, 585], [415, 570], [430, 615], [345, 622]], 0.35, true);

  // Warm shadowed underside of buttercream smears
  brush.fill("#bfa984", 145);
  rShape([[495, 585], [635, 575], [650, 620], [525, 638]], 0.35, true);
  rShape([[555, 685], [655, 675], [638, 738], [535, 725]], 0.35, true);

  // Sticky crimson raspberry jam smear mingled with the buttercream
  brush.fill("#871e27", 155);
  rShape([[525, 595], [610, 582], [625, 618], [545, 628]], 0.4, true);
  rShape([[425, 645], [488, 635], [498, 672], [435, 680]], 0.4, true);

  brush.noFill();

  // Hyperreal palette-knife / fork drag ridges through the smeared buttercream
  for (let i = 0; i < 28; i++) {
    let sy = map(i, 0, 27, 545, 735);
    let sx1 = random(470, 540);
    let sx2 = random(615, 685);
    brush.set("cpencil", i % 2 === 0 ? "#fbf6eb" : "#9c8563", random(0.35, 0.65));
    rSpline([
      [sx1, sy],
      [(sx1 + sx2) * 0.5, sy + random(-14, 14)],
      [sx2, sy + random(-8, 8)]
    ], 0.45);
  }

  // --- CHILD'S STICKY FINGERPRINT ON THE FOIL (Primary thumbprint at x=442, y=662) ---
  // Plus two smaller adjacent index/middle fingertip smudges at (484, 628) and (504, 654)
  let prints = [
    { cx: 442, cy: 662, rx: 24, ry: 32, ang: -24, rings: 15 },
    { cx: 484, cy: 628, rx: 15, ry: 20, ang: -12, rings: 10 },
    { cx: 504, cy: 654, rx: 14, ry: 18, ang: -5, rings: 9 }
  ];

  for (let pr of prints) {
    // Tacky semi-translucent jam & buttercream grease pad dulling the foil
    brush.noStroke();
    brush.fillBleed(0.06, "out");
    brush.fill("#9e5248", 90);
    rEllipse(pr.cx, pr.cy, pr.rx * 1.12, pr.ry * 1.12, 28, 0.35, 0.8, pr.ang);
    brush.fill("#d9be9c", 85);
    rEllipse(pr.cx - 2, pr.cy - 2, pr.rx * 0.92, pr.ry * 0.92, 24, 0.35, 0.5, pr.ang);
    brush.noFill();

    // Epidermal whorl/loop friction ridges in ultra-fine graphite and warm cream colored pencil
    for (let r = 1; r <= pr.rings; r++) {
      let t = r / pr.rings;
      let crx = pr.rx * t;
      let cry = pr.ry * t;
      let arcPts = [];
      let aStart = -155 + (r % 3) * 12;
      let aEnd = 145 - (r % 2) * 15;
      for (let a = aStart; a <= aEnd; a += 18) {
        let [px, py] = ellPt(pr.cx, pr.cy + (1 - t) * 4, crx, cry, a, pr.ang);
        arcPts.push([px, py]);
      }
      brush.set("fine_graphite", r % 2 === 0 ? "#472924" : "#594d42", 0.52);
      rSpline(arcPts, 0.45);

      // Tiny specular grease highlight on ridge crests catching the window light
      if (r % 2 === 1) {
        let hiPts = [];
        for (let a = -120; a <= -15; a += 22) {
          let [px, py] = ellPt(pr.cx - 0.8, pr.cy + (1 - t) * 4 - 0.8, crx, cry, a, pr.ang);
          hiPts.push([px, py]);
        }
        brush.set("cpencil", "#f2ece1", 0.25);
        rSpline(hiPts, 0.45);
      }
    }

    // Sticky pulled ridge rim around the edge of the child's fingerprint
    brush.set("fine_graphite", "#6e272c", 0.6);
    rEllipse(pr.cx, pr.cy, pr.rx, pr.ry, 32, 0.35, 1.1, pr.ang);
  }
}

// ============================================================================
// 5. THE HALF-EATEN BIRTHDAY CAKE (FROSTING, CUT SPONGE, JAM & CRUMBS)
// ============================================================================
function drawHalfEatenCake() {
  // Cake geometry in scene coordinates:
  // Top ellipse center: (765, 360), Bottom ellipse center: (765, 560), rx=305, ry=185
  // Intact cake spans from angle aLeft = -148 deg clockwise through 0 deg to aFront = 104 deg.
  // Inner cut vertex spine: top (735, 378), bottom (742, 578)
  let ccx = 765;
  let cTopY = 360;
  let cBotY = 560;
  let crx = 305;
  let cry = 185;
  let aLeft = -148;
  let aFront = 104;

  let spineTop = [735, 378];
  let spineBot = [742, 578];
  let leftTop = ellPt(ccx, cTopY, crx, cry, aLeft);   // (~506, 262)
  let leftBot = ellPt(ccx, cBotY, crx, cry, aLeft);   // (~506, 462)
  let frontTop = ellPt(ccx, cTopY, crx, cry, aFront); // (~691, 539)
  let frontBot = ellPt(ccx, cBotY, crx, cry, aFront); // (~691, 739)

  // --- A. Cast Shadow of Cake on Foil & Plate (shifted right) ---
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill("#2b1e16", 155);
  let shadowPoly = [[spineBot[0] + 15, spineBot[1] + 15]];
  for (let a = aLeft; a <= aFront; a += 10) {
    let [px, py] = ellPt(ccx + 42, cBotY + 24, crx * 1.04, cry * 1.04, a);
    shadowPoly.push([px, py]);
  }
  rShape(shadowPoly, 0.2, true);
  brush.noFill();

  // --- B. Intact Curved Exterior Side Wall (from angle -25° down to aFront=104°) ---
  let sideWallPoly = [];
  for (let a = -18; a <= aFront; a += 6) {
    sideWallPoly.push(ellPt(ccx, cTopY, crx, cry, a));
  }
  for (let a = aFront; a >= -18; a -= 6) {
    sideWallPoly.push(ellPt(ccx, cBotY, crx, cry, a));
  }

  brush.noStroke();
  brush.wash("#d8c6a8", 235);
  rShape(sideWallPoly, 0.15, true);
  brush.noWash();

  // Shading on curved right side wall (darker warm umber-ochre toward the right away from window)
  brush.fillBleed(0.18, "out");
  brush.fill("#9e8667", 145);
  rShape(sideWallPoly, 0.15, true);

  let rightDeepShadow = [];
  for (let a = -15; a <= 65; a += 8) {
    rightDeepShadow.push(ellPt(ccx, cTopY, crx, cry, a));
  }
  for (let a = 65; a >= -15; a -= 8) {
    rightDeepShadow.push(ellPt(ccx, cBotY, crx, cry, a));
  }
  brush.fill("#6e583f", 135);
  rShape(rightDeepShadow, 0.15, true);
  brush.noFill();

  // Swirled buttercream troughs on the exterior side wall
  for (let i = 0; i < 48; i++) {
    let a1 = random(-15, aFront - 18);
    let a2 = a1 + random(12, 28);
    let yf = random(0.08, 0.92);
    let y1 = lerp(cTopY, cBotY, yf);
    let y2 = y1 + random(-22, 22);
    let p1 = ellPt(ccx, y1, crx, cry, a1);
    let p2 = ellPt(ccx, (y1 + y2) * 0.5, crx + 5, cry + 3, (a1 + a2) * 0.5);
    let p3 = ellPt(ccx, y2, crx, cry, a2);
    brush.set("cpencil", i % 2 === 0 ? "#f2e6cf" : "#6b543b", random(0.45, 0.85));
    rSpline([p1, p2, p3], 0.5);
  }

  // --- C. Two Interior Cut Faces (Upper-Left Face & Front-Left Face) ---
  // Face 1 (Upper-Left Cut): leftTop -> spineTop -> spineBot -> leftBot
  // Face 2 (Front-Left Cut): spineTop -> frontTop -> frontBot -> spineBot
  drawCutSpongeFace(leftTop, spineTop, spineBot, leftBot, false);
  drawCutSpongeFace(spineTop, frontTop, frontBot, spineBot, true);

  // Center vertical cut crease between the two faces
  brush.set("2B", "#4a2c14", 0.75);
  rSpline([
    spineTop,
    [lerp(spineTop[0], spineBot[0], 0.45) + 4, lerp(spineTop[1], spineBot[1], 0.45)],
    spineBot
  ], 0.35);

  // --- D. Top Frosting Surface of the Remaining Cake ---
  let topSurfacePoly = [
    [spineTop[0] - 4, spineTop[1] + 2]
  ];
  for (let a = aLeft; a <= aFront; a += 6) {
    topSurfacePoly.push(ellPt(ccx, cTopY, crx, cry, a));
  }

  brush.noStroke();
  brush.wash("#f0e5cf", 242);
  rShape(topSurfacePoly, 0.12, true);
  brush.noWash();

  // Subtle watercolor modelling across top buttercream (cool window light on left, warm butter shadow on right)
  brush.fillBleed(0.16, "out");
  brush.fill("#e8f0f2", 115);
  rShape([
    leftTop,
    ellPt(ccx, cTopY, crx, cry, -85),
    [775, 315],
    spineTop
  ], 0.25, true);

  brush.fill("#cbb693", 120);
  rShape([
    spineTop,
    ellPt(ccx, cTopY, crx, cry, -25),
    ellPt(ccx, cTopY, crx, cry, 55),
    frontTop
  ], 0.25, true);
  brush.noFill();

  // Hyperreal palette-knife buttercream swirls & ridges on top of cake
  for (let i = 0; i < 65; i++) {
    let a = random(aLeft + 8, aFront - 8);
    let r1 = random(0.08, 0.55);
    let r2 = r1 + random(0.2, 0.42);
    let p1 = ellPt(ccx, cTopY, crx * r1, cry * r1, a);
    let p2 = ellPt(ccx, cTopY, crx * ((r1 + r2) * 0.5), cry * ((r1 + r2) * 0.5), a + random(-24, 24));
    let p3 = ellPt(ccx, cTopY, crx * r2, cry * r2, a + random(-35, 35));

    // Shadow side of frosting ridge
    brush.set("2B", "#8f7a5c", random(0.32, 0.65));
    rSpline([p1, p2, p3], 0.55);

    // Bright window-lit crest of frosting ridge
    brush.set("cpencil", "#faf6ed", random(0.45, 0.85));
    rSpline([
      [p1[0] - 3, p1[1] - 2],
      [p2[0] - 3, p2[1] - 2],
      [p3[0] - 3, p3[1] - 2]
    ], 0.55);
  }

  // Overhanging thick cut buttercream lip along the two cut edges
  drawFrostingCutLip(leftTop, spineTop, 11);
  drawFrostingCutLip(spineTop, frontTop, 9);

  // Piped buttercream shell border along the intact outer rim (top and base)
  for (let a = aLeft + 4; a <= aFront - 4; a += 9) {
    let [tx, ty] = ellPt(ccx, cTopY, crx - 4, cry - 3, a);
    brush.set("cpencil", "#bfa886", 0.75);
    rEllipse(tx + 3, ty + 3, 15, 10, 14, 0.4, 1.2, a * 0.4);
    brush.set("cpencil", "#faf5eb", 0.85);
    rEllipse(tx - 2, ty - 2, 13, 8, 14, 0.4, 1.0, a * 0.4);
  }
  for (let a = -8; a <= aFront - 4; a += 9) {
    let [bx, by] = ellPt(ccx, cBotY, crx + 4, cry + 3, a);
    brush.set("cpencil", "#8a7355", 0.75);
    rEllipse(bx + 2, by + 2, 14, 9, 14, 0.4, 1.2, a * 0.3);
    brush.set("cpencil", "#e8d9be", 0.75);
    rEllipse(bx - 2, by - 1, 12, 8, 14, 0.4, 1.0, a * 0.3);
  }

  // --- E. Collapsed / Half-Eaten Sponge Chunk & Crumb Avalanche at the Cutout Base ---
  drawCollapsedSpongeAndCrumbs(spineBot, leftBot, frontBot);

  // Colored sugar sprinkles on top frosting and fallen onto foil
  let sprinkleCols = ["#d15858", "#d99b38", "#6e9987", "#c77390", "#e6d2a2"];
  for (let i = 0; i < 75; i++) {
    let a = random(aLeft + 6, aFront - 6);
    let rr = random(0.12, 0.94);
    let [sx, sy] = ellPt(ccx, cTopY, crx * rr, cry * rr, a);
    let ang = random(0, 180);
    let dx = Math.cos((ang * Math.PI) / 180) * 4.5;
    let dy = Math.sin((ang * Math.PI) / 180) * 4.5;
    brush.set("fine_graphite", "#594836", 0.45);
    rLine(sx - dx + 1, sy - dy + 1.5, sx + dx + 1, sy + dy + 1.5);
    brush.set("cpencil", random(sprinkleCols), 0.65);
    rLine(sx - dx, sy - dy, sx + dx, sy + dy);
  }
}

// Helper to draw one interior vertical cut face of the half-eaten sponge cake
function drawCutSpongeFace(topA, topB, botB, botA, isFrontFace) {
  // Helper to bilinearly interpolate (u in 0..1 across width, v in 0..1 down height)
  function facePt(u, v) {
    let tx = lerp(topA[0], topB[0], u);
    let ty = lerp(topA[1], topB[1], u);
    let bx = lerp(botA[0], botB[0], u);
    let by = lerp(botA[1], botB[1], u);
    return [lerp(tx, bx, v), lerp(ty, by, v)];
  }

  // 1. Base golden sponge wash
  brush.noStroke();
  brush.wash(isFrontFace ? "#d99d48" : "#c48633", 235);
  rShape([topA, topB, botB, botA], 0.08, true);
  brush.noWash();

  // 2. Watercolor variation for baked crust & moist sponge interior
  brush.fillBleed(0.15, "in");
  brush.fill(isFrontFace ? "#e8b96b" : "#d49b4b", 130);
  rShape([facePt(0.06, 0.12), facePt(0.94, 0.12), facePt(0.94, 0.45), facePt(0.06, 0.45)], 0.1, true);

  brush.fill(isFrontFace ? "#b87624" : "#965b15", 135);
  rShape([facePt(0.04, 0.56), facePt(0.96, 0.56), facePt(0.96, 0.96), facePt(0.04, 0.96)], 0.1, true);

  // 3. Middle Filling Layer (Buttercream ribbon + Crimson Raspberry Jam at v = 0.46..0.58)
  let creamRibbon = [];
  let jamRibbon = [];
  for (let s = 0; s <= 12; s++) {
    let u = s / 12;
    let wave = 0.015 * Math.sin(s * 1.4);
    creamRibbon.push(facePt(u, 0.44 + wave));
    jamRibbon.push(facePt(u, 0.48 + wave));
  }
  for (let s = 12; s >= 0; s--) {
    let u = s / 12;
    let wave = 0.018 * Math.cos(s * 1.7);
    creamRibbon.push(facePt(u, 0.51 + wave));
    jamRibbon.push(facePt(u, 0.57 + wave));
  }

  brush.fill("#f0e3c7", 210);
  rShape(creamRibbon, 0.25, true);

  brush.fill("#6e121a", 215);
  rShape(jamRibbon, 0.25, true);
  brush.noFill();

  // 4. Porous Sponge Crumb Texture (crumb_spray + colored pencil + graphite pores)
  let spongeCols = isFrontFace
    ? ["#f2cc85", "#e0a64c", "#b57422", "#874e10", "#fae0a8"]
    : ["#dfb267", "#bd7e2c", "#915814", "#6b3c08", "#ebd098"];

  for (let i = 0; i < 95; i++) {
    let u = random(0.04, 0.96);
    let v = random() < 0.5 ? random(0.11, 0.44) : random(0.58, 0.95);
    let [px, py] = facePt(u, v);
    brush.set("crumb_spray", random(spongeCols), random(0.45, 0.95));
    rLine(px, py, px + random(-14, 14), py + random(-8, 8));
  }

  // Tiny dark air pockets (vesicles) in the baked sponge crumb
  for (let i = 0; i < 110; i++) {
    let u = random(0.05, 0.95);
    let v = random() < 0.5 ? random(0.11, 0.44) : random(0.58, 0.95);
    let [px, py] = facePt(u, v);
    brush.set("fine_graphite", "#5c340e", random(0.45, 0.85));
    rEllipse(px, py, random(1.2, 3.6), random(0.9, 2.5), 8, 0.3, 0.4);
  }

  // Vertical knife-cut drag marks down the sponge
  for (let i = 0; i < 18; i++) {
    let u = map(i, 0, 17, 0.08, 0.92);
    let p1 = facePt(u, 0.12);
    let p2 = facePt(u + random(-0.02, 0.02), 0.94);
    brush.set("2H", "#7d4916", 0.32);
    rLine(p1[0], p1[1], p2[0], p2[1]);
  }

  // Glossy raspberry jam highlights and seeds
  for (let i = 0; i < 22; i++) {
    let u = random(0.05, 0.95);
    let [jx, jy] = facePt(u, random(0.49, 0.56));
    brush.set("cpencil", i % 3 === 0 ? "#f7d7da" : "#ad2430", random(0.4, 0.75));
    rLine(jx - 5, jy, jx + 5, jy + 1);
  }

  // Caramelized golden-brown bottom & outer crust edges
  brush.set("2B", "#4f2b0d", 0.65);
  rLine(botA[0], botA[1], botB[0], botB[1]);
}

// Helper for overhanging cut buttercream lip at top of cut faces
function drawFrostingCutLip(pA, pB, steps) {
  let lipPts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    lipPts.push([lerp(pA[0], pB[0], t), lerp(pA[1], pB[1], t) - 4]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let sag = 19 + 6 * Math.sin(i * 1.9);
    lipPts.push([lerp(pA[0], pB[0], t), lerp(pA[1], pB[1], t) + sag]);
  }
  brush.noStroke();
  brush.wash("#efe3cc", 235);
  rShape(lipPts, 0.3, true);
  brush.noWash();

  brush.set("2B", "#786449", 0.48);
  rSpline(lipPts.slice(steps + 1), 0.4);
  brush.set("cpencil", "#fcf8f0", 0.65);
  rSpline(lipPts.slice(0, steps + 1), 0.4);
}

