// ============================================================================
// 7. BLOWN-OUT CANDLES, WAX DRIPS & SOFT CHARCOAL SMOKE SMEARS
// ============================================================================
function drawCandlesAndSmoke() {
  let candles = [
    { x: 618, y: 298, h: 132, lean: -5, col: "#d16266", dripEdge: true },
    { x: 718, y: 268, h: 146, lean: 2.5, col: "#d99836", dripEdge: false },
    { x: 792, y: 342, h: 126, lean: 6.5, col: "#c45637", dripEdge: true },
    { x: 882, y: 302, h: 140, lean: -3, col: "#769482", dripEdge: false },
    { x: 852, y: 428, h: 118, lean: 4.5, col: "#d16266", dripEdge: false }
  ];

  // --- First: Draw Soft Charcoal Smoke Smears Rising from Each Candle Wick ---
  for (let idx = 0; idx < candles.length; idx++) {
    let c = candles[idx];
    let rad = (c.lean * Math.PI) / 180;
    let topX = c.x + Math.sin(rad) * c.h;
    let topY = c.y - Math.cos(rad) * c.h;
    let wickX = topX + 2;
    let wickY = topY - 13;

    drawCandleSmokePlume(wickX, wickY, idx);
  }

  // --- Second: Draw Candles, Melted Wax Rosettes, Wax Drips & Glowing Wicks ---
  for (let idx = 0; idx < candles.length; idx++) {
    let c = candles[idx];
    let rad = (c.lean * Math.PI) / 180;
    let topX = c.x + Math.sin(rad) * c.h;
    let topY = c.y - Math.cos(rad) * c.h;
    let w = 9.5;

    // Cast shadow of candle across top buttercream frosting (towards the right)
    brush.set("2B", "#8a7456", 0.85);
    rLine(c.x + 4, c.y + 2, c.x + 88, c.y + 18);

    // Pooled wax & buttercream rosette at base of candle
    brush.noStroke();
    brush.wash("#f5ecda", 220);
    rEllipse(c.x, c.y + 2, 19, 12, 18, 0.35, 1.2);
    brush.wash(c.col, 155);
    rEllipse(c.x, c.y, 14, 9, 16, 0.35, 1.0);

    // Candle cylinder body
    let cPoly = [
      [c.x - w, c.y],
      [c.x + w, c.y],
      [topX + w * 0.92, topY],
      [topX - w * 0.92, topY]
    ];
    brush.wash("#f4ebd9", 242);
    rShape(cPoly, 0.06, true);
    brush.noWash();

    // Diagonal colored spiral stripes up the candle
    let numStripes = 6;
    for (let s = 0; s < numStripes; s++) {
      let f1 = s / numStripes;
      let f2 = (s + 0.55) / numStripes;
      if (f2 > 1) continue;
      let sx1 = lerp(c.x, topX, f1) - w * 0.9;
      let sy1 = lerp(c.y, topY, f1);
      let sx2 = lerp(c.x, topX, f2) + w * 0.9;
      let sy2 = lerp(c.y, topY, f2);
      brush.set("cpencil", c.col, 1.05);
      rLine(sx1, sy1, sx2, sy2);
      rLine(sx1, sy1 - 3, sx2, sy2 - 3);
    }

    // Candle shading (right side shadow, left side cool window highlight)
    brush.set("2B", "#6e5c49", 0.52);
    rLine(c.x + w, c.y, topX + w * 0.92, topY);
    rLine(c.x - w, c.y, topX - w * 0.92, topY);

    brush.set("cpencil", "#ffffff", 0.65);
    rLine(c.x - w * 0.65, c.y - 2, topX - w * 0.65, topY + 2);

    // Melted concave wax cup at top of candle
    brush.noStroke();
    brush.wash("#fcf6ea", 235);
    rEllipse(topX, topY, w * 1.05, 5.5, 16, 0.35, 0.6);
    brush.noWash();

    // Hyperreal Wax Drips running down the candle shaft & pooling at base
    for (let d = 0; d < 4; d++) {
      let dxOff = map(d, 0, 3, -w * 0.75, w * 0.75);
      let dripLen = random(0.32, 0.95);
      let endX = lerp(topX, c.x, dripLen) + dxOff;
      let endY = lerp(topY, c.y, dripLen);

      // Shadow behind wax drip
      brush.set("fine_graphite", "#5e4c3a", 0.55);
      rSpline([
        [topX + dxOff + 1.2, topY + 2],
        [(topX + endX) * 0.5 + dxOff + 2, (topY + endY) * 0.5],
        [endX + 1.2, endY + 2]
      ], 0.4);

      // Translucent wax rivulet & tear-drop bulb
      brush.set("cpencil", d % 2 === 0 ? "#fbf6eb" : c.col, 0.72);
      rSpline([
        [topX + dxOff, topY + 1],
        [(topX + endX) * 0.5 + dxOff, (topY + endY) * 0.5],
        [endX, endY]
      ], 0.4);

      brush.noStroke();
      brush.wash(d % 2 === 0 ? "#fcf8f0" : c.col, 220);
      rEllipse(endX, endY, 3.8, 5.2, 12, 0.35, 0.3);
      brush.noWash();

      // Tiny specular window-light glint on each wax droplet
      brush.set("cpencil", "#ffffff", 0.55);
      rLine(endX - 1.5, endY - 2, endX - 1.5, endY + 0.5);
    }

    // Extra wax drips cascading over the cut cake edge beneath C1 and C3
    if (c.dripEdge) {
      let edgeX = c.x - 8;
      let edgeY = c.y + 42;
      brush.set("fine_graphite", "#4f361b", 0.6);
      rSpline([[c.x - 4, c.y + 6], [edgeX + 2, edgeY + 18], [edgeX + 2, edgeY + 54]], 0.35);
      brush.set("cpencil", c.col, 0.85);
      rSpline([[c.x - 5, c.y + 5], [edgeX, edgeY + 16], [edgeX, edgeY + 52]], 0.35);
      brush.set("cpencil", "#fffaf0", 0.55);
      rLine(edgeX - 1.5, edgeY + 22, edgeX - 1.5, edgeY + 50);
    }

    // Blackened curled wick just blown out
    let wickTopX = topX + 2.5;
    let wickTopY = topY - 14;
    brush.set("charcoal", "#120f0e", 0.65);
    rSpline([
      [topX, topY],
      [topX - 2, topY - 8],
      [wickTopX, wickTopY]
    ], 0.45);

    // Dying pinpoint orange-red ember on the wick tip (seconds after being blown out!)
    if (idx === 0 || idx === 2 || idx === 4) {
      brush.noStroke();
      brush.fillBleed(0.25, "out");
      brush.fill("#ff4800", 180);
      rEllipse(wickTopX, wickTopY, 5.5, 5.5, 12, 0.3, 0);
      brush.noFill();

      brush.wash("#ffaa22", 240);
      rEllipse(wickTopX, wickTopY, 3.0, 3.0, 10, 0.3, 0);
      brush.wash("#fff3b0", 250);
      rEllipse(wickTopX, wickTopY, 1.5, 1.5, 8, 0.3, 0);
      brush.noWash();
    }
  }
}

// Helper for soft charcoal smoke smears and curling window-lit smoke ribbons
function drawCandleSmokePlume(wx, wy, idx) {
  let curvePts1 = [];
  let curvePts2 = [];
  let steps = 11;

  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    // Smoke rises and drifts to the right, widening into turbulent curls
    let driftX = Math.pow(t, 1.35) * (155 + idx * 18) + Math.sin(t * 5.2 + idx * 1.7) * (28 * t);
    let riseY = -t * (320 + (idx % 2) * 45);
    let px = wx + driftX;
    let py = wy + riseY;
    let spread = 3 + Math.pow(t, 1.25) * 46;

    curvePts1.push([px - spread * 0.45, py, 0.3 + t * 0.9]);
    curvePts2.push([px + spread * 0.55, py + 6 * t, 0.25 + t * 0.85]);

    // Soft translucent watercolor smoke veil in upper plume
    if (s >= 2 && s <= 9) {
      brush.noStroke();
      brush.fillBleed(0.35, "out");
      brush.fill(s % 2 === 0 ? "#8e979c" : "#595552", 34);
      rEllipse(px, py, spread * 1.15, spread * 0.85, 16, 0.4, 3, -25);
      brush.noFill();
    }
  }

  // Broad, velvety charcoal smears (dark charcoal core + grey window-lit smoke edge)
  brush.set("smudge", "#2b2623", random(0.85, 1.35));
  rSpline(curvePts2, 0.65);

  brush.set("smudge", "#b0bbc0", random(0.75, 1.2));
  rSpline(curvePts1, 0.65);

  brush.set("charcoal", "#45403d", 0.55);
  rSpline(curvePts2.slice(1, 9), 0.6);

  brush.set("charcoal", "#cfd9de", 0.48);
  rSpline(curvePts1.slice(0, 8), 0.6);

  // Crisp laminar thread right above the hot wick
  brush.set("cpencil", "#e4edf0", 0.52);
  rSpline(curvePts1.slice(0, 5), 0.55);
  brush.set("2H", "#8f999e", 0.38);
  rSpline(curvePts2.slice(0, 5), 0.55);

  // Delicate vector-field smoke tendrils curling off the main plume
  brush.field("smoke_drift");
  for (let f = 0; f < 9; f++) {
    let pick = curvePts1[int(random(2, 9))];
    let [rx, ry] = R(pick[0] + random(-18, 18), pick[1] + random(-15, 15));
    brush.set(f % 2 === 0 ? "charcoal" : "cpencil", f % 2 === 0 ? "#66625e" : "#c7d1d6", random(0.28, 0.52));
    brush.flowLine(rx, ry, random(55, 145), -65 + TILT + random(-18, 18));
  }
  brush.noField();
}

