    if (i % 3 === 0) {
      brush.set("smudge", col, random(0.55, 1.15));
    } else {
      brush.set("charcoal", col, random(0.32, 0.68));
    }
    rLine(bx, by, bx + bLen, by - bLen * 0.28);
  }

  // --- C. Overall Pencil Grain & Stipple Mimicking Film Emulsion ---
  // Fine diagonal 2H/HB graphite cross-grain in shadow and midtone zones
  brush.hatchStyle("2H", "#2e241d", 0.24);
  brush.hatch(14, 32 + TILT, { rand: 0.22 });
  brush.noStroke();
  rShape([[-120, -120], [1320, -120], [1320, 1320], [-120, 1320]], 0.02, true);
  brush.noHatch();

  // Film-grain stipple across the entire canvas using crumb_spray and fine_graphite
  for (let i = 0; i < 240; i++) {
    let gx = random(-40, 1240);
    let gy = random(-40, 1240);
    let gLen = random(8, 38);
    let isLightGrain = random() < 0.42;
    let gCol = isLightGrain
      ? random(["#e8dfd0", "#d4dce0", "#f2e8d5"])
      : random(["#2b211b", "#45362c", "#5e4b3c", "#1c1512"]);
    brush.set("crumb_spray", gCol, random(0.28, 0.62));
    rLine(gx, gy, gx + gLen, gy + random(-12, 12));
  }
}

