// =============================================================================
// GEOMETRY & BRUSH STATE HELPERS
// =============================================================================

function cleanPts(pts, minDistSq = 2.0) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy >= minDistSq) {
      out.push(pts[i]);
    }
  }
  if (out.length > 2) {
    let f = out[0];
    let l = out[out.length - 1];
    if ((f[0] - l[0]) ** 2 + (f[1] - l[1]) ** 2 < minDistSq) {
      out.pop();
    }
  }
  return out;
}

function resetBrushModes() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
}

function watercolorPoly(pts, col, opacity, bleed = 0.12, tex = 0.55, border = 0.45, curv = 0.25) {
  let cPts = cleanPts(pts);
  if (cPts.length < 3) return;
  resetBrushModes();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  resetBrushModes();
}

function washPoly(pts, col, opacity, curv = 0.25) {
  let cPts = cleanPts(pts);
  if (cPts.length < 3) return;
  resetBrushModes();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  resetBrushModes();
}

function strokePoly(pts, brushName, col, weight, close = true, curv = 0.25) {
  let cPts = cleanPts(pts);
  if (cPts.length < 2) return;
  resetBrushModes();
  brush.set(brushName, col, weight);
  if (close && cPts.length >= 3) {
    brush.beginShape(curv);
    for (let i = 0; i < cPts.length; i++) {
      brush.vertex(cPts[i][0], cPts[i][1]);
    }
    brush.endShape(true);
  } else {
    brush.spline(cPts, curv);
  }
  resetBrushModes();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts = { rand: 0.05 }, curv = 0.2) {
  let cPts = cleanPts(pts);
  if (cPts.length < 3) return;
  resetBrushModes();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < cPts.length; i++) {
    brush.vertex(cPts[i][0], cPts[i][1]);
  }
  brush.endShape(true);
  resetBrushModes();
}

function drawReservedIcing(pts, curv = 0.3) {
  let cPts = cleanPts(pts);
  if (cPts.length < 3) return;

  // 1. Subtle warm honey-umber contact shadow right under the icing rim
  let shadowPts = cPts.map(p => [p[0] + 2.2, p[1] + 2.8]);
  watercolorPoly(shadowPts, PAL.cassiaDark, 55, 0.08, 0.4, 0.5, curv);

  // 2. Opaque reserved-paper wash so the icing reads as untouched cream rag paper
  washPoly(cPts, PAL.icingPaper, 248, curv);

  // 3. Soft internal cream highlight & very faint cool grey modelling near edges
  watercolorPoly(cPts, PAL.icingBright, 90, 0.02, 0.2, 0.2, curv);
  hatchPoly(cPts, "cool_pencil", PAL.coolGreyPale, 0.65, 5.5, -32, { rand: 0.04, gradient: 0.65 }, curv);

  // 4. Crisp cool grey pencil contour edging (the signature scientific plate treatment)
  strokePoly(cPts, "cool_pencil", PAL.coolGreyMid, 0.95, true, curv);

  // 5. Darker cool-grey pencil accent along the lower/right overhanging meniscus
  let lowerArc = [];
  for (let i = 0; i < cPts.length; i++) {
    let next = cPts[(i + 1) % cPts.length];
    let dx = next[0] - cPts[i][0];
    let dy = next[1] - cPts[i][1];
    if (dx - dy < 0.5) {
      lowerArc.push(cPts[i]);
    } else if (lowerArc.length >= 3) {
      strokePoly(lowerArc, "cool_pencil", PAL.coolGreyDark, 1.05, false, curv);
      lowerArc = [];
    } else {
      lowerArc = [];
    }
  }
  if (lowerArc.length >= 3) {
    strokePoly(lowerArc, "cool_pencil", PAL.coolGreyDark, 1.05, false, curv);
  }

  // 6. Specular sugar-glaze highlight along top-left icing ridges
  let upperArc = [];
  for (let i = 0; i < cPts.length; i++) {
    let next = cPts[(i + 1) % cPts.length];
    let dx = next[0] - cPts[i][0];
    let dy = next[1] - cPts[i][1];
    if (dx - dy > 1.5 && (i % 5 !== 0)) {
      upperArc.push([cPts[i][0] + 1.5, cPts[i][1] + 1.5]);
    } else if (upperArc.length >= 2) {
      strokePoly(upperArc, "gloss_nib", PAL.glossWhite, 0.75, false, 0.3);
      upperArc = [];
    } else {
      upperArc = [];
    }
  }
}

