// =============================================================================
// FIG. 1: TOP SPIRAL (APICAL VIEW)
// =============================================================================

function spiralRadiusFig1(theta) {
  // 3.65 turns from theta = 0 to 1314 deg
  let t = constrain(theta / 1314, 0, 1);
  let baseR = 8 + 166 * pow(t, 0.88);
  // Natural baked brioche lobing & harmonic undulation
  let lobe =
    4.5 * sin(theta * 3 + 25) * t +
    3.2 * cos(theta * 2 - 40) * t +
    2.4 * sin(theta * 5 + 110) * pow(t, 1.4) +
    6.0 * (noise(cos(theta) * 0.8 + 10, sin(theta) * 0.8 + 10, theta * 0.002) - 0.5) * (0.3 + t);
  return max(4, baseR + lobe);
}

function drawFig1TopSpiral(cx, cy) {
  // 1. Graphite Conchological Construction Underlayer (axes, logarithmic spiral extension, ticks)
  resetBrushModes();
  brush.set("2H", PAL.graphiteLight, 0.35);
  brush.line(cx - 210, cy, cx + 215, cy);
  brush.line(cx, cy - 205, cx, cy + 205);
  brush.line(cx - 150, cy - 150, cx + 155, cy + 155);

  // Dotted geometric reference arc outside the shell
  for (let a = -45; a <= 75; a += 5) {
    let r = spiralRadiusFig1(1314) + 18;
    brush.line(cx + cos(a) * r, cy + sin(a) * r, cx + cos(a + 2.5) * r, cy + sin(a + 2.5) * r);
  }
  // Caliper ticks
  brush.line(cx - 180, cy - 5, cx - 180, cy + 5);
  brush.line(cx + 182, cy - 5, cx + 182, cy + 5);

  // 2. Sharp High-Contrast Cast Shadow (Bottom-Right)
  let outerOutline = [];
  for (let a = 0; a < 360; a += 6) {
    let th = 954 + a;
    let r = spiralRadiusFig1(th);
    outerOutline.push([cx + cos(th) * r, cy + sin(th) * r]);
  }
  let shadowOuter = outerOutline.map(p => [p[0] + 24, p[1] + 28]);
  let shadowMid = outerOutline.map(p => [p[0] + 15, p[1] + 18]);
  let shadowCore = outerOutline.map(p => [p[0] + 8, p[1] + 10]);

  watercolorPoly(shadowOuter, PAL.shadowSoft, 115, 0.22, 0.55, 0.35, 0.3);
  watercolorPoly(shadowMid, PAL.shadowMid, 165, 0.12, 0.6, 0.5, 0.3);
  watercolorPoly(shadowCore, PAL.shadowCore, 210, 0.05, 0.45, 0.65, 0.3);
  hatchPoly(shadowMid, "2B", PAL.umberDeep, 0.5, 4.5, 38, { rand: 0.05 }, 0.25);

  // 3. Base Dough Watercolour Glaze (Translucent Honey across whole specimen)
  watercolorPoly(outerOutline, PAL.honeyLight, 150, 0.1, 0.45, 0.35, 0.3);

  // 4. Spiral Coil Wedges (Batched by Color for Rich Glazing)
  let maxTh = 1314;
  let stepTh = 36;
  let honeyWedges = [];
  let cassiaWedges = [];
  let umberSutureBands = [];
  let coilCrossContours = [];

  for (let th = 0; th < maxTh; th += stepTh) {
    let th2 = min(maxTh, th + stepTh);
    let rOut1 = spiralRadiusFig1(th);
    let rOut2 = spiralRadiusFig1(th2);
    let rIn1 = th >= 360 ? spiralRadiusFig1(th - 360) : 0;
    let rIn2 = th2 >= 360 ? spiralRadiusFig1(th2 - 360) : 0;

    let pOut1 = [cx + cos(th) * rOut1, cy + sin(th) * rOut1];
    let pOutMid = [cx + cos((th + th2) * 0.5) * ((rOut1 + rOut2) * 0.5), cy + sin((th + th2) * 0.5) * ((rOut1 + rOut2) * 0.5)];
    let pOut2 = [cx + cos(th2) * rOut2, cy + sin(th2) * rOut2];
    let pIn2 = [cx + cos(th2) * rIn2, cy + sin(th2) * rIn2];
    let pInMid = [cx + cos((th + th2) * 0.5) * ((rIn1 + rIn2) * 0.5), cy + sin((th + th2) * 0.5) * ((rIn1 + rIn2) * 0.5)];
    let pIn1 = [cx + cos(th) * rIn1, cy + sin(th) * rIn1];

    let wedge = [pOut1, pOutMid, pOut2, pIn2, pInMid, pIn1];
    honeyWedges.push({ pts: wedge, th: th });

    // Outer 55% of each coil gets a warm Cassia-Brown glaze for cylindrical 3D volume
    let rMid1 = lerp(rIn1, rOut1, 0.45);
    let rMid2 = lerp(rIn2, rOut2, 0.45);
    let pMid1 = [cx + cos(th) * rMid1, cy + sin(th) * rMid1];
    let pMid2 = [cx + cos(th2) * rMid2, cy + sin(th2) * rMid2];
    cassiaWedges.push({
      pts: [pOut1, pOutMid, pOut2, pMid2, pMid1],
      lightFactor: sin(th - 45) // darker on bottom-right
    });

    // Suture trench band along the outer seam of each coil
    let sWidth1 = map(th, 0, maxTh, 3.5, 11.5) * (0.85 + 0.35 * noise(th * 0.03));
    let sWidth2 = map(th2, 0, maxTh, 3.5, 11.5) * (0.85 + 0.35 * noise(th2 * 0.03));
    let pSut1 = [cx + cos(th) * max(2, rOut1 - sWidth1), cy + sin(th) * max(2, rOut1 - sWidth1)];
    let pSut2 = [cx + cos(th2) * max(2, rOut2 - sWidth2), cy + sin(th2) * max(2, rOut2 - sWidth2)];
    umberSutureBands.push([pOut1, pOutMid, pOut2, pSut2, pSut1]);

    // Cross-contour engraving lines across the plump dough coil
    for (let sub = 0; sub < 4; sub++) {
      let a = lerp(th, th2, sub / 4);
      let ro = spiralRadiusFig1(a);
      let ri = a >= 360 ? spiralRadiusFig1(a - 360) : 2;
      if (ro - ri > 8) {
        let rm = (ro + ri) * 0.5;
        let bend = a + 14;
        coilCrossContours.push([
          [cx + cos(a) * (ri + 2), cy + sin(a) * (ri + 2)],
          [cx + cos(bend) * rm, cy + sin(bend) * rm],
          [cx + cos(a) * (ro - 2), cy + sin(a) * (ro - 2)]
        ]);
      }
    }
  }

  // Batch render Honey Mid glazes
  for (let w of honeyWedges) {
    watercolorPoly(w.pts, PAL.honeyMid, 95, 0.14, 0.5, 0.35, 0.25);
  }
  // Batch render Cassia Brown volumetric shading
  for (let w of cassiaWedges) {
    let op = map(w.lightFactor, -1, 1, 80, 155);
    watercolorPoly(w.pts, PAL.cassiaMid, op, 0.16, 0.6, 0.45, 0.25);
    if (w.lightFactor > 0.1) {
      watercolorPoly(w.pts, PAL.cassiaDark, 95, 0.12, 0.55, 0.5, 0.25);
    }
  }

  // Graphite & sepia cross-contour hatching over the coils (under and over glaze look)
  resetBrushModes();
  for (let i = 0; i < coilCrossContours.length; i++) {
    let col = i % 2 === 0 ? PAL.graphiteMid : PAL.cassiaDark;
    let bName = i % 2 === 0 ? "2H" : "fine_quill";
    let w = i % 2 === 0 ? 0.38 : 0.55;
    strokePoly(coilCrossContours[i], bName, col, w, false, 0.35);
  }

  // Crispy browned outer edge shading on bottom-right rim
  let rimDarkPts = [];
  for (let a = -25; a <= 145; a += 8) {
    let th = 954 + ((a + 360) % 360);
    let r = spiralRadiusFig1(th);
    rimDarkPts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  for (let a = 145; a >= -25; a -= 8) {
    let th = 954 + ((a + 360) % 360);
    let r = spiralRadiusFig1(th) - 24;
    rimDarkPts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  watercolorPoly(rimDarkPts, PAL.umberMid, 130, 0.18, 0.65, 0.5, 0.25);

  // 5. Deep Sticky Cinnamon-Sugar Suture Trench (Burnt Umber High Contrast)
  for (let sb of umberSutureBands) {
    watercolorPoly(sb, PAL.umberDark, 185, 0.12, 0.65, 0.6, 0.25);
  }

  // Continuous dark molasses-cinnamon spiral core line & bubbling paste
  let sutureSpine = [];
  for (let th = 0; th <= maxTh; th += 12) {
    let r = spiralRadiusFig1(th) - map(th, 0, maxTh, 1.5, 4.5);
    sutureSpine.push([cx + cos(th) * r, cy + sin(th) * r]);
  }
  strokePoly(sutureSpine, "charcoal", PAL.umberDeep, 1.15, false, 0.3);
  strokePoly(sutureSpine, "fine_quill", PAL.umberDeep, 1.4, false, 0.3);

  // Granular cinnamon-sugar crust stipple along the suture
  resetBrushModes();
  brush.set("crumb_stipple", PAL.umberDark, 1.1);
  for (let i = 0; i < sutureSpine.length - 1; i += 2) {
    brush.line(sutureSpine[i][0], sutureSpine[i][1], sutureSpine[i + 1][0], sutureSpine[i + 1][1]);
  }
  resetBrushModes();

  // 6. Cream-Cheese Icing (Reserved Paper + Cool Grey Pencil Edging)
  // Main central whorl pool with 7 organic flowing lobes reaching across the spiral ridges
  let icingMainPts = [];
  let lobeAngles = [18, 68, 128, 185, 238, 292, 342];
  let lobeLengths = [165, 138, 178, 145, 168, 125, 152];
  let lobeWidths = [22, 18, 25, 19, 23, 17, 20];

  for (let a = 0; a < 360; a += 3) {
    let r = 36 + 6 * sin(a * 3) + 4 * cos(a * 5);
    for (let j = 0; j < lobeAngles.length; j++) {
      let diff = abs(((a - lobeAngles[j] + 540) % 360) - 180);
      let w = lobeWidths[j];
      if (diff < w) {
        let profile = pow(cos((diff / w) * 90), 1.6);
        // Swirl offset so the icing ribbons curve slightly with the dough
        let bulb = (diff < w * 0.45) ? 12 * sin((1 - diff / (w * 0.45)) * 180) : 0;
        r = max(r, 36 + (lobeLengths[j] - 36) * profile + bulb);
      }
    }
    let radA = a + 8 * sin(r * 0.04);
    icingMainPts.push([cx + cos(radA) * r, cy + sin(radA) * r]);
  }
  drawReservedIcing(icingMainPts, 0.32);

  // Secondary detached icing droplets & pools caught in the outer spiral suture
  let droplets = [
    { a: 44, r: 132, rx: 16, ry: 9, rot: 45 },
    { a: 98, r: 154, rx: 22, ry: 10, rot: 95 },
    { a: 158, r: 148, rx: 18, ry: 9, rot: 155 },
    { a: 214, r: 162, rx: 25, ry: 11, rot: 210 },
    { a: 318, r: 140, rx: 19, ry: 8, rot: 315 }
  ];
  for (let d of droplets) {
    let dPts = [];
    let dcx = cx + cos(d.a) * d.r;
    let dcy = cy + sin(d.a) * d.r;
    for (let t = 0; t < 360; t += 30) {
      let lx = cos(t) * d.rx * (0.85 + 0.25 * noise(t, d.a));
      let ly = sin(t) * d.ry * (0.85 + 0.25 * noise(t + 50, d.a));
      let rx = lx * cos(d.rot + 90) - ly * sin(d.rot + 90);
      let ry = lx * sin(d.rot + 90) + ly * cos(d.rot + 90);
      dPts.push([dcx + rx, dcy + ry]);
    }
    drawReservedIcing(dPts, 0.35);
  }

  // Delicate spiral flow creases inside the central icing pool (cool grey pencil)
  for (let ring = 14; ring <= 34; ring += 10) {
    let creasePts = [];
    for (let a = 20; a <= 290; a += 20) {
      creasePts.push([cx + cos(a) * ring, cy + sin(a) * ring]);
    }
    strokePoly(creasePts, "cool_pencil", PAL.coolGreyLight, 0.65, false, 0.35);
  }

  // 7. High-Contrast Wet Sugar Crust Gloss (Bright White Reflections on Burnt Umber & Honey Ridges)
  resetBrushModes();
  for (let th = 180; th < maxTh - 40; th += 52) {
    let rSuture = spiralRadiusFig1(th) - 2.5;
    let glossArc = [];
    for (let da = 0; da <= 22; da += 5) {
      let a = th + da;
      let rr = spiralRadiusFig1(a) - 2.5;
      glossArc.push([cx + cos(a) * rr, cy + sin(a) * rr]);
    }
    strokePoly(glossArc, "gloss_nib", PAL.glossWhite, random(0.65, 1.15), false, 0.3);

    // Ridge highlight on top-left facing dough crowns
    if (cos(th + 45) < 0.2) {
      let rCrown = spiralRadiusFig1(th) - 16;
      if (rCrown > 42) {
        let crownArc = [
          [cx + cos(th) * rCrown, cy + sin(th) * rCrown],
          [cx + cos(th + 10) * (rCrown + 1), cy + sin(th + 10) * (rCrown + 1)],
          [cx + cos(th + 20) * rCrown, cy + sin(th + 20) * rCrown]
        ];
        strokePoly(crownArc, "gloss_nib", PAL.glossWarm, 0.85, false, 0.3);
      }
    }
  }
}

// =============================================================================
// FIG. 2: UNDERSIDE CARAMEL BASE (BASAL VIEW)
// =============================================================================

function spiralRadiusFig2(theta) {
  // Inverted specimen: spirals counter-clockwise
  let t = constrain(theta / 1260, 0, 1);
  let baseR = 9 + 156 * pow(t, 0.9);
  let lobe =
    4.0 * sin(theta * 3 - 20) * t +
    3.5 * cos(theta * 4 + 50) * t +
    5.5 * (noise(cos(theta) * 0.9 + 40, sin(theta) * 0.9 + 40, theta * 0.002) - 0.5);
  return max(4, baseR + lobe);
}

function drawFig2CaramelBase(cx, cy) {
  // 1. Graphite Construction Underlayer
  resetBrushModes();
  brush.set("2H", PAL.graphiteLight, 0.35);
  brush.line(cx - 210, cy, cx + 210, cy);
  brush.line(cx, cy - 205, cx, cy + 205);

  // 2. Brittle Translucent Caramel Flange / Skirt Halo (melted sugar spread on baking pan)
  let skirtPts = [];
  let baseOutline = [];
  for (let a = 0; a < 360; a += 5) {
    let th = 900 + a;
    let rBase = spiralRadiusFig2(th);
    baseOutline.push([cx + cos(-a) * rBase, cy + sin(-a) * rBase]);

    // Irregular glassy sugar flange sticking out around the base
    let flangeExtra = 10 + 14 * pow(noise(cos(a) * 1.4 + 20, sin(a) * 1.4 + 20), 1.6);
    if (sin(a * 4 + 15) > 0.3) flangeExtra += 8 * sin(a * 4 + 15);
    let rSkirt = rBase + flangeExtra;
    skirtPts.push([cx + cos(-a) * rSkirt, cy + sin(-a) * rSkirt]);
  }

  // Sharp dark cast shadow under the brittle caramel skirt and base
  let shadowOuter = skirtPts.map(p => [p[0] + 22, p[1] + 26]);
  let shadowMid = skirtPts.map(p => [p[0] + 12, p[1] + 15]);
  let shadowCore = baseOutline.map(p => [p[0] + 10, p[1] + 12]);

  watercolorPoly(shadowOuter, PAL.shadowSoft, 120, 0.2, 0.55, 0.35, 0.3);
  watercolorPoly(shadowMid, PAL.shadowMid, 175, 0.1, 0.6, 0.55, 0.3);
  watercolorPoly(shadowCore, PAL.shadowCore, 220, 0.04, 0.5, 0.7, 0.3);

  // Translucent Honey & Cassia washes for the brittle sugar skirt
  watercolorPoly(skirtPts, PAL.honeyMid, 165, 0.08, 0.5, 0.6, 0.3);
  watercolorPoly(skirtPts, PAL.cassiaMid, 115, 0.12, 0.65, 0.7, 0.3);
  strokePoly(skirtPts, "fine_quill", PAL.umberDark, 0.75, true, 0.3);

  // 3. Flat-Baked Caramelized Base Spiral (High-Contrast Burnt Umber, Cassia & Honey Windows)
  watercolorPoly(baseOutline, PAL.honeyDeep, 175, 0.1, 0.5, 0.4, 0.3);

  let maxTh = 1260;
  let stepTh = 36;
  let darkCaramelWedges = [];
  let deepMolassesSeams = [];

  for (let th = 0; th < maxTh; th += stepTh) {
    let th2 = min(maxTh, th + stepTh);
    let rOut1 = spiralRadiusFig2(th);
    let rOut2 = spiralRadiusFig2(th2);
    let rIn1 = th >= 360 ? spiralRadiusFig2(th - 360) : 0;
    let rIn2 = th2 >= 360 ? spiralRadiusFig2(th2 - 360) : 0;

    // Counter-clockwise angles (-th) for flipped underside
    let a1 = -th;
    let aMid = -(th + th2) * 0.5;
    let a2 = -th2;

    let pOut1 = [cx + cos(a1) * rOut1, cy + sin(a1) * rOut1];
    let pOutMid = [cx + cos(aMid) * ((rOut1 + rOut2) * 0.5), cy + sin(aMid) * ((rOut1 + rOut2) * 0.5)];
    let pOut2 = [cx + cos(a2) * rOut2, cy + sin(a2) * rOut2];
    let pIn2 = [cx + cos(a2) * rIn2, cy + sin(a2) * rIn2];
    let pInMid = [cx + cos(aMid) * ((rIn1 + rIn2) * 0.5), cy + sin(aMid) * ((rIn1 + rIn2) * 0.5)];
    let pIn1 = [cx + cos(a1) * rIn1, cy + sin(a1) * rIn1];

    let nVal = noise(th * 0.025, 77);
    darkCaramelWedges.push({
      pts: [pOut1, pOutMid, pOut2, pIn2, pInMid, pIn1],
      darkness: nVal
    });

    // Fused caramel-molasses spiral suture on the flat bottom (wider and puddle-like)
    let seamW1 = map(th, 0, maxTh, 5, 19) * (0.7 + 0.6 * noise(th * 0.04, 12));
    let seamW2 = map(th2, 0, maxTh, 5, 19) * (0.7 + 0.6 * noise(th2 * 0.04, 12));
    let pS1 = [cx + cos(a1) * max(2, rOut1 - seamW1), cy + sin(a1) * max(2, rOut1 - seamW1)];
    let pS2 = [cx + cos(a2) * max(2, rOut2 - seamW2), cy + sin(a2) * max(2, rOut2 - seamW2)];
    deepMolassesSeams.push([pOut1, pOutMid, pOut2, pS2, pS1]);
  }

  // Wash Cassia Brown & Burnt Umber across the flat baked coils
  for (let w of darkCaramelWedges) {
    watercolorPoly(w.pts, PAL.cassiaDark, 150, 0.15, 0.65, 0.5, 0.25);
    if (w.darkness > 0.42) {
      watercolorPoly(w.pts, PAL.umberMid, 145, 0.16, 0.6, 0.55, 0.25);
    }
  }

  // Deep Burnt Umber puddles where caramel fused along the underside spiral sutures
  for (let s of deepMolassesSeams) {
    watercolorPoly(s, PAL.umberDeep, 195, 0.14, 0.7, 0.65, 0.25);
  }

  // Central umbilical caramel pool (darkest glossy heart of the underside)
  let centerPuddle = [];
  for (let a = 0; a < 360; a += 20) {
    let r = 34 + 12 * noise(cos(a) + 5, sin(a) + 5);
    centerPuddle.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  watercolorPoly(centerPuddle, PAL.umberDeep, 215, 0.12, 0.65, 0.6, 0.3);

  // 4. Radial Pan-Compression Creases & Fine Engraving Hatching
  resetBrushModes();
  for (let i = 0; i < 64; i++) {
    let a = i * (360 / 64) + random(-2, 2);
    let r1 = random(18, 85);
    let r2 = min(162, r1 + random(28, 65));
    let rMid = (r1 + r2) * 0.5;
    let crease = [
      [cx + cos(a) * r1, cy + sin(a) * r1],
      [cx + cos(a - 5) * rMid, cy + sin(a - 5) * rMid],
      [cx + cos(a - 8) * r2, cy + sin(a - 8) * r2]
    ];
    strokePoly(crease, i % 2 === 0 ? "fine_quill" : "2B", PAL.umberDeep, 0.55, false, 0.3);
  }

  // Reverse spiral suture line
  let revSuture = [];
  for (let th = 0; th <= maxTh; th += 14) {
    let r = spiralRadiusFig2(th) - 3;
    revSuture.push([cx + cos(-th) * r, cy + sin(-th) * r]);
  }
  strokePoly(revSuture, "charcoal", PAL.umberDeep, 1.1, false, 0.3);

  // 5. Small Overflow Lip of Cream-Cheese Icing Peeking from Top Side (Upper-Left Rim)
  let peekIcing = [];
  for (let a = 195; a <= 255; a += 6) {
    let r = spiralRadiusFig2(900 + (360 - a)) + 4;
    peekIcing.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  for (let a = 255; a >= 195; a -= 6) {
    let r = spiralRadiusFig2(900 + (360 - a)) + 18 + 8 * sin((a - 195) * 3);
    peekIcing.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  drawReservedIcing(peekIcing, 0.3);

  // 6. Hyperreal Caramelization Craters, Popped Sugar Blisters & Glassy Specular Gloss
  for (let i = 0; i < 48; i++) {
    let th = random(40, maxTh + 120);
    let r = th <= maxTh
      ? spiralRadiusFig2(th) - random(0, 14)
      : spiralRadiusFig2(maxTh) + random(2, 16);
    let bx = cx + cos(-th) * r;
    let by = cy + sin(-th) * r;
    let br = random(2.5, 8.5);

    let bubblePts = [];
    for (let a = 0; a < 360; a += 45) {
      bubblePts.push([bx + cos(a) * br, by + sin(a) * br * 0.85]);
    }
    if (br > 4.5) {
      watercolorPoly(bubblePts, PAL.honeyLight, 130, 0.05, 0.3, 0.5, 0.35);
    }
    strokePoly(bubblePts, "fine_quill", PAL.umberDeep, 0.75, true, 0.35);

    // Razor-sharp white crescent reflection on upper-left rim of each caramel blister
    let glint = [
      [bx + cos(195) * (br * 0.75), by + sin(195) * (br * 0.75)],
      [bx + cos(235) * (br * 0.8), by + sin(235) * (br * 0.8)],
      [bx + cos(275) * (br * 0.75), by + sin(275) * (br * 0.75)]
    ];
    strokePoly(glint, "gloss_nib", PAL.glossWhite, map(br, 2.5, 8.5, 0.45, 0.95), false, 0.3);
  }

  // Broad glassy specular streaks across the flat caramel glaze
  for (let th = 120; th < maxTh; th += 65) {
    let r = spiralRadiusFig2(th) - random(4, 18);
    let streak = [];
    for (let da = 0; da <= 28; da += 7) {
      let a = -(th + da);
      streak.push([cx + cos(a) * r, cy + sin(a) * r]);
    }
    strokePoly(streak, "gloss_nib", PAL.glossWhite, random(0.7, 1.25), false, 0.35);
  }
}

// =============================================================================
// FIG. 3: VERTICAL CROSS-SECTION (LONGITUDINAL SECTION)
// =============================================================================

function drawFig3CrossSection(cx, cy) {
  let halfW = 176;
  let topY = cy - 92;
  let botY = cy + 92;

  // 1. Graphite Conchological Section Guidelines (Axis of Columella & Base Plane)
  resetBrushModes();
  brush.set("2H", PAL.graphiteLight, 0.35);
  brush.line(cx, topY - 42, cx, botY + 38);
  brush.line(cx - halfW - 35, botY, cx + halfW + 35, botY);
  brush.line(cx - halfW, topY - 25, cx - halfW, botY + 20);
  brush.line(cx + halfW, topY - 25, cx + halfW, botY + 20);

  // 2. Sharp Cast Shadow under the Flat Caramelized Base & Right Flank
  let shadowBase = [
    [cx - halfW + 8, botY - 2],
    [cx + halfW + 26, botY - 2],
    [cx + halfW + 36, botY + 18],
    [cx + 20, botY + 24],
    [cx - halfW + 18, botY + 16]
  ];
  let shadowCore = [
    [cx - halfW + 10, botY],
    [cx + halfW + 16, botY],
    [cx + halfW + 20, botY + 10],
    [cx - halfW + 16, botY + 9]
  ];
  watercolorPoly(shadowBase, PAL.shadowSoft, 125, 0.18, 0.55, 0.35, 0.25);
  watercolorPoly(shadowCore, PAL.shadowCore, 215, 0.04, 0.45, 0.65, 0.2);

  // 3. Sectioned Loaf Silhouette & Base Translucent Honey Crumb Wash
  // 9 vertical lobes corresponding to the sectioned spiral chambers (-4..+4)
  let lobeBoundsX = [-176, -138, -100, -62, -24, 24, 62, 100, 138, 176];
  let loafOutline = [];

  // Top undulating crown
  for (let i = 0; i < 9; i++) {
    let x1 = cx + lobeBoundsX[i];
    let x2 = cx + lobeBoundsX[i + 1];
    let distFromCenter = abs(i - 4);
    let domeH = 22 - distFromCenter * 3.5;
    let yVal = topY + distFromCenter * 4.5;
    loafOutline.push([x1, yVal + 8]);
    loafOutline.push([(x1 + x2) * 0.5, yVal - domeH]);
  }
  loafOutline.push([cx + halfW, topY + 26]);
  // Right outer crust wall
  loafOutline.push([cx + halfW + 6, cy - 10]);
  loafOutline.push([cx + halfW + 2, cy + 48]);
  loafOutline.push([cx + halfW - 6, botY]);
  // Flat caramelized bottom
  for (let x = halfW - 30; x >= -halfW + 30; x -= 40) {
    loafOutline.push([cx + x, botY + 2 * sin(x * 2)]);
  }
  loafOutline.push([cx - halfW + 6, botY]);
  // Left outer crust wall
  loafOutline.push([cx - halfW - 2, cy + 48]);
  loafOutline.push([cx - halfW - 6, cy - 10]);
  loafOutline.push([cx - halfW, topY + 26]);

  // Base Pale & Golden Honey Wash for the Cut Brioche Crumb
  watercolorPoly(loafOutline, PAL.honeyPale, 195, 0.06, 0.45, 0.35, 0.25);
  watercolorPoly(loafOutline, PAL.honeyLight, 115, 0.12, 0.55, 0.4, 0.25);

  // 4. Individual Dough Chambers, Baked Crust Rim & Internal Cinnamon-Sugar Septa (Veins)
  let crumbChambers = [];
  let crustMargins = [];
  let cinnamonVeins = [];

  for (let i = 0; i < 9; i++) {
    let xL = lobeBoundsX[i];
    let xR = lobeBoundsX[i + 1];
    let xMid = (xL + xR) * 0.5;
    let distC = abs(i - 4);
    let signC = i < 4 ? -1 : (i > 4 ? 1 : 0);
    let yTop = topY + distC * 4.5 - (22 - distC * 3.5);

    // Slight C-curve bow showing how the dough sheet was rolled inward
    let bow = signC * (10 + distC * 2.5);

    let chamberPts = [
      [cx + xL + 4, yTop + 16],
      [cx + xMid, yTop + 4],
      [cx + xR - 4, yTop + 16],
      [cx + xR - 3 + bow, cy],
      [cx + xR - 5, botY - 8],
      [cx + xMid, botY - 5],
      [cx + xL + 5, botY - 8],
      [cx + xL + 3 + bow, cy]
    ];
    crumbChambers.push({ pts: chamberPts, idx: i, xMid: cx + xMid, yTop: yTop, bow: bow });

    // Golden-brown baked crust along the top dome and bottom of each chamber
    crustMargins.push([
      [cx + xL + 2, yTop + 20],
      [cx + xMid, yTop + 2],
      [cx + xR - 2, yTop + 20],
      [cx + xR - 4, yTop + 34],
      [cx + xMid, yTop + 18],
      [cx + xL + 4, yTop + 34]
    ]);
  }

  // Outer left and right crust walls
  crustMargins.push([
    [cx - halfW, topY + 24],
    [cx - halfW + 18, topY + 28],
    [cx - halfW + 14, botY - 4],
    [cx - halfW + 4, botY],
    [cx - halfW - 5, cy]
  ]);
  crustMargins.push([
    [cx + halfW, topY + 24],
    [cx + halfW + 5, cy],
    [cx + halfW - 4, botY],
    [cx + halfW - 14, botY - 4],
    [cx + halfW - 18, topY + 28]
  ]);

  // 8 Vertical/Curved Cinnamon-Sugar Veins between the 9 chambers
  for (let i = 1; i <= 8; i++) {
    let vx = lobeBoundsX[i];
    let signV = vx < 0 ? -1 : 1;
    let distV = abs(i - 4.5);
    let bow = signV * (9 + distV * 2.2);
    let yT = topY + distV * 4.2 + 8;

    let leftEdge = [];
    let rightEdge = [];
    for (let step = 0; step <= 10; step++) {
      let t = step / 10;
      let y = lerp(yT, botY - 4, t);
      let curveX = cx + vx + bow * sin(t * 180) + (noise(i * 10, step * 0.4) - 0.5) * 6;
      // Vein thickens into sticky pockets in the middle and at the base
      let halfThick = 3.2 + 2.8 * noise(i * 20, step * 0.6) + (t > 0.8 ? 4.5 * (t - 0.8) * 5 : 0);
      leftEdge.push([curveX - halfThick, y]);
      rightEdge.unshift([curveX + halfThick, y]);
    }
    cinnamonVeins.push(leftEdge.concat(rightEdge));
  }

  // Batch render Honey Mid & Cassia Crust washes
  for (let ch of crumbChambers) {
    watercolorPoly(ch.pts, PAL.honeyMid, 75, 0.1, 0.55, 0.35, 0.25);
  }
  for (let cm of crustMargins) {
    watercolorPoly(cm, PAL.cassiaMid, 145, 0.15, 0.6, 0.45, 0.25);
  }

  // Sticky Caramel Base Foot along the entire bottom of the cross-section
  let baseCaramelBand = [
    [cx - halfW + 6, botY - 12],
    [cx, botY - 10],
    [cx + halfW - 6, botY - 12],
    [cx + halfW - 4, botY + 2],
    [cx, botY + 3],
    [cx - halfW + 4, botY + 2]
  ];
  watercolorPoly(baseCaramelBand, PAL.cassiaDark, 175, 0.16, 0.65, 0.5, 0.2);
  watercolorPoly(baseCaramelBand, PAL.umberDeep, 195, 0.08, 0.6, 0.65, 0.2);

  // 5. Hyperreal Aerated Brioche Crumb Texture (Alveolar Pores & Stretched Gluten Network)
  resetBrushModes();
  for (let ch of crumbChambers) {
    let xCenter = ch.xMid;
    // Fine vertical-curved graphite hatching showing the stretched dough grain
    hatchPoly(ch.pts, "2H", PAL.honeyDeep, 0.42, 6.0, 88 - ch.bow * 0.8, { rand: 0.08 }, 0.25);

    // Cellular crumb pores (elongated oval air pockets following the coil curve)
    for (let p = 0; p < 24; p++) {
      let t = random(0.12, 0.92);
      let py = lerp(ch.yTop + 22, botY - 14, t);
      let px = xCenter + ch.bow * sin(t * 180) + random(-12, 12);
      let rx = random(1.5, 3.8);
      let ry = random(2.5, 6.5);
      let porePts = [
        [px, py - ry],
        [px + rx, py],
        [px, py + ry],
        [px - rx, py]
      ];
      strokePoly(porePts, p % 2 === 0 ? "2H" : "fine_quill", PAL.cassiaLight, 0.45, true, 0.4);
    }

    // Crumb stipple
    brush.set("crumb_stipple", PAL.honeyDeep, 0.95);
    brush.line(xCenter + ch.bow * 0.4, ch.yTop + 28, xCenter + ch.bow * 0.4, botY - 18);
  }
  resetBrushModes();

  // 6. Render High-Contrast Cinnamon-Sugar Veins (Cassia Bleed + Deep Burnt Umber Core)
  for (let vPts of cinnamonVeins) {
    // Knife-smear bleed into the golden crumb
    watercolorPoly(vPts, PAL.cassiaMid, 140, 0.24, 0.65, 0.4, 0.25);
    // Dense dark cinnamon paste core
    watercolorPoly(vPts, PAL.umberDeep, 210, 0.07, 0.65, 0.7, 0.25);
    strokePoly(vPts, "fine_quill", PAL.umberDeep, 0.75, true, 0.25);
  }

  // Outer crust outline
  strokePoly(loafOutline, "fine_quill", PAL.umberDark, 0.8, true, 0.25);

  // 7. Top Cream-Cheese Icing Cap (Reserved Paper Pooling in Valleys + Cut-Face Drips)
  let icingCapPts = [];
  // Upper glossy surface of the icing blanket
  icingCapPts.push([cx - halfW + 6, topY + 26]);
  for (let i = 0; i < 9; i++) {
    let x1 = cx + lobeBoundsX[i];
    let x2 = cx + lobeBoundsX[i + 1];
    let xMid = (x1 + x2) * 0.5;
    let distC = abs(i - 4);
    let yCrown = topY + distC * 4.5 - (22 - distC * 3.5);
    icingCapPts.push([xMid, yCrown - 13]);
    if (i < 8) {
      let yValley = topY + abs(i + 0.5 - 4) * 4.5 - 8;
      icingCapPts.push([x2, yValley]);
    }
  }
  icingCapPts.push([cx + halfW - 6, topY + 26]);

  // Lower cut boundary of the icing cap (settling deep into the cinnamon clefts + 3 drips)
  for (let i = 8; i >= 0; i--) {
    let x1 = cx + lobeBoundsX[i];
    let x2 = cx + lobeBoundsX[i + 1];
    let xMid = (x1 + x2) * 0.5;
    let distC = abs(i - 4);
    let yCrown = topY + distC * 4.5 - (22 - distC * 3.5);

    if (i < 8) {
      let vx = x2;
      let yV = topY + abs(i + 0.5 - 4) * 4.5 + 12;
      // Add viscous drips down the cut crumb face at veins 2, 4, and 6
      if (i === 2 || i === 4 || i === 6) {
        let dripLen = i === 4 ? 54 : 38;
        icingCapPts.push([vx + 6, yV]);
        icingCapPts.push([vx + 5, yV + dripLen * 0.65]);
        icingCapPts.push([vx, yV + dripLen]);
        icingCapPts.push([vx - 5, yV + dripLen * 0.65]);
        icingCapPts.push([vx - 6, yV]);
      } else {
        icingCapPts.push([vx, yV + 8]);
      }
    }
    icingCapPts.push([xMid, yCrown + 4]);
  }

  drawReservedIcing(icingCapPts, 0.28);

  // 8. Specular Gloss Highlights on the Sticky Cinnamon Veins & Caramel Base
  resetBrushModes();
  for (let i = 1; i <= 8; i++) {
    let vx = lobeBoundsX[i];
    let signV = vx < 0 ? -1 : 1;
    let distV = abs(i - 4.5);
    let bow = signV * (9 + distV * 2.2);
    let yT = topY + distV * 4.2 + 24;

    for (let g = 0; g < 3; g++) {
      let t1 = 0.2 + g * 0.28;
      let t2 = t1 + 0.12;
      let y1 = lerp(yT, botY - 8, t1);
      let y2 = lerp(yT, botY - 8, t2);
      let x1 = cx + vx + bow * sin(t1 * 180);
      let x2 = cx + vx + bow * sin(t2 * 180);
      strokePoly([[x1, y1], [(x1 + x2) * 0.5 + 1, (y1 + y2) * 0.5], [x2, y2]], "gloss_nib", PAL.glossWhite, 0.8, false, 0.3);
    }
  }
  // Base caramel gloss line
  strokePoly([
    [cx - 120, botY - 4],
    [cx - 40, botY - 3],
    [cx + 50, botY - 4],
    [cx + 135, botY - 3]
  ], "gloss_nib", PAL.glossWhite, 0.9, false, 0.2);
}

// =============================================================================
// FIG. 4: UNROLLED LENGTH OF DOUGH (DISSECTED LAMINA)
// =============================================================================

function getUnrolledSpinePoint(t) {
  // Serpentine S-curve specimen laid out in the bottom-right quadrant (845, 815)
  // t in [0, 1]
  let x = 845 + 136 * sin(t * 330 - 155) + 18 * cos(t * 180);
  let y = 656 + t * 316 + 14 * sin(t * 360);
  return [x, y];
}

function drawFig4UnrolledDough(cx, cy) {
  // 1. Graphite Construction Underlayer (Curvilinear Axis & Measurement Ticks)
  resetBrushModes();
  brush.set("2H", PAL.graphiteLight, 0.35);
  brush.line(cx - 195, cy, cx + 195, cy);
  brush.line(cx, cy - 195, cx, cy + 195);

  let N = 75;
  let spine = [];
  let normals = [];
  let widths = [];

  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let p = getUnrolledSpinePoint(t);
    let pNext = getUnrolledSpinePoint(min(1, t + 0.01));
    let pPrev = getUnrolledSpinePoint(max(0, t - 0.01));
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    spine.push(p);
    normals.push([-dy / len, dx / len]);

    // Taper slightly at the inner tail (t=0) and outer end (t=1)
    let endTaper = sin(constrain(t * 10, 0.25, 1) * 90) * sin(constrain((1 - t) * 10, 0.35, 1) * 90);
    let w = (26 + 4.5 * sin(t * 720) + 5 * (noise(t * 6, 44) - 0.5)) * endTaper;
    widths.push(w);
  }

  // Construct polygon ribbons:
  // A) Exposed Cinnamon-Sugar Inner Face (Top/Front of ribbon)
  // B) 3D Brioche Dough Thickness Rim (Offset [11, 13] showing the golden torn crumb layer)
  // C) Sharp Cast Shadow on Paper (Offset [22, 26], modulated by arch elevation)
  let topEdge = [];
  let botEdge = [];
  let doughThickEdge = [];
  let shadowPolyPts = [];

  for (let i = 0; i <= N; i++) {
    let p = spine[i];
    let n = normals[i];
    let w = widths[i];
    topEdge.push([p[0] + n[0] * w, p[1] + n[1] * w]);
    botEdge.push([p[0] - n[0] * w, p[1] - n[1] * w]);
  }

  let cinnamonFacePoly = topEdge.concat(botEdge.slice().reverse());

  // Dough 3D thickness polygon (offset by [11, 13] from the ribbon)
  let thickOffX = 11;
  let thickOffY = 13;
  for (let i = 0; i <= N; i++) {
    doughThickEdge.push([botEdge[i][0] + thickOffX, botEdge[i][1] + thickOffY]);
  }
  let fullDoughSpecimenPoly = topEdge
    .concat(doughThickEdge.slice().reverse())
    .concat([[topEdge[0][0] + thickOffX, topEdge[0][1] + thickOffY]]);

  // Shadow polygon on the paper (arch height lifts slightly at curves)
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let archLift = 1.0 + 0.35 * pow(sin(t * 360), 2);
    shadowPolyPts.push([topEdge[i][0] + 18 * archLift, topEdge[i][1] + 22 * archLift]);
  }
  for (let i = N; i >= 0; i--) {
    let t = i / N;
    let archLift = 1.0 + 0.35 * pow(sin(t * 360), 2);
    shadowPolyPts.push([doughThickEdge[i][0] + 15 * archLift, doughThickEdge[i][1] + 19 * archLift]);
  }

  // 2. Render Cast Shadow
  watercolorPoly(shadowPolyPts, PAL.shadowSoft, 120, 0.2, 0.55, 0.35, 0.25);
  let tightShadow = fullDoughSpecimenPoly.map(p => [p[0] + 9, p[1] + 11]);
  watercolorPoly(tightShadow, PAL.shadowCore, 205, 0.05, 0.45, 0.65, 0.25);

  // 3. Render Golden Brioche Dough Thickness Layer (Translucent Honey + Crumb Texture)
  watercolorPoly(fullDoughSpecimenPoly, PAL.honeyPale, 210, 0.06, 0.45, 0.35, 0.25);
  watercolorPoly(fullDoughSpecimenPoly, PAL.honeyMid, 150, 0.12, 0.55, 0.45, 0.25);

  // Hatching & cellular pores along the exposed golden dough thickness rim
  let doughRimBand = botEdge.concat(doughThickEdge.slice().reverse());
  watercolorPoly(doughRimBand, PAL.honeyDeep, 125, 0.1, 0.55, 0.45, 0.25);
  hatchPoly(doughRimBand, "2H", PAL.cassiaMid, 0.45, 4.5, 45, { rand: 0.06 }, 0.25);
  strokePoly(doughThickEdge, "fine_quill", PAL.cassiaDark, 0.75, false, 0.25);

  // 4. Render Exposed Cinnamon-Sugar Paste Bark Face (High-Contrast Cassia & Burnt Umber)
  watercolorPoly(cinnamonFacePoly, PAL.cassiaLight, 155, 0.14, 0.6, 0.45, 0.25);
  watercolorPoly(cinnamonFacePoly, PAL.cassiaDark, 145, 0.16, 0.65, 0.5, 0.25);

  // Transverse Bark-Like Cinnamon Paste Islands (where unrolling pulled the sticky filling into ridges,
  // revealing narrow golden-honey dough fissures between dark burnt-umber islands)
  let barkIslands = [];
  for (let i = 2; i < N - 2; i += 2) {
    let p1 = spine[i];
    let p2 = spine[i + 1];
    let n1 = normals[i];
    let n2 = normals[i + 1];
    let w1 = widths[i] * random(0.72, 0.94);
    let w2 = widths[i + 1] * random(0.72, 0.94);

    let island = [
      [p1[0] + n1[0] * w1, p1[1] + n1[1] * w1],
      [p2[0] + n2[0] * w2, p2[1] + n2[1] * w2],
      [p2[0] - n2[0] * w2, p2[1] - n2[1] * w2],
      [p1[0] - n1[0] * w1, p1[1] - n1[1] * w1]
    ];
    barkIslands.push(island);
  }

  for (let idx = 0; idx < barkIslands.length; idx++) {
    let isl = barkIslands[idx];
    watercolorPoly(isl, idx % 2 === 0 ? PAL.umberDark : PAL.umberMid, 185, 0.12, 0.7, 0.6, 0.25);
    strokePoly([isl[0], isl[3]], "fine_quill", PAL.umberDeep, 0.65, false, 0.2);
  }

  // Deep Molasses-Cinnamon Suture Track running along the lower third of the unrolled strip
  let innerTrack = [];
  for (let i = 2; i < N - 1; i++) {
    let p = spine[i];
    let n = normals[i];
    let w = widths[i];
    innerTrack.push([p[0] - n[0] * (w * 0.38), p[1] - n[1] * (w * 0.38)]);
  }
  strokePoly(innerTrack, "charcoal", PAL.umberDeep, 1.35, false, 0.3);

  // Granular cinnamon-sugar stippling along the unrolled strip
  resetBrushModes();
  brush.set("crumb_stipple", PAL.umberDeep, 1.15);
  for (let i = 0; i < spine.length - 1; i += 2) {
    brush.line(spine[i][0], spine[i][1], spine[i + 1][0], spine[i + 1][1]);
  }
  resetBrushModes();

  strokePoly(botEdge, "fine_quill", PAL.umberDark, 0.75, false, 0.25);

  // 5. Cream-Cheese Icing Clinging to the Upper Rim of the Unrolled Strip
  // (Broken into 3 organic scalloped ribbons along the top edge with drips across the cinnamon face)
  let segments = [
    { start: 3, end: 25 },
    { start: 28, end: 52 },
    { start: 55, end: 72 }
  ];

  for (let seg of segments) {
    let icingRibbon = [];
    // Outer scalloped icing crown along topEdge
    for (let i = seg.start; i <= seg.end; i++) {
      let p = topEdge[i];
      let n = normals[i];
      let scallop = 5 + 4 * sin(i * 45) + 3 * noise(i * 0.5, 99);
      icingRibbon.push([p[0] + n[0] * scallop, p[1] + n[1] * scallop]);
    }
    // Inner dripping edge encroaching onto the dark cinnamon face
    for (let i = seg.end; i >= seg.start; i--) {
      let p = topEdge[i];
      let n = normals[i];
      let w = widths[i];
      let drip = 7 + 8 * pow(max(0, sin(i * 38 + 20)), 2);
      if (i === Math.floor((seg.start + seg.end) * 0.5)) {
        drip = w * 1.15; // A long gooey drip reaching halfway across the cinnamon bark!
      }
      icingRibbon.push([p[0] - n[0] * drip, p[1] - n[1] * drip]);
    }
    drawReservedIcing(icingRibbon, 0.3);
  }

  // 6. Specular Sugar Crust Gloss on the Unrolled Strip
  resetBrushModes();
  for (let i = 4; i < N - 4; i += 4) {
    let p = spine[i];
    let n = normals[i];
    let w = widths[i] * 0.5;
    let gLine = [
      [p[0] + n[0] * w, p[1] + n[1] * w],
      [p[0], p[1]],
      [p[0] - n[0] * (w * 0.6), p[1] - n[1] * (w * 0.6)]
    ];
    strokePoly(gLine, "gloss_nib", PAL.glossWhite, random(0.6, 1.05), false, 0.25);
  }
}

