function drawEngravedText(str, x, y, size, slant, brushName, col, weight, tracking = 0.82) {
  resetBrushModes();
  brush.set(brushName, col, weight);
  let cursorX = x;
  for (let idx = 0; idx < str.length; idx++) {
    let ch = str[idx];
    if (ch === " ") {
      cursorX += size * 0.65;
      continue;
    }
    let strokes = GLYPHS[ch];
    if (strokes) {
      for (let s of strokes) {
        let pts = s.map(p => [
          cursorX + p[0] * size + (1 - p[1]) * size * slant,
          y + p[1] * size
        ]);
        if (pts.length === 2) {
          brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
        } else {
          brush.spline(pts, 0.35);
        }
      }
    }
    let adv = (ch === "." || ch === "i" || ch === "I") ? size * 0.48 : (ch === "M" ? size * 1.05 : size * tracking);
    cursorX += adv;
  }
  resetBrushModes();
}

function drawLeaderCallout(x1, y1, x2, y2, label) {
  resetBrushModes();
  brush.set("2H", PAL.graphiteMid, 0.38);
  let dist = sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
  let steps = max(4, floor(dist / 6));
  for (let i = 0; i < steps; i++) {
    if (i % 2 === 0) {
      let t1 = i / steps;
      let t2 = (i + 0.65) / steps;
      brush.line(lerp(x1, x2, t1), lerp(y1, y2, t1), lerp(x1, x2, t2), lerp(y1, y2, t2));
    }
  }
  resetBrushModes();
  drawEngravedText(label, x2 + 4, y2 - 7, 10.5, 0.2, "2H", PAL.graphiteDark, 0.45);
}

function drawPlateLabelsAndNumerals() {
  // Tiny pencilled reference numerals beside each specimen view
  drawEngravedText("Fig. 1.", 135, 132, 13.5, 0.22, "HB", PAL.graphiteDark, 0.5);
  drawEngravedText("Fig. 2.", 632, 132, 13.5, 0.22, "HB", PAL.graphiteDark, 0.5);
  drawEngravedText("Fig. 3.", 135, 608, 13.5, 0.22, "HB", PAL.graphiteDark, 0.5);
  drawEngravedText("Fig. 4.", 632, 608, 13.5, 0.22, "HB", PAL.graphiteDark, 0.5);

  // Subtle anatomical leader letters (suture, icing callus, caramel base, unrolled bark)
  drawLeaderCallout(455, 225, 515, 185, "a.");
  drawLeaderCallout(265, 455, 200, 495, "b.");
  drawLeaderCallout(985, 235, 1035, 195, "c.");
  drawLeaderCallout(355, 712, 395, 655, "a.");
  drawLeaderCallout(475, 902, 525, 938, "c.");
  drawLeaderCallout(925, 725, 1015, 695, "b.");

  // Plate header & taxonomic footer in classic 19th-century engraved capitals
  drawEngravedText("TAB. XIV.", 995, 76, 11.5, 0.0, "fine_quill", PAL.plateInk, 0.55, 0.88);
