    tip: (_m) => {
      _m.rect(-2.1, -1.2, 4.2, 2.4);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.22
  });

  brush.add("chisel_chip", {
    type: "custom",
    weight: 5.2,
    scatter: 0.08,
    opacity: 255,
    spacing: 0.16,
    pressure: [0.85, 1.35, 0.05],
    tip: (_m) => {
      _m.rotate(20);
      _m.triangle(-2.4, -1.5, 2.4, 0, -1.5, 1.9);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.35
  });

  brush.add("burin", {
    type: "default",
    weight: 1.05,
    scatter: 0.02,
    sharpness: 0.96,
    grain: 0.92,
    opacity: 252,
    spacing: 0.09,
    pressure: [0.04, 1.15, 0.04],
    noise: 0.15
  });
}

// ============================================================================
// GEOMETRY & WOODCUT CARVING HELPERS
// ============================================================================

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function clipSegmentToPoly(x1, y1, x2, y2, poly) {
  let ts = [0, 1];
  let dx = x2 - x1, dy = y2 - y1;
  for (let i = 0, n = poly.length; i < n; i++) {
    let a = poly[i], b = poly[(i + 1) % n];
    let ex = b[0] - a[0], ey = b[1] - a[1];
    let denom = dx * ey - dy * ex;
    if (Math.abs(denom) > 1e-9) {
      let t = ((a[0] - x1) * ey - (a[1] - y1) * ex) / denom;
      let u = ((a[0] - x1) * dy - (a[1] - y1) * dx) / denom;
      if (t > 0 && t < 1 && u >= 0 && u <= 1) ts.push(t);
    }
  }
  ts.sort((a, b) => a - b);
  let segs = [];
  for (let i = 0; i < ts.length - 1; i++) {
    let t0 = ts[i], t1 = ts[i + 1];
    if (t1 - t0 < 1e-4) continue;
    let tm = 0.5 * (t0 + t1);
    if (pointInPoly(x1 + dx * tm, y1 + dy * tm, poly)) {
      segs.push([x1 + dx * t0, y1 + dy * t0, x1 + dx * t1, y1 + dy * t1]);
    }
  }
  return segs;
}

function getPolyBounds(poly) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let p of poly) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  return { minX, minY, maxX, maxY };
}

function fillPolySolid(poly, col, edgeBrush = "knife_slash", edgeWeight = 1.0, scanSpacing = 4.2) {
  if (!poly || poly.length < 3) return;
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, 255);
  brush.set(edgeBrush, col, edgeWeight);
  brush.beginShape(0);
  for (let p of poly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Scanline reinforcement guarantees zero WebGL concave-triangulation gaps
  let { minX, minY, maxX, maxY } = getPolyBounds(poly);
  brush.set("block_ink", col, 1.05);
  for (let y = minY + 1.5; y < maxY; y += scanSpacing) {
    let segs = clipSegmentToPoly(minX - 5, y, maxX + 5, y, poly);
    for (let s of segs) {
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }
  if (edgeWeight > 0) {
    brush.set(edgeBrush, col, edgeWeight);
    for (let i = 0; i < poly.length; i++) {
      let a = poly[i], b = poly[(i + 1) % poly.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

function carvePolyHatch(poly, col, brushName, weight, angleDeg, spacing, opts = {}) {
  let { minX, minY, maxX, maxY } = getPolyBounds(poly);
  let cx = 0.5 * (minX + maxX), cy = 0.5 * (minY + maxY);
  let diag = Math.hypot(maxX - minX, maxY - minY) * 0.65 + 20;
  let rad = angleDeg * Math.PI / 180;
  let dx = Math.cos(rad), dy = Math.sin(rad);
  let nx = -dy, ny = dx;

  let dashLen = opts.dashLen || 9999;
  let gapLen = opts.gapLen || 0;
  let jitter = opts.jitter || 0;
  let curveAmt = opts.curve || 0;
  let wVar = opts.weightVar || 0;

  brush.set(brushName, col, weight);

  for (let d = -diag; d <= diag; d += spacing) {
    let ox = cx + nx * (d + random(-jitter, jitter));
    let oy = cy + ny * (d + random(-jitter, jitter));
    let x1 = ox - dx * diag, y1 = oy - dy * diag;
    let x2 = ox + dx * diag, y2 = oy + dy * diag;
    let segs = clipSegmentToPoly(x1, y1, x2, y2, poly);

    for (let s of segs) {
      let sx1 = s[0], sy1 = s[1], sx2 = s[2], sy2 = s[3];
      let len = Math.hypot(sx2 - sx1, sy2 - sy1);
      if (len < 2.5) continue;

      if (dashLen < len) {
        let pos = random(0, dashLen * 0.35);
        while (pos < len - 2) {
          let segL = dashLen * random(0.7, 1.3);
          let t0 = pos / len;
          let t1 = Math.min(1, (pos + segL) / len);
          let ax = sx1 + (sx2 - sx1) * t0, ay = sy1 + (sy2 - sy1) * t0;
          let bx = sx1 + (sx2 - sx1) * t1, by = sy1 + (sy2 - sy1) * t1;
          let w = weight * (1 + random(-wVar, wVar));
          brush.set(brushName, col, Math.max(0.25, w));
          if (curveAmt !== 0 && (t1 - t0) * len > 10) {
            let mx = 0.5 * (ax + bx) + nx * curveAmt * random(0.5, 1.4);
            let my = 0.5 * (ay + by) + ny * curveAmt * random(0.5, 1.4);
            brush.spline([[ax, ay, 0.2], [mx, my, 1.2], [bx, by, 0.2]], 0.35);
          } else {
            brush.line(ax, ay, bx, by);
          }
          pos += segL + gapLen * random(0.6, 1.4);
        }
      } else {
        let w = weight * (1 + random(-wVar, wVar));
        brush.set(brushName, col, Math.max(0.25, w));
        if (curveAmt !== 0 && len > 12) {
          let mx = 0.5 * (sx1 + sx2) + nx * curveAmt * random(0.6, 1.3);
          let my = 0.5 * (sy1 + sy2) + ny * curveAmt * random(0.6, 1.3);
          brush.spline([[sx1, sy1, 0.2], [mx, my, 1.2], [sx2, sy2, 0.2]], 0.35);
        } else {
          brush.line(sx1, sy1, sx2, sy2);
        }
      }
    }
  }
}

// ============================================================================
// SCENE GEOMETRY FUNCTIONS (OAK BLOCK, SPLIT CHASM, SHADOWS)
// ============================================================================

// Center of oak top face & split crack definition
const BLOCK_CX = 578;
const BLOCK_CY = 548;
const BLOCK_RX = 408;
const BLOCK_RY = 104;
const PITH_X = 560;
const PITH_Y = 548;

// The split line on the top face runs from back rim (510, 443) through pith (560, 548) to front rim (598, 653)
function getTopSplitCenterX(y) {
  let t = (y - 443) / (653 - 443);
  return 510 + t * 88 + Math.sin(t * Math.PI * 3.0) * 4.5;
}

function getTopSplitHalfWidth(y) {
  // Widest right where the maul wedge bites (around y = 545..595)
  let d = Math.abs(y - 562);
  let wedgeBoost = Math.max(0, 1 - d / 85) * 14;
  let baseW = 5 + ((y - 443) / 210) * 9;
  return baseW + wedgeBoost;
}

// Outer bark-scalloped rim of the oak top face
function getTopRimRadiusScale(angleDeg) {
  let rad = angleDeg * Math.PI / 180;
  return 1.0
    + 0.022 * Math.sin(rad * 7 + 0.4)
    + 0.015 * Math.cos(rad * 15 - 1.1)
    + 0.010 * Math.sin(rad * 27 + 2.0);
}

// Determines whether a point on the top face of the oak block is in deep chiaroscuro shadow
function isTopFaceInShadow(x, y) {
  // Cast shadow of the maul head and handle across the right half of the block top
  // Shadow boundary from buried blade toe (495, 584) down-right to front rim (745, 652)
  if (y >= 540) {
    let shadowEdgeX = 502 + (y - 580) * 3.1;
    if (x > shadowEdgeX) return true;
  }
  // Behind the maul head / under the handle (y < 540)
  if (y < 540) {
    let shadowEdgeX = 535 + (y - 440) * 0.45;
    if (x > shadowEdgeX) return true;
  }
  // Far right rim curvature shadow
  if (x > 845) return true;
  return false;
}

// Vertical split crack down the front trunk face (y = 652 to y = 1075)
function getTrunkSplitCenterX(y) {
  let t = constrain((y - 652) / (1075 - 652), 0, 1);
  return 598 - t * 10 + Math.sin(t * 14) * 5.5 + Math.cos(t * 29) * 2.5;
}

function getTrunkSplitHalfWidth(y) {
  let t = constrain((y - 652) / (1075 - 652), 0, 1);
  return Math.max(0, (1 - Math.pow(t, 0.72)) * 18.5);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER);
  brush.noField();

  // 1. Solid ink woodblock ground inside print margins
  drawWoodblockGroundAndSky();

  // 2. Foreground split firewood logs & woodyard floor base
  drawForegroundFloorAndLogs();

  // 3. Monumental Scarred Oak Chopping Block (Trunk Bark & Split Chasm)
  drawOakTrunkAndBark();

  // 4. Scarred Oak Chopping Block Top Face (Growth Rings, Medullary Rays, Checks, Scars)
  drawOakTopFace();

  // 5. Deep Split Chasm & Strained White Wood-Fiber Bridges
  drawSplitChasmAndFibers();

  // 6. The Buried Splitting Maul (Hammered Steel Head, Wedge, Single Raw White Bevel Slash, Hickory Handle)
  drawSplittingMaul();

  // 7. Overlapping Impact Splinters & Flying / Scattered White Wood Shards
  drawImpactSplintersAndShards();

  // 8. Woodblock Print Margin & Carved Frame Edge
  drawPrintmakerBorder();

  noLoop();
}

// ============================================================================
// 1. WOODBLOCK GROUND & EXPRESSIONIST RAKING-LIGHT SKY
// ============================================================================

function drawWoodblockGroundAndSky() {
  // Base black woodblock ink square
  let blockPoly = [[36, 36], [1164, 36], [1164, 1164], [36, 1164]];
  fillPolySolid(blockPoly, INK, "knife_slash", 1.5, 4.8);

  // Harsh raking light from upper-left (around x=60, y=40) slashing at ~31 degrees
  // Carve dramatic German Expressionist white gouges into the upper-left sky
  let rayOriginX = -40, rayOriginY = -30;
  for (let i = 0; i < 165; i++) {
    let t = i / 164;
    // Spread rays across the left and upper sky
    let angle = -4 + t * 76 + random(-0.6, 0.6);
    let rad = angle * Math.PI / 180;
    let dx = Math.cos(rad), dy = Math.sin(rad);

    // Distance reaches further in the core raking beam (around 22..42 degrees)
    let beamFocus = Math.exp(-Math.pow((angle - 30) / 26, 2));
    let maxDist = 280 + beamFocus * 590 + random(-60, 70);

    // Break each ray into carved woodcut gouge segments with authentic woodblock chatter
    let dist = 45 + random(0, 35);
    while (dist < maxDist) {
      let segLen = (35 + beamFocus * 85) * random(0.55, 1.35);
      let d0 = dist;
      let d1 = Math.min(maxDist, dist + segLen);
      let x0 = rayOriginX + dx * d0, y0 = rayOriginY + dy * d0;
      let x1 = rayOriginX + dx * d1, y1 = rayOriginY + dy * d1;

      if (x1 > 38 && y1 > 38 && y0 < 680) {
        let cx0 = constrain(x0, 38, 1160);
        let cy0 = constrain(y0, 38, 700);
        let cx1 = constrain(x1, 38, 1160);
        let cy1 = constrain(y1, 38, 700);
        let progress = d0 / maxDist;
        let w = (1 - progress * 0.78) * (1.2 + beamFocus * 1.9) * random(0.75, 1.25);

        brush.set(w > 1.6 ? "u_gouge" : "v_gouge", PAPER, w);
        brush.line(cx0, cy0, cx1, cy1);
      }
      // Gap leaves black woodblock chatter ridges between white gouges
      dist += segLen + (8 + progressGap(dist / maxDist) * 28) * random(0.5, 1.4);
    }
  }

  // Blazing white core in upper-left corner with residual black woodcut knife chatter marks
  let ulCorner = [[36, 36], [420, 36], [280, 210], [36, 360]];
  carvePolyHatch(ulCorner, PAPER, "u_gouge", 1.8, 31, 4.5, {
    dashLen: 140,
    gapLen: 10,
    jitter: 1.2,
    weightVar: 0.25
  });
  // Carve sharp black chatter slivers back into the brightest upper-left zone
  carvePolyHatch(ulCorner, INK, "knife_slash", 0.9, 31, 13, {
    dashLen: 45,
    gapLen: 32,
    jitter: 2.5,
    weightVar: 0.35
  });

  // Tense angular shock/vibration gouges in the dark right sky around the maul handle & head
  brush.set("v_gouge", PAPER, 0.75);
  for (let i = 0; i < 85; i++) {
    let ang = random(-35, 65);
    let r = random(180, 480);
    let cx = 545 + Math.cos(ang * Math.PI / 180) * r;
    let cy = 420 + Math.sin(ang * Math.PI / 180) * r * 0.75;
    if (cx > 580 && cx < 1150 && cy > 45 && cy < 580) {
      let dir = 28 + random(-18, 18);
      let len = random(14, 42);
      let x2 = cx + Math.cos(dir * Math.PI / 180) * len;
      let y2 = cy + Math.sin(dir * Math.PI / 180) * len;
      brush.set("v_gouge", PAPER, random(0.4, 0.95));
      brush.line(cx, cy, x2, y2);
    }
  }
}

function progressGap(p) {
  return p * p * 1.6;
}

// ============================================================================
// 2. FOREGROUND FLOOR & SPLIT FIREWOOD LOGS
// ============================================================================

function drawForegroundFloorAndLogs() {
  // Ground plane carved with rugged horizontal & diagonal raking gouges on the left,
  // sinking into deep chiaroscuro black on the right
  for (let y = 1020; y < 1160; y += 5.5) {
    let t = (y - 1020) / 140;
    // Left side ground catches raking light
    let maxLitX = 680 - t * 120 + random(-40, 40);
    let x = 42;
    while (x < maxLitX) {
      let segW = random(28, 95) * (1 - (x / 950) * 0.5);
      let xEnd = Math.min(maxLitX, x + segW);
      let dy = random(-6, 8);
      let w = (1 - x / 900) * random(0.7, 1.65);
      brush.set(w > 1.1 ? "u_gouge" : "v_gouge", PAPER, w);
      brush.line(x, y, xEnd, y + dy);
      x = xEnd + random(8, 32);
    }
    // Sparse white chisel gouges in the deep shadowed right ground
    for (let s = 0; s < 3; s++) {
      let sx = random(650, 1150);
      let slen = random(16, 48);
      brush.set("v_gouge", PAPER, random(0.45, 0.9));
      brush.line(sx, y + random(-3, 3), sx + slen, y + random(2, 9));
    }
  }

  // Left foreground split quarter-log (resting against base of chopping block)
  let leftLogTop = [[46, 985], [195, 955], [242, 995], [75, 1038]];
  let leftLogSide = [[46, 985], [75, 1038], [235, 1135], [46, 1135]];
  fillPolySolid(leftLogTop, PAPER, "knife_slash", 1.1);
  fillPolySolid(leftLogSide, INK, "knife_slash", 1.1);
  // Radial split grain on left log top
  carvePolyHatch(leftLogTop, INK, "v_gouge", 0.85, -14, 5.5, {
    dashLen: 45, gapLen: 8, jitter: 1.0, weightVar: 0.3
  });
  // Bark crosshatch on left log side
  carvePolyHatch(leftLogSide, PAPER, "v_gouge", 0.9, 32, 7.5, {
    dashLen: 35, gapLen: 10, jitter: 1.5
  });
  carvePolyHatch(leftLogSide, PAPER, "burin", 0.7, -45, 9.5, {
    dashLen: 25, gapLen: 12, jitter: 1.5
  });

  // Right foreground split log in deep chiaroscuro (defined by white burin & V-gouges on black)
  let rightLogFace = [[940, 1025], [1148, 990], [1154, 1125], [915, 1142]];
  fillPolySolid(rightLogFace, DEEP_INK, "knife_slash", 1.2);
  carvePolyHatch(rightLogFace, PAPER, "v_gouge", 0.75, -12, 8.0, {
    dashLen: 38, gapLen: 16, jitter: 1.2, curve: 3
  });
  // Sharp white rim highlight on upper edge of right log
  brush.set("v_gouge", PAPER, 1.3);
  brush.line(940, 1025, 1148, 990);
}

// ============================================================================
// 3. MONUMENTAL OAK CHOPPING BLOCK — TRUNK & CHUNKY CROSSHATCH BARK
// ============================================================================

function drawOakTrunkAndBark() {
  // Build the outer silhouette of the oak trunk (with low-angle perspective taper & split heave on left)
  let trunkPoly = [];
  // Top rim from left (-180 deg) across front (-90..0..90) to right (0 deg)
  for (let a = 180; a >= 0; a -= 5) {
    let rScale = getTopRimRadiusScale(a);
    let rad = a * Math.PI / 180;
    let x = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rScale;
    let y = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rScale;
    if (x < getTopSplitCenterX(y)) {
      x -= 13;
      y -= 5;
    }
    trunkPoly.push([x, y]);
  }
  // Right trunk profile descending from (986, 548) to root flare at (960, 1138)
  let steps = 22;
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let rootFlare = t > 0.82 ? Math.pow((t - 0.82) / 0.18, 1.6) * 28 : 0;
    let barkWobble = Math.sin(t * 24) * 5 + Math.cos(t * 11) * 4;
    let x = 986 - t * 48 + rootFlare + barkWobble;
    let y = 548 + t * 585;
    trunkPoly.push([x, y]);
  }
  // Base profile across the roots (from right to left)
  for (let i = 1; i <= 16; i++) {
    let t = i / 16;
    let x = 966 - t * 775;
    let arch = Math.sin(t * Math.PI) * 14 + Math.sin(t * Math.PI * 5) * 8;
    let y = 1133 + arch;
    trunkPoly.push([x, y]);
  }
  // Left trunk profile ascending from root flare (191, 1133) up to heaved left shoulder (157, 543)
  for (let i = steps - 1; i >= 1; i--) {
    let t = i / steps;
    let rootFlare = t > 0.82 ? Math.pow((t - 0.82) / 0.18, 1.6) * 26 : 0;
    let barkWobble = Math.sin(t * 21 + 1.2) * 5.5 + Math.cos(t * 13) * 4;
    let x = 157 + t * 54 - rootFlare + barkWobble;
    let y = 543 + t * 590;
    trunkPoly.push([x, y]);
  }

  // Fill entire trunk silhouette with dense black ink base
  fillPolySolid(trunkPoly, DEEP_INK, "knife_slash", 1.5, 4.5);

  // Carve the 24 vertical oak bark columns & chunky crosshatched plates
  let numCols = 24;
  for (let c = 0; c < numCols; c++) {
    // Cylindrical angle u0..u1 from left edge (180 deg) to right edge (0 deg)
    let u0 = c / numCols;
    let u1 = (c + 1) / numCols;
    let uMid = 0.5 * (u0 + u1);

    // Map u in [0, 1] via cosine distribution so outer edges foreshorten naturally like a 3D cylinder
    let ang0 = (1 - u0) * Math.PI;
    let ang1 = (1 - u1) * Math.PI;
    let angMid = 0.5 * (ang0 + ang1);

    // Illumination: strong raking light on left flank (u < 0.42), transitional in center, deep chiaroscuro on right
    let cylLight = Math.max(0, Math.cos(angMid - 2.35)); // peaks on left-front
    let shadowDrop = uMid > 0.52 ? Math.max(0.06, 1 - (uMid - 0.52) * 2.4) : 1.0;
    let illum = cylLight * shadowDrop;
    // Slight rim reflection on the far right edge (u > 0.91) so the block silhouette reads against the black void
    let isRightRim = uMid > 0.90;

    // Subdivide column vertically into chunky oak bark plates (9 to 13 plates high)
    let numPlates = Math.floor(random(9, 13));
    for (let r = 0; r < numPlates; r++) {
      let v0 = r / numPlates;
      let v1 = (r + 1) / numPlates;
      let vMid = 0.5 * (v0 + v1);

      // Compute the 4 corners of this bark plate on the tapered 3D trunk
      let pTL = getTrunkPoint(ang0, v0);
      let pTR = getTrunkPoint(ang1, v0);
      let pBR = getTrunkPoint(ang1, v1);
      let pBL = getTrunkPoint(ang0, v1);

      // Skip plates that fall directly inside the central split chasm
      let cx = 0.25 * (pTL[0] + pTR[0] + pBR[0] + pBL[0]);
      let cy = 0.25 * (pTL[1] + pTR[1] + pBR[1] + pBL[1]);
      let splitX = getTrunkSplitCenterX(cy);
      let splitHW = getTrunkSplitHalfWidth(cy);
      if (Math.abs(cx - splitX) < splitHW + 4) continue;

      // Inset plate slightly to leave deep black vertical & diagonal bark furrows
      let inset = 2.8 + random(0.5, 2.5);
      let platePoly = [
        [pTL[0] + inset, pTL[1] + inset + random(-3, 3)],
        [pTR[0] - inset, pTR[1] + inset + random(-4, 4)],
        [pBR[0] - inset, pBR[1] - inset + random(-3, 3)],
        [pBL[0] + inset, pBL[1] - inset + random(-4, 4)]
      ];

      let plateIllum = constrain(illum + random(-0.12, 0.12), 0, 1);

      if (plateIllum > 0.62) {
        // BRIGHT RAKING-LIGHT BARK PLATES (Left side of oak block):
        // Carve white paper base, then cut chunky black crosshatch & vertical bark fissures
        fillPolySolid(platePoly, PAPER, "v_gouge", 0.8, 4.5);

        // Chunky crosshatch in dense black ink: primary diagonal + counter-diagonal + vertical grain
        carvePolyHatch(platePoly, INK, "knife_slash", 1.15, 42 + random(-6, 6), 7.5 + plateIllum * 3, {
          dashLen: 26, gapLen: 6, jitter: 1.4, weightVar: 0.3
        });
        carvePolyHatch(platePoly, INK, "v_gouge", 0.95, -38 + random(-6, 6), 9.0 + plateIllum * 4, {
          dashLen: 22, gapLen: 8, jitter: 1.4, weightVar: 0.3
        });
        // Deep shadow bevel on the right and bottom edge of each raised bark scale
        brush.set("u_gouge", DEEP_INK, 1.4);
        brush.line(platePoly[1][0], platePoly[1][1], platePoly[2][0], platePoly[2][1]);
        brush.line(platePoly[2][0], platePoly[2][1], platePoly[3][0], platePoly[3][1]);
      } else if (plateIllum > 0.25) {
        // MID-TONE CHIAROSCURO BARK PLATES (Center-left & flanking the central split):
        // Solid black base carved with aggressive, chunky white crosshatched gouges
        // Left bevel of the bark scale catches harsh raking light as a thick white chisel cut
        brush.set("u_gouge", PAPER, 1.55);
        brush.line(platePoly[0][0], platePoly[0][1], platePoly[3][0], platePoly[3][1]);
        brush.set("v_gouge", PAPER, 1.25);
        brush.line(platePoly[0][0], platePoly[0][1], platePoly[1][0], platePoly[1][1]);

        // Dense chunky white crosshatch across the bark plate
        let sp = map(plateIllum, 0.25, 0.62, 9.5, 5.2);
        carvePolyHatch(platePoly, PAPER, "v_gouge", 1.05, 36 + random(-5, 5), sp, {
          dashLen: 24, gapLen: 5, jitter: 1.3, weightVar: 0.3
        });
        carvePolyHatch(platePoly, PAPER, "v_gouge", 0.85, -44 + random(-5, 5), sp * 1.15, {
          dashLen: 20, gapLen: 7, jitter: 1.3, weightVar: 0.3
        });
        // Vertical woodcut ridge gouges
        carvePolyHatch(platePoly, PAPER, "burin", 0.85, 86 + random(-4, 4), sp * 1.3, {
          dashLen: 30, gapLen: 8, jitter: 1.0
        });
      } else {
        // DEEP CHIAROSCURO BARK PLATES (Right half of trunk in shadow):
        // Sparse, razor-sharp white crosshatch & vertical edge gouges emerging from pitch black
        if (isRightRim) {
          carvePolyHatch(platePoly, PAPER, "v_gouge", 0.85, 45, 7.5, {
            dashLen: 18, gapLen: 8, jitter: 1.2
          });
          brush.set("v_gouge", PAPER, 1.1);
          brush.line(platePoly[1][0], platePoly[1][1], platePoly[2][0], platePoly[2][1]);
        } else {
          // Catch only the upper-left lip of the rugged oak bark plate + sparse chunky crosshatch
          if (random() < 0.82) {
            brush.set("v_gouge", PAPER, random(0.65, 1.15));
            let lipLen = (platePoly[3][1] - platePoly[0][1]) * random(0.45, 0.9);
            brush.line(platePoly[0][0], platePoly[0][1], platePoly[0][0] + random(-2, 2), platePoly[0][1] + lipLen);
          }
          carvePolyHatch(platePoly, PAPER, "burin", 0.72, 38, 12.5, {
            dashLen: 16, gapLen: 12, jitter: 1.5
          });
          if (vMid < 0.65 && random() < 0.6) {
            carvePolyHatch(platePoly, PAPER, "burin", 0.65, -48, 14.5, {
              dashLen: 14, gapLen: 14, jitter: 1.5
            });
          }
        }
      }
    }
  }
}

function getTrunkPoint(angRad, v) {
  // v = 0 is top rim, v = 1 is root base
  let deg = angRad * 180 / Math.PI;
  let rScale = getTopRimRadiusScale(deg);
  let topX = BLOCK_CX + Math.cos(angRad) * BLOCK_RX * rScale;
  let topY = BLOCK_CY + Math.sin(angRad) * BLOCK_RY * rScale;

  // Bottom center and radius (slightly narrower due to low-angle worm's-eye perspective, plus root flare at bottom)
  let rootFlare = v > 0.82 ? Math.pow((v - 0.82) / 0.18, 1.6) * 26 : 0;
  let botRx = BLOCK_RX * 0.88 + rootFlare;
  let botRy = BLOCK_RY * 0.42;
  let botX = BLOCK_CX + Math.cos(angRad) * botRx;
  let botY = 1118 + Math.sin(angRad) * botRy;

  let x = topX + (botX - topX) * v;
  let y = topY + (botY - topY) * v;

  // Left half heaves outward at the top from the maul wedge
  let splitX = getTrunkSplitCenterX(y);
  if (x < splitX) {
    let heave = (1 - v * 0.75);
    x -= 13 * heave;
    y -= 5 * heave;
  }
  return [x, y];
}

// ============================================================================
// 4. SCARRED OAK TOP FACE (GROWTH RINGS, MEDULLARY RAYS, RADIAL CHECKS, SCARS)
// ============================================================================

function drawOakTopFace() {
  // Build Left Half and Right Half polygons of the top face (separated by the central split chasm)
  let leftTopPoly = [];
  let rightTopPoly = [];

  // Sample outer ellipse rim (360 degrees)
  let totalPts = 120;
  for (let i = 0; i < totalPts; i++) {
    let a = (i / totalPts) * 360;
    let rad = a * Math.PI / 180;
    // Inner sapwood boundary (slightly inside the outer bark rim)
    let rScale = getTopRimRadiusScale(a) * 0.94;
    let x = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rScale;
    let y = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rScale;
    let splitX = getTopSplitCenterX(y);
    let splitHW = getTopSplitHalfWidth(y);

    if (x < splitX - splitHW * 0.3) {
      leftTopPoly.push([x - 13, y - 5]);
    } else if (x > splitX + splitHW * 0.3) {
      rightTopPoly.push([x, y]);
    }
  }

  // First, carve the outer bark crown rim around the top ellipse with chunky radial chisel marks
  for (let a = 0; a < 360; a += 2.2) {
    let rad = a * Math.PI / 180;
    let rIn = getTopRimRadiusScale(a) * 0.925;
    let rOut = getTopRimRadiusScale(a) * 1.01;
    let x1 = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rIn;
    let y1 = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rIn;
    let x2 = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rOut;
    let y2 = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rOut;

    let splitX = getTopSplitCenterX(y1);
    if (Math.abs(x1 - splitX) < getTopSplitHalfWidth(y1) + 4) continue;
    if (x1 < splitX) {
      x1 -= 13; y1 -= 5;
      x2 -= 13; y2 -= 5;
    }

    let inShadow = isTopFaceInShadow(x1, y1);
    brush.set("v_gouge", inShadow ? PAPER : PAPER, inShadow ? 0.65 : 1.15);
    if (!inShadow || random() < 0.55) {
      brush.line(x1, y1, x2, y2);
    }
  }

  // Lay down solid PAPER on the lit region of the top face, and solid INK on the cast-shadow region
  // We do this by building the lit polygon and shadow polygon across both halves
  let litLeftPoly = [];
  for (let a = 92; a <= 268; a += 3) {
    let rad = a * Math.PI / 180;
    let rScale = getTopRimRadiusScale(a) * 0.935;
    let x = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rScale - 13;
    let y = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rScale - 5;
    litLeftPoly.push([x, y]);
  }
  for (let y = 445; y <= 650; y += 6) {
    let sx = getTopSplitCenterX(y) - getTopSplitHalfWidth(y) - 13;
    litLeftPoly.push([sx, y - 5]);
  }
  fillPolySolid(litLeftPoly, PAPER, "knife_slash", 1.0, 4.0);

  // Right half of top face: base is deep chiaroscuro INK, except the rear-left lit wedge near the back rim
  let rightFullPoly = [];
  for (let y = 650; y >= 445; y -= 6) {
    let sx = getTopSplitCenterX(y) + getTopSplitHalfWidth(y);
    rightFullPoly.push([sx, y]);
  }
  for (let a = 272; a <= 448; a += 3) {
    let rad = (a % 360) * Math.PI / 180;
    let rScale = getTopRimRadiusScale(a % 360) * 0.935;
    let x = BLOCK_CX + Math.cos(rad) * BLOCK_RX * rScale;
    let y = BLOCK_CY + Math.sin(rad) * BLOCK_RY * rScale;
    rightFullPoly.push([x, y]);
  }
  fillPolySolid(rightFullPoly, INK, "knife_slash", 1.1, 4.2);

  // Carve the lit portion on the right-rear of the top face (where isTopFaceInShadow is false)
  let rightLitPoly = [];
  for (let y = 555; y >= 446; y -= 5) {
    let sx = getTopSplitCenterX(y) + getTopSplitHalfWidth(y);
    rightLitPoly.push([sx, y]);
  }
  for (let y = 446; y <= 555; y += 5) {
    let shadowEdgeX = y < 540 ? 535 + (y - 440) * 0.45 : 502 + (y - 580) * 3.1;
    rightLitPoly.push([shadowEdgeX + random(-6, 6), y]);
  }
  fillPolySolid(rightLitPoly, PAPER, "v_gouge", 0.9, 4.0);

  // Now carve woodcut transition chatter right along the cast-shadow boundary on the top face!
  for (let y = 448; y <= 650; y += 2.8) {
    let shadowX = y < 540 ? 535 + (y - 440) * 0.45 : 502 + (y - 580) * 3.1;
    let splitR = getTopSplitCenterX(y) + getTopSplitHalfWidth(y);
    if (shadowX > splitR && shadowX < 880) {
      let len = random(18, 52);
      brush.set("v_gouge", PAPER, random(0.65, 1.3));
      brush.line(shadowX - 6, y, shadowX + len, y + len * 0.22);
      brush.set("knife_slash", INK, random(0.6, 1.1));
      brush.line(shadowX - len * 0.6, y - len * 0.12, shadowX + 8, y);
    }
  }

  // CONCENTRIC OAK GROWTH RINGS (44 rings from pith outward, with counterchange polarity!)
  let numRings = 44;
  for (let rIdx = 1; rIdx <= numRings; rIdx++) {
    let normR = rIdx / numRings;
    // Slight non-linear spacing like real oak (tighter near outer sapwood and inner heartwood)
    let radFrac = Math.pow(normR, 0.94) * 0.92;
    let isMajorRing = (rIdx % 3 === 0);

    let ringSamples = 140;
    for (let s = 0; s < ringSamples; s++) {
      let a0 = (s / ringSamples) * 360;
      let a1 = ((s + 1) / ringSamples) * 360;

      let p0 = getGrowthRingPoint(radFrac, a0);
      let p1 = getGrowthRingPoint(radFrac, a1);
      if (!p0 || !p1) continue;
      // Don't connect across the central split chasm!
      if (p0.side !== p1.side) continue;

      let mx = 0.5 * (p0.x + p1.x);
      let my = 0.5 * (p0.y + p1.y);
      let inShadow = isTopFaceInShadow(mx, my);

      // Counterchange polarity: INK gouges on lit paper, PAPER gouges in deep chiaroscuro shadow!
      let strokeCol = inShadow ? PAPER : INK;
      let baseW = isMajorRing ? 0.95 : 0.58;
      if (inShadow && !isMajorRing && random() < 0.25) continue; // Slightly sparser in deepest shadow

      brush.set(isMajorRing ? "v_gouge" : "burin", strokeCol, baseW * random(0.8, 1.25));
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // MEDULLARY RAYS (Characteristic of Oak End-Grain: fine radial flecks radiating from the pith)
  for (let i = 0; i < 110; i++) {
    let a = (i / 110) * 360 + random(-1.2, 1.2);
    let rStart = random(0.08, 0.65);
    let rEnd = Math.min(0.91, rStart + random(0.12, 0.32));
    let p0 = getGrowthRingPoint(rStart, a);
    let p1 = getGrowthRingPoint(rEnd, a);
    if (!p0 || !p1 || p0.side !== p1.side) continue;

    let mx = 0.5 * (p0.x + p1.x), my = 0.5 * (p0.y + p1.y);
    let inShadow = isTopFaceInShadow(mx, my);
    brush.set("burin", inShadow ? PAPER : INK, random(0.45, 0.85));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // RADIAL HEARTWOOD DRYING CHECKS (Deep star-cracks radiating from pith with stark white rim highlights)
  let checkAngles = [18, 52, 128, 158, 194, 222, 248, 315, 342];
  for (let ca of checkAngles) {
    let maxR = random(0.48, 0.86);
    let ptsInk = [];
    let ptsLight = [];
    for (let st = 0; st <= 14; st++) {
      let rf = 0.05 + (st / 14) * maxR;
      let wobbleA = ca + Math.sin(st * 1.3) * 2.8;
      let p = getGrowthRingPoint(rf, wobbleA);
      if (p) {
        ptsInk.push([p.x, p.y, st === 0 || st === 14 ? 0.2 : 1.3]);
        ptsLight.push([p.x + 2.5, p.y + 1.8, st === 0 || st === 14 ? 0.2 : 1.1]);
      }
    }
    if (ptsInk.length > 3) {
      brush.set("knife_slash", DEEP_INK, 1.35);
      brush.spline(ptsInk, 0.3);
      brush.set("v_gouge", BRIGHT_WHITE, 0.95);
      brush.spline(ptsLight, 0.3);
    }
  }

  // OLD AXE & MAUL SCARS (Crisp V-cut gashes criss-crossing the scarred chopping block)
  for (let s = 0; s < 32; s++) {
    let a = random(0, 360);
    let rf = random(0.15, 0.82);
    let p = getGrowthRingPoint(rf, a);
    if (!p) continue;

    let scarAng = random(-65, 65) * Math.PI / 180;
    let scarLen = random(18, 46);
    let x1 = p.x - Math.cos(scarAng) * scarLen * 0.5;
    let y1 = p.y - Math.sin(scarAng) * scarLen * 0.5;
    let x2 = p.x + Math.cos(scarAng) * scarLen * 0.5;
    let y2 = p.y + Math.sin(scarAng) * scarLen * 0.5;

    // Ensure scar doesn't bridge the central split chasm
    let splitX = getTopSplitCenterX(p.y);
    if (Math.abs(x1 - splitX) < 18 || Math.abs(x2 - splitX) < 18) continue;

    // Deep black V-trench + bright white chisel highlight on the lower/right bevel wall
    brush.set("knife_slash", DEEP_INK, random(1.1, 1.7));
    brush.line(x1, y1, x2, y2);
    brush.set("v_gouge", BRIGHT_WHITE, random(0.8, 1.3));
    brush.line(x1 + 1.8, y1 + 2.2, x2 + 1.8, y2 + 2.2);
  }
}

function getGrowthRingPoint(radFrac, angleDeg) {
  let rad = angleDeg * Math.PI / 180;
  let wobble = 1.0
    + 0.035 * Math.sin(rad * 4 + radFrac * 8)
    + 0.022 * Math.cos(rad * 9 - radFrac * 12)
    + 0.012 * Math.sin(rad * 19 + radFrac * 5);

  let x = PITH_X + Math.cos(rad) * (BLOCK_RX * radFrac * wobble);
  let y = PITH_Y + Math.sin(rad) * (BLOCK_RY * radFrac * wobble);

  let splitX = getTopSplitCenterX(y);
  let splitHW = getTopSplitHalfWidth(y);

  if (Math.abs(x - splitX) < splitHW) return null;
  if (x < splitX) {
    return { x: x - 13, y: y - 5, side: -1 };
  }
  return { x, y, side: 1 };
}

// ============================================================================
// 5. SPLIT CHASM ABYSS & STRAINED WHITE WOOD-FIBER BRIDGES
// ============================================================================

function drawSplitChasmAndFibers() {
  // Build polygon for the gaping split chasm across the top face and down the front trunk
  let chasmPoly = [];

  // Left wall from back rim (y=443) to front lip (y=653)
  for (let y = 443; y <= 653; y += 6) {
    let sx = getTopSplitCenterX(y) - getTopSplitHalfWidth(y) - 13;
    chasmPoly.push([sx + random(-2, 2), y - 5]);
  }
  // Left wall down the front trunk from y=653 to y=1075
  for (let y = 656; y <= 1075; y += 10) {
    let sx = getTrunkSplitCenterX(y) - getTrunkSplitHalfWidth(y) - 13 * (1 - ((y - 652) / 423) * 0.75);
    chasmPoly.push([sx + random(-2.5, 2.5), y]);
  }
  // Right wall ascending from y=1075 back up to front lip y=653
  for (let y = 1075; y >= 656; y -= 10) {
    let sx = getTrunkSplitCenterX(y) + getTrunkSplitHalfWidth(y);
    chasmPoly.push([sx + random(-2.5, 2.5), y]);
  }
  // Right wall across top face from front lip (y=653) to back rim (y=443)
  for (let y = 653; y >= 443; y -= 6) {
    let sx = getTopSplitCenterX(y) + getTopSplitHalfWidth(y);
    chasmPoly.push([sx + random(-2, 2), y]);
  }

  fillPolySolid(chasmPoly, DEEP_INK, "knife_slash", 1.4, 3.8);

  // Carve the raking-lit RIGHT INTERIOR WALL of the split chasm:
  // Because the light comes from upper-left, the right inner wall of the split catches vertical shafts of light!
  for (let y = 450; y < 995; y += 4.5) {
    // Skip where the maul blade is directly buried (y = 505..590)
    if (y > 505 && y < 588) continue;

    let rx = y <= 653
      ? getTopSplitCenterX(y) + getTopSplitHalfWidth(y)
      : getTrunkSplitCenterX(y) + getTrunkSplitHalfWidth(y);

    let wallDepth = y <= 653 ? random(5, 14) : random(4, 12) * (1 - (y - 653) / 400);
    if (wallDepth > 2) {
      brush.set("v_gouge", BRIGHT_WHITE, random(0.65, 1.25));
      brush.line(rx, y, rx - wallDepth, y + wallDepth * 1.35);
    }
  }

  // TAUT, SPLINTERED WHITE WOOD FIBERS BRIDGING THE CHASM:
  // Stretched across the dark void under extreme mechanical tension
  for (let i = 0; i < 58; i++) {
    let y = random(455, 1030);
    // Avoid overlapping the solid steel blade body before the maul is drawn, except right at the front lip
    if (y > 505 && y < 575) continue;

    let lx, rx;
    if (y <= 653) {
      lx = getTopSplitCenterX(y) - getTopSplitHalfWidth(y) - 13;
      rx = getTopSplitCenterX(y) + getTopSplitHalfWidth(y);
    } else {
      let heave = 1 - ((y - 652) / 423) * 0.75;
      lx = getTrunkSplitCenterX(y) - getTrunkSplitHalfWidth(y) - 13 * heave;
      rx = getTrunkSplitCenterX(y) + getTrunkSplitHalfWidth(y);
    }

    let gap = rx - lx;
    if (gap < 3) continue;

    let dy = random(-10, 14);
    if (random() < 0.65) {
      // Full strained fiber bridge across the chasm
      let midX = 0.5 * (lx + rx) + random(-4, 4);
      let midY = y + dy * 0.5 + random(-3, 3);
      brush.set(random() < 0.4 ? "v_gouge" : "burin", BRIGHT_WHITE, random(0.5, 1.1));
      brush.spline([[lx - 2, y - 5, 0.4], [midX, midY, 1.1], [rx + 2, y + dy, 0.4]], 0.3);
    } else {
      // Snapped splinter jutting halfway into the black abyss
      let fromLeft = random() < 0.5;
      let len = gap * random(0.35, 0.8);
      brush.set("v_gouge", BRIGHT_WHITE, random(0.55, 1.15));
      if (fromLeft) {
        brush.line(lx - 2, y - 5, lx + len, y - 5 + dy * 0.6);
      } else {
        brush.line(rx + 2, y, rx - len, y - dy * 0.6);
      }
    }
  }
}

// ============================================================================
// 6. THE BURIED SPLITTING MAUL (FORGED STEEL HEAD, RAW WHITE BEVEL, HANDLE)
// ============================================================================

function drawSplittingMaul() {
  // --------------------------------------------------------------------------
  // A. HICKORY HANDLE (Sweeping heroically from the maul eye up-right to (1164, 38..134))
  // --------------------------------------------------------------------------
  // Drawn first where it emerges from the eye, with low-angle perspective flare
  let handleTopEdge = [
    [526, 316], [645, 258], [790, 188], [965, 108], [1164, 36]
  ];
  let handleBotEdge = [
    [1164, 132], [985, 192], [815, 260], [665, 320], [546, 358]
  ];
  let handlePoly = [...handleTopEdge, ...handleBotEdge];

  // Solid black ink foundation for the hickory handle
  fillPolySolid(handlePoly, DEEP_INK, "knife_slash", 1.3, 4.0);

  // Carve longitudinal hickory wood grain & raking-light highlight along the upper handle edge
  let numGrainLines = 28;
  for (let g = 0; g <= numGrainLines; g++) {
    let v = g / numGrainLines; // 0 = top lit edge, 1 = bottom shadowed belly
    let pts = [];
    for (let s = 0; s < handleTopEdge.length; s++) {
      let topP = handleTopEdge[s];
      let botP = handleBotEdge[handleBotEdge.length - 1 - s];
      let x = topP[0] + (botP[0] - topP[0]) * v;
      let y = topP[1] + (botP[1] - topP[1]) * v;
      pts.push([x, y]);
    }

    if (v < 0.28) {
      // Blazing raking-light highlight band along top ridge of handle
      brush.set("u_gouge", v < 0.12 ? BRIGHT_WHITE : PAPER, 1.5 - v * 2.2);
      brush.spline(pts.map(p => [p[0], p[1], 1.0]), 0.35);
    } else if (v < 0.68) {
      // Mid-tone hickory wood grain: dashed splintered chisel gouges following the handle curve
      for (let i = 0; i < pts.length - 1; i++) {
        let a = pts[i], b = pts[i + 1];
        let segs = 3;
        for (let k = 0; k < segs; k++) {
          if (random() < (1 - v) * 1.15) {
            let t0 = (k + random(0, 0.2)) / segs;
            let t1 = (k + random(0.65, 0.95)) / segs;
            let x0 = a[0] + (b[0] - a[0]) * t0, y0 = a[1] + (b[1] - a[1]) * t0;
            let x1 = a[0] + (b[0] - a[0]) * t1, y1 = a[1] + (b[1] - a[1]) * t1;
            brush.set("v_gouge", PAPER, (1 - v) * 1.35 * random(0.75, 1.25));
            brush.line(x0, y0, x1, y1);
          }
        }
      }
    } else if (v > 0.88) {
      // Subtle reflected light from the oak block onto the underside of the hickory handle
      for (let i = 0; i < pts.length - 1; i++) {
        let a = pts[i], b = pts[i + 1];
        brush.set("burin", PAPER, 0.65);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }
  }

  // Carve dark hickory grain pores & stress checks back into the bright upper ridge of the handle
  for (let i = 0; i < 36; i++) {
    let t = random(0.04, 0.94);
    let v = random(0.03, 0.26);
    let idx = Math.min(handleTopEdge.length - 2, Math.floor(t * (handleTopEdge.length - 1)));
    let frac = t * (handleTopEdge.length - 1) - idx;
    let topA = handleTopEdge[idx], topB = handleTopEdge[idx + 1];
    let botA = handleBotEdge[handleBotEdge.length - 1 - idx];
    let botB = handleBotEdge[handleBotEdge.length - 2 - idx];
    let tx = topA[0] + (topB[0] - topA[0]) * frac;
    let ty = topA[1] + (topB[1] - topA[1]) * frac;
    let bx = botA[0] + (botB[0] - botA[0]) * frac;
    let by = botA[1] + (botB[1] - botA[1]) * frac;
    let px = tx + (bx - tx) * v;
    let py = ty + (by - ty) * v;
    let len = random(24, 68);
    brush.set("burin", INK, random(0.65, 1.1));
    brush.line(px, py, px + len * 0.91, py - len * 0.41);
  }

  // --------------------------------------------------------------------------
  // B. FORGED STEEL SPLITTING MAUL HEAD
  // --------------------------------------------------------------------------
  // Full silhouette of the maul head:
  // Octagonal sledge poll at top-left -> recessed neck -> flared eye -> convex wedge cheeks -> buried blade bit
  let maulHeadPoly = [
    [412, 266], // Poll top-back
    [438, 254], // Poll top-front chamfer
    [464, 276], // Upper neck
    [536, 322], // Top-right of eye
    [548, 356], // Bottom-right of eye (handle throat)
    [558, 402], // Inner beard curve
    [594, 452], // Lower beard flare
    [648, 495], // Blade Heel (exposed right corner of cutting edge)
    [572, 544], // Mid-bevel entering wood
    [496, 586], // Blade Toe (buried deep in oak cleft)
    [454, 480], // Front spine lower
    [418, 386], // Front spine upper
    [384, 316], // Poll bottom-back
    [392, 288]  // Poll back face
  ];

  fillPolySolid(maulHeadPoly, DEEP_INK, "knife_slash", 1.5, 3.8);

  // 1. OCTAGONAL SLEDGE POLL (Hammer face & chamfered bevels at top-left, blasted by light)
  let pollFacePoly = [[392, 288], [412, 266], [438, 254], [410, 304], [384, 316]];
  fillPolySolid(pollFacePoly, BRIGHT_WHITE, "knife_slash", 0.9, 3.5);
  // Hammered impact rings & burin scars on the poll face
  carvePolyHatch(pollFacePoly, INK, "burin", 0.75, -55, 4.8, {
    dashLen: 16, gapLen: 6, jitter: 0.8
  });

  let pollUpperChamfer = [[438, 254], [464, 276], [442, 296], [410, 304]];
  fillPolySolid(pollUpperChamfer, PAPER, "v_gouge", 0.8, 3.5);
  carvePolyHatch(pollUpperChamfer, INK, "v_gouge", 0.8, 34, 4.5, {
    dashLen: 18, gapLen: 5, jitter: 0.6
  });

  let pollLowerChamfer = [[410, 304], [442, 296], [430, 338], [384, 316]];
  carvePolyHatch(pollLowerChamfer, PAPER, "v_gouge", 0.95, -28, 4.8, {
    dashLen: 18, gapLen: 4, jitter: 0.8
  });

  // 2. PROTRUDING HICKORY TONGUE & IRON WEDGE AT TOP OF EYE
  let eyeTopPoly = [[470, 272], [534, 314], [524, 326], [462, 284]];
  fillPolySolid(eyeTopPoly, PAPER, "knife_slash", 0.9, 3.5);
  // Dark steel wedge driven down the middle of the protruding handle tongue
  brush.set("knife_slash", DEEP_INK, 1.4);
  brush.line(476, 279, 522, 316);
  brush.set("burin", INK, 0.8);
  for (let k = 0; k < 7; k++) {
    let kx = 468 + k * 8, ky = 278 + k * 5.5;
    brush.line(kx, ky - 3, kx - 5, ky + 4);
  }

  // 3. UPPER-LEFT CHEEK & CONVEX SPLITTING WEDGE (Hammered Steel in Harsh Raking Light)
  // Spans from front spine to the central convex splitting ridge
  let litCheekPoly = [
    [384, 316],
    [430, 338],
    [442, 296],
    [464, 276],
    [496, 338], // Central wedge ridge at eye
    [536, 434], // Central wedge ridge mid
    [572, 526], // Central wedge ridge just above bevel shadow line
    [486, 566], // Front spine just above bevel
    [454, 480],
    [418, 386]
  ];
  fillPolySolid(litCheekPoly, PAPER, "knife_slash", 1.0, 4.0);

  // Carve authentic HAMMERED FORGED STEEL texture across the lit cheek:
  // Interlocking angular chisel facets ("chisel_chip" and "v_gouge") + contour burin lines
  carvePolyHatch(litCheekPoly, INK, "v_gouge", 0.92, -26, 5.2, {
    dashLen: 14, gapLen: 7, jitter: 1.5, curve: 2.2, weightVar: 0.35
  });
  carvePolyHatch(litCheekPoly, INK, "burin", 0.78, 64, 6.8, {
    dashLen: 12, gapLen: 9, jitter: 1.4, weightVar: 0.3
  });

  // Forged hammer-peen dimples (dark angular pit + stark white bottom-right rim highlight)
  for (let i = 0; i < 65; i++) {
    let px = random(395, 562);
    let py = random(285, 550);
    if (!pointInPoly(px, py, litCheekPoly)) continue;
    // Denser hammer scale near poll/eye, smoother ground steel near the blade bevel
    let distToBevel = 555 - py;
    if (distToBevel < 45 && random() < 0.55) continue;

    let sz = random(4, 10);
    let ang = random(-35, 25) * Math.PI / 180;
    let dx = Math.cos(ang) * sz, dy = Math.sin(ang) * sz;
    brush.set("chisel_chip", INK, random(0.65, 1.15));
    brush.line(px, py, px + dx, py + dy);
    brush.set("v_gouge", BRIGHT_WHITE, random(0.75, 1.2));
    brush.line(px + 1.5, py + 2.0, px + dx + 1.5, py + dy + 2.0);
  }

  // Gleaming white highlight ridge along the Front Spine (facing upper-left light directly)
  brush.set("u_gouge", BRIGHT_WHITE, 1.6);
  brush.spline([[386, 316, 0.8], [420, 386, 1.3], [456, 480, 1.2], [486, 562, 0.6]], 0.25);

  // Gleaming white highlight crest along the Central Convex Splitting Wedge Ridge!
  let ridgePts = [[464, 278], [496, 338], [536, 434], [572, 526]];
  brush.set("u_gouge", BRIGHT_WHITE, 1.55);
  brush.spline(ridgePts.map(p => [p[0], p[1], 1.1]), 0.3);
  // Short diagonal white chisel slashes flaring off the central splitting wedge
  for (let t = 0.08; t <= 0.95; t += 0.035) {
    let rx = 464 + (572 - 464) * t + Math.sin(t * Math.PI) * 6;
    let ry = 278 + (526 - 278) * t;
    brush.set("v_gouge", BRIGHT_WHITE, random(0.8, 1.35));
    brush.line(rx - 8, ry - 4, rx + 5, ry + 3);
  }

  // 4. LOWER-RIGHT CHEEK & BEARD (Deep Chiaroscuro Shadow with Carved White Contour Gouges)
  let shadowCheekPoly = [
    [464, 276],
    [536, 322],
    [548, 356],
    [558, 402],
    [594, 452],
    [644, 492],
    [572, 526],
    [536, 434],
    [496, 338]
  ];
  fillPolySolid(shadowCheekPoly, DEEP_INK, "knife_slash", 1.2, 3.8);

  // Carve curved white contour burin & V-gouges wrapping over the convex splitting wedge into shadow
  for (let i = 0; i < 28; i++) {
    let t = (i + 0.5) / 28;
    // Start along the central wedge ridge
    let sx = 468 + (570 - 468) * t;
    let sy = 282 + (522 - 282) * t;
    // Curve toward the rear beard/throat profile
    let ex = 532 + (638 - 532) * t;
    let ey = 324 + (488 - 324) * t;
    let mx = 0.5 * (sx + ex) + 8;
    let my = 0.5 * (sy + ey) - 6;

    // Gouge fades out into deep chiaroscuro black halfway across the shadow cheek,
    // then picks up a faint reflected rim near the rear beard edge!
    let stopT = random(0.32, 0.62);
    let p1x = sx + (mx - sx) * stopT * 1.4;
    let p1y = sy + (my - sy) * stopT * 1.4;
    brush.set("v_gouge", PAPER, random(0.6, 1.15));
    brush.line(sx - 2, sy - 1, p1x, p1y);

    // Faint reflected light along the rear beard curve
    if (i % 2 === 0) {
      let rx0 = ex - (ex - mx) * random(0.18, 0.35);
      let ry0 = ey - (ey - my) * random(0.18, 0.35);
      brush.set("burin", PAPER, random(0.45, 0.85));
      brush.line(rx0, ry0, ex - 2, ey + 1);
    }
  }

  // Hammered steel texture pits in the shadow cheek (carved as tiny white V-gouge crescents)
  for (let i = 0; i < 26; i++) {
    let px = random(495, 625);
    let py = random(310, 495);
    if (!pointInPoly(px, py, shadowCheekPoly)) continue;
    brush.set("burin", PAPER, random(0.5, 0.9));
    brush.line(px, py, px + random(4, 9), py - random(2, 6));
  }

  // 5. THE BRIGHT BEVELLED EDGE ("and the bright bevelled edge is a single raw white slash")
  // First, carve a bold, razor-sharp pitch-black shadow trench right above the bevel so the white slash
  // is framed by pure black ink on both sides!
  let bevelTopGuard = [
    [486, 564], [572, 520], [646, 484], [648, 495], [574, 534], [492, 578]
  ];
  fillPolySolid(bevelTopGuard, DEEP_INK, "knife_slash", 1.2, 3.0);

  // Now carve THE SINGLE RAW WHITE SLASH of the bright bevelled edge!
  // Runs from the buried toe deep in the cleft (500, 582) up-right to the exposed heel (648, 495)
  let rawWhiteSlashPoly = [
    [500, 582], // Needle point plunging into the dark oak cleft
    [542, 550], // Upper bevel shoulder left
    [594, 520], // Upper bevel shoulder mid
    [646, 490], // Upper bevel heel corner
    [649, 498], // Sharp cutting edge heel tip
    [588, 535], // Sharp cutting edge mid
    [536, 565]  // Sharp cutting edge entering cleft
  ];
  fillPolySolid(rawWhiteSlashPoly, BRIGHT_WHITE, "knife_slash", 1.1, 2.5);

  // Reinforce with one single, continuous, electrifying raw white knife slash stroke
  brush.set("u_gouge", BRIGHT_WHITE, 2.2);
  brush.spline([
    [500, 582, 0.15],
    [550, 551, 1.35],
    [605, 518, 1.45],
    [648, 494, 0.9]
  ], 0.15);

  // Razor-sharp black cutting-edge line along the bottom of the raw white slash + 3 tiny honed steel nicks
  brush.set("burin", DEEP_INK, 0.95);
  brush.line(500, 582, 649, 498);
  let nickTs = [0.28, 0.56, 0.78];
  for (let nt of nickTs) {
    let nx = 500 + (649 - 500) * nt;
    let ny = 582 + (498 - 582) * nt;
    brush.set("burin", DEEP_INK, 0.75);
    brush.line(nx, ny, nx - 3, ny - 5);
  }
}

