function drawWoodShard(cx, cy, len, w, angleDeg, isGrounded) {
  let rad = angleDeg * Math.PI / 180;
  let dx = Math.cos(rad), dy = Math.sin(rad);
  let nx = -dy, ny = dx;

  // Sharp, angular 5-vertex splintered wedge polygon
  let pTip1 = [cx - dx * len * 0.52, cy - dy * len * 0.52];
  let pTop1 = [cx - dx * len * 0.15 + nx * w * 0.55, cy - dy * len * 0.15 + ny * w * 0.55];
  let pTop2 = [cx + dx * len * 0.28 + nx * w * 0.38, cy + dy * len * 0.28 + ny * w * 0.38];
  let pTip2 = [cx + dx * len * 0.52 - nx * w * 0.1, cy + dy * len * 0.52 - ny * w * 0.1];
  let pBot  = [cx + dx * len * 0.05 - nx * w * 0.52, cy + dy * len * 0.05 - ny * w * 0.52];

  let shardPoly = [pTip1, pTop1, pTop2, pTip2, pBot];

  // Hard black shadow facet beneath the shard
  let shOffX = isGrounded ? 4.5 : 3.5;
  let shOffY = isGrounded ? 6.5 : 4.5;
  let shadowPoly = shardPoly.map(p => [p[0] + shOffX, p[1] + shOffY]);
  fillPolySolid(shadowPoly, DEEP_INK, "knife_slash", 1.1, 3.0);

  // Stark raw white shard body
  fillPolySolid(shardPoly, BRIGHT_WHITE, "knife_slash", 0.9, 2.8);

  // Crisp black woodcut border so the shard is razor-sharp even over lit zones
  brush.set("knife_slash", DEEP_INK, 0.95);
  for (let i = 0; i < shardPoly.length; i++) {
    let a = shardPoly[i], b = shardPoly[(i + 1) % shardPoly.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Internal wood-grain chisel lines & dark bevel side
  brush.set("burin", INK, 0.72);
  brush.line(
    pTip1[0] * 0.7 + pTop1[0] * 0.3, pTip1[1] * 0.7 + pTop1[1] * 0.3,
    pTip2[0] * 0.7 + pTop2[0] * 0.3, pTip2[1] * 0.7 + pTop2[1] * 0.3
  );
  brush.line(
    pTip1[0] * 0.5 + pBot[0] * 0.5, pTip1[1] * 0.5 + pBot[1] * 0.5,
    pTip2[0] * 0.6 + pBot[0] * 0.4, pTip2[1] * 0.6 + pBot[1] * 0.4
  );
}

