function drawPrintmakerBorder() {
  // Restore clean cotton-rag paper margins outside [36, 36, 1164, 1164]
  let topMargin = [[0, 0], [1200, 0], [1200, 35], [0, 35]];
  let botMargin = [[0, 1165], [1200, 1165], [1200, 1200], [0, 1200]];
  let leftMargin = [[0, 0], [35, 0], [35, 1200], [0, 1200]];
  let rightMargin = [[1165, 0], [1200, 0], [1200, 1200], [1165, 1200]];

  fillPolySolid(topMargin, PAPER, "block_ink", 0.5, 5.0);
  fillPolySolid(botMargin, PAPER, "block_ink", 0.5, 5.0);
  fillPolySolid(leftMargin, PAPER, "block_ink", 0.5, 5.0);
  fillPolySolid(rightMargin, PAPER, "block_ink", 0.5, 5.0);

  // Hand-carved woodblock border frame with organic chisel irregularities
  brush.set("knife_slash", INK, 1.8);
  for (let x = 35; x < 1165; x += 45) {
    let xNext = Math.min(1165, x + 45);
    brush.line(x, 36 + random(-1.5, 1.5), xNext, 36 + random(-1.5, 1.5));
    brush.line(x, 1164 + random(-1.5, 1.5), xNext, 1164 + random(-1.5, 1.5));
  }
  for (let y = 35; y < 1165; y += 45) {
    let yNext = Math.min(1165, y + 45);
    brush.line(36 + random(-1.5, 1.5), y, 36 + random(-1.5, 1.5), yNext);
    brush.line(1164 + random(-1.5, 1.5), y, 1164 + random(-1.5, 1.5), yNext);
  }

  // Outer hairline keyline characteristic of fine German Expressionist woodblock prints
  brush.set("burin", INK, 0.85);
  brush.line(26, 26, 1174, 26);
  brush.line(1174, 26, 1174, 1174);
  brush.line(1174, 1174, 26, 1174);
  brush.line(26, 1174, 26, 26);
}

