function drawFritwareSurface() {
  brush.noStroke();

  // Subtle cool porcelain glaze pooling
  brush.fill(PAL.slipCool, 42);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.25, 0.1);
  brush.circle(620, 580, 480, 0.25);
  brush.circle(380, 820, 360, 0.25);

  brush.fill(PAL.slipBlue, 35);
  brush.fillBleed(0.4, "out");
  brush.circle(780, 420, 410, 0.3);

  // Cast shadow washes in Iznik Cobalt & Turquoise beneath the diagonal bunch
  const shadowPools = [
    // Under leaves (top-right)
    { x: 750, y: 590, r: 170, col: PAL.cobaltWash, op: 35 },
    { x: 920, y: 540, r: 145, col: PAL.turqIce, op: 32 },
    { x: 840, y: 380, r: 150, col: PAL.cobaltWash, op: 26 },
    // Under stems & neck
    { x: 585, y: 635, r: 120, col: PAL.cobaltMid, op: 45 },
    // Under the 6 radish roots (strong cobalt-turquoise cast shadows)
    { x: 435, y: 645, r: 90, col: PAL.cobaltMid, op: 52 },
    { x: 595, y: 785, r: 92, col: PAL.cobaltDeep, op: 60 },
    { x: 345, y: 775, r: 98, col: PAL.cobaltDeep, op: 58 },
    { x: 500, y: 710, r: 105, col: PAL.cobaltDeep, op: 62 },
    { x: 510, y: 885, r: 108, col: PAL.cobaltDeep, op: 68 },
    { x: 380, y: 925, r: 106, col: PAL.cobaltDeep, op: 72 },
    // Cool turquoise secondary bounce around root shadows
    { x: 445, y: 965, r: 135, col: PAL.turqBase, op: 34 },
    { x: 265, y: 985, r: 125, col: PAL.cobaltWash, op: 38 }
  ];

  for (let s of shadowPools) {
    brush.fill(s.col, s.op);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.3, 0.15);
    brush.circle(s.x, s.y, s.r, 0.22);
  }
  brush.noFill();

  // Faint fritware glaze crazing (crackle network across the ceramic/glossy ground)
  for (let i = 0; i < 38; i++) {
    let x = random(40, 1160);
    let y = random(40, 1160);
    let ang = random(360);
    let pts = [[x, y]];
    let segs = floor(random(4, 9));
    for (let j = 0; j < segs; j++) {
      ang += random(-32, 32);
      let len = random(35, 95);
      x += cos(ang) * len;
      y += sin(ang) * len;
      pts.push([x, y, random(0.3, 0.8)]);
    }
    brush.set("2H", i % 2 === 0 ? PAL.crazing1 : PAL.crazing2, 0.45);
    brush.spline(pts, 0.25);
  }

  // Glossy vertical/diagonal reflection smears under the roots (wet tabletop reflection)
  for (let i = 0; i < 45; i++) {
    let rx = random(270, 620);
    let ry = random(850, 1080);
    let len = random(30, 85);
    let col = i % 3 === 0 ? PAL.waxyPink : (i % 2 === 0 ? PAL.cobaltWash : PAL.turqIce);
    brush.set("glaze_shader", col, random(0.7, 1.3));
    brush.line(rx, ry, rx - len * 0.65, ry + len * 0.75);
  }

  // Deep cobalt occlusion shadows right under each root contact zone
  const occlusions = [
    [585, 790, 75], [335, 785, 80], [495, 895, 90], [365, 935, 92], [565, 605, 70]
  ];
  for (let oc of occlusions) {
    for (let k = 0; k < 14; k++) {
      let dy = map(k, 0, 13, -12, 22);
      let w = oc[2] * sin(map(k, 0, 13, 20, 160));
      brush.set("glaze_shader", k < 7 ? PAL.cobaltAbyss : PAL.cobaltDeep, 0.9);
      brush.line(oc[0] - w * 0.7, oc[1] + dy, oc[0] + w * 0.7, oc[1] + dy - 10);
    }
  }
}

// =============================================================================
// STAGE 2 & 3: SERRATED SAZ-STYLE RADISH GREENS
// =============================================================================
function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t, uu = u * u;
  let uuu = uu * u, ttt = tt * t;
  return [
    uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
    uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1]
  ];
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let m = sqrt(dx * dx + dy * dy) || 1;
  return [dx / m, dy / m];
}

function drawSazRadishLeaf(cfg) {
  const { p0, p1, p2, p3, widthMax, lobes, flip, paletteBias, tears, foldAt } = cfg;

  // Sample spine geometry
  const steps = 70;
  let spine = [];
  let leftEdge = [];
  let rightEdge = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalBezier(p0, p1, p2, p3, t);
    let tan = evalBezierTangent(p0, p1, p2, p3, t);
    let norm = [-tan[1], tan[0]];

    // Lyrate-saz radish leaf envelope: narrow petiole base, broad lobed upper half, serrated tip
    let env = pow(sin(t * 168), 0.72) * (0.35 + 0.75 * pow(t, 0.45));
    if (t > 0.88) env *= map(t, 0.88, 1.0, 1.0, 0.12);

    // Serrated saz lobes along the margin
    let lobePhase = t * lobes * 360;
    let saw = 0.72 + 0.28 * sin(lobePhase) + 0.12 * sin(lobePhase * 2 + 35);
    // Deep incisions between basal lobes (lyrate radish leaf character)
    let incision = t < 0.65 ? (0.62 + 0.38 * pow(0.5 + 0.5 * sin(lobePhase - 30), 1.6)) : saw;

    // Check if there is a torn vein notch at this lobe index
    let lobeIdx = floor(t * lobes);
    let tearFactorL = (tears && tears.includes(lobeIdx) && abs((t * lobes) - (lobeIdx + 0.5)) < 0.14) ? 0.28 : 1.0;
    let tearFactorR = (tears && tears.includes(lobeIdx + 1) && abs((t * lobes) - (lobeIdx + 0.8)) < 0.12) ? 0.35 : 1.0;

    let wL = widthMax * env * incision * tearFactorL * (flip > 0 ? 1.05 : 0.88);
    let wR = widthMax * env * saw * tearFactorR * (flip > 0 ? 0.88 : 1.05);

    spine.push({ pt, tan, norm, t, wL, wR, lobeIdx });
    leftEdge.push([
      pt[0] + norm[0] * wL - tan[0] * (wL * 0.15),
      pt[1] + norm[1] * wL - tan[1] * (wL * 0.15)
    ]);
    rightEdge.push([
      pt[0] - norm[0] * wR - tan[0] * (wR * 0.15),
      pt[1] - norm[1] * wR - tan[1] * (wR * 0.15)
    ]);
  }

  // -------------------------------------------------------------------------
  // PASS 1: DENSE FLAT MARKER PASSAGES (Iznik Turquoise, Cobalt, Sage Green)
  // -------------------------------------------------------------------------
  for (let i = 2; i < steps - 1; i++) {
    let s = spine[i];
    let pL = leftEdge[i];
    let pR = rightEdge[i];

    // Pick strict Iznik flat marker zone colors
    let colL, colR;
    if (paletteBias === "cobalt_heavy") {
      colL = s.t < 0.5 ? PAL.cobaltDeep : PAL.turqDeep;
      colR = s.t < 0.6 ? PAL.cobaltAbyss : PAL.cobaltMid;
    } else if (paletteBias === "cobalt_turq") {
      colL = s.t < 0.4 ? PAL.cobaltMid : PAL.turqBase;
      colR = s.t < 0.55 ? PAL.cobaltDeep : PAL.sageDeep;
    } else if (paletteBias === "turq_cobalt") {
      colL = s.t < 0.35 ? PAL.turqDeep : PAL.turqVivid;
      colR = s.t < 0.5 ? PAL.cobaltDeep : PAL.turqBase;
    } else if (paletteBias === "sage_vivid") {
      colL = s.t < 0.3 ? PAL.turqBase : PAL.sageVivid;
      colR = s.t < 0.45 ? PAL.sageDeep : PAL.sageBase;
    } else {
      // sage_turq / turq_sage
      colL = s.t < 0.35 ? PAL.turqBase : (s.t < 0.75 ? PAL.sageBase : PAL.sageVivid);
      colR = s.t < 0.45 ? PAL.cobaltDeep : (s.t < 0.8 ? PAL.turqBase : PAL.sageDeep);
    }

    brush.set("flat_marker", colL, 1.05);
    brush.line(s.pt[0], s.pt[1], pL[0], pL[1]);

    brush.set("flat_marker", colR, 1.05);
    brush.line(s.pt[0], s.pt[1], pR[0], pR[1]);
  }

  // -------------------------------------------------------------------------
  // PASS 2: HYPERREAL 3D VOLUMETRIC MODELING & UNDULATING LOBE RELIEFS
  // -------------------------------------------------------------------------
  for (let i = 3; i < steps - 2; i++) {
    let s = spine[i];
    let pL = leftEdge[i];
    let pR = rightEdge[i];
    let lobeWave = sin(s.t * lobes * 360);

    // Left blade modeling: deep cobalt/turquoise in vein troughs, luminous sage/ice on lobe domes
    let shadeL = lobeWave > 0
      ? (paletteBias.includes("cobalt") ? PAL.turqBright : PAL.sageLight)
      : (paletteBias.includes("cobalt") ? PAL.cobaltDeep : PAL.turqDeep);

    brush.set("glaze_shader", shadeL, 0.95);
    let midL = [
      lerp(s.pt[0], pL[0], 0.55) + s.tan[0] * 10 * lobeWave,
      lerp(s.pt[1], pL[1], 0.55) + s.tan[1] * 10 * lobeWave
    ];
    brush.spline([
      [s.pt[0], s.pt[1], 0.4],
      [midL[0], midL[1], 1.1],
      [pL[0], pL[1], 0.3]
    ], 0.35);

    // Right blade modeling: deeper shadow plane with cobalt troughs and rich turquoise/sage ridges
    let shadeR = lobeWave > 0.1
      ? (paletteBias === "cobalt_heavy" ? PAL.turqBase : PAL.turqVivid)
      : PAL.cobaltAbyss;

    brush.set("glaze_shader", shadeR, 0.95);
    let midR = [
      lerp(s.pt[0], pR[0], 0.55) + s.tan[0] * 8 * lobeWave,
      lerp(s.pt[1], pR[1], 0.55) + s.tan[1] * 8 * lobeWave
    ];
    brush.spline([
      [s.pt[0], s.pt[1], 0.5],
      [midR[0], midR[1], 1.1],
      [pR[0], pR[1], 0.3]
    ], 0.35);

    // Sunlit crest highlights on the convex lobe pillows
    if (lobeWave > 0.35 && i % 2 === 0) {
      let hiCol = paletteBias.includes("sage") ? PAL.sageCream : PAL.turqIce;
      brush.set("waxy_bloom", hiCol, 0.85);
      brush.line(
        lerp(s.pt[0], pL[0], 0.3), lerp(s.pt[1], pL[1], 0.3),
        lerp(s.pt[0], pL[0], 0.82), lerp(s.pt[1], pL[1], 0.82)
      );
    }
  }

  // -------------------------------------------------------------------------
  // PASS 3: LATERAL VEINS, TORN LEAF EDGES & SUCCULENT CENTRAL MIDRIB
  // -------------------------------------------------------------------------
  // Lateral branching veins into each serration tooth
  for (let k = 1; k < lobes * 2; k++) {
    let idx = floor(map(k, 0, lobes * 2, 5, steps - 4));
    let s = spine[idx];
    let targetL = leftEdge[min(steps, idx + 3)];
    let targetR = rightEdge[min(steps, idx + 3)];

    // Dark cobalt/sage shadow directly beneath each raised lateral vein
    brush.set("2B", PAL.cobaltDeep, 0.65);
    brush.line(s.pt[0], s.pt[1] + 2, targetL[0], targetL[1] + 2);
    brush.line(s.pt[0], s.pt[1] + 2, targetR[0], targetR[1] + 2);

    // Crisp pale sage/turquoise lateral vein
    let veinCol = s.t < 0.25 ? PAL.waxyPink : (k % 2 === 0 ? PAL.sageCream : PAL.turqIce);
    brush.set("cpencil", veinCol, 0.75);
    brush.spline([
      [s.pt[0], s.pt[1], 0.9],
      [lerp(s.pt[0], targetL[0], 0.5) + s.tan[0] * 8, lerp(s.pt[1], targetL[1], 0.5) + s.tan[1] * 8, 0.7],
      [targetL[0], targetL[1], 0.2]
    ], 0.3);

    brush.spline([
      [s.pt[0], s.pt[1], 0.9],
      [lerp(s.pt[0], targetR[0], 0.5) + s.tan[0] * 8, lerp(s.pt[1], targetR[1], 0.5) + s.tan[1] * 8, 0.7],
      [targetR[0], targetR[1], 0.2]
    ], 0.3);

    // Fine capillary sub-veins & torn edge fibers
    if (k % 2 === 1) {
      let subStart = [lerp(s.pt[0], targetL[0], 0.55), lerp(s.pt[1], targetL[1], 0.55)];
      brush.set("2H", PAL.stemPale, 0.45);
      brush.line(subStart[0], subStart[1], subStart[0] + s.tan[0] * 16 + s.norm[0] * 8, subStart[1] + s.tan[1] * 16 + s.norm[1] * 8);
    }
  }

  // Succulent central midrib (transitions from rose-bole at petiole base to celadon-sage)
  for (let i = 0; i < steps - 1; i++) {
    let s0 = spine[i];
    let s1 = spine[i + 1];
    let ribW = map(s0.t, 0, 1, 5.5, 0.7);

    // Midrib shadow side
    brush.set("cpencil", s0.t < 0.22 ? PAL.boleShadow : PAL.cobaltDeep, ribW * 0.48);
    brush.line(
      s0.pt[0] - s0.norm[0] * ribW * 0.55, s0.pt[1] - s0.norm[1] * ribW * 0.55,
      s1.pt[0] - s1.norm[0] * ribW * 0.55, s1.pt[1] - s1.norm[1] * ribW * 0.55
    );

    // Midrib body
    let ribCol = s0.t < 0.18 ? PAL.waxyPink : (s0.t < 0.45 ? PAL.sageLight : PAL.stemPale);
    brush.set("glaze_shader", ribCol, ribW * 0.42);
    brush.line(s0.pt[0], s0.pt[1], s1.pt[0], s1.pt[1]);

    // Midrib glossy specular ridge
    if (i < steps - 6) {
      brush.set("specular_glaze", PAL.glazeWhite, map(s0.t, 0, 1, 0.9, 0.25));
      brush.line(
        s0.pt[0] + s0.norm[0] * ribW * 0.22, s0.pt[1] + s0.norm[1] * ribW * 0.22,
        s1.pt[0] + s1.norm[0] * ribW * 0.22, s1.pt[1] + s1.norm[1] * ribW * 0.22
      );
    }
  }

  // -------------------------------------------------------------------------
  // PASS 4: SAZ LEAF TURNOVER FLAP (Deep Cobalt or Turquoise Underside Fold)
  // -------------------------------------------------------------------------
  if (foldAt) {
    let fStart = floor(map(foldAt - 1.2, 0, lobes, 6, steps - 10));
    let fEnd = floor(map(foldAt + 0.8, 0, lobes, 12, steps - 4));
    let foldPts = [];
    for (let i = fStart; i <= fEnd; i++) {
      let s = spine[i];
      let u = map(i, fStart, fEnd, 0, 180);
      let flapDepth = sin(u) * s.wL * 0.48;
      let edgePt = leftEdge[i];
      let innerPt = [
        edgePt[0] - s.norm[0] * flapDepth,
        edgePt[1] - s.norm[1] * flapDepth
      ];
      // Fill turnover with dense cobalt & turquoise contrast
      brush.set("flat_marker", paletteBias.includes("cobalt") ? PAL.turqVivid : PAL.cobaltDeep, 0.85);
      brush.line(edgePt[0], edgePt[1], innerPt[0], innerPt[1]);

      brush.set("glaze_shader", paletteBias.includes("cobalt") ? PAL.turqIce : PAL.cobaltBright, 0.65);
      brush.line(
        lerp(edgePt[0], innerPt[0], 0.3), lerp(edgePt[1], innerPt[1], 0.3),
        innerPt[0], innerPt[1]
      );
      foldPts.push([innerPt[0], innerPt[1], 0.85]);
    }
    // Crisp tahrir inner fold line and glaze catchlight
    brush.set("tahrir_ink", PAL.tahrir, 0.85);
    brush.spline(foldPts, 0.35);
    brush.set("specular_glaze", PAL.glazeWhite, 0.65);
    brush.spline(foldPts.map(p => [p[0] + 1.5, p[1] - 1.5, 0.6]), 0.35);
  }

  // -------------------------------------------------------------------------
  // PASS 5: FINE BLACK TAHRIR OUTLINES & SERRATION TEETH
  // -------------------------------------------------------------------------
  let outlineL = leftEdge.map((p, idx) => [p[0], p[1], idx % 5 === 0 ? 1.15 : 0.65]);
  let outlineR = rightEdge.map((p, idx) => [p[0], p[1], idx % 5 === 0 ? 1.2 : 0.7]);

  brush.set("tahrir_ink", PAL.tahrir, 0.9);
  brush.spline(outlineL, 0.25);
  brush.spline(outlineR, 0.25);

  // Emphasize torn notch fibrous edges and serration tips
  for (let i = 6; i < steps - 4; i += 4) {
    let pL = leftEdge[i];
    let pR = rightEdge[i];
    brush.set("specular_glaze", PAL.glazeWhite, 0.55);
    brush.line(pL[0], pL[1], pL[0] - 4, pL[1] + 3);
    if (i % 8 === 0) {
      brush.line(pR[0], pR[1], pR[0] - 3, pR[1] - 4);
    }
  }
}

