// =============================================================================
// STAGE 4: HYPERREAL RADISH ROOTS (RAISED TOMATO-BOLE RED) & TAPROOTS
// =============================================================================
function rootPoint(cfg, u, v) {
  // u in [0, 1] from crown (0) to taproot tip (1)
  // v in [-1, 1] across the equator
  let theta = u * 180;
  // Slightly top-heavy plump radish profile tapering smoothly into the taproot cone
  let profile = sin(theta) * (1.0 + 0.14 * cos(theta) - 0.12 * pow(u, 2.2));
  let lx = v * cfg.rx * profile;
  let ly = (u - 0.5) * 2.0 * cfg.ry;

  // Subtle organic dimpling
  let dimple = 1.0 + 0.025 * sin(u * 540 + cfg.cx) * cos(v * 180);
  lx *= dimple;

  let ca = cos(cfg.angle);
  let sa = sin(cfg.angle);
  // Crown is at u=0 (pointed toward +sa, -ca i.e. top-right)
  // Wait: for angle ~ 45 deg, let's align local -Y with the direction to top-right (45 deg):
  // Top-right unit vector is (cos(-45), sin(-45)) = (0.707, -0.707).
  // If local axis Y points from crown (u=0, ly=-ry) to tail (u=1, ly=+ry),
  // then +Y points toward bottom-left (-cos(angle), +sin(angle)).
  let dirTailX = -cos(cfg.angle);
  let dirTailY = sin(cfg.angle);
  let perpX = -dirTailY;
  let perpY = dirTailX;

  return [
    cfg.cx + dirTailX * ly + perpX * lx,
    cfg.cy + dirTailY * ly + perpY * lx
  ];
}

function drawRadishRoot(cfg) {
  const latSteps = 44;
  const lonSteps = 24;

  // -------------------------------------------------------------------------
  // PASS 1: DENSE FLAT MARKER PASSAGES (Tomato-Bole Red, Carmine Shadow, Root Cream)
  // -------------------------------------------------------------------------
  for (let i = 1; i < latSteps; i++) {
    let u = i / latSteps;
    let pLeft = rootPoint(cfg, u, -0.96);
    let pMid = rootPoint(cfg, u, 0.12);
    let pRight = rootPoint(cfg, u, 0.96);

    let isWhiteTip = u > (1.0 - cfg.whiteRatio);
    let colLit = isWhiteTip ? PAL.rootCream : (u < 0.25 ? PAL.boleVivid : PAL.boleBase);
    let colDark = isWhiteTip ? PAL.waxyPink : PAL.boleShadow;

    brush.set("flat_marker", colLit, 1.15);
    brush.line(pLeft[0], pLeft[1], pMid[0], pMid[1]);

    brush.set("flat_marker", colDark, 1.15);
    brush.line(pMid[0], pMid[1], pRight[0], pRight[1]);
  }

  // -------------------------------------------------------------------------
  // PASS 2: HYPERREAL 3D SPHERICAL MODELING (Raised Bole Volume & Bounce Light)
  // -------------------------------------------------------------------------
  for (let i = 2; i < latSteps - 1; i++) {
    let u = i / latSteps;
    let whiteStart = 1.0 - cfg.whiteRatio;

    for (let j = 0; j < lonSteps; j++) {
      let v0 = map(j, 0, lonSteps, -0.98, 0.98);
      let v1 = map(j + 1, 0, lonSteps, -0.98, 0.98);
      let vMid = 0.5 * (v0 + v1);

      let p0 = rootPoint(cfg, u, v0);
      let p1 = rootPoint(cfg, u, v1);

      // Determine surface illumination (light comes from upper-left: v ~ -0.35, u ~ 0.35)
      let col, weight = 0.95;

      if (u > whiteStart + 0.06) {
        // Basal white-blushed root cap
        if (vMid < -0.15) col = PAL.rootCream;
        else if (vMid < 0.45) col = PAL.waxyPink;
        else if (vMid < 0.8) col = PAL.turqIce; // cool porcelain bounce light
        else col = PAL.cobaltWash;
      } else if (u > whiteStart - 0.08) {
        // Translucent rose-pink transition zone (waxy skin over white flesh)
        col = vMid < 0.2 ? PAL.boleLight : (vMid < 0.7 ? PAL.waxyPink : PAL.boleShadow);
      } else {
        // Main Raised Tomato-Bole Red bulb
        if (vMid < -0.68) {
          // Upper-left Fresnel edge bloom
          col = PAL.waxyPink;
        } else if (vMid < -0.12) {
          // Bright lit tomato-bole highlight zone
          col = u < 0.5 ? PAL.boleCoral : PAL.boleVivid;
        } else if (vMid < 0.38) {
          // Rich saturated Iznik Armenian bole midtone
          col = PAL.boleBase;
        } else if (vMid < 0.78) {
          // Deep carmine-bole core terminator shadow
          col = u > 0.45 ? PAL.boleDeep : PAL.boleShadow;
        } else {
          // Bottom-right rim bounce light from glossy white porcelain & turquoise leaves
          col = j === lonSteps - 1 ? PAL.turqIce : PAL.boleShadow;
        }
      }

      brush.set("glaze_shader", col, weight);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Longitudinal modeling strokes for organic fibrous skin striation
  for (let j = -8; j <= 8; j += 2) {
    let v = j / 10;
    let pts = [];
    for (let i = 2; i <= latSteps - 2; i += 4) {
      let u = i / latSteps;
      let p = rootPoint(cfg, u, v);
      pts.push([p[0], p[1], sin(u * 180)]);
    }
    let col = v < -0.1 ? PAL.boleCoral : (v < 0.45 ? PAL.boleVivid : PAL.boleDeep);
    brush.set("glaze_shader", col, 0.7);
    brush.spline(pts, 0.35);
  }

  // -------------------------------------------------------------------------
  // PASS 3: WAXY EPICUTICULAR BLOOM ON THE SKIN
  // -------------------------------------------------------------------------
  for (let k = 0; k < 42 * cfg.bloomStrength; k++) {
    let u = random(0.16, 0.72);
    let v = random(-0.82, 0.25);
    let pA = rootPoint(cfg, u, v);
    let pB = rootPoint(cfg, u + random(-0.04, 0.04), constrain(v + random(0.12, 0.28), -0.95, 0.95));
    let bloomCol = k % 3 === 0 ? PAL.waxyBloom : (k % 2 === 0 ? PAL.waxyPink : PAL.turqIce);
    brush.set("waxy_bloom", bloomCol, random(0.65, 1.15));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // -------------------------------------------------------------------------
  // PASS 4: OPTIONAL TURGID SKIN SPLIT (CRISP SNOWY INNER FLESH)
  // -------------------------------------------------------------------------
  if (cfg.hasSplit) {
    let splitU0 = 0.24, splitU1 = 0.68;
    let splitV = -0.12;
    let cleftL = [], cleftR = [], cleftCenter = [];
    for (let s = 0; s <= 12; s++) {
      let t = s / 12;
      let u = lerp(splitU0, splitU1, t);
      let gap = sin(t * 180) * 0.13;
      cleftL.push(rootPoint(cfg, u, splitV - gap));
      cleftR.push(rootPoint(cfg, u, splitV + gap));
      cleftCenter.push(rootPoint(cfg, u, splitV));
    }

    // Fill exposed crisp white radish flesh
    for (let s = 1; s < 12; s++) {
      brush.set("flat_marker", PAL.rootCream, 0.8);
      brush.line(cleftL[s][0], cleftL[s][1], cleftR[s][0], cleftR[s][1]);
      // Subtle cool inner shadow on one side of the split
      brush.set("glaze_shader", PAL.slipBlue, 0.65);
      brush.line(cleftL[s][0], cleftL[s][1], cleftCenter[s][0], cleftCenter[s][1]);
      // Crisp white highlight on the opposite inner wall
      brush.set("specular_glaze", PAL.glazeWhite, 0.8);
      brush.line(cleftCenter[s][0], cleftCenter[s][1], cleftR[s][0], cleftR[s][1]);
    }
    // Deep carmine skin rim around the split
    brush.set("tahrir_ink", PAL.boleDeep, 0.95);
    brush.spline(cleftL.map(p => [p[0], p[1], 0.9]), 0.3);
    brush.spline(cleftR.map(p => [p[0], p[1], 0.9]), 0.3);
    brush.set("specular_glaze", PAL.glazeWhite, 0.75);
    brush.spline(cleftR.map(p => [p[0] + 1.5, p[1] + 1.5, 0.7]), 0.3);
  }

  // -------------------------------------------------------------------------
  // PASS 5: HORIZONTAL LENTICEL SCARS, CROWN COLLAR & FINE BLACK TAHRIR
  // -------------------------------------------------------------------------
  // Horizontal lenticel root scars
  for (let k = 0; k < 9; k++) {
    let u = random(0.22, 0.84);
    let v = random(-0.65, 0.65);
    let span = random(0.12, 0.26);
    let s0 = rootPoint(cfg, u, v - span * 0.5);
    let s1 = rootPoint(cfg, u, v + span * 0.5);

    brush.set("2B", u > 0.7 ? PAL.soilMid : PAL.boleDeep, 0.65);
    brush.line(s0[0], s0[1], s1[0], s1[1]);

    brush.set("specular_glaze", u > 0.7 ? PAL.glazeWhite : PAL.waxyPink, 0.55);
    brush.line(s0[0], s0[1] - 1.5, s1[0], s1[1] - 1.5);

    // Tiny lateral hair rootlet sprouting from lenticel
    if (k % 2 === 0) {
      brush.set("tahrir_ink", PAL.soilDark, 0.45);
      brush.line(s1[0], s1[1], s1[0] - random(8, 22), s1[1] + random(6, 18));
    }
  }

  // Crown collar (where green petioles emerge from the red bulb)
  let cLeft = rootPoint(cfg, 0.05, -0.45);
  let cMid = rootPoint(cfg, 0.02, 0.0);
  let cRight = rootPoint(cfg, 0.05, 0.45);
  brush.set("flat_marker", PAL.sageDeep, 0.75);
  brush.line(cLeft[0], cLeft[1], cRight[0], cRight[1]);
  brush.set("glaze_shader", PAL.boleDeep, 0.85);
  brush.line(cLeft[0], cLeft[1] + 3, cRight[0], cRight[1] + 3);
  brush.set("tahrir_ink", PAL.tahrir, 0.85);
  brush.spline([[cLeft[0], cLeft[1], 0.7], [cMid[0], cMid[1], 1.1], [cRight[0], cRight[1], 0.7]], 0.3);

  // Fine Black Tahrir Outer Contour around the Radish Bulb
  let contourL = [], contourR = [];
  for (let i = 1; i <= latSteps; i += 2) {
    let u = i / latSteps;
    let pL = rootPoint(cfg, u, -1.0);
    let pR = rootPoint(cfg, u, 1.0);
    contourL.push([pL[0], pL[1], map(u, 0, 1, 0.55, 0.9)]);
    contourR.push([pR[0], pR[1], map(u, 0, 1, 0.85, 1.25)]);
  }
  brush.set("tahrir_ink", PAL.tahrir, 0.85);
  brush.spline(contourL, 0.35);
  brush.set("tahrir_ink", PAL.tahrir, 1.05);
  brush.spline(contourR, 0.35);

  // -------------------------------------------------------------------------
  // PASS 6: RAISED FRITWARE GLAZE SPECULAR HIGHLIGHTS ON THE BULB
  // -------------------------------------------------------------------------
  let hiArc1 = [], hiArc2 = [];
  for (let i = 5; i <= 32; i += 2) {
    let u = i / latSteps;
    let p1 = rootPoint(cfg, u, -0.42);
    let p2 = rootPoint(cfg, u, -0.26);
    hiArc1.push([p1[0], p1[1], sin(map(i, 5, 32, 0, 180)) * 1.3]);
    hiArc2.push([p2[0], p2[1], sin(map(i, 5, 32, 0, 180)) * 0.85]);
  }
  brush.set("specular_glaze", PAL.glazeWhite, 1.15);
  brush.spline(hiArc1, 0.35);
  brush.set("specular_glaze", PAL.glazeWhite, 0.75);
  brush.spline(hiArc2, 0.35);

  // Secondary dimpled glaze catchlights (mimicking raised bole relief under glassy glaze)
  for (let m = 0; m < 10; m++) {
    let u = random(0.18, 0.65);
    let v = random(-0.55, -0.15);
    let pt = rootPoint(cfg, u, v);
    brush.set("specular_glaze", PAL.glazeWhite, random(0.7, 1.2));
    brush.line(pt[0], pt[1], pt[0] - 4, pt[1] + 5);
  }
}

// =============================================================================
// SINUOUS TAPROOTS & FINE ROOT HAIRS
// =============================================================================
function drawTaprootAndHairs(cfg) {
  let basePt = rootPoint(cfg, 0.98, 0.0);
  let pts = [basePt, ...cfg.tail];

  // Cast shadow of the taproot in cobalt & turquoise
  brush.set("glaze_shader", PAL.cobaltMid, 0.9);
  brush.spline(pts.map((p, idx) => [p[0] + 5, p[1] + 7, map(idx, 0, pts.length - 1, 1.2, 0.3)]), 0.35);

  // Taproot fleshy core (creamy pink tapering to earthy ochre)
  brush.set("flat_marker", PAL.rootCream, 0.65);
  brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);

  brush.set("glaze_shader", PAL.waxyPink, 0.85);
  brush.spline(pts.map((p, idx) => [p[0], p[1], map(idx, 0, pts.length - 1, 1.3, 0.25)]), 0.35);

  // Shadow edge and tahrir ink outline along taproot
  brush.set("tahrir_ink", PAL.soilMid, 0.85);
  brush.spline(pts.map((p, idx) => [p[0] + 2, p[1] + 2, map(idx, 0, pts.length - 1, 1.1, 0.3)]), 0.35);

  brush.set("tahrir_ink", PAL.tahrir, 0.7);
  brush.spline(pts.map((p, idx) => [p[0] - 2, p[1] - 1, map(idx, 0, pts.length - 1, 0.9, 0.2)]), 0.35);

  // Wet glaze highlight along the taproot
  brush.set("specular_glaze", PAL.glazeWhite, 0.75);
  brush.spline(pts.map((p, idx) => [p[0] - 1, p[1] - 1, map(idx, 0, pts.length - 1, 1.0, 0.2)]), 0.35);

  // Branching fine root hairs along the taproot
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i], b = pts[i + 1];
    for (let s = 0; s < 5; s++) {
      let t = s / 5;
      let hx = lerp(a[0], b[0], t);
      let hy = lerp(a[1], b[1], t);
      let side = (s % 2 === 0 ? 1 : -1);
      let h1 = [hx + side * random(14, 34), hy + random(8, 26), 0.6];
      let h2 = [h1[0] + side * random(12, 28) - 8, h1[1] + random(10, 24), 0.2];

      brush.set("tahrir_ink", s % 2 === 0 ? PAL.soilDark : PAL.tahrir, 0.48);
      brush.spline([[hx, hy, 0.8], h1, h2], 0.35);
    }
  }
}

// =============================================================================
// STAGE 5: SOIL GRIT IN THE ROOT HAIRS & ON THE GLOSSY SURFACE
// =============================================================================
function drawSoilGritPass(radishes) {
  for (let r of radishes) {
    // 1. Soil grit clinging to taproots and root hairs
    for (let i = 0; i < r.tail.length; i++) {
      let tp = r.tail[i];
      brush.set("soil_grit", PAL.soilDark, 1.0);
      brush.line(tp[0] - 12, tp[1] - 8, tp[0] + 14, tp[1] + 12);

      brush.set("soil_grit", PAL.tahrir, 0.85);
      brush.line(tp[0] - 6, tp[1] + 4, tp[0] + 8, tp[1] - 6);

      // Distinct 3D soil crumbs with micro-highlights
      for (let c = 0; c < 6; c++) {
        let cx = tp[0] + random(-24, 24);
        let cy = tp[1] + random(-18, 22);
        let sz = random(2, 5.5);
        brush.set("flat_marker", c % 2 === 0 ? PAL.soilDark : PAL.soilMid, 0.35);
        brush.line(cx, cy, cx + sz, cy + sz * 0.6);
        brush.set("tahrir_ink", PAL.tahrir, 0.7);
        brush.line(cx, cy + sz * 0.5, cx + sz, cy + sz * 0.8);
        if (c % 2 === 0) {
          brush.set("specular_glaze", PAL.glazeWhite, 0.5);
          brush.line(cx, cy, cx + 1.5, cy);
        }
      }
    }

    // 2. Fine soil specks in the root dimples and basal white cone
    for (let m = 0; m < 7; m++) {
      let u = random(0.62, 0.95);
      let v = random(-0.5, 0.65);
      let pt = rootPoint(r, u, v);
      brush.set("soil_grit", PAL.soilDark, 0.65);
      brush.line(pt[0] - 4, pt[1] - 3, pt[0] + 5, pt[1] + 4);
    }
  }

  // 3. Loose soil crumbs & mineral specks scattered on the glossy white surface near the roots
  for (let i = 0; i < 65; i++) {
    let sx = random(95, 580);
    let sy = random(760, 1155);
    // Keep crumbs near the diagonal root zone
    if (sx + sy > 1080 && sx + sy < 1620) {
      let sz = random(1.5, 5.0);
      // Tiny cobalt cast shadow under each crumb on the white glaze
      brush.set("2B", PAL.cobaltWash, 0.65);
      brush.line(sx + 1, sy + 2, sx + sz + 2, sy + 3);

      // Dark earth crumb
      brush.set("tahrir_ink", i % 3 === 0 ? PAL.tahrir : PAL.soilDark, random(0.6, 1.1));
      brush.line(sx, sy, sx + sz, sy + sz * 0.4);

      if (sz > 3.2) {
        brush.set("specular_glaze", PAL.glazeWhite, 0.45);
        brush.line(sx, sy - 0.5, sx + 1.2, sy - 0.5);
      }
    }
  }
}

// =============================================================================
// STAGE 6: WATER DROPLETS & FRITWARE GLAZE SPECULAR SHEEN
// =============================================================================
function drawWaterDroplets(radishes) {
  const drops = [
    // On radish roots
    { x: 462, y: 650, r: 6.5, bg: "bole" },
    { x: 495, y: 688, r: 5.0, bg: "bole" },
    { x: 315, y: 718, r: 6.0, bg: "bole" },
    { x: 468, y: 825, r: 7.2, bg: "bole" },
    { x: 505, y: 868, r: 5.5, bg: "bole" },
    { x: 335, y: 862, r: 7.0, bg: "bole" },
    { x: 375, y: 912, r: 5.2, bg: "cream" },
    // On saz leaves
    { x: 745, y: 435, r: 6.5, bg: "leaf" },
    { x: 865, y: 365, r: 5.5, bg: "leaf" },
    { x: 675, y: 340, r: 6.0, bg: "leaf" },
    { x: 810, y: 505, r: 5.8, bg: "leaf" },
    { x: 635, y: 245, r: 5.2, bg: "leaf" },
    // On the glossy white porcelain surface
    { x: 425, y: 995, r: 7.5, bg: "slip" },
    { x: 545, y: 925, r: 6.0, bg: "slip" },
    { x: 665, y: 745, r: 6.8, bg: "slip" }
  ];

  for (let d of drops) {
    let r = d.r;
    // Upper-left interior refraction dark crescent
    let shadowCol = d.bg === "bole" ? PAL.boleDeep : (d.bg === "leaf" ? PAL.cobaltAbyss : PAL.cobaltMid);
    brush.set("tahrir_ink", shadowCol, 0.85);
    brush.arc(d.x, d.y, r, 195, 345);

    // Lower-right luminous caustic glow through the droplet
