async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(108);
  noiseSeed(108);

  // Custom ultra-fine graphite needle and soft charcoal blender
  brush.add("needle", {
    type: "default",
    weight: 0.35,
    scatter: 0.08,
    sharpness: 0.92,
    grain: 18,
    opacity: 190,
    spacing: 0.12,
    pressure: [0.4, 1.15, 0.3],
    noise: 0.35
  });

  brush.add("smudge", {
    type: "default",
    weight: 6.5,
    scatter: 1.8,
    sharpness: 0.12,
    grain: 9,
    opacity: 28,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.6
  });

  // Schlieren fluid-dynamics vector field (buoyant narrowing jet + Kelvin-Helmholtz vortices)
  const vortices = [
    { x: 536, y: 735, r: 78, s: -58 },
    { x: 660, y: 675, r: 85, s: 64 },
    { x: 505, y: 555, r: 112, s: -82 },
    { x: 682, y: 465, r: 108, s: 78 },
    { x: 525, y: 345, r: 125, s: -74 },
    { x: 675, y: 265, r: 132, s: 85 },
    { x: 585, y: 155, r: 150, s: -68 }
  ];

  brush.addField("schlierenFlow", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let i = 0; i < cols; i++) {
      for (let j = 0; j < rows; j++) {
        let px = (i / (cols - 1)) * 1200;
        let py = (j / (rows - 1)) * 1200;

        // Base upward buoyant flow (-90 deg in screen coords)
        let vx = 0;
        let vy = -1.0;

        // Necking pinch just above the cup rim (y = 750..910)
        if (py > 700 && py < 930) {
          let pinch = map(py, 930, 720, 0.45, -0.05);
          vx += (600 - px) * 0.0045 * pinch;
        }

        // Sinuous primary plume oscillation
        let spineX = 600 + sin(py * 0.65) * map(py, 910, 80, 4, 42);
        vx += (spineX - px) * 0.0018;

        // Superimpose Kelvin-Helmholtz vortex roll-ups
        for (let v of vortices) {
          let dx = px - v.x;
          let dy = py - v.y;
          let d2 = dx * dx + dy * dy;
          let r2 = v.r * v.r;
          let factor = (v.s / 60) * exp(-d2 / (2 * r2));
          vx += (-dy / v.r) * factor;
          vy += (dx / v.r) * factor;
        }

        let n = noise(px * 0.006, py * 0.006, t * 0.1) - 0.5;
        let ang = atan2(vy, vx) + n * 28;
        field[i][j] = ang;
      }
    }
    return field;
  });
}

// ---------------------------------------------------------------------------
// GEOMETRY & DRAWING HELPERS
// ---------------------------------------------------------------------------

function polyWash(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

function polyFill(pts, col, opacity, bleed = 0.08, tex = 0.25) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.fill(col, opacity, bleed, tex);
}

function ellipsePts(cx, cy, rx, ry, n = 64, aStart = 0, aEnd = 360) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = lerp(aStart, aEnd, i / n);
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
  }
  return pts;
}

// Builds a ribbon polygon offset between d1(t) and d2(t) along normal of spine
function buildRibbonPolygon(spine, d1Fn, d2Fn) {
  let leftSide = [];
  let rightSide = [];
  let n = spine.length;
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let p0 = spine[max(0, i - 1)];
    let p1 = spine[min(n - 1, i + 1)];
    let tx = p1[0] - p0[0];
    let ty = p1[1] - p0[1];
    let len = sqrt(tx * tx + ty * ty) || 1;
    // Normal pointing right of upward-moving spine
    let nx = -ty / len;
    let ny = tx / len;
    // Ensure normal consistently points toward +x for vertical plumes
    if (ty < 0 && nx < 0) {
      nx = -nx;
      ny = -ny;
    }
    let off1 = d1Fn(t, i);
    let off2 = d2Fn(t, i);
    leftSide.push([spine[i][0] + nx * off1, spine[i][1] + ny * off1]);
    rightSide.push([spine[i][0] + nx * off2, spine[i][1] + ny * off2]);
  }
  return leftSide.concat(rightSide.reverse());
}

// Renders a knife-edged schlieren refractive gradient ribbon:
// Bright silver/white on one side of the shear spine, razor-sharp transition,
// deep graphite/black on the opposite side, fading smoothly into mid-grey.
function drawSchlierenPlumeRibbon(spine, wLight, wDark, intensity = 1.0, invert = false) {
  let sgn = invert ? -1 : 1;

  // Envelope tapers at start and end of spine
  let env = (t) => sin(pow(t, 0.75) * 180);

  // 1. Broad outer diffuse silver glow (light side) and charcoal shadow (dark side)
  let outerLight = buildRibbonPolygon(
    spine,
    (t) => -sgn * wLight * 1.15 * env(t),
    (t) => -sgn * wLight * 0.02 * env(t)
  );
  polyWash(outerLight, "#aeb3b8", 42 * intensity);

  let midLight = buildRibbonPolygon(
    spine,
    (t) => -sgn * wLight * 0.65 * env(t),
    (t) => 0
  );
  polyWash(midLight, "#CFD4D9", 68 * intensity);

  let coreLight = buildRibbonPolygon(
    spine,
    (t) => -sgn * wLight * 0.28 * env(t),
    (t) => 0
  );
  polyWash(coreLight, "#eef2f6", 115 * intensity);

  let knifeLight = buildRibbonPolygon(
    spine,
    (t) => -sgn * max(2.5, wLight * 0.11 * env(t)),
    (t) => 0
  );
  polyWash(knifeLight, "#ffffff", 185 * intensity);

  // 2. Dark refractive shadow side (immediately across the spine!)
  let outerDark = buildRibbonPolygon(
    spine,
    (t) => 0,
    (t) => sgn * wDark * 1.15 * env(t)
  );
  polyWash(outerDark, "#54585e", 48 * intensity);

  let midDark = buildRibbonPolygon(
    spine,
    (t) => 0,
    (t) => sgn * wDark * 0.62 * env(t)
  );
  polyWash(midDark, "#2e3136", 82 * intensity);

  let coreDark = buildRibbonPolygon(
    spine,
    (t) => 0,
    (t) => sgn * wDark * 0.28 * env(t)
  );
  polyWash(coreDark, "#141619", 135 * intensity);

  let knifeDark = buildRibbonPolygon(
    spine,
    (t) => 0,
    (t) => sgn * max(2.5, wDark * 0.11 * env(t))
  );
  polyWash(knifeDark, "#07080a", 190 * intensity);

  // 3. Hard graphite & charcoal shear-line strokes catching the knife-edge interface
  let lightEdgeSpline = [];
  let darkEdgeSpline = [];
  let smudgeLight = [];
  let smudgeDark = [];

  let n = spine.length;
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let p0 = spine[max(0, i - 1)];
    let p1 = spine[min(n - 1, i + 1)];
    let tx = p1[0] - p0[0];
    let ty = p1[1] - p0[1];
    let len = sqrt(tx * tx + ty * ty) || 1;
    let nx = -ty / len;
    let ny = tx / len;
    if (ty < 0 && nx < 0) {
      nx = -nx;
      ny = -ny;
    }
    let e = env(t);
    let pPress = 0.35 + 0.95 * e;

    lightEdgeSpline.push([
      spine[i][0] - sgn * nx * 1.6,
      spine[i][1] - sgn * ny * 1.6,
      pPress
    ]);
    darkEdgeSpline.push([
      spine[i][0] + sgn * nx * 1.6,
      spine[i][1] + sgn * ny * 1.6,
      pPress
    ]);
    smudgeLight.push([
      spine[i][0] - sgn * nx * (wLight * 0.32 * e),
      spine[i][1] - sgn * ny * (wLight * 0.32 * e),
      pPress * 0.8
    ]);
    smudgeDark.push([
      spine[i][0] + sgn * nx * (wDark * 0.32 * e),
      spine[i][1] + sgn * ny * (wDark * 0.32 * e),
      pPress * 0.8
    ]);
  }

  // Smudged charcoal gradients along both lobes
  brush.set("smudge", "#f2f6fa", 0.9 * intensity);
  brush.spline(smudgeLight, 0.5);

  brush.set("smudge", "#15171b", 0.9 * intensity);
  brush.spline(smudgeDark, 0.5);

  brush.set("charcoal", "#e5eaef", 0.42 * intensity);
  brush.spline(lightEdgeSpline, 0.5);

  brush.set("charcoal", "#121417", 0.45 * intensity);
  brush.spline(darkEdgeSpline, 0.5);

  // Razor-sharp graphite / silver knife edges
  brush.set("needle", "#ffffff", 0.95 * intensity);
  brush.spline(lightEdgeSpline, 0.55);

  brush.set("needle", "#050608", 1.0 * intensity);
  brush.spline(darkEdgeSpline, 0.55);
}

// Generates a spiral Kelvin-Helmholtz vortex spine
function makeVortexSpine(cx, cy, rStart, rEnd, aStart, aEnd, steps = 36, stretchY = 1.08) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = lerp(aStart, aEnd, t);
    let r = lerp(rStart, rEnd, pow(t, 0.88));
    let wob = (noise(cx * 0.01 + t * 2.5, cy * 0.01) - 0.5) * 8 * (1 - t * 0.5);
    let x = cx + cos(ang) * (r + wob);
    let y = cy + sin(ang) * (r + wob) * stretchY;
    pts.push([x, y]);
  }
  return pts;
}

