function drawSaucer() {
  // 1. Cast shadow on the stark grey table surface (slightly offset right & down, matching left window light)
  let shadowLayers = [
    { cx: 616, cy: 1084, rx: 225, ry: 42, col: "#54575c", op: 75 },
    { cx: 614, cy: 1082, rx: 198, ry: 36, col: "#3c3f44", op: 95 },
    { cx: 610, cy: 1080, rx: 172, ry: 30, col: "#232529", op: 130 },
    { cx: 606, cy: 1078, rx: 145, ry: 24, col: "#101215", op: 175 },
    { cx: 603, cy: 1076, rx: 118, ry: 18, col: "#050608", op: 220 }
  ];
  for (let sh of shadowLayers) {
    polyWash(ellipsePts(sh.cx, sh.cy, sh.rx, sh.ry, 64), sh.col, sh.op);
  }

  // Soft charcoal edge along cast shadow perimeter
  brush.set("charcoal", "#16181c", 0.55);
  brush.arc(610, 1080, 165, 10, 170);

  // 2. Saucer Underside Belly ( curving from outer rim y=1042 down to foot ring y=1075 )
  let strips = 36;
  for (let i = 0; i < strips; i++) {
    let t0 = i / strips;
    let t1 = (i + 1) / strips;
    let a0 = lerp(0, 180, t0);
    let a1 = lerp(0, 180, t1);
    let aMid = (a0 + a1) * 0.5;

    let topX0 = 600 + cos(a0) * 192;
    let topY0 = 1042 + sin(a0) * 40;
    let topX1 = 600 + cos(a1) * 192;
    let topY1 = 1042 + sin(a1) * 40;

    let botX0 = 600 + cos(a0) * 116;
    let botY0 = 1074 + sin(a0) * 23;
    let botX1 = 600 + cos(a1) * 116;
    let botY1 = 1074 + sin(a1) * 23;

    // Illumination across curved porcelain underside: bright bounce on left, dark core in middle-right, table bounce on far right
    let u = t0; // 0 = right, 0.5 = front center, 1 = left
    let col = "#7a7e84";
    if (u > 0.72) col = "#d0d5da";
    else if (u > 0.56) col = "#a6abb0";
    else if (u > 0.42) col = "#6e7278";
    else if (u > 0.22) col = "#303338";
    else if (u > 0.08) col = "#4c5056";
    else col = "#84898f";

    polyWash([[topX0, topY0], [topX1, topY1], [botX1, botY1], [botX0, botY0]], col, 225);
  }

  // 3. Saucer Top Concave Dish (cx = 600, cy = 1040, rx = 192, ry = 40)
  // Base porcelain tone
  polyWash(ellipsePts(600, 1040, 192, 40, 72), "#b8bdc2", 240);

  // Radial angular sectors to capture glossy concave porcelain reflections
  let sectors = 48;
  for (let i = 0; i < sectors; i++) {
    let a0 = (i / sectors) * 360;
    let a1 = ((i + 1) / sectors) * 360;
    let aMid = (a0 + a1) * 0.5;

    let pOuter0 = [600 + cos(a0) * 190, 1040 + sin(a0) * 39];
    let pOuter1 = [600 + cos(a1) * 190, 1040 + sin(a1) * 39];
    let pInner0 = [600 + cos(a0) * 68, 1034 + sin(a0) * 15];
    let pInner1 = [600 + cos(a1) * 68, 1034 + sin(a1) * 15];

    // Left wing catches bright studio window light (135..245 deg)
    // Back-left catches soft silver (245..320 deg)
    // Right-front catches deep reflection of cup & dark room (340..75 deg)
    // Front-center catches crisp grey-white reflection (75..135 deg)
    let col = "#afb4ba";
    let op = 175;
    if (aMid >= 145 && aMid < 225) {
      col = aMid > 165 && aMid < 205 ? "#f5f8fb" : "#e0e5ea";
      op = 220;
    } else if (aMid >= 225 && aMid < 295) {
      col = "#c7ccd1";
      op = 180;
    } else if (aMid >= 295 && aMid < 350) {
      col = "#8b9096";
      op = 180;
    } else if (aMid >= 350 || aMid < 58) {
      col = aMid < 32 ? "#45494f" : "#64686e";
      op = 200;
    } else if (aMid >= 58 && aMid < 105) {
      col = "#959a9f";
      op = 175;
    } else {
      col = "#cfd4d9";
      op = 195;
    }

    polyWash([pOuter0, pOuter1, pInner1, pInner0], col, op);
  }

  // 4. Saucer Inner Well & Cast Shadow of the Cup inside the Saucer
  polyWash(ellipsePts(608, 1035, 96, 21, 56), "#383b40", 145);
  polyWash(ellipsePts(606, 1034, 78, 17, 56), "#1d1f23", 195);
  polyWash(ellipsePts(602, 1033, 64, 14, 56), "#0a0b0e", 235);

  // Crisp sunken well ridge ring (left side catching grazing light, right side in shadow)
  let wellHighlight = ellipsePts(600, 1034, 82, 18, 36, 125, 255).map((p) => [p[0], p[1], 0.8]);
  brush.set("needle", "#f4f7fa", 0.85);
  brush.spline(wellHighlight, 0.5);

  let wellShadow = ellipsePts(600, 1034, 82, 18, 36, -55, 115).map((p) => [p[0], p[1], 0.8]);
  brush.set("needle", "#23262b", 0.75);
  brush.spline(wellShadow, 0.5);

  // 5. Saucer Rim Specular Highlights & Graphite Contour Work
  // Front-left brilliant porcelain rim reflection
  let frontLeftRim = ellipsePts(600, 1040, 191, 39.5, 40, 95, 215).map((p) => [p[0], p[1], 1.0]);
  brush.set("rotring", "#ffffff", 0.95);
  brush.spline(frontLeftRim, 0.5);

  let frontLeftInnerRim = ellipsePts(600, 1041, 185, 37.5, 36, 110, 205).map((p) => [p[0], p[1], 0.85]);
  brush.set("needle", "#ffffff", 0.8);
  brush.spline(frontLeftInnerRim, 0.5);

  // Back-right rim specular catch
  let backRightRim = ellipsePts(600, 1040, 191, 39.5, 36, 285, 365).map((p) => [p[0], p[1], 0.85]);
  brush.set("needle", "#f0f4f8", 0.85);
  brush.spline(backRightRim, 0.5);

  // Dark underside contour edge
  let saucerBotEdge = ellipsePts(600, 1074, 116, 23, 40, 10, 170).map((p) => [p[0], p[1], 0.9]);
  brush.set("HB", "#0a0c0e", 0.8);
  brush.spline(saucerBotEdge, 0.5);

  let saucerOuterLowerRim = ellipsePts(600, 1044, 192, 40, 48, 5, 175).map((p) => [p[0], p[1], 0.85]);
  brush.set("2H", "#282b30", 0.65);
  brush.spline(saucerOuterLowerRim, 0.5);
}

