// Helper for cup 3D profile geometry:
// v in [0, 1] from rim (y = 905) down to foot base (y = 1031)
function cupProfile(v) {
  let y = lerp(905, 1031, v);
  // Classic curved Italian espresso cup profile (fuller upper wall, tapering gracefully to foot)
  let rx = lerp(104, 55, pow(v, 1.32)) + sin(v * 180) * 6.5;
  let ry = lerp(26.5, 13.5, pow(v, 1.25));
  return { y, rx, ry };
}

function cupSurfacePt(u, v) {
  // u in [0, 1] across front visible hemisphere: u=0 is left edge (180 deg), u=1 is right edge (0 deg)
  let ang = lerp(180, 0, u);
  let prof = cupProfile(v);
  let x = 600 + cos(ang) * prof.rx;
  let y = prof.y + sin(ang) * prof.ry;
  return [x, y];
}

function drawCupAndHandle() {
  // 1. Draw the Porcelain Handle on the right side first (so cup body cleanly overlaps the front join)
  drawPorcelainHandle();

  // 2. Render the Hyperreal Glazed Porcelain Cup Body via a high-density 3D surface mesh (48 cols x 28 rows)
  let cols = 48;
  let rows = 28;

  for (let r = 0; r < rows; r++) {
    let v0 = r / rows;
    let v1 = (r + 1) / rows;
    let vMid = (v0 + v1) * 0.5;

    for (let c = 0; c < cols; c++) {
      let u0 = c / cols;
      let u1 = (c + 1) / cols;
      let uMid = (u0 + u1) * 0.5;

      let p00 = cupSurfacePt(u0, v0);
      let p10 = cupSurfacePt(u1, v0);
      let p11 = cupSurfacePt(u1, v1);
      let p01 = cupSurfacePt(u0, v1);

      // Compute exact hyperreal porcelain reflectance at (uMid, vMid):
      let col = evaluatePorcelainShader(uMid, vMid);
      polyWash([p00, p10, p11, p01], col, 238);
    }
  }

  // 3. Crisp Specular Window Reflection Overlay & Muntin Bars (curved perspectivally on the cup wall!)
  // Window occupies u in [0.13, 0.43], v in [0.10, 0.76]
  let winPanes = [
    { uA: 0.135, uB: 0.268, vA: 0.11, vB: 0.41, bright: "#ffffff" }, // Top-left pane
    { uA: 0.292, uB: 0.425, vA: 0.11, vB: 0.41, bright: "#f4f8fc" }, // Top-right pane
    { uA: 0.135, uB: 0.268, vA: 0.45, vB: 0.75, bright: "#edf2f7" }, // Bottom-left pane
    { uA: 0.292, uB: 0.425, vA: 0.45, vB: 0.75, bright: "#e2e8ee" }  // Bottom-right pane
  ];

  for (let pane of winPanes) {
    let pts = [];
    // Sample top edge
    for (let i = 0; i <= 8; i++) pts.push(cupSurfacePt(lerp(pane.uA, pane.uB, i / 8), pane.vA));
    // Right edge
    for (let i = 1; i <= 8; i++) pts.push(cupSurfacePt(pane.uB, lerp(pane.vA, pane.vB, i / 8)));
    // Bottom edge
    for (let i = 1; i <= 8; i++) pts.push(cupSurfacePt(lerp(pane.uB, pane.uA, i / 8), pane.vB));
    // Left edge
    for (let i = 1; i < 8; i++) pts.push(cupSurfacePt(pane.uA, lerp(pane.vB, pane.vA, i / 8)));

    polyWash(pts, pane.bright, 215);

    // Crisp graphite/white edge definition along each reflected window pane
    let topCrv = [];
    for (let i = 0; i <= 8; i++) {
      let pt = cupSurfacePt(lerp(pane.uA, pane.uB, i / 8), pane.vA);
      topCrv.push([pt[0], pt[1], 0.85]);
    }
    brush.set("needle", "#ffffff", 0.75);
    brush.spline(topCrv, 0.5);
  }

  // Dark warped window muntin cross-bars (vertical meridian at u=0.28, horizontal latitude at v=0.43)
  let vBar = [];
  for (let i = 0; i <= 14; i++) {
    let pt = cupSurfacePt(0.28, lerp(0.10, 0.76, i / 14));
    vBar.push([pt[0], pt[1], 0.85]);
  }
  brush.set("2H", "#32363c", 0.75);
  brush.spline(vBar, 0.5);

  let hBar = [];
  for (let i = 0; i <= 14; i++) {
    let pt = cupSurfacePt(lerp(0.13, 0.43, i / 14), 0.43);
    hBar.push([pt[0], pt[1], 0.85]);
  }
  brush.set("2H", "#32363c", 0.75);
  brush.spline(hBar, 0.5);

  // Secondary narrow vertical highlight strip near left Fresnel edge (u = 0.05)
  let fresnelStrip = [];
  for (let i = 0; i <= 16; i++) {
    let pt = cupSurfacePt(0.045, lerp(0.06, 0.88, i / 16));
    fresnelStrip.push([pt[0], pt[1], 0.9]);
  }
  brush.set("needle", "#eef3f8", 0.85);
  brush.spline(fresnelStrip, 0.5);

  // 4. Fine Hyperreal Graphite Cross-Contour Shading lines over the porcelain body
  for (let r = 2; r < 26; r += 2) {
    let v = r / 28;
    // Shadow core contour lines (u in 0.46..0.72)
    let coreCrv = [];
    for (let i = 0; i <= 12; i++) {
      let u = lerp(0.45, 0.72, i / 12);
      let pt = cupSurfacePt(u, v);
      coreCrv.push([pt[0], pt[1], sin((i / 12) * 180) * 0.75]);
    }
    brush.set("2H", "#191c20", 0.38);
    brush.spline(coreCrv, 0.5);
  }

  // Crisp outer contour outlines of the cup walls and foot
  let leftWallCrv = [];
  let rightWallCrv = [];
  for (let i = 0; i <= 20; i++) {
    let v = i / 20;
    let pL = cupSurfacePt(0, v);
    let pR = cupSurfacePt(1, v);
    leftWallCrv.push([pL[0], pL[1], 0.85]);
    rightWallCrv.push([pR[0], pR[1], 0.85]);
  }
  brush.set("needle", "#d8dde2", 0.75);
  brush.spline(leftWallCrv, 0.5);
  brush.set("needle", "#25282d", 0.8);
  brush.spline(rightWallCrv, 0.5);

  // Foot ring resting in saucer well
  let footCrv = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let pt = cupSurfacePt(u, 1.0);
    footCrv.push([pt[0], pt[1], 0.9]);
  }
  brush.set("HB", "#08090b", 0.85);
  brush.spline(footCrv, 0.5);
}

// Computes the hyperreal porcelain color value at normalized coordinates (u, v)
function evaluatePorcelainShader(u, v) {
  // Base horizontal cylindrical shading (u = 0 left, u = 1 right)
  let lum = 0.55;

  if (u < 0.08) {
    // Left grazing Fresnel rim light
    lum = map(u, 0, 0.08, 0.84, 0.62);
  } else if (u < 0.13) {
    // Dark window frame border before window reflection
    lum = map(u, 0.08, 0.13, 0.62, 0.34);
  } else if (u < 0.435) {
    // Window reflection zone (with dark muntin crossbars and lower horizon drop)
    if (v > 0.10 && v < 0.76) {
      let inMuntinU = abs(u - 0.28) < 0.016;
      let inMuntinV = abs(v - 0.43) < 0.022;
      if (inMuntinU || inMuntinV) {
        lum = 0.24;
      } else {
        lum = map(v, 0.10, 0.76, 0.97, 0.84) - (u - 0.13) * 0.18;
      }
    } else {
      lum = 0.68;
    }
  } else if (u < 0.70) {
    // Deep studio interior core reflection (high-contrast dark band right next to window!)
    let dCore = sin(map(u, 0.435, 0.70, 0, 180));
    lum = 0.32 - dCore * 0.21;
  } else if (u < 0.91) {
    // Luminous bounce light reflected upward from the right wing of the white porcelain saucer
    let dBounce = sin(map(u, 0.70, 0.91, 0, 180));
    lum = 0.34 + dBounce * 0.44;
  } else {
    // Far right edge turning away into handle shadow
    lum = map(u, 0.91, 1.0, 0.42, 0.18);
  }

  // Vertical modulation:
  // Near v = 0.78..0.92, the curved lower belly of the cup reflects the dark saucer horizon & bright saucer well rim
  if (v > 0.77 && v < 0.87) {
    lum *= 0.62; // Dark horizon ring reflected in lower curve
  } else if (v >= 0.87 && v < 0.95) {
    lum = min(0.92, lum * 1.25 + 0.18); // Bright saucer dish bounce ring at the base
  } else if (v >= 0.95) {
    lum *= 0.45; // Occlusion crease at foot
  }

  let g = constrain( round(lum * 250), 12, 252 );
  // Slight cool-silver porcelain tint
  let r = constrain(g - 3, 10, 250);
  let b = constrain(g + 4, 14, 255);
  return color(r, g, b);
}

function drawPorcelainHandle() {
  // Parametric tubular handle loop on the right side of the cup
  let outerPts = [
    [694, 916], [732, 914], [758, 926], [768, 948],
    [762, 974], [740, 996], [706, 1008], [670, 1010]
  ];
  let innerPts = [
    [690, 936], [718, 935], [736, 944], [740, 958],
    [732, 974], [712, 986], [686, 992], [672, 992]
  ];

  // Interpolate smooth splines for outer, mid-ridge, and inner handle contours
  let steps = 28;
  let getPt = (arr, t) => {
    let idx = t * (arr.length - 1);
    let i0 = floor(idx);
    let i1 = min(arr.length - 1, i0 + 1);
    let f = idx - i0;
    return [lerp(arr[i0][0], arr[i1][0], f), lerp(arr[i0][1], arr[i1][1], f)];
  };

  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let pOut0 = getPt(outerPts, t0);
    let pOut1 = getPt(outerPts, t1);
    let pIn0 = getPt(innerPts, t0);
    let pIn1 = getPt(innerPts, t1);

    // Subdivide across handle thickness (s in [0, 1] from outer edge to inner hole)
    let bands = 6;
    for (let b = 0; b < bands; b++) {
      let s0 = b / bands;
      let s1 = (b + 1) / bands;
      let sMid = (s0 + s1) * 0.5;

      let q00 = [lerp(pOut0[0], pIn0[0], s0), lerp(pOut0[1], pIn0[1], s0)];
      let q10 = [lerp(pOut1[0], pIn1[0], s0), lerp(pOut1[1], pIn1[1], s0)];
      let q11 = [lerp(pOut1[0], pIn1[0], s1), lerp(pOut1[1], pIn1[1], s1)];
      let q01 = [lerp(pOut0[0], pIn0[0], s1), lerp(pOut0[1], pIn0[1], s1)];

      // Tubular porcelain reflection: bright top-outer ridge, dark core ribbon in middle, bounce on inner edge
      let col = "#7a7e84";
      if (sMid < 0.22) col = t0 < 0.55 ? "#f2f6fa" : "#b5bac0";
      else if (sMid < 0.42) col = t0 < 0.45 ? "#d2d7dc" : "#787c82";
      else if (sMid < 0.72) col = "#1c1f24"; // Classic dark porcelain ribbon reflection
      else col = "#9ca1a7";

      polyWash([q00, q10, q11, q01], col, 235);
    }
  }

  // Crisp specular highlight along upper-outer handle ridge
  let ridgeSpline = [];
  for (let i = 0; i <= 20; i++) {
    let t = (i / 20) * 0.72;
    let pOut = getPt(outerPts, t);
    let pIn = getPt(innerPts, t);
    ridgeSpline.push([lerp(pOut[0], pIn[0], 0.14), lerp(pOut[1], pIn[1], 0.14), 0.9]);
  }
  brush.set("rotring", "#ffffff", 0.85);
  brush.spline(ridgeSpline, 0.5);

  // Dark core reflection spline inside handle
  let coreSpline = [];
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let pOut = getPt(outerPts, t);
    let pIn = getPt(innerPts, t);
    coreSpline.push([lerp(pOut[0], pIn[0], 0.56), lerp(pOut[1], pIn[1], 0.56), 0.85]);
  }
  brush.set("HB", "#0d0f12", 0.75);
  brush.spline(coreSpline, 0.5);

  // Crisp inner and outer handle contour lines
  brush.set("needle", "#22252a", 0.7);
  brush.spline(outerPts.map((p) => [p[0], p[1], 0.8]), 0.5);
  brush.spline(innerPts.map((p) => [p[0], p[1], 0.8]), 0.5);
}

// ---------------------------------------------------------------------------
// STAGE 5: CUP RIM, INNER WALL & TIGER-STRIPED ESPRESSO CREMA
// ---------------------------------------------------------------------------

function drawCupRimAndCrema() {
  // 1. Thick Glazed Porcelain Rim Lip (Outer rx=104, ry=26.5; Inner rx=94, ry=23.2 at y=905)
  let rimSegs = 60;
  for (let i = 0; i < rimSegs; i++) {
    let a0 = (i / rimSegs) * 360;
    let a1 = ((i + 1) / rimSegs) * 360;
    let aMid = (a0 + a1) * 0.5;

    let pOut0 = [600 + cos(a0) * 104, 905 + sin(a0) * 26.5];
    let pOut1 = [600 + cos(a1) * 104, 905 + sin(a1) * 26.5];
    let pIn0 = [600 + cos(a0) * 94, 905 + sin(a0) * 23.2];
    let pIn1 = [600 + cos(a1) * 94, 905 + sin(a1) * 23.2];

    // Top lip catches brilliant overhead/left light
    let col = "#d8dde2";
    if (aMid >= 115 && aMid < 245) col = "#ffffff";
    else if (aMid >= 245 && aMid < 330) col = "#e2e7ec";
    else if (aMid >= 330 || aMid < 45) col = "#9ca1a7";
    else col = "#eef2f6";

    polyWash([pOut0, pOut1, pIn1, pIn0], col, 240);
  }

  // 2. Inner Porcelain Wall visible above the crema surface (between y=905 and y=912)
  // Left inside wall is in shadow from left light; right inside wall catches bright light!
  let innerWallSegs = 40;
  for (let i = 0; i < innerWallSegs; i++) {
    let a0 = lerp(180, 360, i / innerWallSegs);
    let a1 = lerp(180, 360, (i + 1) / innerWallSegs);
    let u = i / innerWallSegs; // 0 = left inside, 1 = right inside

    let top0 = [600 + cos(a0) * 94, 905 + sin(a0) * 23.2];
    let top1 = [600 + cos(a1) * 94, 905 + sin(a1) * 23.2];
    let bot0 = [600 + cos(a0) * 91, 913 + sin(a0) * 21.5];
    let bot1 = [600 + cos(a1) * 91, 913 + sin(a1) * 21.5];

    let lum = map(u, 0, 1, 0.24, 0.92);
    // Warm-cool reflection from the crema below
    let g = round(lum * 245);
    polyWash([top0, top1, bot1, bot0], color(g, g, min(255, g + 3)), 235);
  }

  // 3. The Tiger-Striped Espresso Crema Surface (cx = 600, cy = 912, rx = 91.5, ry = 21.5)
  // Clip or construct strictly inside the crema ellipse
  let cremaEllipse = ellipsePts(600, 912, 91.5, 21.2, 64);

  // Deep roasted espresso base
  polyWash(cremaEllipse, "#171412", 245);
  polyFill( ellipsePts(596, 912, 86, 19.5, 56), "#2e2825", 175, 0.08, 0.35 );
  polyFill( ellipsePts(592, 912, 74, 16.5, 56), "#4a423d", 130, 0.1, 0.4 );

  // Helper to project polar coordinates (r in 0..1, ang in deg) onto the crema ellipse
  let cremaPt = (r, ang) => [
    600 + cos(ang) * 89 * r,
    912 + sin(ang) * 20.2 * r
  ];

  // Concentric & swirling convection bands (Tiger-Stripe Mottling!)
  // Real tiger striping consists of dark roasted espresso flecks & ribbons alternating with velvety silver-tan foam
  let stripeRings = 26;
  for (let s = 0; s < stripeRings; s++) {
    let rBase = map(s, 0, stripeRings - 1, 0.94, 0.12);
    let aStart = random(0, 360);
    let aSpan = random(55, 145);
    let swirl = (1 - rBase) * 65;

    let bandSpine = [];
    let steps = 16;
    for (let k = 0; k <= steps; k++) {
      let f = k / steps;
      let a = aStart + f * aSpan + sin(f * 180) * 12;
      let r = rBase - f * 0.14 * (1 - rBase * 0.4) + (noise(s * 2.1, f * 3) - 0.5) * 0.06;
      bandSpine.push(cremaPt(constrain(r, 0.04, 0.95), a + swirl * f));
    }

    // Alternate between bright velvety crema foam ribbons and dark tiger-stripe roasted ribbons
    let isDarkStripe = s % 2 === 0;
    let w = map(rBase, 0.1, 0.95, 1.4, 3.2);
    let poly = buildRibbonPolygon(
      bandSpine,
      (t) => -w * sin(t * 180),
      (t) => w * sin(t * 180)
    );

    if (isDarkStripe) {
      let col = random() < 0.5 ? "#0d0b0a" : "#211c19";
      polyWash(poly, col, 210);
      brush.set("HB", "#090807", 0.55);
      brush.spline(bandSpine.map((p) => [p[0], p[1], 0.8]), 0.5);
    } else {
      let col = random() < 0.45 ? "#b5aca4" : (random() < 0.5 ? "#8c837b" : "#d4ccc5");
      polyWash(poly, col, 185);
      brush.set("2H", "#dfd8d0", 0.45);
      brush.spline(bandSpine.map((p) => [p[0], p[1], 0.75]), 0.5);
    }
  }

  // Fine radial & spiral tiger-stripe flecks drawn with cpencil and needle
  for (let i = 0; i < 85; i++) {
    let r0 = random(0.08, 0.92);
    let r1 = constrain(r0 - random(0.06, 0.22), 0.03, 0.92);
    let a0 = random(360);
    let a1 = a0 + random(18, 48);
    let p0 = cremaPt(r0, a0);
    let pMid = cremaPt((r0 + r1) * 0.5, (a0 + a1) * 0.5 + 8);
    let p1 = cremaPt(r1, a1);

    let isDark = random() < 0.52;
    if (isDark) {
      brush.set("needle", random() < 0.5 ? "#090807" : "#241f1c", random(0.45, 0.85));
    } else {
      brush.set("cpencil", random() < 0.4 ? "#e2dbd4" : "#9e958d", random(0.35, 0.65));
    }
    brush.spline([[p0[0], p0[1], 0.4], [pMid[0], pMid[1], 0.95], [p1[0], p1[1], 0.3]], 0.5);
  }

  // 4. Glossy Meniscus Bubble Ring & Pinpoint Specular Highlights where Crema meets Porcelain
  // Left & back-right meniscus catches tiny brilliant white micro-bubble highlights
  for (let i = 0; i < 68; i++) {
    let ang = random(360);
    let r = random(0.89, 0.985);
    let pt = cremaPt(r, ang);
    let isSpec = (ang > 140 && ang < 250) || (ang > 305 || ang < 35) || random() < 0.25;
    if (isSpec) {
      brush.set("rotring", "#ffffff", random(0.45, 0.95));
      brush.line(pt[0], pt[1], pt[0] + random(1.2, 3.2), pt[1] + random(-0.4, 0.4));
    } else {
      brush.set("needle", "#0b0908", random(0.5, 0.85));
      brush.line(pt[0], pt[1], pt[0] + random(1.5, 3.5), pt[1]);
    }
  }

  // Continuous razor-sharp meniscus liquid highlight arc along the back-left & front-right inner wall
  let meniscusHighlight1 = ellipsePts(600, 912, 91, 21, 32, 165, 255).map((p) => [p[0], p[1], 0.9]);
  brush.set("rotring", "#ffffff", 0.75);
  brush.spline(meniscusHighlight1, 0.5);

  let meniscusHighlight2 = ellipsePts(600, 912, 91, 21, 32, 15, 110).map((p) => [p[0], p[1], 0.85]);
  brush.set("needle", "#f2f6fa", 0.7);
  brush.spline(meniscusHighlight2, 0.5);

  // 5. Final Porcelain Rim Specular Highlights (Front lip & Back lip)
  let frontRimSpec = ellipsePts(600, 905, 99, 24.8, 44, 20, 165).map((p) => [p[0], p[1], 1.0]);
  brush.set("rotring", "#ffffff", 1.05);
  brush.spline(frontRimSpec, 0.5);

  let backRimSpec = ellipsePts(600, 905, 102, 25.8, 44, 190, 345).map((p) => [p[0], p[1], 0.9]);
  brush.set("needle", "#ffffff", 0.9);
  brush.spline(backRimSpec, 0.5);

  // Crisp inner front lip shadow line separating crema from front rim
  let innerFrontLip = ellipsePts(600, 905, 94, 23.2, 40, 15, 165).map((p) => [p[0], p[1], 0.85]);
  brush.set("needle", "#2b2e33", 0.75);
  brush.spline(innerFrontLip, 0.5);

  // 6. Subtle Schlieren Vapor Veil emerging directly across the front rim from the hot crema
  let emergingMistLeft = [
    [522, 914], [528, 892], [538, 868], [546, 842]
  ];
  drawSchlierenPlumeRibbon(emergingMistLeft, 14, 10, 0.52, false);

  let emergingMistRight = [
    [676, 914], [668, 892], [658, 868], [650, 842]
  ];
  drawSchlierenPlumeRibbon(emergingMistRight, 10, 14, 0.52, false);
}

