function draw() {
  translate(-width / 2, -height / 2);

  // 1. Stark mid-grey optical background and table plane
  drawOpticalBackground();

  // 2. Towering schlieren thermal plume (diffuse dipole envelope, curl streamlines, Kelvin-Helmholtz vortices & knife-edges)
  drawSchlierenPlume();

