// ============================================================================
// UTILITY & MATH HELPERS
// ============================================================================

function useStroke(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function useWash(col, opacity = 120) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
}

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

function dot3(a, b) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function lerpNum(a, b, t) {
  return a + (b - a) * t;
}

function hexToRgb(hex) {
  let h = hex.replace("#", "");
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  let num = parseInt(h, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  const c = (n) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
  return "#" + c(r) + c(g) + c(b);
}

function mixHex(c1, c2, t) {
  t = clamp01(t);
  let a = hexToRgb(c1);
  let b = hexToRgb(c2);
  return rgbToHex(
    lerpNum(a[0], b[0], t),
    lerpNum(a[1], b[1], t),
    lerpNum(a[2], b[2], t)
  );
}

function mixRamp(stops, t) {
  t = clamp01(t);
  let scaled = t * (stops.length - 1);
  let idx = Math.min(stops.length - 2, Math.floor(scaled));
  let frac = scaled - idx;
  return mixHex(stops[idx], stops[idx + 1], frac);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let filtered = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = filtered[filtered.length - 1];
    if ( Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 1.5 ) {
      filtered.push(pts[i]);
    }
  }
  if (filtered.length === 2) {
    brush.line(filtered[0][0], filtered[0][1], filtered[1][0], filtered[1][1]);
  } else if (filtered.length >= 3) {
    brush.spline(filtered, curvature);
  }
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let s = clamp01(t) * n;
  let i = Math.min(n - 1, Math.floor(s));
  let u = s - i;

  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];

  let u2 = u * u;
  let u3 = u2 * u;

  const interp = (idx) =>
    0.5 * (
      (2 * p1[idx]) +
      (-p0[idx] + p2[idx]) * u +
      (2 * p0[idx] - 5 * p1[idx] + 4 * p2[idx] - p3[idx]) * u2 +
      (-p0[idx] + 3 * p1[idx] - 3 * p2[idx] + p3[idx]) * u3
    );

  return {
    x: interp(0),
    y: interp(1),
    r: p1[2] !== undefined ? interp(2) : 10
  };
}

function sampleSpine(controlPts, steps = 40) {
  let samples = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = evalCatmullRom(controlPts, t);
    samples.push({ x: p.x, y: p.y, r: p.r, t: t });
  }
  for (let i = 0; i < samples.length; i++) {
    let prev = samples[Math.max(0, i - 1)];
    let next = samples[Math.min(samples.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = Math.hypot(dx, dy) || 1;
    samples[i].tx = dx / len;
    samples[i].ty = dy / len;
    // Normal pointing toward left/upper side of stroke
    samples[i].nx = dy / len;
    samples[i].ny = -dx / len;
    if (samples[i].nx > 0 && Math.abs(samples[i].tx) < 0.85) {
      samples[i].nx = -samples[i].nx;
      samples[i].ny = -samples[i].ny;
    }
  }
  return samples;
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-6) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function drawWashPoly(pts, col, opacity) {
  useWash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// 1. STUDIO BACKDROP & RAKING LIGHT VOID
// ============================================================================

function drawStudioBackdrop() {
  // Subtle raking studio light cone entering from left-middle across the dark backdrop
  const glowLayers = [
    { x: 120, y: 630, rx: 680, ry: 420, col: "#141815", op: 75 },
    { x: 90,  y: 650, rx: 520, ry: 330, col: "#1b201b", op: 65 },
    { x: 60,  y: 670, rx: 380, ry: 250, col: "#222720", op: 55 },
    { x: 30,  y: 690, rx: 240, ry: 170, col: "#292f25", op: 45 }
  ];

  for (let g of glowLayers) {
    let pts = [];
    for (let a = 0; a < 360; a += 18) {
      let rad = 1 + 0.08 * (noise(a * 0.1, g.rx * 0.01) - 0.5);
      pts.push([
        g.x + cos(a) * g.rx * rad,
        g.y + sin(a) * g.ry * rad
      ]);
    }
    drawWashPoly(pts, g.col, g.op);
  }

  // Studio table plane below y ~ 780
  drawWashPoly([
    [0, 775], [520, 765], [1200, 795], [1200, 1200], [0, 1200]
  ], "#0d100f", 160);

  // Left-lit table surface glow just before the slate slab
  drawWashPoly([
    [0, 785], [360, 785], [320, 960], [0, 950]
  ], "#202521", 85);

  // Fine atmospheric colored-pencil grain across the negative space
  const bgTones = ["#070908", "#0d100f", "#141815", "#1c211c", "#232821"];
  for (let i = 0; i < 380; i++) {
    let y = random(0, 1200);
    let x = random(0, 1200);
    // Raking light factor stronger on left middle
    let dLeft = Math.hypot((x - 100) / 650, (y - 660) / 420);
    let lightFactor = clamp01(1 - dLeft * 0.85);
    if (y > 785 && x > 650) lightFactor *= 0.25; // shadowed right tabletop

    let col = mixRamp(bgTones, lightFactor * random(0.6, 1.0));
    let len = random(65, 190);
    let ang = y < 780 ? random(-8, 6) : random(-2, 2);

    useStroke("chalk_burnish", col, random(0.6, 1.4));
    brush.line(
      x - cos(ang) * len * 0.5,
      y - sin(ang) * len * 0.5,
      x + cos(ang) * len * 0.5,
      y + sin(ang) * len * 0.5
    );
  }
}

