  // Helper to check if a point on the slate lies inside the bonsai's raking cast shadow
  const inBonsaiCastShadow = (x, y) => {
    // Trunk shadow strip extending rightwards from (465, 858)
    let trunkShad = (x > 462 && x < 915 &&
      Math.abs(y - (856 + (x - 465) * 0.035)) < lerpNum(24, 48, (x - 465) / 450));
    // Canopy shadow lobes on the right half of the slate
    let padShad1 = Math.hypot((x - 675) / 145, (y - 842) / 38) < 1.0;
    let padShad2 = Math.hypot((x - 815) / 120, (y - 855) / 34) < 1.0;
    let padShad3 = Math.hypot((x - 565) / 95,  (y - 825) / 28) < 1.0;
    return trunkShad || padShad1 || padShad2 || padShad3;
  };

  const slateShadowRamp = ["#090c0e", "#101518", "#181f23", "#222a2f", "#2f383d"];
  const slateEarthRamp  = ["#22201d", "#302d28", "#423e37", "#545047"];
  const slateChalkRamp  = ["#364045", "#4c575d", "#667379", "#839096", "#a2aeb3", "#c0cacd"];

  // 1,350 burnished colored-pencil strokes across the slate top
  for (let i = 0; i < 1350; i++) {
    let x = random(142, 928);
    let y = random(782, 922);
    if (!pointInPoly(x, y, slateTop)) continue;

    let nVal = noise(x * 0.012, y * 0.035);
    let nFine = noise(x * 0.06, y * 0.06);
    let raking = clamp01(1.08 - (x - 140) / 760);
    let shadowed = inBonsaiCastShadow(x, y);

    let col, brushName, weight, len;
    let ang = random(-5, 7) + (nVal - 0.5) * 10;

    if (shadowed) {
      // Deep cool-umber cast shadow of the bonsai on the slate
      let t = clamp01(nVal * 0.65 + (1 - raking) * 0.25);
      col = random() < 0.3
        ? mixRamp(slateEarthRamp, t * 0.55)
        : mixRamp(slateShadowRamp, t * 0.75);
      brushName = random() < 0.5 ? "cpencil" : "2B";
      weight = random(0.45, 0.95);
      len = random(14, 38);
    } else {
      // Lit slate with chalky colored-pencil bloom & muted earth undertones
      let bloom = clamp01(raking * 0.75 + nVal * 0.35 + (nFine - 0.5) * 0.2);
      if (random() < 0.22) {
        // Warm earth-mineral grain in the slate
        col = mixRamp(slateEarthRamp, clamp01(bloom * 0.9));
      } else {
        col = mixRamp(slateChalkRamp, bloom);
      }
      brushName = random() < 0.68 ? "cpencil" : (random() < 0.5 ? "chalk_burnish" : "2H");
      weight = brushName === "chalk_burnish" ? random(0.35, 0.75) : random(0.35, 0.85);
      len = random(12, 34);
    }

    let x1 = x - cos(ang) * len * 0.5;
    let y1 = y - sin(ang) * len * 0.5;
    let x2 = x + cos(ang) * len * 0.5;
    let y2 = y + sin(ang) * len * 0.5;

    if (pointInPoly(x1, y1, slateTop) && pointInPoly(x2, y2, slateTop)) {
      useStroke(brushName, col, weight);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Concentrated chalky bloom stipple & micro-scumbling on the left-lit slate plane
  for (let i = 0; i < 420; i++) {
    let x = random(155, 560);
    let y = random(790, 912);
    if (!pointInPoly(x, y, slateTop) || inBonsaiCastShadow(x, y)) continue;

    let raking = clamp01(1.0 - (x - 155) / 420);
    if (random() > raking * 0.9 + 0.15) continue;

    let col = mixRamp(["#6d7a80", "#8c999f", "#adb8bd", "#cad3d6"], raking * random(0.5, 1.0));
    useStroke("cpencil", col, random(0.28, 0.58));
    let ang = random(-12, 12);
    let l = random(4, 13);
    brush.line(x, y, x + cos(ang) * l, y + sin(ang) * l);
  }

  // Geological cleavage fissures and stepped ridges across the slate top
  const fissures = [
    [[182, 844], [265, 824], [362, 814], [448, 810]],
    [[235, 882], [345, 868], [452, 862], [545, 865]],
    [[510, 804], [618, 812], [728, 826], [835, 838]],
    [[565, 892], [685, 882], [790, 868], [875, 854]],
    [[310, 836], [395, 832], [462, 840]]
  ];

  for (let fis of fissures) {
    // Dark cleavage crevice
    useStroke("2B", "#0b0e10", 0.55);
    safeSpline(fis, 0.35);
    // Chalky raking highlight on the upper-left lip of the cleavage step
    let litLip = fis.map(p => [p[0] - 1.2, p[1] - 1.6]);
    let avgX = fis[0][0];
    let lipCol = avgX < 480 ? "#9aa6ab" : "#495459";
    useStroke("2H", lipCol, 0.42);
    safeSpline(litLip, 0.35);
  }

  // 2E. Chiseled front vertical rock wall of the slate slab
  // Front wall consists of 6 major fractured rock facets from left (x=138) to right (x=932)
  const frontTop = [
    [138, 845],
    [156, 876],
    [262, 904],
    [432, 922],
    [545, 915],
    [735, 902],
    [888, 875],
    [932, 838]
  ];
  const frontBot = [
    [144, 886],
    [164, 918],
    [260, 948],
    [430, 968],
    [546, 960],
    [738, 944],
    [892, 914],
    [936, 872]
  ];

  for (let f = 0; f < frontTop.length - 1; f++) {
    let pTL = frontTop[f];
    let pTR = frontTop[f + 1];
    let pBR = frontBot[f + 1];
    let pBL = frontBot[f];
    let facetPoly = [pTL, pTR, pBR, pBL];

    // Calculate facet orientation relative to left raking light
    let dx = pTR[0] - pTL[0];
    let dy = pTR[1] - pTL[1];
    let len = Math.hypot(dx, dy) || 1;
    // Outward normal of front face in 3D:
    let fnx = -dy / len;
    let fny = dx / len;
    let facetLight = clamp01(fnx * (-0.85) + fny * 0.25 + 0.35 - (pTL[0] - 140) / 1400);

    let baseCol = mixRamp(["#07090b", "#0f1316", "#1b2226", "#2d363b", "#465258"], facetLight);
    drawWashPoly(facetPoly, baseCol, 240);

    // Horizontal slate strata & vertical cleavage markings inside each rock facet
    let stepsH = 18;
    for (let s = 0; s < stepsH; s++) {
      let v = (s + 0.5) / stepsH;
      let lx = lerpNum(pTL[0], pBL[0], v);
      let ly = lerpNum(pTL[1], pBL[1], v);
      let rx = lerpNum(pTR[0], pBR[0], v);
      let ry = lerpNum(pTR[1], pBR[1], v);

      // Step out/in for rough cleaved rock texture
      let strataNoise = noise(f * 3.1, s * 0.45);
      let isBrightStrata = strataNoise > 0.58;
      let sCol = isBrightStrata
        ? mixRamp(["#161c20", "#293237", "#48545a", "#6e7b82", "#97a3a8"], facetLight)
        : mixRamp(["#050708", "#0b0e10", "#14191c", "#21282c"], facetLight);

      useStroke("cpencil", sCol, random(0.35, 0.75));
      // Draw fractured segments along the stratum
      let segs = 4;
      for (let k = 0; k < segs; k++) {
        let u0 = k / segs;
        let u1 = (k + 0.88) / segs;
        let x0 = lerpNum(lx, rx, u0);
        let y0 = lerpNum(ly, ry, u0) + (noise(x0 * 0.05, s) - 0.5) * 3.5;
        let x1 = lerpNum(lx, rx, u1);
        let y1 = lerpNum(ly, ry, u1) + (noise(x1 * 0.05, s) - 0.5) * 3.5;
        brush.line(x0, y0, x1, y1);
      }
    }

    // Vertical cleavage cracks along the rock face
    let numCracks = Math.floor(len / 14);
    for (let c = 0; c < numCracks; c++) {
      let u = random(0.05, 0.95);
      let v0 = random(0.0, 0.4);
      let v1 = v0 + random(0.25, 0.6);
      let tx = lerpNum(pTL[0], pTR[0], u);
      let ty = lerpNum(pTL[1], pTR[1], u);
      let bx = lerpNum(pBL[0], pBR[0], u);
      let by = lerpNum(pBL[1], pBR[1], u);

      let cx0 = lerpNum(tx, bx, v0);
      let cy0 = lerpNum(ty, by, v0);
      let cx1 = lerpNum(tx, bx, v1) + random(-3, 3);
      let cy1 = lerpNum(ty, by, v1);

      useStroke("2B", "#060809", random(0.35, 0.65));
      brush.line(cx0, cy0, cx1, cy1);
      if (facetLight > 0.35) {
        useStroke("2H", mixHex("#5a666c", "#9ba7ac", facetLight), 0.32);
        brush.line(cx0 - 1.2, cy0, cx1 - 1.2, cy1);
      }
    }

    // Sharp top arris (chiseled rim where top surface meets front wall)
    let rimCol = facetLight > 0.38
      ? mixRamp(["#5d696f", "#88949a", "#b4bfc4", "#d5dfe2"], facetLight)
      : mixRamp(["#222a2e", "#364045", "#4f5b61"], facetLight * 2.2);

    useStroke("cpencil", rimCol, random(0.55, 0.9));
    let rimPts = [];
    for (let k = 0; k <= 8; k++) {
      let u = k / 8;
      rimPts.push([
        lerpNum(pTL[0], pTR[0], u),
        lerpNum(pTL[1], pTR[1], u) + (noise(f * 5 + k * 0.7) - 0.5) * 2.8
      ]);
    }
    safeSpline(rimPts, 0.3);
  }
}

