function createCloudPad(cfg) {
  const { id, cx, cy, rx, ry, macroLightBias, stemTips, seed } = cfg;
  let lobes = [];

  // Build 3 tiers of corymb domes (Back/Upper, Mid-Body, Front/Pruned-Underside)
  // so the cloud pad has billowy cumulus broccoli domes on top and a flat-pruned bonsai base
  const tierDefs = [
    // Upper/Back dome crown
    { count: 6, uRange: [-0.72, 0.72], yOff: -0.42, rScale: [0.26, 0.34], z: -0.25 },
    // Middle full-width tier
    { count: 8, uRange: [-0.94, 0.94], yOff: -0.06, rScale: [0.25, 0.33], z: 0.15 },
    // Lower pruned horizon tier (flat-bottomed bonsai pad look)
    { count: 7, uRange: [-0.84, 0.84], yOff: 0.28,  rScale: [0.22, 0.29], z: 0.45 }
  ];

  let lobeIdx = 0;
  for (let t = 0; t < tierDefs.length; t++) {
    let td = tierDefs[t];
    for (let i = 0; i < td.count; i++) {
      let frac = td.count === 1 ? 0.5 : i / (td.count - 1);
      let u = lerpNum(td.uRange[0], td.uRange[1], frac);
      let jitterX = (noise(seed + lobeIdx * 1.7, 1.3) - 0.5) * rx * 0.16;
      let jitterY = (noise(seed + lobeIdx * 2.3, 4.7) - 0.5) * ry * 0.18;

      // Dome arch curve: higher in center, tapering at horizontal tips
      let archY = (1 - u * u * 0.85) * (-ry * 0.28) + td.yOff * ry;
      // Flatten the bottom tier so it looks pruned into a horizontal cloud pad
      if (t === 2) {
        archY = ry * 0.22 + Math.abs(u) * ry * 0.06 + jitterY * 0.35;
      }

      let lx = cx + u * rx + jitterX;
      let ly = cy + archY + jitterY * (t === 2 ? 0.3 : 1.0);
      let lr = rx * lerpNum(td.rScale[0], td.rScale[1], noise(seed + lobeIdx * 3.1)) *
               (1 - Math.abs(u) * 0.22);

      // 3D macro normal of this lobe on the cloud pad
      let mnx = clamp01((lx - (cx - rx)) / (2 * rx)) * 2 - 1;
      let mny = (ly - cy) / (ry * 1.2);
      let mnz = td.z + (1 - Math.hypot(mnx * 0.7, mny * 0.7)) * 0.55;
      let mNorm = normalize3([mnx * 0.85, mny * 0.65, Math.max(0.2, mnz)]);

      lobes.push({
        lx, ly, lr,
        squashY: t === 2 ? 0.72 : 0.84,
        tier: t,
        u,
        mNorm,
        seed: seed + lobeIdx * 19
      });
      lobeIdx++;
    }
  }

  return {
    id, cx, cy, rx, ry,
    macroLightBias,
    stemTips,
    lobes
  };
}

// ============================================================================
// 4. CELERY-WHITE TRUNK & FIBROUS STRIATIONS
// ============================================================================

function drawBranchSystem(branchList) {
  // Palette ramps for the broccoli stalk:
  // Base trunk: pale celery-white -> muted sage-earth -> deep olive-jade
  const celeryLitRamp   = ["#6e8258", "#96ab79", "#bccb9c", "#dce5c4", "#eef3de", "#f8faee"];
  const celeryMidRamp   = ["#2c402c", "#42593d", "#5c7550", "#789164", "#96ad7b", "#b5c798"];
  const celeryShadRamp  = ["#0d1712", "#16261e", "#21382d", "#2f4d3e", "#416350"];
  // Upper twigs/peduncles: bluish-jade -> chartreuse-green
  const peduncleLitRamp = ["#3b5e4b", "#58805c", "#7ba167", "#a1c26f", "#c2dd82", "#dceda2"];
  const peduncleShadRamp= ["#0a1411", "#132621", "#1e3b33", "#2b5246", "#3d6b59"];

  for (let br of branchList) {
    let spine = sampleSpine(br.pts, 46);

    // 4A. Under-painting base washes along the limb
    let leftOutline = [];
    let rightOutline = [];
    let midLine = [];
    for (let s of spine) {
      leftOutline.push([s.x + s.nx * s.r, s.y + s.ny * s.r]);
      rightOutline.push([s.x - s.nx * s.r, s.y - s.ny * s.r]);
      midLine.push([s.x + s.nx * s.r * 0.15, s.y + s.ny * s.r * 0.15]);
    }

    // Full limb silhouette wash in mid-dark sage/jade
    let fullPoly = leftOutline.concat(rightOutline.slice().reverse());
    let avgGreen = (br.baseGreen + br.endGreen) * 0.5;
    let baseWashCol = mixHex("#394934", "#284539", avgGreen);
    drawWashPoly(fullPoly, baseWashCol, 225);

    // Lit left half wash in warm celery-cream / chartreuse
    let litPoly = leftOutline.concat(midLine.slice().reverse());
    let litWashCol = mixHex("#c9d4ad", "#8dad65", avgGreen);
    drawWashPoly(litPoly, litWashCol, 175);

    // Shadowed right half wash in deep bluish-jade / earth-olive
    let shadPoly = midLine.concat(rightOutline.slice().reverse());
    let shadWashCol = mixHex("#1c291d", "#132923", avgGreen);
    drawWashPoly(shadPoly, shadWashCol, 195);

    // 4B. Longitudinal fibrous striations twisting along the 3D stalk
    let avgR = (br.pts[0][2] + br.pts[br.pts.length - 1][2]) * 0.5;
    let numFibers = Math.max(18, Math.round(avgR * 2.4));

    for (let f = 0; f < numFibers; f++) {
      let vBase = -0.96 + (f / (numFibers - 1)) * 1.92;
      // Break each longitudinal fiber into 3 overlapping segments for color transition along length
      let segCount = 3;
      for (let seg = 0; seg < segCount; seg++) {
        let idxStart = Math.floor((seg / segCount) * (spine.length - 1));
        let idxEnd = Math.min(spine.length - 1, Math.ceil(((seg + 1.18) / segCount) * (spine.length - 1)));

        let fiberPts = [];
        let lightAccum = 0;
        let greenAccum = 0;
        let vMid = 0;
        let count = 0;

        for (let i = idxStart; i <= idxEnd; i++) {
          let s = spine[i];
          // Bonsai torque: fibers twist gently across the cylinder radius
          let twistOffset = (s.t - 0.5) * br.twistRate * 0.28;
          let v = vBase + twistOffset + (noise(f * 0.7, s.t * 3.5) - 0.5) * 0.08;
          if (v < -0.98 || v > 0.98) continue;

          // Project v onto cylinder cross-section with fluted longitudinal broccoli ribs
          let ribFreq = 7.0;
          let ribWave = Math.sin(v * Math.PI * ribFreq + f * 0.4);
          let zCyl = Math.sqrt(Math.max(0.02, 1 - v * v));

          // 3D normal of stalk surface including longitudinal rib perturbation
          let snx = s.nx * (-v) + ribWave * 0.22 * s.nx;
          let sny = s.ny * (-v) + ribWave * 0.22 * s.ny;
          let snz = zCyl;
          let sNorm = normalize3([snx, sny, snz]);

          // Direct raking light from left + subtle slate bounce light on right edge
          let directL = clamp01(dot3(sNorm, LIGHT_DIR));
          // Under-canopy ambient occlusion near top of sub-stems (s.t -> 1)
          let canopyAO = br.endGreen > 0.8 ? lerpNum(1.0, 0.35, Math.pow(s.t, 2.2)) : 1.0;
          let localLight = directL * canopyAO;

          let px = s.x - s.nx * (v * s.r * 0.94);
          let py = s.y - s.ny * (v * s.r * 0.94);

          fiberPts.push([px, py, 0.7 + ribWave * 0.25]);
          lightAccum += localLight;
          greenAccum += lerpNum(br.baseGreen, br.endGreen, s.t);
          vMid += v;
          count++;
        }

        if (fiberPts.length < 3) continue;

        let meanLight = lightAccum / count;
        let meanGreen = greenAccum / count;
        vMid /= count;

        // Determine color from celery-white (lower lit) -> chartreuse -> bluish-jade (shadow)
        let stalkCol;
        if (meanLight > 0.52) {
          let t = clamp01((meanLight - 0.52) / 0.48);
          let cStalk = mixRamp(celeryLitRamp, t);
          let cPed   = mixRamp(peduncleLitRamp, t);
          stalkCol   = mixHex(cStalk, cPed, meanGreen * 0.85);
        } else if (meanLight > 0.22) {
          let t = clamp01((meanLight - 0.22) / 0.30);
          let cStalk = mixRamp(celeryMidRamp, t);
          let cPed   = mixRamp(peduncleLitRamp, t * 0.65);
          stalkCol   = mixHex(cStalk, cPed, meanGreen * 0.85);
        } else {
          let t = clamp01(meanLight / 0.22);
          let cStalk = mixRamp(celeryShadRamp, t);
          let cPed   = mixRamp(peduncleShadRamp, t);
          stalkCol   = mixHex(cStalk, cPed, meanGreen);
          // Subtle warm-earth reflected light from the slate on the extreme right rim
          if (vMid > 0.72) {
            stalkCol = mixHex(stalkCol, "#46523c", (vMid - 0.72) * 1.6 * (1 - meanGreen * 0.5));
          }
        }

        // Slight organic fiber tint variation
        if (f % 4 === 0) {
          stalkCol = mixHex(stalkCol, "#1c3026", 0.18); // recessed vascular groove
        } else if (f % 4 === 2 && meanLight > 0.45) {
          stalkCol = mixHex(stalkCol, "#f4f7e8", 0.25); // raised waxy ridge
        }

        let bType = (f % 3 === 0) ? "fiber_needle" : (meanLight > 0.5 ? "2H" : "cpencil");
        let bWeight = bType === "fiber_needle" ? random(0.45, 0.8) : random(0.32, 0.62);

        useStroke(bType, stalkCol, bWeight);
        safeSpline(fiberPts, 0.45);
      }
    }

    // 4C. Fine raking highlight fibers along the left-most sun-kissed contour
    if (br.baseGreen < 0.65) {
      for (let h = 0; h < 6; h++) {
        let v = -0.88 + h * 0.08;
        let hiPts = [];
        for (let i = 2; i < spine.length - 4; i += 2) {
          let s = spine[i];
          if (s.nx > -0.15) continue; // only left-facing edges
          let px = s.x - s.nx * (v * s.r * 0.92);
          let py = s.y - s.ny * (v * s.r * 0.92);
          hiPts.push([px, py]);
        }
        if (hiPts.length >= 3) {
          let hiCol = h < 3 ? "#f6f9eb" : "#e2ead0";
          useStroke("2H", hiCol, 0.38);
          safeSpline(hiPts, 0.4);
        }
      }
    }
  }
}

function drawTrunkScarsAndNebari(bonsai) {
  // 1. Nebari (flared cut stalk base resting on the black slate at (466, 858))
  const bx = 466, by = 858;

  // Tight dark ambient occlusion shadow under the cut base on the slate
  drawWashPoly([
    [bx - 48, by + 2], [bx + 54, by - 4],
    [bx + 68, by + 12], [bx - 12, by + 18], [bx - 46, by + 10]
  ], "#050707", 230);

  // Subtle celery reflection on the chalky slate just below the lit left base
  for (let i = 0; i < 28; i++) {
    let rx = bx - 44 + random(0, 48);
    let ry = by + 8 + random(0, 14);
    useStroke("cpencil", mixHex("#5a695c", "#7c8c78", random()), 0.35);
    brush.line(rx, ry, rx + random(6, 15), ry + random(-1, 2));
  }

  // Root-like buttress flutes at the base of the broccoli stalk
  const buttresses = [
    { x0: 432, y0: 816, x1: 418, y1: 858, col: "#e9efd6", shad: "#8fa176" },
    { x0: 444, y0: 822, x1: 440, y1: 865, col: "#dce4c4", shad: "#687c54" },
    { x0: 462, y0: 824, x1: 468, y1: 866, col: "#97ab7b", shad: "#3d5237" },
    { x0: 478, y0: 820, x1: 496, y1: 862, col: "#4c6143", shad: "#1c2b1f" },
    { x0: 486, y0: 816, x1: 512, y1: 855, col: "#324532", shad: "#111c15" }
  ];

  for (let b of buttresses) {
    for (let s = -4; s <= 4; s++) {
      let off = s * 1.4;
      let col = s < 0 ? b.col : b.shad;
      useStroke("fiber_needle", col, 0.55);
      safeSpline([
        [b.x0 + off * 0.6, b.y0],
        [(b.x0 + b.x1) * 0.5 + off, (b.y0 + b.y1) * 0.5 + 4],
        [b.x1 + off * 1.3, b.y1]
      ], 0.45);
    }
  }

  // Calloused bottom rim of the cut stalk where it meets the stone
  for (let i = 0; i < 45; i++) {
    let t = i / 44;
    let ang = lerpNum(175, 5, t);
    let rx = bx + cos(ang) * 47;
    let ry = by - 4 + sin(ang) * 11;
    let rimCol = t < 0.45
      ? mixHex("#d6dec0", "#959876", t * 2)
      : mixHex("#5e6349", "#182119", (t - 0.45) * 1.8);
    useStroke("cpencil", rimCol, 0.48);
    brush.line(rx, ry, rx + random(-2, 2), ry - random(4, 9));
  }

  // 2. Pruned Leaf-Petiole Scars / Bonsai Jin Scars along the trunk
  // Real broccoli stalks have elliptical pale-pith scars with oxidised olive-brown rims where lower leaves/florets were pruned
  const scars = [
    { x: 432, y: 766, rx: 9.5, ry: 14.5, rot: -14, lit: 0.90 }, // Lit left bend scar
    { x: 468, y: 794, rx: 11.0, ry: 8.0, rot: 18,  lit: 0.42 }, // Lower front-right scar
    { x: 454, y: 668, rx: 8.5, ry: 11.5, rot: -8,  lit: 0.68 }, // Mid-trunk pruned node
    { x: 514, y: 526, rx: 6.5, ry: 9.0,  rot: 12,  lit: 0.55 }  // Upper trunk node scar
  ];

  for (let sc of scars) {
    let polyOuter = [];
    let polyInner = [];
    for (let a = 0; a < 360; a += 20) {
      let lx = cos(a) * sc.rx;
      let ly = sin(a) * sc.ry;
      let rx = lx * cos(sc.rot) - ly * sin(sc.rot);
      let ry = lx * sin(sc.rot) + ly * cos(sc.rot);
      polyOuter.push([sc.x + rx, sc.y + ry]);
      polyInner.push([sc.x + rx * 0.72, sc.y + ry * 0.72]);
    }

    // Calloused outer rim wash (muted earth-olive)
    let rimCol = mixHex("#2a2e20", "#6e6b4c", sc.lit);
    drawWashPoly(polyOuter, rimCol, 210);

    // Pale spongy pith interior wash
    let pithCol = mixHex("#7c876c", "#e7ecd4", sc.lit);
    drawWashPoly(polyInner, pithCol, 220);

    // Recessed shadow on the left inner edge of the concave scar, bright highlight on right inner edge
    for (let a = 0; a < 360; a += 16) {
      let lx = cos(a) * sc.rx * 0.82;
      let ly = sin(a) * sc.ry * 0.82;
      let rx = sc.x + lx * cos(sc.rot) - ly * sin(sc.rot);
      let ry = sc.y + lx * sin(sc.rot) + ly * cos(sc.rot);

      let isLitEdge = cos(a + sc.rot) > 0; // Right inner wall catches left raking light
      let edgeCol = isLitEdge
        ? mixHex("#9aa685", "#f5f8e9", sc.lit)
        : mixHex("#161d14", "#434732", sc.lit);

      useStroke("cpencil", edgeCol, 0.42);
      brush.line(rx, ry, rx + cos(a + 90) * 2.5, ry + sin(a + 90) * 2.5);
    }

    // Vascular dots inside the pith center
    for (let d = 0; d < 7; d++) {
      let dx = sc.x + random(-sc.rx * 0.4, sc.rx * 0.4);
      let dy = sc.y + random(-sc.ry * 0.4, sc.ry * 0.4);
      useStroke("rotring", mixHex("#454b35", "#8f9676", sc.lit), 0.35);
      brush.line(dx, dy, dx + 1.2, dy + 0.8);
    }
  }
}

// ============================================================================
// 5. COILED COPPER BONSAI WIRE
// ============================================================================

function drawCopperWire(wireCtrlPts) {
  const spine = sampleSpine(wireCtrlPts, 180);
  const turns = 6.35; // 6.35 helical turns from trunk anchor out along the right branch
  const wireRadius = 2.2;

  // Build 3D helical points along the branch spine
  let coilPts = [];
  for (let i = 0; i < spine.length; i++) {
    let s = spine[i];
    let phi = s.t * turns * 360 + 25; // degrees
    let sinP = sin(phi);
    let cosP = cos(phi); // z-depth: +1 is front of branch, -1 is back of branch

    // Radial offset from branch centerline
    let rWrap = s.r * 0.96 + wireRadius * 0.55;
    let wx = s.x - s.nx * (sinP * rWrap);
    let wy = s.y - s.ny * (sinP * rWrap);

    // 3D normal of the wire's own cylindrical cross-section & coil tangent
    let wnx = -s.nx * sinP * 0.7 + s.tx * cosP * 0.3;
    let wny = -s.ny * sinP * 0.7 + s.ty * cosP * 0.3;
    let wnz = cosP;
    let wNorm = normalize3([wnx, wny, wnz]);
    let light = clamp01(dot3(wNorm, LIGHT_DIR));

    coilPts.push({
      x: wx,
      y: wy,
      z: cosP,
      sinP: sinP,
      light: light,
      bx: s.x,
      by: s.y,
      nx: s.nx,
      ny: s.ny,
      r: s.r
    });
  }

  // Group contiguous visible front segments (z >= -0.22 so the wire hooks visibly around the branch contour!)
  let frontSegments = [];
  let currentSeg = [];
  for (let p of coilPts) {
    if (p.z >= -0.22) {
      currentSeg.push(p);
    } else {
      if (currentSeg.length >= 3) frontSegments.push(currentSeg);
      currentSeg = [];
    }
  }
  if (currentSeg.length >= 3) frontSegments.push(currentSeg);

  for (let seg of frontSegments) {
    // 5A. Cast shadow of the copper wire falling rightwards/downwards onto the pale celery stalk
    let shadPts = [];
    for (let p of seg) {
      if (p.z > -0.05) {
        let sx = p.x + 3.4 * (0.5 + p.z * 0.5);
        let sy = p.y + 2.2 * (0.5 + p.z * 0.5);
        shadPts.push([sx, sy]);
      }
    }
    if (shadPts.length >= 3) {
      useStroke("2B", "#172116", 0.72);
      safeSpline(shadPts, 0.45);
      useStroke("cpencil", "#283624", 0.5);
      safeSpline(shadPts.map(pt => [pt[0] - 1.0, pt[1] - 0.8]), 0.45);
    }

    // 5B. Dark oxidised copper underside / edge of the wire strand
    let darkEdgePts = seg.map(p => [p.x + 1.1, p.y + 1.1]);
    useStroke("rotring", "#33160c", 0.68);
    safeSpline(darkEdgePts, 0.45);

    let midDarkPts = seg.map(p => [p.x + 0.5, p.y + 0.5]);
    useStroke("cpencil", "#5e2a16", 0.65);
    safeSpline(midDarkPts, 0.45);

    // 5C. Warm burnished terracotta-copper core of the wire
    let corePts = seg.map(p => [p.x, p.y]);
    useStroke("cpencil", "#9c4e28", 0.62);
    safeSpline(corePts, 0.45);

    let warmPts = seg.map(p => [p.x - 0.45, p.y - 0.45]);
    useStroke("2H", "#c76f42", 0.52);
    safeSpline(warmPts, 0.45);

    // 5D. Specular metallic glint on the left-lit portion of each copper coil turn
    let glintPts = [];
    for (let p of seg) {
      if (p.light > 0.46 && p.z > 0.05) {
        glintPts.push([p.x - 0.85, p.y - 0.85]);
      } else {
        if (glintPts.length >= 3) {
          useStroke("rotring", "#f2bc8d", 0.45);
          safeSpline(glintPts, 0.4);
          useStroke("2H", "#fff1e0", 0.32);
          safeSpline(glintPts.slice(0, Math.max(3, glintPts.length - 1)), 0.4);
        }
        glintPts = [];
      }
    }
    if (glintPts.length >= 3) {
      useStroke("rotring", "#f2bc8d", 0.45);
      safeSpline(glintPts, 0.4);
      useStroke("2H", "#fff1e0", 0.32);
      safeSpline(glintPts, 0.4);
    }
  }
}

// ============================================================================
// 6. PRUNED BROCCOLI CLOUD PADS (GRANULAR SCULPTURAL RELIEF)
// ============================================================================

function drawSingleCloudPad(pad, allPads) {
  // Palette ramps from abyssal blue-jade -> glaucous bluish-jade -> muted olive-sage -> chartreuse -> celery-gold
  const creviceRamp   = ["#050b0a", "#091412", "#0f201c", "#162d28"];
  const blueJadeRamp  = ["#122622", "#1b3630", "#264840", "#355d53", "#487468", "#628e82"];
  const earthJadeRamp = ["#1e2e22", "#2f4431", "#445d42", "#5c7853", "#769466", "#91b07a"];
  const chartrRamp    = ["#527347", "#6f9453", "#90b560", "#b2d171", "#cde48b", "#e6f2b3", "#f6fad6"];

  // 6A. Dark pruned under-canopy shadow shelf where sub-stems enter the flat underside of the pad
  let underPoly = [];
  for (let a = 0; a < 360; a += 18) {
    let ux = pad.cx + cos(a) * pad.rx * 0.92;
    let uy = pad.cy + pad.ry * 0.14 + sin(a) * pad.ry * (sin(a) > 0 ? 0.42 : 0.65);
    underPoly.push([ux, uy]);
  }
  drawWashPoly(underPoly, "#091310", 230);

  // Tiny pale-green sub-pedicels peeking out inside the dark pruned underside of the cloud pad
  for (let tip of pad.stemTips) {
    for (let k = -2; k <= 2; k++) {
      let tx0 = tip[0] + k * 2.2;
      let ty0 = tip[1] + 2;
      let tx1 = tip[0] + k * 8.5 + random(-3, 3);
      let ty1 = tip[1] - random(10, 20);
      let isLitSide = (tx0 < pad.cx);
      let pCol = isLitSide ? mixHex("#6e8758", "#9cb37c", random()) : mixHex("#20362b", "#395443", random());
      useStroke("fiber_needle", pCol, 0.45);
      brush.line(tx0, ty0, tx1, ty1);
    }
  }

  // Sort sub-lobes from back/top to front/bottom
  let sortedLobes = pad.lobes.slice().sort((a, b) => (a.tier - b.tier) || (a.ly - b.ly));

  // Helper to check if a point on this pad is shadowed by another pad to its left
  const interPadOcclusion = (x, y) => {
    let occ = 1.0;
    for (let other of allPads) {
      if (other.id === pad.id || other.cx >= pad.cx) continue;
      // Project raking light ray from other pad toward right-down (+1, +0.28)
      let tRay = (x - other.cx) / 220;
      if (tRay > 0 && tRay < 1.35) {
        let projY = other.cy + tRay * 52;
        let dy = Math.abs(y - projY) / (other.ry * 1.15);
        if (dy < 1.0) {
          occ = Math.min(occ, lerpNum(0.35, 1.0, dy));
        }
      }
    }
    return occ;
  };

  // 6B. Render each sub-lobe's base wash and deep inter-lobe crevices
  for (let lobe of sortedLobes) {
    // Dark crevice ring around the sub-lobe so domes read as distinct sculptural clusters
    let crevPoly = [];
    for (let a = 0; a < 360; a += 24) {
      let rad = lobe.lr * (1.06 + 0.08 * (noise(lobe.seed + a * 0.1) - 0.5));
      crevPoly.push([
        lobe.lx + cos(a) * rad,
        lobe.ly + sin(a) * rad * lobe.squashY
      ]);
    }
    drawWashPoly(crevPoly, "#081210", 185);

    // Tonal base wash of the sub-lobe
    let lobeLight = clamp01(dot3(lobe.mNorm, LIGHT_DIR) + pad.macroLightBias) *
                    interPadOcclusion(lobe.lx, lobe.ly);
    let washCol = lobeLight > 0.48
      ? mixRamp(earthJadeRamp, clamp01((lobeLight - 0.2) * 1.1))
      : mixRamp(blueJadeRamp, clamp01(lobeLight * 1.6));

    let bodyPoly = crevPoly.map(p => [
      lerpNum(lobe.lx, p[0], 0.90),
      lerpNum(lobe.ly, p[1], 0.90)
    ]);
    drawWashPoly(bodyPoly, washCol, 210);

    // Deep crevice hatching in the fissures between sub-lobes
    for (let c = 0; c < 10; c++) {
      let ang = random(180, 360); // upper/side fissure arc
      let cr = lobe.lr * random(0.85, 1.05);
      let cx = lobe.lx + cos(ang) * cr;
      let cy = lobe.ly + sin(ang) * cr * lobe.squashY;
      useStroke("2B", mixRamp(creviceRamp, lobeLight * 0.6), random(0.45, 0.8));
      brush.line(cx, cy, cx + cos(ang + 75) * random(5, 11), cy + sin(ang + 75) * random(4, 9));
    }
  }

  // 6C. Generate & render thousands of individual granular flower buds via Golden-Angle Phyllotaxis!
  const goldenAngle = 137.50776;
  let allBuds = [];

  for (let lobe of sortedLobes) {
    // Number of buds packed into this corymb dome
    let numBuds = Math.round(clamp01(lobe.lr / 34) * 28 + 18);

    for (let i = 0; i < numBuds; i++) {
      let frac = (i + 0.5) / numBuds;
      let rNorm = Math.sqrt(frac);
      let theta = i * goldenAngle + lobe.seed * 11;

      // Local dome coordinates (-1 to 1)
      let dx = cos(theta) * rNorm;
      let dy = sin(theta) * rNorm;

      // Organic botryoidal perturbation
      let jx = (noise(lobe.seed + i * 0.35, 1.1) - 0.5) * 0.18;
      let jy = (noise(lobe.seed + i * 0.35, 5.7) - 0.5) * 0.18;
      dx = Math.max(-0.98, Math.min(0.98, dx + jx));
      dy = Math.max(-0.98, Math.min(0.98, dy + jy));

      let bx = lobe.lx + dx * lobe.lr * 0.96;
      let by = lobe.ly + dy * lobe.lr * lobe.squashY * 0.96;

      // Individual bud radius (3.2 to 6.0 px in canvas units)
      let budR = lerpNum(5.4, 3.3, rNorm * 0.75) * (0.85 + 0.3 * noise(bx * 0.08, by * 0.08));

      // Meso 3D normal on the sub-lobe dome
      let dz = Math.sqrt(Math.max(0.05, 1 - (dx * dx + dy * dy) * 0.88));
      let mesoNorm = normalize3([
        dx * 0.62 + lobe.mNorm[0] * 0.55,
        dy * 0.58 + lobe.mNorm[1] * 0.45,
        dz * 0.75 + lobe.mNorm[2] * 0.35
      ]);

      // Combined illumination at this bud
      let rawLight = dot3(mesoNorm, LIGHT_DIR) + pad.macroLightBias * 0.65;
      let occ = interPadOcclusion(bx, by);
      // Darker under-lip on the bottom pruned edge of the pad
      let bottomShade = (lobe.tier === 2 && dy > 0.35) ? lerpNum(1.0, 0.35, (dy - 0.35) / 0.65) : 1.0;
      let light = clamp01((rawLight * 0.82 + 0.24) * occ * bottomShade);

      // Hue temperature: left/top buds run chartreuse, mid/right buds run bluish-jade with earth undertones
      let jadeShift = clamp01((bx - (pad.cx - pad.rx * 0.8)) / (pad.rx * 1.7) - pad.macroLightBias * 0.5);

      allBuds.push({
        bx, by, budR,
        light,
        jadeShift,
        tier: lobe.tier,
        rNorm,
        seed: lobe.seed + i
      });
    }
  }

  // Sort buds back-to-front by tier and vertical y for crisp sculptural overlap
  allBuds.sort((a, b) => (a.tier - b.tier) || (a.by - b.by));

  // Render every individual broccoli bud in 3 sculptural passes:
  // (1) Deep right/bottom shadow cup, (2) Granular mid-tone bead body, (3) Left raking highlight crescent
  for (let b of allBuds) {
    let r = b.budR;
    let L = b.light;
    let J = b.jadeShift;

    // 1. Shadow cup on the right/bottom side of the bud (creates granular relief!)
    let shadCol = mixHex(
      mixRamp(creviceRamp, L * 0.85),
      mixRamp(blueJadeRamp, L * 0.55),
      0.45
    );
    useStroke("cpencil", shadCol, random(0.38, 0.62));
    brush.arc(b.bx + r * 0.14, b.by + r * 0.1, r * 0.78, -45, 115);

    // 2. Mid-tone granular body of the bud
    let bodyJade = mixRamp(blueJadeRamp, clamp01(L * 1.15));
    let bodyEarth = mixRamp(earthJadeRamp, clamp01(L * 1.1));
    let bodyChartr = mixRamp(chartrRamp, clamp01(L * 0.95));

    let bodyCol;
    if (L > 0.55) {
      bodyCol = mixHex(bodyEarth, bodyChartr, clamp01((L - 0.45) * 1.6) * (1 - J * 0.45));
    } else {
      bodyCol = mixHex(bodyEarth, bodyJade, clamp01(J * 0.85 + 0.15));
    }
    // Slight natural botanical variation per bud
    let budVar = noise(b.seed * 0.73);
    if (budVar > 0.68) {
      bodyCol = mixHex(bodyCol, "#4f6d63", 0.25); // glaucous bluish-wax bud
    } else if (budVar < 0.28) {
      bodyCol = mixHex(bodyCol, "#5c633e", 0.22); // muted olive-earth bud
    }

    useStroke("bud_sculpt", bodyCol, random(0.45, 0.72));
    brush.arc(b.bx, b.by, r * 0.58, 95, 295);

    // 3. Sculptural raking crescent highlight on the left/upper-left face of the bud
    if (L > 0.16) {
      let hiCol;
      if (L > 0.64) {
        // Intense raking light: luminous chartreuse to pale celery-gold
        hiCol = mixRamp(chartrRamp, clamp01((L - 0.35) * 1.35));
      } else if (L > 0.36) {
        // Mid-lit transition: chartreuse-jade mixed with glaucous blue-green
        let cChart = mixRamp(chartrRamp, L * 0.95);
        let cJade  = mixRamp(blueJadeRamp, clamp01(L * 1.35));
        hiCol = mixHex(cChart, cJade, J * 0.65);
      } else {
        // Dimly lit right side: cool dusty bluish-jade rim
        hiCol = mixRamp(blueJadeRamp, clamp01(L * 1.85 + 0.15));
      }

      let hiWeight = L > 0.6 ? random(0.42, 0.68) : random(0.30, 0.50);
      let hiBrush = L > 0.55 ? "cpencil" : "2H";
      useStroke(hiBrush, hiCol, hiWeight);
      brush.arc(b.bx - r * 0.14, b.by - r * 0.1, r * 0.64, 130, 265);

      // Pinpoint specular crown on the most prominent left-facing buds
      if (L > 0.76 && budVar > 0.35) {
        useStroke("2H", "#f6fad8", 0.34);
        brush.line(
          b.bx - r * 0.48, b.by - r * 0.28,
          b.bx - r * 0.22, b.by - r * 0.52
        );
      }
    }
  }
}

