// 3D Parametric Geometry Configuration for the Mug
const MUG = {
  cx: 652,
  topY: 338,
  botY: 912,
  rimR: 263,
  rimTube: 16,
  rimAspect: 0.352,
  bodyTopY: 353,
  bodyTopR: 265,
  bodyBotR: 249,
  aspTop: 0.355,
  aspBot: 0.406
};

// Helper: Plank back edge & joint lines
function plankTopEdgeY(x) {
  return 212 - 0.042 * (x - 600);
}
function plankSeamY(x) {
  return 558 - 0.048 * (x - 600) + 3.5 * sin(x * 0.35);
}

// Helper: Mug cylinder radius at vertical parameter v in [0, 1]
function getBodyRadius(v) {
  let baseR = lerp(MUG.bodyTopR, MUG.bodyBotR, pow(v, 0.92));
  // Subtle flare toward top rim and tucked foot ring near bottom
  let topFlare = v < 0.07 ? 3.5 * pow(1 - v / 0.07, 2) : 0;
  let footTuck = v > 0.93 ? -6.5 * sin(((v - 0.93) / 0.07) * 90) : 0;
  let belly = 3.0 * sin(v * 180);
  return baseR + topFlare + footTuck + belly;
}

function getBodyAspect(v) {
  return lerp(MUG.aspTop, MUG.aspBot, v);
}

// 3D-to-2D projection on mug exterior/interior cylinder
// thetaDeg: 0 = right edge, 90 = front center, 180 = left edge, 270 = back center
function cylPoint(thetaDeg, v, radialOffset = 0) {
  let r = getBodyRadius(v) + radialOffset;
  let asp = getBodyAspect(v);
  let yCenter = lerp(MUG.bodyTopY, MUG.botY, v);
  let x = MUG.cx + r * cos(thetaDeg);
  let y = yCenter + r * asp * sin(thetaDeg);
  return [x, y];
}

// 3D-to-2D projection on rolled rim torus
// thetaDeg: 0..360 around mug opening
// phiDeg: cross-sectional angle (-180 = inner wall, -90 = top lip crest, 0 = outer equator, +75 = under-lip)
function rimPoint(thetaDeg, phiDeg, radialOffset = 0) {
  let rTube = MUG.rimTube + radialOffset;
  let rEff = MUG.rimR + rTube * cos(phiDeg);
  let x = MUG.cx + rEff * cos(thetaDeg);
  let y = MUG.topY + rEff * MUG.rimAspect * sin(thetaDeg) + rTube * sin(phiDeg);
  return [x, y];
}

// Exact front rim crest Y for clipping interior strokes
function frontRimCrestY(x) {
  let rCrest = MUG.rimR + MUG.rimTube * cos(-102);
  let dx = (x - MUG.cx) / rCrest;
  if (abs(dx) >= 1) return MUG.topY;
  let sinTheta = sqrt(max(0, 1 - dx * dx));
  return MUG.topY + rCrest * MUG.rimAspect * sinTheta + MUG.rimTube * sin(-102);
}

// Safe spline helper to prevent duplicate-point artifacts
function safeSpline(pts, curv = 0.3) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let d = dist(prev[0], prev[1], pts[i][0], pts[i][1]);
    if (d > 0.75) clean.push(pts[i]);
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curv);
  }
}

// Cubic bezier evaluator
function bezPt(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

// Handle 3D Ribbon Geometry Parameterization
function handlePoint(t, s = 0.5, thick = 0) {
  // s in [0, 1]: 0 = back strap edge, 1 = front strap edge
  // thick in [0, 1]: 0 = outer surface of loop, 1 = inner surface of loop
  const f0 = [408, 466], f1 = [212, 368], f2 = [155, 706], f3 = [418, 796];
  const b0 = [388, 438], b1 = [190, 340], b2 = [136, 675], b3 = [398, 766];

  const fi0 = [408, 492], fi1 = [245, 405], fi2 = [194, 682], fi3 = [416, 770];
  const bi0 = [388, 464], bi1 = [223, 377], bi2 = [175, 651], bi3 = [396, 740];

  let pfOuter = bezPt(f0, f1, f2, f3, t);
  let pbOuter = bezPt(b0, b1, b2, b3, t);
  let pfInner = bezPt(fi0, fi1, fi2, fi3, t);
  let pbInner = bezPt(bi0, bi1, bi2, bi3, t);

  let pOuter = [lerp(pbOuter[0], pfOuter[0], s), lerp(pbOuter[1], pfOuter[1], s)];
  let pInner = [lerp(pbInner[0], pfInner[0], s), lerp(pbInner[1], pfInner[1], s)];

  return [lerp(pOuter[0], pInner[0], thick), lerp(pOuter[1], pInner[1], thick)];
}

// ============================================================================
// OPTICAL + PYSANKY LIGHT MODEL ON THE ENAMEL MUG
// Returns light value in [0, 1] combining hyperreal cylinder reflections
// with stepped pysanky geometric resist modulation.
// ============================================================================
function getMugLight(theta, v) {
  // 1. Primary left-front window reflection column (centered around theta ~ 126 deg)
  let mainCenter = 127 - v * 3.2;
  let dMain = abs(theta - mainCenter);
  let mainSpec = exp(-pow(dMain / 19.5, 2.1));

  // Window mullion / crossbar division in reflection around v = 0.42
  if (abs(v - 0.425) < 0.018 && dMain < 14) {
    mainSpec *= 0.62 + 0.38 * abs(v - 0.425) / 0.018;
  }

  // 2. Secondary crisp vertical reflection on right side (theta ~ 29 deg)
  let secCenter = 29.5 - v * 1.8;
  let dSec = abs(theta - secCenter);
  let secSpec = 0.88 * exp(-pow(dSec / 8.8, 2.0));

  // 3. Grazing left edge rim bounce light (from handle & environment, theta ~ 174 deg)
  let dLeft = abs(theta - 175.5);
  let leftGrazing = 0.66 * exp(-pow(dLeft / 7.5, 1.8));

  // 4. Warm sunlit plank bounce light reflecting into the lower belly (v > 0.58)
  let plankBounce = 0;
  if (v > 0.55) {
    let vFactor = pow((v - 0.55) / 0.45, 1.35);
    let thetaBounce = exp(-pow((theta - 108) / 48, 2)) * 0.46 + exp(-pow((theta - 45) / 30, 2)) * 0.25;
    plankBounce = vFactor * thetaBounce;
  }

  // 5. Subtle upper shoulder sky reflection near v < 0.14
  let skyShoulder = v < 0.14 ? (1 - v / 0.14) * 0.22 * sin(theta) : 0;

  // 6. Enamel orange-peel micro-waviness
  let ripple = (noise(theta * 0.22, v * 15.0) - 0.5) * 0.055;

  // 7. Pysanky geometric resist modulation (collar band, base band, and chevron tooth steps)
  let pysankyBoost = 0;
  // Upper pysanky collar band: v in [0.065, 0.135]
  if (v > 0.065 && v < 0.135) {
    let uBand = (v - 0.065) / 0.07; // 0..1
    let zig = abs(((theta * 0.25) % 2) - 1); // chevron wave every 8 degrees
    let motif = 1 - abs(uBand - zig);
    if (motif > 0.68) pysankyBoost += 0.16;
    else if (motif > 0.42) pysankyBoost += 0.07;
  }
  // Lower pysanky base band: v in [0.835, 0.90]
  if (v > 0.835 && v < 0.90) {
    let uBand = (v - 0.835) / 0.065;
    let zig = abs(((theta * 0.25 + 0.5) % 2) - 1);
    let motif = 1 - abs(uBand - zig);
    if (motif > 0.68) pysankyBoost += 0.15;
    else if (motif > 0.42) pysankyBoost += 0.06;
  }
  // Serrated kistka teeth along the edges of the main reflection column
  let toothWave = sin(v * 360 * 6.5) * 2.4;
  if (abs(dMain + toothWave - 9.5) < 1.8) pysankyBoost += 0.10;
  if (abs(dMain + toothWave - 18.0) < 2.2) pysankyBoost += 0.09;

  // Foot ring bright bevel right at bottom (v > 0.96)
  let footGlint = v > 0.965 ? 0.28 * exp(-pow((theta - 118) / 38, 2)) : 0;

  let total = max(mainSpec, secSpec, leftGrazing) + plankBounce + skyShoulder + pysankyBoost + footGlint + ripple;
  return constrain(total, 0, 1);
}

