// MAIN RENDER PIPELINE
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);

  // 1. Raw weathered timber plank & dark earthen background
  drawRawPlankEnvironment();

  // 2. Multi-layered cast shadow & warm caustic bounce on the plank
  drawMugCastShadow();

  // 3. Stage 0: Pure ivory-white resist reserve for mug body, rim & handle
  drawMugWhiteReserve();

  // 4. Mug interior well (4 pysanky marker stages + interior speculars)
  drawMugInterior();

  // 5. Back half of rolled rim torus
  drawRolledRimBack();

  // 6. Mug exterior body: Pysanky dye-bath stages (Chrome Yellow -> Marigold -> Madder Red -> Aubergine-Black)
  drawMugBodyStages();

  // 7. Pysanky kistka resist lines, folk-optical facets & razor specular highlights
  drawBodyResistAndSpeculars();

  // 8. Front half of rolled rim torus (with under-lip shadow & blazing crest resist)
  drawRolledRimFront();

  // 9. Left enamel strap handle (3D ribbon in pysanky marker stages + weld flanges)
  drawEnamelHandle();

  // 10. Chipped enamel spots: blue-black steel cores, tiny rust halos & white resist fracture edges
  drawAllEnamelChips();

  // 11. Final foreground wood splinters & atmospheric dust glints
  drawFinalSurfaceIncidents();

  noLoop();
}

// ============================================================================
// 1. RAW PLANK TABLETOP & MUTED EARTH BACKGROUND
// ============================================================================
function drawRawPlankEnvironment() {
  brush.noField();
  brush.noHatch();
  brush.noMass();

  // Upper dark earthen studio wall behind the tabletop edge
  brush.noStroke();
  brush.wash(PAL.wallDeep, 245);
  brush.beginShape(0);
  brush.vertex(0, 0);
  brush.vertex(1200, 0);
  brush.vertex(1200, plankTopEdgeY(1200) + 18);
  brush.vertex(0, plankTopEdgeY(0) + 18);
  brush.endShape(true);

  // Soft watercolor texture in dark upper background
  brush.fill(PAL.wallDark, 140);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.55, 0.3);
  brush.beginShape(0);
  brush.vertex(0, 0);
  brush.vertex(1200, 0);
  brush.vertex(1200, plankTopEdgeY(1200) + 8);
  brush.vertex(0, plankTopEdgeY(0) + 8);
  brush.endShape(true);
  brush.noFill();

  // Back plank base wash (between plankTopEdgeY and plankSeamY)
  brush.wash(PAL.plankMid, 215);
  brush.beginShape(0);
  brush.vertex(0, plankTopEdgeY(0));
  brush.vertex(1200, plankTopEdgeY(1200));
  brush.vertex(1200, plankSeamY(1200));
  brush.vertex(0, plankSeamY(0));
  brush.endShape(true);

  // Front main plank base wash (between plankSeamY and bottom of canvas)
  brush.wash(PAL.plankBuff, 210);
  brush.beginShape(0);
  brush.vertex(0, plankSeamY(0));
  brush.vertex(1200, plankSeamY(1200));
  brush.vertex(1200, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);
  brush.noWash();

  // Broad earthen watercolor variations across planks
  const earthPatches = [
    { x1: 0, y1: 580, x2: 520, y2: 550, x3: 560, y3: 1180, x4: 0, y4: 1200, col: PAL.plankLight, op: 85 },
    { x1: 540, y1: 540, x2: 1200, y2: 510, x3: 1200, y3: 1200, x4: 600, y4: 1200, col: PAL.plankUmber, op: 95 },
    { x1: 0, y1: 230, x2: 1200, y2: 190, x3: 1200, y3: 390, x4: 0, y4: 430, col: PAL.plankDark, op: 110 }
  ];
  for (let p of earthPatches) {
    brush.fill(p.col, p.op);
    brush.fillBleed(0.3, "out");
    brush.fillTexture(0.65, 0.35);
    brush.beginShape(0.1);
    brush.vertex(p.x1, p.y1);
    brush.vertex(p.x2, p.y2);
    brush.vertex(p.x3, p.y3);
    brush.vertex(p.x4, p.y4);
    brush.endShape(true);
  }
  brush.noFill();

  // Alcohol-marker earth under-strokes on plank to unify medium
  for (let i = 0; i < 68; i++) {
    let t = i / 67;
    let yLeft = lerp(plankTopEdgeY(0) + 6, 1195, t);
    let yRight = yLeft - 52 + (noise(i * 0.25) - 0.5) * 18;
    let col = i % 3 === 0 ? PAL.plankUmber : i % 3 === 1 ? PAL.plankBuff : PAL.plankLight;
    brush.set("alc_glaze", col, random(0.8, 1.35));
    let pts = [];
    for (let s = 0; s <= 8; s++) {
      let u = s / 8;
      let x = u * 1200;
      let y = lerp(yLeft, yRight, u) + sin(u * 180 + i * 12) * 4;
      pts.push([x, y]);
    }
    safeSpline(pts, 0.25);
  }

  // Detailed raw wood grain fibers, knots, and cathedral arches
  const knotCenters = [
    { x: 235, y: 895, rx: 68, ry: 22 },
    { x: 1015, y: 745, rx: 82, ry: 25 },
    { x: 310, y: 385, rx: 55, ry: 16 }
  ];

  for (let row = 0; row < 210; row++) {
    let t = row / 209;
    // Perspective spacing: tighter near the back of the table, wider in the foreground
    let vPersp = pow(t, 1.28);
    let yBase = lerp(plankTopEdgeY(600) + 4, 1215, vPersp);

    // Choose earth tone for grain line
    let nVal = noise(row * 0.18, 2.5);
    let grainCol = PAL.plankUmber;
    if (nVal > 0.66) grainCol = PAL.plankDark;
    else if (nVal > 0.52) grainCol = PAL.plankCrevice;
    else if (nVal < 0.32) grainCol = PAL.plankLight;

    let w = lerp(0.55, 1.35, vPersp) * random(0.75, 1.25);
    brush.set("wood_fiber", grainCol, w);

    let pts = [];
    let steps = 22;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let x = u * 1200;
      let slope = -0.045 * (x - 600);
      let wave = (noise(x * 0.004, row * 0.08) - 0.5) * 24;
      let y = yBase + slope + wave;

      // Deflect grain smoothly around wood knots
      for (let k of knotCenters) {
        let dx = (x - k.x) / k.rx;
        let dy = (y - k.y) / k.ry;
        let d2 = dx * dx + dy * dy;
        if (d2 < 3.2) {
          let push = exp(-d2 * 0.85) * k.ry * (dy >= 0 ? 1.15 : -1.15);
          y += push;
        }
      }
      pts.push([x, y]);
    }
    safeSpline(pts, 0.35);

    // Occasional bright dry-wood highlight fiber right beside dark grain
    if (row % 5 === 0) {
      brush.set("2H", PAL.resistCream, lerp(0.4, 0.9, vPersp));
      let hiPts = pts.map((p) => [p[0], p[1] + 2.2]);
      safeSpline(hiPts, 0.35);
    }
  }

  // Draw the wood knots with tight concentric rings and dark core checks
  for (let k of knotCenters) {
    for (let r = 1; r <= 7; r++) {
      let frac = r / 7;
      let col = r <= 3 ? PAL.plankDeep : r <= 5 ? PAL.plankCrevice : PAL.plankDark;
      brush.set("wood_fiber", col, 0.95);
      let kPts = [];
      for (let a = 0; a <= 360; a += 30) {
        let radX = k.rx * frac * (0.85 + 0.2 * noise(a * 0.1, r));
        let radY = k.ry * frac * (0.85 + 0.2 * noise(a * 0.1 + 9, r));
        kPts.push([k.x + radX * cos(a), k.y + radY * sin(a)]);
      }
      safeSpline(kPts, 0.4);
    }
    // Small radial split inside knot
    brush.set("rotring", PAL.shadowCore, 0.8);
    brush.line(k.x - k.rx * 0.35, k.y + 2, k.x + k.rx * 0.38, k.y - 2);
  }

  // Draw the top chamfered edge of the back plank
  let topEdgePts = [];
  let topLipPts = [];
  for (let s = 0; s <= 24; s++) {
    let x = (s / 24) * 1200;
    let y = plankTopEdgeY(x) + (noise(s * 0.4) - 0.5) * 4;
    topEdgePts.push([x, y]);
    topLipPts.push([x, y + 4.5]);
  }
  brush.set("charcoal", PAL.plankDeep, 1.4);
  safeSpline(topEdgePts, 0.25);
  brush.set("wood_fiber", PAL.plankLight, 0.9);
  safeSpline(topLipPts, 0.25);

  // Draw the deep weathered seam between the two planks
  let seamPts = [];
  let seamBevelTop = [];
  let seamBevelBot = [];
  for (let s = 0; s <= 32; s++) {
    let x = (s / 32) * 1200;
    let y = plankSeamY(x) + (noise(s * 0.5, 9) - 0.5) * 3.5;
    seamPts.push([x, y]);
    seamBevelTop.push([x, y - 5.5]);
    seamBevelBot.push([x, y + 5.5]);
  }
  brush.set("alc_flat", PAL.plankDark, 1.1);
  safeSpline(seamBevelTop, 0.25);
  brush.set("alc_fine", PAL.plankDeep, 1.4);
  safeSpline(seamPts, 0.25);
  brush.set("charcoal", PAL.shadowCore, 1.25);
  safeSpline(seamPts, 0.25);
  // Sunlit lower lip of the front plank catching light along the seam
  brush.set("wood_fiber", PAL.plankLight, 1.15);
  safeSpline(seamBevelBot, 0.25);
  brush.set("kistka_hair", PAL.resistCream, 0.75);
  safeSpline(seamBevelBot.slice(0, 14), 0.25);

  // Raw timber checks, weathered splits, and vertical saw-mark ghosts in foreground
  const splits = [
    [[48, 985], [142, 978], [238, 974], [312, 970]],
    [[885, 1075], [990, 1068], [1110, 1060], [1198, 1054]],
    [[118, 668], [196, 665], [268, 661]]
  ];
  for (let sp of splits) {
    brush.set("rotring", PAL.plankDeep, 1.1);
    safeSpline(sp, 0.2);
    brush.set("kistka_hair", PAL.plankLight, 0.75);
    safeSpline(sp.map((p) => [p[0], p[1] + 2.2]), 0.2);
  }

  // Subtle vertical band-saw chatter marks across the raw plank
  for (let sx = 65; sx < 1160; sx += random(22, 48)) {
    let yStart = random(580, 920);
    let yEnd = yStart + random(45, 140);
    brush.set("2B", PAL.plankDark, 0.45);
    brush.line(sx, yStart, sx + random(-3, 3), yEnd);
  }
}

// ============================================================================
// 2. CAST SHADOW & WARM CAUSTIC BOUNCE ON PLANK
// ============================================================================
function drawMugCastShadow() {
  brush.noField();
  brush.noStroke();

  // Soft outer umber cast shadow stretching right-forward
  const shadLayers = [
    { cx: 815, cy: 932, rx: 325, ry: 122, col: PAL.shadowSoft, op: 115 },
    { cx: 775, cy: 926, rx: 280, ry: 108, col: PAL.shadowMid, op: 145 },
    { cx: 718, cy: 920, rx: 245, ry: 98, col: PAL.shadowCore, op: 175 }
  ];

  for (let sl of shadLayers) {
    brush.fill(sl.col, sl.op);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.5, 0.3);
    brush.beginShape(0.25);
    for (let a = 0; a < 360; a += 18) {
      let x = sl.cx + sl.rx * cos(a);
      let y = sl.cy + sl.ry * sin(a) - 0.03 * (x - MUG.cx);
      brush.vertex(x, y);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Alcohol-marker shadow strokes following the plank grain inside the cast shadow
  for (let i = 0; i < 42; i++) {
    let t = i / 41;
    let y = lerp(825, 1028, t);
    let dy = (y - 924) / 106;
    if (abs(dy) >= 1) continue;
    let span = sqrt(1 - dy * dy);
    let xStart = MUG.cx - 190 * span;
    let xEnd = 805 + 310 * span;

    let col = abs(dy) < 0.55 ? PAL.aubergineDeep : abs(dy) < 0.8 ? PAL.shadowMid : PAL.plankDark;
    brush.set("alc_flat", col, random(0.85, 1.25));
    brush.line(xStart, y, xEnd, y - 0.045 * (xEnd - xStart));
  }

  // Cast shadow of the left handle loop on the plank
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let angle = lerp(135, 225, t);
    let x1 = 445 + 95 * cos(angle);
    let y1 = 918 + 52 * sin(angle);
    let x2 = 365 + 125 * cos(angle);
    let y2 = 932 + 64 * sin(angle);
    brush.set("alc_fine", i % 2 === 0 ? PAL.shadowMid : PAL.plankDark, 0.95);
    brush.line(x1, y1, x2, y2);
  }

  // Warm marigold & madder reflected caustic glow on the plank just in front-left of the mug base
  for (let i = 0; i < 20; i++) {
    let a = lerp(82, 152, i / 19);
    let p1 = cylPoint(a, 1.0, 2);
    let p2 = cylPoint(a, 1.0, random(18, 42));
    brush.set("alc_fine", i % 2 === 0 ? PAL.marigoldDeep : PAL.madderDeep, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Razor-dark ambient occlusion crevice right under the mug foot ring
  for (let pass = 0; pass < 3; pass++) {
    let pts = [];
    for (let a = 0; a <= 180; a += 6) {
      pts.push(cylPoint(a, 1.0, pass * 1.4 - 0.5));
    }
    brush.set(pass === 0 ? "rotring" : "alc_fine", PAL.aubergineBlack, pass === 0 ? 1.5 : 1.15);
    safeSpline(pts, 0.3);
  }
}

// ============================================================================
// 3. STAGE 0: UNTOUCHED IVORY-WHITE RESIST RESERVE
// Reserves the clean paper ground over the mug silhouette before dye stages
// ============================================================================
function drawMugWhiteReserve() {
  brush.noField();
  brush.noStroke();
  brush.wash(PAL.resistPure, 255);

  // Mug body + rim silhouette polygon
  brush.beginShape(0.05);
  // Top rim back curve (theta 180 to 360)
  for (let a = 180; a <= 360; a += 8) {
    let p = rimPoint(a, -90, 1);
    brush.vertex(p[0], p[1]);
  }
  // Right side down (v 0 to 1)
  for (let s = 0; s <= 12; s++) {
    let p = cylPoint(0, s / 12, 0.5);
    brush.vertex(p[0], p[1]);
  }
  // Bottom base curve (theta 0 to 180)
  for (let a = 8; a <= 180; a += 8) {
    let p = cylPoint(a, 1.0, 0.5);
    brush.vertex(p[0], p[1]);
  }
  // Left side up (v 1 to 0)
  for (let s = 12; s >= 0; s--) {
    let p = cylPoint(180, s / 12, 0.5);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // Handle silhouette white reserve
  // Outer arch + front edge
  brush.beginShape(0.1);
  for (let i = 0; i <= 24; i++) {
    let p = handlePoint(i / 24, 0.0, 0.0);
    brush.vertex(p[0], p[1]);
  }
  for (let i = 24; i >= 0; i--) {
    let p = handlePoint(i / 24, 1.0, 1.0);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  brush.noWash();
}

// ============================================================================
// 4. MUG INTERIOR WELL (Pysanky Dye Stages Inside the Cylinder Opening)
// ============================================================================
function drawMugInterior() {
  // Interior is visible for theta in [176, 364], clipped by frontRimCrestY(x)
  // Light comes from upper-left, so right-back interior wall (theta 265..355) is bright,
  // while left-back interior wall (theta 180..255) is deep aubergine-black & madder.

  function interiorLight(theta, vDepth) {
    // Specular reflection crescent on right-back interior wall around theta = 312 deg
    let dSpec = abs(theta - (312 + vDepth * 12));
    let spec = exp(-pow(dSpec / 22, 1.9)) * (1 - vDepth * 0.55);
    // Warm halftones across 265..355
    let warm = exp(-pow((theta - 305) / 46, 1.8)) * 0.52 * (1 - vDepth * 0.4);
    // Subtle left rim inner bounce near theta = 192
    let leftIn = exp(-pow((theta - 194) / 14, 2)) * 0.26 * (1 - vDepth * 0.7);
    // Pysanky stepped contour ring inside rim around vDepth = 0.14
    let ringBoost = abs(vDepth - 0.14) < 0.025 ? 0.12 : 0;
    return constrain(max(spec, warm) + leftIn + ringBoost, 0, 1);
  }

  // Helper to draw clipped vertical interior marker strokes for a given stage threshold
  function drawInteriorStage(maxLight, col1, col2, brushName, stepDeg, weightMul) {
    for (let theta = 178; theta <= 362; theta += stepDeg) {
      let pts = [];
      for (let s = 0; s <= 26; s++) {
        let vDepth = (s / 26) * 0.48;
        let L = interiorLight(theta, vDepth);
        let p = cylPoint(theta, vDepth, -MUG.rimTube + 2);
        let yClip = frontRimCrestY(p[0]) + 4;
        if (p[1] <= yClip && L <= maxLight) {
          pts.push(p);
        } else {
          if (pts.length >= 2) {
            let c = ( floor(theta) + s ) % 2 === 0 ? col1 : col2;
            brush.set(brushName, c, weightMul * random(0.88, 1.15));
            safeSpline(pts, 0.25);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        let c = floor(theta) % 2 === 0 ? col1 : col2;
        brush.set(brushName, c, weightMul * random(0.88, 1.15));
        safeSpline(pts, 0.25);
      }
    }
  }

  // Stage 1: Chrome Yellow across interior (leaving white resist crescent at L > 0.84)
  drawInteriorStage(0.84, PAL.chromeBright, PAL.chromeMid, "alc_flat", 1.8, 1.05);

  // Stage 2: Marigold climbing over yellow (L <= 0.64)
  drawInteriorStage(0.64, PAL.marigoldBright, PAL.marigoldMid, "alc_flat", 1.7, 1.05);

  // Stage 3: Madder Red climbing over marigold (L <= 0.44)
  drawInteriorStage(0.44, PAL.madderBright, PAL.madderMid, "alc_flat", 1.6, 1.1);
  drawInteriorStage(0.34, PAL.madderDeep, PAL.madderDark, "alc_fine", 2.0, 1.0);

  // Stage 4: Glossy Aubergine-Black in deep interior shadow (L <= 0.24)
  drawInteriorStage(0.24, PAL.auberginePlum, PAL.aubergineMid, "alc_flat", 1.6, 1.15);
  drawInteriorStage(0.15, PAL.aubergineDeep, PAL.aubergineBlack, "alc_fine", 1.8, 1.1);

  // Circumferential marker sweep arcs inside the bowl to give curved enamel gloss
  for (let vDepth = 0.03; vDepth <= 0.42; vDepth += 0.035) {
    for (let theta = 182; theta <= 354; theta += 12) {
      let L = interiorLight(theta + 6, vDepth);
      let col = PAL.aubergineDeep;
      if (L > 0.84) col = PAL.resistPure;
      else if (L > 0.64) col = PAL.chromeBright;
      else if (L > 0.44) col = PAL.marigoldMid;
      else if (L > 0.24) col = PAL.madderMid;

      let arcPts = [];
      for (let a = theta; a <= theta + 14; a += 3.5) {
        let p = cylPoint(a, vDepth, -MUG.rimTube + 2);
        if (p[1] <= frontRimCrestY(p[0]) + 3) arcPts.push(p);
      }
      if (arcPts.length >= 2) {
        brush.set("alc_fine", col, 0.85);
        safeSpline(arcPts, 0.3);
      }
    }
  }

  // Crisp white-resist kistka lines and stage-division arcs inside the right interior highlight
  const resistThresholds = [
    { target: 0.84, col: PAL.resistPure, br: "kistka" },
    { target: 0.64, col: PAL.chromeBright, br: "kistka_hair" },
    { target: 0.44, col: PAL.marigoldBright, br: "kistka_hair" }
  ];
  for (let rt of resistThresholds) {
    for (let side of [-1, 1]) {
      let pts = [];
      for (let s = 0; s <= 22; s++) {
        let vDepth = (s / 22) * 0.36;
        // Find theta near 312 + side * offset where L ~ rt.target
        let bestTheta = 312;
        let bestDiff = 999;
        for (let a = 240; a <= 358; a += 2) {
          if ((a - 312) * side < 0) continue;
          let diff = abs(interiorLight(a, vDepth) - rt.target);
          if (diff < bestDiff) {
            bestDiff = diff;
            bestTheta = a;
          }
        }
        let p = cylPoint(bestTheta, vDepth, -MUG.rimTube + 2);
        if (p[1] <= frontRimCrestY(p[0]) + 1 && bestDiff < 0.08) pts.push(p);
      }
      if (pts.length >= 2) {
        brush.set(rt.br, rt.col, 0.95);
        safeSpline(pts, 0.3);
      }
    }
  }

  // Interior pysanky resist ring at vDepth = 0.14
  let inRingPts = [];
  for (let a = 268; a <= 352; a += 4) {
    let p = cylPoint(a, 0.14, -MUG.rimTube + 2);
    if (p[1] <= frontRimCrestY(p[0])) inRingPts.push(p);
  }
  brush.set("kistka", PAL.resistWarm, 0.9);
  safeSpline(inRingPts, 0.3);
}

// ============================================================================
// 5. BACK HALF OF ROLLED RIM TORUS (theta 178..362)
// ============================================================================
function drawRolledRimBack() {
  // On the back rim, phi goes from -180 (inner wall edge) over -90 (top crest) to -15 (outer back edge)
  function backRimLight(theta, phi) {
    // Top crest around phi = -82 catches strong overhead light
    let crestFactor = exp(-pow((phi - -82) / 42, 2));
    // Left-back (theta ~ 205..245) and right-back (theta ~ 300..348) catch bright rim light
    let thetaGlow =
      0.92 * exp(-pow((theta - 222) / 28, 2)) +
      0.96 * exp(-pow((theta - 322) / 32, 2)) +
      0.38 * exp(-pow((theta - 270) / 40, 2));
    return constrain(crestFactor * thetaGlow + 0.12 * crestFactor, 0, 1);
  }

  // Circumferential torus rings in pysanky stage order
  const stages = [
    { maxL: 0.85, col: PAL.chromeBright, br: "alc_fine", w: 0.95 },
    { maxL: 0.65, col: PAL.marigoldMid, br: "alc_fine", w: 0.95 },
    { maxL: 0.45, col: PAL.madderMid, br: "alc_fine", w: 1.0 },
    { maxL: 0.26, col: PAL.aubergineMid, br: "alc_fine", w: 1.05 },
    { maxL: 0.16, col: PAL.aubergineBlack, br: "alc_fine", w: 1.0 }
  ];

  for (let st of stages) {
    for (let phi = -175; phi <= -15; phi += 12) {
      let pts = [];
      for (let theta = 178; theta <= 362; theta += 3) {
        let L = backRimLight(theta, phi);
        if (L <= st.maxL) {
          pts.push(rimPoint(theta, phi));
        } else {
          if (pts.length >= 2) {
            brush.set(st.br, st.col, st.w);
            safeSpline(pts, 0.3);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        brush.set(st.br, st.col, st.w);
        safeSpline(pts, 0.3);
      }
    }
  }

  // Razor-sharp white resist specular arcs on the top crest of the back rim
  const backHighlights = [
    { t1: 196, t2: 246, phi: -82, w: 1.15 },
    { t1: 294, t2: 348, phi: -80, w: 1.25 },
    { t1: 304, t2: 338, phi: -94, w: 0.85 }
  ];
  for (let bh of backHighlights) {
    let pts = [];
    for (let a = bh.t1; a <= bh.t2; a += 3) {
      pts.push(rimPoint(a, bh.phi));
    }
    brush.set("kistka", PAL.resistPure, bh.w);
    safeSpline(pts, 0.3);
  }

  // Fine kistka chevron resist ticks along the back rim inner bevel
  for (let a = 190; a <= 350; a += 6) {
    let L = backRimLight(a, -120);
    if (L > 0.38) {
      let p1 = rimPoint(a, -110);
      let p2 = rimPoint(a + 2.5, -145);
      brush.set("kistka_hair", L > 0.65 ? PAL.resistWarm : PAL.chromeBright, 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 6. MUG EXTERIOR BODY — THE 4 PYSANKY ALCOHOL-MARKER DYE STAGES
// Colour climbs in stages: Chrome Yellow -> Marigold -> Madder Red -> Aubergine-Black
// ============================================================================
function drawMugBodyStages() {
  // Helper: Draw vertical & circumferential alcohol-marker passes for a given dye bath
  function applyDyeStage(maxLight, colPrimary, colSecondary, colDeep, stepDeg, vStep) {
    // Pass A: Vertical cylinder generator strokes (builds enamel vertical gloss streaks)
    for (let theta = 0; theta <= 180; theta += stepDeg) {
      let pts = [];
      for (let s = 0; s <= vStep; s++) {
        let v = s / vStep;
        let L = getMugLight(theta, v);
        if (L <= maxLight) {
          pts.push(cylPoint(theta, v));
        } else {
          if (pts.length >= 2) {
            let col = (floor(theta * 2) + s) % 3 === 0 ? colSecondary : colPrimary;
            brush.set("alc_flat", col, random(0.88, 1.18));
            safeSpline(pts, 0.22);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        let col = floor(theta * 2) % 2 === 0 ? colPrimary : colSecondary;
        brush.set("alc_flat", col, random(0.88, 1.18));
        safeSpline(pts, 0.22);
      }
    }

    // Pass B: Fine alcohol-marker edge refinement & circumferential glaze rings
    for (let v = 0.015; v <= 0.99; v += 0.028) {
      let pts = [];
      for (let theta = 0; theta <= 180; theta += 2.5) {
        let L = getMugLight(theta, v);
        if (L <= maxLight - 0.02) {
          pts.push(cylPoint(theta, v));
        } else {
          if (pts.length >= 2) {
            brush.set("alc_fine", colDeep, 0.92);
            safeSpline(pts, 0.3);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        brush.set("alc_fine", colDeep, 0.92);
        safeSpline(pts, 0.3);
      }
    }
  }

  // --------------------------------------------------------------------------
  // STAGE 1: CHROME YELLOW DYE BATH (covers everything with L <= 0.88)
  // Leaves pure untouched white resist (L > 0.88) in the razor specular cores!
  // --------------------------------------------------------------------------
  applyDyeStage(0.88, PAL.chromeBright, PAL.chromeMid, PAL.chromeDeep, 1.35, 36);

  // Extra saturated yellow marker glaze in the highlight transition bands
  for (let theta of [24, 26, 32, 34, 114, 117, 120, 134, 137, 140, 173, 176]) {
    let pts = [];
    for (let s = 0; s <= 24; s++) {
      let v = s / 24;
      if (getMugLight(theta, v) <= 0.88) pts.push(cylPoint(theta, v));
    }
    if (pts.length >= 2) {
      brush.set("alc_fine", PAL.chromeBright, 1.1);
      safeSpline(pts, 0.25);
    }
  }

  // --------------------------------------------------------------------------
  // STAGE 2: MARIGOLD DYE BATH (climbs over yellow where L <= 0.68)
  // Leaves Chrome Yellow glowing in specular halos, lower bounce & pysanky motifs!
  // --------------------------------------------------------------------------
  applyDyeStage(0.68, PAL.marigoldBright, PAL.marigoldMid, PAL.marigoldDeep, 1.35, 36);

  // --------------------------------------------------------------------------
  // STAGE 3: MADDER RED DYE BATH (climbs over marigold where L <= 0.48)
  // Deep earthen crimson alcohol-marker glaze across the body
  // --------------------------------------------------------------------------
  applyDyeStage(0.48, PAL.madderBright, PAL.madderMid, PAL.madderDeep, 1.3, 38);

  // Second rich Madder Dark glaze pass for deep enamel saturation (L <= 0.37)
  applyDyeStage(0.37, PAL.madderMid, PAL.madderDeep, PAL.madderDark, 1.5, 34);

  // --------------------------------------------------------------------------
  // STAGE 4: GLOSSY AUBERGINE-BLACK FINAL DYE BATH (climbs where L <= 0.28)
  // Creates the mirror-dark enamel core while letting previous stages glow!
  // --------------------------------------------------------------------------
  applyDyeStage(0.28, PAL.auberginePlum, PAL.aubergineMid, PAL.aubergineDeep, 1.3, 38);

  // Deepest mirror-black core pass (L <= 0.19)
  applyDyeStage(0.19, PAL.aubergineDeep, PAL.aubergineBlack, PAL.aubergineBlack, 1.4, 34);
}

// ============================================================================
// 7. PYSANKY KISTKA RESIST LINES, FOLK-OPTICAL FACETS & SPECULAR HIGHLIGHTS
// ============================================================================
function drawBodyResistAndSpeculars() {
  // A. Re-inforce the untouched White Resist Specular Window Column (theta ~ 123..131)
  // and Secondary Right Specular Column (theta ~ 28..31)
  for (let theta = 123.5; theta <= 130.5; theta += 1.1) {
    let ptsTop = [];
    let ptsBot = [];
    for (let s = 0; s <= 40; s++) {
      let v = s / 40;
      let L = getMugLight(theta, v);
      if (L > 0.86) {
        if (v < 0.415) ptsTop.push(cylPoint(theta, v));
        else if (v > 0.435) ptsBot.push(cylPoint(theta, v));
      }
    }
    brush.set("kistka", PAL.resistPure, 1.15);
    safeSpline(ptsTop, 0.2);
    safeSpline(ptsBot, 0.2);
  }

  // Secondary right razor white resist column
  for (let theta = 28.2; theta <= 30.6; theta += 0.8) {
    let pts = [];
    for (let s = 2; s <= 36; s++) {
      let v = s / 40;
      if (getMugLight(theta, v) > 0.81) {
        pts.push(cylPoint(theta - v * 1.6, v));
      }
    }
    brush.set("kistka", PAL.resistPure, 0.95);
    safeSpline(pts, 0.2);
  }

  // Left grazing edge white/yellow resist filament (theta ~ 176.5)
  let leftEdgePts = [];
  for (let s = 3; s <= 35; s++) {
    let v = s / 40;
    leftEdgePts.push(cylPoint(176.5, v));
  }
  brush.set("kistka_hair", PAL.chromeBright, 0.95);
  safeSpline(leftEdgePts, 0.25);
  brush.set("kistka_hair", PAL.resistWarm, 0.8);
  safeSpline(leftEdgePts.slice(4, 22), 0.25);

  // B. Kistka Iso-Luminance Contour Lines & Serrated Pysanky Facet Divisions
  // Traces the exact boundaries between the 4 dye stages with fine resist lines!
  const stageContours = [
    { target: 0.87, col: PAL.resistPure, br: "kistka", w: 0.95 },
    { target: 0.68, col: PAL.resistWarm, br: "kistka_hair", w: 0.88 },
    { target: 0.66, col: PAL.chromeBright, br: "kistka_hair", w: 0.9 },
    { target: 0.48, col: PAL.chromeBright, br: "kistka_hair", w: 0.82 },
    { target: 0.46, col: PAL.marigoldBright, br: "kistka_hair", w: 0.85 },
    { target: 0.28, col: PAL.madderBright, br: "kistka_hair", w: 0.8 }
  ];

  // Trace contours around the primary reflection (both left and right flanks)
  // and secondary reflection
  const searchZones = [
    { center: 126, minA: 82, maxA: 126 },
    { center: 126, minA: 126, maxA: 164 },
    { center: 29, minA: 8, maxA: 29 },
    { center: 29, minA: 29, maxA: 52 }
  ];

  for (let sc of stageContours) {
    for (let sz of searchZones) {
      let pts = [];
      for (let s = 1; s <= 44; s++) {
        let v = s / 45;
        let bestA = sz.center;
        let bestDiff = 999;
        for (let a = sz.minA; a <= sz.maxA; a += 1.0) {
          let diff = abs(getMugLight(a, v) - sc.target);
          if (diff < bestDiff) {
            bestDiff = diff;
            bestA = a;
          }
        }
        if (bestDiff < 0.065) {
          pts.push(cylPoint(bestA, v));
        } else {
          if (pts.length >= 3) {
            brush.set(sc.br, sc.col, sc.w);
            safeSpline(pts, 0.25);
          }
          pts = [];
        }
      }
      if (pts.length >= 3) {
        brush.set(sc.br, sc.col, sc.w);
        safeSpline(pts, 0.25);
      }
    }
  }

  // C. Pysanky Geometric Resist Collar Band (v = 0.065..0.135) & Base Band (v = 0.835..0.90)
  // Drawn with kistka lines whose color steps optically with the local light level
  // so it looks both folk-dyed AND photographically integrated into the enamel gloss!
  function getResistLineColor(L) {
    if (L > 0.62) return PAL.resistPure;
    if (L > 0.42) return PAL.chromeBright;
    if (L > 0.25) return PAL.marigoldBright;
    return PAL.madderBright;
  }

  function drawPysankyBand(vTop, vBot, hasStars) {
    let vMid = (vTop + vBot) * 0.5;

    // Top and bottom framing kistka double-lines
    for (let vLine of [vTop, vTop + 0.008, vBot - 0.008, vBot]) {
      for (let a = 4; a <= 172; a += 6) {
        let L = getMugLight(a + 3, vLine);
        if (L < 0.16) continue; // Disappears into deep mirror aubergine shadow!
        let col = getResistLineColor(L);
        let p1 = cylPoint(a, vLine);
        let p2 = cylPoint(a + 3, vLine);
        let p3 = cylPoint(a + 6, vLine);
        brush.set("kistka_hair", col, L > 0.55 ? 0.92 : 0.72);
        safeSpline([p1, p2, p3], 0.25);
      }
    }

    // Serrated endless-wave (bezkonechnyk) & diamond lattice (reshitka) inside band
    let stepA = 8;
    for (let a = 6; a <= 166; a += stepA) {
      let L = getMugLight(a + stepA * 0.5, vMid);
      if (L < 0.18) continue;
      let col = getResistLineColor(L);
      let w = L > 0.58 ? 0.95 : 0.75;

      let pLeft = cylPoint(a, vMid);
      let pTop = cylPoint(a + stepA * 0.5, vTop + 0.012);
      let pRight = cylPoint(a + stepA, vMid);
      let pBot = cylPoint(a + stepA * 0.5, vBot - 0.012);

      brush.set("kistka_hair", col, w);
      brush.line(pLeft[0], pLeft[1], pTop[0], pTop[1]);
      brush.line(pTop[0], pTop[1], pRight[0], pRight[1]);
      brush.line(pLeft[0], pLeft[1], pBot[0], pBot[1]);
      brush.line(pBot[0], pBot[1], pRight[0], pRight[1]);

      // 8-point pysanky solar star (ruzha) ticks inside the brightest diamonds
      if (hasStars && L > 0.34) {
        let pCenter = cylPoint(a + stepA * 0.5, vMid);
        let pV1 = cylPoint(a + stepA * 0.5, vTop + 0.018);
        let pV2 = cylPoint(a + stepA * 0.5, vBot - 0.018);
        let pH1 = cylPoint(a + stepA * 0.18, vMid);
        let pH2 = cylPoint(a + stepA * 0.82, vMid);
        brush.set("kistka_hair", L > 0.52 ? PAL.resistPure : PAL.chromeBright, 0.7);
        brush.line(pV1[0], pV1[1], pV2[0], pV2[1]);
        brush.line(pH1[0], pH1[1], pH2[0], pH2[1]);
        // Tiny center resist dot
        brush.circle(pCenter[0], pCenter[1], 1.4);
      }
    }
  }

  drawPysankyBand(0.065, 0.135, true);
  drawPysankyBand(0.835, 0.90, false);

  // D. Fine horizontal kistka specular cross-stitches across the window reflection boundary
  for (let v = 0.16; v <= 0.80; v += 0.032) {
    // Window mullion gap around v = 0.425 gets a crisp double resist line
    let isMullion = abs(v - 0.425) < 0.022;
    let span = isMullion ? 16 : 6.5;
    let centerA = 127 - v * 3.2;
    let p1 = cylPoint(centerA - span, v);
    let p2 = cylPoint(centerA, v);
    let p3 = cylPoint(centerA + span, v);
    brush.set("kistka_hair", isMullion ? PAL.chromeBright : PAL.resistPure, isMullion ? 0.85 : 0.75);
    safeSpline([p1, p2, p3], 0.25);
  }

  // E. Razor-sharp bottom foot-ring specular highlight (v = 0.978)
  let footHiPts = [];
  for (let a = 92; a <= 148; a += 3) {
    footHiPts.push(cylPoint(a, 0.978));
  }
  brush.set("kistka", PAL.chromeBright, 1.0);
  safeSpline(footHiPts, 0.3);
  brush.set("kistka", PAL.resistPure, 0.95);
  safeSpline(footHiPts.slice(3, 15), 0.3);
}

// ============================================================================
// 8. FRONT HALF OF ROLLED RIM TORUS (theta -2..182)
// ============================================================================
function drawRolledRimFront() {
  // On the front rim, phi goes from -155 (inner lip) over -90 (top crest)
  // through 0 (front equator) to +78 (underside overhang meeting mug body)
  function frontRimLight(theta, phi) {
    // Upper-front bevel around phi = -48..-18 catches blazing specular light!
    let bevelSpec = exp(-pow((phi - -35) / 28, 2));
    // Under-lip overhang (phi > 25) drops into deep aubergine-black shadow
    let underShadow = phi > 20 ? pow((phi - 20) / 58, 1.2) * 0.72 : 0;

    // Circumferential light along front rim:
    // Blazing peak at front-left (theta ~ 108..146) and front-right (theta ~ 22..52)
    let thetaLight =
      0.98 * exp(-pow((theta - 128) / 26, 2)) +
      0.92 * exp(-pow((theta - 36) / 20, 2)) +
      0.48 * exp(-pow((theta - 82) / 32, 2)) +
      0.62 * exp(-pow((theta - 172) / 12, 2));

    // Top inner crest reflection around phi = -105
    let innerCrest = 0.45 * exp(-pow((phi - -105) / 22, 2)) * sin(theta);

    let ripple = (noise(theta * 0.25, phi * 0.15) - 0.5) * 0.04;
    return constrain(bevelSpec * thetaLight + innerCrest - underShadow + ripple, 0, 1);
  }

  // First, ensure clean white resist base across the front rim torus so it cleanly occludes interior
  for (let phi = -145; phi <= 72; phi += 9) {
    let pts = [];
    for (let theta = -2; theta <= 182; theta += 4) {
      pts.push(rimPoint(theta, phi));
    }
    brush.set("alc_flat", PAL.resistPure, 1.15);
    safeSpline(pts, 0.3);
  }

  // Apply the 4 Pysanky Alcohol-Marker Stages around the front rim torus
  const rimStages = [
    { maxL: 0.86, col1: PAL.chromeBright, col2: PAL.chromeMid, br: "alc_fine", w: 1.0 },
    { maxL: 0.66, col1: PAL.marigoldBright, col2: PAL.marigoldMid, br: "alc_fine", w: 1.0 },
    { maxL: 0.46, col1: PAL.madderBright, col2: PAL.madderMid, br: "alc_fine", w: 1.05 },
    { maxL: 0.34, col1: PAL.madderDeep, col2: PAL.madderDark, br: "alc_fine", w: 1.0 },
    { maxL: 0.24, col1: PAL.auberginePlum, col2: PAL.aubergineMid, br: "alc_fine", w: 1.05 },
    { maxL: 0.14, col1: PAL.aubergineDeep, col2: PAL.aubergineBlack, br: "alc_fine", w: 1.1 }
  ];

  for (let st of rimStages) {
    for (let phi = -150; phi <= 76; phi += 7.5) {
      let pts = [];
      for (let theta = -2; theta <= 182; theta += 2.5) {
        let L = frontRimLight(theta, phi);
        if (L <= st.maxL) {
          pts.push(rimPoint(theta, phi));
        } else {
          if (pts.length >= 2) {
            let c = floor(phi + theta) % 2 === 0 ? st.col1 : st.col2;
            brush.set(st.br, c, st.w);
            safeSpline(pts, 0.3);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        brush.set(st.br, st.col1, st.w);
        safeSpline(pts, 0.3);
      }
    }
  }

  // Cross-sectional curved strokes wrapping over the rolled lip (gives 3D tubular roundness)
  for (let theta = 2; theta <= 178; theta += 3.5) {
    for (let phi = -135; phi <= 55; phi += 25) {
      let L = frontRimLight(theta, phi + 12);
      if (L > 0.86) continue;
      let col = PAL.aubergineDeep;
      if (L > 0.66) col = PAL.chromeMid;
      else if (L > 0.46) col = PAL.marigoldMid;
      else if (L > 0.24) col = PAL.madderMid;

      let p1 = rimPoint(theta, phi);
      let p2 = rimPoint(theta, phi + 12);
      let p3 = rimPoint(theta, phi + 24);
      brush.set("alc_fine", col, 0.72);
      safeSpline([p1, p2, p3], 0.3);
    }
  }

  // Deep shadow crease right under the rolled lip overhang (phi = 72..80)
  for (let phi of [68, 75]) {
    let underPts = [];
    for (let theta = 0; theta <= 180; theta += 3) {
      underPts.push(rimPoint(theta, phi));
    }
    brush.set("kistka", phi === 75 ? PAL.aubergineBlack : PAL.madderDark, 1.15);
    safeSpline(underPts, 0.3);
  }

  // Blazing Untouched White Resist Specular Lines along the Front Rolled Rim!
  const frontRimSpecArcs = [
    { t1: 100, t2: 152, phi: -36, w: 1.45, col: PAL.resistPure },
    { t1: 106, t2: 146, phi: -24, w: 1.25, col: PAL.resistPure },
    { t1: 92, t2: 158, phi: -48, w: 0.95, col: PAL.resistWarm },
    { t1: 20, t2: 52, phi: -34, w: 1.25, col: PAL.resistPure },
    { t1: 24, t2: 46, phi: -22, w: 0.95, col: PAL.resistPure },
    { t1: 68, t2: 94, phi: -35, w: 0.8, col: PAL.chromeBright },
    { t1: 164, t2: 178, phi: -30, w: 0.9, col: PAL.chromeBright }
  ];
  for (let arc of frontRimSpecArcs) {
    let pts = [];
    for (let a = arc.t1; a <= arc.t2; a += 2.5) {
      pts.push(rimPoint(a, arc.phi));
    }
    brush.set("kistka", arc.col, arc.w);
    safeSpline(pts, 0.3);
  }

  // Fine kistka resist contour steps & diagonal tick marks along the rim stage transitions
  for (let a = 12; a <= 170; a += 4.5) {
    let L = frontRimLight(a, -35);
    if (L > 0.45 && L < 0.86) {
      let p1 = rimPoint(a, -52);
      let p2 = rimPoint(a + 2, -16);
      brush.set("kistka_hair", L > 0.66 ? PAL.resistPure : PAL.chromeBright, 0.75);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 9. THE LEFT ENAMEL STRAP HANDLE (3D Ribbon in Pysanky Stages)
// ============================================================================
function drawEnamelHandle() {
  // Handle consists of:
  // A. Inner underside of loop visible for t in [0.44, 0.96] (between s=0..1 at thick=1)
  // B. Outer face of strap visible for t in [0.0, 0.98] (between s=0..1 at thick=0)
  // C. Front thickness edge of strap (at s=1, between thick=0 and thick=1)
  // D. Upper & lower spot-welded attachment flanges on the mug body

  // --- A. Inner Underside of the Handle Loop (t = 0.44..0.96) ---
  function handleInnerLight(t, s) {
    // Lower inner curve (t ~ 0.62..0.82) catches warm marigold/yellow bounce light from plank
    let bounce = exp(-pow((t - 0.72) / 0.14, 2)) * (0.45 + 0.28 * s);
    return constrain(bounce, 0, 1);
  }

  // Base white reserve for inner loop
  for (let s = 0; s <= 1; s += 0.12) {
    let pts = [];
    for (let i = 18; i <= 40; i++) {
      pts.push(handlePoint(i / 42, s, 1.0));
    }
    brush.set("alc_fine", PAL.chromeMid, 1.0);
    safeSpline(pts, 0.3);
  }

  // Layer Marigold, Madder, and Aubergine-Black on inner underside
  const innerStages = [
    { maxL: 0.62, col: PAL.marigoldMid },
    { maxL: 0.42, col: PAL.madderMid },
    { maxL: 0.28, col: PAL.madderDark },
    { maxL: 0.18, col: PAL.aubergineDeep }
  ];
  for (let st of innerStages) {
    for (let s = 0; s <= 1; s += 0.14) {
      let pts = [];
      for (let i = 18; i <= 40; i++) {
        let t = i / 42;
        if (handleInnerLight(t, s) <= st.maxL) {
          pts.push(handlePoint(t, s, 1.0));
        } else {
          if (pts.length >= 2) {
            brush.set("alc_fine", st.col, 0.95);
            safeSpline(pts, 0.3);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        brush.set("alc_fine", st.col, 0.95);
        safeSpline(pts, 0.3);
      }
    }
  }

  // --- B. Outer Strap Surface of the Handle (t = 0.0..0.98, thick = 0) ---
  function handleOuterLight(t, s) {
    // Blazing sky/window highlight on top arch (t ~ 0.14..0.32), brightest near front edge (s ~ 0.65..0.9)
    let topArch = exp(-pow((t - 0.22) / 0.11, 2)) * (0.72 + 0.32 * exp(-pow((s - 0.72) / 0.35, 2)));
    // Secondary warm reflection on outer bend (t ~ 0.52..0.68)
    let midBend = 0.58 * exp(-pow((t - 0.58) / 0.12, 2)) * (0.6 + 0.4 * s);
    // Upper weld collar reflection (t < 0.08)
    let weldTop = t < 0.09 ? 0.42 * (1 - t / 0.09) : 0;
    // Pysanky chevron band on handle arch around t = 0.36..0.42
    let zig = abs(((s * 3) % 2) - 1);
    let bandBoost = abs(t - (0.37 + 0.03 * zig)) < 0.015 ? 0.16 : 0;
    return constrain(max(topArch, midBend, weldTop) + bandBoost, 0, 1);
  }

  // Ensure pure white resist base on outer strap
  for (let s = 0; s <= 1.01; s += 0.1) {
    let pts = [];
    for (let i = 0; i <= 44; i++) {
      pts.push(handlePoint(i / 44, s, 0.0));
    }
    brush.set("alc_fine", PAL.resistPure, 1.1);
    safeSpline(pts, 0.3);
  }

  // Apply the 4 Pysanky Alcohol-Marker Stages along the outer handle strap
  const outerStages = [
    { maxL: 0.86, col1: PAL.chromeBright, col2: PAL.chromeMid, w: 1.0 },
    { maxL: 0.66, col1: PAL.marigoldBright, col2: PAL.marigoldMid, w: 1.0 },
    { maxL: 0.46, col1: PAL.madderBright, col2: PAL.madderMid, w: 1.05 },
    { maxL: 0.32, col1: PAL.madderDeep, col2: PAL.madderDark, w: 1.0 },
    { maxL: 0.22, col1: PAL.auberginePlum, col2: PAL.aubergineMid, w: 1.05 },
    { maxL: 0.13, col1: PAL.aubergineDeep, col2: PAL.aubergineBlack, w: 1.05 }
  ];

  for (let st of outerStages) {
    for (let s = 0; s <= 1.01; s += 0.09) {
      let pts = [];
      for (let i = 0; i <= 48; i++) {
        let t = i / 48;
        let L = handleOuterLight(t, s);
        if (L <= st.maxL) {
          pts.push(handlePoint(t, s, 0.0));
        } else {
          if (pts.length >= 2) {
            let c = round(s * 10) % 2 === 0 ? st.col1 : st.col2;
            brush.set("alc_fine", c, st.w);
            safeSpline(pts, 0.3);
          }
          pts = [];
        }
      }
      if (pts.length >= 2) {
        brush.set("alc_fine", st.col1, st.w);
        safeSpline(pts, 0.3);
      }
    }
  }

  // Cross-strap marker & resist contour lines across the handle width
  for (let i = 2; i <= 44; i += 2) {
    let t = i / 46;
    let L = handleOuterLight(t, 0.6);
    if (L > 0.86) continue;
    let p0 = handlePoint(t, 0.05, 0.0);
    let p1 = handlePoint(t, 0.5, 0.0);
    let p2 = handlePoint(t, 0.95, 0.0);
    let col = L > 0.66 ? PAL.chromeMid : L > 0.46 ? PAL.marigoldMid : L > 0.24 ? PAL.madderMid : PAL.aubergineDeep;
    brush.set("alc_fine", col, 0.75);
    safeSpline([p0, p1, p2], 0.25);
  }

  // --- C. Front Rolled Thickness Edge of Handle Strap (s = 1.0, thick = 0..1) ---
  for (let th = 0.2; th <= 0.9; th += 0.35) {
    let edgePts = [];
    for (let i = 0; i <= 46; i++) {
      edgePts.push(handlePoint(i / 46, 1.0, th));
    }
    brush.set("alc_fine", th < 0.5 ? PAL.madderDark : PAL.aubergineBlack, 0.85);
    safeSpline(edgePts, 0.3);
  }

  // Razor-sharp Untouched White Resist Specular Highlights along the Handle!
  // 1. Top arch primary highlight
  for (let s of [0.55, 0.72, 0.88]) {
    let archPts = [];
    for (let i = 6; i <= 15; i++) {
      archPts.push(handlePoint(i / 48, s, 0.0));
    }
    brush.set("kistka", PAL.resistPure, 1.15);
    safeSpline(archPts, 0.3);
  }

  // 2. Front strap bevel continuous white/chrome-yellow resist edge line
  let frontBevelHi = [];
  for (let i = 2; i <= 36; i++) {
    frontBevelHi.push(handlePoint(i / 44, 0.96, 0.15));
  }
  brush.set("kistka_hair", PAL.chromeBright, 0.95);
  safeSpline(frontBevelHi, 0.3);
  brush.set("kistka", PAL.resistPure, 1.05);
  safeSpline(frontBevelHi.slice(2, 16), 0.3);
  safeSpline(frontBevelHi.slice(20, 29), 0.3);

  // 3. Back edge silhouette crisp dark definition + top crest glint
  let backEdgePts = [];
  for (let i = 0; i <= 44; i++) {
    backEdgePts.push(handlePoint(i / 44, 0.0, 0.0));
  }
  brush.set("kistka_hair", PAL.aubergineBlack, 0.95);
  safeSpline(backEdgePts, 0.3);
  brush.set("kistka_hair", PAL.chromeBright, 0.85);
  safeSpline(backEdgePts.slice(5, 15), 0.3);

  // 4. Pysanky chevron resist ornament on the handle strap (t = 0.35..0.43)
  for (let k = 0; k < 4; k++) {
    let s1 = k * 0.25;
    let s2 = s1 + 0.125;
    let s3 = s1 + 0.25;
    let pA = handlePoint(0.36, s1, 0.0);
    let pB = handlePoint(0.40, s2, 0.0);
    let pC = handlePoint(0.36, s3, 0.0);
    brush.set("kistka_hair", PAL.resistWarm, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
    brush.line(pB[0], pB[1], pC[0], pC[1]);
  }

  // --- D. Upper & Lower Weld Flanges (where handle joins mug wall) ---
  const welds = [
    { tBase: 0.0, vCenter: 0.18 },
    { tBase: 1.0, vCenter: 0.77 }
  ];
  for (let w of welds) {
    let pFront = handlePoint(w.tBase, 1.0, 0.2);
    let pBack = handlePoint(w.tBase, 0.0, 0.0);
    let pMid = [(pFront[0] + pBack[0]) * 0.5 + 8, (pFront[1] + pBack[1]) * 0.5];
    brush.set("alc_fine", PAL.aubergineBlack, 1.1);
    safeSpline([pBack, pMid, pFront], 0.3);
    brush.set("kistka_hair", PAL.marigoldBright, 0.85);
    safeSpline(
      [
        [pBack[0] + 3, pBack[1] - 2],
        [pMid[0] + 3, pMid[1] - 2],
        [pFront[0] + 3, pFront[1] - 2]
      ],
      0.3
    );
  }
}

// ============================================================================
// 10. CHIPPED ENAMEL SPOTS: BLUE-BLACK STEEL, TINY RUST HALOS & WHITE RESIST EDGES
// ============================================================================
function drawSingleChip(cfg) {
  // cfg: { cx, cy, rx, ry, rotDeg, seed, hasSatellite, isRim }
  // Generates a hyperrealistic multi-lobed enamel chip at (cx, cy) oriented along rotDeg
  let nPts = 24;
  let cosR = cos(cfg.rotDeg);
  let sinR = sin(cfg.rotDeg);

  function chipContour(scaleM, offsetX = 0, offsetY = 0) {
    let pts = [];
    for (let i = 0; i <= nPts; i++) {
      let a = (i / nPts) * 360;
      // Jagged brittle porcelain fracture modulation
      let n1 = noise(cfg.seed + cos(a) * 1.4, cfg.seed + sin(a) * 1.4);
      let n2 = noise(cfg.seed * 2.3 + i * 0.45);
      let lobe = 0.72 + 0.48 * n1 + 0.18 * (n2 - 0.5);
      let lx = cfg.rx * scaleM * lobe * cos(a);
      let ly = cfg.ry * scaleM * lobe * sin(a);
      let gx = cfg.cx + offsetX + lx * cosR - ly * sinR;
      let gy = cfg.cy + offsetY + lx * sinR + ly * cosR;
      pts.push([gx, gy]);
    }
    return pts;
  }

  // 1. Hairline enamel crazing cracks radiating outward from the chip impact
  let outerCheckPts = chipContour(1.12);
  for (let i = 0; i < nPts; i += 4) {
    if (noise(cfg.seed + i * 7.1) > 0.42) {
      let pStart = outerCheckPts[i];
      let a = (i / nPts) * 360 + cfg.rotDeg + random(-18, 18);
      let len = random(8, 22) * (cfg.rx / 24);
      let pMid = [
        pStart[0] + len * 0.55 * cos(a) + random(-2, 2),
        pStart[1] + len * 0.55 * sin(a) + random(-2, 2)
      ];
      let pEnd = [
        pMid[0] + len * 0.45 * cos(a + random(-25, 25)),
        pMid[1] + len * 0.45 * sin(a + random(-25, 25))
      ];
      brush.set("kistka_hair", PAL.aubergineBlack, 0.65);
      safeSpline([pStart, pMid, pEnd], 0.2);
      brush.set("kistka_hair", PAL.resistPure, 0.72);
      safeSpline(
        [
          [pStart[0] + 0.8, pStart[1] + 0.8],
          [pMid[0] + 0.8, pMid[1] + 0.8],
          [pEnd[0] + 0.8, pEnd[1] + 0.8]
        ],
        0.2
      );
    }
  }

  // 2. Stepped Pysanky Dye-Stage Enamel Fracture Bevel (Madder -> Marigold -> Chrome Yellow)
  const bevelRings = [
    { sc: 1.08, col: PAL.madderBright, br: "kistka", w: 1.1 },
    { sc: 1.02, col: PAL.marigoldBright, br: "kistka", w: 1.05 },
    { sc: 0.96, col: PAL.chromeBright, br: "kistka", w: 1.0 }
  ];
  for (let br of bevelRings) {
    let ringPts = chipContour(br.sc);
    brush.set(br.br, br.col, br.w);
    safeSpline(ringPts, 0.25);
  }

  // 3. Tiny Rust Halo (ferric oxide sienna & burnt orange bleeding around the bare steel rim)
  let rustOuter = chipContour(0.94);
  let rustInner = chipContour(0.78);
  for (let i = 0; i < nPts; i++) {
    let p1 = rustOuter[i];
    let p2 = rustInner[i];
    let rCol = i % 3 === 0 ? PAL.rustBright : i % 3 === 1 ? PAL.rustMid : PAL.rustDeep;
    brush.set("rust_grain", rCol, random(0.75, 1.2));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("kistka", PAL.rustMid, 0.95);
  safeSpline(rustOuter, 0.25);
  brush.set("kistka_hair", PAL.rustDark, 0.85);
  safeSpline(rustInner, 0.25);

  // Subtle downward gravity rust stain weeping below the chip
  if (!cfg.isRim && cfg.rx > 12) {
    let botPt = chipContour(0.98)[floor(nPts * 0.25)];
    brush.set("rust_grain", PAL.rustMid, 0.65);
    brush.line(botPt[0], botPt[1], botPt[0] + random(-2, 2), botPt[1] + random(6, 15));
  }

  // 4. Exposed Blue-Black Steel Core
  // Fill core with dense overlapping blue-black steel marker & hatch strokes
  let corePts = chipContour(0.82);
  brush.noStroke();
  brush.wash(PAL.steelDeep, 250);
  brush.beginShape(0.1);
  for (let i = 0; i < corePts.length - 1; i++) {
    brush.vertex(corePts[i][0], corePts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Cold-rolled steel striations & metallic blue-slate sheen across the exposed metal
  let nStr = max(6, floor(cfg.ry * 1.1));
  for (let j = -nStr; j <= nStr; j++) {
    let vFrac = j / nStr;
    if ( abs(vFrac) > 0.78 ) continue;
    let xSpan = sqrt(max(0, 0.68 - vFrac * vFrac)) * cfg.rx;
    let ly = vFrac * cfg.ry * 0.82;
    let lx1 = -xSpan;
    let lx2 = xSpan;

    let gx1 = cfg.cx + lx1 * cosR - ly * sinR;
    let gy1 = cfg.cy + lx1 * sinR + ly * cosR;
    let gx2 = cfg.cx + lx2 * cosR - ly * sinR;
    let gy2 = cfg.cy + lx2 * sinR + ly * cosR;

    // Metallic glint near the upper-left center of the steel core
    let distToGlint = abs(vFrac + 0.15);
    let col = PAL.steelDeep;
    if (distToGlint < 0.16) col = PAL.steelHighlight;
    else if (distToGlint < 0.34) col = PAL.steelSlate;
    else if (vFrac > 0.35) col = PAL.steelBlack;
    else col = PAL.steelMid;

    brush.set("steel_hatch", col, random(0.85, 1.2));
    brush.line(gx1, gy1, gx2, gy2);
  }

  // Dark inner shadow under the top-left enamel cliff of the chip (gives physical depth thickness!)
  let cliffPts = chipContour(0.84, 1.2, 1.5).slice(floor(nPts * 0.45), floor(nPts * 0.95));
  brush.set("kistka", PAL.steelBlack, 1.15);
  safeSpline(cliffPts, 0.25);

  // Fine cold metallic highlight glint streak inside the steel core
  let glintP1 = [cfg.cx - cfg.rx * 0.32 * cosR, cfg.cy - cfg.rx * 0.32 * sinR - 1.5];
  let glintP2 = [cfg.cx + cfg.rx * 0.24 * cosR, cfg.cy + cfg.rx * 0.24 * sinR - 1.5];
  brush.set("kistka_hair", PAL.steelHighlight, 0.88);
  brush.line(glintP1[0], glintP1[1], glintP2[0], glintP2[1]);

  // 5. UNTOUCHED WHITE RESIST HAIRLINE FRACTURE EDGE around the entire chip!
  // Doubles as the kistka wax-resist border and the razor specular glint on the fractured porcelain edge
  let whiteEdgePts = chipContour(1.13);
  brush.set("kistka_hair", PAL.resistWarm, 0.92);
  safeSpline(whiteEdgePts, 0.25);

  // Extra-bright thicker white resist highlight on the lower-right bevel facing the light source
  let litBevelPts = whiteEdgePts.slice(0, floor(nPts * 0.52));
  brush.set("kistka", PAL.resistPure, 1.2);
  safeSpline(litBevelPts, 0.25);
}

