function buildCeleryGeometry() {
  // 7 layered horizontal stalks + inner heart stalks spanning x = 125..960
  // Pinched at twine ties x = 355 and x = 745
  const stalkSpecs = [
    { id: 0, x0: 152, x1: 905, yBase: 500, wBase: 38, family: "olive", lightBias: 0.35, ribs: 6 },
    { id: 1, x0: 136, x1: 940, yBase: 536, wBase: 46, family: "chartreuse", lightBias: 0.78, ribs: 7 },
    { id: 2, x0: 168, x1: 975, yBase: 574, wBase: 38, family: "milky", lightBias: 0.92, ribs: 6 },
    { id: 3, x0: 126, x1: 935, yBase: 616, wBase: 54, family: "chartreuse", lightBias: 0.85, ribs: 8 },
    { id: 4, x0: 160, x1: 965, yBase: 660, wBase: 42, family: "buff", lightBias: 0.88, ribs: 6 },
    { id: 5, x0: 132, x1: 920, yBase: 702, wBase: 50, family: "chartreuse", lightBias: 0.55, ribs: 8 },
    { id: 6, x0: 148, x1: 885, yBase: 744, wBase: 42, family: "olive", lightBias: 0.25, ribs: 6 }
  ];

  for (let s of stalkSpecs) {
    stalks.push(s);
  }
}

// Evaluate centerline Y and half-width of stalk `s` at horizontal coordinate `x`
function getStalkProfile(s, x) {
  const yc = 622; // bundle central axis
  const dy0 = s.yBase - yc;

  // Pinch factor at twine ties (x = 355 and x = 745), swell at base (x = 160), belly (x = 550), flare at right (x > 800)
  const pinch1 = exp(-pow((x - 355) / 78, 2)) * 0.19;
  const pinch2 = exp(-pow((x - 745) / 72, 2)) * 0.22;
  const baseSwell = exp(-pow((x - 155) / 85, 2)) * 0.10;
  const bellySwell = exp(-pow((x - 550) / 135, 2)) * 0.08;
  const rightFlare = x > 760 ? pow((x - 760) / 220, 1.5) * 0.36 : 0;

  const spread = 1.0 - pinch1 - pinch2 + baseSwell + bellySwell + rightFlare;

  // Gentle organic horizontal wave along the bundle
  const arch =
    -sin(((x - 130) / 820) * 180) * 8 +
    sin(((x - 200) / 300) * 180) * 3.5 +
    (x > 750 ? (s.id - 3) * pow((x - 750) / 180, 1.4) * 5.5 : 0);

  const yCenter = yc + dy0 * spread + arch;

  // Width tapers slightly from thick succulent base toward knuckle, pinched at twine
  const taper = map(constrain(x, 125, 960), 125, 960, 1.14, 0.78);
  const tieCompress = 1.0 - exp(-pow((x - 355) / 18, 2)) * 0.08 - exp(-pow((x - 745) / 18, 2)) * 0.09;
  const halfW = (s.wBase * 0.5) * taper * tieCompress;

  return { y: yCenter, hw: halfW };
}

// Query overall bundle top and bottom envelope at `x`
function getBundleEnvelope(x) {
  const topP = getStalkProfile(stalks[0], x);
  const botP = getStalkProfile(stalks[stalks.length - 1], x);
  return {
    top: topP.y - topP.hw * 0.95,
    bot: botP.y + botP.hw * 0.95,
    mid: (topP.y + botP.y) * 0.5
  };
}

function buildPrairieGrid() {
  // Horizontal rail coordinates echoing Frank Lloyd Wright's leaded casements
  // Long, low architectural window spanning x = 56..1144, y = 196..992
  const yRails = [
    // Clerestory & upper repeated horizontals
    196, 214, 232, 256, 288, 326, 358, 382,
    // Celery bundle zone (dense horizontal dissection)
    412, 442, 470, 496, 522, 548, 574, 600, 626, 652, 678, 704, 730, 756, 782, 808, 830,
    // Sill & cast shadow zone
    856, 884, 910, 932
  ];

  for (let r = 0; r < yRails.length - 1; r++) {
    const y0 = yRails[r];
    const y1 = yRails[r + 1];
    const h = y1 - y0;
    const ym = (y0 + y1) * 0.5;

    let xStops = [56];
    let x = 56;

    // Determine subdivision rhythm according to zone
    const inBundleY = ym >= 382 && ym <= 830;
    const inClerestory = ym < 382;

    while (x < 1144) {
      let step = 64;

      if (inClerestory) {
        // Classic Wrightian side-mullion clusters with long calm central horizontal panes
        if (x < 230 || x > 940) {
          const choices = [22, 28, 36, 48, 22];
          step = choices[(r + floor(x / 25)) % choices.length];
        } else if (r <= 2 || r === 6) {
          step = 140 + ((r * 37) % 80);
        } else {
          step = 240 + ((r * 53) % 120);
        }
      } else if (inBundleY) {
        // Finer rectilinear dissection across the cut end, twine bindings, water beads & foliage
        if (x > 95 && x < 225) {
          // Cut root base facets
          const choices = [24, 30, 36, 28, 42];
          step = choices[(r * 3 + floor(x / 20)) % choices.length];
        } else if ((x > 320 && x < 390) || (x > 710 && x < 780)) {
          // Twine binding verticals
          const choices = [18, 22, 26, 20];
          step = choices[(r + floor(x / 18)) % choices.length];
        } else if (x > 840 && x < 1110) {
          // Leaf & knuckle mosaic facets
          const choices = [26, 34, 44, 28, 52, 24];
          step = choices[(r * 5 + floor(x / 24)) % choices.length];
        } else if (x >= 225 && x <= 840) {
          // Main ribbed stalks: long horizontal Wrightian rectangles punctuated by square jewels
          const mod = (r * 7 + floor(x / 45)) % 6;
          if (mod === 0) step = 28;
          else if (mod === 1) step = 54;
          else if (mod === 2) step = 88;
          else if (mod === 3) step = 68;
          else if (mod === 4) step = 104;
          else step = 46;
        } else {
          step = 36;
        }
      } else {
        // Sill & shadow zone
        if (x < 220 || x > 960) {
          step = 32 + ((r * 19 + floor(x / 30)) % 28);
        } else {
          step = 76 + ((r * 41 + floor(x / 60)) % 64);
        }
      }

      if (x + step > 1144 - 20) {
        x = 1144;
      } else {
        x += step;
      }
      xStops.push(x);
    }

    for (let c = 0; c < xStops.length - 1; c++) {
      const fx = xStops[c];
      const fw = xStops[c + 1] - fx;
      const facet = classifyFacet(fx, y0, fw, h, r, c);
      facets.push(facet);
    }
  }

  // Narrow border band of squares running along the bottom (y = 932..992)
  // Upper framing rail: 932..944, Square frieze: 944..980 (h = 36), Lower rail: 980..992
  const sqY = 944;
  const sqH = 36;
  let sx = 56;
  let idx = 0;
  const families = ["chartreuse", "milky", "olive", "buff", "amber", "milky", "chartreuse", "olive"];

  while (sx < 1144) {
    // Alternating rhythm of 36x36 squares with occasional narrow 14x36 Wrightian spacer billets
    let w = idx % 4 === 3 ? 16 : 36;
    if (sx + w > 1144 - 14) w = 1144 - sx;

    const fam = families[idx % families.length];
    const colArr = PAL[fam];
    const col = colArr[idx % colArr.length];

    squareBand.push({
      x: sx,
      y: sqY,
      w: w,
      h: sqH,
      family: fam,
      color: col,
      opacity: w >= 30 ? 115 : 95,
      hasInnerSquare: w >= 32 && idx % 2 === 0,
      idx: idx
    });

    sx += w;
    idx++;
  }
}

function classifyFacet(x, y, w, h, row, col) {
  const cx = x + w * 0.5;
  const cy = y + h * 0.5;

  // Refractive micro-offset for hyperreal details inside this glass facet
  const refDx = (noise(row * 0.37, col * 0.51) - 0.5) * 3.2;
  const refDy = (noise(col * 0.43, row * 0.29) - 0.5) * 2.8;

  const env = getBundleEnvelope(constrain(cx, 125, 1080));
  let region = "glass";
  let family = "milky";
  let color = PAL.milky[0];
  let opacity = 48;

  // 1. Check if facet dissects the bruised cut root end (left side x = 115..200)
  const cutRx = 42;
  const cutRy = (env.bot - env.top) * 0.52;
  const cutNorm = pow((cx - 154) / cutRx, 2) + pow((cy - env.mid) / cutRy, 2);

  if (cx >= 112 && cx <= 202 && cy >= env.top - 6 && cy <= env.bot + 6 && cutNorm <= 1.25) {
    region = "cutEnd";
    if (cutNorm < 0.35) {
      family = (row + col) % 2 === 0 ? "milky" : "buff";
      color = family === "milky" ? PAL.milky[0] : PAL.buff[0];
      opacity = 115;
    } else {
      family = (row + col) % 3 === 0 ? "buff" : "amber";
      color = family === "amber" ? PAL.amber[(row + col) % PAL.amber.length] : PAL.buff[1];
      opacity = 130;
    }
  }
  // 2. Check if facet dissects the twine bindings
  else if (
    ((cx >= 341 && cx <= 370) || (cx >= 731 && cx <= 760)) &&
    cy >= env.top - 4 &&
    cy <= env.bot + 4
  ) {
    region = "twine";
    family = (row + col) % 2 === 0 ? "amber" : "buff";
    color = family === "amber" ? PAL.amber[1] : PAL.buff[0];
    opacity = 125;
  }
  // 3. Check if facet dissects the main celery stalks (x = 150..920)
  else if (cx >= 145 && cx <= 925 && cy >= env.top - 8 && cy <= env.bot + 8) {
    region = "stalk";
    // Find closest stalk at (cx, cy)
    let bestStalk = stalks[3];
    let minDist = 9999;
    for (let s of stalks) {
      if (cx >= s.x0 - 15 && cx <= s.x1 + 25) {
        const p = getStalkProfile(s, cx);
        const d = abs(cy - p.y);
        if (d < minDist) {
          minDist = d;
          bestStalk = s;
        }
      }
    }

    // Select translucent ink fill from the 5 directive families based on stalk & facet position
    const hash = (row * 11 + col * 7) % 10;
    if (bestStalk.family === "milky") {
      family = hash < 6 ? "milky" : hash < 8 ? "chartreuse" : "buff";
    } else if (bestStalk.family === "buff") {
      family = hash < 5 ? "buff" : hash < 8 ? "milky" : "amber";
    } else if (bestStalk.family === "chartreuse") {
      family = hash < 6 ? "chartreuse" : hash === 6 ? "milky" : hash === 7 ? "amber" : "olive";
    } else {
      family = hash < 6 ? "olive" : hash < 8 ? "chartreuse" : "buff";
    }

    // Towards the left base, stalks blanch warmer/paler (buff / milky white)
    if (cx < 265 && hash < 5) {
      family = hash % 2 === 0 ? "milky" : "buff";
    }

    const arr = PAL[family];
    color = arr[(row * 3 + col) % arr.length];
    opacity = family === "milky" ? 105 : 122;
  }
  // 4. Check if facet dissects the celery leaves & branching knuckles (x = 870..1105)
  else if (cx > 860 && cx <= 1108 && cy >= 430 && cy <= 795) {
    // Leaf cluster silhouette envelope
    const leafCenterY = 612 + sin((cx - 860) * 1.1) * 28;
    const leafSpread = 165 * (1 - pow(max(0, cx - 960) / 160, 1.6));
    if (abs(cy - leafCenterY) < leafSpread) {
      region = "leaves";
      const h2 = (row * 5 + col * 3) % 9;
      if (h2 < 4) family = "olive";
      else if (h2 < 7) family = "chartreuse";
      else if (h2 === 7) family = "amber";
      else family = "milky";

      const arr = PAL[family];
      color = arr[(row + col) % arr.length];
      opacity = 118;
    }
  }

  // 5. Cast shadow facets directly beneath the bundle on the sill (y = 755..860)
  if (region === "glass" && cx >= 135 && cx <= 1040 && cy >= env.bot - 4 && cy <= env.bot + 72) {
    region = "shadow";
    const h3 = (row + col) % 4;
    family = h3 === 0 ? "olive" : h3 <= 2 ? "buff" : "amber";
    color = h3 === 0 ? PAL.olive[2] : h3 <= 2 ? PAL.buff[3] : PAL.amber[2];
    opacity = 78;
  }

  // 6. Surrounding Prairie School clear/tinted architectural window facets
  if (region === "glass") {
    const isCornerAccent =
      (cx < 220 || cx > 975) && w <= 42 && h <= 36 && (row * 3 + col) % 5 === 0;
    if (isCornerAccent) {
      const fams = ["amber", "chartreuse", "olive", "buff"];
      family = fams[(row + col) % fams.length];
      color = PAL[family][(row + col) % PAL[family].length];
      opacity = 88;
    } else {
      const gHash = (row * 7 + col * 13) % 8;
      if (gHash < 5) {
        family = "milky";
        color = PAL.milky[(row + col) % PAL.milky.length];
        opacity = 46;
      } else if (gHash < 7) {
        family = "buff";
        color = PAL.buff[2];
        opacity = 42;
      } else {
        family = "chartreuse";
        color = PAL.chartreuse[2];
        opacity = 32;
      }
    }
  }

  return {
    x,
    y,
    w,
    h,
    row,
    col,
    region,
    family,
    color,
    opacity,
    refDx,
    refDy
  };
}

