// Lookup facet containing (px, py) for optical glass refraction offset
function getFacetAt(px, py) {
  for (let i = 0; i < facets.length; i++) {
    const f = facets[i];
    if (px >= f.x && px <= f.x + f.w && py >= f.y && py <= f.y + f.h) {
      return f;
    }
  }
  return null;
}

