function drawFilteredLightGround() {
  background(PAL.ground);

  brush.noStroke();

  // Warm filtered diagonal sunlight shafts washing softly across the cool ground
  const shafts = [
    { x: 80, y: 196, w: 320, h: 796, col: PAL.paperWarm, op: 58 },
