// ============================================================================
// LAYER 2: TRANSLUCENT INK FILLS IN RECTILINEAR FACETS
// ============================================================================

function drawFacetTranslucentFills() {
  brush.noStroke();
  brush.noField();

  // 1. Fast crisp base ink wash for every facet so colors glow like stained glass
  for (let f of facets) {
    brush.wash(f.color, f.opacity);
    brush.rect(f.x + 0.8, f.y + 0.8, f.w - 1.6, f.h - 1.6, "corner");
  }

  // Base washes for the bottom narrow border band of squares
  for (let sq of squareBand) {
    brush.wash(sq.color, sq.opacity);
    brush.rect(sq.x + 0.8, sq.y + 0.8, sq.w - 1.6, sq.h - 1.6, "corner");
  }
  brush.noWash();

  // 2. Watercolor/ink bleed texture pass on key botanical & square facets (batched by color)
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.42, 0.32);

  const colorBatches = {};
  for (let f of facets) {
    if (f.region !== "glass" || f.opacity > 60) {
      const key = f.color;
      if (!colorBatches[key]) colorBatches[key] = [];
      colorBatches[key].push(f);
    }
  }

  for (let colKey in colorBatches) {
    const list = colorBatches[colKey];
    brush.fill(colKey, 58);
    for (let i = 0; i < list.length; i++) {
      const f = list[i];
      // Keep fill count lean for fast render while covering the celery & accent panes
      if (f.region !== "glass" || i % 2 === 0) {
        brush.rect(f.x + 1.5, f.y + 1.5, max(4, f.w - 3), max(4, f.h - 3), "corner");
      }
    }
  }

  // Texture pass on the bottom square band
  for (let sq of squareBand) {
    if (sq.w >= 30 && sq.idx % 2 === 0) {
      brush.fill(sq.color, 62);
      brush.rect(sq.x + 1.5, sq.y + 1.5, sq.w - 3, sq.h - 3, "corner");
    }
  }

  brush.noFill();
}

