function drawSubtleBundleUnderwash() {
  brush.noStroke();

  // Cast shadow on the sill beneath the bundle (cool slate-olive & deep olive)
  brush.wash(PAL.shadowSlate, 58);
  brush.rect(145, 768, 860, 44, "corner");
  brush.wash(PAL.shadowCool, 42);
  brush.rect(175, 812, 790, 26, "corner");
  brush.noWash();

  // Soft tonal modeling across the cylindrical volume of each stalk
  for (let s of stalks) {
    const step = 28;
    for (let x = s.x0; x < s.x1 - step; x += step) {
      const p = getStalkProfile(s, x + step * 0.5);
      // Shaded lower trough of each stalk
      brush.wash(s.family === "olive" ? PAL.olive[1] : PAL.olive[0], 34);
      brush.rect(x, p.y + p.hw * 0.18, step - 1, p.hw * 0.72, "corner");

      // Luminous upper-mid crown of each stalk
      const crownCol =
        s.family === "milky"
          ? PAL.milky[0]
          : s.family === "buff"
          ? PAL.buff[0]
          : PAL.chartreuse[2];
      brush.wash(crownCol, 45);
      brush.rect(x, p.y - p.hw * 0.75, step - 1, p.hw * 0.82, "corner");
    }
  }
  brush.noWash();
}

function drawHyperrealStalksAndRibs() {
  // For each stalk, render:
  // 1) Concave/convex inter-stalk shadow seams
  // 2) Transverse cellular parenchyma striations
  // 3) Crisp longitudinal collenchyma ribs (strings) with facet-by-facet optical refraction!
  for (let s of stalks) {
    const numRibs = s.ribs;

    // A. Transverse fine cellular striations inside the stalk flesh
    brush.set("2H", s.family === "milky" ? "#b8c9be" : "#6c8458", 0.28);
    for (let x = s.x0 + 18; x < s.x1 - 15; x += 9) {
      // Skip directly under twine wraps
      if (abs(x - 355) < 12 || abs(x - 745) < 11) continue;
      const p = getStalkProfile(s, x);
      const f = getFacetAt(x, p.y);
      const dy = f ? f.refDy * 0.7 : 0;
      const yTop = p.y - p.hw * 0.78 + dy;
      const yBot = p.y + p.hw * 0.78 + dy;
      brush.line(x, yTop, x + (noise(x * 0.1, s.id) - 0.5) * 2.5, yBot);
    }

    // B. Longitudinal stringy ribs (drawn segment-by-segment so each facet refracts slightly)
    for (let r = 0; r < numRibs; r++) {
      const vNorm = map(r, 0, numRibs - 1, -0.82, 0.82);
      const isTopLight = vNorm < 0.15;

      const segStep = 16;
      for (let x = s.x0 + 8; x < s.x1 - segStep; x += segStep) {
        const xNext = x + segStep;
        // Pause ribs under twine ties
        if ((xNext > 343 && x < 367) || (xNext > 734 && x < 756)) continue;

        const p1 = getStalkProfile(s, x);
        const p2 = getStalkProfile(s, xNext);

        const y1Raw = p1.y + vNorm * p1.hw;
        const y2Raw = p2.y + vNorm * p2.hw;

        // Facet refraction offset preserves hyperreal detail while showing glass dissection
        const f1 = getFacetAt((x + xNext) * 0.5, (y1Raw + y2Raw) * 0.5);
        const rDy = f1 ? f1.refDy * 0.85 : 0;

        const y1 = y1Raw + rDy;
        const y2 = y2Raw + rDy;

        // 1. Rib shadow groove (fine dark olive/amber trough right below the rib ridge)
        const shadowCol =
          x < 220
            ? PAL.amber[2]
            : vNorm > 0.25
            ? PAL.ribShadow
            : PAL.olive[1];
        brush.set("rotring", shadowCol, 0.36);
        brush.line(x, y1 + 1.8, xNext, y2 + 1.8);

        // 2. Secondary chlorophyll sub-ridge
        const midCol =
          s.family === "milky"
            ? PAL.buff[0]
            : s.family === "buff"
            ? PAL.amber[1]
            : PAL.chartreuse[0];
        brush.set("cpencil", midCol, 0.45);
        brush.line(x, y1 + 0.7, xNext, y2 + 0.7);

        // 3. Crisp stringy collenchyma cord highlight (iridescent milky white / pale chartreuse)
        const cordCol =
          isTopLight || s.family === "milky" ? PAL.ribLight : PAL.ribGlow;
        const cordWeight = r % 2 === 0 ? 0.58 : 0.42;
        brush.set("pen", cordCol, cordWeight);
        brush.line(x, y1 - 0.5, xNext, y2 - 0.5);
      }
    }

    // C. Deep inter-stalk separation crease along the bottom & top of each stalk
    for (let x = s.x0 + 10; x < s.x1 - 18; x += 18) {
      if ((x > 340 && x < 368) || (x > 732 && x < 758)) continue;
      const p1 = getStalkProfile(s, x);
      const p2 = getStalkProfile(s, x + 18);
      const f = getFacetAt(x + 9, p1.y + p1.hw);
      const rDy = f ? f.refDy : 0;

      // Bottom occlusion shadow
      brush.set("rotring", PAL.leafDeep, 0.62);
      brush.line(x, p1.y + p1.hw + rDy, x + 18, p2.y + p2.hw + rDy);

      // Upper rim edge catch-light
      brush.set("pen", PAL.milky[0], 0.48);
      brush.line(x, p1.y - p1.hw + rDy, x + 18, p2.y - p2.hw + rDy);
    }
  }

  // D. Loose, curling peeled celery strings near the cut base and snapped stalks
  const looseStrings = [
    [
      [168, 518],
      [148, 508],
      [132, 494],
      [124, 480]
    ],
    [
      [182, 592],
      [158, 586],
      [138, 574],
      [126, 560]
    ],
    [
      [176, 678],
      [152, 686],
      [134, 702],
      [122, 718]
    ],
    [
      [195, 742],
      [172, 756],
      [152, 766],
      [138, 762]
    ],
    [
      [882, 514],
      [902, 502],
      [918, 492],
      [930, 488]
    ],
    [
      [895, 726],
      [916, 738],
      [934, 746],
      [946, 742]
    ]
  ];

  for (let pts of looseStrings) {
    brush.set("rotring", PAL.amber[2], 0.38);
    brush.spline(
      pts.map((p) => [p[0], p[1] + 1.5]),
      0.5
    );
    brush.set("pen", PAL.milky[0], 0.5);
    brush.spline(pts, 0.5);
  }
}

function drawBruisedCutEnd() {
  // Left butt end (x ≈ 115..205, y ≈ 495..775):
  // Knife-cut root base, crescent petiole cross-sections, vascular bundle dots,
  // and oxidized rust-amber / sienna bruising inside the rectilinear facets.

  const cx = 150;
  const cy = 624;

  // 1. Central spongy pith core with radial cellular fissures & knife score lines
  brush.noStroke();
  brush.wash(PAL.milky[0], 110);
  brush.circle(cx, cy, 34, 0.15);
  brush.wash(PAL.buff[0], 85);
  brush.circle(cx + 6, cy + 4, 24, 0.2);
  brush.noWash();

  // Diagonal knife-cut striations across the flat cut crown
  brush.set("2H", PAL.amber[2], 0.35);
  for (let i = -38; i <= 38; i += 4.5) {
    const hSpan = sqrt(max(0, 42 * 42 - i * i));
    brush.line(cx - hSpan * 0.55, cy + i - 6, cx + hSpan * 0.55, cy + i + 6);
  }

  // Oxidized pith core ring and tiny radial cracks
  brush.set("rotring", PAL.bruiseRust, 0.48);
  for (let a = 0; a < 360; a += 24) {
    const r1 = 8 + (a % 48 === 0 ? 3 : 0);
    const r2 = 22 + sin(a * 3) * 4;
    brush.line(
      cx + cos(a) * r1,
      cy + sin(a) * r1 * 1.45,
      cx + cos(a) * r2,
      cy + sin(a) * r2 * 1.45
    );
  }

  // 2. Individual crescent-shaped cut stalk faces wrapping the root crown
  for (let s of stalks) {
    const p = getStalkProfile(s, s.x0);
    const sx = s.x0;
    const sy = p.y;
    const hw = p.hw * 0.88;

    // Pale fleshy inner crescent of the cut petiole
    const cPts = [
      [sx - 12, sy - hw],
      [sx - 22, sy - hw * 0.45],
      [sx - 24, sy],
      [sx - 21, sy + hw * 0.45],
      [sx - 10, sy + hw],
      [sx + 8, sy + hw * 0.72],
      [sx + 2, sy],
      [sx + 8, sy - hw * 0.72]
    ];

    brush.noStroke();
    brush.wash(PAL.milky[0], 105);
    brush.beginShape(0.35);
    for (let pt of cPts) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);

    // Bruised amber & rust oxidation wash along the cut rim
    brush.wash(PAL.bruiseAmber, 88);
    brush.beginShape(0.35);
    for (let pt of cPts) brush.vertex(pt[0] - 3, pt[1]);
    brush.endShape(true);
    brush.noWash();

    // Crisp oxidized outer crescent contour (burnt sienna & dark umber bruising)
    brush.set("rotring", PAL.bruiseRust, 0.65);
    brush.spline(cPts.slice(0, 6), 0.45);

    brush.set("pen", PAL.bruiseDark, 0.52);
    brush.spline(
      [
        [sx - 10, sy - hw * 0.85],
        [sx - 21, sy],
        [sx - 9, sy + hw * 0.85]
      ],
      0.45
    );

    // Hyperreal vascular bundle dots arranged along the crescent interior
    for (let k = -3; k <= 3; k++) {
      const vy = sy + (k / 3.5) * hw * 0.78;
      const vx = sx - 13 - (1 - pow(k / 3.5, 2)) * 6;
      brush.set("rotring", PAL.bruiseDark, 0.7);
      brush.circle(vx, vy, 1.6, 0.1);
      brush.set("pen", PAL.bruiseAmber, 0.45);
      brush.circle(vx + 1.2, vy, 2.4, 0.15);
    }

    // Longitudinal oxidized bruise streaks bleeding 15-35px into the stalk ribs
    brush.set("cpencil", PAL.bruiseRust, 0.5);
    for (let b = -2; b <= 2; b++) {
      const by = sy + b * (hw * 0.34);
      brush.line(sx - 6, by, sx + 18 + ((b * 7) % 14), by + b * 1.2);
    }
  }
}

function drawKnucklesAndFoliage() {
