  // 2. Crisp, angular, serrated trifoliate celery leaves (x ≈ 885..1105, y ≈ 435..785)
  const leafClusters = [
    { x: 915, y: 472, ang: -24, sc: 1.05, fam: "olive" },
    { x: 955, y: 452, ang: -16, sc: 0.95, fam: "chartreuse" },
    { x: 928, y: 518, ang: -12, sc: 1.12, fam: "chartreuse" },
    { x: 985, y: 495, ang: -8, sc: 1.08, fam: "amber" },
    { x: 1038, y: 478, ang: -5, sc: 0.92, fam: "olive" },
    { x: 942, y: 568, ang: -4, sc: 1.18, fam: "milky" },
