function drawSerratedCeleryLeaf(x, y, ang, sc, fam) {
  // Angular diamond-lobed celery leaflet with sharp marginal teeth and branching veins
  const f = getFacetAt(x, y);
  const rDx = f ? f.refDx * 0.7 : 0;
  const rDy = f ? f.refDy * 0.7 : 0;

  push();
  translate(x + rDx, y + rDy);
  rotate(ang);
  scale(sc);

  // Serrated trifoliate silhouette vertices
  const pts = [
    [0, 0],
    [12, -10],
    [10, -18],
    [24, -15],
    [22, -24],
    [38, -16],
    [44, -22],
    [56, -9],
    [66, 0],
    [56, 9],
    [44, 22],
    [38, 16],
    [22, 24],
    [24, 15],
    [10, 18],
    [12, 10]
  ];

  const fillCol =
    fam === "olive"
      ? PAL.olive[0]
      : fam === "amber"
      ? PAL.amber[0]
      : fam === "milky"
      ? PAL.milky[1]
      : fam === "buff"
      ? PAL.buff[0]
      : PAL.chartreuse[0];

  brush.noStroke();
  brush.wash(fillCol, 92);
  brush.beginShape(0.08);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Crisp serrated leaf margin in deep olive ink
  brush.set("rotring", PAL.leafDeep, 0.42);
  brush.beginShape(0.05);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(true);

  // Luminous central midrib and lateral veins to each tooth
  brush.set("pen", PAL.milky[0], 0.45);
  brush.line(0, 0, 62, 0);

  const veinTargets = [
    [12, 0, 23, -21],
    [26, 0, 42, -19],
    [40, 0, 54, -8],
    [12, 0, 23, 21],
    [26, 0, 42, 19],
    [40, 0, 54, 8]
  ];
  brush.set("2H", PAL.ribGlow, 0.35);
  for (let v of veinTargets) {
    brush.line(v[0], v[1], v[2], v[3]);
  }

  pop();
}

function drawTwineBindings() {
  // Two horizontal bundle ties at x = 355 and x = 745:
  // Multi-wrap twisted hemp twine compressing the celery stalks, with knots and frayed ends
  const tieStations = [
    { x: 355, knotY: 608, wraps: 4 },
    { x: 745, knotY: 622, wraps: 4 }
  ];

  for (let t of tieStations) {
    const env = getBundleEnvelope(t.x);
    const yTop = env.top + 3;
    const yBot = env.bot - 3;

    // 1. Cast shadow of the twine binding on the celery stalks to right and left
    brush.noStroke();
    brush.wash(PAL.bruiseDark, 68);
    brush.rect(t.x - 12, yTop, 26, yBot - yTop, "corner");
    brush.noWash();

    // 2. Individual vertical wraps of twisted 2-ply twine
    for (let w = 0; w < t.wraps; w++) {
      const wx = t.x - 7.5 + w * 5.0;

      // Base warm buff/amber cord
      brush.set("pen", PAL.twineMid, 0.95);
      brush.line(wx, yTop, wx, yBot);

      brush.set("rotring", PAL.twineDark, 0.5);
      brush.line(wx + 2.1, yTop, wx + 2.1, yBot);

      // Diagonal twist plies along the vertical cord
      for (let py = yTop + 4; py < yBot - 6; py += 6.5) {
        brush.set("pen", PAL.twineLight, 0.55);
        brush.line(wx - 1.8, py, wx + 1.8, py + 4.2);
        brush.set("rotring", PAL.twineDark, 0.38);
        brush.line(wx - 1.8, py + 4.2, wx + 1.8, py + 6.2);
      }
    }

    // 3. Tied butcher's knot and loose frayed hemp tails
    const kx = t.x;
    const ky = t.knotY;

    brush.noStroke();
    brush.wash(PAL.twineMid, 165);
    brush.circle(kx, ky, 9.5, 0.25);
    brush.noWash();

    brush.set("rotring", PAL.twineDark, 0.65);
    brush.circle(kx, ky, 9.5, 0.25);
    brush.set("pen", PAL.twineLight, 0.65);
    brush.arc(kx - 1, ky - 1, 6.5, 190, 350);

    // Two frayed twine tails curving outward from the knot
    const tail1 = [
      [kx, ky],
      [kx - 14, ky - 12],
      [kx - 28, ky - 19],
      [kx - 39, ky - 14]
    ];
    const tail2 = [
      [kx, ky],
      [kx + 16, ky + 14],
      [kx + 31, ky + 24],
      [kx + 44, ky + 29]
    ];

    for (let tail of [tail1, tail2]) {
      brush.set("rotring", PAL.twineDark, 0.65);
      brush.spline(
        tail.map((p) => [p[0], p[1] + 2]),
        0.5
      );
      brush.set("pen", PAL.twineMid, 0.85);
      brush.spline(tail, 0.5);
      brush.set("pen", PAL.twineLight, 0.5);
      brush.spline(
        tail.map((p) => [p[0], p[1] - 1]),
        0.5
      );
    }
  }
}

function drawWaterBeads() {
  // Hyperreal water beads clinging to the stalks inside the facets
  for (let b of waterBeads) {
    const f = getFacetAt(b.x, b.y);
