function drawFacetBevelsAndSheen() {
  // Subtle inner bevel highlights and diagonal glass refraction streaks inside the facets
  for (let i = 0; i < facets.length; i++) {
    const f = facets[i];

    // Inner top & left bevel catch-light (iridescent milky white)
    if (f.region !== "glass" || i % 2 === 0) {
      brush.set("pen", PAL.bevelLight, f.region !== "glass" ? 0.48 : 0.32);
      brush.line(f.x + 2, f.y + 2, f.x + f.w - 2, f.y + 2);
      brush.line(f.x + 2, f.y + 2, f.x + 2, f.y + f.h - 2);
    }

    // Inner bottom & right leaded glass shadow edge
    if (f.region !== "glass") {
      brush.set("2H", PAL.shadowSlate, 0.34);
      brush.line(f.x + 2, f.y + f.h - 2, f.x + f.w - 2, f.y + f.h - 2);
      brush.line(f.x + f.w - 2, f.y + 2, f.x + f.w - 2, f.y + f.h - 2);
    }

    // Occasional diagonal milky-white glass sheen across facets
    if (f.w > 26 && f.h >= 20 && (f.row * 5 + f.col * 3) % 7 === 0) {
      brush.set("2H", PAL.bevelLight, 0.35);
      const sx1 = f.x + 6;
      const sy1 = f.y + f.h - 4;
      const sx2 = f.x + min(f.w - 6, f.h * 0.9);
      const sy2 = f.y + 4;
      brush.line(sx1, sy1, sx2, sy2);
      brush.line(sx1 + 4, sy1, sx2 + 4, sy2);
    }
  }
}

function drawBottomSquareBorderDetails() {
