    if (isBundleFacet && (f.row + f.col) % 2 === 0) {
      brush.set("pen", PAL.inkBlack, 0.7);
      brush.line(f.x - 1.5, f.y, f.x + 1.5, f.y);
      brush.line(f.x, f.y - 1.5, f.x, f.y + 1.5);
    }
