    const isMajorRail =
      y === 196 ||
      y === 232 ||
      y === 382 ||
      y === 600 ||
      y === 830 ||
      y === 932 ||
      y === 944 ||
      y === 980 ||
      y === 992;

    brush.set("rotring", PAL.inkBlack, isMajorRail ? 0.82 : 0.54);
    brush.line(56, y, 1144, y);

    // Double-line lead came profile on primary structural horizontals
    if (isMajorRail) {
      brush.set("rotring", PAL.inkBlack, 0.42);
