  // Each finger has: tip (x,y), base (x,y), curvature offset, base radius, meniscus distance from tip, nail specs
  fingers = [
    {
      name: "thumb",
      tip: { x: 548, y: 365 },
      mid: { x: 695, y: 265 },
      base: { x: 920, y: 155 },
      radius: 46,
      meniscusT: 0.34, // fraction from tip to base submerged
      nailLen: 72,
      nailWidthRatio: 0.66,
      nailTilt: -14,
      chipped: false,
      isThumb: true
    },
    {
      name: "index",
      tip: { x: 438, y: 508 },
      mid: { x: 665, y: 342 },
      base: { x: 985, y: 125 },
      radius: 49,
      meniscusT: 0.52,
      nailLen: 88,
      nailWidthRatio: 0.72,
      nailTilt: 0,
      chipped: "minor", // small lateral edge nick
      isThumb: false
    },
    {
      name: "middle",
      tip: { x: 406, y: 644 },
      mid: { x: 682, y: 446 },
      base: { x: 1045, y: 205 },
      radius: 53,
      meniscusT: 0.56,
      nailLen: 96,
      nailWidthRatio: 0.74,
      nailTilt: 0,
      chipped: "major", // prominent hyperreal stepped chip on distal free edge
      isThumb: false
    },
    {
      name: "ring",
      tip: { x: 498, y: 762 },
      mid: { x: 755, y: 562 },
      base: { x: 1105, y: 310 },
      radius: 48,
      meniscusT: 0.50,
      nailLen: 86,
      nailWidthRatio: 0.71,
      nailTilt: 0,
      chipped: false,
      isThumb: false
    },
    {
      name: "pinky",
      tip: { x: 636, y: 838 },
      mid: { x: 848, y: 672 },
      base: { x: 1145, y: 435 },
      radius: 41,
      meniscusT: 0.42,
      nailLen: 70,
      nailWidthRatio: 0.68,
      nailTilt: 0,
      chipped: false,
      isThumb: false
    }
  ];

  // Precompute spine samples for each finger
  for (let f of fingers) {
    f.spine = [];
    let steps = 40;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = evalQuadBezier(f.tip, f.mid, f.base, t);
      let tan = evalQuadTangent(f.tip, f.mid, f.base, t);
      let len = Math.hypot(tan.x, tan.y) || 1;
      let tx = tan.x / len;
      let ty = tan.y / len;
      // Normal pointing toward upper-left (illuminated radial side)
      let nx = ty;
      let ny = -tx;
      f.spine.push({ t, x: p.x, y: p.y, tx, ty, nx, ny });
    }
  }
}

function evalQuadBezier(p0, p1, p2, t) {
  let u = 1 - t;
  return {
    x: u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x,
    y: u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y
  };
}

function evalQuadTangent(p0, p1, p2, t) {
  let u = 1 - t;
  return {
    x: 2 * u * (p1.x - p0.x) + 2 * t * (p2.x - p1.x),
    y: 2 * u * (p1.y - p0.y) + 2 * t * (p2.y - p1.y)
  };
}

// Anatomical finger half-width profile along parameter t in [0..1] (0 = tip, 1 = base)
function fingerProfileWidth(f, t) {
  if (t <= 0) return 0;
  // Rounded parabolic fingertip pad
  let tipCap = t < 0.14 ? Math.pow(t / 0.14, 0.56) : 1.0;
  // Subtle swell at DIP joint (t ~ 0.24) and PIP joint (t ~ 0.56)
  let dipSwell = 0.045 * Math.exp(-Math.pow((t - 0.24) / 0.08, 2));
  let shaftWaist = -0.035 * Math.exp(-Math.pow((t - 0.39) / 0.09, 2));
  let pipSwell = 0.075 * Math.exp(-Math.pow((t - 0.56) / 0.11, 2));
  let baseTaper = 0.06 * t;
  return f.radius * tipCap * (0.94 + dipSwell + shaftWaist + pipSwell + baseTaper);
}

// Get 2D point on finger in local coordinates:
// t in [0..1] along spine, u in [-1..1] across width (-1 = upper-left lit side, +1 = lower-right shadow side)
// Includes subtle Snell's law water refraction offset for submerged portion (t < meniscusT)
function fingerPoint(f, t, u, applyRefraction = true) {
  t = constrain(t, 0, 1);
  let idx = t * (f.spine.length - 1);
  let i0 = Math.floor(idx);
  let i1 = Math.min(f.spine.length - 1, i0 + 1);
  let frac = idx - i0;
  let s0 = f.spine[i0];
  let s1 = f.spine[i1];

  let sx = lerp(s0.x, s1.x, frac);
  let sy = lerp(s0.y, s1.y, frac);
  let nx = lerp(s0.nx, s1.nx, frac);
  let ny = lerp(s0.ny, s1.ny, frac);
  let tx = lerp(s0.tx, s1.tx, frac);
  let ty = lerp(s0.ty, s1.ty, frac);

  let w = fingerProfileWidth(f, t);

  // Subtle refractive expansion and shift underwater
  let refractShiftX = 0;
  let refractShiftY = 0;
  if (applyRefraction && t < f.meniscusT) {
    let subDepth = constrain((f.meniscusT - t) / f.meniscusT, 0, 1);
    let smoothStep = subDepth * subDepth * (3 - 2 * subDepth);
    w *= 1 + 0.045 * smoothStep;
    refractShiftX = -4.5 * smoothStep;
    refractShiftY = 3.5 * smoothStep;
  }

  return {
    x: sx + nx * (u * w) + refractShiftX,
    y: sy + ny * (u * w) + refractShiftY,
    nx,
    ny,
    tx,
    ty,
    w
  };
}

// ============================================================================
// WAVE FIELD, MARBLING DRIFT & TILE REFRACTION MATH
// ============================================================================

const TILE_SIZE = 136;
const TILE_ANGLE = 7.5; // degrees

function toTileSpace(x, y) {
  let cx = 600, cy = 600;
  let dx = x - cx, dy = y - cy;
  let c = Math.cos((TILE_ANGLE * Math.PI) / 180);
  let s = Math.sin((TILE_ANGLE * Math.PI) / 180);
  return {
    u: dx * c + dy * s + 600,
    v: -dx * s + dy * c + 600
  };
}

function fromTileSpace(u, v) {
  let du = u - 600, dv = v - 600;
  let c = Math.cos((TILE_ANGLE * Math.PI) / 180);
  let s = Math.sin((TILE_ANGLE * Math.PI) / 180);
  return {
    x: du * c - dv * s + 600,
    y: du * s + dv * c + 600
  };
}

// Smooth minimum for blending multi-finger distance fields
function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

// Distance from point (x,y) to segment (ax,ay)-(bx,by)
function distToSegment(x, y, ax, ay, bx, by) {
  let vx = bx - ax, vy = by - ay;
  let wx = x - ax, wy = y - ay;
  let c1 = vx * wx + vy * wy;
  if (c1 <= 0) return Math.hypot(x - ax, y - ay);
  let c2 = vx * vx + vy * vy;
  if (c2 <= c1) return Math.hypot(x - bx, y - by);
  let b = c1 / c2;
  let px = ax + b * vx, py = ay + b * vy;
  return Math.hypot(x - px, y - py);
}

// Core distance to the submerged entry zones of the 5 fingertips
function rawEntryDistance(x, y) {
  let dMin = 1e9;
  for (let i = 0; i < fingers.length; i++) {
    let f = fingers[i];
    // Entry segment runs from fingertip (t=0.03) to meniscus (t=meniscusT)
    let p0 = fingerPoint(f, 0.04, 0, true);
    let p1 = fingerPoint(f, f.meniscusT, 0, true);
    let segD = distToSegment(x, y, p0.x, p0.y, p1.x, p1.y) - f.radius * 0.82;
    if (i === 0) {
      dMin = segD;
    } else {
      dMin = smin(dMin, segD, 38);
    }
  }
  // Blend smoothly at larger distances into an elliptical radial wave field
  // so outer concentric rings expand meditatively across the entire canvas
  let globalDx = (x - 555) * 0.94;
  let globalDy = (y - 590) * 0.98;
  let globalD = Math.hypot(globalDx, globalDy) - 185;
  let blend = constrain((dMin - 20) / 280, 0, 1);
  blend = blend * blend * (3 - 2 * blend);
  return lerp(dMin, smin(dMin, globalD, 90), blend * 0.55);
}

// Floating-ink marbling distortion (Suminagashi advection) + submerged tile refraction
function evaluateWaveScalarField(x, y) {
  let baseD = rawEntryDistance(x, y);

  // Marbling drift ramps up smoothly outside the immediate finger meniscus
  let driftMask = constrain((baseD + 15) / 140, 0, 1);
  driftMask = driftMask * driftMask * (3 - 2 * driftMask);

  // Multi-octave curl-like marbling distortion
  let n1 = noise(x * 0.0022 + 11.3, y * 0.0022 + 7.1) - 0.5;
  let n2 = noise(x * 0.0022 + 37.9, y * 0.0022 + 23.4) - 0.5;
  let n3 = noise(x * 0.0058 + n1 * 1.8, y * 0.0058 + n2 * 1.8) - 0.5;
  let n4 = noise(x * 0.012 - n2 * 1.4, y * 0.012 + n1 * 1.4) - 0.5;

  let marbleShift = driftMask * (n1 * 68 + n3 * 34 + n4 * 13);

  // Angular floating-ink billowing lobes
  let ang = Math.atan2(y - 585, x - 545);
  let lobeWave =
    driftMask *
    (14 * Math.sin(ang * 3 + n1 * 4.5) +
      8 * Math.cos(ang * 5 - n2 * 5.0) +
      4.5 * Math.sin(ang * 9 + n3 * 6.0));

  // Tile refraction perturbation: rings bend where the submerged tiles & grout refract
  let ts = toTileSpace(x, y);
  let uMod = ((ts.u % TILE_SIZE) + TILE_SIZE) % TILE_SIZE;
  let vMod = ((ts.v % TILE_SIZE) + TILE_SIZE) % TILE_SIZE;

  // Distance to nearest tile grout seam in u and v
  let duGrout = Math.min(uMod, TILE_SIZE - uMod);
  let dvGrout = Math.min(vMod, TILE_SIZE - vMod);

  // Sharp optical step across tile grout lines + smooth pillow lens distortion across tile glaze
  let groutBendU = Math.exp(-(duGrout * duGrout) / 72);
  let groutBendV = Math.exp(-(dvGrout * dvGrout) / 72);
  let pillowRefract =
    Math.sin((uMod / TILE_SIZE) * Math.PI * 2) *
    Math.sin((vMod / TILE_SIZE) * Math.PI * 2);

  let tileRefraction =
    (groutBendU * 5.8 - groutBendV * 5.2 + pillowRefract * 3.8) *
    constrain((baseD + 25) / 60, 0.25, 1.0);

  return baseD + marbleShift + lobeWave + tileRefraction;
}

// Displace a submerged point (x,y) by the surface water wave lens refraction
function refractSubmergedPoint(x, y) {
  let d = evaluateWaveScalarField(x, y);
  // Wave crests & troughs act as cylindrical lenses shifting apparent position of tiles beneath
  let wavePhase = d * 0.24;
  let dWave = Math.cos(wavePhase) * 6.5 + Math.sin(wavePhase * 2.3) * 2.8;
  // Radial gradient direction away from entry center
  let gx = x - 545;
  let gy = y - 585;
  let glen = Math.hypot(gx, gy) || 1;
  gx /= glen;
  gy /= glen;

  // Attenuate slightly very far from center
  let amp = constrain(1.15 - glen / 1150, 0.45, 1.1);
  return {
    x: x + gx * dWave * amp,
    y: y + gy * dWave * amp
  };
}

// Check if a point (x,y) is occluded by the ABOVE-WATER portion of the hand
function isOccludedByEmergentHand(x, y) {
  for (let f of fingers) {
    // Check spine from meniscusT - 0.03 to 1.0
    for (let i = 0; i < f.spine.length; i++) {
      let sp = f.spine[i];
      if (sp.t < f.meniscusT - 0.02) continue;
      let w = fingerProfileWidth(f, sp.t) * 0.96;
      let dx = x - sp.x;
      let dy = y - sp.y;
      if (dx * dx + dy * dy < w * w) return true;
    }
  }
  // Dorsal hand web / metacarpal mass in upper-right corner
  let handPoly = [
    { x: 735, y: 245 },
    { x: 695, y: 350 },
    { x: 715, y: 465 },
    { x: 775, y: 575 },
    { x: 860, y: 675 },
    { x: 1230, y: 450 },
    { x: 1230, y: 60 },
    { x: 910, y: 125 }
  ];
  if (pointInPoly(x, y, handPoly)) return true;
  return false;
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i].x, yi = poly[i].y;
    let xj = poly[j].x, yj = poly[j].y;
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

// ============================================================================
// MARCHING SQUARES CONTINUOUS CONTOUR EXTRACTOR
// ============================================================================

let fieldGrid = null;
const GRID_NX = 220;
const GRID_NY = 220;
const GRID_MIN = -15;
const GRID_MAX = 1215;

function buildScalarFieldGrid() {
  fieldGrid = new Float32Array((GRID_NX + 1) * (GRID_NY + 1));
  let stepX = (GRID_MAX - GRID_MIN) / GRID_NX;
  let stepY = (GRID_MAX - GRID_MIN) / GRID_NY;

  for (let iy = 0; iy <= GRID_NY; iy++) {
    let y = GRID_MIN + iy * stepY;
    for (let ix = 0; ix <= GRID_NX; ix++) {
      let x = GRID_MIN + ix * stepX;
      fieldGrid[iy * (GRID_NX + 1) + ix] = evaluateWaveScalarField(x, y);
    }
  }
}

function extractIsoContours(isoVal) {
  let stepX = (GRID_MAX - GRID_MIN) / GRID_NX;
  let stepY = (GRID_MAX - GRID_MIN) / GRID_NY;
  let vOffset = (GRID_NY + 1) * GRID_NX;

  // Map from unique grid edge ID -> { x, y, neighbors: [] }
  let nodes = new Map();
  let segments = [];

  function getOrAddNode(edgeId, x, y) {
    let n = nodes.get(edgeId);
    if (!n) {
      n = { id: edgeId, x, y, adj: [] };
      nodes.set(edgeId, n);
    }
    return n;
  }

  function addSeg(idA, ax, ay, idB, bx, by) {
    if (idA === idB) return;
    let nA = getOrAddNode(idA, ax, ay);
    let nB = getOrAddNode(idB, bx, by);
    let segIdx = segments.length;
    segments.push({ a: nA, b: nB, used: false });
    nA.adj.push({ node: nB, segIdx });
    nB.adj.push({ node: nA, segIdx });
  }

  for (let iy = 0; iy < GRID_NY; iy++) {
    let y0 = GRID_MIN + iy * stepY;
    let y1 = y0 + stepY;
    let row0 = iy * (GRID_NX + 1);
    let row1 = (iy + 1) * (GRID_NX + 1);

    for (let ix = 0; ix < GRID_NX; ix++) {
      let v0 = fieldGrid[row0 + ix] - isoVal;     // TL
      let v1 = fieldGrid[row0 + ix + 1] - isoVal; // TR
      let v2 = fieldGrid[row1 + ix + 1] - isoVal; // BR
      let v3 = fieldGrid[row1 + ix] - isoVal;     // BL

      let mask = 0;
      if (v0 >= 0) mask |= 8;
      if (v1 >= 0) mask |= 4;
      if (v2 >= 0) mask |= 2;
      if (v3 >= 0) mask |= 1;
      if (mask === 0 || mask === 15) continue;

      let x0 = GRID_MIN + ix * stepX;
      let x1 = x0 + stepX;

      // Edge IDs:
      // Top (0): H(ix, iy), Right (1): V(ix+1, iy), Bottom (2): H(ix, iy+1), Left (3): V(ix, iy)
      let idTop = iy * GRID_NX + ix;
      let idBot = (iy + 1) * GRID_NX + ix;
      let idLeft = vOffset + iy * (GRID_NX + 1) + ix;
      let idRight = vOffset + iy * (GRID_NX + 1) + ix + 1;

      let tTop = v0 / (v0 - v1 + 1e-12);
      let tRight = v1 / (v1 - v2 + 1e-12);
      let tBot = v3 / (v3 - v2 + 1e-12);
      let tLeft = v0 / (v0 - v3 + 1e-12);

      let pTopX = x0 + constrain(tTop, 0, 1) * stepX, pTopY = y0;
      let pRightX = x1, pRightY = y0 + constrain(tRight, 0, 1) * stepY;
      let pBotX = x0 + constrain(tBot, 0, 1) * stepX, pBotY = y1;
      let pLeftX = x0, pLeftY = y0 + constrain(tLeft, 0, 1) * stepY;

      switch (mask) {
        case 1:
        case 14:
          addSeg(idLeft, pLeftX, pLeftY, idBot, pBotX, pBotY);
          break;
        case 2:
        case 13:
          addSeg(idBot, pBotX, pBotY, idRight, pRightX, pRightY);
          break;
        case 3:
        case 12:
          addSeg(idLeft, pLeftX, pLeftY, idRight, pRightX, pRightY);
          break;
        case 4:
        case 11:
          addSeg(idTop, pTopX, pTopY, idRight, pRightX, pRightY);
          break;
        case 6:
        case 9:
          addSeg(idTop, pTopX, pTopY, idBot, pBotX, pBotY);
          break;
        case 7:
        case 8:
          addSeg(idLeft, pLeftX, pLeftY, idTop, pTopX, pTopY);
          break;
        case 5:
        case 10: {
          let centerVal = 0.25 * (v0 + v1 + v2 + v3);
          if ((mask === 5 && centerVal >= 0) || (mask === 10 && centerVal < 0)) {
            addSeg(idLeft, pLeftX, pLeftY, idTop, pTopX, pTopY);
            addSeg(idBot, pBotX, pBotY, idRight, pRightX, pRightY);
          } else {
            addSeg(idLeft, pLeftX, pLeftY, idBot, pBotX, pBotY);
            addSeg(idTop, pTopX, pTopY, idRight, pRightX, pRightY);
          }
          break;
        }
      }
    }
  }

  // Chain segments into continuous polylines
  let polylines = [];

  function traceFrom(startNode) {
    let pts = [{ x: startNode.x, y: startNode.y }];
    let curr = startNode;
    while (true) {
      let nextStep = null;
      for (let edge of curr.adj) {
        if (!segments[edge.segIdx].used) {
          nextStep = edge;
          break;
        }
      }
      if (!nextStep) break;
      segments[nextStep.segIdx].used = true;
      curr = nextStep.node;
      pts.push({ x: curr.x, y: curr.y });
    }
    return pts;
  }

  // First trace open paths starting at degree-1 boundary nodes
  for (let n of nodes.values()) {
    if (n.adj.length === 1) {
      let seg = segments[n.adj[0].segIdx];
      if (!seg.used) {
        let poly = traceFrom(n);
        if (poly.length >= 3) polylines.push(poly);
      }
    }
  }

  // Then trace closed internal loops
  for (let n of nodes.values()) {
    for (let edge of n.adj) {
      if (!segments[edge.segIdx].used) {
        let poly = traceFrom(n);
        if (poly.length >= 4) polylines.push(poly);
      }
    }
  }

  return polylines;
}

// Split a polyline around emergent hand occlusion and subsample for smooth brush.spline
function clipAndSubsamplePolyline(pts, stepDist = 14) {
  let visibleRuns = [];
  let currentRun = [];

  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!isOccludedByEmergentHand(p.x, p.y)) {
      currentRun.push(p);
    } else {
      if (currentRun.length >= 4) visibleRuns.push(currentRun);
      currentRun = [];
    }
  }
  if (currentRun.length >= 4) visibleRuns.push(currentRun);

  let result = [];
  for (let run of visibleRuns) {
    // Smooth pass
    let smoothed = [run[0]];
    for (let i = 1; i < run.length - 1; i++) {
      smoothed.push({
        x: 0.25 * run[i - 1].x + 0.5 * run[i].x + 0.25 * run[i + 1].x,
        y: 0.25 * run[i - 1].y + 0.5 * run[i].y + 0.25 * run[i + 1].y
      });
    }
    smoothed.push(run[run.length - 1]);

    // Subsample by arc length
    let sub = [[smoothed[0].x, smoothed[0].y]];
    let acc = 0;
    for (let i = 1; i < smoothed.length; i++) {
      let d = Math.hypot(
        smoothed[i].x - smoothed[i - 1].x,
        smoothed[i].y - smoothed[i - 1].y
      );
      acc += d;
      if (acc >= stepDist || i === smoothed.length - 1) {
        sub.push([smoothed[i].x, smoothed[i].y]);
        acc = 0;
      }
    }
    if (sub.length >= 3) {
      // Ensure last two points aren't too close for spline
      let n = sub.length;
      if (
        n > 3 &&
        Math.hypot(sub[n - 1][0] - sub[n - 2][0], sub[n - 1][1] - sub[n - 2][1]) < 4
      ) {
        sub.splice(n - 2, 1);
      }
      result.push(sub);
    }
  }
  return result;
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  brush.clip([0, 0, width, height]);

  // 1. Base dusky twilight water paper ground
  background("#c2ccd8");

  // 2. Build scalar wave & marbling field
  buildScalarFieldGrid();

  // 3. Draw full-bleed submerged ceramic tiles with wave-refracted geometry
  drawSubmergedRefractedTiles();

  // 4. Draw atmospheric twilight water washes & suminagashi marbling tonal bands
  drawTwilightWaterAtmosphere();

  // 5. Draw dense concentric watercolour rings (indigo, soft carbon grey, thin rust red)
  drawConcentricMarblingRings();

  // 6. Render the hyperreal coloured-pencil hand & submerged fingertips
  drawHyperrealHand();

  // 7. Draw surface meniscus rings, overlapping capillary ripples & trapped air beads
  drawMeniscusAndAirBeads();

  brush.noClip();
  noLoop();
}

// ============================================================================
// LAYER 1: SUBMERGED REFRACTED BATH TILES (FULL-BLEED)
// ============================================================================

function drawSubmergedRefractedTiles() {
  brush.noStroke();

  // Group tiles into 4 dusky twilight palette buckets for fast fill batching
  const tilePalettes = [
    { col: "#25344b", alpha: 115 },
    { col: "#1d2b3f", alpha: 125 },
    { col: "#2d3d56", alpha: 105 },
    { col: "#34445c", alpha: 98 }
  ];

  let batches = [[], [], [], []];

  for (let iv = -2; iv <= 10; iv++) {
    for (let iu = -2; iu <= 10; iu++) {
      let u0 = iu * TILE_SIZE + 5;
      let v0 = iv * TILE_SIZE + 5;
      let u1 = (iu + 1) * TILE_SIZE - 5;
      let v1 = (iv + 1) * TILE_SIZE - 5;

      // Sample points along the 4 edges of the tile in tile-space and refract them
      let poly = [];
      let edgeSteps = 5;
      // Top edge
      for (let s = 0; s < edgeSteps; s++) {
        let p = fromTileSpace(lerp(u0, u1, s / edgeSteps), v0);
        poly.push(refractSubmergedPoint(p.x, p.y));
      }
      // Right edge
      for (let s = 0; s < edgeSteps; s++) {
        let p = fromTileSpace(u1, lerp(v0, v1, s / edgeSteps));
        poly.push(refractSubmergedPoint(p.x, p.y));
      }
      // Bottom edge
      for (let s = 0; s < edgeSteps; s++) {
        let p = fromTileSpace(lerp(u1, u0, s / edgeSteps), v1);
        poly.push(refractSubmergedPoint(p.x, p.y));
      }
      // Left edge
      for (let s = 0; s < edgeSteps; s++) {
        let p = fromTileSpace(u0, lerp(v1, v0, s / edgeSteps));
        poly.push(refractSubmergedPoint(p.x, p.y));
      }

      let bucketIdx = Math.abs((iu * 7 + iv * 13) % 4);
      batches[bucketIdx].push(poly);
    }
  }

  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.32);

  for (let b = 0; b < batches.length; b++) {
    brush.fill(tilePalettes[b].col, tilePalettes[b].alpha);
    for (let poly of batches[b]) {
      brush.beginShape(0.15);
      for (let pt of poly) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();

  // Draw refracted submerged tile grout lines & subtle bevel glints
  for (let i = -1; i <= 10; i++) {
    let coord = i * TILE_SIZE;

    // Horizontal tile grout line in tile space
    let hPts = [];
    let hGlint = [];
    for (let s = -100; s <= 1300; s += 24) {
      let p = fromTileSpace(s, coord);
      let rp = refractSubmergedPoint(p.x, p.y);
      hPts.push([rp.x, rp.y]);
      hGlint.push([rp.x + 2.5, rp.y - 2.5]);
    }
    brush.set("wc_bleed_halo", "#141e2e", 1.15);
    brush.spline(hPts, 0.4);
    brush.set("wc_fine", "#8fa3ba", 0.55);
    brush.spline(hGlint, 0.4);

    // Vertical tile grout line in tile space
    let vPts = [];
    let vGlint = [];
    for (let s = -100; s <= 1300; s += 24) {
      let p = fromTileSpace(coord, s);
      let rp = refractSubmergedPoint(p.x, p.y);
      vPts.push([rp.x, rp.y]);
      vGlint.push([rp.x - 2.5, rp.y + 2.5]);
    }
    brush.set("wc_bleed_halo", "#141e2e", 1.15);
    brush.spline(vPts, 0.4);
    brush.set("wc_fine", "#8fa3ba", 0.55);
    brush.spline(vGlint, 0.4);
  }
}

// ============================================================================
// LAYER 2: DUSKY TWILIGHT WATER ATMOSPHERE & CAUSTIC WASHES
// ============================================================================

function drawTwilightWaterAtmosphere() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
