  // Deep twilight vignette & bathwater depth washes at canvas corners/edges
  const cornerWashes = [
    { x: 0, y: 0, w: 650, h: 520, col: "#1a273d", alpha: 72 },
    { x: 580, y: 0, w: 620, h: 480, col: "#222e42", alpha: 65 },
    { x: 0, y: 650, w: 620, h: 550, col: "#172338", alpha: 78 },
    { x: 560, y: 680, w: 640, h: 520, col: "#1d283b", alpha: 74 }
  ];

  for (let cw of cornerWashes) {
    brush.fill(cw.col, cw.alpha);
    brush.rect(cw.x, cw.y, cw.w, cw.h, "corner");
