  brush.noFill();
}

// ============================================================================
// LAYER 3: DENSE CONCENTRIC WATERCOLOUR MARBLING RINGS
// ============================================================================

function drawConcentricMarblingRings() {
  // Generate dense iso-contours from inside the meniscus all the way to the corners (full-bleed)
  // Spacing tightens near the fingers and modulates rhythmically like suminagashi bands
  let isoValues = [];
  let currIso = -16;
  let ringIdx = 0;

  while (currIso < 1020) {
    isoValues.push({ val: currIso, idx: ringIdx });
    // Suminagashi rhythmic spacing: tight doublets/triplets alternating with slightly wider breaths
    let baseStep = map(currIso, -16, 1020, 5.2, 11.2, true);
    let bandMod = 0.72 + 0.45 * Math.pow(Math.sin(ringIdx * 0.42), 2);
    currIso += baseStep * bandMod;
    ringIdx++;
  }

  // Palettes for the three specified watercolour line media:
  // 1) Indigo, 2) Soft carbon grey, 3) Thin rust red
  const indigoTones = ["#142442", "#1d335c", "#264170", "#101d36", "#2b4878"];
  const carbonTones = ["#353b45", "#484f59", "#58606b", "#2a2f37", "#646c78"];
  const rustTones = ["#8c3726", "#a34330", "#782c1e", "#993d2b"];

  for (let item of isoValues) {
    let { val, idx } = item;
    let rawPolys = extractIsoContours(val);

    // Determine ring medium & color according to a meditative marbling cadence
    let isRust = idx > 1 && (idx % 7 === 3 || idx % 17 === 0);
    let isIndigo = !isRust && (idx % 3 === 0 || idx % 5 === 1);

    let lineColor, haloColor, brushName, lineWeight;
    if (isRust) {
      lineColor = rustTones[idx % rustTones.length];
      haloColor = "#9e4736";
      brushName = "wc_rust";
      lineWeight = random(0.75, 1.05);
    } else if (isIndigo) {
      lineColor = indigoTones[idx % indigoTones.length];
      haloColor = "#20365e";
      brushName = "wc_fine";
      lineWeight = random(0.85, 1.32);
    } else {
      lineColor = carbonTones[idx % carbonTones.length];
      haloColor = "#434a54";
      brushName = "wc_fine";
      lineWeight = random(0.75, 1.18);
    }

    // Draw subtle wet watercolour bleed halo on every 3rd ring for authentic suminagashi ink diffusion
    let drawHalo = idx % 3 === 0 || isRust;

    for (let poly of rawPolys) {
      let runs = clipAndSubsamplePolyline(poly, 13);
      for (let run of runs) {
        if (run.length < 3) continue;

        if (drawHalo) {
          brush.set("wc_bleed_halo", haloColor, isRust ? 0.65 : 1.0);
          brush.spline(run, 0.45);
        }

        // Occasional delicate pale silver-sky crest highlight alongside principal indigo rings
        if (isIndigo && idx % 6 === 0 && val > 0) {
          let highlightRun = run.map((pt) => [pt[0] - 1.4, pt[1] - 1.4]);
          brush.set("wc_fine", "#c8d6e6", 0.55);
          brush.spline(highlightRun, 0.45);
        }

        brush.set(brushName, lineColor, lineWeight);
        brush.spline(run, 0.45);
      }
    }
  }
}

// ============================================================================
// LAYER 4: HYPERREAL COLOURED-PENCIL HAND & FINGERTIPS
// ============================================================================

function drawHyperrealHand() {
  // 1. Dorsal hand web / metacarpal base entering from upper-right edge
  drawDorsalHandBase();

  // 2. Render each finger from pinky to thumb so overlapping light/shadow reads naturally
  const drawOrder = [4, 3, 2, 1, 0];
  for (let fi of drawOrder) {
    drawSingleFingerHyperreal(fingers[fi]);
  }
}

function drawDorsalHandBase() {
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.25);

  // Base warm twilight flesh wash for upper-right dorsal hand
  brush.fill("#b89588", 165);
  brush.beginShape(0.2);
  brush.vertex(700, 255);
  brush.vertex(665, 345);
  brush.vertex(685, 455);
  brush.vertex(755, 565);
  brush.vertex(850, 675);
  brush.vertex(1220, 440);
  brush.vertex(1220, 60);
  brush.vertex(915, 135);
  brush.endShape(true);

  // Deeper dusky plum-umber shadow toward lower-right ulnar side of hand
  brush.fill("#5c4447", 140);
  brush.beginShape(0.25);
  brush.vertex(750, 480);
  brush.vertex(845, 675);
  brush.vertex(1220, 445);
  brush.vertex(1220, 220);
  brush.vertex(935, 340);
  brush.endShape(true);

  brush.noFill();

  // Coloured-pencil cross-contour & tendon shading on dorsal hand
  for (let i = 1; i < fingers.length; i++) {
    let f = fingers[i];
    // Inter-digital web shadow between finger bases
    let fPrev = fingers[i - 1];
    let pA = fingerPoint(f, 0.72, -0.85, false);
    let pB = fingerPoint(fPrev, 0.72, 0.85, false);
    let midX = 0.5 * (pA.x + pB.x) + 18;
    let midY = 0.5 * (pA.y + pB.y) - 12;

    for (let k = 0; k < 14; k++) {
      let off = map(k, 0, 13, -12, 12);
      brush.set("cp_soft", k < 7 ? "#4a3438" : "#705356", 0.9);
      brush.spline(
        [
          [pA.x + off * 0.4, pA.y + off * 0.4],
          [midX + off, midY + off * 0.6],
          [pB.x + off * 0.4, pB.y - off * 0.3]
        ],
        0.45
      );
    }

    // Subtle dorsal tendon highlight lines extending back toward wrist
    for (let s = 0; s < 18; s++) {
      let u = random(-0.45, 0.25);
      let pt1 = fingerPoint(f, random(0.68, 0.82), u, false);
      let pt2 = fingerPoint(f, random(0.88, 1.0), u + random(-0.08, 0.08), false);
      let col = u < -0.1 ? "#dec3b6" : "#9c7c73";
      brush.set("cp_micro", col, random(0.7, 1.1));
      brush.line(pt1.x, pt1.y, pt2.x, pt2.y);
    }
  }
}

function drawSingleFingerHyperreal(f) {
  // --- STEP A: UNDER-PAINTING WASHES (SEPARATE SUBMERGED vs EMERGENT PALETTE) ---
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.45, 0.2);

  // 1. Emergent finger portion (above water meniscus, t in [meniscusT..1.0])
  let emergentPoly = buildFingerZonePolygon(f, f.meniscusT - 0.02, 1.0, -1.0, 1.0);
  brush. wash("#c9a99c", 220);
  drawBrushShape(emergentPoly, 0.15);
  brush.noWash();

  // Emergent core shadow along lower-right ulnar side (u in [0.15..0.92])
  let emergentShadow = buildFingerZonePolygon(f, f.meniscusT - 0.02, 1.0, 0.12, 0.94);
  brush.fill("#6e5052", 145);
  drawBrushShape(emergentShadow, 0.15);

  // Emergent sunlit dorsal ridge along upper-left radial side (u in [-0.85..-0.15])
  let emergentLit = buildFingerZonePolygon(f, f.meniscusT - 0.02, 1.0, -0.86, -0.12);
  brush.fill("#ead3c6", 125);
  drawBrushShape(emergentLit, 0.15);

  // 2. Submerged fingertip portion (beneath water meniscus, t in [0..meniscusT])
  // Tinted with cool twilight water refraction over warm dermal undertone
  let submergedPoly = buildFingerZonePolygon(f, 0.0, f.meniscusT + 0.01, -1.0, 1.0);
  brush.wash("#a89193", 215);
  drawBrushShape(submergedPoly, 0.18);
  brush.noWash();

  // Submerged cool slate-plum shadow along lower-right side
  let subShadow = buildFingerZonePolygon(f, 0.01, f.meniscusT, 0.1, 0.94);
  brush.fill("#48455c", 155);
  drawBrushShape(subShadow, 0.15);

  // Submerged luminous cool-peach dorsal highlight
  let subLit = buildFingerZonePolygon(f, 0.02, f.meniscusT, -0.85, -0.1);
  brush.fill("#d8c8c6", 130);
  drawBrushShape(subLit, 0.15);

  brush.noFill();

  // --- STEP B: DENSE COLOURED-PENCIL CROSS-CONTOUR & DERMAL TEXTURE ---
  drawFingerColouredPencilShading(f);

  // --- STEP C: WRINKLED SKIN (DIP JOINT, PIP JOINT & WATER-PRUNED FINGERTIP SULCI) ---
  drawFingerWrinkles(f);

  // --- STEP D: HYPERREAL FINGERNAIL & CHIPPED NAIL DETAIL ---
  drawHyperrealFingernail(f);

  // --- STEP E: CRISP CONTOUR DEFINITION & REFLECTED RIM LIGHT ---
  drawFingerEdgeDefinition(f);
}

function buildFingerZonePolygon(f, tStart, tEnd, uMin, uMax) {
  let pts = [];
  let steps = 16;
  for (let i = 0; i <= steps; i++) {
    let t = lerp(tStart, tEnd, i / steps);
    pts.push(fingerPoint(f, t, uMin, true));
  }
  for (let i = steps; i >= 0; i--) {
    let t = lerp(tStart, tEnd, i / steps);
    pts.push(fingerPoint(f, t, uMax, true));
  }
  return pts;
}

function drawBrushShape(pts, curv = 0.2) {
  brush.beginShape(curv);
  for (let p of pts) {
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

function drawFingerColouredPencilShading(f) {
  // 1. Cross-contour cylindrical coloured-pencil arches along the finger length
  let numContours = 95;
  for (let i = 0; i < numContours; i++) {
    let t = map(i, 0, numContours - 1, 0.03, 0.96);
    let isSub = t < f.meniscusT;

    // Draw 3 overlapping tonal arcs across u in [-0.95..0.95]
    // Lit side arc (-0.92 to -0.05)
    let litPts = [];
    for (let u = -0.92; u <= -0.02; u += 0.22) {
      let archT = t - 0.018 * (1 - u * u);
      let p = fingerPoint(f, archT, u, true);
      litPts.push([p.x, p.y]);
    }
    let litCol = isSub
      ? i % 2 === 0 ? "#e2d6d5" : "#c7b6ba"
      : i % 2 === 0 ? "#f0ddd2" : "#d9bcb0";
    brush.set("cp_micro", litCol, random(0.65, 1.0));
    brush.spline(litPts, 0.4);

    // Mid-tone dorsal transition arc (-0.25 to 0.45)
    let midPts = [];
    for (let u = -0.25; u <= 0.45; u += 0.22) {
      let archT = t - 0.02 * (1 - u * u);
      let p = fingerPoint(f, archT, u, true);
      midPts.push([p.x, p.y]);
    }
    let midCol = isSub
      ? i % 3 === 0 ? "#8a7580" : "#9c878d"
      : i % 3 === 0 ? "#ab847a" : "#bf9b8e";
    brush.set("cp_micro", midCol, random(0.7, 1.05));
    brush.spline(midPts, 0.4);

    // Shadow side arc (0.20 to 0.92)
    let shPts = [];
    for (let u = 0.2; u <= 0.92; u += 0.22) {
      let archT = t - 0.018 * (1 - u * u);
      let p = fingerPoint(f, archT, u, true);
      shPts.push([p.x, p.y]);
    }
    let shCol = isSub
      ? i % 2 === 0 ? "#3b3a52" : "#514a61"
      : i % 2 === 0 ? "#593e42" : "#735457";
    brush.set("cp_micro", shCol, random(0.75, 1.15));
    brush.spline(shPts, 0.4);
  }

  // 2. Fine rhomboid dermal micro-relief (tiny diagonal skin pore hatching)
  for (let i = 0; i < 65; i++) {
    let t = random(0.18, 0.88);
    let u = random(-0.75, 0.75);
    let isSub = t < f.meniscusT;
    let p1 = fingerPoint(f, t, u, true);
    let p2 = fingerPoint(f, t + random(-0.025, 0.025), u + random(-0.18, 0.18), true);
    let col = u < 0
      ? isSub ? "#b8a3a8" : "#cda99d"
      : isSub ? "#464259" : "#66484b";
    brush.set("cp_micro", col, 0.55);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

function drawFingerWrinkles(f) {
  // --- 1. DIP JOINT WRINKLES (Distal knuckle just behind nail base, t ~ 0.23..0.33) ---
  let dipCreases = [0.235, 0.252, 0.268, 0.285, 0.302, 0.318];
  for (let ci = 0; ci < dipCreases.length; ci++) {
    let tBase = dipCreases[ci];
    let isSub = tBase < f.meniscusT;
    let span = map(Math.abs(ci - 2.5), 0, 3, 0.78, 0.52);

    let creasePts = [];
    let ridgePts = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -span, span);
      // Elliptical bowing of knuckle folds + subtle organic wavering
      let bow = (ci < 3 ? -0.012 : 0.012) * (1 - (u / span) * (u / span));
      let wav = 0.003 * Math.sin(s * 1.9 + ci * 2.3);
      let pC = fingerPoint(f, tBase + bow + wav, u, true);
      let pR = fingerPoint(f, tBase + bow + wav - 0.0045, u, true);
      creasePts.push([pC.x, pC.y]);
      ridgePts.push([pR.x, pR.y]);
    }

    // Dark dermal sulcus (crevice)
    let darkCol = isSub ? "#2e2d42" : "#4a3035";
    brush.set("cp_micro", darkCol, random(0.85, 1.25));
    brush.spline(creasePts, 0.45);

    // Adjacent illuminated skin fold ridge
    let lightCol = isSub ? "#e3d9db" : "#f2dfd4";
    brush.set("cp_highlight", lightCol, random(0.65, 0.95));
    brush.spline(ridgePts, 0.45);
  }

  // --- 2. PIP JOINT WRINKLES (Middle knuckle concentric oval folds, t ~ 0.48..0.65) ---
  let pipLines = 11;
  for (let pi = 0; pi < pipLines; pi++) {
    let norm = map(pi, 0, pipLines - 1, -1, 1); // -1 = distal edge of knuckle, +1 = proximal edge
    let tCenter = 0.565 + norm * 0.072;
    let isSub = tCenter < f.meniscusT;
    let span = 0.84 * Math.sqrt(Math.max(0.15, 1 - norm * norm * 0.65));

    let creasePts = [];
    let ridgePts = [];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -span, span);
      // Concentric eye-shaped curvature around the knuckle pad
      let arch = -norm * 0.022 * (1 - (u / span) * (u / span));
      let microWobble = 0.0035 * Math.cos(s * 2.1 + pi * 1.7);
      let pC = fingerPoint(f, tCenter + arch + microWobble, u, true);
      let pR = fingerPoint(f, tCenter + arch + microWobble - 0.004, u, true);
      creasePts.push([pC.x, pC.y]);
      ridgePts.push([pR.x, pR.y]);
    }

    let darkCol = isSub ? "#333147" : "#4f3338";
    let midCol = isSub ? "#61566b" : "#87615c";
    brush.set("cp_soft", midCol, 0.7);
    brush.spline(creasePts, 0.45);
    brush.set("cp_micro", darkCol, random(0.85, 1.3));
    brush.spline(creasePts, 0.45);

    let lightCol = isSub ? "#dfd4d6" : "#f5e3d8";
    brush.set("cp_highlight", lightCol, random(0.6, 0.95));
    brush.spline(ridgePts, 0.45);
  }

  // Radial crow's-feet skin folds fanning out at the lateral edges of the PIP & DIP joints
  for (let side of [-1, 1]) {
    for (let k = 0; k < 7; k++) {
      let tJoint = 0.52 + k * 0.018;
      let p0 = fingerPoint(f, tJoint, side * 0.55, true);
      let p1 = fingerPoint(f, tJoint + (k - 3) * 0.008, side * 0.76, true);
      let p2 = fingerPoint(f, tJoint + (k - 3) * 0.016, side * 0.94, true);
      brush.set("cp_micro", side < 0 ? "#7a5852" : "#3d292e", 0.75);
      brush.spline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y]], 0.4);
    }
  }

  // --- 3. SUBMERGED WATER-PRUNED FINGERTIP WRINKLES (Distal pad & lateral nail folds) ---
  // Sinuous longitudinal & oblique wrinkles characteristic of bathwater-immersed skin
  let pruneCount = 16;
  for (let pw = 0; pw < pruneCount; pw++) {
    // Cluster around the fingertip pad (t in [0.01..0.14]) and lateral borders (|u| in [0.65..0.95])
    let isLateral = pw >= 8;
    let ptsDark = [];
    let ptsLight = [];

    if (!isLateral) {
      // Distal tip pad wrinkles curving around the parabolic tip in front of the nail
      let uStart = map(pw, 0, 7, -0.78, 0.78);
      for (let s = 0; s <= 5; s++) {
        let t = map(s, 0, 5, 0.008, 0.065);
        let u = uStart + 0.09 * Math.sin(s * 1.3 + pw);
        let pD = fingerPoint(f, t, u, true);
        let pL = fingerPoint(f, t, u - 0.04, true);
        ptsDark.push([pD.x, pD.y]);
        ptsLight.push([pL.x, pL.y]);
      }
    } else {
      // Lateral water-pruned skin folds flanking the fingernail
      let side = pw % 2 === 0 ? -1 : 1;
      let t0 = map(pw, 8, pruneCount - 1, 0.04, 0.20);
      for (let s = 0; s <= 5; s++) {
        let t = t0 + s * 0.018;
        let u = side * (0.72 + 0.06 * Math.sin(s * 1.5 + pw));
        let pD = fingerPoint(f, t, u, true);
        let pL = fingerPoint(f, t - 0.003, u - side * 0.035, true);
        ptsDark.push([pD.x, pD.y]);
        ptsLight.push([pL.x, pL.y]);
      }
    }

    brush.set("cp_micro", "#2c2d42", 0.95);
    brush.spline(ptsDark, 0.45);
    brush.set("cp_highlight", "#e4edf5", 0.8);
    brush.spline(ptsLight, 0.45);
  }
}

// ============================================================================
// HYPERREAL FINGERNAIL & CHIPPED NAIL ANATOMY
// ============================================================================

function drawHyperrealFingernail(f) {
  let tDistal = 0.022;
  let tProximal = 0.205;
  let uHalf = f.nailWidthRatio * 0.78;
  if (f.isThumb) uHalf *= 0.88;

  // Helper to map normalized nail coordinates (nt in [0..1] distal->proximal, nu in [-1..1] left->right)
  function nailPt(nt, nu) {
    // Round the proximal base (cuticle arc) and distal edge
    let uScale = 1.0;
    if (nt > 0.75) {
      let k = (nt - 0.75) / 0.25;
      uScale = Math.sqrt(Math.max(0.12, 1 - k * k * 0.55));
    } else if (nt < 0.15) {
      let k = (0.15 - nt) / 0.15;
      uScale = 1 - k * k * 0.12;
    }

    // Apply chipped notch deformation to distal edge if applicable
    let ntDeformed = nt;
    if (f.chipped === "major" && nt < 0.22) {
      // Prominent jagged V-stepped chip on the upper-left/center of the middle fingernail
      let chipDist = Math.abs(nu - -0.22);
      if (chipDist < 0.36) {
        let profile = 1 - chipDist / 0.36;
        // Stepped fracture contour
        let stepNotch =
          profile > 0.55 ? 0.165 : profile > 0.25 ? 0.095 : profile * 0.28;
        ntDeformed = Math.max(nt, stepNotch * (1 - nt * 2.5));
      }
    } else if (f.chipped === "minor" && nt < 0.16) {
      // Smaller corner chip on the index fingernail
      let chipDist = Math.abs(nu - 0.38);
      if (chipDist < 0.24) {
        let notch = (1 - chipDist / 0.24) * 0.11;
        ntDeformed = Math.max(nt, notch * (1 - nt * 3));
      }
    }

    let t = lerp(tDistal, tProximal, ntDeformed);
    let u = nu * uHalf * uScale + (f.isThumb ? -0.08 : 0);
    return fingerPoint(f, t, u, true);
  }

  // 1. Recessed shadow of lateral & proximal nail folds (periungual groove)
  let foldShadowPoly = [];
  for (let s = 0; s <= 16; s++) foldShadowPoly.push(nailPt(s / 16, -1.08));
  for (let s = -1; s <= 1; s += 0.25) foldShadowPoly.push(nailPt(1.04, s));
  for (let s = 16; s >= 0; s--) foldShadowPoly.push(nailPt(s / 16, 1.08));

  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fill("#362b3b", 155);
  drawBrushShape(foldShadowPoly, 0.15);

  // 2. Translucent rose-taupe nail bed wash
  let platePoly = [];
  for (let s = 0; s <= 16; s++) platePoly.push(nailPt(s / 16, -1.0));
  for (let s = -0.8; s <= 0.8; s += 0.25) platePoly.push(nailPt(1.0, s));
  for (let s = 16; s >= 0; s--) platePoly.push(nailPt(s / 16, 1.0));
  for (let s = 0.8; s >= -0.8; s -= 0.2) platePoly.push(nailPt(0.0, s));

  brush.wash("#b88e92", 215);
  drawBrushShape(platePoly, 0.12);
  brush.noWash();

  // Cylindrical shadow on right side of nail plate
  let rightShadePoly = [];
  for (let s = 0; s <= 12; s++) rightShadePoly.push(nailPt(s / 12, 0.15));
  for (let s = 12; s >= 0; s--) rightShadePoly.push(nailPt(s / 12, 1.0));
  brush.fill("#664f61", 130);
  drawBrushShape(rightShadePoly, 0.12);

  // 3. Pale crescent Lunula (half-moon at proximal nail base, nt in [0.74..0.98])
  let lunulaPoly = [];
  for (let s = -0.78; s <= 0.78; s += 0.15) {
    let archNt = 0.73 + 0.12 * (s * s);
    lunulaPoly.push(nailPt(archNt, s));
  }
  for (let s = 0.78; s >= -0.78; s -= 0.15) {
    lunulaPoly.push(nailPt(0.98, s));
  }
  brush.wash("#dfd9dc", 195);
  drawBrushShape(lunulaPoly, 0.2);
  brush.noWash();

  // 4. Distal Free Edge (pale keratin ivory tip, nt in [0.0..0.18])
  let freeEdgePoly = [];
  for (let s = -0.98; s <= 0.98; s += 0.1) freeEdgePoly.push(nailPt(0.0, s));
  for (let s = 0.98; s >= -0.98; s -= 0.1) {
    let innerNt = 0.16 + 0.05 * (s * s);
    freeEdgePoly.push(nailPt(innerNt, s));
  }
  brush.wash("#ddd5c9", 210);
  drawBrushShape(freeEdgePoly, 0.1);
  brush.noWash();
  brush.noFill();

  // Dark rose-umber Onychodermal band (where pink nail bed meets white free edge)
  let onychoPts = [];
  for (let s = -0.95; s <= 0.95; s += 0.15) {
    let p = nailPt(0.17 + 0.05 * (s * s), s);
    onychoPts.push([p.x, p.y]);
  }
  brush.set("cp_micro", "#5e3640", 1.05);
  brush.spline(onychoPts, 0.45);

  // 5. Longitudinal keratin striations (hyperreal coloured-pencil ridges along nail plate)
  let numRidges = 42;
  for (let r = 0; r < numRidges; r++) {
    let nu = map(r, 0, numRidges - 1, -0.94, 0.94);
    let rPts = [];
    for (let s = 0; s <= 6; s++) {
      let nt = s / 6;
      let p = nailPt(nt, nu);
      rPts.push([p.x, p.y]);
    }
    let ridgeCol;
    if (nu > -0.58 && nu < -0.15) {
      // Wet specular highlight band along left-center of nail plate
      ridgeCol = r % 2 === 0 ? "#f4f6fa" : "#e3d6d8";
    } else if (nu <= -0.58) {
      ridgeCol = r % 2 === 0 ? "#d1b2b6" : "#b08991";
    } else if (nu < 0.35) {
      ridgeCol = r % 2 === 0 ? "#c49da1" : "#9c747c";
    } else {
      ridgeCol = r % 2 === 0 ? "#735969" : "#564152";
    }
    brush.set("cp_micro", ridgeCol, random(0.55, 0.9));
    brush.spline(rPts, 0.3);
  }

  // 6. Cuticle (Eponychium) scalloped pale rim & micro-creases
  let cuticlePts = [];
  for (let s = -0.95; s <= 0.95; s += 0.12) {
    let p = nailPt(1.0, s);
    cuticlePts.push([p.x, p.y]);
    // Tiny vertical cuticle skin striae
    let pBack = nailPt(1.06, s);
    brush.set("cp_micro", s < 0 ? "#eadad2" : "#8c6d73", 0.65);
    brush.line(p.x, p.y, pBack.x, pBack.y);
  }
  brush.set("cp_highlight", "#ede3df", 0.9);
  brush.spline(cuticlePts, 0.4);

  // Deep shadow groove right around lateral & proximal nail borders
  for (let side of [-1, 1]) {
    let groovePts = [];
    let foldLitPts = [];
    for (let s = 0; s <= 8; s++) {
      let nt = s / 8;
      let pG = nailPt(nt, side * 1.01);
      let pF = nailPt(nt, side * 1.12);
      groovePts.push([pG.x, pG.y]);
      foldLitPts.push([pF.x, pF.y]);
    }
    brush.set("cp_micro", "#2b202e", 1.15);
    brush.spline(groovePts, 0.4);
    brush.set("cp_highlight", side < 0 ? "#f0e1d8" : "#8d8294", 0.8);
    brush.spline(foldLitPts, 0.4);
  }

  // 7. HERO DETAIL: THE CHIPPED NAIL (Stepped fracture, exposed nail bed & delaminated keratin)
  if (f.chipped === "major" || f.chipped === "minor") {
    let chipCenterNu = f.chipped === "major" ? -0.22 : 0.38;
    let chipSpan = f.chipped === "major" ? 0.35 : 0.22;

    // Raw exposed pink-crimson hyponychium / nail bed inside the chipped notch
    let exposedPoly = [];
    for (let s = -chipSpan; s <= chipSpan; s += 0.06) {
      let nu = chipCenterNu + s;
      let pInner = nailPt(0.0, nu); // deformed inward by notch
      exposedPoly.push(pInner);
    }
    for (let s = chipSpan; s >= -chipSpan; s -= 0.06) {
      let nu = chipCenterNu + s;
      // Undeformed outer contour where the nail used to be
      let t = lerp(tDistal, tProximal, 0.01);
      let u = nu * uHalf * 0.92;
      exposedPoly.push(fingerPoint(f, t, u, true));
    }
    brush.noStroke();
    brush.fill("#63333d", 195);
    drawBrushShape(exposedPoly, 0.05);
    brush.noFill();

    // Jagged white delaminated keratin fracture lines along the stepped chip edge
    let fractureEdge = [];
    let delamLayer = [];
    for (let s = -chipSpan * 1.15; s <= chipSpan * 1.15; s += 0.05) {
      let nu = chipCenterNu + s;
      let pE = nailPt(0.0, nu);
      let pD = nailPt(0.035, nu + 0.015 * Math.sin(s * 30));
      fractureEdge.push([pE.x, pE.y]);
      delamLayer.push([pD.x, pD.y]);
    }
    // Dark shadow under the broken keratin shelf
    brush.set("cp_micro", "#2c1820", 1.2);
    brush.spline(fractureEdge, 0.12);
    // Bright chalky-white peeled keratin layer
    brush.set("cp_highlight", "#ffffff", 1.15);
    brush.spline(delamLayer, 0.15);
    brush.set("cp_highlight", "#ebe6dc", 0.9);
    brush.spline(fractureEdge, 0.12);

    // Fine longitudinal stress cracks radiating slightly back from the chip corner
    if (f.chipped === "major") {
      let c1 = nailPt(0.0, chipCenterNu - 0.06);
      let c2 = nailPt(0.24, chipCenterNu - 0.04);
      brush.set("cp_micro", "#4a2e36", 0.75);
      brush.line(c1.x, c1.y, c2.x, c2.y);
      brush.set("cp_highlight", "#f7f4f0", 0.7);
      brush.line(c1.x + 1.2, c1.y - 0.8, c2.x + 1.2, c2.y - 0.8);
    }
  }

  // Distal free edge rim highlight on unchipped portions
  let distalRim = [];
  for (let s = -0.95; s <= 0.95; s += 0.08) {
    let p = nailPt(0.0, s);
    distalRim.push([p.x, p.y]);
  }
  brush.set("cp_highlight", "#f5f1e8", 0.85);
  brush.spline(distalRim, 0.2);
}

function drawFingerEdgeDefinition(f) {
  // Upper-left illuminated radial contour & lower-right shadowed + water-reflected ulnar contour
  let leftEdge = [];
  let rightEdge = [];
  let rightRim = [];

  for (let s = 0; s <= 24; s++) {
    let t = s / 24;
    let pL = fingerPoint(f, t, -0.98, true);
    let pR = fingerPoint(f, t, 0.98, true);
    let pRim = fingerPoint(f, t, 0.90, true);
    leftEdge.push([pL.x, pL.y]);
    rightEdge.push([pR.x, pR.y]);
    rightRim.push([pRim.x, pRim.y]);
  }

  // Crisp backlit highlight along upper-left edge
  brush.set("cp_highlight", "#f2e6dc", 0.9);
  brush.spline(leftEdge, 0.4);

  // Cool twilight water reflected light along lower-right rim
  brush.set("cp_soft", "#7c8fa6", 0.85);
  brush.spline(rightRim, 0.4);

  // Dark boundary crevice along lower-right edge
  brush.set("cp_micro", "#232536", 1.15);
  brush.spline(rightEdge, 0.4);

  // Parabolic fingertip curve around t in [0..0.06]
  let tipArc = [];
  for (let u = -0.98; u <= 0.98; u += 0.14) {
    let p = fingerPoint(f, 0.005, u, true);
    tipArc.push([p.x, p.y]);
  }
  brush.set("cp_micro", "#2c2e42", 1.05);
  brush.spline(tipArc, 0.45);
}

// ============================================================================
// LAYER 5: WATER MENISCUS (POINT OF ENTRY) & TRAPPED AIR BEADS
// ============================================================================

function drawMeniscusAndAirBeads() {
  // 1. Draw the liquid meniscus collar where each finger pierces the bathwater surface
  for (let f of fingers) {
    let mT = f.meniscusT;

    let troughPts = [];
    let rustCapillaryPts = [];
    let crestHighlightPts = [];
    let secondRipplePts = [];

    for (let s = 0; s <= 14; s++) {
      let u = map(s, 0, 14, -1.06, 1.06);
      // Meniscus wraps around the cylinder of the finger in a forward-curving arc
      let curveT = mT - 0.032 * (1 - u * u) + 0.004 * Math.sin(s * 1.7);
      let pTrough = fingerPoint(f, curveT, u, true);
      let pRust = fingerPoint(f, curveT - 0.008, u, true);
      let pCrest = fingerPoint(f, curveT + 0.006, u, false);
      let pRip2 = fingerPoint(f, curveT - 0.045, u * 1.03, true);

      troughPts.push([pTrough.x, pTrough.y]);
      rustCapillaryPts.push([pRust.x, pRust.y]);
      crestHighlightPts.push([pCrest.x, pCrest.y]);
      secondRipplePts.push([pRip2.x, pRip2.y]);
    }

    // Soft indigo watercolour shadow under the meniscus collar
    brush.set("wc_bleed_halo", "#172847", 1.1);
    brush.spline(troughPts, 0.45);

    // Crisp indigo & thin rust red capillary lines hugging the point of entry
    brush.set("wc_fine", "#14233f", 1.25);
    brush.spline(troughPts, 0.45);

    brush.set("wc_rust", "#943a28", 0.95);
    brush.spline(rustCapillaryPts, 0.45);

    // Secondary submerged capillary ring just forward of meniscus
    brush.set("wc_fine", "#32496e", 0.8);
    brush.spline(secondRipplePts, 0.45);

    // Glistening white coloured-pencil specular meniscus highlight
    brush.set("cp_highlight", "#ffffff", 1.25);
    brush.spline(crestHighlightPts.slice(1, 12), 0.45);
  }

  // 2. Draw delicate overlapping water surface rings passing across the deep submerged tips
  for (let f of fingers) {
    for (let ringT of [0.06, 0.14, 0.27]) {
      if (ringT >= f.meniscusT) continue;
      let overPts = [];
      for (let s = 0; s <= 10; s++) {
        let u = map(s, 0, 10, -1.15, 1.15);
        let t = ringT - 0.02 * (1 - u * u) + 0.005 * Math.cos(s * 1.6);
        let p = fingerPoint(f, Math.max(0.005, t), u, true);
        overPts.push([p.x, p.y]);
      }
      brush.set("wc_fine", "#20365c", 0.68);
      brush.spline(overPts, 0.45);
      let glintPts = overPts.slice(2, 8).map((pt) => [pt[0] - 1.2, pt[1] - 1.2]);
      brush.set("cp_highlight", "#dce8f5", 0.6);
      brush.spline(glintPts, 0.45);
    }
  }

  // 3. HYPERREAL TRAPPED AIR BEADS clinging to submerged fingertips, wrinkles & chipped nail
  let airBeads = [];

  for (let fi = 0; fi < fingers.length; fi++) {
    let f = fingers[fi];

    // Hero air beads trapped right inside the chipped nail notch!
    if (f.chipped === "major") {
      let pChip1 = fingerPoint(f, 0.032, -0.18, true);
      let pChip2 = fingerPoint(f, 0.042, -0.05, true);
      let pChip3 = fingerPoint(f, 0.025, -0.28, true);
      airBeads.push({ x: pChip1.x, y: pChip1.y, r: 6.2 });
      airBeads.push({ x: pChip2.x, y: pChip2.y, r: 4.1 });
      airBeads.push({ x: pChip3.x, y: pChip3.y, r: 3.0 });
    } else if (f.chipped === "minor") {
      let pChip = fingerPoint(f, 0.03, 0.28, true);
      airBeads.push({ x: pChip.x, y: pChip.y, r: 4.6 });
    }

    // Air beads nestled in the cuticle & lateral nail fold grooves
    let nailGrooveSpots = [
      { t: 0.19, u: -0.35, r: 5.2 },
      { t: 0.20, u: 0.15, r: 4.4 },
      { t: 0.14, u: -0.58, r: 3.8 },
      { t: 0.09, u: 0.56, r: 4.8 },
      { t: 0.05, u: -0.52, r: 3.4 }
    ];
    for (let sp of nailGrooveSpots) {
      if (sp.t < f.meniscusT) {
        let p = fingerPoint(f, sp.t, sp.u, true);
        airBeads.push({
          x: p.x + random(-2, 2),
          y: p.y + random(-2, 2),
          r: sp.r * random(0.85, 1.15)
        });
      }
    }

    // Air beads clinging to submerged DIP joint wrinkles, lateral skin folds & meniscus rim
    let count = f.name === "middle" || f.name === "index" ? 16 : 11;
    for (let b = 0; b < count; b++) {
      let t = random(0.015, f.meniscusT - 0.01);
      // Prefer lateral skin folds, DIP creases (t ~ 0.26), or near meniscus
      let u =
        b % 3 === 0
          ? random(-0.92, -0.55)
          : b % 3 === 1
          ? random(0.55, 0.92)
          : random(-0.5, 0.5);
      let p = fingerPoint(f, t, u, true);
      let r = random() < 0.25 ? random(4.8, 7.2) : random(2.0, 4.4);
      airBeads.push({ x: p.x, y: p.y, r });
    }
  }

  // Render every trapped air bead with full optical refraction & specular highlight
  for (let b of airBeads) {
    drawTrappedAirBead(b.x, b.y, b.r);
  }
}

function drawTrappedAirBead(x, y, r) {
  // 1. Tiny dark cast shadow on the submerged skin below-right of the bubble
  brush.noStroke();
  brush.wash("#1b1d2e", 150);
  brush.circle(x + r * 0.38, y + r * 0.42, r * 0.88, 0.1);

  // 2. Dark indigo internal-reflection dome on upper-left half
  brush.wash("#22324d", 190);
  brush.circle(x, y, r, 0.08);

  // 3. Luminous cyan-silver refracted light crescent on lower-right interior
  brush.wash("#9ab8d4", 195);
  brush.circle(x + r * 0.22, y + r * 0.22, r * 0.62, 0.08);
  brush.noWash();

  // 4. Crisp dark refractive outer boundary ring
  brush.set("cp_micro", "#121c30", 0.95);
  brush.circle(x, y, r, 0.06);

  // 5. Lower-right glowing internal reflection arc
  if (r > 2.6) {
    brush.set("cp_highlight", "#d6eafc", 0.85);
    brush.arc(x, y, r * 0.72, 15, 105);
  }

  // 6. Piercing pure white specular highlight pinpoint on upper-left dome
  let hx = x - r * 0.34;
  let hy = y - r * 0.34;
  brush.noStroke();
  brush.wash("#ffffff", 250);
  brush.circle(hx, hy, Math.max(1.2, r * 0.32), 0.02);
  brush.noWash();

  brush.set("cp_highlight", "#ffffff", 1.15);
  brush.line(hx - r * 0.12, hy + r * 0.06, hx + r * 0.14, hy - r * 0.08);
}

// Hyperrealistic Worm's-Eye View: Escaping Helium Balloons & Foreshortened Hand
// p5.js 2.x + p5.brush (WEBGL)

const VX = 575;
const VY = 410;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7429);
  noiseSeed(7429);

  // Custom chisel marker brush for glossy latex specular highlights
  brush.add("gloss_marker", {
    type: "marker",
    weight: 4.5,
    scatter: 0.04,
    opacity: 195,
    spacing: 0.25,
    pressure: [0.6, 1.2, 0.5],
    rotate: "natural",
    markerTip: false,
    noise: 0.15
  });

  // Custom fine detail shader brush for skin & latex micro-modeling
  brush.add("silk_shader", {
    type: "default",
    weight: 1.2,
    scatter: 0.35,
    sharpness: 0.35,
    grain: 0.45,
    opacity: 85,
    spacing: 0.4,
    pressure: [0.2, 1.0, 0.2],
    rotate: "natural",
    noise: 0.3
  });
}

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShapePts(pts, curvature = 0.35, closeShape = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].length > 2) {
      brush.vertex(pts[i][0], pts[i][1], pts[i][2]);
    } else {
      brush.vertex(pts[i][0], pts[i][1]);
    }
  }
  brush.endShape(closeShape);
}

function fillPoly(pts, col, alpha = 120, bleed = 0.12, tex = 0.45, border = 0.25, curvature = 0.35) {
  resetBrushState();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function washPoly(pts, col, alpha = 100, curvature = 0.3) {
  resetBrushState();
  brush.wash(col, alpha);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function hatchPoly(pts, bName, col, weight, dist, angle, opts = {}, curvature = 0.25) {
  resetBrushState();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(dist, angle, opts);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function massPoly(pts, bName, col, opts = {}, curvature = 0.3) {
  resetBrushState();
  brush.mass(bName, col, opts);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function strokeSpline(pts, bName, col, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(bName, col, weight);
  brush.spline(pts, curvature);
  resetBrushState();
}

function strokeLine(x1, y1, x2, y2, bName, col, weight = 1) {
  resetBrushState();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetBrushState();
}

// Generate an organic radial ring polygon around (cx, cy)
function makeRingPoly(cx, cy, rInner, rOuter, startAng, endAng, steps = 16, jitter = 14) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(startAng, endAng, t);
    let n = noise(cx * 0.01 + cos(a) * 1.5, cy * 0.01 + sin(a) * 1.5, rOuter * 0.01);
    let r = rOuter + map(n, 0, 1, -jitter, jitter);
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let a = lerp(startAng, endAng, t);
    let n = noise(cx * 0.01 + cos(a) * 1.5 + 10, cy * 0.01 + sin(a) * 1.5 + 10, rInner * 0.01);
    let r = max(0, rInner + map(n, 0, 1, -jitter * 0.7, jitter * 0.7));
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function makeBlobPoly(cx, cy, rx, ry, rotDeg = 0, steps = 24, noiseAmt = 0.15) {
  let pts = [];
  let cR = cos(rotDeg);
  let sR = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let nv = noise(cx * 0.005 + cos(a) * 1.2, cy * 0.005 + sin(a) * 1.2);
    let mod = 1 + map(nv, 0, 1, -noiseAmt, noiseAmt);
    let lx = cos(a) * rx * mod;
    let ly = sin(a) * ry * mod;
    pts.push([cx + lx * cR - ly * sR, cy + lx * sR + ly * cR]);
  }
  return pts;
}

// ============================================================================
// 1. BAROQUE SKY & OCULUS CEILING ATMOSPHERE
// ============================================================================
function drawBaroqueSky() {
  // Warm antique rag paper tone
  background("#f5ecda");

  // Color-batched watercolor sky washes from deep muted cerulean edges to pale alabaster zenith
  const skyRings = [
    // Deep Prussian/cerulean slate at outer corners
    { rIn: 620, rOut: 1050, col: "#1d3d52", alpha: 115, bleed: 0.28, tex: 0.65 },
    { rIn: 520, rOut: 860,  col: "#29546e", alpha: 105, bleed: 0.25, tex: 0.58 },
    // Mid cerulean-mineral blue
    { rIn: 400, rOut: 690,  col: "#3b6e87", alpha: 95,  bleed: 0.22, tex: 0.52 },
    { rIn: 310, rOut: 540,  col: "#59899c", alpha: 90,  bleed: 0.20, tex: 0.45 },
    // Warm earth-tinted sky transition (chalky robin's egg + ochre mist)
    { rIn: 220, rOut: 420,  col: "#85aab2", alpha: 85,  bleed: 0.18, tex: 0.40 },
    { rIn: 140, rOut: 310,  col: "#b8ccc6", alpha: 85,  bleed: 0.16, tex: 0.35 },
    { rIn: 70,  rOut: 220,  col: "#e3decb", alpha: 95,  bleed: 0.15, tex: 0.30 }
  ];

  for (let ring of skyRings) {
    // Split ring into 4 overlapping quadrants for organic watercolor blooms
    for (let q = 0; q < 4; q++) {
      let a0 = q * 90 - 12;
      let a1 = (q + 1) * 90 + 12;
      let pts = makeRingPoly(VX, VY, ring.rIn, ring.rOut, a0, a1, 12, 35);
      fillPoly(pts, ring.col, ring.alpha, ring.bleed, ring.tex, 0.28, 0.4);
    }
  }

  // Radiant golden-alabaster zenith core
  let corePts1 = makeBlobPoly(VX, VY, 210, 195, -15, 24, 0.12);
  washPoly(corePts1, "#f7efdc", 160, 0.4);
  let corePts2 = makeBlobPoly(VX, VY, 135, 125, 10, 24, 0.08);
  washPoly(corePts2, "#fffcf2", 210, 0.4);

  // Baroque Tiepolo-style cumulus clouds ringing the oculus in muted earth & ochre tones
  const cloudBanks = [
    // Upper left bank
    { x: 210, y: 190, rx: 190, ry: 110, rot: -32 },
    { x: 340, y: 130, rx: 160, ry: 95,  rot: -18 },
    { x: 120, y: 360, rx: 150, ry: 115, rot: -55 },
    // Upper right bank
    { x: 920, y: 175, rx: 210, ry: 120, rot: 28 },
    { x: 1050, y: 340, rx: 175, ry: 110, rot: 52 },
    { x: 760, y: 125, rx: 155, ry: 85,  rot: 12 },
    // Lower left & mid-left clouds
    { x: 145, y: 640, rx: 165, ry: 110, rot: -72 },
    { x: 255, y: 790, rx: 185, ry: 115, rot: -48 },
    // Lower right & mid-right clouds
    { x: 1040, y: 630, rx: 170, ry: 115, rot: 68 },
    { x: 945, y: 815, rx: 195, ry: 120, rot: 42 }
  ];

  // Batch 1: Deep warm umber-mauve cloud underbellies (away from zenith)
  for (let c of cloudBanks) {
    let angToVP = atan2(VY - c.y, VX - c.x);
    let ox = c.x - cos(angToVP) * 28;
    let oy = c.y - sin(angToVP) * 28;
    let pts = makeBlobPoly(ox, oy, c.rx, c.ry, c.rot, 20, 0.22);
    fillPoly(pts, "#7d685c", 72, 0.22, 0.5, 0.25, 0.4);
  }

  // Batch 2: Raw sienna & yellow ochre warm midtones
  for (let c of cloudBanks) {
    let angToVP = atan2(VY - c.y, VX - c.x);
    let ox = c.x + cos(angToVP) * 8;
    let oy = c.y + sin(angToVP) * 8;
    let pts = makeBlobPoly(ox, oy, c.rx * 0.85, c.ry * 0.82, c.rot, 20, 0.2);
    fillPoly(pts, "#c79e72", 80, 0.18, 0.45, 0.22, 0.4);
  }

  // Batch 3: Sunlit cream & warm alabaster cloud crests facing the zenith
  for (let c of cloudBanks) {
    let angToVP = atan2(VY - c.y, VX - c.x);
    let ox = c.x + cos(angToVP) * 36;
    let oy = c.y + sin(angToVP) * 36;
    let pts = makeBlobPoly(ox, oy, c.rx * 0.68, c.ry * 0.65, c.rot, 20, 0.18);
    fillPoly(pts, "#f7eed7", 115, 0.14, 0.35, 0.2, 0.4);

    // Crisp sunlit cloud rim facing VP
    let rimPts = [];
    for (let k = -4; k <= 4; k++) {
      let a = angToVP + k * 14;
      let r = c.rx * 0.58 * (1 + 0.12 * sin(k * 55));
      rimPts.push([ox + cos(a) * r, oy + sin(a) * r]);
    }
    strokeSpline(rimPts, "cpencil", "#fffcf2", 1.4, 0.5);
  }

  // Crepuscular rays radiating from the vanishing point
  for (let i = 0; i < 36; i++) {
    let a = i * 10 + random(-3, 3);
    let rStart = random(35, 110);
    let rEnd = random(420, 880);
    let spread = random(1.8, 4.2);
    let rayPts = [
      [VX + cos(a - spread * 0.3) * rStart, VY + sin(a - spread * 0.3) * rStart],
      [VX + cos(a - spread) * rEnd, VY + sin(a - spread) * rEnd],
      [VX + cos(a + spread) * rEnd, VY + sin(a + spread) * rEnd],
      [VX + cos(a + spread * 0.3) * rStart, VY + sin(a + spread * 0.3) * rStart]
    ];
    if (i % 2 === 0) {
      washPoly(rayPts, "#fff9e6", 28, 0.1);
    }
    strokeLine(
      VX + cos(a) * rStart,
      VY + sin(a) * rStart,
      VX + cos(a) * (rEnd * 0.75),
      VY + sin(a) * (rEnd * 0.75),
      "2H",
      "#fdf5df",
      random(0.4, 0.9)
    );
  }
}

// ============================================================================
// 2. WORM'S-EYE ARCHITECTURAL CORNICE AT CORNERS (Sotto in Su Earth-Toned Frame)
// ============================================================================
function drawArchitecturalCorners() {
  // Steeply foreshortened terracotta & sandstone parapet corners at bottom-left and bottom-right
  // All perspective receding edges point strictly toward (VX, VY)
  function ptTowardVP(x, y, t) {
    return [lerp(x, VX, t), lerp(y, VY, t)];
  }

  // Bottom-Left Cornice
  let blOuter1 = [0, 860];
  let blOuter2 = [250, 1200];
  let blInner1 = ptTowardVP(0, 860, 0.24);
  let blCorner = ptTowardVP(120, 1040, 0.26);
  let blInner2 = ptTowardVP(250, 1200, 0.24);

  // Top soffit plane (warm sunlit sandstone)
  let blPlaneA = [blOuter1, blInner1, blCorner, [120, 1040]];
  washPoly(blPlaneA, "#b88458", 185, 0.05);
  hatchPoly(blPlaneA, "2H", "#7d4e2d", 0.8, 7, atan2(VY - 950, VX - 60), { rand: 0.05 }, 0.05);

  // Side soffit plane (deep raw umber & burnt sienna shadow)
  let blPlaneB = [[120, 1040], blCorner, blInner2, blOuter2, [0, 1200], [0, 860]];
  washPoly([[120, 1040], blCorner, blInner2, blOuter2], "#69412a", 210, 0.05);
  washPoly([[0, 860], [120, 1040], blOuter2, [0, 1200]], "#472a1b", 225, 0.05);
  hatchPoly([[120, 1040], blCorner, blInner2, blOuter2], "HB", "#361e12", 0.9, 6, 35, { rand: 0.06 }, 0.05);

  // Crisp sunlit cornice molding lip
  let blLip1 = ptTowardVP(0, 885, 0.24);
  let blLipC = ptTowardVP(120, 1040, 0.24);
  let blLip2 = ptTowardVP(230, 1200, 0.24);
  strokeSpline([blInner1, blCorner, blInner2], "gloss_marker", "#f0d3a8", 0.9, 0.05);
  strokeSpline([blLip1, blLipC, blLip2], "rotring", "#3b2012", 1.1, 0.05);
  strokeLine(120, 1040, blCorner[0], blCorner[1], "gloss_marker", "#f7dfc0", 0.8);

  // Bottom-Right Cornice
  let brOuter1 = [1200, 890];
  let brOuter2 = [940, 1200];
  let brInner1 = ptTowardVP(1200, 890, 0.22);
  let brCorner = ptTowardVP(1070, 1050, 0.24);
  let brInner2 = ptTowardVP(940, 1200, 0.22);

  let brPlaneA = [brOuter1, brInner1, brCorner, [1070, 1050]];
  washPoly(brPlaneA, "#ad784c", 185, 0.05);
  hatchPoly(brPlaneA, "2H", "#6e4224", 0.8, 7, atan2(VY - 960, VX - 1100), { rand: 0.05 }, 0.05);

  let brPlaneB = [[1070, 1050], brCorner, brInner2, brOuter2];
  washPoly(brPlaneB, "#5e3824", 210, 0.05);
  washPoly([[1200, 890], [1070, 1050], brOuter2, [1200, 1200]], "#3d2215", 225, 0.05);
  hatchPoly(brPlaneB, "HB", "#2e180e", 0.9, 6, 145, { rand: 0.06 }, 0.05);

  strokeSpline([brInner1, brCorner, brInner2], "gloss_marker", "#efd1a5", 0.9, 0.05);
  strokeLine(1070, 1050, brCorner[0], brCorner[1], "gloss_marker", "#f7dfc0", 0.8);
}

// ============================================================================
// 3. HYPERREALISTIC GLOSSY LATEX BALLOONS & WARPED WINDOW REFLECTIONS
// ============================================================================

const BALLOON_PALETTES = {
  red: {
    baseFill: "#bf2c1d",
    deepRim: "#59110b",
    midShadow: "#8c1d14",
    glowOuter: "#e34a2d",
    glowInner: "#f77e45",
    glowCore: "#ffbe73",
    bounce: "#d48752",
    fresnel: "#ffdfd1",
    knotDark: "#450b07",
    knotHighlight: "#e8634a"
  },
  blue: {
    baseFill: "#1c3973",
    deepRim: "#0c1938",
    midShadow: "#142957",
    glowOuter: "#2d59a6",
    glowInner: "#4984d4",
    glowCore: "#8cc2f7",
    bounce: "#8c7a64",
    fresnel: "#d9eeff",
    knotDark: "#071026",
    knotHighlight: "#4f7ec4"
  },
  yellow: {
    baseFill: "#d9a71c",
    deepRim: "#6e4b08",
    midShadow: "#a17210",
    glowOuter: "#edb926",
    glowInner: "#fae064",
    glowCore: "#fff8bd",
    bounce: "#c98542",
    fresnel: "#fffbe6",
    knotDark: "#573905",
    knotHighlight: "#f7d454"
  }
};

// Compute a point on the 3D pear-spheroid contour of a balloon
function balloonContourPt(bx, by, rx, ry, rotDeg, aDeg) {
  // At aDeg == 90 (bottom along local Y), taper slightly into a pear neck
  let s = sin(aDeg);
  let pearMod = s > 0 ? 1 + 0.08 * pow(s, 2) : 1 - 0.03 * pow(-s, 2);
  let widthMod = s > 0.2 ? 1 - 0.14 * pow((s - 0.2) / 0.8, 1.6) : 1;
  let lx = cos(aDeg) * rx * widthMod;
  let ly = sin(aDeg) * ry * pearMod;
  let cR = cos(rotDeg);
  let sR = sin(rotDeg);
  return [bx + lx * cR - ly * sR, by + lx * sR + ly * cR];
}

function getBalloonOutline(b, steps = 36, scale = 1.0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push(balloonContourPt(b.x, b.y, b.rx * scale, b.ry * scale, b.rot, a));
  }
  return pts;
}

// Project normalized window coordinates (u, v) in [-1, 1]^2 onto a spherical cap on the balloon
function projectWindowPt(b, u, v, centerAngDeg, radFrac = 0.56) {
  // Spherical warp: lines curve around the balloon's dome
  let spanAng = 36;
  let a = centerAngDeg + u * spanAng * (1 - 0.12 * v);
  // Radial position on disk foreshortens near edge of sphere (sin of latitude)
  let lat = 37 + v * 19;
  let rNorm = sin(lat) * (1 - 0.09 * u * u);
  let r = lerp(b.rx, b.ry, 0.5) * rNorm * (radFrac / 0.56);
  return [b.x + cos(a) * r, b.y + sin(a) * r];
}

function drawWarpedWindowReflection(b, pal, detailLevel) {
  // Reflection sits on the upper dome facing toward the zenith/sunlight
  let angToVP = atan2(VY - b.y, VX - b.x);
  let reflAng = angToVP + b.reflOffset;

  // Soft atmospheric glow behind the window reflection
  let haloPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    haloPts.push(projectWindowPt(b, cos(a) * 1.05, sin(a) * 1.05, reflAng, 0.56));
  }
  washPoly(haloPts, pal.glowCore, 70 * detailLevel, 0.35);

  // 2x2 warped casement window panes
  const panes = [
    { u0: -0.95, u1: -0.09, v0: -0.92, v1: -0.08, alpha: 225 },
    { u0:  0.09, u1:  0.95, v0: -0.92, v1: -0.08, alpha: 205 },
    { u0: -0.95, u1: -0.09, v0:  0.08, v1:  0.92, alpha: 185 },
    { u0:  0.09, u1:  0.95, v0:  0.08, v1:  0.92, alpha: 160 }
  ];

  for (let p of panes) {
    let pts = [];
    // Sample along the 4 edges so the curvature of the sphere bends every pane edge
    const segs = 5;
    for (let i = 0; i <= segs; i++) pts.push(projectWindowPt(b, lerp(p.u0, p.u1, i / segs), p.v0, reflAng));
    for (let i = 1; i <= segs; i++) pts.push(projectWindowPt(b, p.u1, lerp(p.v0, p.v1, i / segs), reflAng));
    for (let i = 1; i <= segs; i++) pts.push(projectWindowPt(b, lerp(p.u1, p.u0, i / segs), p.v1, reflAng));
    for (let i = 1; i < segs; i++)  pts.push(projectWindowPt(b, p.u0, lerp(p.v1, p.v0, i / segs), reflAng));

    // Pale sky-blue glass tint under crisp ivory marker highlight
    washPoly(pts, "#dff0f5", p.alpha * 0.65 * detailLevel, 0.2);
    washPoly(pts, "#fffef7", p.alpha * 0.85 * detailLevel, 0.15);

    if (detailLevel > 0.65) {
      // Crisp marker strokes across the warped glass pane
      for (let s = 0.2; s <= 0.8; s += 0.3) {
        let mPts = [];
        for (let k = 0; k <= 4; k++) {
          mPts.push(projectWindowPt(b, lerp(p.u0 + 0.06, p.u1 - 0.06, k / 4), lerp(p.v0, p.v1, s), reflAng));
        }
        strokeSpline(mPts, "gloss_marker", "#ffffff", 0.55 * detailLevel, 0.3);
      }
    }
  }

  // Razor-sharp white specular glint along the upper curved window arch
  let glintPts = [];
  for (let i = 0; i <= 8; i++) {
    let u = lerp(-0.9, 0.9, i / 8);
    glintPts.push(projectWindowPt(b, u, -0.94, reflAng));
  }
  strokeSpline(glintPts, "rotring", "#ffffff", 1.2 * detailLevel, 0.4);
}

function drawBalloon(b, allBalloons) {
  const pal = BALLOON_PALETTES[b.type];
  const d = b.depth; // 0.35 (distant) to 1.0 (hero foreground)
  let angToVP = atan2(VY - b.y, VX - b.x);

  // 1. Base Watercolor Latex Wash
  let mainPts = getBalloonOutline(b, 36, 1.0);
  fillPoly(mainPts, pal.baseFill, lerp(115, 175, d), 0.07, 0.42, 0.32, 0.35);

  // 2. Dark Latex Rim Crescent (away from zenith where rubber is denser in shadow)
  let rimPts = [];
  let oppAng = angToVP + 180 - b.rot;
  for (let i = -110; i <= 110; i += 10) {
    rimPts.push(balloonContourPt(b.x, b.y, b.rx * 0.98, b.ry * 0.98, b.rot, oppAng + i));
  }
  for (let i = 110; i >= -110; i -= 10) {
    let innerScale = map(cos(i * 0.8), -1, 1, 0.96, 0.58);
    rimPts.push(balloonContourPt(b.x, b.y, b.rx * innerScale, b.ry * innerScale, b.rot, oppAng + i));
  }
  washPoly(rimPts, pal.midShadow, lerp(80, 145, d), 0.35);

  // Deeper shadow core crescent
  let deepPts = [];
  for (let i = -80; i <= 80; i += 10) {
    deepPts.push(balloonContourPt(b.x, b.y, b.rx * 0.94, b.ry * 0.94, b.rot, oppAng + i));
  }
  for (let i = 80; i >= -80; i -= 10) {
    let innerScale = map(cos(i), -1, 1, 0.92, 0.72);
    deepPts.push(balloonContourPt(b.x, b.y, b.rx * innerScale, b.ry * innerScale, b.rot, oppAng + i));
  }
  washPoly(deepPts, pal.deepRim, lerp(75, 135, d), 0.35);

  // 3. Subsurface Transmitted Sunlight (Offset toward the zenith)
  let glowShift = lerp(b.rx, b.ry, 0.5) * 0.18;
  let gx = b.x + cos(angToVP) * glowShift;
  let gy = b.y + sin(angToVP) * glowShift;

  let glow1 = makeBlobPoly(gx, gy, b.rx * 0.74, b.ry * 0.74, b.rot, 24, 0.04);
  washPoly(glow1, pal.glowOuter, lerp(85, 130, d), 0.4);

  let glow2 = makeBlobPoly(
    gx + cos(angToVP) * glowShift * 0.55,
    gy + sin(angToVP) * glowShift * 0.55,
    b.rx * 0.50,
    b.ry * 0.48,
    b.rot,
    24,
    0.03
  );
  fillPoly(glow2, pal.glowInner, lerp(80, 125, d), 0.12, 0.3, 0.15, 0.4);

  let glow3 = makeBlobPoly(
    gx + cos(angToVP) * glowShift * 0.9,
    gy + sin(angToVP) * glowShift * 0.9,
    b.rx * 0.28,
    b.ry * 0.26,
    b.rot,
    20,
    0.02
  );
  washPoly(glow3, pal.glowCore, lerp(75, 120, d), 0.4);

  // 4. Translucent Overlap Darkening (where deeper balloons sit behind this balloon)
  if (allBalloons) {
    for (let other of allBalloons) {
      if (other === b || other.depth >= b.depth) continue;
      let distCenters = dist(b.x, b.y, other.x, other.y);
      let maxR = max(b.rx, b.ry) + max(other.rx, other.ry);
      if (distCenters < maxR * 0.88) {
        // Compute intersection lens approximation for translucent latex silhouette
        let lensPts = [];
        for (let a = 0; a < 360; a += 15) {
          let p = balloonContourPt(other.x, other.y, other.rx * 0.92, other.ry * 0.92, other.rot, a);
          let dx = (p[0] - b.x) / (b.rx * 0.95);
          let dy = (p[1] - b.y) / (b.ry * 0.95);
          if (dx * dx + dy * dy < 1.0) {
            lensPts.push(p);
          }
        }
        if (lensPts.length >= 4) {
          washPoly(lensPts, pal.deepRim, 55 * d, 0.3);
        }
      }
    }
  }

  // 5. Warm Muted Earth-Tone Bounce Reflection on Underside (from sunlit stone & hand below)
  let bouncePts = [];
  for (let i = -55; i <= 55; i += 10) {
    let a = oppAng + i;
    bouncePts.push(balloonContourPt(b.x, b.y, b.rx * 0.88, b.ry * 0.88, b.rot, a));
  }
  for (let i = 55; i >= -55; i -= 10) {
    let a = oppAng + i;
    let s = map(cos(i * 1.4), -1, 1, 0.86, 0.72);
    bouncePts.push(balloonContourPt(b.x, b.y, b.rx * s, b.ry * s, b.rot, a));
  }
  washPoly(bouncePts, pal.bounce, 95 * d, 0.35);

  // 6. Spherical Contour Modeling with Colored Pencil & Silk Shader
  if (d > 0.5) {
    let arcCount = floor(map(d, 0.5, 1.0, 6, 14));
    for (let k = 0; k < arcCount; k++) {
      let t = map(k, 0, arcCount - 1, 0.62, 0.96);
      let arcPts = [];
      for (let i = -75; i <= 75; i += 15) {
        arcPts.push(balloonContourPt(b.x, b.y, b.rx * t, b.ry * t, b.rot, oppAng + i));
      }
      strokeSpline(arcPts, "silk_shader", pal.deepRim, 0.85 * d, 0.45);
    }
  }

  // 7. Warped Window Reflection on Glossy Sphere
  drawWarpedWindowReflection(b, pal, d);

  // 8. Secondary Pin-Prick Specular Highlight on Lower Rim
  let secPt1 = balloonContourPt(b.x, b.y, b.rx * 0.81, b.ry * 0.81, b.rot, oppAng - 28);
  let secPt2 = balloonContourPt(b.x, b.y, b.rx * 0.81, b.ry * 0.81, b.rot, oppAng - 12);
  strokeLine(secPt1[0], secPt1[1], secPt2[0], secPt2[1], "gloss_marker", "#fff7e6", 0.5 * d);

  // 9. Thin Fresnel Sky-Rim Highlight & Crisp Latex Contour
  let fresnelPts = [];
  let skyLocalAng = angToVP - b.rot;
  for (let i = -80; i <= 80; i += 10) {
    fresnelPts.push(balloonContourPt(b.x, b.y, b.rx * 0.985, b.ry * 0.985, b.rot, skyLocalAng + i));
  }
  strokeSpline(fresnelPts, "cpencil", pal.fresnel, 1.3 * d, 0.45);
  strokeSpline(mainPts.concat([mainPts[0]]), "2B", pal.deepRim, 0.65 * d, 0.35);

  // 10. Foreshortened Balloon Neck, Tied Knot & Rolled Rubber Lip
  // The knot sits at local angle 90 deg (pointing down/inward in worm's-eye perspective)
  let knotBase = balloonContourPt(b.x, b.y, b.rx, b.ry, b.rot, 90);
  let dirX = cos(b.rot + 90);
  let dirY = sin(b.rot + 90);
  let perpX = -dirY;
  let perpY = dirX;
  let kw = b.rx * 0.13;
  let kh = b.ry * 0.09;

  // Dense dark rubber knot bulb
  let knotBulb = [
    [knotBase[0] - perpX * kw * 0.8, knotBase[1] - perpY * kw * 0.8],
    [knotBase[0] + perpX * kw * 0.8, knotBase[1] + perpY * kw * 0.8],
    [knotBase[0] + dirX * kh + perpX * kw * 0.5, knotBase[1] + dirY * kh + perpY * kw * 0.5],
    [knotBase[0] + dirX * kh - perpX * kw * 0.5, knotBase[1] + dirY * kh - perpY * kw * 0.5]
  ];
  washPoly(knotBulb, pal.knotDark, 230, 0.2);

  // Flared rubber lip ring below the knot
  let lipCenter = [knotBase[0] + dirX * kh * 1.45, knotBase[1] + dirY * kh * 1.45];
  let lipRing = makeBlobPoly(lipCenter[0], lipCenter[1], kw * 1.15, kh * 0.55, b.rot, 14, 0.04);
  washPoly(lipRing, pal.midShadow, 215, 0.3);
  strokeSpline(lipRing.concat([lipRing[0]]), "rotring", pal.knotDark, 0.75 * d, 0.3);

  // Specular glint on the knot & lip ring
  strokeLine(
    knotBase[0] - perpX * kw * 0.45,
    knotBase[1] - perpY * kw * 0.45,
    knotBase[0] + perpX * kw * 0.45,
    knotBase[1] + perpY * kw * 0.45,
    "pen",
    pal.knotHighlight,
    0.9 * d
  );
  strokeLine(
    lipCenter[0] - perpX * kw * 0.6,
    lipCenter[1] - perpY * kw * 0.6,
    lipCenter[0] + perpX * kw * 0.6,
    lipCenter[1] + perpY * kw * 0.6,
    "pen",
    "#fff6e8",
    0.7 * d
  );

  // Save knot attachment point for the curling ribbon
  b.knotPos = [knotBase[0] + dirX * kh * 0.7, knotBase[1] + dirY * kh * 0.7];
}

// ============================================================================
// 4. SPIRALING HELICAL RIBBONS IN PERSPECTIVE
// ============================================================================
function drawCurlingRibbon(startPt, endPt, ctrl1, ctrl2, opts) {
  const steps = opts.steps || 85;
  const wStart = opts.wStart || 2.5;
  const wEnd = opts.wEnd || 13.5;
  const curls = opts.curls || 5.5;
  const ampStart = opts.ampStart || 6;
  const ampEnd = opts.ampEnd || 34;
  const phase = opts.phase || 0;
  const colFront = opts.colFront || "#dfb052";
  const colBack = opts.colBack || "#754b21";
  const colEdge = opts.colEdge || "#4a2c10";

  let spine = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let mt = 1 - t;
    // Cubic Bezier base spine from balloon knot down toward hand fingertips
    let bx = mt * mt * mt * startPt[0] + 3 * mt * mt * t * ctrl1[0] + 3 * mt * t * t * ctrl2[0] + t * t * t * endPt[0];
    let by = mt * mt * mt * startPt[1] + 3 * mt * mt * t * ctrl1[1] + 3 * mt * t * t * ctrl2[1] + t * t * t * endPt[1];

    // Tangent approximation
    let dt = 0.01;
    let t2 = min(1, t + dt);
    let mt2 = 1 - t2;
    let bx2 = mt2 * mt2 * mt2 * startPt[0] + 3 * mt2 * mt2 * t2 * ctrl1[0] + 3 * mt2 * t2 * t2 * ctrl2[0] + t2 * t2 * t2 * endPt[0];
    let by2 = mt2 * mt2 * mt2 * startPt[1] + 3 * mt2 * mt2 * t2 * ctrl1[1] + 3 * mt2 * t2 * t2 * ctrl2[1] + t2 * t2 * t2 * endPt[1];
    let tangAng = atan2(by2 - by, bx2 - bx);
    let normAng = tangAng + 90;

    // Helical corkscrew oscillation increasing in perspective toward the viewer
    let theta = t * curls * 360 + phase;
    let amp = lerp(ampStart, ampEnd, pow(t, 1.15));
    let ox = cos(normAng) * sin(theta) * amp + cos(tangAng) * cos(theta) * (amp * 0.22);
    let oy = sin(normAng) * sin(theta) * amp + sin(tangAng) * cos(theta) * (amp * 0.22);

    // Apparent ribbon width foreshortens as the ribbon twists
    let baseW = lerp(wStart, wEnd, pow(t, 1.25));
    let twistFactor = cos(theta);
    let halfW = baseW * 0.5 * twistFactor;

    let px = bx + ox;
    let py = by + oy;
    spine.push({
      x: px,
      y: py,
      edgeA: [px - cos(normAng) * halfW, py - sin(normAng) * halfW],
      edgeB: [px + cos(normAng) * halfW, py + sin(normAng) * halfW],
      twist: twistFactor,
      baseW: baseW,
      normAng: normAng,
      t: t
    });
  }

  // Draw ribbon segments in small quads so front vs back satin sides alternate cleanly
  let chunkSize = 3;
  for (let i = 0; i < spine.length - 1; i += chunkSize) {
    let iEnd = min(spine.length - 1, i + chunkSize);
    let quadPts = [];
    for (let k = i; k <= iEnd; k++) quadPts.push(spine[k].edgeA);
    for (let k = iEnd; k >= i; k--) quadPts.push(spine[k].edgeB);

    let midNode = spine[floor((i + iEnd) * 0.5)];
    let isFront = midNode.twist >= 0;
    let segCol = isFront ? colFront : colBack;
    washPoly(quadPts, segCol, 220, 0.15);

    // Crisp specular highlight where the ribbon face catches direct zenith light
    if (abs(midNode.twist) > 0.72 && midNode.t > 0.2) {
      let n = midNode;
      strokeLine(
        n.edgeA[0], n.edgeA[1],
        n.edgeB[0], n.edgeB[1],
        "gloss_marker",
        "#fffef5",
        map(n.t, 0, 1, 0.35, 0.95)
      );
    }
  }

  // Crisp edge lines along both sides of the ribbon for hyperreal definition
  let edgeAPts = spine.map(s => s.edgeA);
  let edgeBPts = spine.map(s => s.edgeB);
  strokeSpline(edgeAPts, "rotring", colEdge, 0.65, 0.45);
  strokeSpline(edgeBPts, "rotring", colEdge, 0.55, 0.45);
}

// ============================================================================
// 5. FORESHORTENED CHILD'S HAND IN FOREGROUND (Just Released the Ribbons)
// ============================================================================
function drawForeshortenedHand() {
  // The child's right hand enters from bottom-center/right, palm open upward toward the sky,
  // fingers splayed in perspective ("sotto in su") right after letting go of the ribbons.

  // --- A. Forearm & Rolled Linen/Ochre Sleeve Cuff at Bottom Edge ---
  let sleeveMain = [
    [515, 1200], [535, 1085], [575, 1035], [650, 1030],
    [735, 1055], [785, 1110], [820, 1200]
  ];
  fillPoly(sleeveMain, "#cab292", 210, 0.08, 0.5, 0.3, 0.25);

  // Sleeve shadow side (right & underside in warm raw umber)
  let sleeveShadow = [
    [630, 1032], [735, 1055], [785, 1110], [820, 1200], [645, 1200], [620, 1095]
  ];
  washPoly(sleeveShadow, "#7d6449", 185, 0.25);
  hatchPoly(sleeveShadow, "HB", "#4d3a26", 0.9, 6, 65, { rand: 0.07 }, 0.2);

  // Rolled cuff folds catching warm sunlight on left edge
  let cuffRoll1 = [
    [528, 1095], [568, 1032], [655, 1025], [742, 1052],
    [730, 1092], [645, 1068], [565, 1075]
  ];
  washPoly(cuffRoll1, "#e8d7bd", 195, 0.3);
  strokeSpline([[532, 1088], [572, 1032], [655, 1025], [738, 1052]], "gloss_marker", "#fff8eb", 0.9, 0.35);
  strokeSpline([[555, 1075], [645, 1068], [730, 1092]], "2B", "#4a3522", 1.1, 0.35);

  // --- B. Wrist & Foreshortened Palm ---
  // Wrist cylinder bridging cuff to heel of palm
  let wristPts = [
    [555, 1050], [545, 975], [635, 965], [715, 995], [715, 1065], [635, 1045]
  ];
