// Helper to draw closed shapes using beginShape/vertex (avoiding brush.polygon)
function drawClosedShape(pts, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Parametric 3D surface model of a ripe 4-lobed persimmon
// u in [-1, 1] (horizontal azimuth across visible hemisphere)
// v in [0, 1] (0 = top crown hollow, 1 = bottom base resting on tray)
function persimmonSurface(u, v) {
  let theta = v * 180; // 0 at top pole, 180 at bottom contact
  let phi = u * 92;    // -92 to +92 degrees front hemisphere

  let sinT = sin(theta);
  let cosT = cos(theta);
  let sinP = sin(phi);
  let cosP = cos(phi);

  // Persimmon silhouette modulation: plump broad cheeks, slightly flattened base,
  // and 4-fold subtle organic lobing with two front longitudinal sulci (grooves)
  let cheekSwell = 1.0 + 0.08 * sin(v * 180) + 0.045 * sin(v * 360 - 30);
  let grooveL = exp(-pow((u + 0.41) / 0.13, 2)) * pow(sinT, 1.6);
  let grooveR = exp(-pow((u - 0.44) / 0.13, 2)) * pow(sinT, 1.6);
  let lobeMod = 1.0 - 0.026 * (grooveL + grooveR) + 0.016 * cos(u * 3.14159 * 180 / 90);

  // Tiny bruise indentation around (u = 0.35, v = 0.61)
  let duB = (u - 0.35) / 0.075;
  let dvB = (v - 0.61) / 0.055;
  let bruiseDist2 = duB * duB + dvB * dvB;
  let bruiseDip = bruiseDist2 < 2.5 ? 0.022 * exp(-bruiseDist2 * 1.4) : 0;

  let rHoriz = RX * cheekSwell * lobeMod * (1.0 - bruiseDip);

  // X coordinate
  let x = CX + rHoriz * sinT * sinP;

  // Y coordinate: sunken crown at top (v near 0), flat heavy belly at bottom (v near 1)
  let crownSink = 18 * exp(-v * 6.5) * (0.4 + 0.6 * cosP);
  let bellyFlat = 14 * pow(max(0, v - 0.72) / 0.28, 2.2) * cosP;
  // Perspective tilt (viewing slightly from above at ~14 degrees)
  let perspDrop = 26 * sinT * cosP;

  let y = CY - RY * cosT + crownSink - bellyFlat + perspDrop;
  // Clamp bottom cleanly to the tray surface
  y = min(CONTACT_Y, y);

  // Approximate 3D surface normal for optical shading
  let nx = sinT * sinP + 0.09 * ((u + 0.41) * grooveL + (u - 0.44) * grooveR);
  let ny = -cosT + 0.15 * sinT * cosP;
  let nz = sinT * cosP;

  // Perturb normal inside the tiny bruise concavity
  if (bruiseDist2 < 2.2) {
    let bFactor = exp(-bruiseDist2 * 1.3);
    nx -= duB * 0.28 * bFactor;
    ny -= dvB * 0.28 * bFactor;
  }

  let nLen = sqrt(nx * nx + ny * ny + nz * nz) || 1;
  return {
    x,
    y,
    u,
    v,
    nx: nx / nLen,
    ny: ny / nLen,
    nz: nz / nLen,
    groove: grooveL + grooveR,
    bruise: bruiseDist2 < 1.8 ? exp(-bruiseDist2 * 1.2) : 0
  };
}

// Compute strict-palette color for any point on the persimmon skin
function shadePersimmonSkin(pt) {
  // Primary studio window light from upper-left-front
  let lx = -0.46, ly = -0.52, lz = 0.72;
  let ndotl = max(0, pt.nx * lx + pt.ny * ly + pt.nz * lz);

  // Subsurface scattering peaks in the mid-light zone of ripe translucent flesh
  let sss = pow(max(0, 1.0 - abs(ndotl - 0.48) * 1.75), 1.8) * max(0, pt.nz);

  // Grazing Fresnel (dark lacquer tray reflection at bottom, bloom at upper rim)
  let fresnel = pow(1.0 - max(0, pt.nz), 2.2);
  let bottomMirror = pow(max(0, pt.v - 0.74) / 0.26, 1.6);

  // Bounce light from the glowing vermilion reflection on the tray right under the center belly
  let trayBounce = pow(max(0, pt.v - 0.80) / 0.20, 1.5) * exp(-pow(pt.u / 0.55, 2));

  // If inside the tiny bruise, shift to coagulated cinnabar-black & bruised ochre-cinnabar rim
  if (pt.bruise > 0.35) {
    if (pt.bruise > 0.68) return PAL.cinAbyss;
    if (pt.ny < -0.1) return PAL.cinDark;
    return PAL.ochreUmber;
  }

  // Bottom dark mirror zone where the curved skin reflects the black lacquer tray
  if (bottomMirror > 0.55 && trayBounce < 0.25) {
    return ndotl > 0.3 ? PAL.cinShadow : PAL.cinAbyss;
  }
  if (trayBounce > 0.35 && pt.v > 0.88) {
    return PAL.cinRich;
  }

  // Main tonal ladder (strictly vermilion, cinnabar, and black)
  let tone = ndotl * 0.78 + sss * 0.34 - bottomMirror * 0.35 - fresnel * 0.18;

  if (tone > 0.86) return PAL.vermCore;
  if (tone > 0.74) return PAL.vermGlow;
  if (tone > 0.62) return PAL.vermFiery;
  if (tone > 0.50) return PAL.vermBright;
  if (tone > 0.39) return PAL.vermPure;
  if (tone > 0.29) return PAL.vermDark;
  if (tone > 0.20) return PAL.cinRich;
  if (tone > 0.13) return PAL.cinMid;
  if (tone > 0.07) return PAL.cinDeep;
  if (tone > 0.03) return PAL.cinShadow;
  if (tone > 0.01) return PAL.cinDark;
  return PAL.cinAbyss;
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.blkVoid);
  brush.noField();

  // 1. DEEP BLACK LACQUERED TRAY (Dense opaque marker slabs, sharp bevels, almost no gradient)
  drawLacquerTray();

  // 2. LIQUID SURFACE REFLECTION: Han Dynasty Cloud-Scroll Streaks (Yunqiwen)
  drawHanCloudScrollReflection();

  // 3. HYPERREAL PERSIMMON BODY: Opaque washes, 3D marker cross-contours & satin skin
  drawPersimmonBody();

  // 4. FAINT WAXY BLOOM (Epicuticular pruina veil on upper shoulders & creases)
  drawWaxyBloom();

  // 5. THE TINY BRUISE (Concave skin dimple, oxidized cinnabar-black core & rim glint)
  drawTinyBruise();

  // 6. CRISP WINDOW REFLECTION (Curved 4-pane studio window & double-glaze ghost)
  drawCrispWindowReflection();

  // 7. THE CALYX (Single Ochre Accent: 4 curled leathery sepals, woody stem & cast shadows)
  drawOchreCalyx();

  // 8. FINAL CEREMONIAL LACQUER DETAILS (Contact occlusion & razor-sharp surface glints)
  drawFinalLacquerPolish();

  noLoop();
}

// ============================================================================
// 1. DEEP BLACK LACQUERED TRAY
// ============================================================================
function drawLacquerTray() {
  // Base tray recessed plane in dense pitch black
  brush.noStroke();
  brush.wash(PAL.blkUrushi, 255);
  let trayOuter = [
    [110, 310], [1090, 310],
    [1160, 1085], [1120, 1135],
    [80, 1135], [40, 1085]
  ];
  drawClosedShape(trayOuter, 0.02);

  // Inner liquid lacquer mirror well
  brush.wash(PAL.blkVoid, 255);
  let trayInner = [
    [136, 332], [1064, 332],
    [1126, 1068], [1094, 1106],
    [106, 1106], [74, 1068]
  ];
  drawClosedShape(trayInner, 0.02);
  brush.noWash();

  // Dense opaque marker layering across the black ground (sharp edges, almost no gradient)
  for (let i = 0; i < 65; i++) {
    let y = map(i, 0, 64, 40, 1160);
    let col = (i % 3 === 0) ? PAL.blkVoid : ((i % 2 === 0) ? PAL.blkUrushi : PAL.blkSlab);
    brush.set("lacquer_slab", col, random(1.2, 2.1));
    let x1 = random(20, 160);
    let x2 = random(1040, 1180);
    brush.line(x1, y, x2, y);
  }

  // Sharp architectural bevels of the ceremonial Han lacquer tray
  brush.set("scroll_blade", PAL.blkRim, 0.9);
  brush.line(110, 310, 1090, 310);
  brush.line(136, 332, 1064, 332);
  brush.line(106, 1106, 1094, 1106);
  brush.line(80, 1135, 1120, 1135);

  // Hair-thin ceremonial cinnabar urushi pinstripe inlaid along the tray rim
  brush.set("needle_detail", PAL.cinShadow, 0.85);
  brush.line(142, 336, 1058, 336);
  brush.line(142, 336, 82, 1065);
  brush.line(1058, 336, 1118, 1065);
  brush.line(82, 1065, 110, 1101);
  brush.line(1118, 1065, 1090, 1101);

  // Subtle specular catch along the center of the front lacquer lip
  brush.set("needle_detail", PAL.cinMid, 0.9);
  brush.line(310, 1101, 890, 1101);
  brush.set("needle_detail", PAL.vermDark, 0.65);
  brush.line(460, 1101, 740, 1101);
}

// ============================================================================
// 2. LIQUID SURFACE REFLECTION: HAN CLOUD-SCROLL STREAKS (YUNQIWEN)
// ============================================================================
// Helper to build a sharp-edged Han cloud-scroll ribbon with curled volute ends
function buildCloudScrollBand(cx, y, halfW, thickness, curlDirL, curlDirR, waveAmp) {
  let pts = [];
  let steps = 28;
  // Upper edge from left to right
  for (let i = 0; i <= steps; i++) {
    let t = i / steps; // 0 to 1
    let u = (t - 0.5) * 2; // -1 to 1
    let x = cx + u * halfW;
    // Han cloud-scroll S-wave undulation
    let wave = sin(u * 180 + (y * 1.7)) * waveAmp + sin(u * 360) * (waveAmp * 0.35);
    // Tapering at ends before curling into volute hook
    let env = sin(t * 180);
    let h = thickness * (0.25 + 0.75 * pow(env, 0.65));

    // Add hooked scroll crest near the tips
    let scrollHook = 0;
    if (t < 0.14) {
      let st = (0.14 - t) / 0.14;
      scrollHook = curlDirL * pow(st, 1.5) * thickness * 1.45;
      x -= st * thickness * 0.6;
    } else if (t > 0.86) {
      let st = (t - 0.86) / 0.14;
      scrollHook = curlDirR * pow(st, 1.5) * thickness * 1.45;
      x += st * thickness * 0.6;
    }
    pts.push([x, y + wave - h * 0.5 + scrollHook]);
  }
  // Lower edge from right to left
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let u = (t - 0.5) * 2;
    let x = cx + u * halfW;
    let wave = sin(u * 180 + (y * 1.7)) * waveAmp + sin(u * 360) * (waveAmp * 0.35);
    let env = sin(t * 180);
    let h = thickness * (0.25 + 0.75 * pow(env, 0.65));

    let scrollHook = 0;
    if (t < 0.14) {
      let st = (0.14 - t) / 0.14;
      scrollHook = curlDirL * pow(st, 1.8) * thickness * 0.85;
      x -= st * thickness * 0.25;
    } else if (t > 0.86) {
      let st = (t - 0.86) / 0.14;
      scrollHook = curlDirR * pow(st, 1.8) * thickness * 0.85;
      x += st * thickness * 0.25;
    }
    pts.push([x, y + wave + h * 0.5 + scrollHook]);
  }
  return pts;
}

// Helper to draw a spiral volute curl (classic Han lacquer cloud head)
function drawLacquerVolute(x, y, rx, ry, startAng, turns, col, weightStart, dir = 1) {
  let pts = [];
  let totalSteps = 22;
  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    let ang = startAng + dir * t * turns * 360;
    let rScale = pow(1.0 - t * 0.82, 0.85);
    let px = x + cos(ang) * rx * rScale;
    let py = y + sin(ang) * ry * rScale;
    let p = map(1 - t, 0, 1, 0.15, 1.1);
    pts.push([px, py, p]);
  }
  brush.set("scroll_blade", col, weightStart);
  brush.spline(pts, 0.45);
}

function drawHanCloudScrollReflection() {
  // Layer A: Deep Cinnabar & Vermilion mirrored silhouette core on the black lacquer
  // Structured in sharp horizontal cloud-scroll tiers from contact (y=634) down to y=1045
  let numBands = 38;
  for (let i = 0; i < numBands; i++) {
    let t = i / (numBands - 1); // 0 (top under fruit) to 1 (bottom tip of reflection)
    let y = lerp(638, 1025, pow(t, 0.96));

    // Envelope of the inverted persimmon silhouette
    let domeEnv = sin(constrain(map(t, 0, 0.88, 18, 172), 0, 180));
    let baseHalfW = RX * 1.04 * domeEnv;

    // Cloud-scroll rhythmic expansion and contraction
    let scrollMod = 1.0 + 0.22 * sin(i * 47) + 0.14 * cos(i * 95);
    let halfW = max(24, baseHalfW * scrollMod);
    let shiftX = sin(i * 38) * 18 * (0.3 + 0.7 * t);

    // Color selection: deep cinnabar outer halo, fiery vermilion core, ochre at very bottom tip
    let outerCol = (t < 0.15) ? PAL.cinDark : ((t < 0.78) ? PAL.cinDeep : PAL.cinShadow);
    let innerCol = (t < 0.10) ? PAL.cinRich : ((t < 0.55) ? PAL.vermPure : ((t < 0.82) ? PAL.vermDark : PAL.cinMid));
    let coreCol = (t < 0.45) ? PAL.vermFiery : PAL.vermBright;

    let thick = lerp(14, 6.5, t) * (0.85 + 0.3 * sin(i * 63));
    let curlL = (i % 2 === 0) ? -1 : 1;
    let curlR = (i % 3 === 0) ? 1 : -1;
    let waveAmp = lerp(3.5, 11.0, t);

    // 1. Outer Cinnabar cloud-scroll band
    brush.noStroke();
    brush.wash(outerCol, 250);
    let bandOuter = buildCloudScrollBand(CX + shiftX, y, halfW * 1.12, thick * 1.15, curlL, curlR, waveAmp);
    drawClosedShape(bandOuter, 0.2);

    // 2. Inner Vermilion cloud-scroll band
    if (t < 0.88) {
      brush.wash(innerCol, 255);
      let bandInner = buildCloudScrollBand(CX + shiftX * 0.7 - 8, y, halfW * 0.82, thick * 0.82, curlL, curlR, waveAmp * 0.85);
      drawClosedShape(bandInner, 0.2);
    }

    // 3. Luminous Vermilion Core (shifted slightly left toward the lit cheek of the fruit)
    if (t > 0.06 && t < 0.74 && i % 2 === 0) {
      brush.wash(coreCol, 255);
      let bandCore = buildCloudScrollBand(CX - 28 + shiftX * 0.5, y, halfW * 0.48, thick * 0.58, -curlL, curlR, waveAmp * 0.7);
      drawClosedShape(bandCore, 0.2);
    }
    brush.noWash();
  }

  // Layer B: Sharp-edged Black Lacquer Cloud-Scroll Cutouts slicing INTO the reflection
  // This creates the authentic Han lacquer rhythmic interplay of positive/negative scrolls
  for (let i = 0; i < 34; i++) {
    let t = i / 33;
    let y = lerp(646, 1030, t);
    let domeEnv = sin(constrain(map(t, 0, 0.9, 20, 170), 0, 180));
    let span = RX * domeEnv;

    // Left and right black lacquer scroll tongues cutting inward
    let side = (i % 2 === 0) ? -1 : 1;
    let startX = CX + side * (span + 95);
    let endX = CX + side * random(-35, span * 0.42);
    let midX = lerp(startX, endX, 0.55);
    let waveY = sin(i * 55) * 9;

    // Dense opaque black marker scroll cut
    let cutPts = [
      [startX, y - 5],
      [midX, y + waveY - 3.5],
      [endX, y - waveY * 0.6],
      [endX + side * 14, y - waveY * 0.6 + (i % 3 === 0 ? -9 : 9)],
      [midX, y + waveY + 4.5],
      [startX, y + 6]
    ];
    brush.noStroke();
    brush.wash(PAL.blkVoid, 255);
    drawClosedShape(cutPts, 0.25);
    brush.noWash();

    // Crisp black scroll blade stroke with hooked volute tip
    brush.set("scroll_blade", PAL.blkVoid, random(0.9, 1.45));
    brush.spline([
      [startX, y, 0.9],
      [midX, y + waveY, 1.0],
      [endX, y - waveY * 0.5, 0.6],
      [endX + side * 18, y - waveY * 0.5 + (i % 2 === 0 ? -11 : 11), 0.2]
    ], 0.45);
  }

  // Layer C: Signature Han Lacquer Cloud-Scroll Volutes (Yunqi Curls & Hooked Whiskers)
  let scrollNodes = [
    // Left flank flowing cloud-scrolls
    { x: 415, y: 675, rx: 36, ry: 14, ang: 180, turns: 1.15, col: PAL.cinRich, w: 1.0, dir: 1 },
    { x: 378, y: 712, rx: 44, ry: 16, ang: 170, turns: 1.25, col: PAL.vermDark, w: 1.15, dir: -1 },
    { x: 356, y: 754, rx: 48, ry: 18, ang: 185, turns: 1.30, col: PAL.vermPure, w: 1.2, dir: 1 },
    { x: 372, y: 798, rx: 42, ry: 15, ang: 175, turns: 1.20, col: PAL.vermFiery, w: 1.1, dir: -1 },
    { x: 398, y: 842, rx: 38, ry: 14, ang: 190, turns: 1.25, col: PAL.vermBright, w: 1.0, dir: 1 },
    { x: 432, y: 886, rx: 34, ry: 13, ang: 180, turns: 1.15, col: PAL.cinRich, w: 0.95, dir: -1 },
    { x: 475, y: 932, rx: 28, ry: 11, ang: 175, turns: 1.10, col: PAL.cinMid, w: 0.85, dir: 1 },
    // Right flank flowing cloud-scrolls
    { x: 782, y: 682, rx: 34, ry: 13, ang: 0, turns: 1.15, col: PAL.cinMid, w: 0.95, dir: -1 },
    { x: 815, y: 722, rx: 42, ry: 15, ang: 10, turns: 1.25, col: PAL.cinRich, w: 1.1, dir: 1 },
    { x: 832, y: 766, rx: 46, ry: 17, ang: -10, turns: 1.30, col: PAL.vermDark, w: 1.15, dir: -1 },
    { x: 814, y: 810, rx: 40, ry: 15, ang: 5, turns: 1.20, col: PAL.cinRich, w: 1.05, dir: 1 },
    { x: 785, y: 855, rx: 36, ry: 13, ang: -5, turns: 1.25, col: PAL.cinMid, w: 0.95, dir: -1 },
    { x: 746, y: 900, rx: 32, ry: 12, ang: 0, turns: 1.15, col: PAL.cinDeep, w: 0.85, dir: 1 },
    // Internal S-scroll cloud bridges
    { x: 525, y: 735, rx: 52, ry: 14, ang: 180, turns: 0.95, col: PAL.vermGlow, w: 1.15, dir: -1 },
    { x: 655, y: 772, rx: 48, ry: 13, ang: 0, turns: 0.95, col: PAL.vermPure, w: 1.05, dir: 1 },
    { x: 545, y: 828, rx: 45, ry: 13, ang: 175, turns: 1.05, col: PAL.vermFiery, w: 1.1, dir: 1 },
    { x: 635, y: 874, rx: 38, ry: 12, ang: 5, turns: 1.0, col: PAL.vermDark, w: 0.95, dir: -1 }
  ];

  for (let s of scrollNodes) {
    // Draw dark lacquer backing halo then crisp vermilion/cinnabar scroll
    drawLacquerVolute(s.x, s.y + 3, s.rx * 1.06, s.ry * 1.08, s.ang, s.turns, PAL.blkVoid, s.w * 1.35, s.dir);
    drawLacquerVolute(s.x, s.y, s.rx, s.ry, s.ang, s.turns, s.col, s.w, s.dir);
  }

  // Layer D: Mirrored Window Reflection broken into sharp calligraphic cloud-scroll streaks
  // Located on the left-center of the reflection around y = 785..865
  let winRefStreaks = [
    { y: 784, x1: 455, x2: 538, col: PAL.specWarm, w: 1.05, curl: -11 },
    { y: 796, x1: 442, x2: 552, col: PAL.specCrisp, w: 1.25, curl: 13 },
    { y: 806, x1: 468, x2: 545, col: PAL.specPeak, w: 0.95, curl: -9 },
    { y: 822, x1: 448, x2: 534, col: PAL.specCrisp, w: 1.15, curl: -12 },
    { y: 833, x1: 462, x2: 556, col: PAL.specWarm, w: 1.0, curl: 10 },
    { y: 846, x1: 482, x2: 540, col: PAL.vermCore, w: 0.85, curl: -8 }
  ];
  for (let wr of winRefStreaks) {
    let mx = (wr.x1 + wr.x2) * 0.5;
    // Gap in the middle for the reflected window mullion!
    brush.set("scroll_blade", wr.col, wr.w);
    brush.spline([
      [wr.x1, wr.y + wr.curl * 0.5, 0.2],
      [ lerp(wr.x1, mx, 0.5), wr.y - 3, 1.0],
      [mx - 6, wr.y + 1, 0.4]
    ], 0.4);
    brush.spline([
      [mx + 6, wr.y - 1, 0.4],
      [lerp(mx, wr.x2, 0.5), wr.y + 3, 1.0],
      [wr.x2, wr.y - wr.curl * 0.6, 0.15]
    ], 0.4);
  }

  // Layer E: Mirrored Ochre Calyx Echo at the bottom tip of the cloud-scroll reflection (y = 975..1048)
  let ochreEchoes = [
    { y: 982, x: 596, w: 68, col: PAL.ochreDark, curl: 1 },
    { y: 996, x: 604, w: 54, col: PAL.ochreMid, curl: -1 },
    { y: 1010, x: 594, w: 42, col: PAL.ochreGold, curl: 1 },
    { y: 1024, x: 602, w: 28, col: PAL.ochreBright, curl: -1 },
    { y: 1038, x: 598, w: 16, col: PAL.ochreDeep, curl: 1 }
  ];
  for (let oe of ochreEchoes) {
    brush.set("scroll_blade", oe.col, 0.85);
    brush.spline([
      [oe.x - oe.w, oe.y + oe.curl * 6, 0.15],
      [oe.x - oe.w * 0.35, oe.y - 3, 0.95],
      [oe.x + oe.w * 0.35, oe.y + 3, 0.95],
      [oe.x + oe.w, oe.y - oe.curl * 7, 0.15]
    ], 0.45);
  }
}

// ============================================================================
// 3. HYPERREAL PERSIMMON BODY
// ============================================================================
function drawPersimmonBody() {
  // Step 1: Crisp Opaque Base Silhouette Wash
  let silPts = [];
  let edgeSteps = 60;
  for (let i = 0; i <= edgeSteps; i++) {
    let v = i / edgeSteps;
    let p = persimmonSurface(-1.0, v);
    silPts.push([p.x, p.y]);
  }
  for (let i = edgeSteps; i >= 0; i--) {
    let v = i / edgeSteps;
    let p = persimmonSurface(1.0, v);
    silPts.push([p.x, p.y]);
  }
  brush.noStroke();
  brush.wash(PAL.cinDeep, 255);
  drawClosedShape(silPts, 0.15);

  // Step 2: Concentric Opaque Volumetric Zones (from dark cinnabar rim to fiery vermilion core)
  let zones = [
    { uMin: -0.92, uMax: 0.82, vMin: 0.04, vMax: 0.95, col: PAL.cinRich },
    { uMin: -0.84, uMax: 0.68, vMin: 0.06, vMax: 0.90, col: PAL.vermDark },
    { uMin: -0.76, uMax: 0.52, vMin: 0.08, vMax: 0.84, col: PAL.vermPure },
    { uMin: -0.68, uMax: 0.36, vMin: 0.11, vMax: 0.76, col: PAL.vermBright },
    { uMin: -0.60, uMax: 0.20, vMin: 0.14, vMax: 0.66, col: PAL.vermFiery },
    { uMin: -0.52, uMax: 0.05, vMin: 0.17, vMax: 0.54, col: PAL.vermGlow }
  ];
  for (let z of zones) {
    let zPts = [];
    let steps = 24;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let ang = t * 360;
      let u = lerp(z.uMin, z.uMax, 0.5 + 0.5 * cos(ang));
      let v = lerp(z.vMin, z.vMax, 0.5 + 0.5 * sin(ang));
      let pt = persimmonSurface(u, v);
      zPts.push([pt.x, pt.y]);
    }
    brush.wash(z.col, 240);
    drawClosedShape(zPts, 0.25);
  }
  brush.noWash();

  // Step 3: Dense Opaque Marker Latitudinal Cross-Contours (building the glossy 3D form)
  let latRings = 72;
  let uSegs = 16;
  for (let r = 1; r < latRings; r++) {
    let v = r / latRings;
    for (let s = 0; s < uSegs; s++) {
      let u0 = map(s, 0, uSegs, -0.98, 0.98);
      let u1 = map(s + 1.35, 0, uSegs, -0.98, 0.98);
      u1 = min(0.98, u1);
      let uMid = (u0 + u1) * 0.5;

      let p0 = persimmonSurface(u0, v);
      let pMid = persimmonSurface(uMid, v);
      let p1 = persimmonSurface(u1, v);

      let col = shadePersimmonSkin(pMid);
      let w = map(sin(v * 180), 0, 1, 0.55, 1.25);
      brush.set("lacquer_marker", col, w);
      brush.spline([
        [p0.x, p0.y, 0.35],
        [pMid.x, pMid.y, 1.0],
        [p1.x, p1.y, 0.35]
      ], 0.35);
    }
  }

  // Step 4: Longitudinal Lobe Marker Contours (following the 4 plump lobes from crown to base)
  let lonStrips = 64;
  let vSegs = 14;
  for (let m = 0; m <= lonStrips; m++) {
    let u = map(m, 0, lonStrips, -0.98, 0.98);
    for (let s = 0; s < vSegs; s++) {
      let v0 = map(s, 0, vSegs, 0.03, 0.98);
      let v1 = min(0.99, map(s + 1.3, 0, vSegs, 0.03, 0.98));
      let vMid = (v0 + v1) * 0.5;

      let p0 = persimmonSurface(u, v0);
      let pMid = persimmonSurface(u, vMid);
      let p1 = persimmonSurface(u, v1);

      let col = shadePersimmonSkin(pMid);
      brush.set("lacquer_marker", col, 0.85);
      brush.spline([
        [p0.x, p0.y, 0.3],
        [pMid.x, pMid.y, 0.95],
        [p1.x, p1.y, 0.3]
      ], 0.35);
    }
  }

  // Step 5: Hyperreal Satin Skin Polish (Skin_blend & fine colored pencil micro-contours)
  for (let i = 0; i < 420; i++) {
    let u = random(-0.95, 0.95);
    let v = random(0.05, 0.95);
    let du = random(0.08, 0.16) * (random() < 0.5 ? 1 : -1);
    let dv = random(-0.04, 0.04);

    let p0 = persimmonSurface(constrain(u - du, -0.98, 0.98), constrain(v - dv, 0.02, 0.98));
    let pMid = persimmonSurface(u, v);
    let p1 = persimmonSurface(constrain(u + du, -0.98, 0.98), constrain(v + dv, 0.02, 0.98));

    let col = shadePersimmonSkin(pMid);
    brush.set("skin_blend", col, random(0.65, 1.15));
    brush.spline([
      [p0.x, p0.y, 0.2],
      [pMid.x, pMid.y, 0.9],
      [p1.x, p1.y, 0.2]
    ], 0.4);
  }

  // Step 6: Subtle Organic Lobe Sulci (the two vertical shallow creases on the front fruit)
  let grooves = [-0.41, 0.44];
  for (let gu of grooves) {
    for (let s = 0; s < 16; s++) {
      let v0 = map(s, 0, 16, 0.08, 0.88);
      let v1 = map(s + 1.2, 0, 16, 0.08, 0.88);
      let p0 = persimmonSurface(gu, v0);
      let p1 = persimmonSurface(gu, v1);
      // Slightly deeper cinnabar inside the shallow groove
      let gCol = (gu < 0) ? PAL.vermDark : PAL.cinDeep;
      brush.set("skin_blend", gCol, 0.75);
      brush.line(p0.x, p0.y, p1.x, p1.y);

      // Catch-light along the lit ridge immediately right of the left groove
      if (gu < 0 && v0 > 0.15 && v0 < 0.65) {
        let pLit0 = persimmonSurface(gu + 0.045, v0);
        let pLit1 = persimmonSurface(gu + 0.045, v1);
        brush.set("needle_detail", PAL.vermGlow, 0.7);
        brush.line(pLit0.x, pLit0.y, pLit1.x, pLit1.y);
      }
    }
  }

  // Step 7: Crisp Outer Rim Precision Contour (razor-sharp glossy silhouette)
  for (let side of [-1.0, 1.0]) {
    let rimPts = [];
    for (let i = 0; i <= 32; i++) {
      let v = i / 32;
      let pt = persimmonSurface(side, v);
      rimPts.push([pt.x, pt.y, 0.7]);
    }
    let rimCol = (side < 0) ? PAL.vermDark : PAL.cinAbyss;
    brush.set("scroll_blade", rimCol, 0.65);
    brush.spline(rimPts, 0.35);
  }
}

// ============================================================================
// 4. FAINT WAXY BLOOM (EPICUTICULAR PRUINA VEIL)
// ============================================================================
function drawWaxyBloom() {
  // Real persimmons have a delicate powdery bloom near the upper crown, along the
  // shallow lobe grooves, and toward the left/right grazing edges.
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.55, 0.18);

  // Soft translucent bloom patches batched by color
  let bloomRegions = [
    // Upper left shoulder below calyx
    { uC: -0.52, vC: 0.16, uR: 0.22, vR: 0.09, col: PAL.bloomPale, op: 22 },
    // Upper center-right shoulder below calyx
    { uC: 0.28, vC: 0.18, uR: 0.26, vR: 0.10, col: PAL.bloomMid, op: 20 },
    // Left grazing rim bloom
    { uC: -0.82, vC: 0.44, uR: 0.12, vR: 0.24, col: PAL.bloomPale, op: 24 },
    // Left lobe sulcus crease bloom
    { uC: -0.41, vC: 0.38, uR: 0.07, vR: 0.22, col: PAL.bloomMid, op: 18 },
    // Right lobe sulcus crease bloom
    { uC: 0.44, vC: 0.42, uR: 0.08, vR: 0.24, col: PAL.bloomDark, op: 18 },
    // Right shoulder grazing bloom
    { uC: 0.74, vC: 0.34, uR: 0.14, vR: 0.18, col: PAL.bloomDark, op: 16 }
  ];

  for (let br of bloomRegions) {
    let pts = [];
    for (let i = 0; i < 18; i++) {
      let a = (i / 18) * 360;
      let jitter = 0.85 + 0.3 * noise(i * 0.5, br.uC * 10);
      let u = constrain(br.uC + cos(a) * br.uR * jitter, -0.96, 0.96);
      let v = constrain(br.vC + sin(a) * br.vR * jitter, 0.05, 0.88);
      let pt = persimmonSurface(u, v);
      pts.push([pt.x, pt.y]);
    }
    brush.fill(br.col, br.op);
    drawClosedShape(pts, 0.3);
  }
  brush.noFill();

  // Micro-stippled waxy bloom spray & fine dry-media skimming
  for (let i = 0; i < 190; i++) {
    // Concentrate bloom near upper crown (v < 0.35), grazing rims (|u| > 0.68), or grooves
    let u = random(-0.92, 0.88);
    let v = random(0.07, 0.78);
    let nearCrown = v < 0.30;
    let nearRim = abs(u) > 0.66;
    let nearGroove = abs(u + 0.41) < 0.08 || abs(u - 0.44) < 0.08;

    // Avoid covering the crisp window reflection zone or the tiny bruise
    let inWindow = (u > -0.60 && u < -0.14 && v > 0.18 && v < 0.48);
    let inBruise = (abs(u - 0.35) < 0.10 && abs(v - 0.61) < 0.08);
    if (inWindow || inBruise) continue;

    if (nearCrown || nearRim || nearGroove || random() < 0.22) {
      let p0 = persimmonSurface(u, v);
      let p1 = persimmonSurface(constrain(u + random(-0.06, 0.06), -0.95, 0.95), constrain(v + random(-0.03, 0.03), 0.06, 0.85));
      let col = (u < 0.15) ? ((random() < 0.5) ? PAL.bloomPale : PAL.bloomMist) : PAL.bloomMid;
      brush.set("wax_bloom", col, random(0.55, 1.1));
      brush.line(p0.x, p0.y, p1.x, p1.y);

      // Delicate dry cpencil micro-scumble for powdery wax texture
      if (random() < 0.45) {
        brush.set("cpencil", col, 0.22);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }
}

// ============================================================================
// 5. THE TINY BRUISE
// ============================================================================
function drawTinyBruise() {
  let uB = 0.35;
  let vB = 0.61;
  let center = persimmonSurface(uB, vB);

  // 1. Subtle oxidized ochre-cinnabar halo around the sunken bruise
  let haloPts = [];
  for (let i = 0; i < 18; i++) {
    let a = (i / 18) * 360;
    let rMod = 0.9 + 0.2 * sin(a * 3);
    let u = uB + cos(a) * 0.072 * rMod;
    let v = vB + sin(a) * 0.048 * rMod;
    let pt = persimmonSurface(u, v);
    haloPts.push([pt.x, pt.y]);
  }
  brush.noStroke();
  brush.wash(PAL.ochreUmber, 195);
  drawClosedShape(haloPts, 0.25);

  // 2. Deep coagulated cinnabar-black core of the bruise
  let corePts = [];
  for (let i = 0; i < 18; i++) {
    let a = (i / 18) * 360;
    let rMod = 0.88 + 0.22 * cos(a * 2 + 40);
    let u = uB + cos(a) * 0.048 * rMod;
    let v = vB + sin(a) * 0.032 * rMod;
    let pt = persimmonSurface(u, v);
    corePts.push([pt.x, pt.y]);
  }
  brush.wash(PAL.cinDark, 245);
  drawClosedShape(corePts, 0.25);

  // 3. Deepest sunken pit (upper-left inside edge of the concavity is in shadow)
  let pitPts = [];
  for (let i = 0; i < 14; i++) {
    let a = (i / 14) * 360;
    let u = (uB - 0.008) + cos(a) * 0.028;
    let v = (vB - 0.005) + sin(a) * 0.019;
    let pt = persimmonSurface(u, v);
    pitPts.push([pt.x, pt.y]);
  }
  brush.wash(PAL.blkVoid, 250);
  drawClosedShape(pitPts, 0.25);
  brush.noWash();

  // 4. Fine radial skin puckering & tension micro-creases around the bruise
  for (let i = 0; i < 22; i++) {
    let a = (i / 22) * 360 + random(-6, 6);
    let pIn = persimmonSurface(uB + cos(a) * 0.022, vB + sin(a) * 0.015);
    let pMid = persimmonSurface(uB + cos(a) * 0.046, vB + sin(a) * 0.031);
    let pOut = persimmonSurface(uB + cos(a) * 0.068, vB + sin(a) * 0.045);

    let creaseCol = (i % 2 === 0) ? PAL.cinAbyss : PAL.cinShadow;
    brush.set("needle_detail", creaseCol, 0.55);
    brush.spline([
      [pIn.x, pIn.y, 0.8],
      [pMid.x, pMid.y, 0.6],
      [pOut.x, pOut.y, 0.1]
    ], 0.3);
  }

  // 5. Crisp specular rim glint on the lower-right lip of the bruise indentation
  // (where the concave dimple turns back toward the upper-left studio window light)
  let lipPts = [];
  for (let a = -25; a <= 115; a += 14) {
    let u = uB + cos(a) * 0.050;
    let v = vB + sin(a) * 0.034;
    let pt = persimmonSurface(u, v);
    lipPts.push([pt.x, pt.y, sin(map(a, -25, 115, 15, 165))]);
  }
  brush.set("needle_detail", PAL.vermCore, 0.75);
  brush.spline(lipPts, 0.35);

  let glintPts = [];
  for (let a = 15; a <= 75; a += 12) {
    let pt = persimmonSurface(uB + cos(a) * 0.049, vB + sin(a) * 0.033);
    glintPts.push([pt.x, pt.y, 0.9]);
  }
  brush.set("needle_detail", PAL.specCrisp, 0.65);
  brush.spline(glintPts, 0.35);
}

// ============================================================================
// 6. CRISP WINDOW REFLECTION
// ============================================================================
// Helper to trace a warped quadrilateral pane on the 3D persimmon surface
function getWarpedPanePoints(u0, u1, v0, v1, stepsPerEdge = 8) {
  let pts = [];
  for (let i = 0; i < stepsPerEdge; i++) {
    let p = persimmonSurface(lerp(u0, u1, i / stepsPerEdge), v0);
    pts.push([p.x, p.y]);
  }
  for (let i = 0; i < stepsPerEdge; i++) {
    let p = persimmonSurface(u1, lerp(v0, v1, i / stepsPerEdge));
    pts.push([p.x, p.y]);
  }
  for (let i = 0; i < stepsPerEdge; i++) {
    let p = persimmonSurface(lerp(u1, u0, i / stepsPerEdge), v1);
    pts.push([p.x, p.y]);
  }
  for (let i = 0; i < stepsPerEdge; i++) {
    let p = persimmonSurface(u0, lerp(v1, v0, i / stepsPerEdge));
    pts.push([p.x, p.y]);
  }
  return pts;
}

function drawCrispWindowReflection() {
  // 4-pane studio window warped across the upper-left cheek of the persimmon
  let panes = [
    // Top-left pane (brightest direct sky light)
    { u0: -0.55, u1: -0.37, v0: 0.21, v1: 0.31, col: PAL.specPeak, rim: PAL.specCrisp },
    // Top-right pane (curving toward the central lobe groove)
    { u0: -0.34, u1: -0.17, v0: 0.21, v1: 0.31, col: PAL.specCrisp, rim: PAL.specWarm },
    // Bottom-left pane
    { u0: -0.55, u1: -0.37, v0: 0.33, v1: 0.44, col: PAL.specCrisp, rim: PAL.specWarm },
    // Bottom-right pane
    { u0: -0.34, u1: -0.17, v0: 0.33, v1: 0.44, col: PAL.specWarm, rim: PAL.vermCore }
  ];

  // 1. Secondary internal cuticle ghost reflection (shifted slightly down-right)
  brush.noStroke();
  for (let p of panes) {
    let ghostPts = getWarpedPanePoints(p.u0 + 0.018, p.u1 + 0.018, p.v0 + 0.014, p.v1 + 0.014, 6);
    brush.wash(PAL.vermCore, 150);
    drawClosedShape(ghostPts, 0.15);
  }

  // 2. Primary razor-sharp window panes
  for (let p of panes) {
    // Warm outer glow edge
    let outerPts = getWarpedPanePoints(p.u0 - 0.006, p.u1 + 0.006, p.v0 - 0.005, p.v1 + 0.005, 8);
    brush.wash(p.rim, 235);
    drawClosedShape(outerPts, 0.12);

    // Crisp high-intensity core pane
    let corePts = getWarpedPanePoints(p.u0, p.u1, p.v0, p.v1, 8);
    brush.wash(p.col, 255);
    drawClosedShape(corePts, 0.1);
  }
  brush.noWash();

  // 3. Precision glossy marker & needle-detail edges + skin pore sparkle along window border
  for (let p of panes) {
    let borderPts = getWarpedPanePoints(p.u0, p.u1, p.v0, p.v1, 6);
    borderPts.push(borderPts[0]);
    let splinePts = borderPts.map(pt => [pt[0], pt[1], 0.85]);
    brush.set("needle_detail", p.col, 0.9);
    brush.spline(splinePts, 0.15);
  }

  // Crisp dark vermilion mullions (window crossbars) cutting cleanly between the 4 panes
  let vMid = 0.32;
  let uMid = -0.355;
  let hBar = [];
  for (let i = 0; i <= 12; i++) {
    let pt = persimmonSurface(lerp(-0.57, -0.15, i / 12), vMid);
    hBar.push([pt.x, pt.y, 0.9]);
  }
  let vBar = [];
  for (let i = 0; i <= 12; i++) {
    let pt = persimmonSurface(uMid, lerp(0.19, 0.46, i / 12));
    vBar.push([pt.x, pt.y, 0.9]);
  }
  brush.set("scroll_blade", PAL.vermBright, 0.95);
  brush.spline(hBar, 0.25);
  brush.spline(vBar, 0.25);
}

// ============================================================================
// 7. THE CALYX (SINGLE OCHRE ACCENT)
// ============================================================================
// Helper to render one leathery, curled botanical sepal with fibrous ochre ridges
function drawCalyxSepal(baseX, baseY, tipX, tipY, ctrl1X, ctrl1Y, ctrl2X, ctrl2Y, halfWidth, isFront) {
  let steps = 20;
  let leftEdge = [];
  let rightEdge = [];
  let spine = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Cubic bezier centerline of the sepal
    let mt = 1 - t;
    let cx = mt * mt * mt * baseX + 3 * mt * mt * t * ctrl1X + 3 * mt * t * t * ctrl2X + t * t * t * tipX;
    let cy = mt * mt * mt * baseY + 3 * mt * mt * t * ctrl1Y + 3 * mt * t * t * ctrl2Y + t * t * t * tipY;

    // Tangent for perpendicular width offset
    let tx = 3 * mt * mt * (ctrl1X - baseX) + 6 * mt * t * (ctrl2X - ctrl1X) + 3 * t * t * (tipX - ctrl2X);
    let ty = 3 * mt * mt * (ctrl1Y - baseY) + 6 * mt * t * (ctrl2Y - ctrl1Y) + 3 * t * t * (tipY - ctrl2Y);
    let tLen = sqrt(tx * tx + ty * ty) || 1;
    let nx = -ty / tLen;
    let ny = tx / tLen;

    // Broad heart-shaped base tapering to a curled dry point
    let wProfile = sin(pow(t, 0.65) * 180) * (1.0 + 0.25 * sin(t * 360));
    let w = halfWidth * wProfile;

    spine.push([cx, cy, t]);
    leftEdge.push([cx + nx * w, cy + ny * w]);
    rightEdge.push([cx - nx * w, cy - ny * w]);
  }

  let polyPts = leftEdge.concat(rightEdge.slice().reverse());

  // 1. Cast shadow of the curled sepal onto the vermilion persimmon crown
  let shadowPts = polyPts.map(p => [p[0] + 4, p[1] + (isFront ? 11 : 6)]);
  brush.noStroke();
  brush.wash(PAL.cinAbyss, 235);
  drawClosedShape(shadowPts, 0.2);

  // 2. Base opaque dark umber-ochre body
  brush.wash(isFront ? PAL.ochreUmber : PAL.ochreAbyss, 255);
  drawClosedShape(polyPts, 0.2);

  // 3. Lit upper plane in rich golden ochre
  let litPts = [];
  for (let i = 0; i <= steps; i++) {
    litPts.push(leftEdge[i]);
  }
  for (let i = steps; i >= 0; i--) {
    let pL = leftEdge[i];
    let pR = rightEdge[i];
    litPts.push([lerp(pL[0], pR[0], 0.62), lerp(pL[1], pR[1], 0.62)]);
  }
  brush.wash(isFront ? PAL.ochreMid : PAL.ochreDeep, 245);
  drawClosedShape(litPts, 0.2);
  brush.noWash();

  // 4. Fibrous longitudinal veins and dry leathery ridges in ochre tones
  let numRidges = 18;
  for (let r = 0; r <= numRidges; r++) {
    let frac = r / numRidges; // 0 (left/lit edge) to 1 (right/shadow edge)
    let ridgePts = [];
    for (let i = 0; i <= steps; i += 2) {
      let pL = leftEdge[i];
      let pR = rightEdge[i];
      let pS = spine[i];
      // Arch slightly across the sepal cross-section
      let arch = sin(frac * 180) * (isFront ? -5 : -3) * sin((i / steps) * 180);
      let rx = lerp(pL[0], pR[0], frac);
      let ry = lerp(pL[1], pR[1], frac) + arch;
      let press = sin((i / steps) * 180) * 0.9 + 0.15;
      ridgePts.push([rx, ry, press]);
    }

    let rCol;
    if (frac < 0.18) rCol = isFront ? PAL.ochrePale : PAL.ochreBright;
    else if (frac < 0.42) rCol = isFront ? PAL.ochreBright : PAL.ochreGold;
    else if (frac < 0.65) rCol = PAL.ochreMid;
    else if (frac < 0.85) rCol = PAL.ochreDark;
    else rCol = PAL.ochreAbyss;

    brush.set("needle_detail", rCol, 0.75);
    brush.spline(ridgePts, 0.35);
  }

  // 5. Crisp curled margin rim & dry tip highlight
  let leftSpline = leftEdge.map((p, idx) => [p[0], p[1], map(idx, 0, steps, 0.4, 1.0)]);
  brush.set("scroll_blade", isFront ? PAL.ochrePale : PAL.ochreGold, 0.65);
  brush.spline(leftSpline, 0.35);

  let rightSpline = rightEdge.map((p, idx) => [p[0], p[1], map(idx, 0, steps, 0.4, 0.9)]);
  brush.set("needle_detail", PAL.ochreAbyss, 0.8);
  brush.spline(rightSpline, 0.35);

  // Curled tip glint in bright pale ochre
  let tipSlice = leftSpline.slice(steps - 6);
  brush.set("needle_detail", PAL.ochreGlint, 0.85);
  brush.spline(tipSlice, 0.35);
}

function drawOchreCalyx() {
  let crownX = CX;
  let crownY = 278;

  // 1. Deep shadow hollow in the crown depression before placing the calyx
  let hollowPts = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    let rx = 74 * (0.9 + 0.15 * cos(a * 4));
    let ry = 22 * (0.9 + 0.15 * sin(a * 4));
    hollowPts.push([crownX + cos(a) * rx, crownY + sin(a) * ry]);
  }
  brush.noStroke();
  brush.wash(PAL.cinAbyss, 245);
  drawClosedShape(hollowPts, 0.25);
  brush.noWash();

  // 2. Back two sepals (receding onto the upper shoulders)
  // Back-left sepal
  drawCalyxSepal(
    crownX - 12, crownY - 4,
    crownX - 124, crownY - 22,
    crownX - 45, crownY - 24,
    crownX - 92, crownY - 32,
    24, false
  );
  // Back-right sepal
  drawCalyxSepal(
    crownX + 12, crownY - 4,
    crownX + 126, crownY - 16,
    crownX + 48, crownY - 22,
    crownX + 94, crownY - 28,
    24, false
  );

  // 3. Central woody receptacle collar (basal ring where stem meets sepals)
  let collarPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    collarPts.push([crownX + cos(a) * 30, crownY - 2 + sin(a) * 11]);
  }
  brush.noStroke();
  brush.wash(PAL.ochreUmber, 255);
  drawClosedShape(collarPts, 0.25);
  brush.noWash();

  // 4. Front two sepals (curling forward and downward over the plump vermilion lobes)
  // Front-right sepal
  drawCalyxSepal(
    crownX + 10, crownY + 2,
    crownX + 108, crownY + 36,
    crownX + 42, crownY + 8,
    crownX + 82, crownY + 38,
    28, true
  );
  // Front-left sepal (closest to the upper-left studio light)
  drawCalyxSepal(
    crownX - 10, crownY + 2,
    crownX - 112, crownY + 32,
    crownX - 44, crownY + 10,
    crownX - 84, crownY + 36,
    29, true
  );

  // 5. Short Woody Stem Stub (Pedicel) rising ceremonially from the center
  let stemBaseX = crownX;
  let stemBaseY = crownY - 2;
  let stemTopX = crownX + 6;
  let stemTopY = 224;

  let stemPoly = [
    [stemBaseX - 16, stemBaseY],
    [stemBaseX - 12, stemBaseY - 26],
    [stemTopX - 11, stemTopY],
    [stemTopX + 11, stemTopY + 3],
    [stemBaseX + 13, stemBaseY - 24],
    [stemBaseX + 17, stemBaseY]
  ];
  brush.noStroke();
  brush.wash(PAL.ochreUmber, 255);
  drawClosedShape(stemPoly, 0.15);
  brush.noWash();

  // Woody bark vertical fibers on the stem
  for (let i = 0; i <= 14; i++) {
    let f = i / 14; // 0 (left/lit) to 1 (right/shadow)
    let bx = lerp(stemBaseX - 15, stemBaseX + 16, f);
    let tx = lerp(stemTopX - 10, stemTopX + 10, f);
    let mx = lerp(bx, tx, 0.5) + sin(f * 180) * 2;
    let by = stemBaseY + sin(f * 180) * 5;
    let ty = lerp(stemTopY, stemTopY + 3, f);

    let sCol = (f < 0.25) ? PAL.ochrePale : ((f < 0.5) ? PAL.ochreGold : ((f < 0.75) ? PAL.ochreDark : PAL.ochreAbyss));
    brush.set("needle_detail", sCol, 0.8);
    brush.spline([
      [bx, by, 0.7],
      [mx, (by + ty) * 0.5, 1.0],
      [tx, ty, 0.7]
    ], 0.3);
  }

  // Cut woody top cross-section of the stem (bark ring & pale ochre pith)
  let cutOuter = [];
  let cutInner = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    cutOuter.push([stemTopX + cos(a) * 11, stemTopY + 1.5 + sin(a) * 4.5]);
    cutInner.push([stemTopX + cos(a) * 7, stemTopY + 1.5 + sin(a) * 2.8]);
  }
  brush.noStroke();
  brush.wash(PAL.ochreDark, 255);
  drawClosedShape(cutOuter, 0.25);
  brush.wash(PAL.ochreBright, 255);
  drawClosedShape(cutInner, 0.25);
  brush.noWash();

  brush.set("needle_detail", PAL.ochreGlint, 0.75);
  brush.arc(stemTopX, stemTopY + 1.5, 9, 160, 340);
  brush.set("needle_detail", PAL.ochreAbyss, 0.7);
  brush.circle(stemTopX, stemTopY + 1.5, 2.2, 0.2);
}

// ============================================================================
// 8. FINAL CEREMONIAL LACQUER POLISH & CONTACT OCCLUSION
// ============================================================================
function drawFinalLacquerPolish() {
  // Razor-sharp contact occlusion line where the persimmon rests on the liquid black lacquer
  let contactPts = [];
  for (let i = 0; i <= 20; i++) {
    let u = map(i, 0, 20, -0.58, 0.58);
    let pt = persimmonSurface(u, 0.995);
    contactPts.push([pt.x, CONTACT_Y + sin(u * 180) * 1.5, 1.0 - abs(u) * 1.1]);
  }
  brush.set("lacquer_marker", PAL.blkVoid, 1.15);
  brush.spline(contactPts, 0.25);

  // Hair-thin liquid meniscus glint right at the left-front contact edge
  let meniscusPts = [];
  for (let i = 0; i <= 10; i++) {
    let u = map(i, 0, 10, -0.44, -0.05);
    let pt = persimmonSurface(u, 0.99);
    meniscusPts.push([pt.x, CONTACT_Y + 1.5, 0.8]);
  }
  brush.set("needle_detail", PAL.vermGlow, 0.75);
  brush.spline(meniscusPts, 0.25);

  // A few silent, ultra-crisp horizontal lacquer surface tension lines flanking the reflection
  let tensionLines = [
    { x1: 250, x2: 385, y: 642, col: PAL.cinShadow },
    { x1: 815, x2: 950, y: 642, col: PAL.cinDark },
    { x1: 210, x2: 335, y: 748, col: PAL.cinDark },
    { x1: 860, x2: 985, y: 762, col: PAL.cinDark },
    { x1: 280, x2: 410, y: 892, col: PAL.cinAbyss },
    { x1: 790, x2: 915, y: 904, col: PAL.cinAbyss }
  ];
  for (let tl of tensionLines) {
    brush.set("needle_detail", tl.col, 0.7);
    brush.line(tl.x1, tl.y, tl.x2, tl.y);
  }
}

// Hyperrealistic Extreme Crop of a Cheetah's Flank
// Reaction-diffusion labyrinthine spots, dense black-brown pen stippling,
// bleeding hair-part edges, directional ochre/sienna/cream fur, and raking side light.

const SEED = 42719;
const RD_W = 210;
const RD_H = 210;

let rdV = new Float32Array(RD_W * RD_H);
let rdGx = new Float32Array(RD_W * RD_H);
let rdGy = new Float32Array(RD_W * RD_H);

// Anatomical rib & flank topography functions
function getRibMetrics(x, y) {
  const nx = x / 1200;
  const ny = y / 1200;

  // Sweeping diagonal arch of the ribcage across the flank
  const u = nx * 0.82 + ny * 0.57;
  const v = -nx * 0.57 + ny * 0.82;

  // Curvature of the ribs bending across the torso barrel
  const barrelCurve = Math.sin(v * 2.6 + 0.4) * 0.14 + (v - 0.1) * (v - 0.1) * 0.22;
  const ribCoord = (u + barrelCurve) * 4.4 * Math.PI * 2.0;

  // Secondary muscular modulation and intercostal troughs
  const nMod = (noise(nx * 2.4 + 10, ny * 2.4 + 20) - 0.5) * 0.85;
  const phase = ribCoord + nMod;

  // Asymmetric rib profile: broader rounded rib crest, tighter intercostal furrow
  const s1 = Math.sin(phase);
  const c1 = Math.cos(phase);
  const s2 = Math.sin(2.0 * phase + 0.4);
  const ribWave = s1 * 0.78 + s2 * 0.22;
  const ribSlope = c1 * 0.78 + Math.cos(2.0 * phase + 0.4) * 0.44;

  // Broad torso cylinder swell (brighter upper-mid flank, deeper lower/right turn)
  const torsoSwell = Math.cos((nx - 0.34) * 1.65) * Math.cos((ny - 0.42) * 1.45);

  // Fine fur lock / tract undulations (cowlicks and parting ridges)
  const tractPhase = (v * 18.0 + Math.sin(u * 9.0) * 1.8) * Math.PI;
  const tractWave = Math.sin(tractPhase + (noise(nx * 6, ny * 6) - 0.5) * 2.2);

  // Raking side light from upper-left grazing across the rib swells
  const rakingRib = constrain(0.52 - ribSlope * 0.38 + ribWave * 0.18, 0, 1);
  const rakingGlobal = constrain(torsoSwell * 0.85 + (1.0 - nx * 0.55 - ny * 0.25) * 0.35, 0, 1);
  const light = constrain(rakingRib * 0.68 + rakingGlobal * 0.32 + tractWave * 0.07, 0, 1);

  // Hair parting lines along intercostal troughs and tract seams
  const ribParting = Math.exp(-Math.pow(Math.sin(phase * 0.5 - 0.35), 2) * 18.0);

  return {
    nx,
    ny,
    u,
    v,
    phase,
    ribWave,
    ribSlope,
    torsoSwell,
    tractWave,
    light,
    ribParting
  };
}

// Base anatomical fur flow angle in degrees
function getFurAngle(x, y, rdSample) {
  const m = getRibMetrics(x, y);

  // Primary fur tract flows sweeping from upper-left/dorsal toward lower-right/ventral
  // flexing rhythmically over each rib swell
  let baseAngle = 33.0
    + Math.sin(m.u * 4.5 + 0.5) * 14.0
    + Math.cos(m.v * 3.8 - 0.3) * 11.0
    + m.ribSlope * 13.5;

  // Multi-scale organic flow variation
  const n1 = (noise(m.nx * 3.2 + 5, m.ny * 3.2 + 8) - 0.5) * 22.0;
  const n2 = (noise(m.nx * 9.5 + 40, m.ny * 9.5 + 12) - 0.5) * 10.0;
  baseAngle += n1 + n2;

  // Hair parting deflection where hair parts at spot boundaries and rib seams
  if (rdSample && rdSample.edge > 0.15) {
    const rad = baseAngle * (Math.PI / 180.0);
    const fx = Math.cos(rad);
    const fy = Math.sin(rad);
    // Cross product between fur direction and spot gradient deflects hairs apart at the edge
    const cross = fx * rdSample.gy - fy * rdSample.gx;
    baseAngle += cross * rdSample.edge * 26.0;
  }

  return baseAngle;
}

// Precompute Gray-Scott Reaction-Diffusion field modulated by the ribcage
function computeReactionDiffusion() {
  const size = RD_W * RD_H;
  let U0 = new Float32Array(size);
  let V0 = new Float32Array(size);
  let U1 = new Float32Array(size);
  let V1 = new Float32Array(size);

  U0.fill(1.0);
  V0.fill(0.0);

  // Seed organic clusters across a jittered lattice so spots both split (mitosis)
  // and coalesce into labyrinthine Turing chains across the ribs
  const spacing = 11.5;
  for (let gy = 0; gy < RD_H; gy += spacing) {
    for (let gx = 0; gx < RD_W; gx += spacing) {
      const cx = gx + random(-3.8, 3.8);
      const cy = gy + random(-3.8, 3.8);
      const r = random(2.1, 3.6);

      // Elongate some seeds along the rib arch to encourage labyrinthine merging
      const stretch = random(1.0, 2.1);
      const ang = (32 + random(-18, 18)) * (Math.PI / 180);
      const ca = Math.cos(ang);
      const sa = Math.sin(ang);

      const ir = Math.ceil(r * stretch + 1);
      for (let dy = -ir; dy <= ir; dy++) {
        for (let dx = -ir; dx <= ir; dx++) {
          const rx = (dx * ca + dy * sa) / stretch;
          const ry = -dx * sa + dy * ca;
          if (rx * rx + ry * ry <= r * r) {
            const ix = (Math.round(cx + dx) + RD_W) % RD_W;
            const iy = (Math.round(cy + dy) + RD_H) % RD_H;
            const idx = iy * RD_W + ix;
            U0[idx] = 0.48 + random(-0.06, 0.06);
            V0[idx] = 0.26 + random(-0.04, 0.04);
          }
        }
      }
    }
  }

  // Spatially varying feed (F) and kill (K) rates across the ribs:
  // Over the main rib swells, parameters favor vermiculate/labyrinthine merging (King Cheetah / Turing stripes-to-spots).
  // Toward the flank hollows, parameters favor splitting dumbbell rosettes and discrete spots.
  const F_map = new Float32Array(size);
  const K_map = new Float32Array(size);

  for (let y = 0; y < RD_H; y++) {
    for (let x = 0; x < RD_W; x++) {
      const px = (x / RD_W) * 1200;
      const py = (y / RD_H) * 1200;
      const m = getRibMetrics(px, py);

      // Labyrinthine zone modulated by rib swells and diagonal dorsal-to-flank gradient
      const labFactor = constrain(
        0.52 + 0.32 * Math.sin(m.u * 3.4 - 0.2) + 0.22 * m.ribWave + (noise(x * 0.035, y * 0.035) - 0.5) * 0.35,
        0,
        1
      );

      // F in [0.034, 0.043], K in [0.0602, 0.0632]
      F_map[y * RD_W + x] = lerp(0.0345, 0.0425, labFactor);
      K_map[y * RD_W + x] = lerp(0.0630, 0.0604, labFactor);
    }
  }

  const Du = 0.16;
  const Dv = 0.078;
  const steps = 460;

  for (let step = 0; step < steps; step++) {
    for (let y = 0; y < RD_H; y++) {
      const ym = ((y - 1 + RD_H) % RD_H) * RD_W;
      const y0 = y * RD_W;
      const yp = ((y + 1) % RD_H) * RD_W;

      for (let x = 0; x < RD_W; x++) {
        const xm = (x - 1 + RD_W) % RD_W;
        const xp = (x + 1) % RD_W;
        const idx = y0 + x;

        const u = U0[idx];
        const v = V0[idx];

        // Anisotropic 9-point Laplacian slightly favoring diagonal fur/rib alignment
        const lapU =
          (U0[y0 + xm] + U0[y0 + xp] + U0[ym + x] + U0[yp + x]) * 0.19 +
          (U0[ym + xm] + U0[yp + xp]) * 0.075 +
          (U0[ym + xp] + U0[yp + xm]) * 0.045 -
          u;

        const lapV =
          (V0[y0 + xm] + V0[y0 + xp] + V0[ym + x] + V0[yp + x]) * 0.19 +
          (V0[ym + xm] + V0[yp + xp]) * 0.075 +
          (V0[ym + xp] + V0[yp + xm]) * 0.045 -
          v;

        const uvv = u * v * v;
        const f = F_map[idx];
        const k = K_map[idx];

        let nu = u + (Du * lapU - uvv + f * (1.0 - u));
        let nv = v + (Dv * lapV + uvv - (f + k) * v);

        U1[idx] = nu < 0 ? 0 : nu > 1 ? 1 : nu;
        V1[idx] = nv < 0 ? 0 : nv > 1 ? 1 : nv;
      }
    }
    let tmpU = U0; U0 = U1; U1 = tmpU;
    let tmpV = V0; V0 = V1; V1 = tmpV;
  }

  // Percentile normalization so the reaction-diffusion spots have guaranteed
  // high-contrast cores and soft bleeding boundaries across the entire sheet
  const sorted = Float32Array.from(V0).sort();
  const vLow = sorted[Math.floor(size * 0.50)];  // Start of soft bleeding hair-part halo
  const vHigh = sorted[Math.floor(size * 0.94)]; // Deepest black-brown stipple core
  const span = Math.max(0.0001, vHigh - vLow);

  for (let i = 0; i < size; i++) {
    let norm = (V0[i] - vLow) / span;
    norm = norm < 0 ? 0 : norm > 1 ? 1 : norm;
    // Smooth S-curve with soft toe for bleeding edges
    rdV[i] = norm * norm * (3.0 - 2.0 * norm);
  }

  // Compute spatial gradients of the normalized RD field for hair-parting physics
  for (let y = 0; y < RD_H; y++) {
    const ym = ((y - 1 + RD_H) % RD_H) * RD_W;
    const y0 = y * RD_W;
    const yp = ((y + 1) % RD_H) * RD_W;
    for (let x = 0; x < RD_W; x++) {
      const xm = (x - 1 + RD_W) % RD_W;
      const xp = (x + 1) % RD_W;
      const idx = y0 + x;
      const gx = (rdV[y0 + xp] - rdV[y0 + xm]) * 0.5;
      const gy = (rdV[yp + x] - rdV[ym + x]) * 0.5;
      const mag = Math.hypot(gx, gy) + 1e-5;
      rdGx[idx] = gx / mag;
      rdGy[idx] = gy / mag;
    }
  }
}

// Bilinear sampler for the reaction-diffusion field with subtle rib-curve warping
function sampleRD(x, y) {
  const m = getRibMetrics(x, y);

  // Subtle organic warp so spots drape naturally over the 3D curvature of the ribs
  const wx = x + m.ribWave * 18.0 + (noise(x * 0.004, y * 0.004) - 0.5) * 28.0;
  const wy = y - m.ribWave * 14.0 + (noise(x * 0.004 + 30, y * 0.004 + 30) - 0.5) * 28.0;

  // Map canvas [-60, 1260] cleanly into the periodic RD grid
  let gx = ((wx + 120) / 1440) * (RD_W - 20) + 10;
  let gy = ((wy + 120) / 1440) * (RD_H - 20) + 10;

  gx = ((gx % RD_W) + RD_W) % RD_W;
  gy = ((gy % RD_H) + RD_H) % RD_H;

  const ix0 = Math.floor(gx);
  const iy0 = Math.floor(gy);
  const fx = gx - ix0;
  const fy = gy - iy0;

  const ix1 = (ix0 + 1) % RD_W;
  const iy1 = (iy0 + 1) % RD_H;

  const i00 = iy0 * RD_W + ix0;
  const i10 = iy0 * RD_W + ix1;
  const i01 = iy1 * RD_W + ix0;
  const i11 = iy1 * RD_W + ix1;

  const v =
    rdV[i00] * (1 - fx) * (1 - fy) +
    rdV[i10] * fx * (1 - fy) +
    rdV[i01] * (1 - fx) * fy +
    rdV[i11] * fx * fy;

  const gradX =
    rdGx[i00] * (1 - fx) * (1 - fy) +
    rdGx[i10] * fx * (1 - fy) +
    rdGx[i01] * (1 - fx) * fy +
    rdGx[i11] * fx * fy;

  const gradY =
    rdGy[i00] * (1 - fx) * (1 - fy) +
    rdGy[i10] * fx * (1 - fy) +
    rdGy[i01] * (1 - fx) * fy +
    rdGy[i11] * fx * fy;

  // Edge intensity peaks in the bleeding transition zone where the hair parts (v ~ 0.18..0.58)
  const edge = Math.max(0, 1.0 - Math.pow((v - 0.36) / 0.28, 2));

  return { v, gx: gradX, gy: gradY, edge, metrics: m };
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(SEED);
  noiseSeed(SEED);

  // Precompute the reaction-diffusion spot field
  computeReactionDiffusion();

  // Register custom hyperrealistic fur & stippling brushes
  // (Created after scaleBrushes(3), so weights are in direct 1200x1200 canvas units)
  brush.add("fur_under", {
    type: "default",
    weight: 1.55,
    scatter: 0.35,
    sharpness: 0.45,
    grain: 0.65,
    opacity: 145,
    spacing: 0.32,
    pressure: [0.3, 1.0, 0.15],
    noise: 0.45
  });

  brush.add("fur_guard", {
    type: "default",
    weight: 0.95,
    scatter: 0.12,
    sharpness: 0.82,
    grain: 0.78,
    opacity: 205,
    spacing: 0.24,
    pressure: [0.35, 1.0, 0.04],
    noise: 0.3
  });

  brush.add("fur_raking_tip", {
    type: "default",
    weight: 0.72,
    scatter: 0.06,
    sharpness: 0.92,
    grain: 0.85,
    opacity: 235,
    spacing: 0.2,
    pressure: [0.15, 0.95, 0.02],
    noise: 0.2
  });

  brush.add("stipple_bleed", {
    type: "default",
    weight: 1.85,
    scatter: 0.85,
    sharpness: 0.32,
    grain: 0.75,
    opacity: 135,
    spacing: 0.42,
    pressure: [0.5, 1.15, 0.4],
    noise: 0.6
  });

  brush.add("stipple_quill", {
    type: "default",
    weight: 1.05,
    scatter: 0.22,
    sharpness: 0.9,
    grain: 0.88,
    opacity: 230,
    spacing: 0.35,
    pressure: [0.85, 1.05, 0.75],
    noise: 0.25
  });

  // Register custom vector field following the cheetah's rib topography
  brush.addField("cheetahFlank", (t, field) => {
    const cols = field.length;
    const rows = field[0].length;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        const px = (c / (cols - 1)) * 1200;
        const py = (r / (rows - 1)) * 1200;
        const s = sampleRD(px, py);
        field[c][r] = getFurAngle(px, py, s);
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm sunlit parchment-ochre base skin/undercoat tone
  background("#dfba84");

  // =========================================================================
  // PASS 1: WATERCOLOR & WASH UNDERPAINTING (RIB SWELLS & BLEEDING SPOT HALOS)
  // =========================================================================
  brush.noStroke();

  // 1A. Rib trough & crest atmospheric washes batched by color
  const washBatches = [
    { color: "#9c4b16", opacity: 62, bleed: 0.38, polys: [] }, // Deep raw sienna intercostal troughs
    { color: "#c97a2b", opacity: 58, bleed: 0.34, polys: [] }, // Warm ochre mid-rib transitions
    { color: "#f5dfb8", opacity: 68, bleed: 0.35, polys: [] }, // Raking light cream rib crests
    { color: "#4d2712", opacity: 75, bleed: 0.42, polys: [] }, // Soft bleeding sepia spot halos
    { color: "#261107", opacity: 90, bleed: 0.32, polys: [] }  // Deep bistre spot under-wash
  ];

  // Generate ribbon polygons along the rib waves for luminous undercoat depth
  const gridStep = 85;
  for (let y = -40; y < 1240; y += gridStep) {
    for (let x = -40; x < 1240; x += gridStep) {
      const cx = x + random(-18, 18);
      const cy = y + random(-18, 18);
      const s = sampleRD(cx, cy);
      const m = s.metrics;
      const ang = getFurAngle(cx, cy, s) * (Math.PI / 180);

      const rx = Math.cos(ang);
      const ry = Math.sin(ang);
      const px = -ry;
      const py = rx;

      const len = random(65, 110);
      const wid = random(36, 62);

      const pts = [];
      for (let k = 0; k < 6; k++) {
        const a = (k / 6) * Math.PI * 2;
        const ca = Math.cos(a) * len;
        const sa = Math.sin(a) * wid;
        pts.push([cx + rx * ca + px * sa, cy + ry * ca + py * sa]);
      }

      if (m.light < 0.38) {
        washBatches[0].polys.push(pts);
      } else if (m.light > 0.66) {
        washBatches[2].polys.push(pts);
      } else {
        washBatches[1].polys.push(pts);
      }
    }
  }

  // Sample reaction-diffusion spot clusters for soft bleeding ink under-washes
  const spotWashStep = 34;
  for (let y = -20; y < 1220; y += spotWashStep) {
    for (let x = -20; x < 1220; x += spotWashStep) {
      const cx = x + random(-8, 8);
      const cy = y + random(-8, 8);
      const s = sampleRD(cx, cy);
      if (s.v > 0.34) {
        const ang = getFurAngle(cx, cy, s) * (Math.PI / 180);
        const rx = Math.cos(ang);
        const ry = Math.sin(ang);
        const px = -ry;
        const py = rx;

        const rLong = map(s.v, 0.34, 1.0, 18, 34) * random(0.85, 1.2);
        const rShort = map(s.v, 0.34, 1.0, 12, 24) * random(0.85, 1.2);
        const pts = [];
        for (let k = 0; k < 6; k++) {
          const a = (k / 6) * Math.PI * 2;
          const ca = Math.cos(a) * rLong;
          const sa = Math.sin(a) * rShort;
          pts.push([cx + rx * ca + px * sa, cy + ry * ca + py * sa]);
        }

        if (s.v > 0.66 && random() < 0.55) {
          washBatches[4].polys.push(pts);
        } else if (random() < 0.65) {
          washBatches[3].polys.push(pts);
        }
      }
    }
  }

  // Render watercolor batches
  for (let b of washBatches) {
    brush.fill(b.color, b.opacity);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.55, 0.28);
    for (let pts of b.polys) {
      brush.beginShape(0.45);
      for (let p of pts) {
        brush.vertex(p[0], p[1]);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();

  // =========================================================================
  // PASS 2: DEEP UNDERCOAT & HAIR-PARTING ROOT LAYER
  // =========================================================================
  // Thousands of soft directional undercoat strokes establishing the velvety depth
  // of raw sienna, burnt ochre, warm umber, and dark sepia roots where the hair parts.
  const underBuckets = [
    { brush: "fur_under", color: "#5e280d", weight: 1.15, lines: [] }, // Deep intercostal & parting root umber
    { brush: "fur_under", color: "#873e14", weight: 1.10, lines: [] }, // Rich raw sienna shadow undercoat
    { brush: "fur_under", color: "#ad5a1e", weight: 1.05, lines: [] }, // Warm burnt ochre undercoat
    { brush: "fur_under", color: "#cf8131", weight: 1.00, lines: [] }, // Golden ochre mid-undercoat
    { brush: "fur_under", color: "#e6aa58", weight: 0.95, lines: [] }, // Warm buff lit undercoat
    { brush: "fur_under", color: "#3b1d0e", weight: 1.15, lines: [] }, // Bleeding spot-edge dark bistre fur
    { brush: "fur_under", color: "#1f0e06", weight: 1.10, lines: [] }  // Deep spot interior base fur
  ];

  const underStep = 14;
  for (let y = -35; y < 1235; y += underStep) {
    for (let x = -35; x < 1235; x += underStep) {
      const px = x + random(-6.5, 6.5);
      const py = y + random(-6.5, 6.5);
      const s = sampleRD(px, py);
      const m = s.metrics;

      const ang = getFurAngle(px, py, s) + random(-5, 5);
      const rad = ang * (Math.PI / 180);
      const len = random(18, 32);

      // Push roots slightly away from the parting line to expose the skin/stipple crease
      const partShift = (s.edge > 0.35 ? 2.5 : 0) + (m.ribParting > 0.6 ? 2.0 : 0);
      const sx = px + s.gx * partShift;
      const sy = py + s.gy * partShift;
      const ex = sx + Math.cos(rad) * len;
      const ey = sy + Math.sin(rad) * len;

      let bIdx = 2;
      if (s.v > 0.58) {
        bIdx = 6;
      } else if (s.v > 0.26) {
        bIdx = 5;
      } else {
        const lVal = m.light + random(-0.1, 0.1) - m.ribParting * 0.22;
        if (lVal < 0.26) bIdx = 0;
        else if (lVal < 0.44) bIdx = 1;
        else if (lVal < 0.62) bIdx = 2;
        else if (lVal < 0.78) bIdx = 3;
        else bIdx = 4;
      }

      underBuckets[bIdx].lines.push([sx, sy, ex, ey]);
    }
  }

  for (let b of underBuckets) {
    brush.set(b.brush, b.color, b.weight);
    for (let ln of b.lines) {
      brush.line(ln[0], ln[1], ln[2], ln[3]);
    }
  }

  // =========================================================================
  // PASS 3: OBSESSIVE BLACK-BROWN PEN STIPPLING & BLEEDING SPOT EDGES
  // =========================================================================
  // The reaction-diffusion spots are built from thousands of dense pen stipples
  // and micro-ink ticks that bleed softly where the fur parts at the periphery.
  const stippleBuckets = [
    { brush: "stipple_bleed", color: "#572e17", weight: 1.05, lines: [] }, // Outer bleeding raw-umber halo
    { brush: "stipple_bleed", color: "#3d1e0e", weight: 0.95, lines: [] }, // Soft bleeding sepia hair-part edge
    { brush: "stipple_quill", color: "#2e160a", weight: 0.90, lines: [] }, // Outer pen stippling (warm bistre)
    { brush: "stipple_quill", color: "#1f0d05", weight: 0.85, lines: [] }, // Dense black-brown pen stippling
    { brush: "stipple_quill", color: "#120702", weight: 0.82, lines: [] }, // Obsessive pitch-brown core stippling
    { brush: "rotring",       color: "#180a04", weight: 0.42, lines: [] }, // Crisp technical-pen micro-stipples & root ticks
    { brush: "rotring",       color: "#381c0d", weight: 0.36, lines: [] }  // Feathered parting hair-root ticks
  ];

  // Dense multi-pass stratified sampling across the entire reaction-diffusion field
  const stippleStep = 6.2;
  for (let y = -20; y < 1220; y += stippleStep) {
    for (let x = -20; x < 1220; x += stippleStep) {
      const px = x + random(-3.0, 3.0);
      const py = y + random(-3.0, 3.0);
      const s = sampleRD(px, py);

      // Skip pure tawny areas far from spot boundaries
      if (s.v < 0.16) continue;

      const furAng = getFurAngle(px, py, s);
      const furRad = furAng * (Math.PI / 180);

      // Zone 1: Soft bleeding edge where the hair parts (0.16 <= v < 0.42)
      if (s.v < 0.42) {
        const bleedProb = map(s.v, 0.16, 0.42, 0.12, 0.82);
        if (random() < bleedProb) {
          // Stipples and tiny parted root-ticks feathering along the parting seam
          const tickLen = random(1.6, 4.2);
          const jitterAng = furRad + random(-0.45, 0.45);
          const x2 = px + Math.cos(jitterAng) * tickLen;
          const y2 = py + Math.sin(jitterAng) * tickLen;

          if (s.v < 0.28) {
            stippleBuckets[0].lines.push([px, py, x2, y2]);
          } else {
            stippleBuckets[1].lines.push([px, py, x2, y2]);
          }

          // Crisp micro-pen stipple dot or parted root hair at the bleeding boundary
          if (random() < 0.65) {
            const dLen = random(1.0, 2.6);
            const sx = px + random(-2.2, 2.2);
            const sy = py + random(-2.2, 2.2);
            stippleBuckets[6].lines.push([
              sx,
              sy,
              sx + Math.cos(furRad) * dLen,
              sy + Math.sin(furRad) * dLen
            ]);
          }
        }
      }
      // Zone 2: Mid-to-outer spot cluster (0.42 <= v < 0.68)
      else if (s.v < 0.68) {
        // Primary stipple dot
        const d1 = random(1.1, 2.5);
        const a1 = furRad + random(-0.6, 0.6);
        const bIdx = s.v < 0.54 ? 2 : 3;
        stippleBuckets[bIdx].lines.push([
          px,
          py,
          px + Math.cos(a1) * d1,
          py + Math.sin(a1) * d1
        ]);

        // Secondary tightly packed pen stipple for obsessive grain
        if (random() < 0.78) {
          const ox = px + random(-2.8, 2.8);
          const oy = py + random(-2.8, 2.8);
          const d2 = random(0.9, 2.2);
          stippleBuckets[5].lines.push([
            ox,
            oy,
            ox + Math.cos(furRad) * d2,
            oy + Math.sin(furRad) * d2
          ]);
        }
      }
      // Zone 3: Deep labyrinthine reaction-diffusion core (v >= 0.68)
      else {
        // Leave subtle microscopic breathing lines along rib-partings so the spot reads as parted fur + skin
        const partGap = s.metrics.ribParting > 0.82 && random() < 0.25;
        if (!partGap) {
          const d1 = random(1.2, 2.8);
          const a1 = furRad + random(-0.5, 0.5);
          stippleBuckets[4].lines.push([
            px,
            py,
            px + Math.cos(a1) * d1,
            py + Math.sin(a1) * d1
          ]);

          // Double-density stipple cluster in the deepest core
          const ox = px + random(-2.5, 2.5);
          const oy = py + random(-2.5, 2.5);
          const d2 = random(0.9, 2.0);
          const a2 = furRad + random(-0.8, 0.8);
          stippleBuckets[3].lines.push([
            ox,
            oy,
            ox + Math.cos(a2) * d2,
            oy + Math.sin(a2) * d2
          ]);

          if (random() < 0.65) {
            const tx = px + random(-2.2, 2.2);
            const ty = py + random(-2.2, 2.2);
            const d3 = random(0.8, 1.8);
            stippleBuckets[5].lines.push([
              tx,
              ty,
              tx + Math.cos(furRad) * d3,
              ty + Math.sin(furRad) * d3
            ]);
          }
        }
      }
    }
  }

  for (let b of stippleBuckets) {
    brush.set(b.brush, b.color, b.weight);
    for (let ln of b.lines) {
      brush.line(ln[0], ln[1], ln[2], ln[3]);
    }
  }

  // =========================================================================
  // PASS 4: DIRECTIONAL GUARD HAIRS & MID-COAT (OCHRE, RAW SIENNA, CREAM)
  // =========================================================================
  // Thousands of tapered individual hairs curving across the ribs, parting around
  // the stippled spots, with golden hairs overlapping spot leading edges and dark
  // espresso hairs growing out of the trailing edges of the spots.
  const furBuckets = [
    { brush: "fur_guard", color: "#6e3110", weight: 0.92, lines: [] }, // 0: Deep raw sienna / burnt umber shadow hair
    { brush: "fur_guard", color: "#964818", weight: 0.90, lines: [] }, // 1: Rich raw sienna flank hair
    { brush: "fur_guard", color: "#b86422", weight: 0.88, lines: [] }, // 2: Deep warm ochre hair
    { brush: "fur_guard", color: "#d1802f", weight: 0.86, lines: [] }, // 3: Classic cheetah golden ochre hair
    { brush: "fur_guard", color: "#e39b44", weight: 0.85, lines: [] }, // 4: Bright sunlit ochre hair
    { brush: "fur_guard", color: "#efb867", weight: 0.84, lines: [] }, // 5: Warm buff-cream transition hair
    { brush: "fur_guard", color: "#f7cf8b", weight: 0.82, lines: [] }, // 6: Soft cream flank hair
    { brush: "cpencil",   color: "#7d3a13", weight: 0.55, lines: [] }, // 7: Dry tactile pencil grain (raw sienna)
    { brush: "cpencil",   color: "#c7762a", weight: 0.52, lines: [] }, // 8: Dry tactile pencil grain (warm ochre)
    { brush: "fur_guard", color: "#291308", weight: 0.82, lines: [] }, // 9: Dark brown-black spot guard hairs
    { brush: "fur_guard", color: "#472512", weight: 0.80, lines: [] }  // 10: Warm espresso parted edge hairs
  ];

  const guardStep = 10.2;
  for (let y = -30; y < 1230; y += guardStep) {
    for (let x = -30; x < 1230; x += guardStep) {
      const rx = x + random(-4.6, 4.6);
      const ry = y + random(-4.6, 4.6);
      const s = sampleRD(rx, ry);
      const m = s.metrics;

      // Where the hair parts (along spot boundaries and intercostal creases),
      // roots shift slightly away from the parting centerline so the soft bleeding
      // stippled edge remains visible between parting locks of hair!
      let rootX = rx;
      let rootY = ry;
      if (s.edge > 0.42) {
        const pushDir = s.v < 0.36 ? -1.0 : 1.0;
        rootX += s.gx * pushDir * 2.8;
        rootY += s.gy * pushDir * 2.8;
      }

      const ang1 = getFurAngle(rootX, rootY, s) + random(-3.8, 3.8);
      const rad1 = ang1 * (Math.PI / 180);

      // Hairs are slightly shorter inside the stippled spot cores so the pen stippling
      // dominates the spot texture, and longer/flowing across the golden ochre swells
      const isSpotCore = s.v > 0.50;
      const totalLen = isSpotCore ? random(11, 19) : random(18, 31);
      const halfLen = totalLen * 0.52;

      const midX = rootX + Math.cos(rad1) * halfLen;
      const midY = rootY + Math.sin(rad1) * halfLen;

      // Slight natural arch along the hair shaft toward the local clump convergence
      const clumpBend = Math.sin(m.u * 28.0 + m.v * 34.0) * 4.5 + m.ribSlope * 3.0;
      const rad2 = (ang1 + clumpBend) * (Math.PI / 180);
      const tipX = midX + Math.cos(rad2) * (totalLen - halfLen);
      const tipY = midY + Math.sin(rad2) * (totalLen - halfLen);

      if (s.v > 0.52) {
        // Inside the spots: sparse, sleek dark hairs that part to reveal the dense stippling beneath
        if (random() < 0.58) {
          const bIdx = s.v > 0.68 ? 9 : 10;
          furBuckets[bIdx].lines.push([rootX, rootY, midX, midY]);
          furBuckets[bIdx].lines.push([midX, midY, tipX, tipY]);
        }
      } else if (s.v > 0.34) {
        // Bleeding hair-part transition zone:
        // Hairs rooted just outside the spot project golden/sienna tips over the bleeding edge,
        // while hairs rooted just inside splay dark sepia shafts outward.
        if (random() < 0.48) {
          furBuckets[10].lines.push([rootX, rootY, midX, midY]);
          furBuckets[10].lines.push([midX, midY, tipX, tipY]);
        } else {
          const lTone = m.light + random(-0.08, 0.08);
          const bIdx = lTone < 0.42 ? 1 : lTone < 0.65 ? 3 : 5;
          furBuckets[bIdx].lines.push([rootX, rootY, midX, midY]);
          furBuckets[bIdx].lines.push([midX, midY, tipX, tipY]);
        }
      } else {
        // Tawny coat (warm ochre, raw sienna, and cream modulated by rib curvature and raking light)
        const ventFactor = constrain((m.ny - 0.55) * 0.65 - (m.nx - 0.4) * 0.35, -0.15, 0.28);
        const tone = m.light * 0.78 + ventFactor + (noise(rx * 0.015, ry * 0.015) - 0.5) * 0.24 - m.ribParting * 0.16;

        let bIdx = 3;
        if (tone < 0.24) bIdx = 0;
        else if (tone < 0.37) bIdx = 1;
        else if (tone < 0.49) bIdx = 2;
        else if (tone < 0.61) bIdx = 3;
        else if (tone < 0.72) bIdx = 4;
        else if (tone < 0.83) bIdx = 5;
        else bIdx = 6;

        furBuckets[bIdx].lines.push([rootX, rootY, midX, midY]);
        furBuckets[bIdx].lines.push([midX, midY, tipX, tipY]);

        // Add dry-media colored-pencil micro-texture hairs for hyperrealistic tooth
        if (random() < 0.28) {
          const pIdx = tone < 0.48 ? 7 : 8;
          furBuckets[pIdx].lines.push([rootX, rootY, tipX, tipY]);
        }
      }
    }
  }

  for (let b of furBuckets) {
    brush.set(b.brush, b.color, b.weight);
    for (let ln of b.lines) {
      brush.line(ln[0], ln[1], ln[2], ln[3]);
    }
  }

  // =========================================================================
  // PASS 5: RAKING SIDE LIGHT PICKING OUT EACH HAIR TIP
  // =========================================================================
  // Grazing side light from the upper-left catches the arched distal tips of the
  // guard hairs across the rib crests, spot borders, and dark espresso fur tufts.
  const tipBuckets = [
    { brush: "fur_raking_tip", color: "#5e3920", weight: 0.72, lines: [] }, // 0: Raking bronze-espresso glint on dark spot hair tips
    { brush: "fur_raking_tip", color: "#8c5832", weight: 0.70, lines: [] }, // 1: Warm amber-copper rim light on spot-edge hair tips
    { brush: "fur_raking_tip", color: "#e8a449", weight: 0.75, lines: [] }, // 2: Golden ochre lit tips in mid-shadow ribs
    { brush: "fur_raking_tip", color: "#f6c976", weight: 0.76, lines: [] }, // 3: Sunlit warm gold hair tips
    { brush: "fur_raking_tip", color: "#fce2a6", weight: 0.78, lines: [] }, // 4: Luminous cream hair tips
    { brush: "fur_raking_tip", color: "#fff5d6", weight: 0.74, lines: [] }, // 5: Incandescent ivory raking highlight on rib crests
    { brush: "rotring",        color: "#fff9e6", weight: 0.32, lines: [] }  // 6: Razor-sharp specular filament on highest hair tips
  ];

  const tipStep = 11.5;
  for (let y = -20; y < 1220; y += tipStep) {
    for (let x = -20; x < 1220; x += tipStep) {
      const px = x + random(-4.8, 4.8);
      const py = y + random(-4.8, 4.8);
      const s = sampleRD(px, py);
      const m = s.metrics;

      // Raking light probability increases strongly on the lit slope of each rib swell
      // and along the arched edges where the hair parts
      const rakingIntensity = constrain(
        m.light * 1.08 + s.edge * 0.22 - m.ribParting * 0.15 + (noise(px * 0.025, py * 0.025) - 0.5) * 0.25,
        0,
        1
      );

      if (random() > rakingIntensity * 0.92 + 0.12) continue;

      const ang = getFurAngle(px, py, s) + random(-3.2, 3.2);
      const rad = ang * (Math.PI / 180);

      // Draw only the distal arched tip of the hair catching the grazing light
      const tipLen = s.v > 0.45 ? random(7.5, 13.5) : random(10.5, 20.0);
      const midLen = tipLen * 0.55;

      // Slight upward flick toward the grazing light
      const flickRad = (ang - 3.5) * (Math.PI / 180);
      const mx = px + Math.cos(rad) * midLen;
      const my = py + Math.sin(rad) * midLen;
      const tx = mx + Math.cos(flickRad) * (tipLen - midLen);
      const ty = my + Math.sin(flickRad) * (tipLen - midLen);

      if (s.v > 0.50) {
        // Grazing side light picking out individual dark hair tips inside the stippled spots
        if (rakingIntensity > 0.46) {
          const bIdx = rakingIntensity > 0.68 ? 1 : 0;
          tipBuckets[bIdx].lines.push([px, py, mx, my]);
          tipBuckets[bIdx].lines.push([mx, my, tx, ty]);
        }
      } else if (s.v > 0.28) {
        // Golden and cream hairs overhanging the bleeding stippled spot edges,
        // creating dramatic hyperrealistic contrast against the black-brown stippling
        const bIdx = rakingIntensity > 0.65 ? 4 : rakingIntensity > 0.45 ? 3 : 1;
        tipBuckets[bIdx].lines.push([px, py, mx, my]);
        tipBuckets[bIdx].lines.push([mx, my, tx, ty]);

        if (rakingIntensity > 0.72 && random() < 0.45) {
          tipBuckets[6].lines.push([mx, my, tx, ty]);
        }
      } else {
        // Tawny coat hair tips picked out by the raking side light across the rib swells
        let bIdx = 2;
        if (rakingIntensity < 0.42) bIdx = 2;
        else if (rakingIntensity < 0.58) bIdx = 3;
        else if (rakingIntensity < 0.74) bIdx = 4;
        else bIdx = 5;

        tipBuckets[bIdx].lines.push([px, py, mx, my]);
        tipBuckets[bIdx].lines.push([mx, my, tx, ty]);

        // Crisp finest highlight at the very tip of the sun-struck guard hairs
        if (rakingIntensity > 0.70 && random() < 0.52) {
          tipBuckets[6].lines.push([mx, my, tx, ty]);
        }
      }
    }
  }

  for (let b of tipBuckets) {
    brush.set(b.brush, b.color, b.weight);
    for (let ln of b.lines) {
      brush.line(ln[0], ln[1], ln[2], ln[3]);
    }
  }

  // =========================================================================
  // PASS 6: FINAL MICRO-STIPPLE & PARTED HAIR ACCENTS FOR TACTILE PRECISION
  // =========================================================================
  // A final pass of razor-sharp black-brown ink stipples in the deepest spot cores
  // and stray sunlit guard hairs arching across spot channels.
  brush.set("rotring", "#100602", 0.38);
  for (let i = 0; i < 2200; i++) {
    const px = random(-10, 1210);
    const py = random(-10, 1210);
    const s = sampleRD(px, py);
    if (s.v > 0.56) {
      const a = getFurAngle(px, py, s) * (Math.PI / 180) + random(-0.7, 0.7);
      const d = random(0.8, 2.0);
      brush.line(px, py, px + Math.cos(a) * d, py + Math.sin(a) * d);
    }
  }

  // Stray sunlit cream guard hairs arching over the parted spot boundaries
  brush.set("fur_raking_tip", "#fff6db", 0.66);
  for (let i = 0; i < 650; i++) {
    const px = random(-10, 1210);
    const py = random(-10, 1210);
    const s = sampleRD(px, py);
    if (s.edge > 0.55 && s.metrics.light > 0.45) {
      const ang = getFurAngle(px, py, s) + random(-6, 6);
      const rad = ang * (Math.PI / 180);
      const len = random(12, 22);
      brush.line(px, py, px + Math.cos(rad) * len, py + Math.sin(rad) * len);
    }
  }

  noLoop();
}

// Hyperreal Steel-Engraved Strawberry Postage Stamp
// Rendered with p5.js v2 + p5.brush in WEBGL mode

const PAL = {
  envBase: "#e5dac3",
  envWarm: "#dccfb4",
  envDark: "#cbbba0",
  envFiber: "#b5a487",
  envRule: "#d2c4a8",
  shadowOuter: "#9c8d74",
  shadowCore: "#5c4f3c",
  stampPaper: "#fbf9f0",
  stampWarm: "#f4f0e2",
  stampEdgeLit: "#ded8c8",
  stampEdgeShade: "#8a7f6c",
  carmine: "#c9162b",
  carmineDeep: "#960b1c",
  carmineBright: "#e3243b",
  carmineWash: "#d41930",
  ink: "#141210",
  inkSoft: "#2c2824",
  inkMid: "#4a433d",
  cancelInk: "#1c1a18"
};

let achenes = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);

  // Scale built-in brushes first
  brush.scaleBrushes(3);

  // Custom high-precision steel-engraving & philatelic brushes
  brush.add("burin", {
    type: "default",
    weight: 0.72,
    scatter: 0.015,
    sharpness: 0.94,
    grain: 2,
    opacity: 248,
    spacing: 0.11,
    pressure: [0.22, 1.35, 0.22],
    noise: 0.12
  });

  brush.add("burin_fine", {
    type: "default",
    weight: 0.42,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 1,
    opacity: 235,
    spacing: 0.1,
    pressure: [0.25, 1.15, 0.25],
    noise: 0.08
  });

  brush.add("burin_bold", {
    type: "default",
    weight: 1.08,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 3,
    opacity: 255,
    spacing: 0.11,
    pressure: [0.35, 1.4, 0.35],
    noise: 0.12
  });

  brush.add("carmine_burin", {
    type: "default",
    weight: 0.95,
    scatter: 0.04,
    sharpness: 0.85,
    grain: 4,
    opacity: 215,
    spacing: 0.12,
    pressure: [0.3, 1.3, 0.3],
    noise: 0.18
  });

  brush.add("trichome", {
    type: "default",
    weight: 0.34,
    scatter: 0.01,
    sharpness: 0.97,
    grain: 1,
    opacity: 245,
    spacing: 0.09,
    pressure: [1.15, 0.65, 0.08],
    noise: 0.08
  });

  brush.add("cancel_rubber", {
    type: "default",
    weight: 2.35,
    scatter: 0.16,
    sharpness: 0.62,
    grain: 16,
    opacity: 215,
    spacing: 0.14,
    pressure: [0.85, 1.08, 0.85],
    noise: 0.55
  });

  initAcheneLattice();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.envBase);

  // 1. Cream Envelope Paper Texture & Subtle Fibers
  drawEnvelopeBackground();

  // Stamp sits slightly askew on the cream envelope paper
  const stampCX = 596;
  const stampCY = 594;
  const stampAngle = -3.1;
  const stampW = 696;
  const stampH = 836;

  push();
  translate(stampCX, stampCY);
  rotate(stampAngle);

  // 2. Perforated White Stamp Body & Realistic Cast Shadow
  const perfPts = buildPerforatedContour(stampW, stampH, 34.8, 11.4);
  drawStampBodyAndShadow(perfPts, stampW, stampH);

  // 3. Engraved Frame Lines & Philatelic Ruled Sky Ground
  const frameW = 574;
  const frameH = 714;
  drawEngravedFrameAndGround(frameW, frameH);

  // 4. Off-Register Carmine Spot Colour Plate (shifted bottom-left)
  const regDX = -11.5;
  const regDY = 8.5;
  drawOffRegisterCarminePlate(regDX, regDY);

  // 5. Dense Steel-Engraved Black Cross-Hatching on the Berry
  drawStrawberryEngraving();

  // 6. Precise Sunken Seeds (Achenes) with Rim Highlights
  drawAllAchenes(regDX, regDY);

  // 7. Hairy Calyx (Crown of Sepals, Stem & Fine Trichomes)
  drawHairyCalyx();

  // 8. Engraved Denomination Numeral ("25c") & Country Name ("HELVETIA")
  drawStampTypography(frameW, frameH, regDX, regDY);

  pop();

  // 9. Wavy Black Postmark Cancellation Slashing Across Corner
  drawWavyPostmarkCancellation(stampCX, stampCY, stampAngle, stampW, stampH);

  noLoop();
}

// =============================================================================
// 1. CREAM ENVELOPE PAPER BACKGROUND
// =============================================================================
function drawEnvelopeBackground() {
  brush.noStroke();
  brush.fill(PAL.envWarm, 55);
  brush.fillBleed(0.35, "in");
  brush.fillTexture(0.45, 0.2);
  brush.rect(0, 0, width, height);

  // Vignette warmth at edges
  brush.fill(PAL.envDark, 42);
  brush.rect(0, 0, width, 130);
  brush.rect(0, height - 140, width, 140);
  brush.rect(0, 0, 130, height);
  brush.rect(width - 140, 0, 140, height);
  brush.noFill();

  // Laid paper vergé lines (subtle horizontal wire marks)
  brush.set("2H", PAL.envRule, 0.35);
  for (let y = 8; y < height; y += 7.5) {
    let yOff = y + sin(y * 3.7) * 0.4;
    brush.line(0, yOff, width, yOff + random(-0.5, 0.5));
  }

  // Vertical chain lines every 110px
  brush.set("2H", PAL.envDark, 0.28);
  for (let x = 65; x < width; x += 110) {
    brush.line(x, 0, x, height);
  }

  // Scattered natural cotton/rag fibers in the cream envelope paper
  for (let i = 0; i < 240; i++) {
    let fx = random(20, width - 20);
    let fy = random(20, height - 20);
    let len = random(4, 16);
    let ang = random(360);
    let col = i % 3 === 0 ? PAL.envFiber : (i % 2 === 0 ? PAL.envDark : "#f5ebd6");
    brush.set("burin_fine", col, random(0.25, 0.55));
    let x2 = fx + cos(ang) * len;
    let y2 = fy + sin(ang) * len;
    let xm = (fx + x2) * 0.5 + random(-1.8, 1.8);
    let ym = (fy + y2) * 0.5 + random(-1.8, 1.8);
    safeSpline([[fx, fy, 0.3], [xm, ym, 0.7], [x2, y2, 0.2]], 0.5);
  }
}

// =============================================================================
// 2. PERFORATED STAMP BORDER & SHADOW
// =============================================================================
function buildPerforatedContour(w, h, pitch, holeR) {
  let pts = [];
  let hw = w / 2;
  let hh = h / 2;

  function addEdgeWithPerfs(x1, y1, x2, y2, nx, ny) {
    let dx = x2 - x1;
    let dy = y2 - y1;
    let len = sqrt(dx * dx + dy * dy);
    let ux = dx / len;
    let uy = dy / len;

    let nHoles = floor((len - pitch * 0.8) / pitch);
    let startOffset = (len - (nHoles - 1) * pitch) * 0.5;

    pts.push([x1, y1]);

    for (let i = 0; i < nHoles; i++) {
      let centerDist = startOffset + i * pitch;
      let dBefore = centerDist - holeR;
      let dAfter = centerDist + holeR;

      // Tooth edge before perforation notch
      let bx = x1 + ux * dBefore + nx * random(-0.4, 0.4);
      let by = y1 + uy * dBefore + ny * random(-0.4, 0.4);
      pts.push([bx, by]);

      // Concave semicircular notch biting inward (-nx, -ny)
      let cx = x1 + ux * centerDist;
      let cy = y1 + uy * centerDist;
      let steps = 7;
      for (let s = 1; s < steps; s++) {
        let t = s / steps;
        let a = t * 180; // 0 to 180 degrees
        let along = -cos(a) * holeR;
        let inward = -sin(a) * holeR;
        let jit = (s === 1 || s === steps - 1) ? random(-0.45, 0.45) : random(-0.2, 0.2);
        let px = cx + ux * along + nx * (inward + jit);
        let py = cy + uy * along + ny * (inward + jit);
        pts.push([px, py]);
      }

      // Tooth edge after perforation notch
      let ax = x1 + ux * dAfter + nx * random(-0.4, 0.4);
      let ay = y1 + uy * dAfter + ny * random(-0.4, 0.4);
      pts.push([ax, ay]);
    }
  }

  // Top edge (normal points up: 0, -1)
  addEdgeWithPerfs(-hw, -hh, hw, -hh, 0, -1);
  // Right edge (normal points right: 1, 0)
  addEdgeWithPerfs(hw, -hh, hw, hh, 1, 0);
  // Bottom edge (normal points down: 0, 1)
  addEdgeWithPerfs(hw, hh, -hw, hh, 0, 1);
  // Left edge (normal points left: -1, 0)
  addEdgeWithPerfs(-hw, hh, -hw, -hh, -1, 0);

  return pts;
}

function drawStampBodyAndShadow(perfPts, w, h) {
  // Soft ambient shadow cast on the envelope
  brush.noStroke();
  brush.wash(PAL.shadowOuter, 125);
  brush.beginShape(0.15);
  for (let p of perfPts) {
    brush.vertex(p[0] + 8.5, p[1] + 10.5);
  }
  brush.endShape(true);

  // Tight crisp contact shadow right under the perforated teeth
  brush.wash(PAL.shadowCore, 175);
  brush.beginShape(0.12);
  for (let p of perfPts) {
    brush.vertex(p[0] + 3.8, p[1] + 4.8);
  }
  brush.endShape(true);
  brush.noWash();

  // Main ivory stamp paper body
  brush.noStroke();
  brush.wash(PAL.stampPaper, 255);
  brush.beginShape(0.1);
  for (let p of perfPts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Subtle paper texture inside the stamp
  brush.fill(PAL.stampWarm, 45);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.35, 0.15);
  brush.rect(-w * 0.44, -h * 0.44, w * 0.88, h * 0.88);
  brush.noFill();

  // Fibrous bevel edge along every perforation tooth
  for (let i = 0; i < perfPts.length; i++) {
    let p1 = perfPts[i];
    let p2 = perfPts[(i + 1) % perfPts.length];
    let mx = (p1[0] + p2[0]) * 0.5;
    let my = (p1[1] + p2[1]) * 0.5;

    // Top & Left edges catch light; Bottom & Right edges show paper thickness shade
    let isShadowEdge = (mx > w * 0.46) || (my > h * 0.46);
    brush.set("2H", isShadowEdge ? PAL.stampEdgeShade : PAL.stampEdgeLit, isShadowEdge ? 0.65 : 0.45);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Tiny torn paper fibers at perforation tooth tips
    if (i % 7 === 0 && random() < 0.7) {
      brush.set("burin_fine", PAL.stampPaper, 0.55);
      let outX = mx > 0 ? 1.6 : (mx < 0 ? -1.6 : 0);
      let outY = my > 0 ? 1.6 : (my < 0 ? -1.6 : 0);
      brush.line(mx, my, mx + outX + random(-0.8, 0.8), my + outY + random(-0.8, 0.8));
    }
  }
}

// =============================================================================
// 3. ENGRAVED FRAME & RULED BACKGROUND
// =============================================================================
function drawEngravedFrameAndGround(fw, fh) {
  let hw = fw / 2;
  let hh = fh / 2;

  // Outer hairline frame
  brush.set("burin_fine", PAL.ink, 0.75);
  brush.line(-hw - 7, -hh - 7, hw + 7, -hh - 7);
  brush.line(hw + 7, -hh - 7, hw + 7, hh + 7);
  brush.line(hw + 7, hh + 7, -hw - 7, hh + 7);
  brush.line(-hw - 7, hh + 7, -hw - 7, -hh - 7);

  // Heavy inner engraved border frame (double-cut burin line)
  brush.set("burin_bold", PAL.ink, 1.05);
  brush.line(-hw, -hh, hw, -hh);
  brush.line(hw, -hh, hw, hh);
  brush.line(hw, hh, -hw, hh);
  brush.line(-hw, hh, -hw, -hh);

  // Fine inner companion line
  brush.set("burin_fine", PAL.ink, 0.55);
  brush.line(-hw + 3.5, -hh + 3.5, hw - 3.5, -hh + 3.5);
  brush.line(hw - 3.5, -hh + 3.5, hw - 3.5, hh - 3.5);
  brush.line(hw - 3.5, hh - 3.5, -hw + 3.5, hh - 3.5);
  brush.line(-hw + 3.5, hh - 3.5, -hw + 3.5, -hh + 3.5);

  // Corner engraver's cross-squares
  const corners = [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]];
  for (let [cx, cy] of corners) {
    let sx = cx < 0 ? -1 : 1;
    let sy = cy < 0 ? -1 : 1;
    brush.set("burin_fine", PAL.ink, 0.65);
    brush.line(cx, cy, cx + sx * 7, cy);
    brush.line(cx, cy, cx, cy + sy * 7);
    brush.line(cx + sx * 3.5, cy + sy * 3.5, cx + sx * 7, cy + sy * 3.5);
    brush.line(cx + sx * 3.5, cy + sy * 3.5, cx + sx * 3.5, cy + sy * 7);
  }

  // Horizontal ruled engraving lines in the stamp ground
  // Leaves a luminous halo around the strawberry, calyx, numeral, and bottom title
  let yStart = -hh + 9;
  let yEnd = hh - 56;
  for (let y = yStart; y <= yEnd; y += 5.2) {
    let tY = (y - yStart) / (yEnd - yStart);
    // Graduated line weight (slightly richer near top, lighter toward bottom)
    let baseW = lerp(0.58, 0.28, tY);
    brush.set("burin_fine", PAL.ink, baseW);

    let xLeft = -hw + 9;
    let xRight = hw - 9;

    // Collect segments that stay outside the luminous halo around the subject
    let segStart = null;
    let step = 6;
    for (let x = xLeft; x <= xRight; x += step) {
      let inHalo = isInsideSubjectHalo(x, y);
      if (!inHalo && segStart === null) {
        segStart = x;
      } else if (inHalo && segStart !== null) {
        if (x - segStart > 8) {
          brush.line(segStart, y, x - step * 0.5, y);
        }
        segStart = null;
      }
    }
    if (segStart !== null && xRight - segStart > 8) {
      brush.line(segStart, y, xRight, y);
    }
  }

  // Subtle horizontal divider rule above "HELVETIA" footer banner
  brush.set("burin_fine", PAL.ink, 0.6);
  brush.line(-hw + 9, hh - 50, hw - 9, hh - 50);
}

function isInsideSubjectHalo(x, y) {
  // Halo around "25c" denomination box in upper-right
  if (x > 135 && y < -222) return true;

  // Halo around stem & calyx at top
  let dxCalyx = (x + 4) / 215;
  let dyCalyx = (y + 145) / 115;
  if (dxCalyx * dxCalyx + dyCalyx * dyCalyx < 1.0) return true;

  // Halo around main strawberry body
  if (y >= -145 && y <= 258) {
    let vApprox = constrain((y + 128) / 365, 0, 1);
    let r = strawberryRadius(vApprox) + 22;
    let cx = strawberryAxisX(vApprox);
    if (abs(x - cx) < r) return true;
  }
  return false;
}

// =============================================================================
// 3D PARAMETRIC STRAWBERRY GEOMETRY & LIGHTING
// =============================================================================
function strawberryRadius(v) {
  v = constrain(v, 0, 1);
  let s = pow(v, 0.53);
  // Plump upper shoulder tapering to a rounded conical apex
  let profile = sin(s * 180) * (1.0 + 0.36 * cos(s * 152));
  return 172 * profile + (1 - v) * 8 * exp(-v * 25);
}

function strawberryAxisX(v) {
  // Subtle natural organic curve
  return 5.5 * sin(v * 180) - 2.5 * sin(v * 360);
}

function strawberryY(v) {
  v = constrain(v, 0, 1);
  // Slight shoulder rise around stem pit then smooth descent to apex
  let shoulderLift = 13 * sin(min(1, v / 0.085) * 180);
  return -118 - shoulderLift + 354 * pow(v, 0.93);
}

function strawberryPoint3D(u, v) {
  // u in [-90, 90] degrees across front hemisphere; v in [0, 1] top to bottom
  let rBase = strawberryRadius(v);
  // Subtle 3-lobed longitudinal undulation of a real garden berry
  let lobe = 1.0 + 0.026 * sin(v * 180) * cos(u * 3 + 22);
  // Slight organic asymmetry between left and right flanks
  let asym = 1.0 - 0.025 * sin(u) * sin(v * 180);
  let r = rBase * lobe * asym;

  let x = strawberryAxisX(v) + r * sin(u);
  let z = r * cos(u);
  // Perspective foreshortening on y (front belly curves slightly down)
  let y = strawberryY(v) + 14 * sin(v * 180) * (1 - cos(u)) * (v < 0.25 ? -0.6 : 0.45);

  return { x, y, z, r };
}

function initAcheneLattice() {
  achenes = [];
  const nRows = 15;
  for (let row = 0; row < nRows; row++) {
    let v = map(row, 0, nRows - 1, 0.065, 0.935);
    // Slightly fewer columns near the very narrow apex
    let nCols = row >= 13 ? 6 : (row >= 11 ? 7 : 9);
    let uSpan = 79;
    for (let col = 0; col < nCols; col++) {
      let shift = (row % 2 === 1) ? 0.5 : 0.0;
      let tCol = (col + shift) / (nCols - 0.5);
      if (tCol > 1.02) continue;
      let u = map(tCol, 0, 1, -uSpan, uSpan);

      // Natural botanical micro-jitter
      let uJit = u + random(-2.1, 2.1);
      let vJit = constrain(v + random(-0.007, 0.007), 0.04, 0.96);
      let p = strawberryPoint3D(uJit, vJit);

      achenes.push({
        u: uJit,
        v: vJit,
        x: p.x,
        y: p.y,
        z: p.z,
        foreshorten: cos(uJit),
        scale: map(vJit, 0, 1, 1.02, 0.72)
      });
    }
  }
}

function evaluateBerrySurface(u, v) {
  let p = strawberryPoint3D(u, v);

  // Base 3D surface normal components
  let nx = sin(u) * 0.92;
  let ny = map(v, 0, 1, -0.58, 0.52);
  let nz = cos(u);

  // Longitudinal lobe normal perturbation
  nx += 0.08 * sin(u * 3 + 22) * sin(v * 180);

  // Local seed-dimple concavity & cushioned pillow perturbation
  let pitDarkening = 0;
  let pillowHighlight = 0;
  let pitDeflectY = 0;

  for (let i = 0; i < achenes.length; i++) {
    let a = achenes[i];
    if (abs(v - a.v) > 0.065 || abs(u - a.u) > 16) continue;

    let du = (u - a.u) / 7.2;
    let dv = (v - a.v) / 0.036;
    let d2 = du * du + dv * dv;
    if (d2 < 2.2) {
      let w = exp(-d2 * 1.45);
      // Directional derivative along upper-left light vector
      let slope = (du * 0.68 + dv * 0.73);
      if (slope < 0) {
        // Upper-left inner wall of seed pit turns into shadow
        pitDarkening += (-slope) * w * 0.42;
      } else {
        // Lower-right cushioned pillow rim catches specular light
        pillowHighlight += slope * w * 0.38;
      }
      pitDeflectY += dv * w * 2.2;
    }
  }

  let nLen = sqrt(nx * nx + ny * ny + nz * nz);
  nx /= nLen;
  ny /= nLen;
  nz /= nLen;

  // Primary light from upper-left-front
  let lx = -0.54, ly = -0.48, lz = 0.69;
  let ndotl = constrain(nx * lx + ny * ly + nz * lz, -1, 1);

  // Base darkness (0 = bright highlight, 1 = deep core shadow)
  let darkness = map(ndotl, 0.92, -0.65, 0.0, 0.96);
  darkness = constrain(darkness, 0, 1);

  // Reflected light along far right contour & bottom tip
  if (u > 48) {
    let refl = sin(map(u, 48, 90, 0, 180)) * 0.22;
    darkness -= refl;
  }

  // Cast shadow right underneath the overhanging calyx sepals at top
  let calyxEdgeV = 0.16 + 0.055 * cos(u * 3.5) + 0.03 * sin(u * 1.5);
  if (v < calyxEdgeV) {
    let tCast = map(v, calyxEdgeV, 0, 0, 1);
    darkness += pow(tCast, 0.7) * 0.55;
  }

  // Apply seed pit shadow & pillow highlight
  darkness = darkness + pitDarkening - pillowHighlight;

  // Glossy specular window on upper-left shoulder pillows
  let specZone = exp(-pow((u + 26) / 28, 2) - pow((v - 0.29) / 0.19, 2));
  if (specZone > 0.25 && pitDarkening < 0.08) {
    darkness -= specZone * (0.28 + pillowHighlight * 0.6);
  }

  darkness = constrain(darkness, 0.0, 1.0);

  return {
    x: p.x,
    y: p.y + pitDeflectY,
    darkness,
    specZone,
    pillowHighlight
  };
}

// =============================================================================
// 4. OFF-REGISTER CARMINE SPOT COLOUR PLATE
// =============================================================================
function drawOffRegisterCarminePlate(dx, dy) {
  push();
  translate(dx, dy);
  rotate(0.35); // Tiny angular registration shift

  // Build outer silhouette of the strawberry for the carmine plate
  let silPts = [];
  for (let i = 0; i <= 40; i++) {
    let v = i / 40;
    let p = strawberryPoint3D(-90, v);
    silPts.push([p.x, p.y]);
  }
  for (let i = 40; i >= 0; i--) {
    let v = i / 40;
    let p = strawberryPoint3D(90, v);
    silPts.push([p.x, p.y]);
  }

  // 1. Primary carmine print wash
  brush.noStroke();
  brush.wash(PAL.carmineWash, 195);
  brush.beginShape(0.2);
  for (let pt of silPts) {
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Deeper ruby-carmine tonal build on the belly & right shadow side
  brush.fill(PAL.carmineDeep, 95);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.3);
  brush.beginShape(0.25);
  for (let i = 2; i <= 38; i += 2) {
    let v = i / 40;
    let p = strawberryPoint3D(-15, v);
    brush.vertex(p.x, p.y);
  }
  for (let i = 38; i >= 2; i -= 2) {
    let v = i / 40;
    let p = strawberryPoint3D(88, v);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noFill();

  // 3. Knock-out paper-white specular pillows on the carmine plate
  // (Real spot plates have etched highlight windows on the upper-left swell)
  brush.noStroke();
  brush.wash(PAL.stampPaper, 225);
  for (let a of achenes) {
    if (a.u > -54 && a.u < -4 && a.v > 0.14 && a.v < 0.48) {
      // Glossy pillow crescent below-right of each seed in the highlight zone
      brush.circle(a.x + 5.5, a.y + 5.0, 5.2, 0.25);
    }
  }
  brush.noWash();

  // 4. Carmine engraved contour shading lines (gives the red plate true print grain)
  const nCarmineRings = 54;
  for (let i = 1; i < nCarmineRings; i++) {
    let v = i / nCarmineRings;
    let currentPts = [];
    let col = i % 2 === 0 ? PAL.carmine : PAL.carmineDeep;
    brush.set("carmine_burin", col, 0.85);

    for (let u = -88; u <= 88; u += 4) {
      let surf = evaluateBerrySurface(u, v);
      // Leave specular pillow cutouts open
      if (surf.darkness < 0.14) {
        if (currentPts.length >= 3) safeSpline(currentPts, 0.45);
        currentPts = [];
      } else {
        let press = map(surf.darkness, 0.14, 1.0, 0.28, 1.35);
        currentPts.push([surf.x, surf.y, press]);
      }
    }
    if (currentPts.length >= 3) safeSpline(currentPts, 0.45);
  }

  pop();
}

// =============================================================================
// 5. DENSE LINE-ENGRAVING CROSS-HATCH IN FINE BLACK PEN
// =============================================================================
function drawStrawberryEngraving() {
  // FAMILY 1: Primary Latitudinal Cross-Contour Engraving Lines
  // Swelling and thinning across the form & dipping into seed dimples
  const nLat = 88;
  for (let i = 1; i < nLat; i++) {
    let v = i / nLat;
    brush.set("burin", PAL.ink, 0.92);

    let seg = [];
    for (let u = -90; u <= 90; u += 3) {
      let surf = evaluateBerrySurface(u, v);
      // Break line in the brightest specular pillows
      let threshold = (i % 2 === 0) ? 0.11 : 0.19;
      if (surf.darkness < threshold) {
        if (seg.length >= 3) safeSpline(seg, 0.45);
        seg = [];
      } else {
        let p = map(surf.darkness, threshold, 1.0, 0.2, 1.48);
        seg.push([surf.x, surf.y, p]);
      }
    }
    if (seg.length >= 3) safeSpline(seg, 0.45);
  }

  // FAMILY 2: Right-Leaning Parastichy (Diagonal Spiral Cross-Hatch)
  // Follows the botanical diamond lattice between seeds
  const nDiag1 = 46;
  for (let k = -18; k < nDiag1; k++) {
    brush.set("burin", PAL.ink, 0.82);
    let seg = [];
    let steps = 42;
    for (let s = 0; s <= steps; s++) {
      let v = map(s, 0, steps, 0.02, 0.98);
      let u = -90 + (k * 6.2) + v * 108;
      if (u < -90 || u > 90) {
        if (seg.length >= 3) safeSpline(seg, 0.4);
        seg = [];
        continue;
      }
      let surf = evaluateBerrySurface(u, v);
      if (surf.darkness < 0.29) {
        if (seg.length >= 3) safeSpline(seg, 0.4);
        seg = [];
      } else {
        let p = map(surf.darkness, 0.29, 1.0, 0.18, 1.32);
        seg.push([surf.x, surf.y, p]);
      }
    }
    if (seg.length >= 3) safeSpline(seg, 0.4);
  }

  // FAMILY 3: Left-Leaning Parastichy (Opposing Diagonal Cross-Hatch)
  // Forms classic burin diamond lozenges in the midtones and core shadows
  const nDiag2 = 46;
  for (let k = -6; k < nDiag2; k++) {
    brush.set("burin", PAL.ink, 0.78);
    let seg = [];
    let steps = 42;
    for (let s = 0; s <= steps; s++) {
      let v = map(s, 0, steps, 0.02, 0.98);
      let u = 90 - (k * 6.2) - v * 108;
      if (u < -90 || u > 90) {
        if (seg.length >= 3) safeSpline(seg, 0.4);
        seg = [];
        continue;
      }
      let surf = evaluateBerrySurface(u, v);
      if (surf.darkness < 0.44) {
        if (seg.length >= 3) safeSpline(seg, 0.4);
        seg = [];
      } else {
        let p = map(surf.darkness, 0.44, 1.0, 0.18, 1.28);
        seg.push([surf.x, surf.y, p]);
      }
    }
    if (seg.length >= 3) safeSpline(seg, 0.4);
  }

  // FAMILY 4: Meridional (Longitudinal) Deep Core Shadow & Contour Reinforcement
  const nMerid = 44;
  for (let m = 0; m <= nMerid; m++) {
    let u = map(m, 0, nMerid, -90, 90);
    brush.set("burin_fine", PAL.ink, 0.85);
    let seg = [];
    for (let s = 0; s <= 40; s++) {
      let v = map(s, 0, 40, 0.02, 0.98);
      let surf = evaluateBerrySurface(u, v);
      // Activate in deep core shadows, calyx overhang, and near left/right silhouette rims
      let rimBoost = pow(abs(u) / 90, 4) * 0.35;
      let effDark = surf.darkness + rimBoost;
      if (effDark < 0.62) {
        if (seg.length >= 3) safeSpline(seg, 0.4);
        seg = [];
      } else {
        let p = map(effDark, 0.62, 1.15, 0.2, 1.35);
        seg.push([surf.x, surf.y, p]);
      }
    }
    if (seg.length >= 3) safeSpline(seg, 0.4);
  }

  // Crisp outer engraved contour with natural seed-dimple scalloping
  for (let side of [-90, 90]) {
    let contourPts = [];
    brush.set("burin_bold", PAL.ink, side === 90 ? 1.05 : 0.72);
    for (let i = 0; i <= 60; i++) {
      let v = i / 60;
      let surf = evaluateBerrySurface(side, v);
      // Slight scalloping along silhouette
      let scallop = sin(v * 180 * 14) * 1.1 * (side === 90 ? 1 : -1);
      let press = map(surf.darkness, 0, 1, 0.35, 1.25);
      contourPts.push([surf.x + scallop, surf.y, press]);
    }
    safeSpline(contourPts, 0.45);
  }
}

// =============================================================================
// 6. SEEDS (ACHENES) AS PRECISE SUNKEN DOTS & HIGHLIGHTS
// =============================================================================
function drawAllAchenes(regDX, regDY) {
  for (let a of achenes) {
    let sc = a.scale;
    let wSeed = 3.2 * sc * max(0.38, a.foreshorten);
    let hSeed = 5.2 * sc;

    // Slight tilt of the seed toward the apex
    let tilt = map(a.u, -90, 90, -24, 24) * sin(a.v * 160);

    push();
    translate(a.x, a.y);
    rotate(tilt);

    // 1. Sunken pit shadow crescent on upper-left of the seed dimple
    brush.set("burin", PAL.ink, 0.95 * sc);
    safeSpline([
      [-wSeed * 1.45, hSeed * 0.25, 0.3],
      [-wSeed * 1.35, -hSeed * 0.85, 1.15],
      [0, -hSeed * 1.28, 1.25],
      [wSeed * 1.15, -hSeed * 0.55, 0.35]
    ], 0.5);

    // Secondary fine pit hatch strokes
    brush.set("burin_fine", PAL.ink, 0.75 * sc);
    brush.line(-wSeed * 1.1, -hSeed * 0.95, -wSeed * 0.3, -hSeed * 1.35);
    brush.line(-wSeed * 0.5, -hSeed * 1.25, wSeed * 0.5, -hSeed * 1.15);

    // 2. Cushioned flesh pillow highlight on the lower-right rim of the dimple
    if (a.u < 55) {
      brush.set("burin_fine", PAL.stampPaper, 1.15 * sc);
      safeSpline([
        [-wSeed * 0.4, hSeed * 1.35, 0.35],
        [wSeed * 1.05, hSeed * 1.15, 1.25],
        [wSeed * 1.55, -hSeed * 0.1, 0.4]
      ], 0.5);
    }

    // 3. The Achene (Seed) Body — crisp engraved teardrop dot
    brush.noStroke();
    brush.wash(PAL.ink, 245);
    brush.beginShape(0.35);
    brush.vertex(0, -hSeed * 0.95);
    brush.vertex(wSeed * 0.95, -hSeed * 0.15);
    brush.vertex(wSeed * 0.7, hSeed * 0.78);
    brush.vertex(0, hSeed * 0.98);
    brush.vertex(-wSeed * 0.7, hSeed * 0.78);
    brush.vertex(-wSeed * 0.95, -hSeed * 0.15);
    brush.endShape(true);
    brush.noWash();

    // 4. Razor-sharp paper-white highlight dot on upper-left of the seed
    brush.set("burin", PAL.stampPaper, 0.95 * sc);
    safeSpline([
      [-wSeed * 0.48, hSeed * 0.25, 0.4],
      [-wSeed * 0.38, -hSeed * 0.35, 1.25],
      [0, -hSeed * 0.68, 0.5]
    ], 0.45);

    pop();
  }
}

// =============================================================================
// 7. HAIRY CALYX (LEAFY CROWN & FIBROUS STEM WITH TRICHOMES)
// =============================================================================
function drawHairyCalyx() {
  // 1. Back Sepals (behind the stem)
  drawSingleSepal(0, -118, -148, 128, 34, true, -0.25);
  drawSingleSepal(0, -120, -116, 112, 30, true, 0.15);
  drawSingleSepal(0, -120, -58, 118, 32, true, -0.2);
  drawSingleSepal(0, -118, -28, 134, 34, true, 0.28);

  // 2. Central Woody/Herbaceous Stem (Pedicel)
  drawPedicelStem();

  // 3. Front & Lateral Sepals Draping Over the Crown of the Strawberry
  drawSingleSepal(-8, -116, 174, 156, 40, false, -0.32);  // Far-left sweeping sepal
  drawSingleSepal(8, -116, 12, 158, 40, false, 0.35);     // Far-right curling sepal
  drawSingleSepal(-12, -114, 146, 142, 42, false, 0.22);  // Mid-left sepal over shoulder
  drawSingleSepal(12, -114, 42, 146, 42, false, -0.25);   // Mid-right sepal over shoulder
  drawSingleSepal(-4, -115, 118, 108, 34, false, -0.15);  // Inner-left bractlet
  drawSingleSepal(6, -115, 68, 114, 35, false, 0.18);     // Inner-right bractlet
  drawSingleSepal(0, -112, 93, 124, 44, false, 0.08);     // Center-front primary sepal
}

function drawPedicelStem() {
  // Stem curve from receptacle (0, -116) up to cut top (-22, -262)
  let leftEdge = [];
  let rightEdge = [];
  let centerLine = [];
  let steps = 28;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let cx = -24 * pow(t, 1.35) + 4 * sin(t * 180);
    let cy = lerp(-114, -262, t);
    // Swells at base receptacle and flares slightly at cut tip
    let halfW = lerp(13.5, 7.8, t) + 3.5 * exp(-t * 8) + 1.8 * pow(t, 4);

    let ang = -98 - t * 14;
    let nx = cos(ang + 90);
    let ny = sin(ang + 90);

    leftEdge.push([cx - nx * halfW, cy - ny * halfW]);
    rightEdge.push([cx + nx * halfW, cy + ny * halfW]);
    centerLine.push({ cx, cy, nx, ny, halfW, t });
  }

  // Opaque paper knock-out for stem
  brush.noStroke();
  brush.wash(PAL.stampPaper, 255);
  brush.beginShape(0.15);
  for (let p of leftEdge) brush.vertex(p[0], p[1]);
  for (let i = rightEdge.length - 1; i >= 0; i--) brush.vertex(rightEdge[i][0], rightEdge[i][1]);
  brush.endShape(true);
  brush.noWash();

  // Longitudinal cylindrical burin shading lines along the stem
  for (let f = -1.0; f <= 1.0; f += 0.14) {
    // Left side faces light; right side turns into deep shadow
    let shade = map(f, -1.0, 1.0, 0.15, 1.0);
    if (f > -0.65 && f < -0.25) continue; // Specular ridge along stem

    brush.set("burin", PAL.ink, map(shade, 0.15, 1.0, 0.45, 0.95));
    let pts = [];
    for (let c of centerLine) {
      let px = c.cx + c.nx * c.halfW * f;
      let py = c.cy + c.ny * c.halfW * f;
      pts.push([px, py, shade * 1.2]);
    }
    safeSpline(pts, 0.4);
  }

  // Ring cross-hatching on the shadowed right side of the stem
  brush.set("burin_fine", PAL.ink, 0.65);
  for (let i = 2; i < steps - 1; i++) {
    let c = centerLine[i];
    let rPts = [];
    for (let f = -0.15; f <= 1.0; f += 0.25) {
      let dip = sin((f + 1) * 90) * 3.5;
      rPts.push([
        c.cx + c.nx * c.halfW * f,
        c.cy + c.ny * c.halfW * f + dip,
        map(f, -0.15, 1.0, 0.2, 1.15)
      ]);
    }
    safeSpline(rPts, 0.4);
  }

  // Cut elliptical cross-section at the top of the stem
  let topC = centerLine[steps];
  brush.set("burin_bold", PAL.ink, 0.85);
  let cutPts = [];
  for (let a = 0; a <= 360; a += 30) {
    let ex = topC.cx + cos(a) * topC.halfW * 0.95;
    let ey = topC.cy + sin(a) * 3.8;
    cutPts.push([ex, ey, 0.8]);
  }
  safeSpline(cutPts, 0.5);
  // Central vascular pith dot
  brush.set("burin", PAL.ink, 0.9);
  brush.circle(topC.cx, topC.cy, 3.2, 0.2);

  // Abundant spreading botanical hairs (trichomes) along both sides of the stem
  for (let i = 1; i < steps; i++) {
    let c = centerLine[i];
    for (let side of [-1, 1]) {
      let nHairs = 3;
      for (let h = 0; h < nHairs; h++) {
        let bx = c.cx + c.nx * c.halfW * side * 0.95 + random(-1, 1);
        let by = c.cy + c.ny * c.halfW * side * 0.95 + random(-2, 2);
        let hLen = random(11, 22);
        let baseAng = side < 0 ? 195 : -15;
        let ang = baseAng + random(-28, 28);
        drawTrichomeHair(bx, by, ang, hLen, side * 18, PAL.ink, 0.85);
      }
    }
  }
}

function drawSingleSepal(ox, oy, baseAngle, len, maxWidth, isBack, curlFactor) {
  let steps = 26;
  let spine = [];
  let leftRim = [];
  let rightRim = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Graceful S-curve along the sepal blade
    let ang = baseAngle + curlFactor * 52 * pow(t, 1.4) + 12 * sin(t * 180) * curlFactor;
    let dist = t * len;
    let sx = ox + cos(ang) * dist;
    let sy = oy + sin(ang) * dist;

    // Tangent & normal
    let tang = ang + curlFactor * 35 * t;
    let nx = -sin(tang);
    let ny = cos(tang);

    // Leaf width profile: narrow base, wide belly at t=0.36, acuminate pointed tip
    let wProfile = sin(pow(t, 0.65) * 180) * (1 - 0.25 * t);
    // Subtle marginal serration
    let serration = 1.0 + 0.05 * sin(t * 180 * 5);
    let w = maxWidth * 0.5 * wProfile * serration;

    spine.push({ x: sx, y: sy, nx, ny, w, t, tang });
    leftRim.push([sx - nx * w, sy - ny * w]);
    rightRim.push([sx + nx * w, sy + ny * w]);
  }

  // 1. Paper knock-out so sepal cleanly overlaps underlying lines
  brush.noStroke();
  brush.wash(PAL.stampPaper, 255);
  brush.beginShape(0.15);
  for (let p of leftRim) brush.vertex(p[0], p[1]);
  for (let i = rightRim.length - 1; i >= 0; i--) brush.vertex(rightRim[i][0], rightRim[i][1]);
  brush.endShape(true);
  brush.noWash();

  // 2. Engraved feather-vein cross-contour lines from midrib to margins
  let nVeins = 38;
  for (let vIdx = 1; vIdx < nVeins; vIdx++) {
    let t = vIdx / nVeins;
    let idx = constrain(floor(t * steps), 0, steps - 1);
    let sp = spine[idx];
    if (sp.w < 1.5) continue;

    for (let side of [-1, 1]) {
      // Determine lighting on each half of the leaf blade
      let worldNormalAng = sp.tang + side * 90;
      let lightDot = cos(worldNormalAng - (-135)); // Upper-left light at -135 deg
      let shade = map(lightDot, 0.9, -0.9, 0.18, 0.98);
      if (isBack) shade = constrain(shade + 0.25, 0.35, 1.0);

      // Leave small specular sheen on lit side of front sepals
      if (!isBack && shade < 0.28 && vIdx % 2 === 0) continue;

      brush.set("burin_fine", PAL.ink, map(shade, 0.18, 1.0, 0.42, 0.95));

      // Curve from midrib outward and slightly forward toward leaf tip
      let p0 = [sp.x + sp.nx * side * 1.2, sp.y + sp.ny * side * 1.2, shade * 0.7];
      let midIdx = min(steps, idx + 1);
      let spMid = spine[midIdx];
      let p1 = [
        spMid.x + spMid.nx * side * sp.w * 0.55,
        spMid.y + spMid.ny * side * sp.w * 0.55,
        shade * 1.25
      ];
      let endIdx = min(steps, idx + 2);
      let spEnd = spine[endIdx];
      let p2 = [
        spEnd.x + spEnd.nx * side * spEnd.w * 0.98,
        spEnd.y + spEnd.ny * side * spEnd.w * 0.98,
        shade * 0.95
      ];
      safeSpline([p0, p1, p2], 0.45);
    }
  }

  // 3. Longitudinal cross-hatching on the darker half & base of the sepal
  for (let side of [-1, 1]) {
    for (let frac of [0.28, 0.52, 0.76]) {
      let pts = [];
      brush.set("burin_fine", PAL.ink, 0.65);
      for (let i = 1; i < steps; i++) {
        let sp = spine[i];
        let worldNormalAng = sp.tang + side * 90;
        let lightDot = cos(worldNormalAng - (-135));
        let isDarkSide = isBack || lightDot < 0.1 || i < 6 || i > steps - 6;
        if (!isDarkSide) {
          if (pts.length >= 3) safeSpline(pts, 0.4);
          pts = [];
        } else {
          pts.push([
            sp.x + sp.nx * side * sp.w * frac,
            sp.y + sp.ny * side * sp.w * frac,
            isBack ? 1.0 : 0.75
          ]);
        }
      }
      if (pts.length >= 3) safeSpline(pts, 0.4);
    }
  }

  // 4. Crisp Midrib Vein (double engraved hairline with luminous center ridge)
  let midLeft = [];
  let midRight = [];
  for (let sp of spine) {
    let mw = lerp(1.6, 0.2, sp.t);
    midLeft.push([sp.x - sp.nx * mw, sp.y - sp.ny * mw, 0.85]);
    midRight.push([sp.x + sp.nx * mw, sp.y + sp.ny * mw, 0.95]);
  }
  brush.set("burin_fine", PAL.ink, 0.78);
  safeSpline(midLeft, 0.45);
  safeSpline(midRight, 0.45);

  // 5. Crisp Engraved Outer Margins of the Sepal
  brush.set("burin", PAL.ink, 0.88);
  let lPts = leftRim.map((p, idx) => [p[0], p[1], idx > steps * 0.7 ? 1.15 : 0.75]);
  let rPts = rightRim.map((p, idx) => [p[0], p[1], idx > steps * 0.7 ? 1.2 : 0.9]);
  safeSpline(lPts, 0.45);
  safeSpline(rPts, 0.45);

  // 6. Fine Botanical Hairs (Trichomes) Ciliating the Sepal Margins & Midrib
  for (let i = 2; i < steps; i++) {
    let sp = spine[i];
    for (let side of [-1, 1]) {
      let mx = sp.x + sp.nx * side * sp.w;
      let my = sp.y + sp.ny * side * sp.w;
      let outAng = sp.tang + side * 62 + random(-14, 14);
      let hLen = map(sp.t, 0, 1, 13, 6.5) * random(0.8, 1.25);

      // Draw crisp black hair extending outward, plus a tiny white hair base where it overlaps dark ink
      drawTrichomeHair(mx, my, outAng, hLen, -side * 22, PAL.ink, 0.82);
      if (i % 2 === 0) {
        drawTrichomeHair(
          mx - cos(outAng) * 3,
          my - sin(outAng) * 3,
          outAng,
          hLen * 0.55,
          -side * 15,
          PAL.stampPaper,
          0.75
        );
      }
    }

    // Surface hairs along the midrib
    if (i % 2 === 1 && sp.t < 0.85) {
      let hAng = sp.tang + random(-28, 28);
      drawTrichomeHair(sp.x, sp.y, hAng, random(7, 12), 15, PAL.stampPaper, 0.7);
      drawTrichomeHair(sp.x + 1, sp.y + 1, hAng, random(7, 12), 15, PAL.ink, 0.65);
    }
  }
}

function drawTrichomeHair(x, y, ang, len, bendDeg, col, weight) {
  brush.set("trichome", col, weight);
  let x1 = x + cos(ang) * (len * 0.5);
  let y1 = y + sin(ang) * (len * 0.5);
  let x2 = x1 + cos(ang + bendDeg) * (len * 0.5);
  let y2 = y1 + sin(ang + bendDeg) * (len * 0.5);
  safeSpline([[x, y, 1.1], [x1, y1, 0.65], [x2, y2, 0.1]], 0.5);
}

