// 8. STAMP TYPOGRAPHY (DENOMINATION NUMERAL & COUNTRY NAME)
// =============================================================================
function drawStampTypography(fw, fh, regDX, regDY) {
  let hw = fw / 2;
  let hh = fh / 2;

  // 1. Subtle off-register carmine ghost on the denomination numeral "25"
  drawEngravedString("25", 162 + regDX * 0.45, -310 + regDY * 0.45, 50, 12, PAL.carmine, 0.55, false);

  // 2. Crisp Black Engraved Denomination Numeral "25" & "c" in Upper-Right Corner
  drawEngravedString("25", 162, -310, 50, 12, PAL.ink, 1.15, true);
  drawEngravedString("C", 242, -296, 25, 4, PAL.ink, 0.95, true);
  // Underline bar beneath the 'c'
  brush.set("burin_bold", PAL.ink, 0.95);
  brush.line(241, -264, 259, -264);
  brush.set("burin_fine", PAL.ink, 0.6);
  brush.line(241, -260.5, 259, -260.5);

  // 3. Country Name "HELVETIA" Centered in Bottom Banner
  drawEngravedString("HELVETIA", -154, hh - 38, 25, 19.5, PAL.ink, 1.0, true);

  // Small philatelic star ornaments flanking "HELVETIA"
  drawEngravedStar(-212, hh - 25.5, 7.5);
  drawEngravedStar(212, hh - 25.5, 7.5);

  // 4. Tiny Botanical & Engraver Credits in Outer Margin Below Frame
  drawEngravedString("COURVOISIER", -hw + 4, hh + 14, 7.5, 3.2, PAL.inkSoft, 0.48, false);
  drawEngravedString("FRAGARIA VESCA", -54, hh + 14, 7.5, 3.5, PAL.ink, 0.52, false);
  drawEngravedString("1958", hw - 36, hh + 14, 7.5, 3.2, PAL.inkSoft, 0.48, false);
}

function drawEngravedStar(cx, cy, r) {
  brush.set("burin_fine", PAL.ink, 0.75);
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    let len = (i % 2 === 0) ? r : r * 0.55;
    brush.line(cx, cy, cx + cos(a) * len, cy + sin(a) * len);
  }
}

