function drawEngravedString(str, startX, startY, h, tracking, col, weight, inlineShade) {
  let w = h * 0.66;
  let curX = startX;

  for (let idx = 0; idx < str.length; idx++) {
    let ch = str[idx].toUpperCase();
    if (ch === " ") {
      curX += w * 0.6 + tracking;
      continue;
    }
    let g = GLYPHS[ch];
    if (!g) {
      curX += w + tracking;
      continue;
    }

    let charW = (ch === "I" || ch === "1" || ch === ".") ? w * 0.45 : w;

    // Main outline strokes
    brush.set(h > 20 ? "burin" : "burin_fine", col, weight);
    for (let poly of g.lines) {
      drawGlyphPoly(poly, curX, startY, charW, h);
    }

    // Thick stem double/triple engraving lines
    if (inlineShade && g.thick) {
      let offsets = h > 35 ? [1.6, 3.2, 4.8] : [1.3, 2.5];
      brush.set("burin_fine", col, weight * 0.72);
      for (let tPoly of g.thick) {
        for (let off of offsets) {
          drawGlyphPoly(tPoly, curX + off, startY, charW, h);
        }
      }
    }

    // Bracketed Roman serifs
    if (inlineShade && g.serifs) {
      let sLen = max(2.2, h * 0.13);
      brush.set("burin_fine", col, weight * 0.75);
      for (let [sx, sy] of g.serifs) {
        let px = curX + sx * charW;
        let py = startY + sy * h;
        brush.line(px - sLen, py, px + sLen + (h > 35 ? 3.5 : 1.5), py);
      }
    }

    curX += charW + tracking;
  }
}

function drawGlyphPoly(poly, ox, oy, cw, ch) {
  if (poly.length === 2) {
    brush.line(
      ox + poly[0][0] * cw,
      oy + poly[0][1] * ch,
      ox + poly[1][0] * cw,
      oy + poly[1][1] * ch
    );
  } else if (poly.length >= 3) {
    let pts = poly.map(p => [ox + p[0] * cw, oy + p[1] * ch, 0.9]);
    safeSpline(pts, 0.35);
  }
}

// =============================================================================
// 9. WAVY BLACK POSTMARK CANCELLATION SLASHING ACROSS CORNER
// =============================================================================
function drawWavyPostmarkCancellation(stampCX, stampCY, stampAngle, stampW, stampH) {
  // Position the cancellation slashing across the bottom-right corner of the stamp
  // and bleeding onto the cream envelope paper
  push();
  translate(795, 875);
  rotate(-14.5);

  const cdsR = 122;
  const cdsX = -275;
  const cdsY = 0;

  // Helper to check if a postmark point is right on the physical paper step of the stamp edge
  // (Real metal postmark dies leave a tiny 3px ink skip right where the thick stamp paper steps down!)
  function isAtStampStep(localX, localY) {
    // Transform postmark local point back to world, then into stamp local coords
    let a1 = -14.5;
    let wx = 795 + localX * cos(a1) - localY * sin(a1);
    let wy = 875 + localX * sin(a1) + localY * cos(a1);

    let dx = wx - stampCX;
    let dy = wy - stampCY;
    let a2 = -stampAngle;
    let sx = dx * cos(a2) - dy * sin(a2);
    let sy = dx * sin(a2) + dy * cos(a2);

    let distR = abs( abs(sx) - stampW * 0.5 );
    let distB = abs( abs(sy) - stampH * 0.5 );
    let insideW = abs(sx) <= stampW * 0.5 + 8;
    let insideH = abs(sy) <= stampH * 0.5 + 8;

    return (insideH && distR < 5.5) || (insideW && distB < 5.5);
  }

  // 1. Circular Date Stamp (CDS) Outer & Inner Rings
  for (let r of [cdsR, cdsR - 34]) {
    for (let pass = 0; pass < 2; pass++) {
      let curR = r + (pass === 0 ? -0.9 : 0.9);
      brush.set("cancel_rubber", PAL.cancelInk, pass === 0 ? 0.85 : 0.65);
      let seg = [];
      for (let a = 0; a <= 364; a += 5) {
        let px = cdsX + cos(a) * curR;
        let py = cdsY + sin(a) * curR;
        if (isAtStampStep(px, py)) {
          if (seg.length >= 3) safeSpline(seg, 0.45);
          seg = [];
        } else {
          let p = 0.75 + 0.35 * noise(a * 0.08, pass * 10);
          seg.push([px, py, p]);
        }
      }
      if (seg.length >= 3) safeSpline(seg, 0.45);
    }
  }

  // 2. Date Bridge Bars inside the Circular Date Stamp
  for (let by of [-18, 18]) {
    let halfChord = sqrt(pow(cdsR - 34, 2) - by * by);
    brush.set("cancel_rubber", PAL.cancelInk, 0.78);
    brush.line(cdsX - halfChord + 2, by, cdsX + halfChord - 2, by);
  }

  // Date text across the bridge: "14. VI. 58 - 11"
  drawEngravedString("14. VI. 58 - 11", cdsX - 78, -8, 16, 4.2, PAL.cancelInk, 0.95, false);

  // Curved city text along top arc of CDS: "GENEVE 1 · EXPED."
  const topText = "GENEVE 1 - EXPED.";
  let rTextTop = cdsR - 17;
  for (let i = 0; i < topText.length; i++) {
    let ang = map(i, 0, topText.length - 1, -152, -28);
    push();
    translate(cdsX + cos(ang) * rTextTop, cdsY + sin(ang) * rTextTop);
    rotate(ang + 90);
    drawEngravedString(topText[i], -5, -7, 14, 0, PAL.cancelInk, 0.95, false);
    pop();
  }

  // Curved text along bottom arc: "* SUISSE *"
  const botText = "SUISSE";
  let rTextBot = cdsR - 17;
  for (let i = 0; i < botText.length; i++) {
    let ang = map(i, 0, botText.length - 1, 128, 52);
    push();
    translate(cdsX + cos(ang) * rTextBot, cdsY + sin(ang) * rTextBot);
    rotate(ang - 90);
    drawEngravedString(botText[i], -5, -7, 14, 0, PAL.cancelInk, 0.95, false);
    pop();
  }

  // 3. Six Bold Wavy Cancellation Bars ("Killer Waves") Slashing Across the Corner
  const nWaves = 6;
  const waveSpacing = 38;
  const waveStartX = cdsX + cdsR + 14;
  const waveEndX = 295;

  for (let w = 0; w < nWaves; w++) {
    let baseY = (w - (nWaves - 1) * 0.5) * waveSpacing;

    // Multi-pass rendering for authentic squeezed rubber/metal stamp ink edges
    const offsets = [
      { dy: -1.8, weight: 0.92, brushName: "burin_bold" },
      { dy: 0.0,  weight: 1.15, brushName: "cancel_rubber" },
      { dy: 1.8,  weight: 0.88, brushName: "burin_bold" }
    ];

    for (let pass of offsets) {
      brush.set(pass.brushName, PAL.cancelInk, pass.weight);
      let seg = [];
      for (let x = waveStartX; x <= waveEndX; x += 6) {
        let phase = (x - waveStartX) * 2.85;
        let wy = baseY + sin(phase) * 11.5 + pass.dy;

        if (isAtStampStep(x, wy)) {
          if (seg.length >= 3) safeSpline(seg, 0.45);
          seg = [];
        } else {
          let inkPress = 0.72 + 0.42 * noise(x * 0.03, w * 5 + pass.dy);
          seg.push([x, wy, inkPress]);
        }
      }
      if (seg.length >= 3) safeSpline(seg, 0.45);
    }

    // Fine ink spatter/micro-beads along the wavy bars
    brush.set("burin_fine", PAL.cancelInk, 0.45);
    for (let x = waveStartX + 8; x < waveEndX - 8; x += 18) {
      if (random() < 0.45) {
        let phase = (x - waveStartX) * 2.85;
        let wy = baseY + sin(phase) * 11.5 + random(-3.5, 3.5);
        if (!isAtStampStep(x, wy)) {
          brush.circle(x, wy, random(0.6, 1.4), 0.3);
        }
      }
    }
  }

  pop();
}

// =============================================================================
// UTILITY: DEFENSIVE SPLINE RENDERER
// =============================================================================
function safeSpline(pts, curvature = 0.45) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let curr = pts[i];
    let dx = curr[0] - prev[0];
    let dy = curr[1] - prev[1];
    if (dx * dx + dy * dy > 0.6) {
      clean.push(curr);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

