// Compute left and right timber profile as a function of y (65 to 1135)
function getPilingBounds(y) {
  let cx = 600;
  let baseHalfW = 212;

  // Slight natural taper and tidal waisting (erosion in the mid-tidal zone)
  let normY = constrain((y - 65) / (1135 - 65), 0, 1);
  let taper = lerp(-4, 10, normY);
  let tidalWaist = -14 * exp(-pow((y - 430) / 140, 2));

  // Organic edge irregularity from wood splinters, mussels, and barnacles
  let nL = (noise(y * 0.018, 1.2) - 0.5) * 14;
  let nR = (noise(y * 0.018, 8.7) - 0.5) * 14;

  // Mussel bed bulging around y = 500..720
  let musselBulgeL = 22 * exp(-pow((y - 605) / 85, 2)) * pow(noise(y * 0.04, 3.1), 1.3);
  let musselBulgeR = 24 * exp(-pow((y - 615) / 85, 2)) * pow(noise(y * 0.04, 6.4), 1.3);

  // Barnacle encrustation roughness around y = 710..950
  let barnBulgeL = 11 * exp(-pow((y - 830) / 95, 2)) * (noise(y * 0.09, 2.2) - 0.2);
  let barnBulgeR = 11 * exp(-pow((y - 830) / 95, 2)) * (noise(y * 0.09, 9.1) - 0.2);

  // Kelp flare at base y = 950..1135
  let kelpFlare = y > 940 ? pow((y - 940) / 195, 1.6) * 26 : 0;

  let left = cx - baseHalfW - taper - tidalWaist + nL - musselBulgeL - barnBulgeL - kelpFlare * 0.8;
  let right = cx + baseHalfW + taper + tidalWaist + nR + musselBulgeR + barnBulgeR + kelpFlare * 0.8;

  // Top crown bevel
  if (y < 82) {
    let crownFactor = (82 - y) / 17;
    left += crownFactor * 16;
    right -= crownFactor * 14;
  }

  return { left, right, cx, w: right - left };
}

// Displace wood grain x-coordinate around knots and natural timber twist
function getGrainX(baseX, y) {
  let dx = (noise(baseX * 0.012, y * 0.004) - 0.5) * 14;
  for (let k of knots) {
    let dy = y - k.y;
    let distX = baseX - k.x;
    let r2 = distX * distX + (dy * 0.55) * (dy * 0.55);
    let influence = exp(-r2 / (k.r * k.r * 2.8));
    let sign = distX >= 0 ? 1 : -1;
    dx += sign * k.r * 1.15 * influence * exp(- abs(distX) / (k.r * 2.2));
  }
  return baseX + dx;
}

function initGeometry() {
  // 1. Timber knots in the upper/bleached zones
  knots = [
    { x: 518, y: 202, r: 22, rx: 16, ry: 28 },
    { x: 688, y: 378, r: 19, rx: 14, ry: 24 },
    { x: 452, y: 446, r: 13, rx: 10, ry: 17 }
  ];

  // 2. Deep vertical splits / desiccation checks in the wood
  let splitSeeds = [
    { x: 438, yStart: 68, yEnd: 545, maxW: 9.5 },
    { x: 486, yStart: 66, yEnd: 380, maxW: 6.5 },
    { x: 556, yStart: 65, yEnd: 710, maxW: 14.0 },
    { x: 612, yStart: 130, yEnd: 620, maxW: 8.5 },
    { x: 658, yStart: 66, yEnd: 510, maxW: 11.5 },
    { x: 724, yStart: 68, yEnd: 665, maxW: 10.0 },
    { x: 772, yStart: 95, yEnd: 465, maxW: 7.0 },
    // Secondary shorter splits
    { x: 415, yStart: 140, yEnd: 330, maxW: 4.2 },
    { x: 528, yStart: 255, yEnd: 520, maxW: 5.5 },
    { x: 584, yStart: 67, yEnd: 295, maxW: 5.8 },
    { x: 634, yStart: 290, yEnd: 590, maxW: 5.0 },
    { x: 698, yStart: 180, yEnd: 350, maxW: 4.5 },
    { x: 748, yStart: 240, yEnd: 540, maxW: 5.2 },
    { x: 468, yStart: 360, yEnd: 640, maxW: 5.0 }
  ];

  for (let s of splitSeeds) {
    let pts = [];
    let steps = floor((s.yEnd - s.yStart) / 8);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(s.yStart, s.yEnd, t);
      let gx = getGrainX(s.x, y) + (noise(s.x, y * 0.025) - 0.5) * 8;
      // Width profile: wide near top crown or upper-middle, tapering to a point
      let env = s.yStart < 75 ? pow(1 - t, 0.75) : sin(t * 180);
      let w = s.maxW * env * (0.7 + 0.5 * noise(s.x * 0.1, y * 0.05));
      pts.push({ x: gx, y, w });
    }
    splits.push({ ...s, pts });
  }

  // 3. Major & minor high-water marks (ruled lines of salt scum)
  tideLevels = [
    { y: 132, major: true, weight: 1.0, label: "EHWS" },
    { y: 176, major: false, weight: 0.45 },
    { y: 222, major: true, weight: 1.25, label: "MHWS" },
    { y: 268, major: false, weight: 0.55 },
    { y: 314, major: true, weight: 1.35, label: "MHHW" },
