    { y: 494, major: true, weight: 1.3, label: "MHWN" },
    { y: 562, major: false, weight: 0.5 },
    { y: 632, major: true, weight: 1.15, label: "MTL" },
    { y: 688, major: false, weight: 0.55 },
    { y: 734, major: true, weight: 1.25, label: "MLWN" },
    { y: 828, major: false, weight: 0.5 },
    { y: 924, major: true, weight: 1.1, label: "MLWS" },
    { y: 1022, major: false, weight: 0.45 },
    { y: 1122, major: true, weight: 1.3, label: "CD" }
  ];

  // 4. Generate Acorn Barnacles (dense crust y = 695..955, plus crevice pioneers y = 435..695)
  let candidates = [];
  // Main barnacle zone
  for (let i = 0; i < 1600; i++) {
    let y = random(685, 958);
    let b = getPilingBounds(y);
    let x = random(b.left + 8, b.right - 8);
    let r = random(4.5, 14.5) * (0.85 + 0.3 * sin(map(y, 685, 958, 20, 160)));
    candidates.push({ x, y, r });
  }
  // Pioneer barnacles climbing up the splits and mid-tide crevices
  for (let s of splits) {
    for (let pt of s.pts) {
      if (pt.y > 425 && pt.y < 710 && random() < 0.65) {
        let count = floor(random(1, 4));
        for (let c = 0; c < count; c++) {
          candidates.push({
            x: pt.x + random(-14, 14),
            y: pt.y + random(-8, 8),
            r: random(3.8, 9.5)
          });
        }
      }
    }
  }

  // Pack barnacles with slight overlap allowed for realistic calcareous fusing
  for (let cand of candidates) {
    let ok = true;
    for (let existing of barnacles) {
      let d = dist(cand.x, cand.y, existing.x, existing.y);
      if (d < (cand.r + existing.r) * 0.72) {
        ok = false;
        break;
      }
    }
    if (ok) {
      barnacles.push(cand);
    }
  }
  // Sort top-to-bottom slightly weighted by radius
  barnacles.sort((a, b) => (a.y - a.r * 0.3) - (b.y - b.r * 0.3));

  // 5. Generate Mussel-Blue Clusters (y = 478..738)
  let clusterCenters = [
    { x: 425, y: 535, rx: 48, ry: 36, count: 22 },
    { x: 485, y: 518, rx: 52, ry: 34, count: 24 },
    { x: 558, y: 505, rx: 56, ry: 38, count: 28 },
    { x: 645, y: 525, rx: 54, ry: 36, count: 25 },
    { x: 728, y: 515, rx: 50, ry: 34, count: 24 },
    { x: 785, y: 548, rx: 45, ry: 38, count: 20 },

    { x: 408, y: 605, rx: 55, ry: 48, count: 28 },
    { x: 478, y: 592, rx: 64, ry: 50, count: 32 },
    { x: 556, y: 585, rx: 68, ry: 54, count: 36 },
    { x: 632, y: 602, rx: 64, ry: 50, count: 32 },
    { x: 718, y: 595, rx: 62, ry: 48, count: 30 },
    { x: 792, y: 615, rx: 52, ry: 46, count: 26 },

    { x: 438, y: 675, rx: 56, ry: 42, count: 26 },
    { x: 518, y: 668, rx: 62, ry: 45, count: 30 },
    { x: 595, y: 682, rx: 60, ry: 44, count: 28 },
    { x: 678, y: 672, rx: 58, ry: 42, count: 28 },
    { x: 758, y: 685, rx: 52, ry: 40, count: 24 }
  ];

  for (let cc of clusterCenters) {
    for (let i = 0; i < cc.count; i++) {
      let ang = random(-180, 180);
      let rad = pow(random(), 0.65);
      let mx = cc.x + cos(ang) * cc.rx * rad;
      let my = cc.y + sin(ang) * cc.ry * rad;
      let b = getPilingBounds(my);
      mx = constrain(mx, b.left - 14, b.right + 14);

      // Mussels point outward/downward from the crevice center
      let outAngle = atan2(my - (cc.y - 10), mx - cc.x);
      // Bias slightly downward as mussels hang by byssal threads
      let shellAngle = outAngle * 0.55 + 90 * 0.45 + random(-22, 22);
      let len = random(24, 52) * (1.05 - 0.35 * rad);
      let wid = len * random(0.42, 0.54);
      let zOrder = my + (1 - rad) * 25 + random(-8, 8);
      mussels.push({
        x: mx,
        y: my,
        len,
        wid,
        angle: shellAngle,
        zOrder,
        cx: cc.x,
        cy: cc.y,
        hasBarnacle: random() < 0.32
      });
    }
  }
  mussels.sort((a, b) => a.zOrder - b.zOrder);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Overcast archival paper ground
  background("#f1efe8");
  drawPaperAndMarginAtmosphere();

  // 2. Layered transparent watercolor glazes (viridian, burnt umber, Payne's grey)
  drawWatercolorUnderpainting();

  // 3. Bleached grey & dry silver-cracked wood grain + deep vertical splits
  drawWoodGrainAndSplits();

  // 4. Acorn barnacle crust & basal scars (with sharp graphite plate detail)
  drawBarnacleZone();

  // 5. Mussel-blue clusters (the vibrant marine blue accent)
  drawMusselClusters();

  // 6. Slick black-green kelp at the base & calm tide waterline
  drawKelpBaseAndWaterline();

  // 7. Crisp ruled lines of salt scum & documentary tide-chart measurement
  drawSaltScumAndTideChart();

  noLoop();
}

