  brush.noFill();

  // Very faint horizontal overcast atmospheric bands behind the piling
  for (let i = 0; i < 28; i++) {
    let y = map(i, 0, 27, 70, 1130);
    brush.set("glaze", i % 2 === 0 ? "#dfddd4" : "#d8dad8", random(0.9, 1.5));
    brush.line(90, y, 1110, y + random(-2, 2));
  }
}

// ============================================================================
// 2. LAYERED TRANSPARENT WATERCOLOR GLAZES
// ============================================================================
function drawWatercolorUnderpainting() {
  brush.noField();
  brush.noStroke();

  // Helper to build a horizontal band polygon following the piling silhouette
  function fillPilingBand(y1, y2, col, alpha, bleed, tex, border, xInsetL = 0, xInsetR = 0) {
    brush.fill(col, alpha);
    brush.fillBleed(bleed, "out");
    brush.fillTexture(tex, border);
    brush.beginShape(0.15);
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let y = lerp(y1, y2, i / steps);
      let b = getPilingBounds(y);
      brush.vertex(b.left + xInsetL + random(-2, 2), y);
    }
    for (let i = steps; i >= 0; i--) {
      let y = lerp(y1, y2, i / steps);
      let b = getPilingBounds(y);
      brush.vertex(b.right - xInsetR + random(-2, 2), y);
    }
    brush.endShape(true);
    brush.noFill();
  }

  // --- ZONE A: Dry Silver-Cracked Wood at Top (y = 66..285) ---
  fillPilingBand(66, 285, "#d2d5d6", 65, 0.12, 0.5, 0.3);
  fillPilingBand(68, 210, "#c5c0b7", 38, 0.15, 0.45, 0.25, 12, 12);
  fillPilingBand(195, 295, "#9ea5aa", 52, 0.18, 0.55, 0.35);

  // --- ZONE B: Bleached Grey Grain (y = 275..505) ---
  fillPilingBand(275, 505, "#8f969c", 72, 0.18, 0.6, 0.38);
  fillPilingBand(310, 460, "#756a5e", 45, 0.22, 0.55, 0.3, 18, 18); // Burnt umber undertone
  fillPilingBand(395, 515, "#5d6870", 68, 0.2, 0.6, 0.4); // Payne's grey high-tide dampness

  // --- ZONE C: Mussel-Blue Cluster Zone (y = 485..735) ---
  fillPilingBand(485, 735, "#384957", 88, 0.22, 0.65, 0.42); // Payne's grey wet timber
  fillPilingBand(495, 720, "#1d4c6e", 82, 0.25, 0.65, 0.45, 8, 8); // Marine mussel-blue glaze
  fillPilingBand(540, 710, "#473528", 65, 0.2, 0.55, 0.35, 25, 25); // Burnt umber crevice warmth

  // --- ZONE D: Acorn Barnacle Crust (y = 705..955) ---
  fillPilingBand(705, 955, "#505759", 92, 0.2, 0.7, 0.45); // Wet limestone/ash base
  fillPilingBand(725, 950, "#1e4b3d", 68, 0.24, 0.65, 0.4, 10, 10); // Viridian tidal film
  fillPilingBand(780, 960, "#3b2c20", 74, 0.22, 0.6, 0.38, 15, 15); // Burnt umber lower stain

  // --- ZONE E: Slick Black-Green Kelp Base (y = 925..1135) ---
  fillPilingBand(925, 1135, "#153026", 115, 0.24, 0.65, 0.45); // Deep viridian-black
  fillPilingBand(950, 1135, "#1b242b", 110, 0.2, 0.6, 0.4, 6, 6); // Payne's grey depth
  fillPilingBand(980, 1135, "#2b1f16", 90, 0.22, 0.55, 0.35, 18, 18); // Burnt umber kelp shadow

  // Vertical cylindrical shading glazes along left and right edges of the timber
  for (let side of [-1, 1]) {
    for (let pass = 0; pass < 7; pass++) {
      let inset = 6 + pass * 11;
      for (let y = 72; y < 1110; y += 95) {
        let y2 = min(1125, y + 105);
        let b1 = getPilingBounds(y);
        let b2 = getPilingBounds(y2);
        let x1 = side < 0 ? b1.left + inset : b1.right - inset;
        let x2 = side < 0 ? b2.left + inset : b2.right - inset;

        let col = y < 300 ? "#8a9196" : (y < 520 ? "#566069" : (y < 750 ? "#253847" : "#162621"));
        brush.set("glaze", col, map(pass, 0, 6, 1.35, 0.55));
        brush.line(x1, y, x2, y2);
      }
    }
  }

  // Horizontal tidal wetness glazes at each high-water transition
  for (let tl of tideLevels) {
    if (tl.y > 1100) continue;
    let b = getPilingBounds(tl.y);
    let glazeCol = tl.y < 320 ? "#959ca1" : (tl.y < 520 ? "#525e68" : (tl.y < 760 ? "#1f475c" : "#183b30"));
    brush.set("fine_glaze", glazeCol, tl.major ? 1.4 : 0.8);
    brush.line(b.left + 4, tl.y + 4, b.right - 4, tl.y + 4);
    if (tl.major) {
      brush.set("fine_glaze", "#4f3e30", 0.9); // Subtle burnt umber tide-line stain
      brush.line(b.left + 10, tl.y + 8, b.right - 10, tl.y + 8);
    }
  }
}

// ============================================================================
// 3. BLEACHED GREY & DRY SILVER WOOD GRAIN + DEEP SPLITS
// ============================================================================
function drawWoodGrainAndSplits() {
  brush.noField();

  // A. Weathered Top Crown (End-grain and jagged splintered top at y = 64..86)
  let topB = getPilingBounds(68);
  for (let x = topB.left; x <= topB.right; x += 2.2) {
    let crownY = 66 + (noise(x * 0.06, 1.1) - 0.5) * 9;
    // Check if inside a split mouth
    let inSplit = false;
    for (let s of splits) {
      if (s.yStart < 72 && abs(x - s.pts[0].x) < s.pts[0].w * 0.7) {
        crownY += 10;
        inSplit = true;
      }
    }
    brush.set("chalk_scum", inSplit ? "#4c5257" : "#e3e5e4", random(0.6, 1.1));
    brush.line(x, crownY, x + random(-1, 1), crownY + random(14, 28));
    brush.set("needle", "#3a4045", random(0.6, 1.0));
    brush.line(x + 1, crownY + 2, x + 1, crownY + random(10, 22));
  }

  // B. Thousands of vertical wood-grain tracheid fibers & earlywood channels (y = 68..940)
  let numThreads = 230;
  for (let i = 0; i < numThreads; i++) {
    let frac = i / (numThreads - 1);
    let baseX = lerp(388, 812, frac);

    // Walk down the timber in segments so color & texture shift through the tidal zones
    let y = 68 + random(0, 12);
    while (y < 935) {
      let segLen = random(26, 62);
      let yNext = min(940, y + segLen);
      let midY = (y + yNext) * 0.5;
      let b = getPilingBounds(midY);

      let x1 = getGrainX(baseX, y);
      let x2 = getGrainX(baseX, yNext);

      if (x1 > b.left + 3 && x1 < b.right - 3 && x2 > b.left + 3 && x2 < b.right - 3) {
        // Determine zone appearance
        if (midY < 275) {
          // Dry silver-cracked wood: bright silver latewood ridges + crisp graphite micro-fissures
          if (i % 2 === 0) {
            brush.set("chalk_scum", random() < 0.6 ? "#e4e6e5" : "#cfd3d4", random(0.45, 0.85));
            brush.line(x1, y, x2, yNext);
          }
          let shadeCol = random() < 0.7 ? "#565d63" : "#4a3d33";
          brush.set("needle", shadeCol, random(0.55, 1.05));
          brush.line(x1 + 0.8, y, x2 + 0.8, yNext);
        } else if (midY < 505) {
          // Bleached grey grain: water-worn channels, Payne's grey & burnt umber grooves
          if (i % 3 === 0) {
            brush.set("chalk_scum", "#c6cbcd", random(0.4, 0.75));
            brush.line(x1, y, x2, yNext);
          }
          let grooveCol = random() < 0.55 ? "#3f4850" : (random() < 0.6 ? "#524336" : "#2b4744");
          brush.set("2H", grooveCol, random(0.45, 0.85));
          brush.line(x1 + 1.0, y, x2 + 1.0, yNext);
        } else if (midY < 735) {
          // Damp timber visible between mussel clusters
          if (random() < 0.65) {
            let dampCol = random() < 0.5 ? "#22303b" : "#1b3d38";
            brush.set("2B", dampCol, random(0.5, 0.9));
            brush.line(x1, y, x2, yNext);
          }
        } else {
          // Lower barnacle zone underlying wood grooves
          if (random() < 0.35) {
            brush.set("2B", "#1a2824", random(0.5, 0.8));
            brush.line(x1, y, x2, yNext);
          }
        }
      }
      y = yNext + random(-3, 5);
    }
  }

  // C. Horizontal desiccation cross-checks in the dry silver top & wave-ripple erosion in bleached zone
  for (let i = 0; i < 180; i++) {
    let y = random(72, 490);
    let b = getPilingBounds(y);
    let x = random(b.left + 12, b.right - 18);
    let w = random(4, 16);
    if (y < 275) {
      // Crisp silver-wood cross-checks
      brush.set("needle", "#2e353b", random(0.5, 0.85));
      brush.line(x, y, x + w, y + random(-1.5, 1.5));
      brush.set("chalk_scum", "#eceee9", 0.45);
      brush.line(x, y + 1.2, x + w, y + 1.2);
    } else {
      // Soft horizontal wave-eroded earlywood ripples
      brush.set("2H", "#4e565e", random(0.35, 0.65));
      brush.line(x, y, x + w * 1.4, y + random(-1, 1));
    }
  }

  // D. Render the Weathered Knots
  for (let k of knots) {
    // Dark recessed knot core
    brush.noStroke();
    brush.wash("#221c18", 210);
    brush.circle(k.x, k.y, k.rx * 0.75, 0.25);
    brush.noWash();

    // Concentric elliptical rings and radial knot checks
    for (let r = 3; r <= k.ry; r += 2.4) {
      let pts = [];
      for (let a = 0; a <= 360; a += 30) {
        let px = k.x + cos(a) * (r * (k.rx / k.ry)) + (noise(a, r) - 0.5) * 2.5;
        let py = k.y + sin(a) * r + (noise(r, a) - 0.5) * 2.5;
        pts.push([px, py]);
      }
      brush.set("needle", r < k.ry * 0.5 ? "#1b1613" : "#443d37", random(0.6, 1.0));
      brush.spline(pts, 0.5);
    }
    // Radial star cracks inside knot
    for (let a = 0; a < 360; a += 42) {
      let ang = a + random(-10, 10);
      brush.set("needle", "#111417", 0.9);
      brush.line(k.x, k.y, k.x + cos(ang) * k.rx * 0.9, k.y + sin(ang) * k.ry * 0.9);
    }
    // Silver bleached rim highlight on knot collar
    brush.set("chalk_scum", "#dfe2e0", 0.65);
    brush.arc(k.x, k.y, k.rx * 0.95, -60, 110);
  }

  // E. Deep Vertical Splits in the Grain (abyssal core, stepped inner wall, bridging splinters)
  for (let s of splits) {
    let pts = s.pts;

    // 1. Stepped inner wood wall (shows 3D thickness of the crack)
    let perspSide = s.x < 600 ? 1 : -1;
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i];
      let p2 = pts[i + 1];
      let wallCol = p1.y < 290 ? "#686e73" : (p1.y < 510 ? "#484039" : "#253330");
      brush.set("cpencil", wallCol, max(0.4, p1.w * 0.22));
      brush.line(
        p1.x + perspSide * p1.w * 0.35, p1.y,
        p2.x + perspSide * p2.w * 0.35, p2.y
      );
    }

    // 2. Deep dark chasm core (Payne's grey + burnt umber black)
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i];
      let p2 = pts[i + 1];
      let passes = ceil(p1.w * 0.7);
      for (let p = 0; p < passes; p++) {
        let off = map(p, 0, max(1, passes - 1), -p1.w * 0.38, p1.w * 0.38);
        brush.set("rotring", p % 2 === 0 ? "#12161a" : "#211914", random(0.8, 1.4));
        brush.line(p1.x + off, p1.y, p2.x + off * (p2.w / max(0.5, p1.w)), p2.y);
      }
    }

    // 3. Sharp graphite outer edges + bright silver splinter rim + internal bridging fibers
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i];
      let p2 = pts[i + 1];

      // Left and right jagged rims
      brush.set("needle", "#0d1114", 1.1);
      brush.line(p1.x - p1.w * 0.5, p1.y, p2.x - p2.w * 0.5, p2.y);
      brush.line(p1.x + p1.w * 0.5, p1.y, p2.x + p2.w * 0.5, p2.y);

      // Lit silver splinter edge
      if (p1.y < 520) {
        let rimCol = p1.y < 280 ? "#eff0ec" : "#c8cdcf";
        brush.set("chalk_scum", rimCol, random(0.5, 0.85));
        brush.line(
          p1.x - perspSide * p1.w * 0.55, p1.y,
          p2.x - perspSide * p2.w * 0.55, p2.y
        );
      }

      // Torn wood fibers bridging diagonally across the split
      if (p1.w > 3.0 && random() < 0.42) {
        let fy = lerp(p1.y, p2.y, random());
        brush.set("needle", p1.y < 320 ? "#b8bdbf" : "#6c655d", 0.65);
        brush.line(
          p1.x - p1.w * 0.45, fy,
          p1.x + p1.w * 0.45, fy + random(-5, 5)
        );
      }
    }
  }
}

// ============================================================================
// 4. ACORN BARNACLE CRUST & BASAL SCARS
// ============================================================================
function drawBarnacleZone() {
  brush.noField();

  // A. Calcareous Basal Scars (flat white spoked rings left by dead barnacles on bleached/mid wood)
  for (let i = 0; i < 110; i++) {
    let y = random(420, 745);
    let b = getPilingBounds(y);
    let x = random(b.left + 14, b.right - 14);
    let r = random(3.2, 7.5);

    brush.noStroke();
    brush.wash("#d8d7cf", 150);
    brush.circle(x, y, r, 0.2);
    brush.noWash();

    // Radial septa spokes in fine graphite
    brush.set("needle", "#585e63", 0.55);
    brush.circle(x, y, r, 0.15);
    for (let a = 0; a < 360; a += 45) {
      brush.line(x + cos(a) * r * 0.25, y + sin(a) * r * 0.25, x + cos(a) * r, y + sin(a) * r);
    }
  }

  // B. Underlying Barnacle Pavement Matrix (y = 700..955)
  for (let i = 0; i < 420; i++) {
    let y = random(700, 955);
    let b = getPilingBounds(y);
    let x = random(b.left + 6, b.right - 6);
    let r = random(4, 11);
    let col = y > 860 && random() < 0.45 ? "#2e4a3f" : (random() < 0.5 ? "#384044" : "#878982");
    brush.set("cpencil", col, random(0.8, 1.5));
    brush.circle(x, y, r, 0.3);
  }

  // C. Render Every Individual Acorn Barnacle with Parietal Plates & Operculum Split
  for (let barn of barnacles) {
    drawSingleBarnacle(barn.x, barn.y, barn.r);
  }

  // D. Hundreds of Tiny Juvenile Spat Barnacles crusting crevices & edges
  for (let i = 0; i < 520; i++) {
    let y = random() < 0.78 ? random(685, 955) : random(460, 685);
    let b = getPilingBounds(y);
    let x = random(b.left + 4, b.right - 4);
    let sr = random(1.4, 3.2);

    // Chalky ring
    brush.set("chalk_scum", y > 880 ? "#c5cec8" : "#ecebe4", random(0.55, 0.9));
    brush.circle(x, y, sr, 0.15);
    // Dark pinhole aperture
    brush.set("needle", "#141b1f", 0.95);
    brush.line(x - sr * 0.4, y, x + sr * 0.4, y);
  }
}

function drawSingleBarnacle(bx, by, r) {
  // Cylindrical perspective tilt based on horizontal distance from piling centerline
  let perspX = constrain((bx - 600) / 225, -1, 1);
  let wetFactor = constrain(map(by, 680, 955, 0, 1), 0, 1);

  // 6-sided irregular parietal base & shifted top opercular rim
  let numPlates = 6;
  let basePts = [];
  let topPts = [];
  let rotOff = (bx * 7 + by * 13) % 60;

  let apX = bx + perspX * r * 0.34;
  let apY = by - r * 0.10;
  let apRx = r * 0.44 * (1 - abs(perspX) * 0.22);
  let apRy = r * 0.36;

  for (let i = 0; i < numPlates; i++) {
    let a = rotOff + i * (360 / numPlates);
    let radVar = r * (0.88 + 0.24 * noise(bx * 0.1 + i, by * 0.1));
    basePts.push({
      x: bx + cos(a) * radVar * (1 - abs(perspX) * 0.12),
      y: by + sin(a) * radVar * 0.88
    });
    topPts.push({
      x: apX + cos(a) * apRx,
      y: apY + sin(a) * apRy
    });
  }

  // 1. Cast shadow around base in dark Payne's grey / burnt umber
  brush.set("2B", wetFactor > 0.6 ? "#14241e" : "#22292e", 0.75);
  for (let i = 0; i < numPlates; i++) {
    let p1 = basePts[i];
    let p2 = basePts[(i + 1) % numPlates];
    brush.line(p1.x, p1.y + 1.2, p2.x, p2.y + 1.2);
  }

  // 2. Parietal Shell Plates (shaded by overcast top-light + viridian algal tint near bottom)
  for (let i = 0; i < numPlates; i++) {
    let b1 = basePts[i];
    let b2 = basePts[(i + 1) % numPlates];
    let t1 = topPts[i];
    let t2 = topPts[(i + 1) % numPlates];

    let midY = (b1.y + b2.y) * 0.5;
    let isUpperPlate = midY < by;

    let plateCol;
    if (isUpperPlate) {
      plateCol = wetFactor > 0.65 ? "#cfd6d0" : (random() < 0.6 ? "#ebeae2" : "#d8d7ce");
    } else {
      plateCol = wetFactor > 0.65 ? "#687a72" : (random() < 0.5 ? "#9ea29e" : "#7d8280");
    }

    // Fill plate with radial chalk/calcified strokes and transverse growth striae
    let steps = max(2, floor(r * 0.38));
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let lx1 = lerp(b1.x, t1.x, u);
      let ly1 = lerp(b1.y, t1.y, u);
      let lx2 = lerp(b2.x, t2.x, u);
      let ly2 = lerp(b2.y, t2.y, u);

      brush.set("chalk_scum", plateCol, map(r, 4, 15, 0.45, 0.9));
      brush.line(lx1, ly1, lx2, ly2);

      // Fine graphite concentric growth ridge on larger barnacles
      if (r > 7.5 && s % 2 === 1) {
        brush.set("needle", "#5e6466", 0.45);
        brush.line(lx1, ly1, lx2, ly2);
      }
    }

    // Crisp graphite suture line separating adjacent parietal plates
    brush.set("needle", "#252c32", map(r, 4, 15, 0.55, 0.95));
    brush.line(b1.x, b1.y, t1.x, t1.y);
  }

  // 3. Recessed Central Operculum (Dark Cavity + Tergum/Scutum Valve Split)
  brush.noStroke();
  brush.wash("#161e22", 230);
  brush.circle(apX, apY, apRx * 0.85, 0.18);
  brush.noWash();

  // Inner opercular valve plates (scutum & tergum) with sharp central cleft
  brush.set("needle", "#6e7678", 0.6);
  brush.line(apX - apRx * 0.65, apY - apRy * 0.25, apX + apRx * 0.65, apY - apRy * 0.15);

  // Razor-sharp black-graphite opercular split
  brush.set("needle", "#080c0f", 1.15);
  brush.line(apX - apRx * 0.78, apY, apX + apRx * 0.78, apY + apRy * 0.1);
  // Cross-suture between tergum and scutum
  brush.line(apX + apRx * 0.15, apY - apRy * 0.55, apX - apRx * 0.1, apY + apRy * 0.55);

  // Crisp chalk-white rim highlight along the top edge of the orifice
  brush.set("chalk_scum", "#f6f5f0", map(r, 4, 15, 0.45, 0.85));
  brush.line(topPts[3].x, topPts[3].y, topPts[4].x, topPts[4].y);
  brush.line(topPts[4].x, topPts[4].y, topPts[5].x, topPts[5].y);
}

// ============================================================================
// 5. MUSSEL-BLUE CLUSTERS (THE MARINE ACCENT)
// ============================================================================
function drawMusselClusters() {
  brush.noField();

  // A. Deep crevice shadows & golden-umber byssal threads anchoring the clusters
  for (let m of mussels) {
    if (random() < 0.45) {
      // Fibrous byssus threads radiating from timber crevice to mussel umbo
      let threads = floor(random(2, 5));
      for (let t = 0; t < threads; t++) {
        let tx = m.cx + random(-18, 18);
        let ty = m.cy + random(-12, 12);
        brush.set("needle", random() < 0.6 ? "#4f3c28" : "#2b2117", 0.65);
        brush.line(tx, ty, m.x, m.y);
      }
    }
  }

  // B. Render each mussel shell valve from back to front
  for (let m of mussels) {
    drawSingleMussel(m);
  }
}

function drawSingleMussel(m) {
  let x = m.x;
  let y = m.y;
  let L = m.len;
  let W = m.wid;
  let ang = m.angle;

  let ca = cos(ang);
  let sa = sin(ang);

  // Helper to transform local shell coordinates (u along length 0..1, v across width -0.5..0.5)
  function shellPt(u, v) {
    // Asymmetric fan/teardrop mussel contour: pointed umbo at u=0, broad rounded posterior at u=1
    let profileW = W * pow(sin(u * 180), 0.68) * (0.45 + 0.55 * u);
    // Slight dorsal arch asymmetry
    let arch = W * 0.12 * sin(u * 180);
    let lx = u * L;
    let ly = v * profileW - arch;
    return {
      x: x + lx * ca - ly * sa,
      y: y + lx * sa + ly * ca
    };
  }

  // 1. Deep cast shadow underneath posterior rim
  let sh1 = shellPt(0.3, 0.45);
  let sh2 = shellPt(0.75, 0.52);
  let sh3 = shellPt(1.0, 0.0);
  brush.set("2B", "#0a121a", 1.5);
  brush.line(sh1.x, sh1.y + 3, sh2.x, sh2.y + 3.5);
  brush.line(sh2.x, sh2.y + 3.5, sh3.x, sh3.y + 3);

  // 2. Solid dark navy-slate base wash for the shell valve
  brush.noStroke();
  brush.wash("#122b42", 225);
  brush.beginShape(0.2);
  let outlineSteps = 12;
  for (let i = 0; i <= outlineSteps; i++) {
    let p = shellPt(i / outlineSteps, -0.5);
    brush.vertex(p.x, p.y);
  }
  for (let i = outlineSteps; i >= 0; i--) {
    let p = shellPt(i / outlineSteps, 0.5);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Layered Mussel-Blue Iridescent Banding (Prussian blue, cerulean slate, viridian-navy)
  let longStrips = 7;
  for (let s = 0; s <= longStrips; s++) {
    let v = map(s, 0, longStrips, -0.44, 0.44);
    let pStart = shellPt(0.12, v);
    let pMid = shellPt(0.55, v);
    let pEnd = shellPt(0.92, v);

    let col;
    if (abs(v) > 0.34) {
      col = "#0d1f30"; // Dark periostracum margin
    } else if (v < -0.05) {
      col = random() < 0.55 ? "#2b6aa0" : "#3f84bd"; // Lit upper valve curvature (rich mussel-blue)
    } else if (v < 0.2) {
      col = random() < 0.6 ? "#1c4d78" : "#18475c"; // Deep marine Prussian / viridian-blue
    } else {
      col = "#122e4a"; // Shaded lower valve flank
    }

    brush.set("cpencil", col, map(L, 24, 52, 0.75, 1.35));
    brush.spline([[pStart.x, pStart.y], [pMid.x, pMid.y], [pEnd.x, pEnd.y]], 0.4);
  }

  // 4. Eroded Chalky Silver-Blue Umbo (beak tip at u = 0..0.28)
  for (let s = -0.3; s <= 0.3; s += 0.2) {
    let u0 = shellPt(0.02, s * 0.4);
    let u1 = shellPt(random(0.18, 0.30), s);
    brush.set("chalk_scum", random() < 0.5 ? "#b5c7d4" : "#d8e1e6", 0.6);
    brush.line(u0.x, u0.y, u1.x, u1.y);
  }

  // 5. Concentric Growth Rings (sharp graphite + pale blue-silver striae)
  let numRings = floor(map(L, 24, 52, 6, 11));
  for (let r = 2; r <= numRings; r++) {
    let u = r / (numRings + 1);
    let ringPts = [];
    for (let v = -0.46; v <= 0.46; v += 0.23) {
      let pt = shellPt(u + (1 - abs(v * 1.4)) * 0.08, v);
      ringPts.push([pt.x, pt.y]);
    }
    brush.set("needle", r % 2 === 0 ? "#08131f" : "#689dc7", r % 2 === 0 ? 0.75 : 0.5);
    brush.spline(ringPts, 0.5);
  }

  // 6. Crisp Outer Valve Rim & Hinge Split Line
  let rimPts = [];
  for (let i = 0; i <= 8; i++) {
    let p = shellPt(i / 8, -0.48);
    rimPts.push([p.x, p.y]);
  }
  for (let i = 8; i >= 0; i--) {
    let p = shellPt(i / 8, 0.48);
    rimPts.push([p.x, p.y]);
  }
  brush.set("needle", "#07101a", 0.95);
  brush.spline(rimPts, 0.35);

  // Wet specular sheen streak along the dorsal ridge
  let g1 = shellPt(0.28, -0.18);
  let g2 = shellPt(0.55, -0.16);
  let g3 = shellPt(0.78, -0.10);
  brush.set("wet_sheen", "#cce2f0", map(L, 24, 52, 0.5, 0.95));
  brush.spline([[g1.x, g1.y], [g2.x, g2.y], [g3.x, g3.y]], 0.4);

  // 7. Epibiont Acorn Barnacles encrusted directly on the mussel shell
  if (m.hasBarnacle) {
    let bp = shellPt(random(0.45, 0.78), random(-0.2, 0.2));
    drawSingleBarnacle(bp.x, bp.y, random(3.6, 6.2));
  }
}

// ============================================================================
// 6. SLICK BLACK-GREEN KELP AT THE BASE & WATERLINE
// ============================================================================
function drawKelpBaseAndWaterline() {
  brush.noField();

  // A. Root-like Holdfasts (haptera) gripping the lower barnacle crust (y = 895..955)
  let numFronds = 46;
  let frondRoots = [];
  for (let i = 0; i < numFronds; i++) {
    let frac = i / (numFronds - 1);
    let rootY = random(898, 962);
    let b = getPilingBounds(rootY);
    let rootX = lerp(b.left + 6, b.right - 6, frac) + random(-6, 6);
    frondRoots.push({ x: rootX, y: rootY, frac });

    // Branching holdfast claws gripping between barnacles
    if (i % 2 === 0) {
      for (let c = 0; c < 5; c++) {
        let ca = random(-160, -20);
        let clen = random(10, 24);
        brush.set("cpencil", c % 2 === 0 ? "#132920" : "#2e241a", random(0.8, 1.3));
        brush.line(rootX, rootY, rootX + cos(ca) * clen, rootY + sin(ca) * clen);
        brush.set("needle", "#09140f", 0.75);
        brush.line(rootX, rootY, rootX + cos(ca) * clen, rootY + sin(ca) * clen);
      }
    }
  }

  // B. Broad, Undulating Slick Black-Green Kelp Blades (y = 910..1138)
  for (let pass = 0; pass < 2; pass++) {
    for (let f of frondRoots) {
      if ((pass === 0 && f.frac % 0.1 < 0.05) || (pass === 1 && f.frac % 0.1 >= 0.05)) continue;

      let startX = f.x;
      let startY = f.y;
      let endY = random(1118, 1142);
      let bladeW = random(11, 24);

      // Generate undulating centerline spine
      let spine = [];
      let steps = 9;
      let driftX = (f.frac - 0.5) * 42 + random(-14, 14);
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let sy = lerp(startY, endY, t);
        let wave = sin(t * 260 + f.x * 2.5) * (6 + t * 8);
        let sx = startX + driftX * pow(t, 1.3) + wave;
        // Width tapers at stipe top, widens in middle blade, tapers or splits at water tip
        let w = bladeW * sin(pow(t, 0.7) * 165) * (0.75 + 0.25 * pass);
        spine.push({ x: sx, y: sy, w });
      }

      // 1. Dark black-viridian / burnt umber blade body wash
      let washCol = pass === 0
        ? (random() < 0.6 ? "#0c1c15" : "#1a1712")
        : (random() < 0.65 ? "#132e23" : "#1c2b24");
      brush.noStroke();
      brush.wash(washCol, 220);
      brush.beginShape(0.25);
      for (let s = 0; s <= steps; s++) {
        brush.vertex(spine[s].x - spine[s].w * 0.5, spine[s].y);
      }
      for (let s = steps; s >= 0; s--) {
        brush.vertex(spine[s].x + spine[s].w * 0.5, spine[s].y);
      }
      brush.endShape(true);
      brush.noWash();

      // 2. Longitudinal viridian + burnt umber striations along the blade
      for (let strip = -0.38; strip <= 0.38; strip += 0.25) {
        let stripPts = spine.map(p => [p.x + p.w * strip, p.y]);
        let stCol = strip < 0 ? "#1d4737" : (strip > 0.1 ? "#091410" : "#2c2419");
        brush.set("cpencil", stCol, random(0.7, 1.2));
        brush.spline(stripPts, 0.45);
      }

      // 3. Ruffled blade margins and sharp central midrib
      let leftEdge = [];
      let rightEdge = [];
      let midRib = [];
      for (let s = 0; s <= steps; s++) {
        let p = spine[s];
        let ruffleL = (s % 2 === 0 ? -2.5 : 2.0) * (p.w / 18);
        let ruffleR = (s % 2 === 0 ? 2.5 : -2.0) * (p.w / 18);
        leftEdge.push([p.x - p.w * 0.5 + ruffleL, p.y]);
        rightEdge.push([p.x + p.w * 0.5 + ruffleR, p.y]);
        midRib.push([p.x, p.y]);
      }
      brush.set("needle", "#060e0b", 0.95);
      brush.spline(leftEdge, 0.45);
      brush.spline(rightEdge, 0.45);
      brush.set("needle", "#264f3e", 0.7);
      brush.spline(midRib, 0.45);

      // 4. Slick Wet Specular Reflections (crucial for wet black-green kelp realism)
      if (pass === 1 || random() < 0.5) {
        let sStart = floor(random(1, 4));
        let sEnd = min(steps - 1, sStart + floor(random(2, 5)));
        let sheenPts = [];
        for (let s = sStart; s <= sEnd; s++) {
          sheenPts.push([spine[s].x - spine[s].w * 0.16, spine[s].y]);
        }
        brush.set("wet_sheen", "#b8d1c7", random(0.65, 1.25));
        brush.spline(sheenPts, 0.45);

        // Razor-thin paper-white wet highlight core
        brush.set("chalk_scum", "#e9f2ee", 0.5);
        brush.line(
          sheenPts[0][0], sheenPts[0][1],
          sheenPts[1][0], sheenPts[1][1]
        );
      }

      // 5. Occasional Fucus air bladders (paired vesicles with wet specular rings)
      if (pass === 1 && random() < 0.42) {
        let p = spine[floor(random(2, steps - 2))];
        for (let side of [-1, 1]) {
          let vx = p.x + side * p.w * 0.28;
          let vy = p.y + random(-3, 3);
          brush.noStroke();
          brush.wash("#173326", 230);
          brush.circle(vx, vy, 4.2, 0.15);
          brush.noWash();
          brush.set("needle", "#07120d", 0.85);
          brush.circle(vx, vy, 4.2, 0.15);
          brush.set("chalk_scum", "#d6e8e0", 0.55);
          brush.arc(vx, vy, 2.8, -140, -20);
        }
      }
    }
  }

  // C. Calm Overcast Waterline & Submerged Reflection at Base (y = 1120..1158)
  let bWater = getPilingBounds(1122);
  for (let i = 0; i < 24; i++) {
    let wy = map(i, 0, 23, 1122, 1156);
    let spread = map(i, 0, 23, 25, 85);
    let col = i % 3 === 0 ? "#12241e" : (i % 3 === 1 ? "#1f2b30" : "#cdd4d1");
    let wt = i % 3 === 2 ? 0.55 : random(0.8, 1.5);
    brush.set(i % 3 === 2 ? "chalk_scum" : "fine_glaze", col, wt);
    brush.line(bWater.left - spread + random(-15, 15), wy, bWater.right + spread + random(-15, 15), wy);
  }
}

