// 7. CRISP RULED LINES OF SALT SCUM & DOCUMENTARY TIDE-CHART MEASUREMENT
// ============================================================================
function drawSaltScumAndTideChart() {
  brush.noField();

  // Vertical documentary datum axes flanking the timber piling (tide-chart measurement)
  let leftAxisX = 316;
  let rightAxisX = 884;

  brush.set("needle", "#7a8085", 0.65);
  brush.line(leftAxisX, 66, leftAxisX, 1122);
  brush.line(rightAxisX, 66, rightAxisX, 1122);

  // Fine graduation ruler ticks every 10 px along both measurement axes
  for (let y = 70; y <= 1122; y += 10) {
    let is50 = (y - 70) % 50 === 0;
    let tickLen = is50 ? 9 : 4.5;
    brush.set("needle", is50 ? "#3d444a" : "#878d91", is50 ? 0.75 : 0.45);
    brush.line(leftAxisX - tickLen, y, leftAxisX, y);
    brush.line(rightAxisX, y, rightAxisX + tickLen, y);
  }

  // Top & bottom documentary specimen boundary ticks
  let topB = getPilingBounds(66);
  brush.set("needle", "#4a5157", 0.6);
  brush.line(leftAxisX - 14, 66, topB.left - 12, 66);
  brush.line(topB.right + 12, 66, rightAxisX + 14, 66);

  // Render each High-Water Mark as a Crisp Ruled Line of Salt Scum
  for (let tl of tideLevels) {
    let y = tl.y;
    let b = getPilingBounds(y);

    // 1. Dark mineral/organic under-shadow line directly beneath the salt scum
    brush.set("needle", "#1f272e", tl.major ? 0.95 : 0.55);
    brush.line(b.left + 1, y + 1.4, b.right - 1, y + 1.4);

    // 2. Crisp Ruled Line of White Salt Scum across the timber (dipping only at deep splits)
    let segStart = b.left;
    let stepX = 3;
    for (let x = b.left; x <= b.right; x += stepX) {
      // Check if crossing a deep open split
      let splitDip = 0;
      for (let s of splits) {
        if (y >= s.yStart && y <= s.yEnd) {
          let idx = constrain(floor(map(y, s.yStart, s.yEnd, 0, s.pts.length - 1)), 0, s.pts.length - 1);
          let sp = s.pts[idx];
          if (abs(x - sp.x) < sp.w * 0.48 && sp.w > 3.5) {
            splitDip = sp.w * 0.35;
          }
        }
      }

      if (splitDip > 0) {
        if (x > segStart + 2) {
          drawSaltSegment(segStart, x - 1, y, tl.major, tl.weight);
        }
        // Faint recessed salt trace inside the split
        brush.set("needle", "#b8bab2", 0.45);
        brush.line(x - 1, y + 1.5, x + stepX, y + 1.5);
        segStart = x + stepX;
      }
    }
    if (b.right > segStart) {
      drawSaltSegment(segStart, b.right, y, tl.major, tl.weight);
    }

    // 3. Documentary Tide-Chart Leader Lines & Datum Markers connecting to the axes
    if (tl.major) {
      brush.set("needle", "#4f565c", 0.65);
      // Left datum extension
      brush.line(leftAxisX - 14, y, leftAxisX + 10, y);
      for (let dx = leftAxisX + 16; dx < b.left - 8; dx += 8) {
        brush.line(dx, y, min(dx + 3.5, b.left - 8), y);
      }
      // Right datum extension
      brush.line(rightAxisX - 10, y, rightAxisX + 14, y);
      for (let dx = b.right + 8; dx < rightAxisX - 14; dx += 8) {
        brush.line(dx, y, min(dx + 3.5, rightAxisX - 14), y);
      }

      // Crisp geometric tide-datum triangle indicator on the left & right axes
      drawDatumTriangle(leftAxisX - 14, y, 1);
      drawDatumTriangle(rightAxisX + 14, y, -1);
    } else {
      // Minor high-water tick extensions
      brush.set("needle", "#787f84", 0.5);
      brush.line(b.left - 14, y, b.left - 4, y);
      brush.line(b.right + 4, y, b.right + 14, y);
    }
  }
}

function drawSaltSegment(x1, x2, y, isMajor, wt) {
  // Crisp ruled salt crust in chalk white & bone
  brush.set("chalk_scum", "#f7f6f0", wt * 0.85);
  brush.line(x1, y, x2, y);

  if (isMajor) {
    // Second razor-sharp pass for crystalline salt edge definition
    brush.set("needle", "#ffffff", 0.95);
    brush.line(x1, y - 0.4, x2, y - 0.4);

    // Tiny crystalline salt-scum accumulations caught in vertical grain grooves
    for (let x = x1 + 4; x < x2 - 4; x += random(5, 13)) {
      let scumH = random(1.5, 4.2);
      brush.set("chalk_scum", "#efeee6", random(0.45, 0.8));
      brush.line(x, y - scumH * 0.4, x, y + scumH * 0.7);
    }
  }
}

function drawDatumTriangle(x, y, dir) {
  let s = 4.5 * dir;
  brush.set("needle", "#2a3137", 0.8);
  brush.line(x, y - 3.5, x + s, y);
  brush.line(x + s, y, x, y + 3.5);
  brush.line(x, y - 3.5, x, y + 3.5);
}

