// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function drawOpenPath(pts, curvature = 0.25) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(false);
}

function makeCirclePts(cx, cy, r, n = 64) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function makeRingSectorPts(cx, cy, rIn, rOut, aStart, aEnd, steps = 8) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rOut, cy + sin(a) * rOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
  }
  return pts;
}

function scalePoly(pts, cx, cy, sx, sy = sx, ox = 0, oy = 0) {
  return pts.map(p => [cx + (p[0] - cx) * sx + ox, cy + (p[1] - cy) * sy + oy]);
}

function smoothPolyChaikin(pts, iterations = 1) {
  let curr = pts;
  for (let it = 0; it < iterations; it++) {
    let next = [];
    for (let i = 0; i < curr.length; i++) {
      let p0 = curr[i];
      let p1 = curr[(i + 1) % curr.length];
      next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
      next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
    }
    curr = next;
  }
  return curr;
}

function clipPolyHalfPlane(poly, px, py, nx, ny) {
  if (!poly || poly.length === 0) return [];
  let out = [];
  for (let i = 0; i < poly.length; i++) {
    let cur = poly[i];
    let prev = poly[(i + poly.length - 1) % poly.length];
    let dCur = (cur[0] - px) * nx + (cur[1] - py) * ny;
    let dPrev = (prev[0] - px) * nx + (prev[1] - py) * ny;
    if (dCur <= 0) {
      if (dPrev > 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev <= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi + 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

