function drawBaseGround() {
  background(PAL.lapisVoid);

  // Dense mineral lapis base wash
  brush.noStroke();
  brush.wash(PAL.lapisAbyss, 240);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Inner sanctuary rich mineral watercolor layer
  brush.fill(PAL.lapisDeep, 175);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.55, 0.35);
  brush.rect(150, 150, 900, 900, "corner");
  brush.noFill();
}

function drawOuterBrocadeBorder() {
  // Band from 26 to 82 (width 56px)
  const bOut = 26, bIn = 82;

  // Base cinnabar-dark under-ground for the silk brocade frame
  brush.noStroke();
  brush.wash(PAL.cinnAbyss, 245);
  brush.rect(bOut, bOut, 1200 - 2 * bOut, bIn - bOut, "corner");
  brush.rect(bOut, 1200 - bIn, 1200 - 2 * bOut, bIn - bOut, "corner");
  brush.rect(bOut, bIn, bIn - bOut, 1200 - 2 * bIn, "corner");
  brush.rect(1200 - bIn, bIn, bIn - bOut, 1200 - 2 * bIn, "corner");
  brush.noWash();

  // Collect stepped silk fret blocks by mineral color batch
  const colors = [PAL.cinnMid, PAL.malaMid, PAL.lapisMid, PAL.orpiMid];
  const lightColors = [PAL.cinnBright, PAL.malaBright, PAL.lapisBright, PAL.orpiBright];
  let batches = [[], [], [], []];
  let lightBatches = [[], [], [], []];
  let fretLines = [];

  const segCount = 24;
  const span = 1200 - 2 * bIn; // 1036
  const step = span / segCount;

  // Helper to build one brocade cell at local coords (0..step, 0..56) transformed to edge
  function addBrocadeEdge(isHoriz, isRev) {
    for (let i = 0; i < segCount; i++) {
      let cIdx = i % 4;
      let u0 = bIn + i * step;
      let u1 = u0 + step;
      let um = (u0 + u1) * 0.5;
      let v0 = isRev ? 1200 - bIn : bOut;
      let v1 = isRev ? 1200 - bOut : bIn;
      let vm = (v0 + v1) * 0.5;

      let rectPts = isHoriz
        ? [[u0 + 2, v0 + 3], [u1 - 2, v0 + 3], [u1 - 2, v1 - 3], [u0 + 2, v1 - 3]]
        : [[v0 + 3, u0 + 2], [v1 - 3, u0 + 2], [v1 - 3, u1 - 2], [v0 + 3, u1 - 2]];
      batches[cIdx].push(rectPts);

      let innerPts = isHoriz
        ? [[u0 + 9, v0 + 11], [u1 - 9, v0 + 11], [u1 - 9, v1 - 11], [u0 + 9, v1 - 11]]
        : [[v0 + 11, u0 + 9], [v1 - 11, u0 + 9], [v1 - 11, u1 - 9], [v0 + 11, u1 - 9]];
      lightBatches[cIdx].push(innerPts);

      // Tibetan T-fret key motif inside each cell
      let keyPts = isHoriz
        ? [
            [u0 + 5, vm], [u0 + 5, v0 + 7], [u1 - 5, v0 + 7], [u1 - 5, v1 - 7],
            [u0 + 5, v1 - 7], [u0 + 5, vm + 5], [um + 6, vm + 5], [um + 6, vm - 5], [um - 6, vm - 5]
          ]
        : [
            [vm, u0 + 5], [v0 + 7, u0 + 5], [v0 + 7, u1 - 5], [v1 - 7, u1 - 5],
            [v1 - 7, u0 + 5], [vm + 5, u0 + 5], [vm + 5, um + 6], [vm - 5, um + 6], [vm - 5, um - 6]
          ];
      fretLines.push(keyPts);
    }
  }

  addBrocadeEdge(true, false);  // Top
  addBrocadeEdge(true, true);   // Bottom
  addBrocadeEdge(false, false); // Left
  addBrocadeEdge(false, true);  // Right

  // Batch watercolor fills for the 4 mineral colors
  brush.noStroke();
  for (let c = 0; c < 4; c++) {
    brush.fill(colors[c], 210);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.45, 0.35);
    for (let poly of batches[c]) drawPoly(poly, 0, true);
    brush.noFill();

    brush.wash(lightColors[c], 150);
    for (let poly of lightBatches[c]) drawPoly(poly, 0, true);
    brush.noWash();
  }

  // Draw gold T-fret key lines
  brush.set("gold_hairline", PAL.goldBright, 1.0);
  for (let path of fretLines) {
    drawOpenPath(path, 0);
  }

  // 4 Corner Brocade Medallions
  const corners = [
    [bOut, bOut],
    [1200 - bIn, bOut],
    [bOut, 1200 - bIn],
    [1200 - bIn, 1200 - bIn]
  ];
  for (let [cx0, cy0] of corners) {
    let scx = cx0 + (bIn - bOut) * 0.5;
    let scy = cy0 + (bIn - bOut) * 0.5;
    brush.noStroke();
    brush.wash(PAL.orpiMid, 230);
    brush.rect(cx0 + 3, cy0 + 3, bIn - bOut - 6, bIn - bOut - 6, "corner");
    brush.wash(PAL.cinnMid, 230);
    drawPoly([
      [scx, cy0 + 6], [cx0 + bIn - bOut - 6, scy],
      [scx, cy0 + bIn - bOut - 6], [cx0 + 6, scy]
    ], 0, true);
    brush.noWash();

    brush.set("gold_bold", PAL.goldGleam, 1.0);
    brush.noFill();
    brush.rect(cx0 + 3, cy0 + 3, bIn - bOut - 6, bIn - bOut - 6, "corner");
    drawPoly([
      [scx, cy0 + 6], [cx0 + bIn - bOut - 6, scy],
      [scx, cy0 + bIn - bOut - 6], [cx0 + 6, scy]
    ], 0, true);
    brush.circle(scx, scy, 7, 0.05);
  }
}

function drawCloudScrollBorder() {
  // Band from 90 to 146 (width 56px)
  const bOut = 90, bIn = 146;

  // Deep Lapis mineral ground for cloud band
  brush.noStroke();
  brush.wash(PAL.lapisDeep, 240);
  brush.rect(bOut, bOut, 1200 - 2 * bOut, bIn - bOut, "corner");
  brush.rect(bOut, 1200 - bIn, 1200 - 2 * bOut, bIn - bOut, "corner");
  brush.rect(bOut, bIn, bIn - bOut, 1200 - 2 * bIn, "corner");
  brush.rect(1200 - bIn, bIn, bIn - bOut, 1200 - 2 * bIn, "corner");
  brush.noWash();

  // Build symmetrical cloud scroll motifs along all 4 sides
  let cloudOuterBatches = { mala: [], cinn: [], orpi: [], lapis: [] };
  let cloudInnerBatches = { malaLight: [], cinnLight: [], orpiLight: [], lapisLight: [] };
  let goldOutlines = [];
  let goldSpirals = [];

  const nClouds = 10;
  const span = 1200 - 2 * bIn; // 908
  const step = span / nClouds;

  function makeCloudLobe(x, y, rx, ry, rotDeg) {
    let pts = [];
    let c = cos(rotDeg), s = sin(rotDeg);
    for (let i = 0; i < 14; i++) {
      let a = (i / 14) * 360;
      let lx = cos(a) * rx;
      let ly = sin(a) * ry * (1 + 0.15 * sin(a * 2));
      pts.push([x + lx * c - ly * s, y + lx * s + ly * c]);
    }
    return pts;
  }

  function makeSpiral(x, y, rMax, dir = 1, startA = 0) {
    let pts = [];
    for (let i = 0; i <= 16; i++) {
      let t = i / 16;
      let a = startA + dir * t * 440;
      let r = rMax * (1 - 0.82 * t);
      pts.push([x + cos(a) * r, y + sin(a) * r]);
    }
    return pts;
  }

  function buildEdgeClouds(isHoriz, isRev) {
    for (let i = 0; i < nClouds; i++) {
      let uMid = bIn + (i + 0.5) * step;
      let vMid = isRev ? 1200 - (bOut + bIn) * 0.5 : (bOut + bIn) * 0.5;
      let sign = isRev ? -1 : 1;

      let isEven = i % 2 === 0;
      let mainKey = isEven ? "mala" : "cinn";
      let subKey = isEven ? "orpi" : "lapis";
      let mainLight = isEven ? "malaLight" : "cinnLight";
      let subLight = isEven ? "orpiLight" : "lapisLight";

      // 3 lobes per cloud scroll unit: left wing, right wing, central crown
      let offsets = [
        [-step * 0.27, sign * 6, 16, 11, -18 * sign],
        [step * 0.27, sign * 6, 16, 11, 18 * sign],
        [0, -sign * 4, 21, 14, 0]
      ];

      for (let k = 0; k < offsets.length; k++) {
        let [du, dv, rx, ry, ang] = offsets[k];
        let cx = isHoriz ? uMid + du : vMid + dv;
        let cy = isHoriz ? vMid + dv : uMid + du;
        let rot = isHoriz ? ang : ang + 90;

        let lobe = makeCloudLobe(cx, cy, rx, ry, rot);
        let inner = makeCloudLobe(cx, cy, rx * 0.65, ry * 0.65, rot);

        if (k < 2) {
          cloudOuterBatches[subKey].push(lobe);
          cloudInnerBatches[subLight].push(inner);
        } else {
          cloudOuterBatches[mainKey].push(lobe);
          cloudInnerBatches[mainLight].push(inner);
        }
        goldOutlines.push(lobe);
        goldSpirals.push(makeSpiral(cx, cy, ry * 0.62, k === 0 ? -1 : 1, rot));
      }
    }
  }

  buildEdgeClouds(true, false);
  buildEdgeClouds(true, true);
  buildEdgeClouds(false, false);
  buildEdgeClouds(false, true);

  // Batch watercolor fills for cloud scrolls
  brush.noStroke();
  const outerMap = {
    mala: PAL.malaMid,
    cinn: PAL.cinnMid,
    orpi: PAL.orpiMid,
    lapis: PAL.lapisMid
  };
  for (let k in outerMap) {
    brush.fill(outerMap[k], 220);
    brush.fillBleed(0.03, "in");
    brush.fillTexture(0.4, 0.3);
    for (let p of cloudOuterBatches[k]) drawPoly(p, 0.2, true);
    brush.noFill();
  }

  const innerMap = {
    malaLight: PAL.malaLight,
    cinnLight: PAL.cinnLight,
    orpiLight: PAL.orpiLight,
    lapisLight: PAL.lapisLight
  };
  for (let k in innerMap) {
    brush.wash(innerMap[k], 175);
    for (let p of cloudInnerBatches[k]) drawPoly(p, 0.2, true);
    brush.noWash();
  }

  // Fine gold pen outlines & inner spirals
  brush.set("gold_hairline", PAL.goldBright, 1.0);
  for (let p of goldOutlines) drawPoly(p, 0.2, true);
  for (let s of goldSpirals) drawOpenPath(s, 0.25);

  // 4 Corner Lotus Rosettes in the Cloud Band
  const cCenters = [
    [(bOut + bIn) * 0.5, (bOut + bIn) * 0.5],
    [1200 - (bOut + bIn) * 0.5, (bOut + bIn) * 0.5],
    [(bOut + bIn) * 0.5, 1200 - (bOut + bIn) * 0.5],
    [1200 - (bOut + bIn) * 0.5, 1200 - (bOut + bIn) * 0.5]
  ];
  for (let [ccx, ccy] of cCenters) {
    drawSmallLotusMedallion(ccx, ccy, 23);
  }
}

function drawSmallLotusMedallion(cx, cy, r) {
  let petals = [];
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    let a1 = a - 18, a2 = a + 18;
    petals.push([
      [cx + cos(a1) * r * 0.3, cy + sin(a1) * r * 0.3],
      [cx + cos(a1) * r * 0.85, cy + sin(a1) * r * 0.85],
      [cx + cos(a) * r, cy + sin(a) * r],
      [cx + cos(a2) * r * 0.85, cy + sin(a2) * r * 0.85],
      [cx + cos(a2) * r * 0.3, cy + sin(a2) * r * 0.3]
    ]);
  }
  brush.noStroke();
  brush.wash(PAL.cinnBright, 230);
  for (let p of petals) drawPoly(p, 0.2, true);
  brush.wash(PAL.orpiBright, 240);
  brush.circle(cx, cy, r * 0.36, 0.05);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldGleam, 1.0);
  for (let p of petals) drawPoly(p, 0.2, true);
  brush.circle(cx, cy, r * 0.36, 0.05);
}

function drawCornerSpandrels() {
  // Ornate symmetrical floral/cloud filigree in the 4 corners of the [154..1046] square
  const corners = [
    [158, 158, 1, 1],
    [1042, 158, -1, 1],
    [158, 1042, 1, -1],
    [1042, 1042, -1, -1]
  ];

  let malaLeaves = [];
  let malaHighlights = [];
  let cinnBuds = [];
  let orpiCenters = [];
  let goldScrolls = [];

  for (let [ox, oy, sx, sy] of corners) {
    // Corner lotus medallion at (ox + 68*sx, oy + 68*sy)
    let mcx = ox + 64 * sx;
    let mcy = oy + 64 * sy;

    // Symmetrical scrolling tendrils extending along both axes of the corner spandrel
    const leafSpecs = [
      // Along horizontal spandrel arm
      [ox + 125 * sx, oy + 32 * sy, 28, 12, sx > 0 ? 15 * sy : 180 - 15 * sy],
      [ox + 168 * sx, oy + 24 * sy, 22, 10, sx > 0 ? 8 * sy : 180 - 8 * sy],
      [ox + 206 * sx, oy + 16 * sy, 16, 7, sx > 0 ? 4 * sy : 180 - 4 * sy],
      // Along vertical spandrel arm
      [ox + 32 * sx, oy + 125 * sy, 28, 12, sy > 0 ? 90 - 15 * sx : -90 + 15 * sx],
      [ox + 24 * sx, oy + 168 * sy, 22, 10, sy > 0 ? 90 - 8 * sx : -90 + 8 * sx],
      [ox + 16 * sx, oy + 206 * sy, 16, 7, sy > 0 ? 90 - 4 * sx : -90 + 4 * sx],
      // Diagonal inner flanks
      [ox + 102 * sx, oy + 66 * sy, 22, 10, sx > 0 ? 32 * sy : 180 - 32 * sy],
      [ox + 66 * sx, oy + 102 * sy, 22, 10, sy > 0 ? 90 - 32 * sx : -90 + 32 * sx]
    ];

    for (let [lx, ly, rx, ry, ang] of leafSpecs) {
      let pts = [];
      let c = cos(ang), s = sin(ang);
      for (let i = 0; i < 12; i++) {
        let a = (i / 12) * 360;
        let px = cos(a) * rx;
        let py = sin(a) * ry * (1 - 0.3 * cos(a));
        pts.push([lx + px * c - py * s, ly + px * s + py * c]);
      }
      malaLeaves.push(pts);
      malaHighlights.push(scalePoly(pts, lx, ly, 0.6));
      goldScrolls.push(pts);
    }

    // Cinnabar lotus buds in the corner spandrel
    const budPts = [
      [mcx, mcy, 24],
      [ox + 145 * sx, oy + 46 * sy, 13],
      [ox + 46 * sx, oy + 145 * sy, 13],
      [ox + 24 * sx, oy + 24 * sy, 15]
    ];
    for (let [bx, by, br] of budPts) {
      for (let k = 0; k < 8; k++) {
        let a = k * 45;
        let p = [
          [bx + cos(a - 16) * br * 0.3, by + sin(a - 16) * br * 0.3],
          [bx + cos(a - 12) * br * 0.85, by + sin(a - 12) * br * 0.85],
          [bx + cos(a) * br * 1.1, by + sin(a) * br * 1.1],
          [bx + cos(a + 12) * br * 0.85, by + sin(a + 12) * br * 0.85],
          [bx + cos(a + 16) * br * 0.3, by + sin(a + 16) * br * 0.3]
        ];
        cinnBuds.push(p);
        goldScrolls.push(p);
      }
      orpiCenters.push(makeCirclePts(bx, by, br * 0.42, 12));
    }

    // Gold filigree vine connecting corner to arms
    goldScrolls.push([
      [ox + 18 * sx, oy + 18 * sy],
      [mcx, mcy],
      [ox + 125 * sx, oy + 32 * sy],
      [ox + 185 * sx, oy + 20 * sy],
      [ox + 235 * sx, oy + 12 * sy]
    ]);
    goldScrolls.push([
      [mcx, mcy],
      [ox + 32 * sx, oy + 125 * sy],
      [ox + 20 * sx, oy + 185 * sy],
      [ox + 12 * sx, oy + 235 * sy]
    ]);
  }

  brush.noStroke();
  brush.fill(PAL.malaMid, 215);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.4, 0.3);
  for (let p of malaLeaves) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.wash(PAL.malaLight, 170);
  for (let p of malaHighlights) drawPoly(p, 0.2, true);

  brush.wash(PAL.cinnBright, 225);
  for (let p of cinnBuds) drawPoly(p, 0.2, true);

  brush.wash(PAL.orpiBright, 240);
  for (let p of orpiCenters) drawPoly(p, 0.2, true);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldBright, 1.0);
  for (let p of goldScrolls) drawOpenPath(p, 0.2);
}

function drawRectangularGoldRulings() {
  // Crisp double-gold rulings framing all nested rectangular borders
  const frames = [18, 26, 82, 90, 146, 154];
  brush.noFill();
  for (let i = 0; i < frames.length; i++) {
    let d = frames[i];
    brush.set("gold_bold", i % 2 === 0 ? PAL.goldMid : PAL.goldGleam, 1.0);
