function drawWisdomFlameBand(cx, cy, rIn, rOut) {
  // Base dark cinnabar ring
  brush.noStroke();
  brush.wash(PAL.cinnAbyss, 245);
  for (let s = 0; s < 12; s++) {
    let pts = makeRingSectorPts(cx, cy, rIn, rOut, s * 30, (s + 1) * 30, 8);
    drawPoly(pts, 0, true);
  }
  brush.noWash();

  // 44 symmetrical curling Thangka wisdom flames (Me-ri)
  const nFlames = 44;
  let outerTongues = [];
  let midTongues = [];
  let innerCores = [];
  let sideFlicks = [];
  let goldOutlines = [];
  let goldSpirals = [];

  for (let i = 0; i < nFlames; i++) {
    let aBase = (i / nFlames) * 360 - 90;
    let da = 360 / nFlames;

    // Symmetrical curl direction toward the top apex (-90 deg)
    let rel = ((aBase + 90 + 540) % 360) - 180;
    let curlSign = rel >= 0 ? -1 : 1;
    if (abs(rel) < 2) curlSign = 1;

    let aL = aBase - da * 0.48;
    let aR = aBase + da * 0.48;
    let aMid = aBase + curlSign * da * 0.18;
    let aTip = aBase + curlSign * da * 0.62;
    let aHook = aBase + curlSign * da * 0.35;

    let rMid = lerp(rIn, rOut, 0.52);
    let rShoulder = lerp(rIn, rOut, 0.76);
    let rTip = rOut - 3;

    let flameOuter = [
      [cx + cos(aL) * rIn, cy + sin(aL) * rIn],
      [cx + cos(aBase - curlSign * da * 0.38) * rMid, cy + sin(aBase - curlSign * da * 0.38) * rMid],
      [cx + cos(aBase - curlSign * da * 0.12) * rShoulder, cy + sin(aBase - curlSign * da * 0.12) * rShoulder],
      [cx + cos(aTip) * rTip, cy + sin(aTip) * rTip],
      [cx + cos(aHook) * (rShoulder - 4), cy + sin(aHook) * (rShoulder - 4)],
      [cx + cos(aBase + curlSign * da * 0.42) * (rMid - 5), cy + sin(aBase + curlSign * da * 0.42) * (rMid - 5)],
      [cx + cos(aR) * rIn, cy + sin(aR) * rIn]
    ];
    outerTongues.push(flameOuter);
    goldOutlines.push(flameOuter);

    // Secondary side flick
    let aFlick = aBase - curlSign * da * 0.45;
    let flickPoly = [
      [cx + cos(aBase - curlSign * da * 0.25) * (rIn + 10), cy + sin(aBase - curlSign * da * 0.25) * (rIn + 10)],
      [cx + cos(aFlick) * (rMid + 12), cy + sin(aFlick) * (rMid + 12)],
      [cx + cos(aBase - curlSign * da * 0.08) * (rMid + 2), cy + sin(aBase - curlSign * da * 0.08) * (rMid + 2)]
    ];
    sideFlicks.push(flickPoly);
    goldOutlines.push(flickPoly);

    // Mid vermilion tongue
    let flameMid = [
      [cx + cos(aBase - curlSign * da * 0.28) * (rIn + 4), cy + sin(aBase - curlSign * da * 0.28) * (rIn + 4)],
      [cx + cos(aBase - curlSign * da * 0.18) * rMid, cy + sin(aBase - curlSign * da * 0.18) * rMid],
      [cx + cos(aTip - curlSign * da * 0.12) * (rTip - 11), cy + sin(aTip - curlSign * da * 0.12) * (rTip - 11)],
      [cx + cos(aMid) * (rMid - 4), cy + sin(aMid) * (rMid - 4)],
      [cx + cos(aBase + curlSign * da * 0.24) * (rIn + 4), cy + sin(aBase + curlSign * da * 0.24) * (rIn + 4)]
    ];
    midTongues.push(flameMid);

    // Orpiment yellow core
    let flameCore = [
      [cx + cos(aBase - curlSign * da * 0.15) * (rIn + 6), cy + sin(aBase - curlSign * da * 0.15) * (rIn + 6)],
      [cx + cos(aBase) * (rMid + 3), cy + sin(aBase) * (rMid + 3)],
      [cx + cos(aBase + curlSign * da * 0.15) * (rIn + 6), cy + sin(aBase + curlSign * da * 0.15) * (rIn + 6)]
    ];
    innerCores.push(flameCore);

    // Swirling gold core line
    goldSpirals.push([
      [cx + cos(aBase) * (rIn + 5), cy + sin(aBase) * (rIn + 5)],
      [cx + cos(aBase - curlSign * da * 0.1) * rMid, cy + sin(aBase - curlSign * da * 0.1) * rMid],
      [cx + cos(aTip) * (rTip - 5), cy + sin(aTip) * (rTip - 5)]
    ]);
  }

  // Paint dense mineral watercolor layers
  brush.noStroke();
  brush.fill(PAL.cinnMid, 225);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.45, 0.35);
  for (let p of outerTongues) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.wash(PAL.cinnBright, 220);
  for (let p of sideFlicks) drawPoly(p, 0.15, true);
  for (let p of midTongues) drawPoly(p, 0.2, true);

  brush.wash(PAL.orpiBright, 240);
  for (let p of innerCores) drawPoly(p, 0.2, true);
  brush.noWash();

  // Fine gold ink outlines
  brush.set("gold_hairline", PAL.goldBright, 1.0);
  for (let p of goldOutlines) drawPoly(p, 0.2, true);
  brush.set("gold_hairline", PAL.goldGleam, 0.9);
  for (let s of goldSpirals) drawOpenPath(s, 0.25);

  // Outer double gold boundary ring
  brush.set("gold_bold", PAL.goldMid, 1.1);
  brush.noFill();
  brush.circle(cx, cy, rOut + 2, 0.01);
  brush.set("gold_hairline", PAL.goldGleam, 1.0);
  brush.circle(cx, cy, rOut - 1, 0.01);
}

function drawMalachitePearlBand(cx, cy, rIn, rOut) {
  // Deep Malachite band
  brush.noStroke();
  brush.fill(PAL.malaDark, 235);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.45, 0.3);
  for (let s = 0; s < 12; s++) {
    drawPoly(makeRingSectorPts(cx, cy, rIn, rOut, s * 30, (s + 1) * 30, 8), 0, true);
  }
  brush.noFill();

  // Inner malachite highlight strip
  brush.wash(PAL.malaMid, 180);
  for (let s = 0; s < 12; s++) {
    drawPoly(makeRingSectorPts(cx, cy, rIn + 5, rOut - 5, s * 30, (s + 1) * 30, 8), 0, true);
  }
  brush.noWash();

  // 64 Golden Pearls & Alternating Cinnabar/Lapis Lozenges
  const nBeads = 64;
  const rMid = (rIn + rOut) * 0.5;
  let pearls = [];
  let cinnGems = [];
  let lapisGems = [];
  let goldSettings = [];

  for (let i = 0; i < nBeads; i++) {
    let a = (i / nBeads) * 360;
    let bx = cx + cos(a) * rMid;
    let by = cy + sin(a) * rMid;

    if (i % 2 === 0) {
      let p = makeCirclePts(bx, by, 5.5, 10);
      pearls.push(p);
      goldSettings.push(p);
    } else {
      let c = cos(a), s = sin(a);
      let rx = 7.5, ry = 4.5;
      let gem = [
        [bx - c * rx, by - s * rx],
        [bx - s * ry, by + c * ry],
        [bx + c * rx, by + s * rx],
        [bx + s * ry, by - c * ry]
      ];
      if ((i % 4) === 1) cinnGems.push(gem);
      else lapisGems.push(gem);
      goldSettings.push(gem);
    }
  }

  brush.noStroke();
  brush.wash(PAL.orpiLight, 245);
  for (let p of pearls) drawPoly(p, 0.1, true);
  brush.wash(PAL.cinnBright, 235);
  for (let g of cinnGems) drawPoly(g, 0, true);
  brush.wash(PAL.lapisBright, 235);
  for (let g of lapisGems) drawPoly(g, 0, true);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldGleam, 1.0);
  for (let g of goldSettings) drawPoly(g, 0.05, true);

  // Gold bezel borders of the pearl band
  brush.set("gold_bold", PAL.goldBright, 1.1);
  brush.noFill();
  brush.circle(cx, cy, rOut, 0.01);
  brush.circle(cx, cy, rIn, 0.01);
}

function drawLotusPetalBand(cx, cy, rIn, rOut) {
  // Deep Lapis under-ring between petal tips
  brush.noStroke();
  brush.wash(PAL.lapisAbyss, 245);
  for (let s = 0; s < 12; s++) {
    drawPoly(makeRingSectorPts(cx, cy, rIn, rOut, s * 30, (s + 1) * 30, 8), 0, true);
  }
  brush.noWash();

  const nPetals = 24;
  const da = 360 / nPetals; // 15 deg per petal

  // Layer A: 24 Interstitial Outer Malachite Lotus Petals
  let malaOuter = [];
  let malaInner = [];
  let malaTips = [];
  let malaGold = [];

  for (let i = 0; i < nPetals; i++) {
    let a = (i + 0.5) * da - 90;
    let aL = a - da * 0.44;
    let aR = a + da * 0.44;
    let rMid = lerp(rIn, rOut, 0.65);
    let rTip = rOut - 2;

    let poly = [
      [cx + cos(aL) * (rIn + 18), cy + sin(aL) * (rIn + 18)],
      [cx + cos(a - da * 0.36) * rMid, cy + sin(a - da * 0.36) * rMid],
      [cx + cos(a - da * 0.14) * (rTip - 5), cy + sin(a - da * 0.14) * (rTip - 5)],
      [cx + cos(a) * rTip, cy + sin(a) * rTip],
      [cx + cos(a + da * 0.14) * (rTip - 5), cy + sin(a + da * 0.14) * (rTip - 5)],
      [cx + cos(a + da * 0.36) * rMid, cy + sin(a + da * 0.36) * rMid],
      [cx + cos(aR) * (rIn + 18), cy + sin(aR) * (rIn + 18)]
    ];
    malaOuter.push(poly);
    malaGold.push(poly);

    let inner = scalePoly(poly, cx + cos(a) * rMid, cy + sin(a) * rMid, 0.72);
    malaInner.push(inner);

    let tip = [
      [cx + cos(a - da * 0.18) * (rTip - 12), cy + sin(a - da * 0.18) * (rTip - 12)],
      [cx + cos(a) * (rTip - 2), cy + sin(a) * (rTip - 2)],
      [cx + cos(a + da * 0.18) * (rTip - 12), cy + sin(a + da * 0.18) * (rTip - 12)]
    ];
    malaTips.push(tip);
  }

  brush.noStroke();
  brush.fill(PAL.malaDark, 230);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.45, 0.35);
  for (let p of malaOuter) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.wash(PAL.malaBright, 210);
  for (let p of malaInner) drawPoly(p, 0.2, true);
  brush.wash(PAL.malaLight, 220);
  for (let p of malaTips) drawPoly(p, 0.15, true);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldMid, 1.0);
  for (let p of malaGold) drawPoly(p, 0.2, true);

  // Layer B: 24 Primary Broad Cinnabar & Orpiment Lotus Petals
  let cinnOuter = [];
  let cinnBody = [];
  let orpiRim = [];
  let cinnBase = [];
  let petalOutlines = [];
  let petalVeins = [];

  for (let i = 0; i < nPetals; i++) {
    let a = i * da - 90;
    let aL = a - da * 0.47;
    let aR = a + da * 0.47;
    let rBelly = lerp(rIn, rOut, 0.56);
    let rShoulder = lerp(rIn, rOut, 0.82);
    let rTip = rOut - 4;

    // Outer ogival lotus petal contour (gives the upturned golden rim)
    let outerP = [
      [cx + cos(a - da * 0.32) * rIn, cy + sin(a - da * 0.32) * rIn],
      [cx + cos(aL) * rBelly, cy + sin(aL) * rBelly],
      [cx + cos(a - da * 0.35) * rShoulder, cy + sin(a - da * 0.35) * rShoulder],
      [cx + cos(a - da * 0.14) * (rTip - 4), cy + sin(a - da * 0.14) * (rTip - 4)],
      [cx + cos(a) * rTip, cy + sin(a) * rTip],
      [cx + cos(a + da * 0.14) * (rTip - 4), cy + sin(a + da * 0.14) * (rTip - 4)],
      [cx + cos(a + da * 0.35) * rShoulder, cy + sin(a + da * 0.35) * rShoulder],
      [cx + cos(aR) * rBelly, cy + sin(aR) * rBelly],
      [cx + cos(a + da * 0.32) * rIn, cy + sin(a + da * 0.32) * rIn]
    ];
    orpiRim.push(outerP);
    petalOutlines.push(outerP);

    // Main cinnabar body inset from the curled orpiment collar
    let bodyP = [
      [cx + cos(a - da * 0.28) * (rIn + 2), cy + sin(a - da * 0.28) * (rIn + 2)],
      [cx + cos(a - da * 0.40) * (rBelly - 2), cy + sin(a - da * 0.40) * (rBelly - 2)],
      [cx + cos(a - da * 0.26) * (rShoulder - 5), cy + sin(a - da * 0.26) * (rShoulder - 5)],
      [cx + cos(a) * (rTip - 11), cy + sin(a) * (rTip - 11)],
      [cx + cos(a + da * 0.26) * (rShoulder - 5), cy + sin(a + da * 0.26) * (rShoulder - 5)],
      [cx + cos(a + da * 0.40) * (rBelly - 2), cy + sin(a + da * 0.40) * (rBelly - 2)],
      [cx + cos(a + da * 0.28) * (rIn + 2), cy + sin(a + da * 0.28) * (rIn + 2)]
    ];
    cinnOuter.push(bodyP);
    petalOutlines.push(bodyP);

    // Bright vermilion-cinnabar upper belly
    let brightP = [
      [cx + cos(a - da * 0.24) * (rIn + 14), cy + sin(a - da * 0.24) * (rIn + 14)],
      [cx + cos(a - da * 0.30) * rBelly, cy + sin(a - da * 0.30) * rBelly],
      [cx + cos(a) * (rTip - 16), cy + sin(a) * (rTip - 16)],
      [cx + cos(a + da * 0.30) * rBelly, cy + sin(a + da * 0.30) * rBelly],
      [cx + cos(a + da * 0.24) * (rIn + 14), cy + sin(a + da * 0.24) * (rIn + 14)]
    ];
    cinnBody.push(brightP);

    // Deep crimson petal base cushion
    let baseP = [
      [cx + cos(a - da * 0.24) * (rIn + 2), cy + sin(a - da * 0.24) * (rIn + 2)],
      [cx + cos(a - da * 0.22) * (rIn + 24), cy + sin(a - da * 0.22) * (rIn + 24)],
      [cx + cos(a) * (rIn + 30), cy + sin(a) * (rIn + 30)],
      [cx + cos(a + da * 0.22) * (rIn + 24), cy + sin(a + da * 0.22) * (rIn + 24)],
      [cx + cos(a + da * 0.24) * (rIn + 2), cy + sin(a + da * 0.24) * (rIn + 2)]
    ];
    cinnBase.push(baseP);

    // 3 Hairline gold veins per petal
    for (let v = -1; v <= 1; v++) {
      let av = a + v * da * 0.13;
      petalVeins.push([
        [cx + cos(a + v * da * 0.06) * (rIn + 5), cy + sin(a + v * da * 0.06) * (rIn + 5)],
        [cx + cos(av) * rBelly, cy + sin(av) * rBelly],
        [cx + cos(a + v * da * 0.08) * (rTip - 14), cy + sin(a + v * da * 0.08) * (rTip - 14)]
      ]);
    }
  }

  brush.noStroke();
  brush.wash(PAL.orpiBright, 240);
  for (let p of orpiRim) drawPoly(p, 0.2, true);
  brush.noWash();

  brush.fill(PAL.cinnMid, 230);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.45, 0.35);
  for (let p of cinnOuter) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.wash(PAL.cinnBright, 200);
  for (let p of cinnBody) drawPoly(p, 0.2, true);

  brush.wash(PAL.cinnDark, 225);
  for (let p of cinnBase) drawPoly(p, 0.2, true);
  brush.noWash();

  // Hairline gold veining and double outlines
  brush.set("gold_hairline", PAL.goldMid, 0.85);
  for (let v of petalVeins) drawOpenPath(v, 0.15);

  brush.set("gold_hairline", PAL.goldGleam, 1.05);
  for (let p of petalOutlines) drawPoly(p, 0.2, true);
}

function drawInnerCloudCollar(cx, cy, rIn, rOut) {
  // Base Lapis ring
  brush.noStroke();
  brush.wash(PAL.lapisDeep, 245);
  for (let s = 0; s < 12; s++) {
    drawPoly(makeRingSectorPts(cx, cy, rIn, rOut, s * 30, (s + 1) * 30, 8), 0, true);
  }
  brush.noWash();

  const nClouds = 24;
  const da = 360 / nClouds;
  const rMid = (rIn + rOut) * 0.5;

  let lapisClouds = [];
  let malaClouds = [];
  let lightCenters = [];
  let orpiHearts = [];
  let goldLines = [];

  for (let i = 0; i < nClouds; i++) {
    let a = i * da - 90;
    let ccx = cx + cos(a) * rMid;
    let ccy = cy + sin(a) * rMid;

    // Scalloped cloud collar lobe
    let pts = [];
    for (let k = 0; k < 14; k++) {
      let ka = (k / 14) * 360;
      let rad = 16 + 3 * cos(ka * 3);
      let lx = cos(ka) * (rad * 0.72);
      let ly = sin(ka) * (rad * 1.05);
      let c = cos(a), s = sin(a);
      pts.push([ccx + lx * c - ly * s, ccy + lx * s + ly * c]);
    }
    if (i % 2 === 0) lapisClouds.push(pts);
    else malaClouds.push(pts);
    goldLines.push(pts);

    let inner = scalePoly(pts, ccx, ccy, 0.65);
    lightCenters.push({ isEven: i % 2 === 0, poly: inner });

    let heart = makeCirclePts(ccx, ccy, 4.5, 10);
    orpiHearts.push(heart);
    goldLines.push(heart);
  }

  brush.noStroke();
  brush.fill(PAL.lapisMid, 225);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.4, 0.3);
  for (let p of lapisClouds) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.fill(PAL.malaMid, 225);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.4, 0.3);
  for (let p of malaClouds) drawPoly(p, 0.2, true);
  brush.noFill();

  brush.wash(PAL.lapisLight, 185);
  for (let item of lightCenters) {
    if (item.isEven) drawPoly(item.poly, 0.2, true);
  }
  brush.wash(PAL.malaLight, 185);
  for (let item of lightCenters) {
    if (!item.isEven) drawPoly(item.poly, 0.2, true);
  }
  brush.wash(PAL.orpiBright, 240);
  for (let p of orpiHearts) drawPoly(p, 0.1, true);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldBright, 1.0);
  for (let p of goldLines) drawPoly(p, 0.2, true);

  brush.set("gold_bold", PAL.goldBright, 1.1);
  brush.noFill();
  brush.circle(cx, cy, rOut, 0.01);
}

function drawCentralSanctuaryHalo(cx, cy, rHalo) {
  // High-contrast abyssal obsidian-lapis ground so the ruby pomegranate glows
  let haloCircle = makeCirclePts(cx, cy, rHalo, 72);
  let innerGlow = makeCirclePts(cx, cy - 20, rHalo * 0.78, 60);

  brush.noStroke();
  brush.wash(PAL.lapisVoid, 250);
  drawPoly(haloCircle, 0.1, true);
  brush.noWash();

  brush.fill(PAL.lapisAbyss, 190);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.55, 0.35);
  drawPoly(innerGlow, 0.1, true);
  brush.noFill();

  // 144 Hairline Gold Prabha Rays radiating from the enthroned center (600, 560)
  const rcx = 600, rcy = 560;
  const nRays = 144;
  for (let i = 0; i < nRays; i++) {
    let a = (i / nRays) * 360;
    // Ray intersection with circle (cx, cy, rHalo - 4)
    let dx = cos(a), dy = sin(a);
    let ox = rcx - cx, oy = rcy - cy;
    let B = 2 * (ox * dx + oy * dy);
    let C = ox * ox + oy * oy - (rHalo - 5) * (rHalo - 5);
    let disc = max(0, B * B - 4 * C);
    let tMax = (-B + sqrt(disc)) * 0.5;
    let tMin = (i % 2 === 0) ? 135 : 158;
    if (tMax > tMin) {
      brush.set("gold_hairline", i % 2 === 0 ? PAL.goldDark : PAL.goldShadow, i % 2 === 0 ? 0.85 : 0.65);
      brush.line(rcx + dx * tMin, rcy + dy * tMin, rcx + dx * tMax, rcy + dy * tMax);
    }
  }

  // Heavy burnished double gold bezel around the central sanctuary
  brush.noFill();
  brush.set("gold_bold", PAL.goldDark, 1.4);
  brush.circle(cx, cy, rHalo + 2, 0.01);
  brush.set("gold_bold", PAL.goldGleam, 1.2);
  brush.circle(cx, cy, rHalo - 1, 0.01);
  brush.set("gold_hairline", PAL.goldBright, 0.9);
  brush.circle(cx, cy, rHalo - 5, 0.01);
}

function drawLotusThronePedestal(cx, cy) {
  // A delicate golden lotus moon-disc & jewel bowl at the bottom of the central halo
  // catching the sacred drip of pomegranate juice
  let petals = [];
  let innerPetals = [];
  const wSpan = 86;
  const nP = 7;

  for (let i = 0; i < nP; i++) {
    let u = map(i, 0, nP - 1, -1, 1);
    let px = cx + u * wSpan;
    let py = cy + abs(u) * 8;
    let pw = 16 - abs(u) * 3;
    let ph = 20 - abs(u) * 4;
    let p = [
      [px - pw * 0.7, py + 4],
      [px - pw, py - ph * 0.5],
      [px, py - ph],
      [px + pw, py - ph * 0.5],
      [px + pw * 0.7, py + 4]
    ];
    petals.push(p);
    innerPetals.push(scalePoly(p, px, py - ph * 0.4, 0.65));
  }

  // Moon disc cushion
  let cushion = [
    [cx - 78, cy - 6],
    [cx - 50, cy - 13],
    [cx + 50, cy - 13],
    [cx + 78, cy - 6],
    [cx + 62, cy + 5],
    [cx - 62, cy + 5]
  ];

  brush.noStroke();
  brush.wash(PAL.cinnMid, 230);
  for (let p of petals) drawPoly(p, 0.2, true);
  brush.wash(PAL.orpiBright, 235);
  for (let p of innerPetals) drawPoly(p, 0.2, true);
  brush.wash(PAL.pithCream, 220);
  drawPoly(cushion, 0.2, true);

  // Subtle ruby reflection pool in the center of the moon disc directly under the falling drop
  let pool = [
    [cx - 16, cy - 9],
    [cx, cy - 11],
    [cx + 16, cy - 9],
    [cx, cy - 6]
  ];
  brush.wash(PAL.rubyBright, 195);
  drawPoly(pool, 0.2, true);
  brush.noWash();

  brush.set("gold_hairline", PAL.goldGleam, 1.0);
  for (let p of petals) drawPoly(p, 0.2, true);
  drawPoly(cushion, 0.2, true);
}

// ============================================================================
// 3. THE HYPERREAL SPLIT POMEGRANATE (CENTERPIECE)
