function drawHyperrealPomegranate(cx, cy) {
  // --- A. Deep Chiaroscuro Aura / Drop Shadow behind Fruit ---
  let shadowPoly = makeCirclePts(cx, cy + 8, 178, 48);
  brush.noStroke();
  brush.wash(PAL.lapisVoid, 220);
  drawPoly(shadowPoly, 0.2, true);
  brush.noWash();

  // --- B. The Royal Calyx (Crown) at the Top (y ~ 356..418) ---
  drawPomegranateCrown(cx, cy - 154);

  // --- C. Outer Leathery Pericarp (Rind) — Left & Right Split Hemispheres ---
  // Notice the natural hexagonal/lobular bulges of a real pomegranate
  const rindOuter = [
    [cx, cy - 150],         // Top split notch below crown
    [cx - 32, cy - 154],
    [cx - 88, cy - 142],    // Upper-left shoulder lobe
    [cx - 138, cy - 104],
