  brush.fillTexture(0.5, 0.3);
  drawPoly(rindMidPoly, 0.22, true);
  brush.noFill();

  // Upper-left warm vermilion-russet illumination on the leathery skin
  let leftLitRind = [
    [cx - 28, cy - 150],
