  drawPoly(rightLitRind, 0.25, true);
  brush.noFill();

  brush.wash(PAL.rindRusset, 150);
  drawPoly(scalePoly(leftLitRind, cx - 120, cy - 45, 0.65), 0.25, true);
  brush.noWash();

  // --- D. Torn Spongy White/Ivory Pith Wall (Mesocarp) ---
  // Irregular cellular torn contour just inside the leathery skin
  const pithOuter = [
    [cx, cy - 140],
    [cx - 26, cy - 144],
    [cx - 78, cy - 131],
    [cx - 124, cy - 95],
    [cx - 151, cy - 38],
    [cx - 153, cy + 25],
    [cx - 128, cy + 86],
    [cx - 82, cy + 130],
    [cx - 28, cy + 152],
    [cx - 4, cy + 158],
    [cx, cy + 144],
    [cx + 4, cy + 158],
    [cx + 28, cy + 152],
