  const centerChasm = [
    [cx, cy - 136],
    [cx - 10, cy - 105],
    [cx - 15, cy - 45],
    [cx - 9, cy + 15],
    [cx - 12, cy + 88],
    [cx, cy + 146],
    [cx + 12, cy + 88],
    [cx + 9, cy + 15],
    [cx + 15, cy - 45],
    [cx + 10, cy - 105]
  ];

  // Fill deep garnet-black void inside the seed chambers
  brush.noStroke();
  brush.wash(PAL.rubyVoid, 250);
  drawPoly(leftCavern, 0.15, true);
  drawPoly(rightCavern, 0.15, true);
  drawPoly(centerChasm, 0.15, true);
  brush.noWash();

  // --- F. Generate & Render Voronoi-Faceted Glistening Ruby Arils ---
  drawAllRubyArils(cx, cy, leftCavern, rightCavern);

  // --- G. Torn Pith Septa, Central Spongy Core & Translucent Membrane Veils ---
  drawTornPithMembranes(cx, cy, pithOuter, rindOuter);
}

