function drawAllRubyArils(cx, cy, leftCavern, rightCavern) {
  // Generate tightly packed seed centers across the left & right chambers
  let seeds = [];

  // Helper to populate a chamber with relaxed hexagonal grid points
  function populateChamber(poly, xMin, xMax, yMin, yMax, spacing, isDeep = false) {
    let row = 0;
    for (let y = yMin; y <= yMax; y += spacing * 0.86) {
      let xOff = (row % 2 === 0) ? 0 : spacing * 0.5;
      for (let x = xMin + xOff; x <= xMax; x += spacing) {
        let jx = x + random(-spacing * 0.22, spacing * 0.22);
        let jy = y + random(-spacing * 0.22, spacing * 0.22);
        if (pointInPoly(jx, jy, poly)) {
          seeds.push({
            x: jx,
            y: jy,
            r: spacing * random(0.56, 0.64),
            isDeep: isDeep,
            chamberPoly: poly
          });
        }
      }
      row++;
    }
  }

  // Background deep arils in the central torn fissure
  const deepCleftPoly = [
    [cx - 18, cy - 115], [cx + 18, cy - 115],
    [cx + 22, cy + 125], [cx - 22, cy + 125]
  ];
  populateChamber(deepCleftPoly, cx - 16, cx + 16, cy - 110, cy + 118, 17, true);

  // Foreground glistening arils in the Left and Right chambers
  populateChamber(leftCavern, cx - 142, cx - 6, cy - 130, cy + 136, 18.5, false);
  populateChamber(rightCavern, cx + 6, cx + 142, cy - 130, cy + 136, 18.5, false);

  // 1-step Lloyds relaxation within each layer so arils pack with organic perfection
  for (let iter = 0; iter < 2; iter++) {
    for (let i = 0; i < seeds.length; i++) {
      let a = seeds[i];
      let fx = 0, fy = 0;
      for (let j = 0; j < seeds.length; j++) {
        if (i === j || seeds[i].isDeep !== seeds[j].isDeep) continue;
        let b = seeds[j];
        let dx = a.x - b.x, dy = a.y - b.y;
        let d = sqrt(dx * dx + dy * dy) + 0.001;
        let minD = (a.r + b.r) * 0.82;
        if (d < minD) {
          let push = (minD - d) * 0.35;
          fx += (dx / d) * push;
          fy += (dy / d) * push;
        }
      }
      let nx = a.x + fx, ny = a.y + fy;
      if (pointInPoly(nx, ny, a.chamberPoly)) {
        a.x = nx;
        a.y = ny;
      }
    }
  }

  // Construct Voronoi-clipped faceted polygon for every aril
  let arilData = [];
  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];
    // Start with a 9-sided slightly organic polygon
    let poly = [];
    let rot0 = random(360);
    for (let k = 0; k < 9; k++) {
      let a = rot0 + (k / 9) * 360;
      let rad = s.r * random(0.95, 1.06);
      poly.push([s.x + cos(a) * rad, s.y + sin(a) * rad]);
    }

    // Clip against nearby neighbor arils in the same depth layer (creates authentic flat compressed facets!)
    for (let j = 0; j < seeds.length; j++) {
      if (i === j || s.isDeep !== seeds[j].isDeep) continue;
      let nb = seeds[j];
      let dx = nb.x - s.x, dy = nb.y - s.y;
      let d = sqrt(dx * dx + dy * dy);
      if (d < (s.r + nb.r) * 1.15 && d > 0.1) {
        let nx = dx / d, ny = dy / d;
        // Midpoint shifted slightly inward by 0.65px to leave a dark interstitial crevice
        let ratio = s.r / (s.r + nb.r);
        let mx = s.x + dx * ratio - nx * 0.65;
        let my = s.y + dy * ratio - ny * 0.65;
        poly = clipPolyHalfPlane(poly, mx, my, nx, ny);
      }
    }

    if (poly.length >= 3) {
      // Chaikin corner-cutting for glossy rounded-facet tension
      let smoothP = smoothPolyChaikin(poly, 1);
      arilData.push({
        x: s.x,
        y: s.y,
        r: s.r,
        isDeep: s.isDeep,
        poly: smoothP,
        rawPoly: poly,
        tone: random()
      });
    }
  }

  // Sort back-to-front (deep cleft arils first, then foreground arils)
  arilData.sort((a, b) => (b.isDeep ? 1 : 0) - (a.isDeep ? 1 : 0));

  // Batch lists for fast, ultra-rich multi-layered glazing
  let deepBaseBatch = [];
  let deepMidBatch = [];
  let fgAbyssBatch = [];
  let fgDarkBatch = [];
  let fgMidBatch = [];
  let fgBrightBatch = [];
  let fgGlowBatch = [];
  let fgFireBatch = [];
  let seedCoreBatch = [];
  let specPinkBatch = [];
  let specWhitePolys = [];
  let specGlintLines = [];

  for (let aril of arilData) {
    let { x, y, r, isDeep, poly, rawPoly, tone } = aril;
    if (isDeep) {
      deepBaseBatch.push(poly);
      deepMidBatch.push(scalePoly(poly, x, y, 0.72, 0.72, 1, 1));
      continue;
    }

    // 1. Outer facet shadow rim
    fgAbyssBatch.push(poly);

    // 2. Main ruby body (90% scale)
    let bodyP = scalePoly(poly, x, y, 0.90, 0.90);
    if (tone < 0.35) fgDarkBatch.push(bodyP);
    else fgMidBatch.push(bodyP);

    // 3. Vibrant crimson middle facet (74% scale)
    let midP = scalePoly(poly, x, y, 0.74, 0.74, 0.6, 0.6);
    if (tone < 0.25) fgMidBatch.push(midP);
    else fgBrightBatch.push(midP);

    // 4. Translucent subsurface scattering glow in lower-right belly of the aril
    let glowP = scalePoly(poly, x, y, 0.52, 0.52, r * 0.14, r * 0.16);
    fgGlowBatch.push(glowP);

    if (tone > 0.3) {
      let fireP = scalePoly(poly, x, y, 0.32, 0.32, r * 0.18, r * 0.20);
      fgFireBatch.push(fireP);
    }

    // 5. Dimly visible pale inner seed (endosperm) in the center of the translucent pulp
    let ang = atan2(y - cy, x - cx) + random(-25, 25);
    let c = cos(ang), s = sin(ang);
    let sr1 = r * 0.24, sr2 = r * 0.11;
    let seedPoly = [
      [x - c * sr1, y - s * sr1],
      [x - s * sr2, y + c * sr2],
      [x + c * sr1, y + s * sr1],
      [x + s * sr2, y - c * sr2]
    ];
    seedCoreBatch.push(seedPoly);

    // 6. Crisp wet specular highlights on the upper-left facet ridge!
    // Find vertex closest to upper-left (-125 deg)
    let bestIdx = 0;
    let bestScore = -1e9;
    for (let k = 0; k < rawPoly.length; k++) {
      let vx = rawPoly[k][0] - x;
      let vy = rawPoly[k][1] - y;
      let sc = -vx * 0.75 - vy * 0.66;
      if (sc > bestScore) {
        bestScore = sc;
        bestIdx = k;
      }
    }
    let v0 = rawPoly[bestIdx];
    let v1 = rawPoly[(bestIdx + 1) % rawPoly.length];
    let vPrev = rawPoly[(bestIdx + rawPoly.length - 1) % rawPoly.length];

    // Inset slightly from the top-left facet edge for the wet glass window reflection
    let hx0 = lerp(x, vPrev[0], 0.66);
    let hy0 = lerp(y, vPrev[1], 0.66);
    let hx1 = lerp(x, v0[0], 0.72);
    let hy1 = lerp(y, v0[1], 0.72);
    let hx2 = lerp(x, v1[0], 0.66);
    let hy2 = lerp(y, v1[1], 0.66);

    let specRibbon = [
      [hx0, hy0],
      [hx1, hy1],
      [hx2, hy2],
      [lerp(x, v0[0], 0.46), lerp(y, v0[1], 0.46)]
    ];
    specPinkBatch.push(scalePoly(specRibbon, hx1, hy1, 1.25));
    specWhitePolys.push(specRibbon);

    // Secondary pinpoint glint or facet edge line
    specGlintLines.push([[hx0, hy0], [hx1, hy1], [hx2, hy2]]);
  }

  // Execute batched fills in strict back-to-front order
  brush.noStroke();

  // Deep background arils
  brush.wash(PAL.rubyAbyss, 245);
  for (let p of deepBaseBatch) drawPoly(p, 0.1, true);
  brush.wash(PAL.rubyDark, 210);
  for (let p of deepMidBatch) drawPoly(p, 0.1, true);

  // Foreground aril shadow rims
  brush.wash(PAL.rubyAbyss, 250);
  for (let p of fgAbyssBatch) drawPoly(p, 0.1, true);

  // Dark garnet bodies
  brush.wash(PAL.rubyDark, 235);
  for (let p of fgDarkBatch) drawPoly(p, 0.1, true);

  // Rich crimson-ruby bodies (watercolor fill batch for lush glaze texture)
  brush.fill(PAL.rubyMid, 225);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.4, 0.3);
  for (let p of fgMidBatch) drawPoly(p, 0.1, true);
  brush.noFill();

  // Bright ruby facets
  brush.wash(PAL.rubyBright, 220);
  for (let p of fgBrightBatch) drawPoly(p, 0.1, true);

  // Subsurface scattering glow
  brush.wash(PAL.rubyGlow, 215);
  for (let p of fgGlowBatch) drawPoly(p, 0.15, true);

  // Fiery translucent caustic bellies
  brush.wash(PAL.rubyFire, 195);
  for (let p of fgFireBatch) drawPoly(p, 0.15, true);

  // Pale internal seed cores (softened inside the red pulp)
  brush.wash(PAL.seedCore, 115);
  for (let p of seedCoreBatch) drawPoly(p, 0.2, true);

  // Soft icy-rose halo around specular reflections
  brush.wash(PAL.specPink, 175);
  for (let p of specPinkBatch) drawPoly(p, 0.1, true);

  // Razor-sharp pure white wet window highlights
  brush.wash(PAL.specWhite, 250);
  for (let p of specWhitePolys) drawPoly(p, 0.05, true);
  brush.noWash();

  // Crisp specular ridge strokes & pinpoint wet glints
  brush.set("specular_nib", PAL.specWhite, 0.95);
  for (let i = 0; i < specGlintLines.length; i++) {
    let g = specGlintLines[i];
    drawOpenPath(g, 0.15);
    // Tiny secondary glint dot on an adjacent facet
    if (i % 2 === 0) {
      let gx = g[1][0] + 2.5, gy = g[1][1] + 4.2;
      brush.line(gx, gy, gx + 0.8, gy + 0.8);
    }
  }
}

function drawTornPithMembranes(cx, cy, pithOuter, rindOuter) {
  // 1. Translucent papery membrane veils stretching partially over the ruby arils
  const membraneVeils = [
    // Upper-left chamber divider membrane
    [
      [cx - 12, cy - 55], [cx - 48, cy - 64], [cx - 88, cy - 78],
      [cx - 122, cy - 86], [cx - 115, cy - 62], [cx - 75, cy - 48], [cx - 16, cy - 36]
    ],
    // Lower-left chamber divider membrane
    [
      [cx - 14, cy + 18], [cx - 58, cy + 28], [cx - 102, cy + 48],
      [cx - 134, cy + 32], [cx - 96, cy + 14], [cx - 52, cy + 4], [cx - 18, cy - 2]
    ],
    // Upper-right chamber divider membrane
    [
      [cx + 12, cy - 52], [cx + 52, cy - 62], [cx + 92, cy - 76],
      [cx + 120, cy - 84], [cx + 112, cy - 58], [cx + 72, cy - 45], [cx + 16, cy - 34]
    ],
    // Lower-right chamber divider membrane
    [
      [cx + 14, cy + 16], [cx + 56, cy + 26], [cx + 98, cy + 46],
      [cx + 132, cy + 30], [cx + 94, cy + 12], [cx + 50, cy + 2], [cx + 18, cy - 4]
    ],
    // Central torn spongy bridge across the middle of the columella
    [
      [cx - 26, cy - 22], [cx - 4, cy - 30], [cx + 24, cy - 18],
      [cx + 28, cy + 16], [cx + 5, cy + 28], [cx - 24, cy + 18]
    ]
  ];

  // Semi-transparent warm cream wash so the ruby arils glow faintly underneath the thin membrane!
  brush.noStroke();
  brush.wash(PAL.pithWarm, 155);
  for (let v of membraneVeils) drawPoly(v, 0.22, true);
  brush.noWash();

  // Thicker opaque torn septal ridges along the center of each membrane
  let ridgePolys = [];
  for (let v of membraneVeils) {
    let cxv = 0, cyv = 0;
    for (let p of v) { cxv += p[0]; cyv += p[1]; }
    cxv /= v.length; cyv /= v.length;
    ridgePolys.push(scalePoly(v, cxv, cyv, 0.62, 0.55));
  }

  // Also add the torn left and right walls of the central vertical columella
  const leftColumella = [
    [cx - 3, cy - 138], [cx - 18, cy - 122], [cx - 16, cy - 65],
    [cx - 24, cy - 12], [cx - 18, cy + 38], [cx - 14, cy + 98],
    [cx - 5, cy + 145], [cx - 2, cy + 95], [cx - 8, cy + 32],
    [cx - 8, cy - 18], [cx - 6, cy - 72]
  ];
  const rightColumella = [
    [cx + 3, cy - 138], [cx + 18, cy - 122], [cx + 16, cy - 65],
    [cx + 24, cy - 12], [cx + 18, cy + 38], [cx + 14, cy + 98],
    [cx + 5, cy + 145], [cx + 2, cy + 95], [cx + 8, cy + 32],
    [cx + 8, cy - 18], [cx + 6, cy - 72]
  ];
  ridgePolys.push(leftColumella, rightColumella);

  brush.fill(PAL.pithCream, 235);
  brush.fillBleed(0.03, "out");
  brush.fillTexture(0.45, 0.3);
  for (let p of ridgePolys) drawPoly(p, 0.2, true);
  brush.noFill();

  // Brightest ivory highlights on the torn central sponge
  brush.wash(PAL.pithWhite, 210);
  for (let p of ridgePolys) {
    let cxp = p[0][0], cyp = p[0][1];
    drawPoly(scalePoly(p, cxp, cyp, 0.55), 0.2, true);
  }
  brush.noWash();

  // Crimson juice stains bleeding into the torn white pith around the edges
  let stainSpots = [
    [cx - 18, cy - 42, 9], [cx + 17, cy - 38, 8],
    [cx - 15, cy + 24, 10], [cx + 16, cy + 28, 9],
    [cx - 136, cy - 12, 11], [cx + 135, cy + 8, 10],
    [cx - 82, cy + 118, 11], [cx + 78, cy + 116, 11],
    [cx - 6, cy + 142, 12], [cx + 6, cy + 142, 12]
  ];
  brush.fill(PAL.rubyBright, 115);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.2);
  for (let [sx, sy, sr] of stainSpots) {
    drawPoly(makeCirclePts(sx, sy, sr, 10), 0.2, true);
  }
  brush.noFill();

  // Fine fibrous cellular texture & torn edge stippling on the pith
  for (let p of membraneVeils) {
    brush.set("2H", PAL.pithOchre, 0.85);
    drawOpenPath(p, 0.25);
    brush.set("specular_nib", PAL.pithWhite, 0.75);
    for (let k = 0; k < p.length; k++) {
      let pt = p[k];
      brush.line(pt[0], pt[1], pt[0] + random(-5, 5), pt[1] + random(-5, 5));
    }
  }

  // Fibrous cross-hatching and lenticel speckles along the outer rind & torn pith border
  brush.set("2H", PAL.pithShadow, 0.8);
  drawPoly(pithOuter, 0.18, true);

  for (let i = 0; i < 95; i++) {
    let idx = floor(random(pithOuter.length));
    let p1 = pithOuter[idx];
    let p2 = rindOuter[idx];
    let tx = lerp(p1[0], p2[0], random(0.15, 0.85)) + random(-4, 4);
    let ty = lerp(p1[1], p2[1], random(0.15, 0.85)) + random(-4, 4);
    brush.set("gold_hairline", i % 2 === 0 ? PAL.rindOchre : PAL.pithShadow, 0.75);
    brush.line(tx, ty, tx + random(-2, 2), ty + random(-2, 2));
  }

  // Golden rim-light along the outer rind contour from the surrounding mandala
  brush.set("gold_hairline", PAL.goldMid, 0.85);
  drawPoly(rindOuter, 0.22, true);
}

// ============================================================================
// 4. THE SINGLE DRIP OF RUBY JUICE
// ============================================================================

function drawSingleJuiceDrip(cx, cleftY) {
  // 1. Glistening ruby meniscus pooling at the bottom torn cleft of the pomegranate
  const meniscus = [
    [cx - 14, cleftY - 8],
    [cx - 7, cleftY + 4],
    [cx - 3, cleftY + 14],
    [cx, cleftY + 21],
    [cx + 3, cleftY + 14],
    [cx + 7, cleftY + 4],
    [cx + 14, cleftY - 8],
    [cx + 5, cleftY - 3],
    [cx, cleftY - 12],
    [cx - 5, cleftY - 3]
  ];

  // 2. The Single Suspended Falling Teardrop of Ruby Juice (y ~ cleftY + 28 to cleftY + 64)
  const dropTopY = cleftY + 26;
  const dropBotY = cleftY + 63;
  const dropMidY = cleftY + 49;
  const dropR = 10.5;

  const dropOuter = [
    [cx, dropTopY],                              // Razor-sharp upper surface-tension tail
    [cx - 2.5, dropTopY + 8],
    [cx - 6.8, dropTopY + 16],
    [cx - dropR, dropMidY - 2],
    [cx - dropR * 0.92, dropMidY + 6],
    [cx - dropR * 0.55, dropBotY - 2],
    [cx, dropBotY],                              // Rounded bottom belly
    [cx + dropR * 0.55, dropBotY - 2],
    [cx + dropR * 0.92, dropMidY + 6],
    [cx + dropR, dropMidY - 2],
    [cx + 6.8, dropTopY + 16],
    [cx + 2.5, dropTopY + 8]
  ];

  // Mid crimson core of the drop
  const dropMid = scalePoly(dropOuter, cx, dropMidY, 0.86, 0.88);

  // Translucent glowing ruby caustic belly on the lower-right side
  const dropGlow = [
    [cx - 3, dropMidY - 2],
    [cx - 6, dropMidY + 5],
    [cx - 2, dropBotY - 2],
    [cx + 4, dropBotY - 2],
    [cx + 8, dropMidY + 4],
    [cx + 6, dropMidY - 4]
  ];

  const dropFire = scalePoly(dropGlow, cx + 2, dropMidY + 4, 0.6);

  // Render the meniscus and falling teardrop
  brush.noStroke();
  brush.wash(PAL.rubyAbyss, 250);
  drawPoly(meniscus, 0.2, true);
  drawPoly(dropOuter, 0.22, true);

  brush.fill(PAL.rubyMid, 235);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.35, 0.25);
  drawPoly(dropMid, 0.22, true);
  brush.noFill();

  brush.wash(PAL.rubyGlow, 230);
  drawPoly(scalePoly(meniscus, cx, cleftY + 6, 0.65), 0.2, true);
  drawPoly(dropGlow, 0.25, true);

  brush.wash(PAL.rubyFire, 220);
  drawPoly(dropFire, 0.25, true);

  // Crisp pure white curved specular highlight on the upper-left belly of the teardrop
  const dropSpec = [
    [cx - 2.2, dropTopY + 12],
    [cx - 5.8, dropTopY + 19],
    [cx - 7.6, dropMidY + 2],
    [cx - 5.2, dropMidY + 3],
    [cx - 3.8, dropTopY + 19]
  ];
  brush.wash(PAL.specWhite, 255);
  drawPoly(dropSpec, 0.2, true);
  brush.noWash();

  // Hairline wet highlights on meniscus, drop tail, and bottom-right reflected rim
  brush.set("specular_nib", PAL.specWhite, 1.0);
  drawOpenPath([
    [cx - 1.5, dropTopY + 9],
    [cx - 5.5, dropTopY + 18],
    [cx - 7.2, dropMidY + 3]
  ], 0.25);
  // Pinpoint glint at bottom of meniscus
  brush.line(cx - 2, cleftY + 10, cx - 1, cleftY + 15);
  // Reflected pink-white rim on bottom right of teardrop
  brush.set("specular_nib", PAL.specPink, 0.85);
  drawOpenPath([
    [cx + 1, dropBotY - 1.2],
    [cx + 5.8, dropBotY - 3],
    [cx + 8.2, dropMidY + 3]
  ], 0.25);
}

