// ============================================================================
// GEOMETRY & COORDINATE HELPERS FOR THE 3D FERRY RAILING
// ============================================================================

const BOW_CX = 640;
const BOW_CY = 1190;
const BOW_R = 805;

const RAIL_P0 = { x: -90, y: 908 };
const RAIL_P1 = { x: 915, y: 418 };
const RAIL_R0 = 60;
const RAIL_R1 = 24;

// Unit tangent and normal along the main foreground rail
const RAIL_DX = RAIL_P1.x - RAIL_P0.x;
const RAIL_DY = RAIL_P1.y - RAIL_P0.y;
const RAIL_LEN = Math.hypot(RAIL_DX, RAIL_DY);
const RAIL_TX = RAIL_DX / RAIL_LEN;
const RAIL_TY = RAIL_DY / RAIL_LEN;
const RAIL_NX = -RAIL_TY; // Points down-right (+0.438, +0.899)
const RAIL_NY = RAIL_TX;

function railCenter(t) {
  return {
    x: RAIL_P0.x + RAIL_DX * t,
    y: RAIL_P0.y + RAIL_DY * t
  };
}

function railRadius(t) {
  let clamped = Math.max(0, Math.min(1.1, t));
  return RAIL_R0 + (RAIL_R1 - RAIL_R0) * Math.pow(clamped, 0.86);
}

// Maps (t along rail, theta in degrees [-90..+90] around cylinder face) to 2D canvas
function railSurfacePoint(t, thetaDeg, radialOffset = 0) {
  let c = railCenter(t);
  let r = railRadius(t) + radialOffset;
  let s = Math.sin((thetaDeg * Math.PI) / 180);
  // Subtle axial curvature of cylindrical cross-section in perspective
  let cProj = Math.cos((thetaDeg * Math.PI) / 180) * r * 0.14;
  return {
    x: c.x + RAIL_NX * (r * s) - RAIL_TX * cProj,
    y: c.y + RAIL_NY * (r * s) - RAIL_TY * cProj
  };
}

function drawArcBandPolygon(cx, cy, rInner, rOuter, aStart, aEnd, steps, curv = 0.4) {
  brush.beginShape(curv);
  for (let i = 0; i <= steps; i++) {
    let a = aStart + ((aEnd - aStart) * i) / steps;
    let rad = (a * Math.PI) / 180;
    brush.vertex(cx + Math.cos(rad) * rOuter, cy + Math.sin(rad) * rOuter);
  }
  for (let i = steps; i >= 0; i--) {
    let a = aStart + ((aEnd - aStart) * i) / steps;
    let rad = (a * Math.PI) / 180;
    brush.vertex(cx + Math.cos(rad) * rInner, cy + Math.sin(rad) * rInner);
  }
  brush.endShape(true);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Base damp alabaster-white fog ground
  background("#f1f4f8");

  // 1. Atmospheric Watercolor Under-Washes (Fog Bow + White-on-White Sky)
  drawFogBowWatercolorBase();

  // 2. Layered Spray Mist & Powdery Charcoal Blending for the Fog Bow & Sky
  drawAtmosphericMistAndBow();

  // 3. Distant Ferry Deck Structure (Receding Rail, Mid-Cable, Distant Stanchion)
  drawRecedingDeckElements();

  // 4. Foreground Welded Stanchion Post (Sharp at Collar, Dissolving Down into Fog)
  drawForegroundStanchion();

  // 5. The Foreground Painted Steel Rail (Cream Enamel Cylinder + Reflections)
  drawMainSteelRailBody();

  // 6. Chipped Cream Enamel, Marine Primer & Vivid Rust Blooms
  drawChippedEnamelAndRust();

  // 7. Micro-Surface Sweat, Meniscus Film & Hanging Beads of Condensation
  drawCondensationAndDroplets();

  // 8. Final Atmospheric Mist Veils over Receding Zones (Leaving Near Rail Knife-Sharp)
  drawFinalFogDissolution();

  noLoop();
}

// ============================================================================
// 1. WATERCOLOR BASE WASHES FOR THE FOG BOW & SKY
// ============================================================================

function drawFogBowWatercolorBase() {
  brush.noStroke();

  // Outer ambient cool fog washes (outside the bow)
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.35, 0.08);
  const outerSkyColors = ["#e4e9f0", "#eaeff5", "#dfe5ee"];
  for (let i = 0; i < 6; i++) {
    brush.fill(outerSkyColors[i % outerSkyColors.length], 28);
    let r1 = BOW_R + 75 + i * 55;
    let r2 = r1 + 95;
    drawArcBandPolygon(BOW_CX, BOW_CY, r1, r2, -172, -12, 24, 0.3);
  }

  // Cold violet-grey interior of the fog bow (batched by color tone)
  const violetInteriorTones = [
    { col: "#68709e", alpha: 24, rIn: 480, rOut: 760 },
    { col: "#737ba8", alpha: 26, rIn: 360, rOut: 750 },
    { col: "#7f87b3", alpha: 25, rIn: 240, rOut: 735 },
    { col: "#8d95be", alpha: 24, rIn: 120, rOut: 690 },
    { col: "#9ea6ca", alpha: 22, rIn: 40, rOut: 560 },
    { col: "#5d6594", alpha: 20, rIn: 610, rOut: 758 },
    { col: "#7884b5", alpha: 18, rIn: 680, rOut: 768 }
  ];

  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.42, 0.1);
  for (let b of violetInteriorTones) {
    brush.fill(b.col, b.alpha);
    drawArcBandPolygon(
      BOW_CX + random(-12, 12),
      BOW_CY + random(-12, 12),
      b.rIn,
      b.rOut,
      -175,
      -8,
      26,
      0.4
    );
  }

  // Faintest blush of saturated apricot on the outer edge of the fog bow
  const apricotBlushBands = [
    { col: "#ff8648", alpha: 18, rIn: BOW_R + 18, rOut: BOW_R + 56 },
    { col: "#ff9b66", alpha: 22, rIn: BOW_R + 10, rOut: BOW_R + 68 },
    { col: "#ffb085", alpha: 24, rIn: BOW_R + 24, rOut: BOW_R + 86 },
    { col: "#ffc6a3", alpha: 20, rIn: BOW_R + 40, rOut: BOW_R + 108 },
    { col: "#ffdbbd", alpha: 18, rIn: BOW_R + 60, rOut: BOW_R + 135 }
  ];

  brush.fillBleed(0.48, "out");
  for (let b of apricotBlushBands) {
    brush.fill(b.col, b.alpha);
    drawArcBandPolygon(BOW_CX, BOW_CY, b.rIn, b.rOut, -172, -12, 28, 0.4);
  }

  // Ghostly white core of the fog bow (opaque washes + soft fills)
  brush.noFill();
  for (let i = 0; i < 4; i++) {
    brush.wash("#ffffff", 38);
    drawArcBandPolygon(
      BOW_CX,
      BOW_CY,
      BOW_R - 42 + i * 6,
      BOW_R + 22 - i * 5,
      -175,
      -8,
      28,
      0.4
    );
  }
  brush.noWash();
}

// ============================================================================
// 2. LAYERED SPRAY MIST & POWDERY CHARCOAL BLENDING FOR THE FOG BOW & SKY
// ============================================================================

function drawAtmosphericMistAndBow() {
  // Concentric powdery charcoal & soft mist veil arcs building the optical fog bow
  for (let pass = 0; pass < 420; pass++) {
    let u = random();
    let r, col, bName, w;

    if (u < 0.34) {
      // Cold violet-grey interior
      let t = random();
      r = lerp(140, BOW_R - 42, Math.pow(t, 0.7));
      const cols = ["#636b99", "#7179a6", "#8189b3", "#9299c0", "#a6add0", "#b8bedb"];
      let idx = Math.floor(map(r, 140, BOW_R - 42, cols.length - 1, 0));
      col = cols[constrain(idx + floor(random(-1, 1.5)), 0, cols.length - 1)];
      bName = random() < 0.55 ? "powder_charcoal" : "mist_veil";
      w = random(0.8, 1.8);
    } else if (u < 0.42) {
      // Inner supernumerary slate-blue/violet edge
      r = random(BOW_R - 58, BOW_R - 28);
      const cols = ["#5c6799", "#6c79ad", "#8591c2", "#aeb7db"];
      col = random(cols);
      bName = random() < 0.6 ? "powder_charcoal" : "fine_spray";
      w = random(0.7, 1.4);
    } else if (u < 0.68) {
      // Ghostly colourless white fog bow core
      r = BOW_R + randomGaussian(0, 18);
      const cols = ["#ffffff", "#ffffff", "#fafcff", "#f2f6fc"];
      col = random(cols);
      bName = random() < 0.5 ? "mist_veil" : random() < 0.7 ? "powder_charcoal" : "fine_spray";
      w = random(0.9, 2.1);
    } else if (u < 0.84) {
      // Faintest blush of apricot on outer edge
      r = BOW_R + random(18, 92);
      let fade = map(r, BOW_R + 18, BOW_R + 92, 0, 1);
      const vividApricot = ["#ff7a38", "#ff8f54", "#ffa370", "#ffb68c", "#ffcaa8", "#ffe0cc"];
      let idx = constrain(Math.floor(fade * vividApricot.length), 0, vividApricot.length - 1);
      col = vividApricot[idx];
      bName = random() < 0.5 ? "powder_charcoal" : random() < 0.75 ? "mist_veil" : "fine_spray";
      w = random(0.7, 1.6);
    } else {
      // Outer white-on-white damp sky
      r = random(BOW_R + 82, 1380);
      const cols = ["#e3e8f0", "#ebeef4", "#f2f5f9", "#ffffff", "#dfe5ed"];
      col = random(cols);
      bName = random() < 0.6 ? "mist_veil" : "powder_charcoal";
      w = random(1.0, 2.2);
    }

    let a1 = random(-172, -32);
    let span = random(14, 46);
    let a2 = Math.min(-8, a1 + span);

    brush.set(bName, col, w);
    brush.arc(BOW_CX + random(-8, 8), BOW_CY + random(-8, 8), r, a1, a2);
  }

  // Drifting horizontal sea-mist flow lines across the frame
  brush.field("sea_mist");
  for (let i = 0; i < 190; i++) {
    let x = random(-60, 1260);
    let y = random(-40, 1240);
    let distToBow = Math.hypot(x - BOW_CX, y - BOW_CY);

    let col = "#f2f5f9";
    if (distToBow < BOW_R - 45) {
      col = random(["#7d85b0", "#9198bf", "#a8afd1", "#c5cae3", "#e2e6f2"]);
    } else if (distToBow < BOW_R + 24) {
      col = "#ffffff";
    } else if (distToBow < BOW_R + 85) {
      col = random(["#ff9d69", "#ffb68e", "#ffd4ba", "#fff2e8"]);
    } else {
      col = random(["#e6ebf2", "#eef2f7", "#f7f9fc", "#ffffff"]);
    }

    let bName = random() < 0.55 ? "powder_charcoal" : random() < 0.8 ? "mist_veil" : "fine_spray";
    brush.set(bName, col, random(0.6, 1.6));
    brush.flowLine(x, y, random(90, 280), random() < 0.5 ? 0 : 180);
  }
  brush.noField();

  // Extra luminous white powdery highlight at the crest of the fog bow
  for (let i = 0; i < 85; i++) {
    let r = BOW_R + randomGaussian(-2, 13);
    let a1 = random(-155, -35);
    let a2 = a1 + random(12, 32);
    brush.set(random() < 0.6 ? "powder_charcoal" : "fine_spray", "#ffffff", random(0.8, 1.7));
    brush.arc(BOW_CX, BOW_CY, r, a1, a2);
  }
}

// ============================================================================
// 3. DISTANT FERRY DECK ELEMENTS DISSOLVING INTO FOG
// ============================================================================

function drawRecedingDeckElements() {
  // A. Distant Bulwark / Lower Deck Horizon Hint on Left & Bottom (Ghostly)
  for (let i = 0; i < 45; i++) {
    let y = random(980, 1200);
    brush.set("mist_veil", random(["#b2b8d0", "#c6cce0", "#d8dceb", "#eaedf5"]), random(1.2, 2.4));
    brush.line(random(-50, 300), y, random(500, 1250), y + random(-35, 35));
  }

  // B. Distant Stanchion at t = 0.94 (x ~ 855, y ~ 448) dropping into fog toward (960, 790)
  let stTop = railCenter(0.94);
  let stBot = { x: stTop.x + 110, y: stTop.y + 340 };
  for (let step = 0; step < 36; step++) {
    let f = step / 35;
    let fade = Math.pow(f, 0.75); // Rapidly dissolves downward
    let x1 = lerp(stTop.x, stBot.x, f);
    let y1 = lerp(stTop.y, stBot.y, f);
    let w = lerp(13, 8, f);

    for (let s = -1; s <= 1; s += 0.25) {
      let px = x1 + s * w;
      let py = y1 - s * w * 0.3;
      let baseCol = s < -0.2 ? "#d6d4cf" : s < 0.3 ? "#9c9da8" : "#787c96";
      let fogCol = "#8a91b8";
      let c = lerpColor(color(baseCol), color(fogCol), fade);
      brush.set("powder_charcoal", c, lerp(0.5, 1.2, fade));
      brush.line(px, py, px + 3, py + 10);
    }
  }

  // C. Receding Turn of the Main Rail beyond t = 0.94 into the White-on-White Fog (to 1175, 392)
  let elbow = railCenter(0.95);
  let farEnd = { x: 1185, y: 392 };
  for (let i = 0; i < 48; i++) {
    let f = i / 47;
    let cx = lerp(elbow.x, farEnd.x, f);
    let cy = lerp(elbow.y, farEnd.y, f);
    let rad = lerp(24, 13, f);
    let fogMix = Math.pow(f, 0.65);

    for (let th = -85; th <= 85; th += 14) {
      let s = Math.sin((th * Math.PI) / 180);
      let px = cx + s * rad * 0.25;
      let py = cy + s * rad * 0.96;
      let nx = lerp(elbow.x, farEnd.x, Math.min(1, f + 0.04)) + s * rad * 0.25;
      let ny = lerp(elbow.y, farEnd.y, Math.min(1, f + 0.04)) + s * rad * 0.96;

      let shade = th < -20 ? "#f2efe8" : th < 25 ? "#d2cbc0" : "#8e8c96";
      let skyTarget = f < 0.5 ? "#ffe5d1" : "#ebeff5";
      let c = lerpColor(color(shade), color(skyTarget), fogMix);
      brush.set(f < 0.4 ? "enamel_shader" : "powder_charcoal", c, lerp(0.7, 1.5, f));
      brush.line(px, py, nx, ny);
    }
  }

  // D. Lower Parallel Steel Wire Cable / Mid-Rail (Sharp near foreground stanchion, dissolving both ways)
  // Passes through foreground stanchion around (396, 892)
  let cableP0 = { x: -60, y: 1116 };
  let cableP1 = { x: 910, y: 638 };
  let cableSegs = 70;
  for (let i = 0; i < cableSegs; i++) {
    let t0 = i / cableSegs;
    let t1 = (i + 1) / cableSegs;
    let distFromStanchion = Math.abs(t0 - 0.45);
    let fogFactor = constrain(map(distFromStanchion, 0.08, 0.42, 0, 1), 0, 1);
    if (fogFactor > 0.96) continue;

    let x0 = lerp(cableP0.x, cableP1.x, t0);
    let y0 = lerp(cableP0.y, cableP1.y, t0);
    let x1 = lerp(cableP0.x, cableP1.x, t1);
    let y1 = lerp(cableP0.y, cableP1.y, t1);
    let rCable = lerp(8.5, 3.8, t0);

    let fogBg = t0 < 0.5 ? "#9ba1c4" : "#838ab3";
    let topC = lerpColor(color("#f5f2eb"), color(fogBg), fogFactor);
    let midC = lerpColor(color("#a89f96"), color(fogBg), fogFactor);
    let botC = lerpColor(color("#585460"), color(fogBg), fogFactor);

    let bType = fogFactor < 0.35 ? "enamel_shader" : "powder_charcoal";
    brush.set(bType, topC, lerp(0.6, 1.1, fogFactor));
    brush.line(x0, y0 - rCable * 0.6, x1, y1 - rCable * 0.6);

    brush.set(bType, midC, lerp(0.7, 1.2, fogFactor));
    brush.line(x0, y0, x1, y1);

    brush.set(bType, botC, lerp(0.6, 1.1, fogFactor));
    brush.line(x0, y0 + rCable * 0.65, x1, y1 + rCable * 0.65);

    if (fogFactor < 0.28) {
      brush.set("razor_detail", "#3f3b45", 0.7);
      brush.line(x0, y0 + rCable * 0.9, x1, y1 + rCable * 0.9);
      // Small rust spot on cable near stanchion sleeve
      if (Math.abs(t0 - 0.45) < 0.05) {
        brush.set("razor_detail", "#c94814", 1.1);
        brush.line(x0, y0 + rCable * 0.2, x1, y1 + rCable * 0.3);
      }
    }
  }
}

// ============================================================================
// 4. FOREGROUND STANCHION POST (SHARP AT WELD COLLAR, DISSOLVING DOWNWARD)
// ============================================================================

function drawForegroundStanchion() {
  // Joins main rail at t = 0.38
  let attach = railCenter(0.38);
  let stEnd = { x: attach.x + 175, y: attach.y + 520 };
  let stDX = stEnd.x - attach.x;
  let stDY = stEnd.y - attach.y;
  let stLen = Math.hypot(stDX, stDY);
  let stNX = stDY / stLen; // Normal across stanchion shaft
  let stNY = -stDX / stLen;

  let steps = 65;
  for (let i = 0; i < steps; i++) {
    let f0 = i / steps;
    let f1 = (i + 1) / steps;
    // Stanchion stays sharp in upper half (f < 0.42), then dissolves into rising deck fog
    let fogMix = constrain(map(f0, 0.38, 0.92, 0, 1), 0, 1);
    let r0 = lerp(26, 22, f0);
    // Flared weld collar near f0 < 0.12
    if (f0 < 0.12) r0 += Math.pow((0.12 - f0) / 0.12, 1.6) * 11;

    let cx0 = lerp(attach.x, stEnd.x, f0);
    let cy0 = lerp(attach.y, stEnd.y, f0);
    let cx1 = lerp(attach.x, stEnd.x, f1);
    let cy1 = lerp(attach.y, stEnd.y, f1);

    let bgFog = lerpColor(color("#8a91b8"), color("#d2d7e8"), f0);

    for (let s = -1; s <= 1; s += 0.1) {
      let shade;
      if (s < -0.65) shade = "#e8ecf2";
      else if (s < -0.25) shade = "#fbf8f0";
      else if (s < 0.2) shade = "#dfd5c3";
      else if (s < 0.65) shade = "#8f8988";
      else shade = "#5e5a63";

      // Rust weeping down the center-right of the stanchion from the collar
      if (s > -0.15 && s < 0.45 && f0 < 0.55) {
        let rustNoise = noise(f0 * 12, s * 6);
        if (rustNoise > 0.42) {
          shade = lerpColor(
            color(shade),
            color(rustNoise > 0.62 ? "#c74312" : "#e36c20"),
            constrain((0.55 - f0) * 2.2, 0, 0.85)
          );
        }
      }

      let finalCol = lerpColor(color(shade), bgFog, Math.pow(fogMix, 0.85));
      let bName = fogMix < 0.35 ? "enamel_shader" : "powder_charcoal";
      brush.set(bName, finalCol, lerp(0.85, 1.6, fogMix));
      brush.line(
        cx0 + stNX * s * r0,
        cy0 + stNY * s * r0,
        cx1 + stNX * s * r0,
        cy1 + stNY * s * r0
      );
    }

    // Knife-sharp edges on upper stanchion
    if (fogMix < 0.35) {
      brush.set("razor_detail", "#45424a", 0.85 * (1 - fogMix));
      brush.line(cx0 + stNX * r0, cy0 + stNY * r0, cx1 + stNX * r0, cy1 + stNY * r0);
      brush.set("razor_detail", "#b8b4ad", 0.75 * (1 - fogMix));
      brush.line(cx0 - stNX * r0, cy0 - stNY * r0, cx1 - stNX * r0, cy1 - stNY * r0);
    }
  }

  // Cable sleeve / eye-bolt on stanchion at f = 0.36
  let slvX = lerp(attach.x, stEnd.x, 0.36);
  let slvY = lerp(attach.y, stEnd.y, 0.36);
  brush.set("enamel_shader", "#4a2416", 1.2);
  brush.circle(slvX + 4, slvY + 2, 11, 0.15);
  brush.set("razor_detail", "#d95218", 1.1);
  brush.arc(slvX + 4, slvY + 2, 12, -40, 160);
  brush.set("razor_detail", "#fff8eb", 0.9);
  brush.arc(slvX + 4, slvY + 2, 10, -150, -30);
}

// ============================================================================
// 5. THE FOREGROUND PAINTED STEEL RAIL (CYLINDRICAL CREAM ENAMEL FORM)
// ============================================================================

function drawMainSteelRailBody() {
  // Opaque under-wash so zero background strokes bleed through the solid steel cylinder
  brush.noStroke();
  brush.wash("#e3d8c6", 245);
  brush.beginShape(0.1);
  for (let i = 0; i <= 40; i++) {
    let t = (i / 40) * 0.96;
    let p = railSurfacePoint(t, -90);
    brush.vertex(p.x, p.y);
  }
  for (let i = 40; i >= 0; i--) {
    let t = (i / 40) * 0.96;
    let p = railSurfacePoint(t, 90);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Longitudinal cylindrical shading strips from theta = -90 (top) to +90 (bottom)
  let tSteps = 55;
  for (let th = -90; th <= 90; th += 2.2) {
    for (let i = 0; i < tSteps; i++) {
      let t0 = (i / tSteps) * 0.96;
      let t1 = ((i + 1) / tSteps) * 0.96;
      let p0 = railSurfacePoint(t0, th);
      let p1 = railSurfacePoint(t1, th);

      // Compute hyperreal cylindrical reflectance on wet cream enamel
      let baseCol = getCreamEnamelColor(t0, th);

      // Far end beyond t = 0.85 begins to pick up atmospheric veil
      if (t0 > 0.85) {
        let mistFade = map(t0, 0.85, 0.96, 0, 0.65);
        baseCol = lerpColor(baseCol, color("#f0ece6"), mistFade);
      }

      let w = map(t0, 0, 0.96, 1.35, 0.65);
      brush.set("enamel_shader", baseCol, w);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Fine glossy specular sheen lines along upper cylinder (-52 to -26 deg)
  for (let th = -48; th <= -28; th += 3.5) {
    let pts = [];
    for (let i = 0; i <= 30; i++) {
      let t = (i / 30) * 0.86;
      let p = railSurfacePoint(t, th + (noise(t * 8, th) - 0.5) * 2.5);
      pts.push([p.x, p.y, map(t, 0, 0.86, 1.1, 0.6)]);
    }
    brush.set("razor_detail", th > -42 && th < -33 ? "#ffffff" : "#fbf7ef", 0.95);
    brush.spline(pts, 0.3);
  }

  // Circumferential welded pipe joint rings at t = 0.375 and t = 0.74
  drawWeldSeamRing(0.375);
  drawWeldSeamRing(0.74);

  // Knife-sharp top and bottom boundary contours of the steel rail in the near ground
  for (let i = 0; i < 48; i++) {
    let t0 = (i / 48) * 0.88;
    let t1 = ((i + 1) / 48) * 0.88;
    let sharpnessFade = t0 > 0.78 ? map(t0, 0.78, 0.88, 1, 0.2) : 1;

    // Top edge: crisp cool sky rim with slight dark contrast hairline just inside
    let top0 = railSurfacePoint(t0, -90);
    let top1 = railSurfacePoint(t1, -90);
    brush.set("razor_detail", "#ffffff", 1.1 * sharpnessFade);
    brush.line(top0.x, top0.y, top1.x, top1.y);

    let topIn0 = railSurfacePoint(t0, -86);
    let topIn1 = railSurfacePoint(t1, -86);
    brush.set("razor_detail", "#b5afa6", 0.7 * sharpnessFade);
    brush.line(topIn0.x, topIn0.y, topIn1.x, topIn1.y);

    // Bottom edge: sharp dark wet underside shadow contour
    let bot0 = railSurfacePoint(t0, 90);
    let bot1 = railSurfacePoint(t1, 90);
    brush.set("razor_detail", "#2e2a33", 1.15 * sharpnessFade);
    brush.line(bot0.x, bot0.y, bot1.x, bot1.y);
  }
}

function getCreamEnamelColor(t, th) {
  // Base cream enamel palette across cylindrical angles [-90..+90]
  let c;
  if (th < -72) {
    // Upper sky-facing rim
    c = lerpColor(color("#dce3ec"), color("#f2efe6"), map(th, -90, -72, 0, 1));
  } else if (th < -48) {
    // Transition into bright specular band
    c = lerpColor(color("#f2efe6"), color("#ffffff"), map(th, -72, -48, 0, 1));
  } else if (th < -26) {
    // Glossy wet specular band
    c = lerpColor(color("#ffffff"), color("#f7f0e2"), map(th, -48, -26, 0, 1));
  } else if (th < 12) {
    // Warm cream enamel body
    c = lerpColor(color("#f7f0e2"), color("#e3d5bd"), map(th, -26, 12, 0, 1));
  } else if (th < 48) {
    // Lower turning curve into cool damp shadow
    c = lerpColor(color("#e3d5bd"), color("#968f8c"), map(th, 12, 48, 0, 1));
  } else if (th < 74) {
    // Core terminator shadow infused with cold violet-grey sky bounce
    c = lerpColor(color("#968f8c"), color("#66626e"), map(th, 48, 74, 0, 1));
  } else if (th < 85) {
    // Underside reflected bounce light from wet deck
    c = lerpColor(color("#66626e"), color("#7a7785"), map(th, 74, 85, 0, 1));
  } else {
    // Dark water-film saturation line along very bottom
    c = lerpColor(color("#7a7785"), color("#3b3640"), map(th, 85, 90, 0, 1));
  }

  // Subtle environmental color inflection from the fog bow behind the rail
  if (t > 0.58 && t < 0.88 && th > -35 && th < 35) {
    // Warm apricot & luminous bow reflection on mid-upper right rail
    c = lerpColor(c, color("#ffcfb0"), 0.12);
  } else if (t < 0.55 && th > 20 && th < 75) {
    // Cold violet-grey reflection on lower-left rail shadow
    c = lerpColor(c, color("#737aa6"), 0.16);
  }

  // Subtle weathered enamel mottling
  let n = noise(t * 25, th * 0.15);
  if (n > 0.58) {
    c = lerpColor(c, color("#d1bfa3"), (n - 0.58) * 0.35);
  }
  return c;
}

function drawWeldSeamRing(tSeam) {
  let ptsDark = [];
  let ptsLight = [];
  let ptsRust = [];
  for (let th = -88; th <= 88; th += 10) {
    let jitter = (noise(th * 0.2, tSeam * 10) - 0.5) * 0.004;
    let pD = railSurfacePoint(tSeam + jitter, th, 1.2);
    let pL = railSurfacePoint(tSeam - 0.003 + jitter, th, 1.2);
    let pR = railSurfacePoint(tSeam + 0.002 + jitter, th, 0.6);
    ptsDark.push([pD.x, pD.y]);
    ptsLight.push([pL.x, pL.y]);
    ptsRust.push([pR.x, pR.y]);
  }
  brush.set("enamel_shader", "#c76228", 0.9);
  brush.spline(ptsRust, 0.4);
  brush.set("razor_detail", "#5c4a42", 0.95);
  brush.spline(ptsDark, 0.4);
  brush.set("razor_detail", "#fffdf7", 0.95);
  brush.spline(ptsLight, 0.4);
}

// ============================================================================
// 6. CHIPPED CREAM ENAMEL, MARINE PRIMER & VIVID RUST BLOOMS
// ============================================================================

function drawChippedEnamelAndRust() {
  // Major hyper-detailed chipped enamel & rust bloom complexes along the rail
  const rustComplexes = [
    { t: 0.09, th: -8, dt: 0.048, dth: 44, seed: 101, intensity: 1.0 },
    { t: 0.16, th: 38, dt: 0.032, dth: 28, seed: 202, intensity: 0.85 },
    { t: 0.24, th: -32, dt: 0.038, dth: 30, seed: 303, intensity: 0.9 },
    { t: 0.31, th: 18, dt: 0.028, dth: 26, seed: 404, intensity: 0.8 },
    { t: 0.378, th: 28, dt: 0.052, dth: 48, seed: 505, intensity: 1.0 }, // Weld joint bloom
    { t: 0.46, th: -18, dt: 0.035, dth: 32, seed: 606, intensity: 0.9 },
    { t: 0.54, th: 32, dt: 0.03, dth: 28, seed: 707, intensity: 0.85 },
    { t: 0.63, th: -6, dt: 0.042, dth: 36, seed: 808, intensity: 0.95 },
    { t: 0.74, th: 12, dt: 0.036, dth: 34, seed: 909, intensity: 0.85 }, // Second weld joint
    { t: 0.82, th: -14, dt: 0.028, dth: 26, seed: 1010, intensity: 0.7 }
  ];

  // 1. First pass: Translucent weeping rust stains bleeding downward over the cream enamel
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.2);

  for (let rc of rustComplexes) {
    // Gravity stain extending toward theta = +88
    brush.fill("#e66b20", 42 * rc.intensity);
    brush.beginShape(0.35);
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      let tOff = Math.cos(a) * rc.dt * 1.25;
      let thOff = Math.sin(a) * rc.dth * (Math.sin(a) > 0 ? 1.65 : 1.05);
      let thClamped = constrain(rc.th + thOff, -88, 89);
      let p = railSurfacePoint(rc.t + tOff, thClamped);
      brush.vertex(p.x, p.y);
    }
    brush.endShape(true);

    // Secondary bright ochre-orange weep halo
    brush.fill("#f59331", 32 * rc.intensity);
    brush.beginShape(0.4);
    for (let i = 0; i <= steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      let tOff = Math.cos(a) * rc.dt * 0.95 + 0.004;
      let thOff = Math.sin(a) * rc.dth * (Math.sin(a) > 0 ? 1.9 : 0.8);
      let thClamped = constrain(rc.th + thOff, -88, 89);
      let p = railSurfacePoint(rc.t + tOff, thClamped);
      brush.vertex(p.x, p.y);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // 2. Second pass: Render each chipped enamel fracture, marine primer rim, 3D paint lip, and rust core
  for (let rc of rustComplexes) {
    drawSingleChipComplex(rc);
  }

  // 3. Third pass: Dozens of smaller micro-chips, pinhead rust blisters, and hairline enamel cracks
  for (let i = 0; i < 65; i++) {
    let t = random(0.02, 0.86);
    let th = random(-78, 78);
    let scale = map(t, 0, 0.86, 1.0, 0.42);
    let p = railSurfacePoint(t, th);

    // Rust dot core
    brush.set("razor_detail", random(["#591f0e", "#9e3311", "#d95016", "#f07b22"]), 0.9 * scale);
    brush.circle(p.x, p.y, random(1.2, 3.8) * scale, 0.35);

    // Tiny downward rust weep line
    if (random() < 0.65) {
      let pDown = railSurfacePoint(t + random(-0.002, 0.003), Math.min(89, th + random(8, 26)));
      brush.set("glass_glaze", random(["#d95818", "#eb7a26"]), 0.6 * scale);
      brush.line(p.x, p.y, pDown.x, pDown.y);
    }

    // Tiny bright bottom paint lip highlight
    let pLip = railSurfacePoint(t, Math.min(89, th + 3.5));
    brush.set("razor_detail", "#fffdf9", 0.65 * scale);
    brush.line(pLip.x - 2 * scale, pLip.y, pLip.x + 2 * scale, pLip.y - 1 * scale);
  }
}

function drawSingleChipComplex(rc) {
  let numVerts = 28;
  let outerChipPts = [];
  let primerPts = [];
  let innerCorePts = [];

  for (let i = 0; i <= numVerts; i++) {
    let ang = (i / numVerts) * Math.PI * 2;
    let n = noise(Math.cos(ang) * 2.2 + rc.seed, Math.sin(ang) * 2.2 + rc.seed);
    let jag = 0.55 + n * 0.78;

    let tOuter = rc.t + Math.cos(ang) * rc.dt * jag;
    let thOuter = constrain(rc.th + Math.sin(ang) * rc.dth * jag, -87, 87);
    outerChipPts.push({ t: tOuter, th: thOuter, ang: ang, p: railSurfacePoint(tOuter, thOuter) });

    let tPrimer = rc.t + Math.cos(ang) * rc.dt * jag * 0.84;
    let thPrimer = constrain(rc.th + Math.sin(ang) * rc.dth * jag * 0.84, -86, 86);
    primerPts.push(railSurfacePoint(tPrimer, thPrimer));

    let tCore = rc.t + Math.cos(ang) * rc.dt * jag * 0.58;
    let thCore = constrain(rc.th + Math.sin(ang) * rc.dth * jag * 0.58, -85, 85);
    innerCorePts.push(railSurfacePoint(tCore, thCore));
  }

  let scale = map(rc.t, 0, 0.88, 1.0, 0.45);

  // A. Exposed Vivid Turquoise-Blue Marine Primer Rim (just inside the chipped cream paint!)
  brush.noStroke();
  brush.wash("#1b8796", 215);
  brush.beginShape(0.2);
  for (let pt of outerChipPts) brush.vertex(pt.p.x, pt.p.y);
  brush.endShape(true);

  // B. Vivid Cadmium Orange / Red-Lead Sub-Primer & Rust Bloom Layer
  brush.wash("#e04f16", 230);
  brush.beginShape(0.25);
  for (let pt of primerPts) brush.vertex(pt.x, pt.y);
  brush.endShape(true);

  // C. Deep Dark Iron Oxide Pitted Core
  brush.wash("#3b170c", 235);
  brush.beginShape(0.3);
  for (let pt of innerCorePts) brush.vertex(pt.x, pt.y);
  brush.endShape(true);
  brush.noWash();

  // D. Rich Textured Rust Granulation inside the Bloom (Burnt Sienna, Cadmium Rust, Ochre)
  let rustSamples = Math.floor(38 * scale);
  for (let k = 0; k < rustSamples; k++) {
    let rFrac = Math.pow(random(), 0.7);
    let ang = random(Math.PI * 2);
    let n = noise(Math.cos(ang) * 2.2 + rc.seed, Math.sin(ang) * 2.2 + rc.seed);
    let jag = (0.55 + n * 0.78) * rFrac;
    let tk = rc.t + Math.cos(ang) * rc.dt * jag;
    let thk = constrain(rc.th + Math.sin(ang) * rc.dth * jag, -86, 86);
    let pk = railSurfacePoint(tk, thk);

    let rustPalette = [
      "#291008",
      "#521b0c",
      "#8c2d10",
      "#c94212",
      "#eb641b",
      "#f78e28",
      "#ffad42"
    ];
    let col = random(rustPalette);
    // Occasional fleck of exposed turquoise primer at outer boundary
    if (rFrac > 0.78 && random() < 0.35) {
      col = random(["#187e8c", "#2eb0bf", "#125863"]);
    }

    brush.set(random() < 0.7 ? "razor_detail" : "fine_spray", col, random(0.6, 1.25) * scale);
    brush.line(
      pk.x + random(-2, 2) * scale,
      pk.y + random(-2, 2) * scale,
      pk.x + random(-3, 3) * scale,
      pk.y + random(-3, 3) * scale
    );
  }

  // E. 3D Chipped Cream Paint Edge Thickness!
  // Upper rim of chip (sin(ang) < 0) casts a razor-sharp dark shadow downward onto the primer/rust.
  // Lower rim of chip (sin(ang) > 0) catches overhead sky light on its broken cream cliff edge!
  for (let i = 0; i < numVerts; i++) {
    let cur = outerChipPts[i];
    let nxt = outerChipPts[i + 1];
    let midSin = Math.sin((cur.ang + nxt.ang) * 0.5);

    if (midSin < 0) {
      // Upper lip of chipped cream enamel: dark undercut shadow + sharp cream contour
      brush.set("razor_detail", "#1c0d08", 1.15 * scale);
      brush.line(
        cur.p.x + RAIL_NX * 1.4 * scale,
        cur.p.y + RAIL_NY * 1.4 * scale,
        nxt.p.x + RAIL_NX * 1.4 * scale,
        nxt.p.y + RAIL_NY * 1.4 * scale
      );
      brush.set("razor_detail", "#d9cdb8", 0.8 * scale);
      brush.line(cur.p.x, cur.p.y, nxt.p.x, nxt.p.y);
    } else {
      // Lower lip of chipped cream enamel: brilliant sunlit ivory thickness bevel!
      brush.set("razor_detail", "#ffffff", 1.25 * scale);
      brush.line(cur.p.x, cur.p.y, nxt.p.x, nxt.p.y);

      brush.set("razor_detail", "#7a5c49", 0.75 * scale);
      brush.line(
        cur.p.x + RAIL_NX * 1.3 * scale,
        cur.p.y + RAIL_NY * 1.3 * scale,
        nxt.p.x + RAIL_NX * 1.3 * scale,
        nxt.p.y + RAIL_NY * 1.3 * scale
      );
    }
  }

  // F. Hairline stress cracks in the cream enamel radiating from the chip corners
  for (let c = 0; c < 3; c++) {
    let startIdx = Math.floor(random(numVerts));
    let st = outerChipPts[startIdx];
    let crackPts = [[st.p.x, st.p.y]];
    let curT = st.t;
    let curTh = st.th;
    let dirT = (curT > rc.t ? 1 : -1) * random(0.004, 0.009);
    let dirTh = random(-6, 6);
    for (let s = 0; s < 4; s++) {
      curT += dirT + random(-0.002, 0.002);
      curTh = constrain(curTh + dirTh + random(-4, 4), -86, 86);
      let cp = railSurfacePoint(curT, curTh);
      crackPts.push([cp.x, cp.y]);
    }
    brush.set("razor_detail", "#543222", 0.55 * scale);
    brush.spline(crackPts, 0.3);
  }
}

// ============================================================================
// 7. BEADS OF CONDENSATION HANGING FROM THE UNDERSIDE & SURFACE DEW
// ============================================================================

function drawCondensationAndDroplets() {
  // 1. Continuous glistening wet meniscus film along the underside of the rail (theta = +84..+90)
  for (let i = 0; i < 42; i++) {
    let t0 = (i / 42) * 0.85;
    let t1 = ((i + 1) / 42) * 0.85;
    let p0 = railSurfacePoint(t0, 88.5, 0.8);
    let p1 = railSurfacePoint(t1, 88.5, 0.8);
    let scale = map(t0, 0, 0.85, 1.0, 0.45);

    brush.set("glass_glaze", "#9da6c4", 1.1 * scale);
    brush.line(p0.x, p0.y, p1.x, p1.y);

    if (i % 2 === 0) {
      brush.set("razor_detail", "#ffffff", 0.8 * scale);
      brush.line(p0.x, p0.y + 0.8 * scale, p1.x, p1.y + 0.8 * scale);
    }
  }

  // 2. Micro-condensation beads clinging to the lower cheek of the rail (theta = +32..+84)
  for (let i = 0; i < 110; i++) {
    let t = random(0.02, 0.84);
    let th = random(32, 84);
    let scale = map(t, 0, 0.84, 1.0, 0.42);
    let rBead = random(1.4, 3.6) * scale;
    let p = railSurfacePoint(t, th);

    // Tiny dark shadow above/around bead
    brush.set("razor_detail", "#332f3a", 0.75 * scale);
    brush.arc(p.x, p.y, rBead, -160, 40);

    // Luminous lower caustic belly
    brush.set("razor_detail", "#dce6f7", 0.8 * scale);
    brush.arc(p.x, p.y, rBead * 0.85, 20, 170);

    // Pinpoint white specular
    brush.set("razor_detail", "#ffffff", 0.95 * scale);
    brush.line(p.x - rBead * 0.35, p.y - rBead * 0.35, p.x + 0.2, p.y - rBead * 0.35);
  }

  // 3. Signature Pendant Beads of Condensation Hanging from the Underside of the Rail!
  // Rust-tinted flag indicates droplets hanging directly below a major rust bloom
  const pendantDrops = [
    { t: 0.045, size: 0.75, rustTint: 0.1 },
    { t: 0.088, size: 1.25, rustTint: 0.95 }, // Below major foreground rust bloom!
    { t: 0.112, size: 0.85, rustTint: 0.75 },
    { t: 0.158, size: 1.05, rustTint: 0.85 },
    { t: 0.195, size: 0.65, rustTint: 0.15 },
    { t: 0.238, size: 1.15, rustTint: 0.8 },
    { t: 0.272, size: 0.7, rustTint: 0.2 },
    { t: 0.312, size: 0.95, rustTint: 0.75 },
    { t: 0.348, size: 0.6, rustTint: 0.3 },
    { t: 0.415, size: 1.18, rustTint: 0.9 }, // Just below stanchion weld collar
    { t: 0.442, size: 0.72, rustTint: 0.4 },
    { t: 0.468, size: 1.0, rustTint: 0.75 },
    { t: 0.505, size: 0.68, rustTint: 0.15 },
    { t: 0.542, size: 1.08, rustTint: 0.85 },
    { t: 0.578, size: 0.62, rustTint: 0.1 },
    { t: 0.612, size: 0.8, rustTint: 0.3 },
    { t: 0.635, size: 1.12, rustTint: 0.9 },
    { t: 0.668, size: 0.65, rustTint: 0.2 },
    { t: 0.702, size: 0.88, rustTint: 0.15 },
    { t: 0.742, size: 1.05, rustTint: 0.85 }, // Below second weld seam
    { t: 0.778, size: 0.68, rustTint: 0.2 },
    { t: 0.815, size: 0.85, rustTint: 0.6 },
    { t: 0.848, size: 0.6, rustTint: 0.15 }
  ];

  for (let d of pendantDrops) {
    drawHangingWaterBead(d.t, d.size, d.rustTint);
  }
}

function drawHangingWaterBead(t, sizeMult, rustTint) {
  let attach = railSurfacePoint(t, 89.5);
  let rRail = railRadius(t);
  let scale = (rRail / RAIL_R0) * sizeMult;

  // Dimensions of the pendant droplet
  let dropW = 14.5 * scale; // Half-width of belly
  let dropH = 23.0 * scale; // Total hanging length downward (gravity +Y with slight normal tilt)

  // Center of the spherical belly of the hanging drop
  let bellyX = attach.x + RAIL_NX * (dropW * 0.22);
  let bellyY = attach.y + dropH * 0.54;

  // Build contour points of the pendant droplet (wide meniscus base on rail -> pinched neck -> round gravity belly)
  let leftNeckX = attach.x - RAIL_TX * (dropW * 1.25);
  let leftNeckY = attach.y - RAIL_TY * (dropW * 1.25);
  let rightNeckX = attach.x + RAIL_TX * (dropW * 1.25);
  let rightNeckY = attach.y + RAIL_TY * (dropW * 1.25);

  let contour = [];
  let steps = 24;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps; // 0 = left attachment on rail, 0.5 = bottom tip of drop, 1 = right attachment
    let ang = Math.PI - u * Math.PI; // PI down to 0 through negative/positive
    // Parametric pendant shape
    let theta = Math.PI * (1 - u); // PI (left) -> PI/2 (bottom) -> 0 (right)
    let sinT = Math.sin(theta);
    let cosT = Math.cos(theta);

    // Blend between rail attachment tangent at top (sinT -> 0) and round gravity bulb at bottom (sinT -> 1)
    let flare = Math.pow(sinT, 0.58);
    let neckSpread = (1 - flare) * 1.22 + flare * 1.0;
    let x =
      attach.x -
      RAIL_TX * cosT * dropW * neckSpread * (1 - flare * 0.65) -
      cosT * dropW * flare * 0.82 +
      RAIL_NX * flare * dropW * 0.18;
    let y =
      attach.y -
      RAIL_TY * cosT * dropW * neckSpread * (1 - flare * 0.65) +
      Math.pow(sinT, 0.78) * dropH;

    contour.push({ x, y, u });
  }

  // 1. Opaque base fill of the water droplet (refracting the cold violet-grey sky / dark rail interior)
  brush.noStroke();
  let interiorBaseCol = lerpColor(color("#4a516e"), color("#6b341c"), rustTint * 0.55);
  brush.wash(interiorBaseCol, 225);
  brush.beginShape(0.25);
  for (let pt of contour) brush.vertex(pt.x, pt.y);
  brush.endShape(true);

  // 2. Upper internal refraction (inverted image of dark rail + glowing amber rust bloom above!)
  let upperRefractCol = lerpColor(color("#2e3244"), color("#d94e14"), rustTint * 0.88);
  brush.wash(upperRefractCol, 210);
  brush.beginShape(0.3);
  brush.vertex(leftNeckX, leftNeckY);
  brush.vertex(bellyX - dropW * 0.75, bellyY - dropH * 0.08);
  brush.vertex(bellyX, bellyY + dropH * 0.05);
  brush.vertex(bellyX + dropW * 0.75, bellyY - dropH * 0.08);
  brush.vertex(rightNeckX, rightNeckY);
  brush.endShape(true);

  // If rust-tinted, add a glowing fiery amber-orange core refraction inside the upper dome
  if (rustTint > 0.4) {
    brush.wash("#f78628", 185 * rustTint);
    brush.beginShape(0.35);
    brush.vertex(bellyX - dropW * 0.5, bellyY - dropH * 0.22);
    brush.vertex(bellyX, bellyY - dropH * 0.02);
    brush.vertex(bellyX + dropW * 0.5, bellyY - dropH * 0.22);
    brush.vertex(bellyX, bellyY - dropH * 0.34);
    brush.endShape(true);
  }

  // 3. Lower internal caustic crescent (focusing the luminous fog bow & cold violet-ice light at the bottom belly)
  let causticCol =
    t > 0.58
      ? lerpColor(color("#e8f0ff"), color("#ffd7ba"), 0.45) // Apricot bow refraction on right
      : lerpColor(color("#d8e3fa"), color("#ffb884"), rustTint * 0.35);

  brush.wash(causticCol, 220);
  brush.beginShape(0.35);
  for (let i = 5; i <= 19; i++) {
    let pt = contour[i];
    let inwardX = lerp(pt.x, bellyX, 0.16);
    let inwardY = lerp(pt.y, bellyY, 0.16);
    brush.vertex(inwardX, inwardY);
  }
  for (let i = 18; i >= 6; i--) {
    let pt = contour[i];
    let innerX = lerp(pt.x, bellyX, 0.55);
    let innerY = lerp(pt.y, bellyY - dropH * 0.12, 0.55);
    brush.vertex(innerX, innerY);
  }
  brush.endShape(true);
  brush.noWash();

  // 4. Smooth glass glaze strokes inside the droplet
  brush.set("glass_glaze", "#ffffff", 0.95 * scale);
  let causticArc = [];
  for (let i = 7; i <= 17; i++) {
    let pt = contour[i];
    causticArc.push([lerp(pt.x, bellyX, 0.24), lerp(pt.y, bellyY, 0.24)]);
  }
  brush.spline(causticArc, 0.4);

  // 5. Razor-sharp dark Fresnel outer contour (total internal reflection at water-air boundary)
  let fresnelPts = contour.map((pt) => [pt.x, pt.y]);
  brush.set("razor_detail", "#252938", 1.05 * Math.max(0.45, scale));
  brush.spline(fresnelPts, 0.35);

  // Meniscus shadow line where water grips the underside of the rail
  brush.set("razor_detail", "#1e1b24", 0.95 * Math.max(0.45, scale));
  brush.line(leftNeckX, leftNeckY, rightNeckX, rightNeckY);

  // 6. Brilliant Pinpoint Specular Highlights on the Water Surface!
  // Primary upper-left window-like specular reflection of the bright fog bow
  let specX = bellyX - dropW * 0.42;
  let specY = bellyY - dropH * 0.14;
  brush.set("razor_detail", "#ffffff", 1.35 * Math.max(0.5, scale));
  brush.line(specX, specY - 2.2 * scale, specX - 1.1 * scale, specY + 2.4 * scale);
  brush.circle(specX - 0.3 * scale, specY, 1.4 * scale, 0.1);

  // Secondary pinpoint highlight at the bottom-right rim
  let spec2X = bellyX + dropW * 0.45;
  let spec2Y = bellyY + dropH * 0.24;
  brush.set("razor_detail", "#ffffff", 1.05 * Math.max(0.45, scale));
  brush.line(spec2X - 1.2 * scale, spec2Y + 0.8 * scale, spec2X + 1.0 * scale, spec2Y - 1.0 * scale);
}

// ============================================================================
// 8. FINAL ATMOSPHERIC MIST VEILS OVER RECEDING ZONES
// ============================================================================

function drawFinalFogDissolution() {
  // Soft spray mist and powdery charcoal veils over:
  // 1) The far upper-right end of the railing (x > 840, y < 480) where it recedes into the fog
  // 2) The lower stanchions and bottom deck edge (y > 920)
  // Leaving the near-ground diagonal rail (t = 0.0 to 0.78) completely untouched and KNIFE-SHARP!

  // Upper-right receding rail dissolution
  for (let i = 0; i < 65; i++) {
    let x = random(855, 1200);
    let y = random(280, 490);
    let fade = map(x, 855, 1150, 0, 1);
    if (random() > fade + 0.15) continue;

    let col = random(["#eef1f6", "#f7f9fc", "#ffffff", "#ffe6d4", "#d9dfec"]);
    brush.set(random() < 0.6 ? "mist_veil" : "powder_charcoal", col, random(0.8, 1.9));
    brush.line(x - random(20, 70), y + random(-15, 15), x + random(20, 70), y + random(-15, 15));
  }

  // Lower deck rising sea-mist dissolution (strictly below the foreground rail and droplets!)
  for (let i = 0; i < 95; i++) {
    let x = random(-40, 1240);
    // Keep strictly below the main rail + droplet zone at any x
    let railYAtX = map(x, RAIL_P0.x, RAIL_P1.x, RAIL_P0.y, RAIL_P1.y);
    let minSafeY = Math.max(railYAtX + 115, 860);
    if (minSafeY > 1210) continue;

    let y = random(minSafeY, 1220);
    let distToBow = Math.hypot(x - BOW_CX, y - BOW_CY);
    let col =
      distToBow < BOW_R - 40
        ? random(["#8890b8", "#9ca3c7", "#b4bad6", "#cfd4e6", "#e4e7f2"])
        : random(["#e8ecf4", "#f2f5f9", "#ffffff"]);

    let bName = random() < 0.55 ? "mist_veil" : random() < 0.8 ? "powder_charcoal" : "fine_spray";
    brush.set(bName, col, random(0.9, 2.1));
    brush.line(x - random(35, 95), y + random(-12, 12), x + random(35, 95), y + random(-12, 12));
  }
}
